n18641.content:
\begin{definition}[Boolean hypercube]
\lean{BooleanAnalysis.BoolCube}
\label{BooleanAnalysis.BoolCube}
\leanok
The \emph{Boolean hypercube} of dimension $n$ is $\{0,1\}^n$,
represented as the function type $\mathrm{Fin}\,n \to \mathrm{Bool}$.
\end{definition}

n18642.content:
\begin{definition}[Boolean function]
\lean{BooleanAnalysis.BooleanFunc}
\label{BooleanAnalysis.BooleanFunc}
\leanok
\uses{BooleanAnalysis.BoolCube}
A \emph{Boolean function} of arity $n$ is a function $f : \{0,1\}^n \to \mathbb{R}$.
\end{definition}

n18643.content:
\begin{definition}[Uniform weight]
\lean{BooleanAnalysis.uniformWeight}
\label{BooleanAnalysis.uniformWeight}
\leanok
The uniform probability measure on $\{0,1\}^n$ assigns weight
$2^{-n}$ to each point.
\end{definition}

n18644.content:
\begin{definition}[Expectation]
\lean{BooleanAnalysis.expect}
\label{BooleanAnalysis.expect}
\leanok
\uses{BooleanAnalysis.uniformWeight, BooleanAnalysis.BooleanFunc}
The \emph{expectation} of $f$ under the uniform measure:
\[
  \mathbb{E}[f] \;=\; 2^{-n}\sum_{x\in\{0,1\}^n} f(x).
\]
\end{definition}

n18645.content:
\begin{definition}[$L^2$ inner product]
\lean{BooleanAnalysis.innerProduct}
\label{BooleanAnalysis.innerProduct}
\leanok

\uses{BooleanAnalysis.expect}
The \emph{$L^2$ inner product} of two Boolean functions with respect to the
uniform measure:
\[
  \langle f, g\rangle \;=\; \mathbb{E}[f\cdot g]
  \;=\; 2^{-n}\sum_{x\in\{0,1\}^n} f(x)\,g(x).
\]
\end{definition}

n18647.content:
\begin{lemma}[Inner product is symmetric]
\lean{BooleanAnalysis.innerProduct_comm}
\label{BooleanAnalysis.innerProduct_comm}
\leanok
\uses{BooleanAnalysis.innerProduct}

$\langle f, g\rangle = \langle g, f\rangle$.
\end{lemma}

n18648.content:
\begin{lemma}[Inner product is nonneg on the diagonal]
\lean{BooleanAnalysis.innerProduct_self_nonneg}
\label{BooleanAnalysis.innerProduct_self_nonneg}
\leanok
\uses{BooleanAnalysis.innerProduct}

$\langle f, f\rangle \ge 0$.
\end{lemma}

n18649.content:
\begin{lemma}[Inner product is linear in the first argument]
\lean{BooleanAnalysis.innerProduct_add_left}
\label{BooleanAnalysis.innerProduct_add_left}
\leanok
\uses{BooleanAnalysis.innerProduct}

$\langle f + g, h\rangle = \langle f, h\rangle + \langle g, h\rangle$.
\end{lemma}

n18650.content:
\begin{definition}[Sign encoding]
\lean{BooleanAnalysis.boolToSign}
\label{BooleanAnalysis.boolToSign}
\leanok
The \emph{sign encoding} maps $\mathrm{Bool}$ to $\{-1,1\}\subset\mathbb{R}$:
\[
  \sigma(b) \;=\; \begin{cases} 1 & b = \texttt{false},\\
                                -1 & b = \texttt{true}. \end{cases}
\]
\end{definition}

n18652.content:
\begin{definition}[Walsh character]
\lean{BooleanAnalysis.chiS}
\label{BooleanAnalysis.chiS}
\leanok

\uses{BooleanAnalysis.boolToSign}
The \emph{Walsh--Fourier character} associated to $S\subseteq[n]$ is
\[
  \chi_S(x) \;=\; \prod_{i\in S}(-1)^{x_i}
  \;=\; \prod_{i\in S}\sigma(x_i).
\]
The family $\{\chi_S\}_{S\subseteq[n]}$ forms an orthonormal basis for
$L^2(\{0,1\}^n,\mathrm{uniform})$.
\end{definition}

n18655.content:
\begin{lemma}[Characters take values in $\{-1,1\}$]
\lean{BooleanAnalysis.chiS_sq_eq_one}
\label{BooleanAnalysis.chiS_sq_eq_one}
\leanok
\uses{BooleanAnalysis.chiS, BooleanAnalysis.boolToSign_sq}

$\chi_S(x)^2 = 1$ for all $S$ and $x$.
\end{lemma}

n18656.content:
\begin{lemma}[Characters are multiplicative on disjoint sets]
\lean{BooleanAnalysis.chiS_mul_of_disjoint}
\label{BooleanAnalysis.chiS_mul_of_disjoint}
\leanok

\uses{BooleanAnalysis.chiS}

If $S$ and $T$ are disjoint then $\chi_{S\cup T}(x) = \chi_S(x)\cdot\chi_T(x)$.
\end{lemma}

n18657.content:
\begin{lemma}[Product of two characters]
\lean{BooleanAnalysis.chiS_mul_chiS}
\label{BooleanAnalysis.chiS_mul_chiS}
\leanok

\uses{BooleanAnalysis.chiS}

$\chi_S(x)\cdot\chi_T(x) = \chi_{S\mathbin{\triangle} T}(x)$,
where $\triangle$ denotes symmetric difference.
\end{lemma}

n18658.content:
\begin{lemma}[Character under global bit flip]
\lean{BooleanAnalysis.chiS_neg}
\label{BooleanAnalysis.chiS_neg}
\leanok
\uses{BooleanAnalysis.chiS, BooleanAnalysis.boolToSign_not}

Flipping all bits multiplies the character by $(-1)^{|S|}$:
\[
  \chi_S(\lnot x) \;=\; (-1)^{|S|}\,\chi_S(x).
\]
\end{lemma}

n18659.content:
\begin{lemma}[Count of Walsh characters]
\lean{BooleanAnalysis.card_walsh_characters}
\label{BooleanAnalysis.card_walsh_characters}
\leanok













































\uses{BooleanAnalysis.chiS}

There are exactly $2^n$ Walsh characters, matching the dimension of
$L^2(\{0,1\}^n)$.
\end{lemma}

n18660.content:
\begin{definition}[Fourier coefficient]
\lean{BooleanAnalysis.fourierCoeff}
\label{BooleanAnalysis.fourierCoeff}
\leanok

\uses{BooleanAnalysis.innerProduct, BooleanAnalysis.chiS}
The \emph{Fourier--Walsh coefficient} of $f$ at frequency $S$ is
\[
  \hat f(S) \;=\; \langle f, \chi_S\rangle
  \;=\; 2^{-n}\sum_{x\in\{0,1\}^n} f(x)\,\chi_S(x).
\]
\end{definition}

n18661.content:
\begin{lemma}[Fourier coefficient at $\varnothing$ equals expectation]
\lean{BooleanAnalysis.fourierCoeff_empty}

\label{BooleanAnalysis.fourierCoeff_empty}
\leanok
\uses{BooleanAnalysis.fourierCoeff, BooleanAnalysis.expect}

$\hat f(\varnothing) = \mathbb{E}[f]$.
\end{lemma}

n18662.content:
\begin{theorem}[Walsh expansion]
\lean{BooleanAnalysis.walsh_expansion}
\label{BooleanAnalysis.walsh_expansion}
\leanok



\uses{BooleanAnalysis.fourierCoeff, BooleanAnalysis.chiS}

Every Boolean function $f:\{0,1\}^n\to\mathbb{R}$ has the unique representation
\[
  f(x) \;=\; \sum_{S\subseteq[n]} \hat f(S)\,\chi_S(x).
\]
This is the Fourier inversion formula for the uniform measure on $\{0,1\}^n$.
\end{theorem}

n18663.content:
\begin{theorem}[Orthonormality of Walsh characters]
\lean{BooleanAnalysis.fourier_coeff_chi}

\label{BooleanAnalysis.fourier_coeff_chi}
\leanok












































\uses{BooleanAnalysis.innerProduct, BooleanAnalysis.chiS, BooleanAnalysis.chiS_mul_chiS}

The Walsh characters form an orthonormal system:
\[
  \langle \chi_S, \chi_T\rangle \;=\; [S = T].
\]
\end{theorem}

n18664.content:
\begin{lemma}[Self inner product of a character is 1]
\lean{BooleanAnalysis.innerProduct_chi_self}

\label{BooleanAnalysis.innerProduct_chi_self}
\leanok












































\uses{BooleanAnalysis.fourier_coeff_chi}

$\langle \chi_S, \chi_S\rangle = 1$.
\end{lemma}

n18665.content:
\begin{theorem}[Parseval's identity]
\lean{BooleanAnalysis.parseval}
\label{BooleanAnalysis.parseval}
\leanok



\uses{BooleanAnalysis.innerProduct, BooleanAnalysis.fourierCoeff, BooleanAnalysis.fourier_coeff_chi, BooleanAnalysis.walsh_expansion}

The squared $L^2$ norm of $f$ equals the sum of squared Fourier coefficients:
\[
  \|f\|^2 \;=\; \langle f, f\rangle \;=\; \sum_{S\subseteq[n]} \hat f(S)^2.
\]
\end{theorem}

n18666.content:
\begin{definition}[Bit flip]
\lean{BooleanAnalysis.flipBit}
\label{BooleanAnalysis.flipBit}
\leanok
\uses{BooleanAnalysis.BoolCube}
The point $x^i\in\{0,1\}^n$ obtained from $x$ by flipping the $i$-th coordinate.
\end{definition}

n18667.content:
\begin{definition}[Influence]
\lean{BooleanAnalysis.influence}
\label{BooleanAnalysis.influence}
\leanok

\uses{BooleanAnalysis.expect, BooleanAnalysis.flipBit}
The \emph{influence} of coordinate $i$ on $f$ measures how often flipping
bit $i$ changes the output:
\[
  \mathrm{Inf}_i[f]
  \;=\; \mathbb{E}\!\left[\frac{(f(x)-f(x^i))^2}{4}\right].
\]
For $\pm 1$-valued $f$ this equals $\Pr[f(x)\ne f(x^i)]$.
\end{definition}

n18669.content:
\begin{lemma}[Influence of a Walsh character]
\lean{BooleanAnalysis.influence_chi}
\label{BooleanAnalysis.influence_chi}
\leanok
\uses{BooleanAnalysis.influence, BooleanAnalysis.chiS}

$\mathrm{Inf}_i[\chi_S] = [i\in S]$.
\end{lemma}

n18670.content:
\begin{theorem}[Influence via Fourier coefficients]
\lean{BooleanAnalysis.influence_eq_sum_fourier}

\label{BooleanAnalysis.influence_eq_sum_fourier}
\leanok























































\uses{BooleanAnalysis.influence, BooleanAnalysis.fourierCoeff, BooleanAnalysis.parseval, BooleanAnalysis.walsh_expansion, BooleanAnalysis.fourier_coeff_chi}

\[
  \mathrm{Inf}_i[f] \;=\; \sum_{\substack{S\subseteq[n]\\ i\in S}} \hat f(S)^2.
\]
\end{theorem}

n18671.content:
\begin{theorem}[Total influence via Fourier coefficients]
\lean{BooleanAnalysis.totalInfluence_eq_sum_sq_deg}

\label{BooleanAnalysis.totalInfluence_eq_sum_sq_deg}
\leanok


























































\uses{BooleanAnalysis.totalInfluence, BooleanAnalysis.influence_eq_sum_fourier}

\[
  I[f] \;=\; \sum_{S\subseteq[n]} |S|\,\hat f(S)^2.
\]
\end{theorem}

n18672.content:
\begin{lemma}[Influence is at most 1]
\lean{BooleanAnalysis.influence_le_one}
\label{BooleanAnalysis.influence_le_one}
\leanok
\uses{BooleanAnalysis.influence}

For any $\pm 1$-valued function and any coordinate $i$,
$\mathrm{Inf}_i[f] \le 1$.
\end{lemma}

n18673.content:
\begin{lemma}[Average influence lower bound]
\lean{BooleanAnalysis.max_influence_lower_bound}
\label{BooleanAnalysis.max_influence_lower_bound}
\leanok
\uses{BooleanAnalysis.totalInfluence, BooleanAnalysis.influence}

There exists a coordinate $i$ with $\mathrm{Inf}_i[f] \ge I[f]/n$.
\end{lemma}

n18675.content:
\begin{theorem}[Noise operator in the Fourier domain]
\lean{BooleanAnalysis.noiseOp_fourier}

\label{BooleanAnalysis.noiseOp_fourier}
\leanok

\uses{BooleanAnalysis.noiseOp, BooleanAnalysis.fourierCoeff, BooleanAnalysis.fourier_coeff_chi}

\[
  \widehat{T_\rho f}(S) \;=\; \rho^{|S|}\,\hat f(S).
\]
\end{theorem}

n18676.content:
\begin{theorem}[Stability formula]
\lean{BooleanAnalysis.stability_formula}

\label{BooleanAnalysis.stability_formula}
\leanok

















































\uses{BooleanAnalysis.noiseOp, BooleanAnalysis.innerProduct, BooleanAnalysis.fourierCoeff, BooleanAnalysis.fourier_coeff_chi, BooleanAnalysis.walsh_expansion}

\[
  \langle f, T_\rho f\rangle \;=\; \sum_{S\subseteq[n]} \rho^{|S|}\,\hat f(S)^2.
\]
\end{theorem}

n18677.content:
\begin{definition}[Dictator]
\lean{BooleanAnalysis.dictator}
\label{BooleanAnalysis.dictator}
\leanok

\uses{BooleanAnalysis.boolToSign}
The \emph{dictator function} for coordinate $i$ outputs the sign of the $i$-th
bit: $\mathrm{dict}_i(x) = (-1)^{x_i}$.  Its unique nonzero Fourier coefficient
is $\widehat{\mathrm{dict}_i}(\{i\}) = 1$.
\end{definition}

n18679.content:
\begin{definition}[Parity]
\lean{BooleanAnalysis.parity}
\label{BooleanAnalysis.parity}
\leanok

\uses{BooleanAnalysis.boolToSign}
The \emph{parity function} $f(x) = (-1)^{x_1+\cdots+x_n}$ satisfies
$\hat f([n]) = 1$ and $\hat f(S) = 0$ for $S\ne[n]$.
\end{definition}

n18681.content:
\begin{definition}[Majority]
\lean{BooleanAnalysis.majority}
\label{BooleanAnalysis.majority}
\leanok
\uses{BooleanAnalysis.BooleanFunc}
The \emph{majority function} on $\{0,1\}^{2k+1}$ outputs $1$ if more than half
the inputs are $\texttt{false}$, and $-1$ otherwise.
\end{definition}

n18682.content:
\begin{definition}[Sensitivity at a point]
\lean{BooleanAnalysis.sensitivity}
\label{BooleanAnalysis.sensitivity}
\leanok
\uses{BooleanAnalysis.flipBit}
The \emph{sensitivity} of $f$ at $x$ is the number of coordinates $i$ such
that flipping bit $i$ changes $f(x)$.
\end{definition}

n18683.content:
\begin{definition}[Maximum sensitivity]
\lean{BooleanAnalysis.maxSensitivity}
\label{BooleanAnalysis.maxSensitivity}
\leanok
\uses{BooleanAnalysis.sensitivity}
The maximum sensitivity of $f$ over all inputs.
\end{definition}

n18684.content:
\begin{definition}[Odd function]
\lean{BooleanAnalysis.isOddFunc}
\label{BooleanAnalysis.isOddFunc}
\leanok
\uses{BooleanAnalysis.BooleanFunc}
A Boolean function $f$ is \emph{odd} if $f(\lnot x) = -f(x)$ for all $x$.
This models antisymmetry of pairwise preferences in social choice.
\end{definition}

n18686.content:
\begin{lemma}[Odd functions have zero even-level Fourier coefficients]
\lean{BooleanAnalysis.fourierCoeff_odd_even}
\label{BooleanAnalysis.fourierCoeff_odd_even}
\leanok
\uses{BooleanAnalysis.isOddFunc, BooleanAnalysis.fourierCoeff, BooleanAnalysis.chiS_neg}

If $f$ is odd and $|S|$ is even, then $\hat f(S) = 0$.
\end{lemma}

n18687.content:
\begin{lemma}[Self inner product of a $\pm 1$ function]
\lean{BooleanAnalysis.innerProduct_self_pm_one}
\label{BooleanAnalysis.innerProduct_self_pm_one}
\leanok

\uses{BooleanAnalysis.isPmOne, BooleanAnalysis.innerProduct}

If $f$ is $\pm 1$-valued then $\langle f, f\rangle = 1$.
\end{lemma}

n18688.content:
\begin{lemma}[Parseval for $\pm 1$-valued functions]
\lean{BooleanAnalysis.parseval_pm_one}
\label{BooleanAnalysis.parseval_pm_one}
\leanok


\uses{BooleanAnalysis.isPmOne, BooleanAnalysis.parseval, BooleanAnalysis.innerProduct_self_pm_one}

If $f$ is $\pm 1$-valued then $\sum_{S\subseteq[n]}\hat f(S)^2 = 1$.
\end{lemma}

n18689.content:
\begin{definition}[Fourier weight at level $k$]
\lean{BooleanAnalysis.weightLevel}
\label{BooleanAnalysis.weightLevel}
\leanok

\uses{BooleanAnalysis.fourierCoeff}
The \emph{Fourier weight at level $k$} is
\[
  W_k[f] \;=\; \sum_{\substack{S\subseteq[n]\\ |S|=k}} \hat f(S)^2.
\]
\end{definition}

n18690.content:
\begin{lemma}[Moment equals power of expectation]
\lean{BooleanAnalysis.moment_eq_expect}
\label{BooleanAnalysis.moment_eq_expect}
\leanok

\uses{BooleanAnalysis.BoolCube, BooleanAnalysis.BooleanFunc, BooleanAnalysis.expect, BooleanAnalysis.uniformWeight}

Let $P$ be a probability measure on $\{0,1\}^n$ that assigns the uniform weight
to each singleton.  Then for any Boolean function $f$ and $p\in\mathbb{N}$, the
$p$-th moment of $f$ under $P$ equals the uniform expectation of $f^p$:
\[
  \mathbb{E}_P[f^p] \;=\; \mathbb{E}\!\left[f(x)^p\right].
\]
\end{lemma}

n18691.content:
\begin{lemma}[Sum over subsets as a product]
\lean{BooleanAnalysis.sum_prod_subset_eq_prod_one_add}
\label{BooleanAnalysis.sum_prod_subset_eq_prod_one_add}
\leanok

For any $c : \mathrm{Fin}\,n \to \mathbb{R}$,
\[
  \sum_{S\subseteq[n]} \prod_{i\in S} c_i \;=\; \prod_{i=1}^n (1 + c_i).
\]
\end{lemma}

n18692.content:
\begin{lemma}[Completeness kernel for the Walsh basis]
\lean{BooleanAnalysis.sum_chiS_mul_eq}
\label{BooleanAnalysis.sum_chiS_mul_eq}
\leanok

\uses{BooleanAnalysis.BoolCube, BooleanAnalysis.boolToSign, BooleanAnalysis.boolToSign_mul_self, BooleanAnalysis.chiS, BooleanAnalysis.sum_prod_subset_eq_prod_one_add}

For points $x, y\in\{0,1\}^n$,
\[
  \sum_{S\subseteq[n]} \chi_S(x)\,\chi_S(y) \;=\;
  \begin{cases} 2^n & x = y,\\ 0 & x\ne y. \end{cases}
\]
This is the completeness kernel underlying Fourier inversion.
\end{lemma}

n18693.content:
\begin{definition}[Degree at most $k$]
\lean{BooleanAnalysis.has_degree_at_most}
\label{BooleanAnalysis.has_degree_at_most}
\leanok

\uses{BooleanAnalysis.BooleanFunc}
A Boolean function $f$ \emph{has degree at most $k$} if every nonzero Fourier
coefficient is supported on a set of size at most $k$: for all $S$, if
$\hat f(S)\ne 0$ then $|S|\le k$.
\end{definition}

n18694.content:
\begin{lemma}[Sum of sign encoding over a bit]
\lean{BooleanAnalysis.sum_boolToSign}
\label{BooleanAnalysis.sum_boolToSign}
\leanok
\uses{BooleanAnalysis.boolToSign}

Summing the sign encoding over the two Boolean values gives zero:
$\sum_{b\in\mathrm{Bool}} \sigma(b) = 0$.
\end{lemma}

n18695.content:
\begin{lemma}[Sum of a character over the cube]
\lean{BooleanAnalysis.sum_chiS}
\label{BooleanAnalysis.sum_chiS}
\leanok

\uses{BooleanAnalysis.BoolCube, BooleanAnalysis.boolToSign, BooleanAnalysis.chiS}

Summing the character $\chi_S$ over the whole hypercube yields
\[
  \sum_{x\in\{0,1\}^n} \chi_S(x) \;=\;
  \begin{cases} 2^n & S = \varnothing,\\ 0 & S\ne\varnothing. \end{cases}
\]
\end{lemma}

n18696.content:
\begin{theorem}[Plancherel's identity]
\lean{BooleanAnalysis.plancherel}

\label{BooleanAnalysis.plancherel}
\leanok















































\uses{BooleanAnalysis.BoolCube, BooleanAnalysis.BooleanFunc, BooleanAnalysis.chiS, BooleanAnalysis.expect, BooleanAnalysis.fourierCoeff, BooleanAnalysis.fourier_coeff_chi, BooleanAnalysis.innerProduct, BooleanAnalysis.uniformWeight, BooleanAnalysis.walsh_expansion}

The inner product of two Boolean functions equals the sum of the products of
their Fourier coefficients:
\[
  \langle f, g\rangle \;=\; \sum_{S\subseteq[n]} \hat f(S)\,\hat g(S).
\]
\end{theorem}

n18697.content:
\begin{lemma}[Flipping a bit twice is the identity]
\lean{BooleanAnalysis.flipBit_flipBit}
\label{BooleanAnalysis.flipBit_flipBit}
\leanok
\uses{BooleanAnalysis.BoolCube, BooleanAnalysis.flipBit}

Flipping coordinate $i$ twice returns the original point:
$(x^i)^i = x$.
\end{lemma}

n18698.content:
\begin{lemma}[Flipping bit $i$ leaves other coordinates fixed]
\lean{BooleanAnalysis.flipBit_ne}
\label{BooleanAnalysis.flipBit_ne}
\leanok
\uses{BooleanAnalysis.BoolCube, BooleanAnalysis.flipBit}

If $i\ne j$ then flipping coordinate $i$ does not change coordinate $j$:
$(x^i)_j = x_j$.
\end{lemma}

n18699.content:
\begin{lemma}[Character under a single bit flip]
\lean{BooleanAnalysis.chiS_flipBit}
\label{BooleanAnalysis.chiS_flipBit}
\leanok
\uses{BooleanAnalysis.BoolCube, BooleanAnalysis.boolToSign, BooleanAnalysis.chiS, BooleanAnalysis.flipBit}

Flipping coordinate $i$ negates $\chi_S$ when $i\in S$ and leaves it unchanged
otherwise:
\[
  \chi_S(x^i) \;=\;
  \begin{cases} -\chi_S(x) & i\in S,\\ \chi_S(x) & i\notin S. \end{cases}
\]
\end{lemma}

n18700.content:
\begin{definition}[Discrete derivative]
\lean{BooleanAnalysis.derivative}
\label{BooleanAnalysis.derivative}
\leanok

\uses{BooleanAnalysis.BooleanFunc}
The \emph{discrete derivative} of $f$ in direction $i$ is the Boolean function
\[
  (D_i f)(x) \;=\; \frac{f(x^{i\mapsto 0}) - f(x^{i\mapsto 1})}{2},
\]
where $x^{i\mapsto b}$ sets coordinate $i$ of $x$ to $b$.
\end{definition}

n18701.content:
\begin{lemma}[Derivative is additive]
\lean{BooleanAnalysis.derivative_add}
\label{BooleanAnalysis.derivative_add}
\leanok

\uses{BooleanAnalysis.BooleanFunc, BooleanAnalysis.derivative}

The discrete derivative respects addition:
$D_i(f + g) = D_i f + D_i g$.
\end{lemma}

n18702.content:
\begin{lemma}[Derivative commutes with scalars]
\lean{BooleanAnalysis.derivative_smul}
\label{BooleanAnalysis.derivative_smul}
\leanok

\uses{BooleanAnalysis.BooleanFunc, BooleanAnalysis.derivative}

The discrete derivative commutes with scalar multiplication:
$D_i(c\cdot f) = c\cdot D_i f$ for $c\in\mathbb{R}$.
\end{lemma}

n18703.content:
\begin{definition}[Derivative as a linear map]
\lean{BooleanAnalysis.derivativeLm}
\label{BooleanAnalysis.derivativeLm}
\leanok
\uses{BooleanAnalysis.BooleanFunc, BooleanAnalysis.derivative, BooleanAnalysis.derivative_add, BooleanAnalysis.derivative_smul}
The discrete derivative $D_i$ packaged as an $\mathbb{R}$-linear map on the space of
Boolean functions.
\end{definition}

n18704.content:
\begin{definition}[Expectation operator]
\lean{BooleanAnalysis.expectationOperator}
\label{BooleanAnalysis.expectationOperator}
\leanok

\uses{BooleanAnalysis.BooleanFunc}
The \emph{expectation operator} in direction $i$ averages $f$ over the two
values of coordinate $i$:
\[
  (E_i f)(x) \;=\; \frac{f(x^{i\mapsto 0}) + f(x^{i\mapsto 1})}{2}.
\]
\end{definition}

n18705.content:
\begin{lemma}[Expectation operator is additive]
\lean{BooleanAnalysis.expectation_add}
\label{BooleanAnalysis.expectation_add}
\leanok
\uses{BooleanAnalysis.BooleanFunc, BooleanAnalysis.expectationOperator}

The expectation operator respects addition:
$E_i(f + g) = E_i f + E_i g$.
\end{lemma}

n18706.content:
\begin{lemma}[Expectation operator commutes with scalars]
\lean{BooleanAnalysis.expectation_smul}
\label{BooleanAnalysis.expectation_smul}
\leanok
\uses{BooleanAnalysis.BooleanFunc, BooleanAnalysis.expectationOperator}

The expectation operator commutes with scalar multiplication:
$E_i(c\cdot f) = c\cdot E_i f$ for $c\in\mathbb{R}$.
\end{lemma}

n18707.content:
\begin{definition}[Expectation operator as a linear map]
\lean{BooleanAnalysis.expectationLm}
\label{BooleanAnalysis.expectationLm}
\leanok
\uses{BooleanAnalysis.BooleanFunc, BooleanAnalysis.expectationOperator, BooleanAnalysis.expectation_add, BooleanAnalysis.expectation_smul}
The expectation operator $E_i$ packaged as an $\mathbb{R}$-linear map on the space of
Boolean functions.
\end{definition}

n18708.content:
\begin{lemma}[Noise operator is self-adjoint]
\lean{BooleanAnalysis.noiseOp_self_adjoint}

\label{BooleanAnalysis.noiseOp_self_adjoint}
\leanok
\uses{BooleanAnalysis.BooleanFunc, BooleanAnalysis.fourierCoeff, BooleanAnalysis.innerProduct, BooleanAnalysis.noiseOp, BooleanAnalysis.noiseOp_fourier, BooleanAnalysis.plancherel}

The noise operator $T_\rho$ is self-adjoint with respect to the $L^2$ inner
product:
\[
  \langle T_\rho f, g\rangle \;=\; \langle f, T_\rho g\rangle.
\]
\end{lemma}

n18709.content:
\begin{definition}[Unanimity]
\lean{ArrowTheorem.unanimity}
\label{ArrowTheorem.unanimity}
\leanok
\uses{BooleanAnalysis.BooleanFunc}
A social welfare function $f:\{0,1\}^n\to\mathbb{R}$ is \emph{unanimous} if
$f(\texttt{false},\dots,\texttt{false}) = 1$: when all voters prefer
alternative $a$ over $b$, so does society.
\end{definition}

n18710.content:
\begin{definition}[Dictatorship]
\lean{ArrowTheorem.isDictator}
\label{ArrowTheorem.isDictator}
\leanok
\uses{BooleanAnalysis.dictator}
$f$ is a \emph{dictatorship} if there exists a voter $i$ such that
$f = \mathrm{dict}_i$, i.e.\ society's preference always equals voter $i$'s.
\end{definition}

n18711.content:
\begin{definition}[Pairwise preference functions]
\lean{ArrowTheorem.abPref}
\label{ArrowTheorem.abPref}
\lean{ArrowTheorem.bcPref}
\label{ArrowTheorem.bcPref}
\lean{ArrowTheorem.caPref}
\label{ArrowTheorem.caPref}
