\begin{theorem}[Hamming (sphere-packing) bound]
\lean{ErrorCorrectingCodes.Codeword.hamming_bound}
\label{ErrorCorrectingCodes.Codeword.hamming_bound}
\leanok















\uses{ErrorCorrectingCodes.Codeword.hamming_ball_size, ErrorCorrectingCodes.Codeword.hamming_ball'_disjoint}

Let $q=|\alpha|>1$.  If $C\subseteq\alpha^n$ has minimum distance $d>0$, then
\[
|C|
\;\le\;
\frac{q^n}{\displaystyle\sum_{i=0}^{\lfloor(d-1)/2\rfloor}\binom{n}{i}(q-1)^i}.
\]
\end{theorem}

n18761.content:
\begin{theorem}[Entropy upper bound on Hamming balls]
\lean{ErrorCorrectingCodes.Codeword.hamming_ball_size_asymptotic_upper_bound}
\label{ErrorCorrectingCodes.Codeword.hamming_ball_size_asymptotic_upper_bound}
\leanok

\uses{ErrorCorrectingCodes.Codeword.hamming_ball_size, ErrorCorrectingCodes.Codeword.qaryEntropy}

For $0<p\le 1-1/q$ and $q=|\alpha|$,
\[
|B_{\lfloor np\rfloor}(c)| \;\le\; q^{H_q(p)\,n}.
\]
\end{theorem}

n18763.content:
\begin{lemma}[Same identity, alternate exponentiation]
\lean{ErrorCorrectingCodes.Codeword.q_pow_qary_entropy_simp'}
\label{ErrorCorrectingCodes.Codeword.q_pow_qary_entropy_simp'}
\leanok
\uses{ErrorCorrectingCodes.Codeword.q_pow_qary_entropy_simp}

Variant using a different exponentiation operator.
\end{lemma}

n18765.content:
\begin{lemma}[Asymptotic lower bound on binomial term]
\lean{ErrorCorrectingCodes.Codeword.binomial_coef_asymptotic_lower_bound'}
\label{ErrorCorrectingCodes.Codeword.binomial_coef_asymptotic_lower_bound'}
\leanok

\uses{ErrorCorrectingCodes.Codeword.qaryEntropy}

For $0<p<1$ and $q\ge 2$, eventually
\[
\tbinom{n}{\lfloor np\rfloor}(q-1)^{pn}
\;\ge\;
q^{H_q(p)\,n - \varepsilon(n)},
\quad \varepsilon(n) = o(n).
\]
\end{lemma}

n18768.content:
\begin{lemma}[AM--GM for two nonnegative reals]
\lean{ErrorCorrectingCodes.Codeword.am_gm_sqrt_le_half_sum}
\label{ErrorCorrectingCodes.Codeword.am_gm_sqrt_le_half_sum}
\leanok

For nonnegative reals $a,b\ge 0$, the geometric mean is at most the arithmetic mean:
\[
\sqrt{ab} \;\le\; \frac{a+b}{2}.
\]
\end{lemma}

n18769.content:
\begin{lemma}[A Stirling square-root identity]
\lean{ErrorCorrectingCodes.Codeword.sqrt_two_pi_mul_sqrt_pi_half}
\label{ErrorCorrectingCodes.Codeword.sqrt_two_pi_mul_sqrt_pi_half}
\leanok

For $n\ge 0$,
\[
\sqrt{2\pi n}\,\cdot\,\sqrt{\pi/2}\,\cdot\,\sqrt{n} \;=\; \pi n.
\]
\end{lemma}

n18770.content:
\begin{lemma}[Positivity of $\lfloor np\rfloor$ for large $n$]
\lean{ErrorCorrectingCodes.Codeword.floor_np_pos}
\label{ErrorCorrectingCodes.Codeword.floor_np_pos}
\leanok

Let $0<p$ and $0<1-p$, and set $N_2 = \lceil 2/(p(1-p))\rceil + 1$. If $N_2 \le n$, then $\lfloor np\rfloor > 0$.
\end{lemma}

n18771.content:
\begin{lemma}[Stirling-based ratio bound for the binomial term]
\lean{ErrorCorrectingCodes.Codeword.stirling_comb_bound}

\label{ErrorCorrectingCodes.Codeword.stirling_comb_bound}
\leanok









\uses{ErrorCorrectingCodes.Codeword.am_gm_sqrt_le_half_sum, ErrorCorrectingCodes.Codeword.sqrt_two_pi_mul_sqrt_pi_half}

Let $a,b,n\in\mathbb{N}$ with $a,b>0$, $a+b=n$, and let $c>0$. Suppose the Stirling-type bound
\[
a!\,\cdot\,b! \;\le\; c\cdot\Big(\sqrt{2}\sqrt{a}\sqrt{\pi}\,(a/e)^a\cdot\sqrt{2}\sqrt{b}\sqrt{\pi}\,(b/e)^b\Big)
\]
holds. Then
\[
\frac{n^n}{a^a\,b^b}\,\Big/\,\big(c\,\sqrt{\pi/2}\,\sqrt{n}\big)
\;\le\;
\frac{n!}{a!\,b!}.
\]
\end{lemma}

n18772.content:
\begin{theorem}[Distance equals minimum nonzero weight]
\lean{ErrorCorrectingCodes.Codeword.Linear_Code_dist_eq_min_weight}
\label{ErrorCorrectingCodes.Codeword.Linear_Code_dist_eq_min_weight}
\leanok

\uses{ErrorCorrectingCodes.Codeword.Linear_Code', ErrorCorrectingCodes.Codeword.weight, ErrorCorrectingCodes.Codeword.distance}

If $C$ is linear (witnessed by some generator matrix) and has minimum distance $d$, then:
\begin{itemize}
  \item every nonzero codeword in $C$ has weight at least $d$;
  \item some codeword in $C$ has weight exactly $d$.
\end{itemize}
\end{theorem}

n18773.content:
\begin{definition}[Uniform distribution on vectors]
\lean{ErrorCorrectingCodes.Codeword.uniform_vector_dist}
\label{ErrorCorrectingCodes.Codeword.uniform_vector_dist}
\leanok

The uniform probability mass function on $\alpha^n$, encoded as a function
$\alpha^n\to\mathbb{R}$ assigning $1/|\alpha|^n$ to each vector.
\end{definition}

n18774.content:
\begin{lemma}[Finiteness of constrained matrix set]
\lean{ErrorCorrectingCodes.Codeword.finite_matrix_dist}
\label{ErrorCorrectingCodes.Codeword.finite_matrix_dist}
\leanok

For fixed $x\in\alpha^k$ and $v\in\alpha^n$, the set $\{G : Gx=v\}$ is finite.
\end{lemma}

n18775.content:
\begin{definition}[Distribution induced by random matrices]
\lean{ErrorCorrectingCodes.Codeword.matrix_dist}
\label{ErrorCorrectingCodes.Codeword.matrix_dist}
\leanok
$\mu_x(v)$ is the fraction of $n\times k$ matrices $G$ satisfying $Gx=v$.
\end{definition}

n18776.content:
\begin{definition}[Row extraction]
\lean{ErrorCorrectingCodes.Codeword.get_matrix_row}
\label{ErrorCorrectingCodes.Codeword.get_matrix_row}
\leanok
Utility returning the $i$-th row of a matrix as a $1\times k$ matrix.
\end{definition}

n18777.content:
\begin{theorem}[Uniformity of $Gx$ for nonzero $x$]
\lean{ErrorCorrectingCodes.Codeword.uniformity_lemma}
\label{ErrorCorrectingCodes.Codeword.uniformity_lemma}
\leanok












\uses{ErrorCorrectingCodes.Codeword.matrix_dist, ErrorCorrectingCodes.Codeword.uniform_vector_dist, ErrorCorrectingCodes.Codeword.finite_matrix_dist}

If $x\neq 0$ and $k\ge 1$, then for a uniformly random $n\times k$ matrix $G$ over $\alpha$,
the product $Gx$ is uniformly distributed over $\alpha^n$:
\[
\Pr[Gx = v] = \frac{1}{|\alpha|^n}
\quad\text{for all }v\in\alpha^n.
\]
\end{theorem}

n18778.content:
\begin{theorem}[Probability of low-weight codeword]
\lean{ErrorCorrectingCodes.Codeword.prob_leq_ball_size}
\label{ErrorCorrectingCodes.Codeword.prob_leq_ball_size}
\leanok














\uses{ErrorCorrectingCodes.Codeword.uniformity_lemma, ErrorCorrectingCodes.Codeword.weight, ErrorCorrectingCodes.Codeword.hamming_ball}

For any nonzero $x\in\alpha^k$,
\[
\frac{|\{G : \mathrm{wt}(Gx) < d\}|}{|\alpha|^{nk}}
\;\le\;
\frac{|B_{d-1}(\mathbf{0})|}{|\alpha|^n}.
\]
\end{theorem}

n18779.content:
\begin{theorem}[Existence bound via union bound]
\lean{ErrorCorrectingCodes.Codeword.existence_bound}
\label{ErrorCorrectingCodes.Codeword.existence_bound}
\leanok















\uses{ErrorCorrectingCodes.Codeword.prob_leq_ball_size}

The number of $n\times k$ matrices that send some nonzero message to a codeword of
weight $<d$ is at most
\[
(|\alpha|^k-1)\cdot|\alpha|^{nk-n}\cdot|B_{d-1}(\mathbf{0})|.
\]
\end{theorem}

n18780.content:
\begin{theorem}[Gilbert--Varshamov bound]
\lean{ErrorCorrectingCodes.Codeword.gv_bound}
\label{ErrorCorrectingCodes.Codeword.gv_bound}
\leanok
















\uses{ErrorCorrectingCodes.Codeword.existence_bound}

If $k \le n - \lceil\log_q|B_{d-1}(\mathbf{0})|\rceil - 1$, then there exists a
generator matrix $G$ such that every nonzero message is mapped to a codeword of
Hamming weight at least $d$.
\end{theorem}

n18781.content:
\begin{definition}[List-decodable code]
\lean{ErrorCorrectingCodes.Codeword.list_decodable}
\label{ErrorCorrectingCodes.Codeword.list_decodable}
\leanok
A code $C$ is $(\rho,L)$-list-decodable if every Hamming ball of radius
$\lfloor\rho n\rfloor$ contains at most $L$ codewords of $C$.
\end{definition}

n18782.content:
\begin{lemma}[Existence of list-decodable codes]
\lean{ErrorCorrectingCodes.Codeword.exists_listDecodable_code}
\label{ErrorCorrectingCodes.Codeword.exists_listDecodable_code}
\leanok
\uses{ErrorCorrectingCodes.Codeword.list_decodable, ErrorCorrectingCodes.Codeword.hamming_ball}

If the ball volume $V$ and code size $M$ satisfy the counting inequality
\[
|\alpha|^n\cdot\tbinom{V}{L+1}\cdot\tbinom{|\alpha|^n-(L+1)}{M-(L+1)}
\;<\;
\tbinom{|\alpha|^n}{M},
\]
then there exists a code $C$ of size $M$ that is $(p,L)$-list-decodable.
\end{lemma}

n18784.content:
\begin{lemma}[Counting inequality for list decoding]
\lean{ErrorCorrectingCodes.Codeword.listDecoding_counting_ineq}
\label{ErrorCorrectingCodes.Codeword.listDecoding_counting_ineq}
\leanok
\uses{ErrorCorrectingCodes.Codeword.binom_ratio_bound, ErrorCorrectingCodes.Codeword.qaryEntropy}

For the choice $r = 1-H_q(\rho)-1/L$, $M=\lfloor q^{rn}\rfloor$, and
$V=\lfloor q^{H_q(\rho)n}\rfloor$, whenever $L<M\le q^n$,
\[
q^n\cdot\tbinom{V}{L+1}\cdot\tbinom{q^n-(L+1)}{M-(L+1)}
\;<\;
\tbinom{q^n}{M}.
\]
\end{lemma}

n18785.content:
\begin{theorem}[List-decoding capacity]
\lean{ErrorCorrectingCodes.Codeword.list_decoding_capacity}
\label{ErrorCorrectingCodes.Codeword.list_decoding_capacity}
\leanok
\uses{ErrorCorrectingCodes.Codeword.exists_listDecodable_code, ErrorCorrectingCodes.Codeword.listDecoding_counting_ineq, ErrorCorrectingCodes.Codeword.qary_entropy_pos, ErrorCorrectingCodes.Codeword.hamming_ball_size_asymptotic_upper_bound}

For any $q=|\alpha|$, $0<\rho\le 1-1/q$, and $L\ge 1$, there exist codes of rate
$r = 1-H_q(\rho)-1/L$ that are $(\rho,L)$-list-decodable.
\end{theorem}

n18786.content:
\begin{definition}[Maximum admissible code size]
\lean{A0}
\label{A0}
\leanok
\uses{CodingTheory.Johnson.AdmissibleCode}
$A_0(n,d,w)$ is the maximum size of an $(n,d,w)$-admissible code.
\end{definition}

n18787.content:
\begin{theorem}[Johnson bound, radius form]
\lean{binary_johnson_bound_radius}
\label{binary_johnson_bound_radius}
\leanok
\uses{A0, CodingTheory.Johnson.binary_johnson_card_bound_of_admissible}

If $n > 0$, $1 \le d$, $2d \le n$, and $w \le J_2(n,d)$, then
\[
A_0(n,d,w) \;\le\; 2n.
\]
\end{theorem}

n18788.content:
\begin{definition}[Binary vector type]
\lean{CodingTheory.Johnson.BitVec}
\label{CodingTheory.Johnson.BitVec}
\leanok
The type of binary words of length $n$, namely functions $\mathrm{Fin}\,n \to \mathrm{Bool}$.
\end{definition}

n18789.content:
\begin{definition}[Euclidean coordinate space]
\lean{CodingTheory.Johnson.Euc}
\label{CodingTheory.Johnson.Euc}
\leanok
Abbreviation for the $n$-dimensional real Euclidean space $\mathbb{R}^n$ with the
$\ell^2$ inner product, i.e.\ \texttt{EuclideanSpace} $\mathbb{R}$ $(\mathrm{Fin}\,n)$.
\end{definition}

n18790.content:
\begin{definition}[Hamming weight]
\lean{CodingTheory.Johnson.wt}
\label{CodingTheory.Johnson.wt}
\leanok

\uses{CodingTheory.Johnson.BitVec}
For a binary word $x$ of length $n$, its weight is the number of coordinates where
$x$ takes the value \texttt{true}:
$\mathrm{wt}(x) = \left\lvert \{\, i : x_i = \texttt{true} \,\}\right\rvert$.
\end{definition}

n18791.content:
\begin{definition}[Hamming distance]
\lean{CodingTheory.Johnson.hdist}
\label{CodingTheory.Johnson.hdist}
\leanok

\uses{CodingTheory.Johnson.BitVec}
For binary words $x,y$ of length $n$, the Hamming distance is the number of
coordinates on which they differ:
$\mathrm{hdist}(x,y) = \left\lvert \{\, i : x_i \neq y_i \,\}\right\rvert$.
\end{definition}

n18792.content:
\begin{definition}[$\pm 1$ embedding]
\lean{CodingTheory.Johnson.pmOne}
\label{CodingTheory.Johnson.pmOne}
\leanok
\uses{CodingTheory.Johnson.BitVec, CodingTheory.Johnson.Euc}
The map sending a binary word $x$ to the real vector in $\mathbb{R}^n$ whose $i$-th
coordinate is $-1$ if $x_i = \texttt{true}$ and $+1$ otherwise.
\end{definition}

n18793.content:
\begin{definition}[All-ones vector]
\lean{CodingTheory.Johnson.ones}
\label{CodingTheory.Johnson.ones}
\leanok
\uses{CodingTheory.Johnson.Euc}
The vector in $\mathbb{R}^n$ all of whose coordinates equal $1$.
\end{definition}

n18794.content:
\begin{definition}[Shifted $\pm 1$ vector]
\lean{CodingTheory.Johnson.shifted}
\label{CodingTheory.Johnson.shifted}
\leanok
\uses{CodingTheory.Johnson.BitVec, CodingTheory.Johnson.Euc, CodingTheory.Johnson.ones, CodingTheory.Johnson.pmOne}
For a real parameter $\alpha$ and a binary word $x$, the vector
$\hat{x}^\alpha = \mathrm{pmOne}(x) - \alpha \cdot \mathbf{1} \in \mathbb{R}^n$.
\end{definition}

n18795.content:
\begin{definition}[Normalization]
\lean{CodingTheory.Johnson.normalize}
\label{CodingTheory.Johnson.normalize}
\leanok
\uses{CodingTheory.Johnson.Euc}
The rescaling $u \mapsto \lVert u\rVert^{-1} \cdot u$ of a vector of $\mathbb{R}^n$.
\end{definition}

n18796.content:
\begin{lemma}[Coordinates of the all-ones vector]
\lean{CodingTheory.Johnson.ones_apply}
\label{CodingTheory.Johnson.ones_apply}
\leanok
\uses{CodingTheory.Johnson.ones}

Every coordinate of $\mathbf{1} \in \mathbb{R}^n$ equals $1$: for each $i$,
$\mathbf{1}_i = 1$.
\end{lemma}

n18797.content:
\begin{lemma}[$\pm 1$ embedding at a false coordinate]
\lean{CodingTheory.Johnson.pmOne_apply_false}
\label{CodingTheory.Johnson.pmOne_apply_false}
\leanok
\uses{CodingTheory.Johnson.BitVec, CodingTheory.Johnson.pmOne}

If $x_i = \texttt{false}$ then $\mathrm{pmOne}(x)_i = 1$.
\end{lemma}

n18798.content:
\begin{lemma}[$\pm 1$ embedding at a true coordinate]
\lean{CodingTheory.Johnson.pmOne_apply_true}
\label{CodingTheory.Johnson.pmOne_apply_true}
\leanok
\uses{CodingTheory.Johnson.BitVec, CodingTheory.Johnson.pmOne}

If $x_i = \texttt{true}$ then $\mathrm{pmOne}(x)_i = -1$.
\end{lemma}

n18799.content:
\begin{definition}[Binary Johnson radius]
\lean{CodingTheory.Johnson.J2}
\label{CodingTheory.Johnson.J2}
\leanok
The real quantity
\[
J_2(n,d) \;=\; \frac{n - \sqrt{n\,(n - 2d)}}{2}.
\]
\end{definition}

n18801.content:
\begin{definition}[Admissible code]
\lean{CodingTheory.Johnson.AdmissibleCode}
\label{CodingTheory.Johnson.AdmissibleCode}
\leanok
\uses{CodingTheory.Johnson.BitVec, CodingTheory.Johnson.hdist, CodingTheory.Johnson.wt}
A finite set $C$ of binary words of length $n$ is $(n,d,w)$-admissible when any two
distinct elements of $C$ are at Hamming distance at least $d$ and every element of
$C$ has weight at most $w$.
\end{definition}

n18802.content:
\begin{lemma}[Coordinatewise product of $\pm 1$ embeddings]
\lean{CodingTheory.Johnson.coord_mul_pmOne}
\label{CodingTheory.Johnson.coord_mul_pmOne}
\leanok
\uses{CodingTheory.Johnson.BitVec, CodingTheory.Johnson.pmOne}

For all binary words $x,y$ and every coordinate $i$,
$\mathrm{pmOne}(x)_i \cdot \mathrm{pmOne}(y)_i$ equals $1$ if $x_i = y_i$ and $-1$ otherwise.
\end{lemma}

n18803.content:
\begin{lemma}[Inner product of two $\pm 1$ embeddings]
\lean{CodingTheory.Johnson.inner_pmOne_pmOne}
\label{CodingTheory.Johnson.inner_pmOne_pmOne}
\leanok
\uses{CodingTheory.Johnson.BitVec, CodingTheory.Johnson.coord_mul_pmOne, CodingTheory.Johnson.hdist, CodingTheory.Johnson.pmOne}

For all binary words $x,y$ of length $n$,
\[
\langle \mathrm{pmOne}(x), \mathrm{pmOne}(y)\rangle \;=\; n - 2\,\mathrm{hdist}(x,y).
\]
\end{lemma}

n18804.content:
\begin{lemma}[Inner product with the all-ones vector]
\lean{CodingTheory.Johnson.inner_pmOne_ones}
\label{CodingTheory.Johnson.inner_pmOne_ones}
\leanok
\uses{CodingTheory.Johnson.BitVec, CodingTheory.Johnson.ones, CodingTheory.Johnson.pmOne, CodingTheory.Johnson.wt}

For every binary word $x$ of length $n$,
\[
\langle \mathrm{pmOne}(x), \mathbf{1}\rangle \;=\; n - 2\,\mathrm{wt}(x).
\]
\end{lemma}

n18805.content:
\begin{lemma}[Squared norm of the all-ones vector]
\lean{CodingTheory.Johnson.inner_ones_ones}
\label{CodingTheory.Johnson.inner_ones_ones}
\leanok
\uses{CodingTheory.Johnson.ones}

$\langle \mathbf{1}, \mathbf{1}\rangle = n$ in $\mathbb{R}^n$.
\end{lemma}

n18807.content:
\begin{lemma}[Upper bound on the shifted inner product]
\lean{CodingTheory.Johnson.inner_shifted_le_expr}
\label{CodingTheory.Johnson.inner_shifted_le_expr}
\leanok
\uses{CodingTheory.Johnson.BitVec, CodingTheory.Johnson.hdist, CodingTheory.Johnson.inner_ones_ones, CodingTheory.Johnson.inner_pmOne_ones, CodingTheory.Johnson.inner_pmOne_pmOne, CodingTheory.Johnson.inner_shifted_expand, CodingTheory.Johnson.shifted, CodingTheory.Johnson.wt}

If $\alpha \ge 0$, $\mathrm{hdist}(x,y) \ge d$, and $\mathrm{wt}(x), \mathrm{wt}(y) \le w$, then
\[
\langle \hat{x}^\alpha, \hat{y}^\alpha \rangle
\;\le\; (n - 2d) + \alpha^2 n + 2\alpha\,(2w - n).
\]
\end{lemma}

n18810.content:
\begin{lemma}[$\alpha$ is less than one]
\lean{CodingTheory.Johnson.alpha_lt_one_of_hd1}
\label{CodingTheory.Johnson.alpha_lt_one_of_hd1}
\leanok
\uses{CodingTheory.Johnson.alpha}

If $n > 0$, $d \ge 1$, and $2d \le n$, then $\alpha(n,d) < 1$.
\end{lemma}

n18811.content:
\begin{lemma}[Johnson arithmetic inequality]
\lean{CodingTheory.Johnson.johnson_arith}
\label{CodingTheory.Johnson.johnson_arith}
\leanok
\uses{CodingTheory.Johnson.J2, CodingTheory.Johnson.alpha}

If $n > 0$, $2d \le n$, and $w \le J_2(n,d)$, then for $\alpha = \alpha(n,d)$
\[
(n - 2d) + \alpha^2 n + 2\alpha\,(2w - n) \;\le\; 0.
\]
\end{lemma}

n18812.content:
\begin{lemma}[Projections keep non-positive inner products]
\lean{CodingTheory.Johnson.inner_proj_le_zero}
\label{CodingTheory.Johnson.inner_proj_le_zero}
\leanok

Let $V$ be a real inner product space, $u \in V$ a unit vector, and $x,y \in V$ with
$\langle x,u\rangle \le 0$, $\langle y,u\rangle \le 0$ and $\langle x,y\rangle \le 0$.
Then the components of $x$ and $y$ orthogonal to $u$ satisfy
$\langle x - \langle x,u\rangle u,\ y - \langle y,u\rangle u\rangle \le 0$.
\end{lemma}

n18813.content:
\begin{lemma}[Squared norm of an orthogonal component]
\lean{CodingTheory.Johnson.proj_norm_sq}
\label{CodingTheory.Johnson.proj_norm_sq}
\leanok

For a unit vector $u$ and any $x$ in a real inner product space,
$\lVert x - \langle x,u\rangle u\rVert^2 = \lVert x\rVert^2 - \langle x,u\rangle^2$.
\end{lemma}

n18814.content:
\begin{lemma}[Nonvanishing of the orthogonal component]
\lean{CodingTheory.Johnson.proj_nonzero}
\label{CodingTheory.Johnson.proj_nonzero}
\leanok

If $u$ and $x$ are unit vectors with $\langle x,u\rangle \le 0$ and $x \neq u$,
$x \neq -u$, then $x - \langle x,u\rangle u \neq 0$.
\end{lemma}

n18815.content:
\begin{lemma}[Injectivity of the projection on a set of unit vectors]
\lean{CodingTheory.Johnson.proj_inj_on}
\label{CodingTheory.Johnson.proj_inj_on}
\leanok

Let $u$ be a unit vector and $S$ a set of unit vectors each having non-positive
inner product with $u$. Then $x \mapsto x - \langle x,u\rangle u$ is injective on $S$.
\end{lemma}

n18816.content:
\begin{definition}[Orthogonal projection off a unit vector]
\lean{CodingTheory.Johnson.orthProj}
\label{CodingTheory.Johnson.orthProj}
\leanok
For $u,v$ in a real inner product space, $\mathrm{orthProj}(u,v) = v - \langle u,v\rangle u$,
the projection of $v$ onto the orthogonal complement of $\mathrm{span}\{u\}$.
\end{definition}

n18817.content:
\begin{lemma}[The projection lies in the orthogonal complement]
\lean{CodingTheory.Johnson.orthProj_mem_orthogonal}
\label{CodingTheory.Johnson.orthProj_mem_orthogonal}
\leanok
\uses{CodingTheory.Johnson.orthProj}

If $\lVert u\rVert = 1$ then $\mathrm{orthProj}(u,v) \in (\mathrm{span}_{\mathbb{R}}\{u\})^{\perp}$
for every $v$.
\end{lemma}

n18818.content:
\begin{lemma}[The projection of a unit vector is nonzero]
\lean{CodingTheory.Johnson.orthProj_ne_zero}
\label{CodingTheory.Johnson.orthProj_ne_zero}
\leanok
\uses{CodingTheory.Johnson.orthProj}

If $u$ and $v$ are unit vectors with $v \neq u$ and $v \neq -u$, then
$\mathrm{orthProj}(u,v) \neq 0$.
\end{lemma}

n18819.content:
\begin{lemma}[Projections preserve non-positive inner products]
\lean{CodingTheory.Johnson.orthProj_inner_nonpos}
\label{CodingTheory.Johnson.orthProj_inner_nonpos}
\leanok
\uses{CodingTheory.Johnson.orthProj}

Let $\lVert u\rVert = 1$ and let $v,w$ satisfy $\langle v,w\rangle \le 0$,
$\langle v,u\rangle \le 0$ and $\langle w,u\rangle \le 0$. Then
$\langle \mathrm{orthProj}(u,v), \mathrm{orthProj}(u,w)\rangle \le 0$.
\end{lemma}

n18820.content:
\begin{lemma}[Normalized projections of distinct vectors differ]
\lean{CodingTheory.Johnson.normalized_orthProj_injective}
\label{CodingTheory.Johnson.normalized_orthProj_injective}
\leanok
\uses{CodingTheory.Johnson.orthProj, CodingTheory.Johnson.orthProj_ne_zero}

Let $u,v,w$ be unit vectors with $\langle v,u\rangle \le 0$, $\langle w,u\rangle \le 0$,
$\langle v,w\rangle \le 0$, with $v,w \notin \{u,-u\}$ and $v \neq w$. Then the
normalized projections $\lVert \mathrm{orthProj}(u,v)\rVert^{-1}\mathrm{orthProj}(u,v)$ and
$\lVert \mathrm{orthProj}(u,w)\rVert^{-1}\mathrm{orthProj}(u,w)$ cannot be equal
(the statement derives a contradiction from their equality).
\end{lemma}

n18821.content:
\begin{lemma}[Normalized projection is a unit vector]
\lean{CodingTheory.Johnson.norm_normalized_orthProj}
\label{CodingTheory.Johnson.norm_normalized_orthProj}
\leanok
\uses{CodingTheory.Johnson.orthProj, CodingTheory.Johnson.orthProj_ne_zero}

If $u,v$ are unit vectors with $v \neq u$ and $v \neq -u$, then
$\lVert \ \lVert \mathrm{orthProj}(u,v)\rVert^{-1}\,\mathrm{orthProj}(u,v)\ \rVert = 1$.
\end{lemma}

n18822.content:
\begin{lemma}[Non-positive inner product of normalized projections]
\lean{CodingTheory.Johnson.normalized_orthProj_inner_nonpos}
\label{CodingTheory.Johnson.normalized_orthProj_inner_nonpos}
\leanok
\uses{CodingTheory.Johnson.orthProj, CodingTheory.Johnson.orthProj_inner_nonpos}

Under $\lVert u\rVert = 1$, $\langle v,w\rangle \le 0$, $\langle v,u\rangle \le 0$ and
$\langle w,u\rangle \le 0$ (with both projections nonzero), the normalized projections
of $v$ and $w$ also have non-positive inner product.
\end{lemma}

n18823.content:
\begin{lemma}[Rank of the orthogonal complement of a line]
\lean{CodingTheory.Johnson.finrank_orthogonal_span_singleton}
\label{CodingTheory.Johnson.finrank_orthogonal_span_singleton}
\leanok

For a unit vector $u$ in a finite-dimensional real inner product space $V$,
$\dim_{\mathbb{R}} (\mathrm{span}_{\mathbb{R}}\{u\})^{\perp} = \dim_{\mathbb{R}} V - 1$.
\end{lemma}

n18824.content:
\begin{lemma}[Discarding $u$ and $-u$ costs at most two elements]
\lean{CodingTheory.Johnson.card_filter_add_two}
\label{CodingTheory.Johnson.card_filter_add_two}
\leanok

For a finite subset $S$ of an additive group and $u \in S$,
$\left\lvert S\right\rvert \le \left\lvert \{\, v \in S : v \neq u \text{ and } v \neq -u \,\}\right\rvert + 2$.
\end{lemma}

n18825.content:
\begin{definition}[Normalized projection as an element of the complement]
\lean{CodingTheory.Johnson.mkProj}
\label{CodingTheory.Johnson.mkProj}
\leanok
\uses{CodingTheory.Johnson.orthProj, CodingTheory.Johnson.orthProj_mem_orthogonal}
Given a unit vector $u$, this packages the normalized projection
$\lVert \mathrm{orthProj}(u,v)\rVert^{-1}\mathrm{orthProj}(u,v)$ together with its membership
proof as an element of the subspace $(\mathrm{span}_{\mathbb{R}}\{u\})^{\perp}$.
\end{definition}

n18826.content:
\begin{lemma}[Underlying vector of \texttt{mkProj}]
\lean{CodingTheory.Johnson.mkProj_val}
\label{CodingTheory.Johnson.mkProj_val}
\leanok
\uses{CodingTheory.Johnson.mkProj, CodingTheory.Johnson.orthProj}

The value in $V$ underlying $\mathrm{mkProj}(u,v)$ is
$\lVert \mathrm{orthProj}(u,v)\rVert^{-1}\,\mathrm{orthProj}(u,v)$.
\end{lemma}

n18827.content:
\begin{theorem}[Rankin bound in a finite-dimensional space]
\lean{CodingTheory.Johnson.rankin_bound_general}

\label{CodingTheory.Johnson.rankin_bound_general}
\leanok









































\uses{CodingTheory.Johnson.card_filter_add_two, CodingTheory.Johnson.finrank_orthogonal_span_singleton, CodingTheory.Johnson.mkProj, CodingTheory.Johnson.mkProj_val, CodingTheory.Johnson.norm_normalized_orthProj, CodingTheory.Johnson.normalized_orthProj_injective, CodingTheory.Johnson.normalized_orthProj_inner_nonpos, CodingTheory.Johnson.orthProj, CodingTheory.Johnson.orthProj_ne_zero}

Let $V$ be a finite-dimensional real inner product space and $S \subseteq V$ a finite
set of unit vectors whose pairwise inner products are non-positive. Then
$\left\lvert S\right\rvert \le 2 \dim_{\mathbb{R}} V$.
\end{theorem}

n18828.content:
\begin{theorem}[Rankin bound in $\mathbb{R}^n$]
\lean{CodingTheory.Johnson.rankin_finset_bound}

\label{CodingTheory.Johnson.rankin_finset_bound}
\leanok









































\uses{CodingTheory.Johnson.Euc, CodingTheory.Johnson.rankin_bound_general}

A finite set $S$ of unit vectors in $\mathbb{R}^n$ with pairwise non-positive inner
products satisfies $\left\lvert S\right\rvert \le 2n$.
\end{theorem}

n18829.content:
\begin{lemma}[Shifted vectors are nonzero for $\alpha < 1$]
\lean{CodingTheory.Johnson.shifted_ne_zero_of_alpha_lt_one}
\label{CodingTheory.Johnson.shifted_ne_zero_of_alpha_lt_one}
\leanok
\uses{CodingTheory.Johnson.BitVec, CodingTheory.Johnson.Euc, CodingTheory.Johnson.ones, CodingTheory.Johnson.pmOne, CodingTheory.Johnson.shifted}

If $n > 0$ and $0 \le \alpha < 1$, then $\hat{x}^\alpha \neq 0$ for every binary word
$x$ of length $n$.
\end{lemma}

n18830.content:
\begin{theorem}[Johnson cardinality bound, parametric form]
\lean{CodingTheory.Johnson.binary_johnson_card_bound_parametric}
\label{CodingTheory.Johnson.binary_johnson_card_bound_parametric}
\leanok
\uses{CodingTheory.Johnson.BitVec, CodingTheory.Johnson.Euc, CodingTheory.Johnson.hdist, CodingTheory.Johnson.inner_shifted_le_expr, CodingTheory.Johnson.normalize, CodingTheory.Johnson.rankin_finset_bound, CodingTheory.Johnson.shifted, CodingTheory.Johnson.wt}

Let $n > 0$ and let $C$ be a finite set of binary words of length $n$ with pairwise
Hamming distance at least $d$ and all weights at most $w$. If $\alpha \ge 0$ is such
that $\hat{x}^\alpha \neq 0$ for all $x \in C$ and
$(n - 2d) + \alpha^2 n + 2\alpha(2w - n) \le 0$, then $\left\lvert C\right\rvert \le 2n$.
\end{theorem}

n18831.content:
\begin{theorem}[Binary Johnson cardinality bound]
\lean{CodingTheory.Johnson.binary_johnson_card_bound}
\label{CodingTheory.Johnson.binary_johnson_card_bound}
\leanok
\uses{CodingTheory.Johnson.BitVec, CodingTheory.Johnson.J2, CodingTheory.Johnson.alpha, CodingTheory.Johnson.alpha_lt_one_of_hd1, CodingTheory.Johnson.alpha_nonneg, CodingTheory.Johnson.binary_johnson_card_bound_parametric, CodingTheory.Johnson.hdist, CodingTheory.Johnson.johnson_arith, CodingTheory.Johnson.shifted, CodingTheory.Johnson.shifted_ne_zero_of_alpha_lt_one, CodingTheory.Johnson.wt}

Assume $n > 0$, $1 \le d$ and $2d \le n$. If $C$ is a finite set of binary words of
length $n$ whose distinct elements are at Hamming distance at least $d$, whose weights
are all at most $w$, and if $w \le J_2(n,d)$, then $\left\lvert C\right\rvert \le 2n$.
\end{theorem}

n18832.content:
\begin{theorem}[Johnson bound for admissible codes]
\lean{CodingTheory.Johnson.binary_johnson_card_bound_of_admissible}
\label{CodingTheory.Johnson.binary_johnson_card_bound_of_admissible}
\leanok
\uses{CodingTheory.Johnson.AdmissibleCode, CodingTheory.Johnson.BitVec, CodingTheory.Johnson.J2, CodingTheory.Johnson.binary_johnson_card_bound}

Assume $n > 0$, $1 \le d$ and $2d \le n$. Every $(n,d,w)$-admissible code $C$ with
$w \le J_2(n,d)$ satisfies $\left\lvert C\right\rvert \le 2n$.
\end{theorem}

n18833.content:
\begin{lemma}[Uniform bound transfers to $A_0$]
\lean{A0_le_of_forall_le}
\label{A0_le_of_forall_le}
\leanok
\uses{A0, CodingTheory.Johnson.AdmissibleCode, CodingTheory.Johnson.BitVec}

If every $(n,d,w)$-admissible code $C$ has $\left\lvert C\right\rvert \le K$, then $A_0(n,d,w) \le K$.
\end{lemma}

n18841.content:
\begin{definition}[Pauli basis]
\lean{PauliBasis}

\label{PauliBasis}
\leanok

The four Pauli basis elements $\{I,X,Y,Z\}$, represented as an inductive type.
\end{definition}

n18842.content:
\begin{definition}[Pauli string]
\lean{PauliString}

\label{PauliString}
\leanok

A \emph{Pauli string} of length $n$ is a function $p : \mathrm{Fin}\,n \to \mathrm{PauliBasis}$.
\end{definition}

n18843.content:
\begin{definition}[Support and weight]
\lean{support}
\label{support}



\lean{weight}
\label{weight}
\leanok

The \emph{support} $\mathrm{supp}(p) \subseteq \mathrm{Fin}\,n$ consists of coordinates
where $p(i) \neq I$; the \emph{weight} is $\mathrm{wt}(p) = |\mathrm{supp}(p)|$.
\end{definition}

n18844.content:
\begin{definition}[Pauli error set]
\lean{PauliErrorsLe}
\label{PauliErrorsLe}
\leanok



\uses{PauliString, weight}
The set of all Pauli strings of weight at most $t$:
\[
\mathcal{E}(n,t) = \bigl\{p : \mathrm{PauliString}\,n \;\big|\; \mathrm{wt}(p) \le t\bigr\}.
\]
\end{definition}

n18845.content:
\begin{theorem}[Cardinality of the Pauli error set]
\lean{card_pauliErrorsLe}
\label{card_pauliErrorsLe}
\leanok



\uses{PauliErrorsLe, weight}

\[
|\mathcal{E}(n,t)| \;=\; \sum_{i=0}^{t}\binom{n}{i}\,3^i.
\]
\end{theorem}

n18847.content:
\begin{definition}[$n$-qubit Hilbert space]
\lean{Hn}
\label{Hn}
\leanok


The $n$-qubit Hilbert space
$\mathcal{H}_n = \ell^2\!\bigl(\{0,1\}^n,\mathbb{C}\bigr)$,
implemented as \texttt{EuclideanSpace ℂ (Fin n → Fin 2)}.
\end{definition}

n18849.content:
\begin{definition}[Pauli operator]
\lean{pauliOp}

\label{pauliOp}
\leanok

\uses{PauliString, Hn}
For $p \in \mathrm{PauliString}\,n$, the associated Pauli operator
$\hat{p} : \mathcal{H}_n \to \mathcal{H}_n$.
\end{definition}

n18850.content:
\begin{definition}[Knill--Laflamme condition]
\lean{KnillLaflamme}
\label{KnillLaflamme}
\leanok





\uses{pauliOp}
A subspace $C \le \mathcal{H}_n$ satisfies the \emph{Knill--Laflamme condition}
for $t$-error correction if for all Pauli strings $E,F$ with $\mathrm{wt}(E),\mathrm{wt}(F) \le t$
there exists $\lambda_{EF}\in\mathbb{C}$ such that
$P_C\,E^\dagger F\,P_C = \lambda_{EF}\,P_C$,
where $P_C$ is the orthogonal projection onto $C$.
\end{definition}

n18851.content:
\begin{definition}[Non-degenerate code]
\lean{IsNondegenerate}
\label{IsNondegenerate}
\leanok





\uses{KnillLaflamme}
A code is \emph{non-degenerate} if it satisfies the Knill--Laflamme condition
and additionally $P_C E^\dagger F P_C = 0$ whenever $E \neq F$.
\end{definition}

n18852.content:
\begin{definition}[Error sphere]
\lean{ErrorSphere}
\label{ErrorSphere}
\leanok



\uses{pauliOp}
The \emph{error sphere} $\mathrm{ES}(C,t)$ is the subspace
$\bigvee_{\mathrm{wt}(p)\le t} \hat{p}(C)$, i.e.\ the supremum of the
Pauli images of $C$ over all $t$-errors.
\end{definition}

n18853.content:
\begin{lemma}[Error subspaces are pairwise orthogonal]
\lean{error_subspaces_orthogonal}
\label{error_subspaces_orthogonal}
\leanok





\uses{IsNondegenerate, pauliOp}

If $C$ is non-degenerate and $E \neq F$ both have weight $\le t$, then
$\hat{E}(C) \perp \hat{F}(C)$.
\end{lemma}

n18854.content:
\begin{lemma}[Dimension of the error sphere]
\lean{error_sphere_dimension}
\label{error_sphere_dimension}
\leanok




\uses{ErrorSphere, error_subspaces_orthogonal, card_pauliErrorsLe}

If $C$ is non-degenerate,
\[
\dim(\mathrm{ES}(C,t)) \;=\; |\mathcal{E}(n,t)|\cdot\dim(C).
\]
\end{lemma}

n18855.content:
\begin{theorem}[Quantum Hamming bound]
\lean{quantum_hamming_bound}
\label{quantum_hamming_bound}
\leanok







\uses{error_sphere_dimension, finrank_Hn}

If $C \le \mathcal{H}_n$ is non-degenerate, then
\[
\left(\sum_{i=0}^{t}\binom{n}{i}\,3^i\right)\cdot\dim_{\mathbb{C}}(C)
\;\le\; 2^n.
\]
\end{theorem}

n18856.content:
\begin{definition}[Pauli $I$ matrix]
\lean{sigmaI}
\label{sigmaI}
\leanok

The $2\times 2$ identity matrix over $\mathbb{C}$, i.e.\ the Pauli operator $I$.
\end{definition}

n18857.content:
\begin{definition}[Pauli $X$ matrix]
\lean{sigmaX}

\label{sigmaX}
\leanok

The bit-flip Pauli matrix
$X = \begin{pmatrix} 0 & 1 \\ 1 & 0 \end{pmatrix}$
over $\mathbb{C}$.
\end{definition}

n18858.content:
\begin{definition}[Pauli $Y$ matrix]
\lean{sigmaY}

\label{sigmaY}
\leanok

The bit-phase-flip Pauli matrix
$Y = \begin{pmatrix} 0 & -i \\ i & 0 \end{pmatrix}$
over $\mathbb{C}$.
\end{definition}

n18859.content:
\begin{definition}[Pauli $Z$ matrix]
\lean{sigmaZ}

\label{sigmaZ}
\leanok

The phase-flip Pauli matrix
$Z = \begin{pmatrix} 1 & 0 \\ 0 & -1 \end{pmatrix}$
over $\mathbb{C}$.
\end{definition}

n18860.content:
\begin{definition}[Matrix of a Pauli basis element]
\lean{PauliBasis.toMatrix}

\label{PauliBasis.toMatrix}
\leanok

\uses{sigmaI, sigmaX, sigmaY, sigmaZ}
Maps each Pauli basis element $\{I,X,Y,Z\}$ to its corresponding $2\times 2$ matrix
$\{\sigma_I,\sigma_X,\sigma_Y,\sigma_Z\}$.
\end{definition}

n18861.content:
\begin{definition}[Matrix of a Pauli string]
\lean{pauliMatrix}

\label{pauliMatrix}
\leanok

\uses{PauliBasis.toMatrix, PauliString}
For a Pauli string $p$ on $n$ qubits, the $2^n\times 2^n$ matrix obtained as the
tensor product of the single-qubit Pauli matrices $\sigma_{p(i)}$ over all coordinates~$i$.
\end{definition}

n18862.content:
\begin{definition}[Embedding of a non-identity Pauli]
\lean{PauliNZ.toBasis}
\label{PauliNZ.toBasis}
\leanok
Embeds a non-identity Pauli ($X$, $Y$, or $Z$) from the three-element type
$\mathrm{PauliNZ}$ into the full Pauli basis $\{I,X,Y,Z\}$.
\end{definition}

n18863.content:
\begin{definition}[Pauli string with prescribed support]
\lean{mkWithSupport}
\label{mkWithSupport}
\leanok
\uses{PauliNZ.toBasis, PauliString}
Given a finset $S \subseteq \mathrm{Fin}\,n$ and an assignment $f : S \to \mathrm{PauliNZ}$,
constructs the Pauli string that equals $f(i).\mathrm{toBasis}$ on each $i \in S$ and equals $I$
elsewhere.
\end{definition}

n18864.content:
\begin{lemma}[Support of \texttt{mkWithSupport}]
\lean{support_mkWithSupport}
\label{support_mkWithSupport}
\leanok
\uses{mkWithSupport, support}

The Pauli string $\mathrm{mkWithSupport}\,S\,f$ has support exactly $S$.
\end{lemma}

n18865.content:
\begin{definition}[Pauli strings with exact support]
\lean{pauliStringsExactSupport}
\label{pauliStringsExactSupport}
\leanok
\uses{PauliString, support}
The finset of all Pauli strings on $n$ qubits whose support equals exactly the given
finset $S$.
\end{definition}

n18866.content:
\begin{lemma}[Count of Pauli strings with exact support]
\lean{card_pauliStringsExactSupport}
\label{card_pauliStringsExactSupport}
\leanok

\uses{PauliNZ.toBasis, mkWithSupport, pauliStringsExactSupport, support, support_mkWithSupport}

The number of Pauli strings with support exactly $S$ is $3^{|S|}$, since each coordinate in $S$
is assigned one of the three non-identity Paulis.
\end{lemma}

n18867.content:
\begin{definition}[Quantum code]
\lean{Code}
\label{Code}
\leanok




\uses{Hn}
An $n$-qubit quantum code is a subspace of the $n$-qubit Hilbert space $\mathcal{H}_n$.
\end{definition}

n18868.content:
\begin{definition}[Adjoint of a Pauli operator]
\lean{pauliOpAdjoint}
\label{pauliOpAdjoint}
\leanok
\uses{Hn, PauliString, pauliMatrix}
The adjoint (Hermitian conjugate) $\hat{p}^\dagger : \mathcal{H}_n \to \mathcal{H}_n$ of the
Pauli operator associated with a Pauli string $p$.
\end{definition}

n18869.content:
\begin{definition}[Projection onto a code]
\lean{codeProj}
\label{codeProj}
\leanok
\uses{Hn}
The orthogonal projection of $\mathcal{H}_n$ onto a subspace $C$, viewed as an endomorphism
$P_C : \mathcal{H}_n \to \mathcal{H}_n$.
\end{definition}

n18870.content:
\begin{lemma}[Action of the code projection]
\lean{codeProj_apply}
\label{codeProj_apply}
\leanok
\uses{Hn, codeProj}

For any $x \in \mathcal{H}_n$, the value $P_C\,x$ coincides with the orthogonal projection
$\Pi_C(x)$ of $x$ onto $C$.
\end{lemma}

n18871.content:
\begin{lemma}[Image of the code projection lies in $C$]
\lean{codeProj_mem}
\label{codeProj_mem}
\leanok
\uses{Hn, codeProj, codeProj_apply}

For any $x \in \mathcal{H}_n$, the projected vector $P_C\,x$ belongs to the code subspace $C$.
\end{lemma}

n18872.content:
\begin{lemma}[Projection fixes code vectors]
\lean{codeProj_eq_self_of_mem}
\label{codeProj_eq_self_of_mem}
\leanok
\uses{Hn, codeProj}

If $x \in C$, then $P_C\,x = x$.
\end{lemma}

n18873.content:
\begin{lemma}[Idempotence of the code projection]
\lean{codeProj_idempotent}
\label{codeProj_idempotent}
\leanok
\uses{Hn, codeProj, codeProj_eq_self_of_mem, codeProj_mem}

The code projection is idempotent: $P_C(P_C\,x) = P_C\,x$ for all $x \in \mathcal{H}_n$.
\end{lemma}

n18874.content:
\begin{theorem}[Quantum Hamming bound, raw form]
\lean{quantum_hamming_bound_raw}
\label{quantum_hamming_bound_raw}
\leanok







\uses{ErrorSphere, Hn, IsNondegenerate, card_pauliErrorsLe, error_sphere_dimension, finrank_Hn}

For a non-degenerate $[[n,k]]$ quantum code $C \le \mathcal{H}_n$ correcting $t$ errors, with
$\dim_{\mathbb{C}}(C) = 2^k$, the dimension of the error sphere does not exceed the ambient
dimension:
\[
\left(\sum_{j=0}^{t}\binom{n}{j}\,3^j\right)\cdot 2^k \;\le\; 2^n.
\]
\end{theorem}

n18875.content:
\begin{lemma}[Embedded non-identity Paulis are not $I$]
\lean{PauliNZ.toBasis_ne_I}
\label{PauliNZ.toBasis_ne_I}
\leanok
\uses{PauliNZ.toBasis}

For every $a \in \mathrm{PauliNZ}$, its image $a.\mathrm{toBasis}$ in the Pauli basis
differs from $I$; that is, the embedding of $\{X,Y,Z\}$ never hits the identity element.
\end{lemma}

n18876.content:
\begin{definition}[Symplectic form]
\lean{sym_form}
\label{sym_form}
\leanok





For $u = (x,z), v = (x',z') \in V = \mathbb{F}_p^n \times \mathbb{F}_p^n$,
\[
\omega(u,v) \;=\; \sum_{i=0}^{n-1}(x_i z'_i - z_i x'_i).
\]
\end{definition}

n18877.content:
\begin{lemma}[Bilinearity]
\lean{sym_form_add_left}
\label{sym_form_add_left}

\lean{sym_form_add_right}
