n18946.content:
\begin{definition}[Merge of two gate arrays]
\lean{LMN.mergeGates}
\label{LMN.mergeGates}
\leanok
Given gate arrays $g_1 : \mathrm{Fin}\,m_1 \to \alpha$ and
$g_2 : \mathrm{Fin}\,m_2 \to \alpha$, the merged array
$\mathrm{mergeGates}\,g_1\,g_2 : \mathrm{Fin}\,(m_1+m_2) \to \alpha$ takes its values
from $g_1$ on indices $0,\dots,m_1-1$ and from $g_2$ on indices
$m_1,\dots,m_1+m_2-1$.
\end{definition}

n18947.content:
\begin{lemma}[Left projection of merge]
\lean{LMN.mergeGates_castAdd}
\label{LMN.mergeGates_castAdd}
\leanok
\uses{LMN.mergeGates}

For every $i : \mathrm{Fin}\,m_1$, evaluating the merged array at the left-embedded index
$\mathrm{castAdd}\,m_2\,i$ recovers $g_1\,i$, i.e.
$\mathrm{mergeGates}\,g_1\,g_2\,(\mathrm{castAdd}\,m_2\,i) = g_1\,i$.
\end{lemma}

n18948.content:
\begin{lemma}[Right projection of merge]
\lean{LMN.mergeGates_natAdd}
\label{LMN.mergeGates_natAdd}
\leanok
\uses{LMN.mergeGates}

For every $i : \mathrm{Fin}\,m_2$, evaluating the merged array at the right-embedded index
$\mathrm{natAdd}\,m_1\,i$ recovers $g_2\,i$, i.e.
$\mathrm{mergeGates}\,g_1\,g_2\,(\mathrm{natAdd}\,m_1\,i) = g_2\,i$.
\end{lemma}

n18949.content:
\begin{lemma}[Reindex into left half evaluates the original]
\lean{LMN.reidx_eval_mergeGates_left}
\label{LMN.reidx_eval_mergeGates_left}
\leanok
\uses{BoolCircuit.Circuit, BoolCircuit.Circuit.eval, BoolCircuit.Circuit.reidx, BoolCircuit.Circuit.reidx_eval, LMN.mergeGates}

For a circuit $c$ on $m_1$ gates and Boolean gate values $g_1, g_2$, reindexing $c$ along
the left embedding $\mathrm{castAdd}\,m_2$ and evaluating against the merged array yields
the original evaluation: $(\mathrm{reidx}\,c\,(\mathrm{castAdd}\,m_2)).\mathrm{eval}\,(\mathrm{mergeGates}\,g_1\,g_2) = c.\mathrm{eval}\,g_1$.
\end{lemma}

n18950.content:
\begin{lemma}[Reindex into right half evaluates the original]
\lean{LMN.reidx_eval_mergeGates_right}
\label{LMN.reidx_eval_mergeGates_right}
\leanok
\uses{BoolCircuit.Circuit, BoolCircuit.Circuit.eval, BoolCircuit.Circuit.reidx, BoolCircuit.Circuit.reidx_eval, LMN.mergeGates}

For a circuit $c$ on $m_2$ gates and Boolean gate values $g_1, g_2$, reindexing $c$ along
the right embedding $\mathrm{natAdd}\,m_1$ and evaluating against the merged array yields
the original evaluation: $(\mathrm{reidx}\,c\,(\mathrm{natAdd}\,m_1)).\mathrm{eval}\,(\mathrm{mergeGates}\,g_1\,g_2) = c.\mathrm{eval}\,g_2$.
\end{lemma}

n18951.content:
