\begin{lemma}[Restriction respects pointwise equality]
\lean{LMN.restrictFn_ext'}
\label{LMN.restrictFn_ext'}
\leanok
\uses{SwitchingLemma2.Restriction, SwitchingLemma2.restrictFn}

If $f,g:(\mathrm{Fin}\,n\to\{0,1\})\to\{0,1\}$ agree pointwise, i.e.\ $f(x)=g(x)$ for all $x$,
then for every restriction $\rho$ the restricted functions coincide:
$\mathrm{restrictFn}\,f\,\rho = \mathrm{restrictFn}\,g\,\rho$.
\end{lemma}

