n19089.content:
\begin{theorem}[General switching lemma for CNFs]
\lean{LMN.switching_bernoulli_dtDepth_cnf_general}


\label{LMN.switching_bernoulli_dtDepth_cnf_general}
\leanok
\uses{CNF, CNF.eval, CNF.width, LMN.cleanCNF, LMN.cleanCNF_eval, LMN.cleanCNF_nodup, LMN.cleanCNF_var_inj, LMN.cleanCNF_width_le, SwitchingBernoulli.switching_bernoulli_dtDepth_cnf, SwitchingLemma2.bernoulliRestrProb, SwitchingLemma2.restrictFn, dtDepth}

Let $f$ be a CNF of width at most $w$ with $0<w$ and $0<n$, and let $p\in\mathbb{R}$ satisfy
$0<p$, $p\le \tfrac{1}{40w}$ and $p\le 1$. Then for every $t\in\mathbb{N}$,
\[
\mathrm{bernoulliRestrProb}\,p\,\bigl(\rho \mapsto \mathrm{dtDepth}(\mathrm{restrictFn}\,(\mathrm{CNF.eval}\,f)\,\rho) > t\bigr)
\;\le\; \bigl(\tfrac12\bigr)^{t} + \exp\!\bigl(-np/3\bigr),
\]
again without any non-duplication hypothesis on $f$.
\end{theorem}

