n19119.content:
\begin{definition}[Re-indexing a circuit]
\lean{BoolCircuit.Circuit.reidx}
\label{BoolCircuit.Circuit.reidx}
\leanok
\uses{BoolCircuit.Circuit}
Given a circuit $c$ on $m$ variables and a function $f : \mathrm{Fin}\,m \to \mathrm{Fin}\,m'$,
the re-indexed circuit $\mathrm{reidx}(c, f)$ on $m'$ variables is obtained by replacing
each literal index $i$ by $f(i)$ (keeping its sign) and recursing structurally through the
$\mathrm{And}/\mathrm{Or}$ nodes.
\end{definition}

n19120.content:
\begin{theorem}[Re-indexing preserves depth]
\lean{BoolCircuit.Circuit.reidx_depth}
\label{BoolCircuit.Circuit.reidx_depth}
\leanok
\uses{BoolCircuit.Circuit, BoolCircuit.Circuit.depth, BoolCircuit.Circuit.ind, BoolCircuit.Circuit.reidx}

For every circuit $c$ on $m$ variables and every $f : \mathrm{Fin}\,m \to \mathrm{Fin}\,m'$,
the re-indexed circuit has the same depth as $c$, i.e. $\mathrm{depth}(\mathrm{reidx}(c, f)) = \mathrm{depth}(c)$.
\end{theorem}

n19121.content:
\begin{theorem}[Re-indexing commutes with evaluation]
\lean{BoolCircuit.Circuit.reidx_eval}
\label{BoolCircuit.Circuit.reidx_eval}
\leanok
\uses{BoolCircuit.Circuit, BoolCircuit.Circuit.eval, BoolCircuit.Circuit.ind, BoolCircuit.Circuit.reidx, BoolCircuit.Lit.eval}

For every circuit $c$ on $m$ variables, every $f : \mathrm{Fin}\,m \to \mathrm{Fin}\,m'$,
and every assignment $g : \mathrm{Fin}\,m' \to \mathrm{Bool}$, evaluating the re-indexed
circuit under $g$ equals evaluating $c$ under the pulled-back assignment $g \circ f$, i.e.
$\mathrm{eval}(\mathrm{reidx}(c, f), g) = \mathrm{eval}(c, g \circ f)$.
\end{theorem}

n19122.content:
\begin{definition}[DNF to dual CNF]
\lean{LMN.dnfToDualCNF}
\label{LMN.dnfToDualCNF}
\leanok
\uses{CNF, DNF, Literal.flipNeg}
The De~Morgan dual of a DNF $\varphi$ on $n$ variables, obtained by negating every
literal of every term and reading the result as a CNF. Concretely
$\neg\big(\bigvee_i \bigwedge_j \ell_{ij}\big) = \bigwedge_i \bigvee_j \neg\ell_{ij}$.
\end{definition}

n19123.content:
\begin{lemma}[Dual CNF preserves width]
\lean{LMN.dnfToDualCNF_width}
\label{LMN.dnfToDualCNF_width}
\leanok
\uses{CNF.width, DNF, DNF.width, LMN.dnfToDualCNF, Term.width}

The dual CNF $\mathrm{dnfToDualCNF}\,\varphi$ has the same width as $\varphi$, since
flipping the sign of each literal leaves the number of literals per term (and hence
per clause) unchanged.
\end{lemma}

n19124.content:
\begin{lemma}[Dual CNF negates the evaluation]
\lean{LMN.dnfToDualCNF_eval}
\label{LMN.dnfToDualCNF_eval}
\leanok
\uses{CNF.eval, CNF.evalClause, DNF, DNF.eval, LMN.dnfToDualCNF, Literal.flipNeg_eval, Term.eval}

For every input $x : \mathrm{Fin}\,n \to \mathrm{Bool}$, the dual CNF evaluates to the
negation of the original DNF: $\mathrm{CNF.eval}\,(\mathrm{dnfToDualCNF}\,\varphi)\,x
= \neg(\mathrm{DNF.eval}\,\varphi\,x)$.
\end{lemma}

