n19222.content:
\begin{definition}[Composition of two restrictions]
\lean{LMN.composeRestr}

\label{LMN.composeRestr}
\leanok
\uses{SwitchingLemma2.Restriction}
Given two restrictions $\rho_1, \rho_2$ on $n$ variables, their composition is the
restriction that on each coordinate $i$ uses the value fixed by $\rho_1$ if there is
one, and otherwise the value given by $\rho_2$. This models applying $\rho_1$ first
and then $\rho_2$ on the variables left free by $\rho_1$.
\end{definition}

n19223.content:
\begin{definition}[Per-variable Bernoulli weight]
\lean{LMN.varWeight}

\label{LMN.varWeight}
\leanok
For a parameter $p \in \mathbb{R}$, the per-variable weight assigns $p$ to a free
coordinate (value \texttt{none}) and $(1-p)/2$ to a fixed coordinate (value
\texttt{some\_}), matching the marginal of the Bernoulli restriction model.
\end{definition}

n19224.content:
\begin{lemma}[Pointwise characterization of composition]
\lean{LMN.composeRestr_eq_iff}
\label{LMN.composeRestr_eq_iff}
\leanok
\uses{LMN.composeRestr, SwitchingLemma2.Restriction}

The composition $\mathrm{composeRestr}\,\rho_1\,\rho_2$ equals $\sigma$ if and only if
for every coordinate $i$ the value $(\rho_1\,i)$, falling back to $(\rho_2\,i)$,
equals $\sigma\,i$.
\end{lemma}

n19225.content:
\begin{lemma}[Right identity for composition]
\lean{LMN.composeRestr_id_right}
\label{LMN.composeRestr_id_right}
\leanok
\uses{LMN.composeRestr, SwitchingLemma2.Restriction}

Composing a restriction $\rho$ with the all-free restriction (which fixes no
variable) returns $\rho$ unchanged.
\end{lemma}

n19226.content:
\begin{lemma}[Bernoulli weight factors as a product]
\lean{LMN.bernoulliRestrWeight_eq_prod}
\label{LMN.bernoulliRestrWeight_eq_prod}
\leanok
\uses{LMN.varWeight, SwitchingLemma2.Restriction, SwitchingLemma2.Restriction.freeVars, SwitchingLemma2.bernoulliRestrWeight}

The Bernoulli restriction weight of $\rho$ at parameter $p$ equals the product over
all coordinates $i$ of the per-variable weights:
\[
  \mathrm{bernoulliRestrWeight}\,p\,\rho = \prod_{i : \mathrm{Fin}\,n} \mathrm{varWeight}\,p\,(\rho\,i).
\]
\end{lemma}

n19227.content:
\begin{lemma}[Per-variable composition identity]
\lean{LMN.varWeight_compose_sum}
\label{LMN.varWeight_compose_sum}
\leanok
\uses{LMN.varWeight}

For parameters $p, q \in \mathbb{R}$ and any outcome $c$, summing the products
$\mathrm{varWeight}\,p\,a \cdot \mathrm{varWeight}\,q\,b$ over all pairs $(a,b)$ whose
composition equals $c$ gives $\mathrm{varWeight}\,(pq)\,c$:
\[
  \sum_{a} \sum_{b} \mathrm{varWeight}\,p\,a \cdot \mathrm{varWeight}\,q\,b \cdot
    [\,a \,\triangleright\, b = c\,] = \mathrm{varWeight}\,(pq)\,c.
\]
\end{lemma}

n19230.content:
\begin{theorem}[Composition inequality]
\lean{LMN.restriction_compose_le}

\label{LMN.restriction_compose_le}
\leanok
\uses{LMN.composeRestr, LMN.restriction_compose_eq, SwitchingLemma2.Restriction, SwitchingLemma2.bernoulliRestrProb, SwitchingLemma2.bernoulliRestrProb_le_one', SwitchingLemma2.bernoulliRestrWeight_nonneg'}

For $0 < p \le 1$ and $0 < q \le 1$, the Bernoulli($pq$) probability of an event is
at most the Bernoulli($p$) probability that some $\rho_2$ makes the event hold after
composition:
\[
  \mathrm{bernoulliRestrProb}\,(pq)\,\mathrm{event}
  \le \mathrm{bernoulliRestrProb}\,p\,\bigl(\rho_1 \mapsto \exists \rho_2,\;
      \mathrm{event}(\mathrm{composeRestr}\,\rho_1\,\rho_2)\bigr).
\]
\end{theorem}

n19231.content:
\begin{definition}[Restriction of a decision tree]
\lean{LMN.dtRestrict}
\label{LMN.dtRestrict}
\leanok
\uses{DecisionTree, SwitchingLemma2.Restriction}
Given a decision tree $T$ and a partial assignment $\rho$, the restricted tree
$\mathrm{dtRestrict}\,T\,\rho$ is obtained by collapsing every branch whose query variable
is fixed by $\rho$ into the corresponding subtree, and keeping unrestricted branches intact.
\end{definition}

n19232.content:
\begin{theorem}[Restriction does not increase depth]
\lean{LMN.dtRestrict_depth_le}
\label{LMN.dtRestrict_depth_le}
\leanok
\uses{DecisionTree, DecisionTree.depth, LMN.dtRestrict, SwitchingLemma2.Restriction}

For every decision tree $T$ and restriction $\rho$, the depth of the restricted tree
satisfies $\mathrm{depth}(\mathrm{dtRestrict}\,T\,\rho) \le \mathrm{depth}(T)$.
\end{theorem}

n19233.content:
\begin{theorem}[Evaluation of a restricted tree]
\lean{LMN.dtRestrict_eval}
\label{LMN.dtRestrict_eval}
\leanok
\uses{DecisionTree, DecisionTree.eval, LMN.dtRestrict, SwitchingLemma2.Restriction, SwitchingLemma2.Restriction.extend}

For every decision tree $T$, restriction $\rho$, and input $x$, the restricted tree
evaluates as $(\mathrm{dtRestrict}\,T\,\rho).\mathrm{eval}(x) = T.\mathrm{eval}(\mathrm{extend}\,\rho\,x)$,
where $\mathrm{extend}\,\rho\,x$ fills in the unset coordinates of $\rho$ using $x$.
\end{theorem}

n19234.content:
\begin{theorem}[Decision-tree depth is monotone under restriction]
\lean{LMN.dtDepth_restrictFn_le'}
\label{LMN.dtDepth_restrictFn_le'}
\leanok
\uses{DecisionTree, DecisionTree.depth, DecisionTree.eval, LMN.dtRestrict, LMN.dtRestrict_depth_le, LMN.dtRestrict_eval, SwitchingLemma2.Restriction, SwitchingLemma2.restrictFn, buildFullDTree, buildFullDTree_depth, buildFullDTree_eval, dtDepth}

For every Boolean function $f$ and restriction $\rho$, the decision-tree depth of the
restricted function satisfies $\mathrm{dtDepth}(f|_\rho) \le \mathrm{dtDepth}(f)$.
\end{theorem}

n19235.content:
\begin{theorem}[Composing restrictions further decreases depth]
\lean{LMN.dtDepth_composeRestr_le}
\label{LMN.dtDepth_composeRestr_le}
\leanok
\uses{LMN.composeRestr, LMN.dtDepth_restrictFn_le', SwitchingLemma2.Restriction, SwitchingLemma2.Restriction.extend, SwitchingLemma2.restrictFn, dtDepth}

For every Boolean function $f$ and restrictions $\rho_1, \rho_2$, restricting by the
composed restriction can only decrease decision-tree depth:
$\mathrm{dtDepth}(f|_{\rho_1 \circ \rho_2}) \le \mathrm{dtDepth}(f|_{\rho_1})$.
