\uses{CNF, Term.width}
The width of a CNF formula $c$, defined as the maximum width over its clauses (and $0$
for the empty formula).
\end{definition}

n19396.content:
\begin{definition}[Evaluation of a decision tree]
\lean{DecisionTree.eval}

\label{DecisionTree.eval}
\leanok
\uses{DecisionTree}
Evaluates a decision tree on an input $x$: a leaf returns its stored bit, and a branch
on variable $i$ follows the high subtree when $x_i$ is \texttt{true} and the low subtree
otherwise.
\end{definition}

n19397.content:
\begin{definition}[Depth of a decision tree]
\lean{DecisionTree.depth}

\label{DecisionTree.depth}
\leanok
\uses{DecisionTree}
The depth of a decision tree (maximum path length to a leaf): a leaf has depth $0$ and a
branch has depth $1$ plus the maximum of its two subtrees' depths.
\end{definition}

n19398.content:
\begin{definition}[Deepest path of a decision tree]
\lean{DecisionTree.deepPath}
\label{DecisionTree.deepPath}
\leanok
\uses{DecisionTree, DecisionTree.depth}
Extracts a deepest root-to-leaf path from a decision tree, at each branch descending into
the deeper subtree (ties broken toward the high subtree). It returns the list of
$(\text{queried variable}, \text{branch direction})$ pairs along that path.
\end{definition}

n19399.content:
\begin{lemma}[Deep path length equals depth]
\lean{DecisionTree.length_deepPath}
\label{DecisionTree.length_deepPath}
\leanok
\uses{DecisionTree, DecisionTree.deepPath, DecisionTree.depth}

For every decision tree $T$, the length of its deepest path equals its depth:
$T.\mathrm{deepPath}.\mathrm{length} = T.\mathrm{depth}$.
\end{lemma}

n19400.content:
\begin{lemma}[Depth bound for the full decision tree]
\lean{buildFullDTree_depth}
\label{buildFullDTree_depth}
\leanok
\uses{DecisionTree.depth, buildFullDTree}

For a function $f$, an index $k \le n$, and an accumulator assignment $acc$, the complete
decision tree $\mathrm{buildFullDTree}\,f\,k\,acc$ that queries variables
$k, k+1, \dots, n-1$ in order has depth at most $n - k$.
\end{lemma}

n19401.content:
\begin{lemma}[Correctness of the full decision tree]
\lean{buildFullDTree_eval}
\label{buildFullDTree_eval}
\leanok
\uses{DecisionTree.eval, buildFullDTree}

For a function $f$, an index $k \le n$, and assignments $acc, x$ agreeing on all
coordinates below $k$ (i.e. $acc\,i = x\,i$ whenever $i.\mathrm{val} < k$), the complete
decision tree $\mathrm{buildFullDTree}\,f\,k\,acc$ evaluates to $f\,x$ on $x$.
\end{lemma}

n19402.content:
\begin{definition}[Circuit literal]
\lean{BoolCircuit.Lit}

\label{BoolCircuit.Lit}
\leanok
A literal for Boolean circuits: a variable index $\mathtt{idx} : \mathrm{Fin}\,n$
together with a polarity $\mathtt{sign} : \mathrm{Bool}$ (true = positive occurrence).
\end{definition}

n19403.content:
\begin{definition}[Literal]
\lean{Literal}

\label{Literal}
\leanok
A literal for switching-lemma formulas: a variable $\mathtt{var} : \mathrm{Fin}\,n$
with a negation flag $\mathtt{neg} : \mathrm{Bool}$ (true = negated literal).
\end{definition}

n19404.content:
\begin{definition}[Term]
\lean{Term}


\label{Term}
\leanok
\uses{Literal}
A term is a conjunction of literals, represented as a list:
$\mathtt{Term}\,n = \mathtt{List}\,(\mathtt{Literal}\,n)$.
\end{definition}

n19405.content:
\begin{definition}[Term width]
\lean{Term.width}


\label{Term.width}
\leanok
\uses{Term}
The width of a term is its number of literals (the list length).
\end{definition}

n19406.content:
\begin{definition}[Term evaluation]
\lean{Term.eval}


\label{Term.eval}
\leanok
\uses{Term}
A term evaluates to true on input $x$ iff every literal in it holds under $x$
(conjunction semantics).
\end{definition}

n19407.content:
\begin{definition}[DNF formula]
\lean{DNF}


\label{DNF}
\leanok
\uses{Term}
A DNF formula is a disjunction of terms, represented as a list:
$\mathtt{DNF}\,n = \mathtt{List}\,(\mathtt{Term}\,n)$.
\end{definition}

n19408.content:
\begin{definition}[DNF width]
\lean{DNF.width}


\label{DNF.width}
\leanok
\uses{DNF, Term.width}
The width of a DNF formula is the maximum width of its terms ($0$ for the empty
formula).
\end{definition}

n19409.content:
\begin{definition}[DNF evaluation]
\lean{DNF.eval}


\label{DNF.eval}
\leanok
\uses{DNF, Term.eval}
A DNF formula evaluates to true on input $x$ iff at least one of its terms holds
under $x$ (disjunction of conjunctions).
\end{definition}

n19410.content:
\begin{definition}[CNF formula]
\lean{CNF}


\label{CNF}
\leanok
\uses{Term}
A CNF formula is a conjunction of clauses, each clause a disjunction of literals;
it is represented as $\mathtt{CNF}\,n = \mathtt{List}\,(\mathtt{Term}\,n)$ with
dual evaluation semantics.
\end{definition}

n19411.content:
\begin{definition}[Clause evaluation]
\lean{CNF.evalClause}


\label{CNF.evalClause}
\leanok
\uses{CNF, Term}
A single CNF clause evaluates to true on input $x$ iff some literal in it holds
under $x$ (disjunction semantics).
\end{definition}

n19412.content:
\begin{definition}[CNF evaluation]
\lean{CNF.eval}


\label{CNF.eval}
\leanok
\uses{CNF, CNF.evalClause}
A CNF formula evaluates to true on input $x$ iff every clause holds under $x$.
\end{definition}

n19413.content:
\begin{definition}[Decision tree]
\lean{DecisionTree}

\label{DecisionTree}
\leanok
A decision tree on $n$ Boolean variables: a leaf $\mathtt{leaf}\,b$ outputs $b$,
and a branch $\mathtt{branch}\,i\,lo\,hi$ queries variable $i$, following $lo$ on
false and $hi$ on true.
\end{definition}

n19414.content:
\begin{definition}[Full decision tree]
\lean{buildFullDTree}
\label{buildFullDTree}
\leanok
\uses{DecisionTree}
The complete decision tree for a function $f$ that queries variables
$k, k+1, \dots, n-1$ in order, starting from accumulator assignment $acc$, and
outputs $f$ applied to the completed assignment at each leaf.
\end{definition}

n19415.content:
\begin{definition}[Decision-tree depth of a function]
\lean{dtDepth}

\label{dtDepth}
\leanok
\uses{DecisionTree, buildFullDTree}
The decision-tree depth of $f : (\mathrm{Fin}\,n \to \mathrm{Bool}) \to
\mathrm{Bool}$ is the least $d$ such that some decision tree of depth at most $d$
computes $f$; it is well defined since the full tree computes $f$ at depth $n$.
\end{definition}

n19416.content:
\begin{definition}[Free literals of a term under a restriction]
\lean{SwitchingLemma2.Term.freeLiterals}
\label{SwitchingLemma2.Term.freeLiterals}
\leanok
\uses{Literal, SwitchingLemma2.Restriction, SwitchingLemma2.Restriction.freeVars, Term}
Given a term $t$ (a conjunction of literals) and a restriction $\rho$, this is the list
of literals of $t$ whose underlying variable is still free under $\rho$, i.e. the
sublist of $t$ obtained by keeping those literals $l$ with $l.\mathrm{var} \in \rho.\mathrm{freeVars}$.
\end{definition}

n19417.content:
\begin{definition}[Process one clause's free literals against the path]
\lean{SwitchingLemma2.processClauseLits}
\label{SwitchingLemma2.processClauseLits}
\leanok

\uses{Literal, SwitchingLemma2.Restriction}
Consumes the free literals of a single clause (each paired with its position index)
against the canonical decision-tree path, one path entry per literal. For each free
literal it fixes the literal's variable to its satisfying direction in $\sigma$,
records the path direction in $\rho_0$ (mirroring the canonical decision-tree
branching), and appends the pair (literal position in clause, path direction) to the
auxiliary data. It returns the remaining path together with the updated $\rho_0$,
$\sigma$, and the accumulated clause auxiliary data.
\end{definition}

n19418.content:
\begin{definition}[Razborov encoding]
\lean{SwitchingLemma2.razborovEncode}
\label{SwitchingLemma2.razborovEncode}
\leanok

\uses{DNF, DecisionTree.deepPath, SwitchingLemma2.Restriction, SwitchingLemma2.canonicalDTree}
The Razborov encoding of a DNF $f$ and a restriction $\rho$ with parameters $w, d$.
It takes the first $d$ steps of the deepest path of the canonical decision tree for
$f|_\rho$, then repeatedly selects the first clause of $f$ not killed by the current
restriction, processes all of that clause's free literals against the path, and emits
a termination marker $(w, \mathrm{false})$. The result is a pair $(\gamma, \mathrm{aux})$,
where $\gamma$ extends $\rho$ by fixing $d$ variables to their satisfying directions
and $\mathrm{aux}$ consists of per-clause blocks separated by the termination markers.
\end{definition}

n19419.content:
\begin{definition}[Razborov decoding]
\lean{SwitchingLemma2.razborovDecode}
\label{SwitchingLemma2.razborovDecode}
\leanok

\uses{DNF, SwitchingLemma2.Restriction}
The inverse of the Razborov encoding: given the DNF $f$, parameter $w$, and a pair
$(\gamma, \mathrm{aux})$ produced by the encoder, it recovers the original restriction
$\rho$. It repeatedly finds the first clause not killed by the current restriction,
processes that clause's auxiliary block (unfixing each recorded variable in $\sigma$
and recording its path direction in $\rho_0$ until a termination marker is reached),
and returns the resulting restriction.
\end{definition}

n19420.content:
\begin{lemma}[Processing does not lengthen the path]
\lean{SwitchingLemma2.processClauseLits_path_le}
\label{SwitchingLemma2.processClauseLits_path_le}
\leanok
\uses{Literal, SwitchingLemma2.Restriction, SwitchingLemma2.processClauseLits}

The remaining path returned by \texttt{processClauseLits} is no longer than the input
path: the length of the first component of $\mathrm{processClauseLits}\,(\mathit{lits},
\mathit{path}, \rho_0, \sigma)$ is at most the length of $\mathit{path}$.
\end{lemma}

n19421.content:
\begin{lemma}[Output bound for processClauseLits]
\lean{SwitchingLemma2.processClauseLits_bound}

\label{SwitchingLemma2.processClauseLits_bound}
\leanok







\uses{Literal, SwitchingLemma2.Restriction, SwitchingLemma2.processClauseLits}

For any literal/index list and any path, the combined output of
\texttt{SwitchingLemma2.processClauseLits} is bounded: the length of its auxiliary entry
list plus twice the length of its remaining path is at most $2 \cdot |\mathrm{path}|$.
\end{lemma}

n19422.content:
\begin{lemma}[Tight bound for non-empty inputs]
\lean{SwitchingLemma2.processClauseLits_tight}
\label{SwitchingLemma2.processClauseLits_tight}
\leanok
\uses{Literal, SwitchingLemma2.Restriction, SwitchingLemma2.processClauseLits, SwitchingLemma2.processClauseLits_bound}

On non-empty literal and path lists, \texttt{SwitchingLemma2.processClauseLits} satisfies
the strengthened bound: the auxiliary-entry length plus one, plus twice the remaining
path length, is still at most twice the length of the input path.
\end{lemma}

n19423.content:
\begin{lemma}[Length bound for the encoder loop]
\lean{SwitchingLemma2.encode_go_aux_length_bound}

\label{SwitchingLemma2.encode_go_aux_length_bound}
\leanok


















\uses{DNF, SwitchingLemma2.Restriction, SwitchingLemma2.processClauseLits_tight}

The output produced by the encoder loop \texttt{SwitchingLemma2.razborovEncode}'s
\texttt{go} grows in a controlled way: its second component has length at most
$|\mathrm{acc}| + 2 \cdot |\mathrm{path}|$, where $\mathrm{acc}$ is the accumulator and
$\mathrm{path}$ the current path.
\end{lemma}

n19424.content:
\begin{lemma}[Encoding length is at most $2d$]
\lean{SwitchingLemma2.razborovEncode_aux_length_le}
\label{SwitchingLemma2.razborovEncode_aux_length_le}
\leanok




























\uses{DNF, DNF.eval, DecisionTree.deepPath, SwitchingLemma2.IsBadRestriction, SwitchingLemma2.Restriction, SwitchingLemma2.canonicalDTree, SwitchingLemma2.encode_go_aux_length_bound, SwitchingLemma2.razborovEncode}

For a bad restriction $\rho$ of a DNF $f$ with depth parameter $d$, the encoded output
\texttt{SwitchingLemma2.razborovEncode} has length at most $2d$.
\end{lemma}

n19425.content:
\begin{lemma}[processClauseLits preserves $\sigma$ off the literal list]
\lean{SwitchingLemma2.processClauseLits_sigma_stable}
\label{SwitchingLemma2.processClauseLits_sigma_stable}
\leanok
\uses{Literal, SwitchingLemma2.Restriction, SwitchingLemma2.processClauseLits}

If a variable $v$ is the variable of no literal in the input list, then
\texttt{SwitchingLemma2.processClauseLits} leaves the $\sigma$ restriction unchanged at
