The Razborov encoding is injective on bad restrictions: for a width-$w$ DNF $f$ with
distinct variables per term, if $\rho_1$ and $\rho_2$ are both bad restrictions for
$f.\mathrm{eval}$ at depth $d$ and their encodings agree,
$\mathrm{razborovEncode}\ f\ w\ d\ \rho_1 = \mathrm{razborovEncode}\ f\ w\ d\ \rho_2$,
then $\rho_1 = \rho_2$.
\end{theorem}

n19493.content:
\begin{definition}[Deterministic communication protocol]
\lean{CommunicationComplexity.Deterministic.Protocol}
\label{CommunicationComplexity.Deterministic.Protocol}
\leanok
A deterministic two-party communication protocol over input types $X$ (Alice) and $Y$ (Bob)
producing a value of type $\alpha$ is an inductive type with three constructors: an
\emph{output} node carrying the final value, an \emph{alice} node in which Alice applies a
function $f : X \to \mathrm{Bool}$ to her input and branches on the resulting bit, and a
\emph{bob} node in which Bob does the same with a function $g : Y \to \mathrm{Bool}$.
\end{definition}

n19494.content:
\begin{definition}[Protocol execution]
\lean{CommunicationComplexity.Deterministic.Protocol.run}
\label{CommunicationComplexity.Deterministic.Protocol.run}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol}
Given a protocol $p$, \texttt{run} evaluates $p$ on inputs $x : X$ and $y : Y$ by
recursively following the bit-branching structure until an output node is reached,
returning the stored value of type $\alpha$.
\end{definition}

n19495.content:
\begin{definition}[Communication complexity]
\lean{CommunicationComplexity.Deterministic.Protocol.complexity}
\label{CommunicationComplexity.Deterministic.Protocol.complexity}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol}
The communication complexity of a protocol $p$ is the worst-case total number of bits
exchanged: an output node costs $0$, while an alice or bob node costs $1$ plus the
maximum complexity of the two sub-protocols reached by the bit $\mathtt{false}$ and the
bit $\mathtt{true}$.
\end{definition}

n19496.content:
\begin{definition}[Protocol equivalence]
\lean{CommunicationComplexity.Deterministic.Protocol.Equiv}
\label{CommunicationComplexity.Deterministic.Protocol.Equiv}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.run}
Two protocols $p$ and $q$ over the same input and output types are \emph{equivalent} if
$\texttt{run}\,p = \texttt{run}\,q$, i.e.\ they produce identical outputs on every pair of
inputs $(x, y)$.
\end{definition}

n19497.content:
\begin{definition}[Protocol computes a function]
\lean{CommunicationComplexity.Deterministic.Protocol.Computes}
\label{CommunicationComplexity.Deterministic.Protocol.Computes}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.run}
A protocol $p$ \emph{computes} a two-argument function $f : X \to Y \to \alpha$ if
$p.\texttt{run}\,x\,y = f\,x\,y$ for all inputs $x : X$ and $y : Y$.
\end{definition}

n19498.content:
\begin{definition}[Role swap]
\lean{CommunicationComplexity.Deterministic.Protocol.swap}
\label{CommunicationComplexity.Deterministic.Protocol.swap}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol}
Given a protocol $p$ over $X \times Y$, \texttt{swap} produces a protocol over $Y \times X$
by exchanging the roles of Alice and Bob throughout: every alice node becomes a bob node
and vice versa, while output nodes are left unchanged.
\end{definition}

n19499.content:
\begin{theorem}[Swap preserves run]
\lean{CommunicationComplexity.Deterministic.Protocol.swap_run}
\label{CommunicationComplexity.Deterministic.Protocol.swap_run}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.run, CommunicationComplexity.Deterministic.Protocol.swap}

For any protocol $p$ over $X \times Y$ and any inputs $x : X$, $y : Y$,
\[
  p.\texttt{swap}.\texttt{run}\;y\;x \;=\; p.\texttt{run}\;x\;y.
\]
\end{theorem}

n19500.content:
\begin{theorem}[Swap preserves complexity]
\lean{CommunicationComplexity.Deterministic.Protocol.swap_complexity}
\label{CommunicationComplexity.Deterministic.Protocol.swap_complexity}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.complexity, CommunicationComplexity.Deterministic.Protocol.swap}

For any protocol $p$ over $X \times Y$,
\[
  p.\texttt{swap}.\texttt{complexity} \;=\; p.\texttt{complexity}.
\]
\end{theorem}

n19501.content:
\begin{theorem}[Swap is an involution]
\lean{CommunicationComplexity.Deterministic.Protocol.swap_swap}
\label{CommunicationComplexity.Deterministic.Protocol.swap_swap}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.swap}

Swapping Alice and Bob twice recovers the original protocol: for any $p$ over $X \times Y$,
$p.\texttt{swap}.\texttt{swap} = p$.
\end{theorem}

n19502.content:
\begin{theorem}[Alice node to Bob node]
\lean{CommunicationComplexity.Deterministic.Protocol.alice_to_bob}
\label{CommunicationComplexity.Deterministic.Protocol.alice_to_bob}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.complexity, CommunicationComplexity.Deterministic.Protocol.run, CommunicationComplexity.Deterministic.Protocol.swap, CommunicationComplexity.Deterministic.Protocol.swap_complexity, CommunicationComplexity.Deterministic.Protocol.swap_run}

For any alice-rooted protocol $\texttt{alice}\;f\;P$ over $X \times Y$, there exists a
protocol $q$ over $Y \times X$ such that $q.\texttt{run}\;y\;x = (\texttt{alice}\;f\;P).\texttt{run}\;x\;y$
for all $x, y$, and $q.\texttt{complexity} = (\texttt{alice}\;f\;P).\texttt{complexity}$.
This allows reducing the bob case to the alice case in inductive arguments.
\end{theorem}

n19503.content:
\begin{theorem}[Bob node to Alice node]
\lean{CommunicationComplexity.Deterministic.Protocol.bob_to_alice}
\label{CommunicationComplexity.Deterministic.Protocol.bob_to_alice}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.complexity, CommunicationComplexity.Deterministic.Protocol.run, CommunicationComplexity.Deterministic.Protocol.swap, CommunicationComplexity.Deterministic.Protocol.swap_complexity, CommunicationComplexity.Deterministic.Protocol.swap_run}

For any bob-rooted protocol $\texttt{bob}\;g\;P$ over $X \times Y$, there exists a protocol
$q$ over $Y \times X$ such that $q.\texttt{run}\;y\;x = (\texttt{bob}\;g\;P).\texttt{run}\;x\;y$
for all $x, y$, and $q.\texttt{complexity} = (\texttt{bob}\;g\;P).\texttt{complexity}$.
This allows reducing the alice case to the bob case in inductive arguments.
\end{theorem}

n19504.content:
\begin{definition}[Input pull-back]
\lean{CommunicationComplexity.Deterministic.Protocol.comap}
\label{CommunicationComplexity.Deterministic.Protocol.comap}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol}
Given functions $f_X : X' \to X$ and $f_Y : Y' \to Y$, \texttt{comap} pulls back a protocol
$p$ over $X \times Y$ to a protocol over $X' \times Y'$ by pre-composing every message
function with $f_X$ or $f_Y$ as appropriate, leaving output nodes unchanged.
\end{definition}

n19505.content:
\begin{theorem}[Comap run]
\lean{CommunicationComplexity.Deterministic.Protocol.comap_run}
\label{CommunicationComplexity.Deterministic.Protocol.comap_run}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.comap, CommunicationComplexity.Deterministic.Protocol.run}

For any protocol $p$ over $X \times Y$, input maps $f_X : X' \to X$ and $f_Y : Y' \to Y$,
and inputs $x' : X'$, $y' : Y'$,
\[
  (p.\texttt{comap}\;f_X\;f_Y).\texttt{run}\;x'\;y' \;=\; p.\texttt{run}\;(f_X\,x')\;(f_Y\,y').
\]
\end{theorem}

n19506.content:
\begin{theorem}[Comap preserves complexity]
\lean{CommunicationComplexity.Deterministic.Protocol.comap_complexity}
\label{CommunicationComplexity.Deterministic.Protocol.comap_complexity}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.comap, CommunicationComplexity.Deterministic.Protocol.complexity}

For any protocol $p$ over $X \times Y$ and input maps $f_X : X' \to X$, $f_Y : Y' \to Y$,
\[
  (p.\texttt{comap}\;f_X\;f_Y).\texttt{complexity} \;=\; p.\texttt{complexity}.
\]
\end{theorem}

n19507.content:
\begin{theorem}[Infimum over \texttt{ENat}-valued family bounded by coercion]
\lean{CommunicationComplexity.Internal.enat_iInf_le_coe_iff}
\label{CommunicationComplexity.Internal.enat_iInf_le_coe_iff}
\leanok

Let $\iota$ be a type and $f : \iota \to \mathbb{N}_\infty$ an $\mathbb{N}_\infty$-valued
family.  Then $\inf_{i} f(i) \le n$ if and only if there exists an index $i$ such that
$f(i) \le n$.  Here $n : \mathbb{N}$ is coerced into $\mathbb{N}_\infty = \mathrm{ENat}$.
\end{theorem}

n19508.content:
\begin{definition}[Deterministic communication complexity]
\lean{CommunicationComplexity.Deterministic.communicationComplexity}
\label{CommunicationComplexity.Deterministic.communicationComplexity}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.Computes, CommunicationComplexity.Deterministic.Protocol.complexity}
The deterministic communication complexity of $f : X \to Y \to \alpha$ is defined as
\[
  D(f) \;=\; \inf_{\substack{p \;:\; \mathrm{Protocol}\;X\;Y\;\alpha \\ p \text{ computes } f}}
              p.\mathrm{complexity} \;\in\; \mathbb{N}_\infty.
\]
The infimum is taken over all deterministic protocols $p$ that compute $f$, and the
result lives in $\mathrm{ENat}$ to accommodate the case where no finite protocol exists.
\end{definition}

n19509.content:
\begin{theorem}[Upper bound characterization of communication complexity]
\lean{CommunicationComplexity.Deterministic.communicationComplexity_le_iff}
\label{CommunicationComplexity.Deterministic.communicationComplexity_le_iff}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.Computes, CommunicationComplexity.Deterministic.Protocol.complexity, CommunicationComplexity.Deterministic.communicationComplexity, CommunicationComplexity.Internal.enat_iInf_le_coe_iff}

For $f : X \to Y \to \alpha$ and $n : \mathbb{N}$, we have $D(f) \le n$ if and only if
there exists a protocol $p : \mathrm{Protocol}\;X\;Y\;\alpha$ such that $p$ computes $f$
and $p.\mathrm{complexity} \le n$.
\end{theorem}

n19510.content:
\begin{theorem}[Finite-message upper bound characterization]
\lean{CommunicationComplexity.Deterministic.communicationComplexity_le_iff_finiteMessage}
\label{CommunicationComplexity.Deterministic.communicationComplexity_le_iff_finiteMessage}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.ofProtocol_equiv, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.run, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.toProtocol, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.toProtocol_complexity, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.toProtocol_run, CommunicationComplexity.Deterministic.communicationComplexity, CommunicationComplexity.Deterministic.communicationComplexity_le_iff}

For $f : X \to Y \to \alpha$ and $n : \mathbb{N}$, we have $D(f) \le n$ if and only if
there exists a finite-message protocol $p : \mathrm{FiniteMessage.Protocol}\;X\;Y\;\alpha$
such that $p.\mathrm{run} = f$ and $p.\mathrm{complexity} \le n$.  This equivalence follows
from the mutual simulation between general protocols and their finite-message counterparts.
\end{theorem}

n19511.content:
\begin{theorem}[Lower bound characterization of communication complexity]
\lean{CommunicationComplexity.Deterministic.le_communicationComplexity_iff}
\label{CommunicationComplexity.Deterministic.le_communicationComplexity_iff}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.Computes, CommunicationComplexity.Deterministic.Protocol.complexity, CommunicationComplexity.Deterministic.communicationComplexity}

For $f : X \to Y \to \alpha$ and $n : \mathbb{N}$, we have $n \le D(f)$ (in
$\mathbb{N}_\infty$) if and only if every protocol $p : \mathrm{Protocol}\;X\;Y\;\alpha$
that computes $f$ satisfies $n \le p.\mathrm{complexity}$.
\end{theorem}

n19512.content:
\begin{definition}[Map over protocol output]
\lean{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.map}
\label{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.map}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol}
Given a function $g : \alpha \to \beta$ and a protocol $p : \mathrm{Protocol}\,X\,Y\,\alpha$,
\texttt{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.map}~$g$~$p$ is the protocol that runs $p$ and then applies $g$ to the output,
yielding a protocol of type $\mathrm{Protocol}\,X\,Y\,\beta$ with the same communication
structure as $p$.
\end{definition}

n19513.content:
\begin{theorem}[Map commutes with run]
\lean{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.map_run}
\label{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.map_run}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.map, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.run}

For any function $g : \alpha \to \beta$, protocol $p$, and inputs $x \in X$, $y \in Y$,
\[
  (\texttt{map}\;g\;p).\texttt{run}\;x\;y \;=\; g\,(p.\texttt{run}\;x\;y).
\]
\end{theorem}

n19514.content:
\begin{theorem}[Map preserves complexity]
\lean{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.map_complexity}
\label{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.map_complexity}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.map}

For any function $g : \alpha \to \beta$ and protocol $p$,
$(\texttt{map}\;g\;p).\texttt{complexity} = p.\texttt{complexity}$.
Mapping a post-processing function over the output does not change the number of bits
communicated.
\end{theorem}

n19515.content:
\begin{definition}[Monadic bind of protocols]
\lean{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.bind}
\label{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.bind}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol}
Given a protocol $p : \mathrm{Protocol}\,X\,Y\,\alpha$ and a continuation
$q : \alpha \to \mathrm{Protocol}\,X\,Y\,\beta$, \texttt{bind}~$p$~$q$ sequentially
composes them: each output leaf $a$ of $p$ is replaced by the sub-protocol $q\,a$,
giving a protocol of type $\mathrm{Protocol}\,X\,Y\,\beta$.
\end{definition}

n19516.content:
\begin{theorem}[Bind commutes with run]
\lean{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.bind_run}
\label{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.bind_run}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.bind, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.run}

For any protocol $p$, continuation $q$, and inputs $x \in X$, $y \in Y$,
\[
  (\texttt{bind}\;p\;q).\texttt{run}\;x\;y
  \;=\; (q\,(p.\texttt{run}\;x\;y)).\texttt{run}\;x\;y.
\]
\end{theorem}

n19518.content:
\begin{theorem}[Bind complexity when continuation is constant]
\lean{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.bind_complexity_const}
\label{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.bind_complexity_const}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.bind, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.finset_sup_add_const}

If $q\,a$ has the same complexity $c$ for every output $a$ of $p$, then
\[
  (\texttt{bind}\;p\;q).\texttt{complexity} \;=\; p.\texttt{complexity} + c.
\]
\end{theorem}

n19519.content:
\begin{definition}[Product of two protocols]
\lean{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.prod}
\label{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.prod}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.map}
Given $p_1 : \mathrm{Protocol}\,X_1\,Y_1\,\alpha_1$ and
$p_2 : \mathrm{Protocol}\,X_2\,Y_2\,\alpha_2$, their product
$p_1.\texttt{prod}\;p_2 : \mathrm{Protocol}\,(X_1 \times X_2)\,(Y_1 \times Y_2)\,(\alpha_1 \times \alpha_2)$
runs $p_1$ on the first components and $p_2$ on the second components, pairing the outputs.
\end{definition}

n19520.content:
\begin{theorem}[Product run]
\lean{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.prod_run}
\label{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.prod_run}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.prod, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.run}

For protocols $p_1$, $p_2$ and inputs $x = (x_1, x_2)$, $y = (y_1, y_2)$,
\[
  (p_1.\texttt{prod}\;p_2).\texttt{run}\;x\;y
  \;=\; (p_1.\texttt{run}\;x_1\;y_1,\; p_2.\texttt{run}\;x_2\;y_2).
\]
\end{theorem}

n19521.content:
\begin{theorem}[Product complexity is additive]
\lean{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.prod_complexity}
\label{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.prod_complexity}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.finset_sup_add_const, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.prod}

The complexity of the product protocol satisfies
\[
  (p_1.\texttt{prod}\;p_2).\texttt{complexity}
  \;=\; p_1.\texttt{complexity} + p_2.\texttt{complexity}.
\]
\end{theorem}

n19522.content:
\begin{definition}[$k$-fold product of protocols]
\lean{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.pi}
\label{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.pi}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.bind, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.map}
Given a family of protocols $p_i : \mathrm{Protocol}\,X_i\,Y_i\,\alpha_i$ for
$i \in \mathrm{Fin}\,k$, \texttt{pi}~$p$ is the protocol of type
$\mathrm{Protocol}\,(\Pi_i\,X_i)\,(\Pi_i\,Y_i)\,(\Pi_i\,\alpha_i)$ that runs each $p_i$
on the $i$-th components and collects all outputs into a tuple.
It is defined by induction on $k$, using \texttt{bind}, \texttt{comap}, and \texttt{map}.
\end{definition}

n19523.content:
\begin{theorem}[$k$-fold product run]
\lean{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.pi_run}
\label{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.pi_run}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.bind_run, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap_run, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.map_run, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.pi, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.run}

For a family $p$ and input tuples $x$, $y$,
\[
  (\texttt{pi}\;p).\texttt{run}\;x\;y \;=\; \lambda i.\; (p_i).\texttt{run}\;(x\,i)\;(y\,i).
\]
\end{theorem}

n19524.content:
\begin{theorem}[$k$-fold product complexity is sum]
\lean{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.pi_complexity}
\label{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.pi_complexity}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.bind_complexity_const, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.map, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.pi}

The complexity of the $k$-fold product satisfies
\[
  (\texttt{pi}\;p).\texttt{complexity} \;=\; \sum_{i=0}^{k-1} (p_i).\texttt{complexity}.
\]
\end{theorem}

n19525.content:
\begin{definition}[Swap of a protocol input set]
\lean{CommunicationComplexity.Deterministic.Protocol.swapInputSet}
\label{CommunicationComplexity.Deterministic.Protocol.swapInputSet}
\leanok
Given a set $R \subseteq X \times Y$, $\texttt{swapInputSet}(R)$ is the set
$\{(y, x) \mid (x, y) \in R\} \subseteq Y \times X$ obtained by swapping the two
coordinates of every element.
\end{definition}

n19526.content:
\begin{theorem}[Membership in swapped set]
\lean{CommunicationComplexity.Deterministic.Protocol.mem_swapInputSet}
\label{CommunicationComplexity.Deterministic.Protocol.mem_swapInputSet}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol.swapInputSet}

For any set $R \subseteq X \times Y$ and pair $(y, x) \in Y \times X$,
$(y, x) \in \texttt{swapInputSet}(R)$ if and only if $(x, y) \in R$.
\end{theorem}

n19527.content:
\begin{theorem}[Swap is an involution]
\lean{CommunicationComplexity.Deterministic.Protocol.swapInputSet_swapInputSet}
\label{CommunicationComplexity.Deterministic.Protocol.swapInputSet_swapInputSet}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol.swapInputSet}

For any set $R \subseteq X \times Y$, applying $\texttt{swapInputSet}$ twice recovers
$R$: $\texttt{swapInputSet}(\texttt{swapInputSet}(R)) = R$.
\end{theorem}

n19528.content:
\begin{definition}[Preimage of a protocol input set]
\lean{CommunicationComplexity.Deterministic.Protocol.preimageInputSet}
\label{CommunicationComplexity.Deterministic.Protocol.preimageInputSet}
\leanok
Given maps $f_X : X' \to X$ and $f_Y : Y' \to Y$ and a set $R \subseteq X \times Y$,
$\texttt{preimageInputSet}(f_X, f_Y, R)$ is the set
$\{(x', y') \in X' \times Y' \mid (f_X(x'), f_Y(y')) \in R\}$, the pullback of $R$ along
the product map $f_X \times f_Y$.
\end{definition}

n19529.content:
\begin{theorem}[Membership in preimage input set]
\lean{CommunicationComplexity.Deterministic.Protocol.mem_preimageInputSet}
\label{CommunicationComplexity.Deterministic.Protocol.mem_preimageInputSet}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol.preimageInputSet}

For maps $f_X : X' \to X$, $f_Y : Y' \to Y$, a set $R \subseteq X \times Y$, and a pair
$(x', y') \in X' \times Y'$, we have $(x', y') \in \texttt{preimageInputSet}(f_X, f_Y, R)$
if and only if $(f_X(x'), f_Y(y')) \in R$.
\end{theorem}

n19530.content:
\begin{definition}[Auxiliary leaf rectangles relative to a constraint]
\lean{CommunicationComplexity.Deterministic.Protocol.leafRectanglesAux}
\label{CommunicationComplexity.Deterministic.Protocol.leafRectanglesAux}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol}
For a protocol $p$ and sets $A \subseteq X$, $B \subseteq Y$, $\texttt{leafRectanglesAux}(p, A, B)$
is the collection of rectangles induced by the leaves of $p$ when the reachable inputs are
constrained to $A \times B$. It is defined by structural recursion: an output node yields
$\{A \times B\}$, while Alice (resp.\ Bob) nodes split $A$ (resp.\ $B$) according to the
branching function and recurse.
\end{definition}

n19531.content:
\begin{definition}[Protocol leaf rectangles]
\lean{CommunicationComplexity.Deterministic.Protocol.leafRectangles}
\label{CommunicationComplexity.Deterministic.Protocol.leafRectangles}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.leafRectanglesAux}
The \emph{leaf rectangles} of a protocol $p : \texttt{Protocol}\,X\,Y\,\alpha$ form the
collection $\texttt{leafRectangles}(p) = \texttt{leafRectanglesAux}(p, X, Y)$, i.e.\ the set
of input rectangles induced by the leaves of $p$ over the full input space $X \times Y$.
\end{definition}

n19532.content:
\begin{theorem}[Swap sends leaf rectangles to leaf rectangles (auxiliary)]
\lean{CommunicationComplexity.Deterministic.Protocol.swapInputSet_mem_leafRectanglesAux_swap}
\label{CommunicationComplexity.Deterministic.Protocol.swapInputSet_mem_leafRectanglesAux_swap}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.leafRectanglesAux, CommunicationComplexity.Deterministic.Protocol.leafRectangles_cover, CommunicationComplexity.Deterministic.Protocol.swap, CommunicationComplexity.Deterministic.Protocol.swapInputSet}

If $R \in \texttt{leafRectanglesAux}(p, A, B)$, then
$\texttt{swapInputSet}(R) \in \texttt{leafRectanglesAux}(p.\texttt{swap}, B, A)$.
This is an internal auxiliary result proved by structural induction on the protocol.
\end{theorem}

n19533.content:
\begin{theorem}[Swap sends leaf rectangles to leaf rectangles]
\lean{CommunicationComplexity.Deterministic.Protocol.swapInputSet_mem_leafRectangles_swap}
\label{CommunicationComplexity.Deterministic.Protocol.swapInputSet_mem_leafRectangles_swap}
