\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity}

The pullback does not change the communication complexity:
$(p.\mathrm{comap}\,f_X\,f_Y).\mathrm{complexity} = p.\mathrm{complexity}$.
\end{theorem}

n19575.content:
\begin{definition}[Set disjointness function]
\lean{CommunicationComplexity.Functions.Disjointness.disjointness}
\label{CommunicationComplexity.Functions.Disjointness.disjointness}
\leanok
For $n \in \mathbb{N}$ and subsets $X, Y \subseteq [n]$, $\mathrm{disjointness}(n, X, Y)$
is the Boolean function that returns $\mathtt{true}$ if and only if $X$ and $Y$ are
disjoint, i.e.\ $X \cap Y = \emptyset$.
\end{definition}

n19576.content:
\begin{theorem}[Commutativity of disjointness]
\lean{CommunicationComplexity.Functions.Disjointness.disjointness_comm}
\label{CommunicationComplexity.Functions.Disjointness.disjointness_comm}
\leanok
\uses{CommunicationComplexity.Functions.Disjointness.disjointness}

The disjointness function is symmetric in its two set arguments: for all
$X, Y \subseteq [n]$, $\mathrm{disjointness}(n, X, Y) = \mathrm{disjointness}(n, Y, X)$.
\end{theorem}

n19577.content:
\begin{definition}[Fooling set for disjointness]
\lean{CommunicationComplexity.Functions.Disjointness.foolingSet}
\label{CommunicationComplexity.Functions.Disjointness.foolingSet}
\leanok
The candidate fooling set for disjointness is the collection of all pairs
$(X, X^c)$ where $X \subseteq [n]$, i.e.\ $\mathrm{foolingSet}(n) = \{(X, Y) \mid Y = X^c\}$.
\end{definition}

n19578.content:
\begin{theorem}[Fooling set validity]
\lean{CommunicationComplexity.Functions.Disjointness.foolingSet_isFoolingSet}
\label{CommunicationComplexity.Functions.Disjointness.foolingSet_isFoolingSet}
\leanok
\uses{CommunicationComplexity.Functions.Disjointness.disjointness, CommunicationComplexity.Functions.Disjointness.foolingSet, CommunicationComplexity.Rectangle.IsFoolingSet, CommunicationComplexity.Rectangle.IsRectangle_iff}

The collection $\{(X, X^c) \mid X \subseteq [n]\}$ is a fooling set for
$\mathrm{disjointness}(n)$: every pair $(X, X^c)$ evaluates to $\mathtt{true}$,
and for any monochromatic rectangle $R$ with $\mathrm{disjointness} = \mathtt{true}$
that contains two distinct fooling-set pairs, those pairs must coincide.
\end{theorem}

n19579.content:
\begin{theorem}[Fooling set cardinality]
\lean{CommunicationComplexity.Functions.Disjointness.foolingSet_card}
\label{CommunicationComplexity.Functions.Disjointness.foolingSet_card}
\leanok
\uses{CommunicationComplexity.Functions.Disjointness.foolingSet}

The fooling set $\mathrm{foolingSet}(n)$ has cardinality $2^n$, since it is in
bijection with the power set of $[n]$ via $X \mapsto (X, X^c)$.
\end{theorem}

n19580.content:
\begin{theorem}[Upper bound on complexity of disjointness]
\lean{CommunicationComplexity.Functions.Disjointness.communicationComplexity_le}
\label{CommunicationComplexity.Functions.Disjointness.communicationComplexity_le}
\leanok
\uses{CommunicationComplexity.Deterministic.communicationComplexity, CommunicationComplexity.Deterministic.communicationComplexity_le_clog_card_X_alpha, CommunicationComplexity.Functions.Disjointness.disjointness}

The deterministic communication complexity of $\mathrm{disjointness}(n)$ is at most
$n + 1$: Alice can communicate her entire set $X \subseteq [n]$ in $n$ bits, after
which Bob sends a single bit for the answer.
\end{theorem}

n19581.content:
\begin{theorem}[Lower bound on complexity of disjointness]
\lean{CommunicationComplexity.Functions.Disjointness.le_communicationComplexity}
\label{CommunicationComplexity.Functions.Disjointness.le_communicationComplexity}
\leanok
\uses{CommunicationComplexity.Deterministic.communicationComplexity, CommunicationComplexity.Deterministic.le_communicationComplexity_of_forall_lt_ncard, CommunicationComplexity.Functions.Disjointness.disjointness, CommunicationComplexity.Functions.Disjointness.foolingSet, CommunicationComplexity.Functions.Disjointness.foolingSet_isFoolingSet, CommunicationComplexity.Rectangle.monoPartition_point_mem, CommunicationComplexity.Rectangle.monoPartition_values_eq}

For $n \ge 1$, the deterministic communication complexity of $\mathrm{disjointness}(n)$
is at least $n + 1$.  The proof uses the fooling set of size $2^n$ together with an
additional input $(x_0, y_0)$ with $x_0 \cap y_0 \ne \emptyset$ to show that any
monochromatic partition of the input space into rectangles requires more than $2^n$
pieces.
\end{theorem}

n19582.content:
\begin{theorem}[Exact complexity of disjointness]
\lean{CommunicationComplexity.Functions.Disjointness.communicationComplexity_eq}
\label{CommunicationComplexity.Functions.Disjointness.communicationComplexity_eq}
\leanok
\uses{CommunicationComplexity.Deterministic.communicationComplexity, CommunicationComplexity.Functions.Disjointness.communicationComplexity_le, CommunicationComplexity.Functions.Disjointness.disjointness, CommunicationComplexity.Functions.Disjointness.le_communicationComplexity}

For $n \ge 1$, the deterministic communication complexity of the set-disjointness
function on subsets of $[n]$ is exactly $n + 1$.  This follows by combining the
matching upper and lower bounds.
\end{theorem}

n19583.content:
\begin{definition}[$n$-bit Boolean input type]
\lean{CommunicationComplexity.BoolInput}
\label{CommunicationComplexity.BoolInput}
\leanok
$\texttt{BoolInput}(n)$ is the type of $n$-bit Boolean inputs, defined as the function
type $\mathrm{Fin}\,n \to \mathrm{Bool}$.
\end{definition}

n19584.content:
\begin{definition}[All-zero Boolean input]
\lean{CommunicationComplexity.zeroInput}
\label{CommunicationComplexity.zeroInput}
\leanok
\uses{CommunicationComplexity.BoolInput}
$\texttt{zeroInput}(n) : \texttt{BoolInput}(n)$ is the constant $\mathrm{false}$ function,
i.e.\ the $n$-bit string consisting entirely of zeros.
\end{definition}

n19585.content:
\begin{lemma}[Nonzero input has a true coordinate]
\lean{CommunicationComplexity.exists_true_of_ne_zeroInput}
\label{CommunicationComplexity.exists_true_of_ne_zeroInput}
\leanok
\uses{CommunicationComplexity.BoolInput, CommunicationComplexity.boolSign, CommunicationComplexity.zeroInput}

If $x : \texttt{BoolInput}(n)$ satisfies $x \ne \texttt{zeroInput}(n)$, then there exists
some index $i \in \mathrm{Fin}\,n$ such that $x\,i = \mathrm{true}$.
\end{lemma}

n19586.content:
\begin{definition}[Boolean sign]
\lean{CommunicationComplexity.boolSign}
\label{CommunicationComplexity.boolSign}
\leanok
$\texttt{boolSign} : \mathrm{Bool} \to \mathbb{R}$ assigns the real value $1$ to
$\mathrm{false}$ and $-1$ to $\mathrm{true}$, embedding Boolean values into the
multiplicative group $\{\pm 1\} \subset \mathbb{R}$.
\end{definition}

n19587.content:
\begin{lemma}[Boolean sign converts xor to multiplication]
\lean{CommunicationComplexity.boolSign_xor}
\label{CommunicationComplexity.boolSign_xor}
\leanok
\uses{CommunicationComplexity.boolSign}

For all $a, b : \mathrm{Bool}$,
\[
  \texttt{CommunicationComplexity.boolSign}(a \oplus b) \;=\; \texttt{CommunicationComplexity.boolSign}(a) \cdot \texttt{CommunicationComplexity.boolSign}(b).
\]
That is, $\texttt{boolSign}$ is a group homomorphism from $(\mathrm{Bool}, \oplus)$ to
$(\{\pm 1\}, \cdot)$.
\end{lemma}

n19588.content:
\begin{lemma}[Boolean sign of a finite sum]
\lean{CommunicationComplexity.boolSign_sum}
\label{CommunicationComplexity.boolSign_sum}
\leanok
\uses{CommunicationComplexity.boolSign, CommunicationComplexity.boolSign_xor}

For a finite type $\alpha$, a finite set $s : \mathrm{Finset}\,\alpha$, and a function
$f : \alpha \to \mathrm{Bool}$,
\[
  \texttt{CommunicationComplexity.boolSign}\!\left(\sum_{i \in s} f(i)\right)
  \;=\; \prod_{i \in s} \texttt{boolSign}(f(i)).
\]
\end{lemma}

n19589.content:
\begin{lemma}[Product of two Boolean signs]
\lean{CommunicationComplexity.boolSign_mul_boolSign_eq_sub_two_indicator}
\label{CommunicationComplexity.boolSign_mul_boolSign_eq_sub_two_indicator}
\leanok
\uses{CommunicationComplexity.boolSign}

For all $a, b : \mathrm{Bool}$,
\[
  \texttt{CommunicationComplexity.boolSign}(a) \cdot \texttt{CommunicationComplexity.boolSign}(b)
  \;=\; 1 - 2 \cdot \mathbf{1}[a \ne b].
\]
In other words, the product of two $\pm 1$ signs equals $1$ when the bits agree and
$-1$ when they disagree.
\end{lemma}

n19590.content:
\begin{definition}[Single-coordinate flip]
\lean{CommunicationComplexity.flipAt}
\label{CommunicationComplexity.flipAt}
\leanok
\uses{CommunicationComplexity.BoolInput}
Given $i : \mathrm{Fin}\,n$ and $x : \texttt{BoolInput}(n)$, $\texttt{flipAt}\,i\,x$ is
the Boolean input obtained from $x$ by negating the $i$-th coordinate and leaving all
other coordinates unchanged.
\end{definition}

n19591.content:
\begin{lemma}[Flip applies at the flipped coordinate]
\lean{CommunicationComplexity.flipAt_apply_same}
\label{CommunicationComplexity.flipAt_apply_same}
\leanok
\uses{CommunicationComplexity.BoolInput, CommunicationComplexity.flipAt}

For $i : \mathrm{Fin}\,n$ and $x : \texttt{BoolInput}(n)$,
$(\texttt{flipAt}\,i\,x)\,i = \neg(x\,i)$.
\end{lemma}

n19592.content:
\begin{lemma}[Flip leaves other coordinates unchanged]
\lean{CommunicationComplexity.flipAt_apply_ne}
\label{CommunicationComplexity.flipAt_apply_ne}
\leanok
\uses{CommunicationComplexity.BoolInput, CommunicationComplexity.flipAt}

For $i, j : \mathrm{Fin}\,n$ with $j \ne i$ and $x : \texttt{BoolInput}(n)$,
$(\texttt{flipAt}\,i\,x)\,j = x\,j$.
\end{lemma}

n19593.content:
\begin{lemma}[Flip is an involution]
\lean{CommunicationComplexity.flipAt_flipAt}
\label{CommunicationComplexity.flipAt_flipAt}
\leanok
\uses{CommunicationComplexity.BoolInput, CommunicationComplexity.flipAt}

For $i : \mathrm{Fin}\,n$ and $x : \texttt{BoolInput}(n)$,
$\texttt{flipAt}\,i\,(\texttt{flipAt}\,i\,x) = x$.
That is, applying $\texttt{flipAt}\,i$ twice recovers the original input.
\end{lemma}

n19594.content:
\begin{lemma}[Flip is bijective]
\lean{CommunicationComplexity.flipAt_bijective}
\label{CommunicationComplexity.flipAt_bijective}
\leanok
\uses{CommunicationComplexity.BoolInput, CommunicationComplexity.flipAt, CommunicationComplexity.flipAt_flipAt}

For every $i : \mathrm{Fin}\,n$, the map
$\texttt{flipAt}\,i : \texttt{BoolInput}(n) \to \texttt{BoolInput}(n)$ is bijective; its
two-sided inverse is itself.
\end{lemma}

n19596.content:
\begin{definition}[Protocol execution]
\lean{CommunicationComplexity.Deterministic.OneWay.Protocol.run}
\label{CommunicationComplexity.Deterministic.OneWay.Protocol.run}
\leanok
\uses{CommunicationComplexity.Deterministic.OneWay.Protocol}
Given a one-way protocol $p$ and inputs $x \in X$, $y \in Y$, executing the protocol
yields the output $p.\mathtt{decode}(p.\mathtt{send}(x),\, y) \in \alpha$.
\end{definition}

n19597.content:
\begin{definition}[Protocol bit cost]
\lean{CommunicationComplexity.Deterministic.OneWay.Protocol.cost}
\label{CommunicationComplexity.Deterministic.OneWay.Protocol.cost}
\leanok
\uses{CommunicationComplexity.Deterministic.OneWay.Protocol}
The communication cost of a one-way protocol $p$ is $\lceil \log_2 |\mathtt{Message}| \rceil$
bits, where $\mathtt{Message}$ is the protocol's codebook.
\end{definition}

n19598.content:
\begin{definition}[Protocol computes a function]
\lean{CommunicationComplexity.Deterministic.OneWay.Protocol.Computes}
\label{CommunicationComplexity.Deterministic.OneWay.Protocol.Computes}
\leanok
\uses{CommunicationComplexity.Deterministic.OneWay.Protocol, CommunicationComplexity.Deterministic.OneWay.Protocol.run}
A one-way protocol $p$ \emph{computes} a function $f : X \to Y \to \alpha$ if
$p.\mathtt{run}(x, y) = f(x, y)$ for every pair of inputs $(x, y)$.
\end{definition}

n19599.content:
\begin{definition}[Embedding into the finite-message model]
\lean{CommunicationComplexity.Deterministic.OneWay.Protocol.toFiniteMessage}
\label{CommunicationComplexity.Deterministic.OneWay.Protocol.toFiniteMessage}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol, CommunicationComplexity.Deterministic.OneWay.Protocol}
Given a one-way protocol $p$ with finite output type $\alpha$, one obtains an interactive
finite-message protocol by having Alice send her one-way message and then having Bob
encode the decoded output as an index in $\{0,\ldots,|\alpha|-1\}$ and transmit it.
\end{definition}

n19600.content:
\begin{theorem}[Embedding preserves execution]
\lean{CommunicationComplexity.Deterministic.OneWay.Protocol.toFiniteMessage_run}
\label{CommunicationComplexity.Deterministic.OneWay.Protocol.toFiniteMessage_run}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.run, CommunicationComplexity.Deterministic.OneWay.Protocol, CommunicationComplexity.Deterministic.OneWay.Protocol.run, CommunicationComplexity.Deterministic.OneWay.Protocol.toFiniteMessage}

For any one-way protocol $p$ and inputs $(x, y)$, running $p$'s embedding in the
finite-message model yields the same output as running $p$ directly:
$\mathtt{FiniteMessage.Protocol.run}(p.\mathtt{toFiniteMessage},\, x,\, y) = p.\mathtt{run}(x, y)$.
\end{theorem}

n19601.content:
\begin{theorem}[Embedding complexity formula]
\lean{CommunicationComplexity.Deterministic.OneWay.Protocol.toFiniteMessage_complexity}
\label{CommunicationComplexity.Deterministic.OneWay.Protocol.toFiniteMessage_complexity}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.Deterministic.OneWay.Protocol, CommunicationComplexity.Deterministic.OneWay.Protocol.cost, CommunicationComplexity.Deterministic.OneWay.Protocol.toFiniteMessage}

The interactive complexity of the embedding equals the one-way cost plus the cost for
Bob to transmit the decoded output:
$(p.\mathtt{toFiniteMessage}).\mathtt{complexity} = p.\mathtt{cost} + \lceil \log_2 |\alpha| \rceil$.
\end{theorem}

n19602.content:
\begin{definition}[One-way communication complexity]
\lean{CommunicationComplexity.Deterministic.OneWay.communicationComplexity}
\label{CommunicationComplexity.Deterministic.OneWay.communicationComplexity}
\leanok
\uses{CommunicationComplexity.Deterministic.OneWay.Protocol, CommunicationComplexity.Deterministic.OneWay.Protocol.Computes, CommunicationComplexity.Deterministic.OneWay.Protocol.cost}
The one-way deterministic communication complexity of $f : X \to Y \to \alpha$ is the
infimum (in $\mathbb{N}_\infty$) of the bit costs $p.\mathtt{cost}$ over all one-way
protocols $p$ that compute $f$.
\end{definition}

n19603.content:
\begin{theorem}[Upper-bound characterization]
\lean{CommunicationComplexity.Deterministic.OneWay.communicationComplexity_le_iff}
\label{CommunicationComplexity.Deterministic.OneWay.communicationComplexity_le_iff}
\leanok
\uses{CommunicationComplexity.Deterministic.OneWay.Protocol, CommunicationComplexity.Deterministic.OneWay.Protocol.Computes, CommunicationComplexity.Deterministic.OneWay.Protocol.cost, CommunicationComplexity.Deterministic.OneWay.communicationComplexity, CommunicationComplexity.Internal.enat_iInf_le_coe_iff}

For a function $f$ and $n \in \mathbb{N}$, the one-way complexity of $f$ is at most $n$
if and only if there exists a one-way protocol $p$ that computes $f$ with
$p.\mathtt{cost} \le n$.
\end{theorem}

n19604.content:
\begin{theorem}[Lower-bound characterization]
\lean{CommunicationComplexity.Deterministic.OneWay.le_communicationComplexity_iff}
\label{CommunicationComplexity.Deterministic.OneWay.le_communicationComplexity_iff}
\leanok
\uses{CommunicationComplexity.Deterministic.OneWay.Protocol, CommunicationComplexity.Deterministic.OneWay.Protocol.Computes, CommunicationComplexity.Deterministic.OneWay.Protocol.cost, CommunicationComplexity.Deterministic.OneWay.communicationComplexity}

For a function $f$ and $k \in \mathbb{N}$, $k$ is at most the one-way complexity of $f$
if and only if every one-way protocol $p$ computing $f$ satisfies
$k \le p.\mathtt{cost}$.
\end{theorem}

n19605.content:
\begin{theorem}[One-way bound implies deterministic bound]
\lean{CommunicationComplexity.Deterministic.OneWay.deterministic_communicationComplexity_le_of_oneWay_le}
\label{CommunicationComplexity.Deterministic.OneWay.deterministic_communicationComplexity_le_of_oneWay_le}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.run, CommunicationComplexity.Deterministic.OneWay.Protocol.Computes, CommunicationComplexity.Deterministic.OneWay.Protocol.cost, CommunicationComplexity.Deterministic.OneWay.Protocol.run, CommunicationComplexity.Deterministic.OneWay.Protocol.toFiniteMessage, CommunicationComplexity.Deterministic.OneWay.communicationComplexity, CommunicationComplexity.Deterministic.OneWay.communicationComplexity_le_iff, CommunicationComplexity.Deterministic.communicationComplexity, CommunicationComplexity.Deterministic.communicationComplexity_le_iff_finiteMessage}

If the one-way communication complexity of $f : X \to Y \to \alpha$ is at most $n$, then
the (interactive) deterministic communication complexity of $f$ is at most
$n + \lceil \log_2 |\alpha| \rceil$, with the additive term accounting for Bob's cost
of transmitting the decoded output in the interactive model.
\end{theorem}

n19606.content:
\begin{theorem}[One-way bound implies deterministic bound for Boolean functions]
\lean{CommunicationComplexity.Deterministic.OneWay.deterministic_communicationComplexity_le_of_oneWay_le_bool}
\label{CommunicationComplexity.Deterministic.OneWay.deterministic_communicationComplexity_le_of_oneWay_le_bool}
\leanok
\uses{CommunicationComplexity.Deterministic.OneWay.communicationComplexity, CommunicationComplexity.Deterministic.OneWay.deterministic_communicationComplexity_le_of_oneWay_le, CommunicationComplexity.Deterministic.communicationComplexity}

For a Boolean function $f : X \to Y \to \mathtt{Bool}$, if the one-way complexity of $f$
is at most $n$, then the deterministic complexity of $f$ is at most $n + 1$; this
specializes the general bound using $\lceil \log_2 |\mathtt{Bool}| \rceil = 1$.
\end{theorem}

n19607.content:
\begin{definition}[Rectangle]
\lean{CommunicationComplexity.Rectangle.IsRectangle}
\label{CommunicationComplexity.Rectangle.IsRectangle}
\leanok
A subset $S \subseteq X \times Y$ is a \emph{rectangle} if it factors as a
product $A \times B$ for some $A \subseteq X$ and $B \subseteq Y$.
\end{definition}

n19608.content:
\begin{theorem}[Cross-product characterization of rectangles]
\lean{CommunicationComplexity.Rectangle.IsRectangle_iff}
\label{CommunicationComplexity.Rectangle.IsRectangle_iff}
\leanok
\uses{CommunicationComplexity.Rectangle.IsRectangle}

A set $R \subseteq X \times Y$ is a rectangle if and only if it satisfies the
\emph{cross property}: whenever $(x, y) \in R$ and $(x', y') \in R$, the mixed
pairs $(x', y)$ and $(x, y')$ also belong to $R$.
\end{theorem}

n19609.content:
\begin{definition}[Monochromatic set]
\lean{CommunicationComplexity.Rectangle.IsMonochromatic}
\label{CommunicationComplexity.Rectangle.IsMonochromatic}
\leanok
A set $S \subseteq X \times Y$ is \emph{monochromatic} for a function
$g : X \to Y \to \alpha$ if $g$ is constant on $S$, i.e., $g\,x\,y = g\,x'\,y'$
for all $(x,y), (x',y') \in S$.
\end{definition}

n19610.content:
\begin{definition}[Fooling set]
\lean{CommunicationComplexity.Rectangle.IsFoolingSet}
\label{CommunicationComplexity.Rectangle.IsFoolingSet}
\leanok
\uses{CommunicationComplexity.Rectangle.IsMonochromatic, CommunicationComplexity.Rectangle.IsRectangle}
A set $S \subseteq X \times Y$ is a \emph{fooling set} for $g : X \to Y \to \alpha$
if every monochromatic rectangle with respect to $g$ contains at most one point
of $S$, i.e., $S \cap R$ is a subsingleton for every rectangle $R$ that is
monochromatic for $g$.
\end{definition}

n19611.content:
\begin{definition}[Monochromatic rectangle partition]
\lean{CommunicationComplexity.Rectangle.IsMonoPartition}
\label{CommunicationComplexity.Rectangle.IsMonoPartition}
\leanok
\uses{CommunicationComplexity.Rectangle.IsMonochromatic, CommunicationComplexity.Rectangle.IsRectangle}
A collection $\mathcal{P}$ of subsets of $X \times Y$ is a \emph{monochromatic
rectangle partition} for $g : X \to Y \to \alpha$ if every member of
$\mathcal{P}$ is a rectangle, every member is monochromatic for $g$, the members
cover all of $X \times Y$, and distinct members are disjoint.
\end{definition}

n19612.content:
\begin{theorem}[Every point lies in some part]
\lean{CommunicationComplexity.Rectangle.monoPartition_point_mem}
\label{CommunicationComplexity.Rectangle.monoPartition_point_mem}
\leanok
\uses{CommunicationComplexity.Rectangle.IsMonoPartition}

If $\mathcal{P}$ is a monochromatic rectangle partition for $g$, then for every
point $p \in X \times Y$ there exists some $R \in \mathcal{P}$ with $p \in R$.
\end{theorem}

n19613.content:
\begin{theorem}[Uniqueness of part containing a point]
\lean{CommunicationComplexity.Rectangle.monoPartition_part_unique}
\label{CommunicationComplexity.Rectangle.monoPartition_part_unique}
\leanok
\uses{CommunicationComplexity.Rectangle.IsMonoPartition}

If $\mathcal{P}$ is a monochromatic rectangle partition for $g$ and a point
$p \in X \times Y$ belongs to two parts $R, S \in \mathcal{P}$, then $R = S$.
\end{theorem}

n19614.content:
\begin{theorem}[Cross closure within a part]
\lean{CommunicationComplexity.Rectangle.monoPartition_cross_mem}
\label{CommunicationComplexity.Rectangle.monoPartition_cross_mem}
\leanok
\uses{CommunicationComplexity.Rectangle.IsMonoPartition, CommunicationComplexity.Rectangle.IsRectangle_iff}

If $\mathcal{P}$ is a monochromatic rectangle partition for $g$, $R \in \mathcal{P}$,
and $(x,y), (x',y') \in R$, then the mixed pairs $(x',y)$ and $(x,y')$ both
belong to $R$.
\end{theorem}

n19615.content:
\begin{theorem}[Equal values within a part]
\lean{CommunicationComplexity.Rectangle.monoPartition_values_eq}
\label{CommunicationComplexity.Rectangle.monoPartition_values_eq}
\leanok
\uses{CommunicationComplexity.Rectangle.IsMonoPartition}

If $\mathcal{P}$ is a monochromatic rectangle partition for $g$, $R \in \mathcal{P}$,
and $(x,y), (x',y') \in R$, then $g\,x\,y = g\,x'\,y'$.
\end{theorem}

n19616.content:
\begin{theorem}[Fooling set bound — extended cardinality]
\lean{CommunicationComplexity.Rectangle.foolingSet_encard_le_of_monoPartition}
\label{CommunicationComplexity.Rectangle.foolingSet_encard_le_of_monoPartition}
\leanok
\uses{CommunicationComplexity.Rectangle.IsFoolingSet, CommunicationComplexity.Rectangle.IsMonoPartition, CommunicationComplexity.Rectangle.monoPartition_point_mem}

If $S$ is a fooling set for $g$ and $\mathcal{P}$ is a monochromatic rectangle
partition for $g$, then $\#S \le \#\mathcal{P}$ in the sense of extended natural
number cardinality (\texttt{Set.encard}).
\end{theorem}

n19617.content:
\begin{theorem}[Fooling set bound — finite cardinality]
\lean{CommunicationComplexity.Rectangle.foolingSet_ncard_le_of_monoPartition}
\label{CommunicationComplexity.Rectangle.foolingSet_ncard_le_of_monoPartition}
\leanok
\uses{CommunicationComplexity.Rectangle.IsFoolingSet, CommunicationComplexity.Rectangle.IsMonoPartition, CommunicationComplexity.Rectangle.foolingSet_encard_le_of_monoPartition}

If $S$ is a fooling set for $g$, $\mathcal{P}$ is a monochromatic rectangle
partition for $g$, and $\mathcal{P}$ is finite, then
$|S| \le |\mathcal{P}|$ as natural numbers (\texttt{Set.ncard}).
\end{theorem}

n19618.content:
\begin{definition}[Subprotocol predicate]
\lean{CommunicationComplexity.Deterministic.Protocol.IsSubprotocol}
\label{CommunicationComplexity.Deterministic.Protocol.IsSubprotocol}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol}
The inductive proposition $\texttt{IsSubprotocol}\; s\; p$ asserts that protocol $s$ is a
rooted subtree of protocol $p$.  It is generated by: reflexivity ($s$ is a subtree of
itself), and three step cases recording that $s$ is a subtree of one of the two children of
an Alice-node or the false-child of a Bob-node, and hence a subtree of the parent.
\end{definition}

n19619.content:
\begin{lemma}[Transitivity of subprotocol]
\lean{CommunicationComplexity.Deterministic.Protocol.IsSubprotocol.trans}
\label{CommunicationComplexity.Deterministic.Protocol.IsSubprotocol.trans}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.IsSubprotocol}

If $s$ is a subprotocol of $t$ and $t$ is a subprotocol of $u$, then $s$ is a subprotocol
of $u$.  That is, the subprotocol relation is transitive.
\end{lemma}

n19620.content:
\begin{lemma}[Balanced subprotocol auxiliary]
\lean{CommunicationComplexity.Deterministic.Protocol.balanced_aux}
\label{CommunicationComplexity.Deterministic.Protocol.balanced_aux}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.IsSubprotocol, CommunicationComplexity.Deterministic.Protocol.IsSubprotocol.trans, CommunicationComplexity.Deterministic.Protocol.numLeaves, CommunicationComplexity.Deterministic.Protocol.shape}

Given a protocol $p$ with $3 \cdot p.\mathrm{numLeaves} \ge 2n$ and $n > 1$, there exists a
subprotocol $s$ of $p$ satisfying $n \le 3 \cdot s.\mathrm{numLeaves} < 2n$.  This is the
inductive step used to prove the balanced subprotocol theorem.
\end{lemma}

n19621.content:
\begin{theorem}[Balanced subprotocol]
\lean{CommunicationComplexity.Deterministic.Protocol.balanced_subprotocol}
\label{CommunicationComplexity.Deterministic.Protocol.balanced_subprotocol}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.IsSubprotocol, CommunicationComplexity.Deterministic.Protocol.IsSubprotocol.trans, CommunicationComplexity.Deterministic.Protocol.balanced_aux, CommunicationComplexity.Deterministic.Protocol.numLeaves, CommunicationComplexity.Deterministic.Protocol.shape}

If a protocol $p$ has more than one leaf (i.e.\ $p.\mathrm{numLeaves} > 1$), then there
exists a subprotocol $s$ of $p$ satisfying
\[
  p.\mathrm{numLeaves} \;\le\; 3\cdot s.\mathrm{numLeaves} \;<\; 2\cdot p.\mathrm{numLeaves}.
\]
In other words, $s$ contains between one-third and two-thirds of $p$'s leaves.
\end{theorem}

n19622.content:
\begin{definition}[Subprotocol path witness]
\lean{CommunicationComplexity.Deterministic.Protocol.SubprotocolPath}
\label{CommunicationComplexity.Deterministic.Protocol.SubprotocolPath}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol}
The inductive type $\texttt{SubprotocolPath}\; s\; p$ is a data-carrying witness that $s$ is a
rooted subtree of $p$, recording the sequence of left/right choices made from the root of
$p$ down to the root of $s$.  It mirrors the constructors of \texttt{IsSubprotocol} but lives
in \texttt{Type} rather than \texttt{Prop}, enabling structural recursion over the path.
\end{definition}

n19623.content:
\begin{definition}[Path to subprotocol proof]
\lean{CommunicationComplexity.Deterministic.Protocol.SubprotocolPath.toIsSubprotocol}
\label{CommunicationComplexity.Deterministic.Protocol.SubprotocolPath.toIsSubprotocol}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.IsSubprotocol, CommunicationComplexity.Deterministic.Protocol.SubprotocolPath}
Every \texttt{SubprotocolPath} $s\; p$ can be mapped to a proof that $s$ is a subprotocol of
$p$: the function \texttt{SubprotocolPath.toIsSubprotocol} performs this conversion by
structural recursion on the path.
\end{definition}

n19624.content:
\begin{theorem}[Existence of a subprotocol path]
\lean{CommunicationComplexity.Deterministic.Protocol.path_exists_of_isSubprotocol}
\label{CommunicationComplexity.Deterministic.Protocol.path_exists_of_isSubprotocol}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.IsSubprotocol, CommunicationComplexity.Deterministic.Protocol.SubprotocolPath, CommunicationComplexity.Deterministic.Protocol.reachXPath}

If $s$ is a subprotocol of $p$ (i.e.\ \texttt{IsSubprotocol} $s\; p$ holds), then the type
\texttt{CommunicationComplexity.Deterministic.Protocol.SubprotocolPath} $s\; p$ is nonempty.  That is, every propositional subprotocol
embedding has at least one data-carrying path witness.
\end{theorem}

n19625.content:
\begin{definition}[Classical choice of a subprotocol path]
\lean{CommunicationComplexity.Deterministic.Protocol.choosePath}
\label{CommunicationComplexity.Deterministic.Protocol.choosePath}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.IsSubprotocol, CommunicationComplexity.Deterministic.Protocol.SubprotocolPath, CommunicationComplexity.Deterministic.Protocol.path_exists_of_isSubprotocol}
Given a proof that $s$ is a subprotocol of $p$, \texttt{choosePath} uses classical choice to
extract a definite \texttt{SubprotocolPath} $s\; p$ witness.  The resulting function is
noncomputable.
\end{definition}

n19626.content:
\begin{lemma}[Subprotocol has at most as many leaves]
\lean{CommunicationComplexity.Deterministic.Protocol.SubprotocolPath.numLeaves_le}
\label{CommunicationComplexity.Deterministic.Protocol.SubprotocolPath.numLeaves_le}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.SubprotocolPath, CommunicationComplexity.Deterministic.Protocol.numLeaves, CommunicationComplexity.Deterministic.Protocol.shape}

If \texttt{hsp} is a \texttt{SubprotocolPath} from $s$ to $p$, then
$s.\mathrm{numLeaves} \le p.\mathrm{numLeaves}$.  A subtree cannot have more leaves than
its parent.
\end{lemma}

n19627.content:
\begin{definition}[Reachable Alice inputs along a path]
\lean{CommunicationComplexity.Deterministic.Protocol.reachXPath}
\label{CommunicationComplexity.Deterministic.Protocol.reachXPath}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.SubprotocolPath}
Given a subprotocol path \texttt{hsp} from $s$ to $p$, \texttt{reachXPath hsp} is the set of
Alice's inputs $x \in X$ that are consistent with all of Alice's choices along the path from
the root of $p$ to the root of $s$.
\end{definition}

n19628.content:
\begin{definition}[Reachable Bob inputs along a path]
\lean{CommunicationComplexity.Deterministic.Protocol.reachYPath}
\label{CommunicationComplexity.Deterministic.Protocol.reachYPath}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.SubprotocolPath}
Given a subprotocol path \texttt{hsp} from $s$ to $p$, \texttt{reachYPath hsp} is the set of
Bob's inputs $y \in Y$ that are consistent with all of Bob's choices along the path from the
root of $p$ to the root of $s$.
\end{definition}

n19629.content:
\begin{definition}[Inputs that reach a subprotocol path]
\lean{CommunicationComplexity.Deterministic.Protocol.reachesPath}
\label{CommunicationComplexity.Deterministic.Protocol.reachesPath}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.SubprotocolPath, CommunicationComplexity.Deterministic.Protocol.reachXPath, CommunicationComplexity.Deterministic.Protocol.reachYPath}
$\texttt{reachesPath}\;\texttt{hsp}\;x\;y$ is the proposition that the input pair $(x, y)$
causes protocol $p$ to reach the subprotocol $s$ indicated by the path \texttt{hsp}; that is,
$x \in \texttt{reachXPath}\;\texttt{hsp}$ and $y \in \texttt{reachYPath}\;\texttt{hsp}$.
\end{definition}

n19630.content:
\begin{definition}[Alice's reach set for a subprotocol]
\lean{CommunicationComplexity.Deterministic.Protocol.reachX}
\label{CommunicationComplexity.Deterministic.Protocol.reachX}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.IsSubprotocol, CommunicationComplexity.Deterministic.Protocol.choosePath, CommunicationComplexity.Deterministic.Protocol.reachXPath}
Given a proof \texttt{hsp} that $s$ is a subprotocol of $p$, \texttt{reachX hsp} is the set of
Alice's inputs that reach the subprotocol, defined by applying \texttt{reachXPath} to the
classically chosen path.
\end{definition}

n19631.content:
\begin{definition}[Bob's reach set for a subprotocol]
\lean{CommunicationComplexity.Deterministic.Protocol.reachY}
\label{CommunicationComplexity.Deterministic.Protocol.reachY}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.IsSubprotocol, CommunicationComplexity.Deterministic.Protocol.choosePath, CommunicationComplexity.Deterministic.Protocol.reachYPath}
Given a proof \texttt{hsp} that $s$ is a subprotocol of $p$, \texttt{reachY hsp} is the set of
Bob's inputs that reach the subprotocol, defined by applying \texttt{reachYPath} to the
classically chosen path.
\end{definition}

n19632.content:
\begin{definition}[Inputs that reach a subprotocol]
\lean{CommunicationComplexity.Deterministic.Protocol.reaches}
\label{CommunicationComplexity.Deterministic.Protocol.reaches}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.IsSubprotocol, CommunicationComplexity.Deterministic.Protocol.reachX, CommunicationComplexity.Deterministic.Protocol.reachY}
$\texttt{reaches}\;\texttt{hsp}\;x\;y$ is the proposition that input $(x, y)$ causes $p$ to
reach the subprotocol $s$; equivalently, $x \in \texttt{reachX}\;\texttt{hsp}$ and
$y \in \texttt{reachY}\;\texttt{hsp}$.
\end{definition}

n19633.content:
\begin{lemma}[Subprotocol and parent agree on reached inputs (path version)]
\lean{CommunicationComplexity.Deterministic.Protocol.subprotocol_run_eq_of_reachesPath}
\label{CommunicationComplexity.Deterministic.Protocol.subprotocol_run_eq_of_reachesPath}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.SubprotocolPath, CommunicationComplexity.Deterministic.Protocol.reachXPath, CommunicationComplexity.Deterministic.Protocol.reachYPath, CommunicationComplexity.Deterministic.Protocol.reachesPath, CommunicationComplexity.Deterministic.Protocol.run}

If the input pair $(x, y)$ reaches the subprotocol $s$ of $p$ via path \texttt{hsp}, then
running $p$ and running $s$ on $(x, y)$ produce the same output: $p.\texttt{run}\;x\;y =
s.\texttt{run}\;x\;y$.
\end{lemma}

n19634.content:
\begin{lemma}[Subprotocol and parent agree on reached inputs]
\lean{CommunicationComplexity.Deterministic.Protocol.subprotocol_run_eq_of_reaches}
\label{CommunicationComplexity.Deterministic.Protocol.subprotocol_run_eq_of_reaches}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.IsSubprotocol, CommunicationComplexity.Deterministic.Protocol.choosePath, CommunicationComplexity.Deterministic.Protocol.reachX, CommunicationComplexity.Deterministic.Protocol.reachY, CommunicationComplexity.Deterministic.Protocol.reaches, CommunicationComplexity.Deterministic.Protocol.run, CommunicationComplexity.Deterministic.Protocol.subprotocol_run_eq_of_reachesPath}

If \texttt{hsp} witnesses that $s$ is a subprotocol of $p$ and $(x, y)$ reaches $s$, then
$p.\texttt{run}\;x\;y = s.\texttt{run}\;x\;y$.
\end{lemma}

