\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.Transcript, CommunicationComplexity.Deterministic.Protocol.swap}
Given a syntactic transcript $t$ of $p$, \texttt{transcriptSwap}~$t$ is the corresponding
transcript of the swapped protocol $p.\mathrm{swap}$ (where Alice and Bob exchange
roles), obtained by preserving the Boolean message sequence while reinterpreting each
node as the opposite player.
\end{definition}

n19672.content:
\begin{theorem}[Transcript swap is injective]
\lean{CommunicationComplexity.Deterministic.Protocol.transcriptSwap_injective}
\label{CommunicationComplexity.Deterministic.Protocol.transcriptSwap_injective}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.transcriptSwap}

For every protocol $p$, the map \texttt{transcriptSwap} from $\mathrm{Transcript}(p)$ to
$\mathrm{Transcript}(p.\mathrm{swap})$ is injective: distinct transcripts of $p$ give
distinct transcripts of the swapped protocol.
\end{theorem}

n19673.content:
\begin{theorem}[Swap commutes with transcript computation]
\lean{CommunicationComplexity.Deterministic.Protocol.transcriptSwap_transcript}
\label{CommunicationComplexity.Deterministic.Protocol.transcriptSwap_transcript}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.swap, CommunicationComplexity.Deterministic.Protocol.transcript, CommunicationComplexity.Deterministic.Protocol.transcriptSwap}

For every protocol $p$ and inputs $x \in X$, $y \in Y$, swapping the transcript of $p$
on $(x, y)$ equals the transcript of the swapped protocol on the reversed pair $(y, x)$:
$\mathrm{transcriptSwap}(p.\mathrm{transcript}(x, y)) = p.\mathrm{swap}.\mathrm{transcript}(y, x)$.
\end{theorem}

n19674.content:
\begin{definition}[Transcript comap]
\lean{CommunicationComplexity.Deterministic.Protocol.transcriptComap}
\label{CommunicationComplexity.Deterministic.Protocol.transcriptComap}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.Transcript, CommunicationComplexity.Deterministic.Protocol.comap, CommunicationComplexity.Deterministic.Protocol.transcriptSwap}
Given maps $f_X : X' \to X$ and $f_Y : Y' \to Y$ and a syntactic transcript $t$ of
$p$, \texttt{transcriptComap}~$p$~$f_X$~$f_Y$~$t$ is the corresponding transcript of
the pulled-back protocol $p.\mathrm{comap}(f_X, f_Y)$, obtained by preserving the
Boolean message sequence while re-routing through the input maps.
\end{definition}

n19675.content:
\begin{theorem}[Transcript comap is injective]
\lean{CommunicationComplexity.Deterministic.Protocol.transcriptComap_injective}
\label{CommunicationComplexity.Deterministic.Protocol.transcriptComap_injective}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.transcriptComap, CommunicationComplexity.Deterministic.Protocol.transcriptSwap}

For every protocol $p$ and input maps $f_X : X' \to X$, $f_Y : Y' \to Y$, the map
\texttt{CommunicationComplexity.Deterministic.Protocol.transcriptComap}~$p$~$f_X$~$f_Y$ from $\mathrm{Transcript}(p)$ to
$\mathrm{Transcript}(p.\mathrm{comap}(f_X, f_Y))$ is injective.
\end{theorem}

n19676.content:
\begin{theorem}[Comap commutes with transcript computation]
\lean{CommunicationComplexity.Deterministic.Protocol.transcriptComap_transcript}
\label{CommunicationComplexity.Deterministic.Protocol.transcriptComap_transcript}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.comap, CommunicationComplexity.Deterministic.Protocol.transcript, CommunicationComplexity.Deterministic.Protocol.transcriptComap, CommunicationComplexity.Deterministic.Protocol.transcriptSwap}

For every protocol $p$, maps $f_X : X' \to X$, $f_Y : Y' \to Y$, and inputs
$x' \in X'$, $y' \in Y'$, pulling back the transcript of $p$ on $(f_X(x'), f_Y(y'))$
equals the transcript of the comapped protocol on $(x', y')$:
$\mathrm{transcriptComap}(p,f_X,f_Y,p.\mathrm{transcript}(f_X(x'),f_Y(y')))
= (p.\mathrm{comap}(f_X,f_Y)).\mathrm{transcript}(x',y')$.
\end{theorem}

n19677.content:
\begin{definition}[Protocol tree shape]
\lean{CommunicationComplexity.Deterministic.Protocol.shape}
\label{CommunicationComplexity.Deterministic.Protocol.shape}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol}
Given a deterministic communication protocol $p$ over input types $X$ and $Y$ with output
type $\alpha$, \texttt{shape} maps $p$ to its underlying binary tree of type
\texttt{Tree Unit}.  An output node becomes a leaf (\texttt{Tree.nil}), while an Alice or
Bob branching node becomes an internal node (\texttt{Tree.node}) whose two children are the
shapes of the two sub-protocols reached by the bit $\mathtt{false}$ and
$\mathtt{true}$, respectively.
\end{definition}

n19678.content:
\begin{definition}[Number of protocol leaves]
\lean{CommunicationComplexity.Deterministic.Protocol.numLeaves}
\label{CommunicationComplexity.Deterministic.Protocol.numLeaves}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.shape}
The number of leaves (output nodes) of a protocol $p$ is defined as
$\texttt{numLeaves}(p) = \texttt{shape}(p).\texttt{numLeaves}$, i.e.\ the count of
\texttt{Tree.nil} nodes in the tree shape of $p$.
\end{definition}

n19679.content:
\begin{definition}[Subtree relation on binary trees]
\lean{CommunicationComplexity.TreeIsSubtree}
\label{CommunicationComplexity.TreeIsSubtree}
\leanok
\texttt{TreeIsSubtree s t} is an inductively defined proposition asserting that $s$ is a
subtree of $t$.  It has two constructors: reflexivity ($s$ is a subtree of itself) and a
descent rule ($s$ is a subtree of the left child $\ell$ of $\texttt{node}(v,\ell,r)$,
hence a subtree of the whole node; an analogous right rule also exists in the
implementation).
\end{definition}

n19680.content:
\begin{lemma}[Transitivity of the subtree relation]
\lean{CommunicationComplexity.TreeIsSubtree.trans}
\label{CommunicationComplexity.TreeIsSubtree.trans}
\leanok
\uses{CommunicationComplexity.TreeIsSubtree}

If $s$ is a subtree of $t$ and $t$ is a subtree of $u$, then $s$ is a subtree of $u$.
That is, \texttt{TreeIsSubtree} is transitive.
\end{lemma}

n19681.content:
\begin{lemma}[Balanced subtree — auxiliary]
\lean{CommunicationComplexity.tree_balanced_subtree_aux}
\label{CommunicationComplexity.tree_balanced_subtree_aux}
\leanok
\uses{CommunicationComplexity.TreeIsSubtree, CommunicationComplexity.TreeIsSubtree.trans}

Let $t$ be a binary tree and $n$ a natural number with $n > 1$ and
$3 \cdot \lvert t \rvert \ge 2n$, where $\lvert t \rvert$ denotes the number of leaves
of $t$.  Then there exists a subtree $s$ of $t$ such that
$n \le 3\lvert s \rvert < 2n$.
\end{lemma}

n19682.content:
\begin{theorem}[Balanced subtree]
\lean{CommunicationComplexity.tree_balanced_subtree}
\label{CommunicationComplexity.tree_balanced_subtree}
\leanok
\uses{CommunicationComplexity.TreeIsSubtree, CommunicationComplexity.TreeIsSubtree.trans, CommunicationComplexity.tree_balanced_subtree_aux}

Every binary tree $t$ with more than one leaf has a subtree $s$ satisfying
\[
  \lvert t \rvert \;\le\; 3\lvert s \rvert \;<\; 2\lvert t \rvert,
\]
where $\lvert \cdot \rvert$ denotes the leaf count.  Equivalently, $s$ contains at
least one third and strictly fewer than two thirds of the total leaves of $t$.
\end{theorem}

n19683.content:
\begin{theorem}[Complexity bounded by $\lceil\log|X|\rceil + \lceil\log|Y|\rceil$]
\lean{CommunicationComplexity.Deterministic.communicationComplexity_le_clog_card}
\label{CommunicationComplexity.Deterministic.communicationComplexity_le_clog_card}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.run, CommunicationComplexity.Deterministic.communicationComplexity, CommunicationComplexity.Deterministic.communicationComplexity_le_iff_finiteMessage}

For finite, nonempty types $X$ and $Y$ and any function $f : X \to Y \to \alpha$,
the deterministic communication complexity satisfies
\[
  \mathrm{CC}(f) \;\le\; \lceil\log_2 |X|\rceil + \lceil\log_2 |Y|\rceil.
\]
This bound is achieved by the protocol in which Alice sends her entire input to Bob
and Bob then sends his entire input to Alice.
\end{theorem}

n19684.content:
\begin{theorem}[Complexity bounded by $\lceil\log|X|\rceil + \lceil\log|\alpha|\rceil$]
\lean{CommunicationComplexity.Deterministic.communicationComplexity_le_clog_card_X_alpha}
\label{CommunicationComplexity.Deterministic.communicationComplexity_le_clog_card_X_alpha}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.run, CommunicationComplexity.Deterministic.communicationComplexity, CommunicationComplexity.Deterministic.communicationComplexity_le_iff_finiteMessage}

For finite, nonempty types $X$ and $\alpha$ and any function $f : X \to Y \to \alpha$,
the deterministic communication complexity satisfies
\[
  \mathrm{CC}(f) \;\le\; \lceil\log_2 |X|\rceil + \lceil\log_2 |\alpha|\rceil.
\]
This bound is achieved by the protocol in which Alice sends her input $x$ to Bob,
and Bob computes and sends back the output $f(x, y)$.
\end{theorem}

n19685.content:
\begin{theorem}[Complexity bounded by $\lceil\log|Y|\rceil + \lceil\log|\alpha|\rceil$]
\lean{CommunicationComplexity.Deterministic.communicationComplexity_le_clog_card_Y_alpha}
\label{CommunicationComplexity.Deterministic.communicationComplexity_le_clog_card_Y_alpha}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.run, CommunicationComplexity.Deterministic.communicationComplexity, CommunicationComplexity.Deterministic.communicationComplexity_le_iff_finiteMessage}

For finite, nonempty types $Y$ and $\alpha$ and any function $f : X \to Y \to \alpha$,
the deterministic communication complexity satisfies
\[
  \mathrm{CC}(f) \;\le\; \lceil\log_2 |Y|\rceil + \lceil\log_2 |\alpha|\rceil.
\]
This bound is achieved by the protocol in which Bob sends his input $y$ to Alice,
and Alice computes and sends back the output $f(x, y)$.
\end{theorem}

n19686.content:
\begin{definition}[Coin tape of length $n$]
\lean{CommunicationComplexity.CoinTape}
\label{CommunicationComplexity.CoinTape}
\leanok
$\texttt{CoinTape}(n)$ is the type $\mathrm{Fin}\,n \to \mathrm{Bool}$, i.e.\ the set of
all binary strings of length $n$, representing the $2^n$ possible outcomes of $n$
independent fair coin flips.
\end{definition}

n19687.content:
\begin{definition}[Public-coin protocol fixed to deterministic]
\lean{CommunicationComplexity.PublicCoin.Protocol.toDeterministic}
\label{CommunicationComplexity.PublicCoin.Protocol.toDeterministic}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.comap, CommunicationComplexity.PublicCoin.Protocol}
Given a public-coin protocol $p$ over randomness space $\Omega$ and a fixed
outcome $\omega : \Omega$, \texttt{PublicCoin.Protocol.toDeterministic}~$p~\omega$
is the deterministic protocol obtained by substituting $\omega$ for the shared
randomness (implemented via \texttt{comap} with $\mathrm{Prod.mk}\,\omega$).
\end{definition}

n19688.content:
\begin{theorem}[Fixed-randomness run equals randomised run]
\lean{CommunicationComplexity.PublicCoin.Protocol.toDeterministic_run}
\label{CommunicationComplexity.PublicCoin.Protocol.toDeterministic_run}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol.run, CommunicationComplexity.PublicCoin.Protocol, CommunicationComplexity.PublicCoin.Protocol.rrun, CommunicationComplexity.PublicCoin.Protocol.toDeterministic}

For any inputs $x : X$ and $y : Y$, running the deterministic protocol
$(p.\mathrm{toDeterministic}\,\omega)$ on $(x, y)$ yields the same output as
running the randomised protocol $p$ on $(x, y, \omega)$, i.e.\
$(p.\mathrm{toDeterministic}\,\omega).\mathrm{run}\,x\,y = p.\mathrm{rrun}\,x\,y\,\omega$.
\end{theorem}

n19689.content:
\begin{theorem}[Fixed-randomness complexity equals original]
\lean{CommunicationComplexity.PublicCoin.Protocol.toDeterministic_complexity}
\label{CommunicationComplexity.PublicCoin.Protocol.toDeterministic_complexity}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol.complexity, CommunicationComplexity.PublicCoin.Protocol, CommunicationComplexity.PublicCoin.Protocol.toDeterministic}

Fixing the shared randomness does not change the communication complexity:
$(p.\mathrm{toDeterministic}\,\omega).\mathrm{complexity} = p.\mathrm{complexity}$
for every $\omega : \Omega$.
\end{theorem}

n19690.content:
\begin{definition}[Deterministic finite-message protocol to private-coin]
\lean{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.toPrivateCoin}
\label{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.toPrivateCoin}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol}
Given a deterministic finite-message protocol $p$, the operation
\texttt{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.toPrivateCoin} converts it into a
private-coin finite-message protocol over arbitrary coin spaces $\Omega_X$ and
$\Omega_Y$ by ignoring both coin inputs (via \texttt{comap} with $\mathrm{Prod.snd}$).
\end{definition}

n19691.content:
\begin{theorem}[Private-coin run of embedded deterministic protocol]
\lean{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.toPrivateCoin_rrun}
\label{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.toPrivateCoin_rrun}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap_run, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.run, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.toPrivateCoin, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.rrun}

For any inputs $x : X$, $y : Y$ and any coin draws $\omega_X : \Omega_X$,
$\omega_Y : \Omega_Y$, the randomised run of $p.\mathrm{toPrivateCoin}$ equals
the deterministic run of $p$:
$\mathrm{rrun}(p.\mathrm{toPrivateCoin})\,x\,y\,\omega_X\,\omega_Y = p.\mathrm{run}\,x\,y$.
\end{theorem}

n19692.content:
\begin{theorem}[Complexity preserved under embedding into private-coin]
\lean{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.toPrivateCoin_complexity}
\label{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.toPrivateCoin_complexity}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.toPrivateCoin}

Embedding a deterministic finite-message protocol into the private-coin model
preserves its complexity: $(p.\mathrm{toPrivateCoin}).\mathrm{complexity} = p.\mathrm{complexity}$.
\end{theorem}

n19693.content:
\begin{definition}[Public-coin finite-message protocol fixed to deterministic]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toDeterministic}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toDeterministic}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol}
Given a public-coin finite-message protocol $p$ and a fixed randomness sample
$\omega : \Omega$, \texttt{PublicCoin.FiniteMessage.Protocol.toDeterministic}~$p~\omega$
is the deterministic finite-message protocol obtained by substituting $\omega$
for the shared randomness (via \texttt{comap} with $\mathrm{Prod.mk}\,\omega$).
\end{definition}

n19694.content:
\begin{theorem}[Fixed-randomness run equals randomised run (finite-message)]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toDeterministic_run}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toDeterministic_run}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap_run, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.run, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rrun, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toDeterministic}

For any inputs $x : X$ and $y : Y$, the deterministic run of
$p.\mathrm{toDeterministic}\,\omega$ equals the randomised run at $\omega$:
$(p.\mathrm{toDeterministic}\,\omega).\mathrm{run}\,x\,y = p.\mathrm{rrun}\,x\,y\,\omega$.
\end{theorem}

n19695.content:
\begin{theorem}[Fixed-randomness complexity equals original (finite-message)]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toDeterministic_complexity}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toDeterministic_complexity}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toDeterministic}

Fixing the shared randomness of a public-coin finite-message protocol does not
change its complexity:
$(p.\mathrm{toDeterministic}\,\omega).\mathrm{complexity} = p.\mathrm{complexity}$.
\end{theorem}

n19696.content:
\begin{theorem}[Private-coin complexity at most deterministic]
\lean{CommunicationComplexity.PrivateCoin.communicationComplexity_le_deterministic}
\label{CommunicationComplexity.PrivateCoin.communicationComplexity_le_deterministic}
\leanok
\uses{CommunicationComplexity.CoinTape, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap_run, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.ofProtocol_equiv, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.run, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.toPrivateCoin, CommunicationComplexity.Deterministic.communicationComplexity, CommunicationComplexity.Deterministic.communicationComplexity_le_iff, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.rrun, CommunicationComplexity.PrivateCoin.communicationComplexity, CommunicationComplexity.PrivateCoin.communicationComplexity_le_iff_finiteMessage}

For any function $f : X \to Y \to \alpha$ and any error parameter $\varepsilon \ge 0$,
the private-coin communication complexity satisfies
\[
  \mathrm{CC}_{\mathrm{priv}}(f, \varepsilon) \;\le\; \mathrm{CC}_{\mathrm{det}}(f).
\]
The inequality holds because every deterministic protocol can be viewed as a
private-coin protocol with zero error by embedding it via \texttt{toPrivateCoin}.
\end{theorem}

n19697.content:
\begin{definition}[Finite measurable space]
\lean{CommunicationComplexity.FiniteMeasureSpace}
\label{CommunicationComplexity.FiniteMeasureSpace}
\leanok
A typeclass for a measurable space $\Omega$ that is simultaneously finite (carries a
\texttt{Fintype} instance) and discrete (every subset is measurable).  It deliberately
does not bundle a measure, so that a single type can be equipped with many different
measures.
\end{definition}

n19698.content:
\begin{definition}[Constructor for \texttt{FiniteMeasureSpace}]
\lean{CommunicationComplexity.FiniteMeasureSpace.of}
\label{CommunicationComplexity.FiniteMeasureSpace.of}
\leanok
\uses{CommunicationComplexity.FiniteMeasureSpace}
Given a type $\Omega$ that already carries \texttt{Fintype} and
\texttt{DiscreteMeasurableSpace} instances, \texttt{CommunicationComplexity.FiniteMeasureSpace.of} bundles them
into a \texttt{FiniteMeasureSpace} record without requiring any additional data.
\end{definition}

n19699.content:
\begin{definition}[Finite probability space]
\lean{CommunicationComplexity.FiniteProbabilitySpace}
\label{CommunicationComplexity.FiniteProbabilitySpace}
\leanok
\uses{CommunicationComplexity.FiniteMeasureSpace}
A typeclass bundling a \texttt{MeasureSpace} structure on $\Omega$ together with a
\texttt{CommunicationComplexity.FiniteMeasureSpace} witness and an \texttt{IsProbabilityMeasure} instance for the
canonical volume measure.  This makes $\Omega$ simultaneously a finite discrete
measurable space and a probability space.
\end{definition}

n19700.content:
\begin{definition}[Constructor from existing instances]
\lean{CommunicationComplexity.FiniteProbabilitySpace.of}
\label{CommunicationComplexity.FiniteProbabilitySpace.of}
\leanok
\uses{CommunicationComplexity.FiniteMeasureSpace.of, CommunicationComplexity.FiniteProbabilitySpace}
Given a type $\Omega$ already equipped with a \texttt{MeasureSpace}, \texttt{Fintype},
\texttt{DiscreteMeasurableSpace}, and \texttt{IsProbabilityMeasure} instance for
\texttt{volume}, this helper packages all of those into a \texttt{CommunicationComplexity.FiniteProbabilitySpace}
record.
\end{definition}

n19701.content:
\begin{definition}[Constructor from an explicit measure]
\lean{CommunicationComplexity.FiniteProbabilitySpace.ofMeasure}
\label{CommunicationComplexity.FiniteProbabilitySpace.ofMeasure}
\leanok
\uses{CommunicationComplexity.FiniteMeasureSpace, CommunicationComplexity.FiniteProbabilitySpace}
Given a finite measurable space $\Omega$ and an unbundled probability measure $\mu$ on
it, \texttt{FiniteProbabilitySpace.ofMeasure} promotes $\mu$ to the canonical volume and
returns a \texttt{FiniteProbabilitySpace} instance.
\end{definition}

n19702.content:
\begin{theorem}[Singleton decomposition of a finite measure]
\lean{CommunicationComplexity.FiniteMeasureSpace.measureReal_eq_sum_singletons}
\label{CommunicationComplexity.FiniteMeasureSpace.measureReal_eq_sum_singletons}
\leanok
\uses{CommunicationComplexity.FiniteMeasureSpace}

Let $\Omega$ be a finite measurable space, $\mu$ a finite measure on it, and $S
\subseteq \Omega$ any set.  Then
\[
  \mu^{\mathbb{R}}(S) \;=\; \sum_{\omega \in \Omega}
    \begin{cases} \mu^{\mathbb{R}}(\{\omega\}) & \text{if } \omega \in S, \\ 0 & \text{otherwise.} \end{cases}
\]
In other words, a finite measure on a finite measurable space is determined by and
recovers as a finite sum over its singleton masses.
\end{theorem}

n19703.content:
\begin{theorem}[Measure of a preimage via fibers]
\lean{CommunicationComplexity.FiniteMeasureSpace.measureReal_preimage_eq_sum_fibers}
\label{CommunicationComplexity.FiniteMeasureSpace.measureReal_preimage_eq_sum_fibers}
\leanok
\uses{CommunicationComplexity.FiniteMeasureSpace, CommunicationComplexity.FiniteMeasureSpace.measureReal_eq_sum_singletons}

Let $Z : \Omega \to \alpha$ be a function from a finite measurable space to a finite
type, $\mu$ a finite measure on $\Omega$, and $P$ a predicate on $\alpha$.  Then
\[
  \mu^{\mathbb{R}}\{\omega \mid P(Z(\omega))\}
  \;=\; \sum_{z \in \alpha} \begin{cases} \mu^{\mathbb{R}}(Z^{-1}\{z\}) & \text{if } P(z), \\ 0 & \text{otherwise.} \end{cases}
\]
\end{theorem}

n19704.content:
\begin{theorem}[Absolute continuity via singletons]
\lean{CommunicationComplexity.FiniteMeasureSpace.absolutelyContinuous_iff_forall_singletons}
\label{CommunicationComplexity.FiniteMeasureSpace.absolutelyContinuous_iff_forall_singletons}
\leanok
\uses{CommunicationComplexity.FiniteMeasureSpace}

On a finite measurable space, two measures satisfy $\mu \ll \nu$ if and only if for
every $\omega \in \Omega$, $\nu(\{\omega\}) = 0$ implies $\mu(\{\omega\}) = 0$.
\end{theorem}

n19705.content:
\begin{theorem}[Jensen's inequality: square of expectation]
\lean{CommunicationComplexity.FiniteMeasureSpace.sq_integral_le_integral_sq}
\label{CommunicationComplexity.FiniteMeasureSpace.sq_integral_le_integral_sq}
\leanok
\uses{CommunicationComplexity.FiniteMeasureSpace}

For any probability measure $\mu$ on a finite measurable space and any function $f :
\Omega \to \mathbb{R}$,
\[
  \Bigl(\int_\Omega f\,d\mu\Bigr)^2 \;\le\; \int_\Omega f^2\,d\mu.
\]
\end{theorem}

n19706.content:
\begin{theorem}[Integral as a sum over fibers]
\lean{CommunicationComplexity.FiniteMeasureSpace.integral_comp_eq_sum_measureReal_fibers}
\label{CommunicationComplexity.FiniteMeasureSpace.integral_comp_eq_sum_measureReal_fibers}
\leanok
\uses{CommunicationComplexity.FiniteMeasureSpace}

Let $Z : \Omega \to \alpha$ be a measurable map from a finite measurable space to a
finite discrete type, $\mu$ a finite measure on $\Omega$, and $f : \alpha \to
\mathbb{R}$.  Then
\[
  \int_\Omega f(Z(\omega))\,d\mu(\omega)
  \;=\; \sum_{z \in \alpha} \mu^{\mathbb{R}}(Z^{-1}\{z\}) \cdot f(z).
\]
\end{theorem}

n19709.content:
\begin{theorem}[Uniform measure equals subtype cardinality ratio]
\lean{CommunicationComplexity.uniformOn_univ_measureReal_eq_card_subtype}
\label{CommunicationComplexity.uniformOn_univ_measureReal_eq_card_subtype}
\leanok
\uses{CommunicationComplexity.uniformOn_univ_measureReal_eq_card_filter}

Under the uniform measure on a nonempty finite discrete type $\Omega$, the
real-valued measure of a set $S$ equals $|\{S\}| / |\Omega|$ where $|\{S\}|$ denotes
the cardinality of the subtype $\{\omega : \Omega \mid \omega \in S\}$.
\end{theorem}

n19710.content:
\begin{theorem}[A finite probability space is nonempty]
\lean{CommunicationComplexity.FiniteProbabilitySpace.nonempty}
\label{CommunicationComplexity.FiniteProbabilitySpace.nonempty}
\leanok
\uses{CommunicationComplexity.FiniteProbabilitySpace}

Any type carrying a \texttt{FiniteProbabilitySpace} instance is nonempty.
\end{theorem}

n19711.content:
\begin{definition}[Probability mass function of a finite probability space]
\lean{CommunicationComplexity.FiniteProbabilitySpace.toPMF}
\label{CommunicationComplexity.FiniteProbabilitySpace.toPMF}
\leanok
\uses{CommunicationComplexity.FiniteProbabilitySpace}
For a finite probability space $\Omega$, \texttt{toPMF} converts the canonical volume
measure to a probability mass function $\mathrm{PMF}\,\Omega$, assigning to each
$\omega$ the real weight $\mu(\{\omega\})$.
\end{definition}

n19712.content:
\begin{theorem}[Measure of a set as a PMF sum]
\lean{CommunicationComplexity.FiniteProbabilitySpace.measure_eq}
\label{CommunicationComplexity.FiniteProbabilitySpace.measure_eq}
\leanok
