n19731.content:
\begin{definition}[Hash function space]
\lean{CommunicationComplexity.Functions.Hash.HashSpace}
\label{CommunicationComplexity.Functions.Hash.HashSpace}
\leanok
$\texttt{HashSpace}\,\alpha\,k$ is the type of all functions $\alpha \to \mathrm{Fin}\,k$,
i.e.\ the space of hash functions on $\alpha$ with output range $\{0,\dots,k-1\}$.
Equipped with the product probability measure (uniform over each coordinate), it serves
as the ambient probability space for the random-hash argument.
\end{definition}

n19732.content:
\begin{definition}[Collision piece]
\lean{CommunicationComplexity.Functions.Hash.collisionPiece}
\label{CommunicationComplexity.Functions.Hash.collisionPiece}
\leanok
\uses{CommunicationComplexity.Functions.Hash.HashSpace}
For $x, y : \alpha$ and $a : \mathrm{Fin}\,k$, $\texttt{collisionPiece}\,k\,x\,y\,a$ is
the set of hash functions $h \in \texttt{HashSpace}\,\alpha\,k$ satisfying $h(x) = a$ and
$h(y) = a$, i.e.\ the subset of the product space where both $x$ and $y$ are mapped to
the fixed value $a$.  These pieces partition the collision event $\{h \mid h(x) = h(y)\}$.
\end{definition}

n19733.content:
\begin{lemma}[Collision event as union of pieces]
\lean{CommunicationComplexity.Functions.Hash.collision_mem_iUnion}
\label{CommunicationComplexity.Functions.Hash.collision_mem_iUnion}
\leanok
\uses{CommunicationComplexity.Functions.Hash.HashSpace, CommunicationComplexity.Functions.Hash.collisionPiece}

For any $x, y : \alpha$ and any $k$,
\[
  \{h : \texttt{HashSpace}\,\alpha\,k \mid h(x) = h(y)\}
  \;=\; \bigcup_{a : \mathrm{Fin}\,k} \texttt{collisionPiece}\,k\,x\,y\,a.
\]
\end{lemma}

n19734.content:
\begin{lemma}[Collision pieces are pairwise disjoint]
\lean{CommunicationComplexity.Functions.Hash.collisionPiece_pairwiseDisjoint}
\label{CommunicationComplexity.Functions.Hash.collisionPiece_pairwiseDisjoint}
\leanok
\uses{CommunicationComplexity.Functions.Hash.collisionPiece}

For any $x, y : \alpha$ and $k$, the sets $\texttt{collisionPiece}\,k\,x\,y\,a$ for
$a : \mathrm{Fin}\,k$ are pairwise disjoint: if $a \ne b$ then
$\texttt{collisionPiece}\,k\,x\,y\,a \cap \texttt{collisionPiece}\,k\,x\,y\,b = \emptyset$.
\end{lemma}

n19735.content:
\begin{lemma}[Singleton measure in hash range]
\lean{CommunicationComplexity.Functions.Hash.hashRange_singleton_measure}
\label{CommunicationComplexity.Functions.Hash.hashRange_singleton_measure}
\leanok

For $k \ge 1$ and any $a : \mathrm{Fin}\,k$, the uniform measure of the singleton
$\{a\} \subseteq \mathrm{Fin}\,k$ equals $1/k$ as an extended non-negative real:
$\mu(\{a\}) = 1/k \in \mathbb{R}_{\ge 0}^\infty$.
\end{lemma}

n19736.content:
\begin{lemma}[Singleton measure in hash range (real-valued)]
\lean{CommunicationComplexity.Functions.Hash.hashRange_singleton_measureReal}
\label{CommunicationComplexity.Functions.Hash.hashRange_singleton_measureReal}
\leanok
\uses{CommunicationComplexity.Functions.Hash.hashRange_singleton_measure}

For $k \ge 1$ and any $a : \mathrm{Fin}\,k$, the real-valued uniform measure of $\{a\}$
in $\mathrm{Fin}\,k$ equals $1/k \in \mathbb{R}$, i.e.\ $\mu_{\mathbb{R}}(\{a\}) = 1/k$.
\end{lemma}

n19737.content:
\begin{lemma}[Measure of a collision piece]
\lean{CommunicationComplexity.Functions.Hash.collisionPiece_measureReal}
\label{CommunicationComplexity.Functions.Hash.collisionPiece_measureReal}
\leanok
\uses{CommunicationComplexity.FiniteProbabilitySpace.measureReal_pi_univ, CommunicationComplexity.Functions.Hash.collisionPiece, CommunicationComplexity.Functions.Hash.hashRange_singleton_measureReal}

Let $\alpha$ be a finite type, $k \ge 1$, $x \ne y \in \alpha$, and $a : \mathrm{Fin}\,k$.
Under the product measure on $\texttt{HashSpace}\,\alpha\,k$,
\[
  \mu_{\mathbb{R}}(\texttt{collisionPiece}\,k\,x\,y\,a) = \left(\frac{1}{k}\right)^2.
\]
\end{lemma}

n19738.content:
\begin{theorem}[Collision probability bound]
\lean{CommunicationComplexity.Functions.Hash.collision_prob_le}
\label{CommunicationComplexity.Functions.Hash.collision_prob_le}
\leanok
\uses{CommunicationComplexity.FiniteProbabilitySpace.measureReal_iUnion_fintype, CommunicationComplexity.Functions.Hash.HashSpace, CommunicationComplexity.Functions.Hash.collisionPiece_measureReal, CommunicationComplexity.Functions.Hash.collisionPiece_pairwiseDisjoint, CommunicationComplexity.Functions.Hash.collision_mem_iUnion}

Let $\alpha$ be a finite type, $k \ge 1$, and let $x \ne y \in \alpha$.
For a uniformly random hash function $h : \alpha \to \mathrm{Fin}\,k$,
\[
  \Pr[h(x) = h(y)] \;\le\; \frac{1}{k}.
\]
That is, $\mu_{\mathbb{R}}\bigl(\{h \in \texttt{HashSpace}\,\alpha\,k \mid h(x) = h(y)\}\bigr) \le 1/k$.
\end{theorem}

n19739.content:
\begin{definition}[Distributional error of a deterministic protocol]
\lean{CommunicationComplexity.Deterministic.Protocol.distributionalError}
\label{CommunicationComplexity.Deterministic.Protocol.distributionalError}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.run, CommunicationComplexity.FiniteProbabilitySpace}
Given a deterministic protocol $p : \mathrm{Protocol}\,X\,Y\,\alpha$, a finite
probability space $\mu$ on $X \times Y$, and a target function $f : X \to Y \to \alpha$,
the \emph{distributional error} $p.\mathrm{distributionalError}(\mu, f) \in \mathbb{R}$
is the $\mu$-probability that the output of $p$ disagrees with $f$, i.e.\
$\mu\bigl(\{(x,y) \mid p.\mathrm{run}(x,y) \ne f(x,y)\}\bigr)$.
\end{definition}

n19740.content:
\begin{lemma}[Failure integral swap]
\lean{CommunicationComplexity.PublicCoin.failureIntegral_swap}
\label{CommunicationComplexity.PublicCoin.failureIntegral_swap}
\leanok
\uses{CommunicationComplexity.CoinTape, CommunicationComplexity.FiniteProbabilitySpace, CommunicationComplexity.FiniteProbabilitySpace.measureReal_eq_integral_indicator_one, CommunicationComplexity.PublicCoin.Protocol, CommunicationComplexity.PublicCoin.Protocol.rrun}

Let $\mu$ be a finite probability space on $X \times Y$, let $m \in \mathbb{N}$, and let
$p$ be a public-coin protocol with coin tape of length $m$.  For any $f : X \to Y \to \alpha$,
\[
  \int_{\omega}\,\mu\!\left(\bigl\{(x,y) \mid p.\mathrm{rrun}(x,y,\omega) \ne f(x,y)\bigr\}\right)\,d\omega
  \;=\;
  \int_{(x,y)}\,\mathrm{vol}\!\left(\bigl\{\omega : \mathrm{CoinTape}\,m \mid
    p.\mathrm{rrun}(x,y,\omega) \ne f(x,y)\bigr\}\right)\,d\mu,
\]
obtained by swapping the order of integration via Fubini's theorem applied to the
failure-indicator function.
\end{lemma}

n19741.content:
\begin{theorem}[Yao's minimax principle]
\lean{CommunicationComplexity.PublicCoin.lt_communicationComplexity_of_forall_distributionalError_gt}
\label{CommunicationComplexity.PublicCoin.lt_communicationComplexity_of_forall_distributionalError_gt}
\leanok
\uses{CommunicationComplexity.CoinTape, CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.complexity, CommunicationComplexity.Deterministic.Protocol.distributionalError, CommunicationComplexity.FiniteProbabilitySpace, CommunicationComplexity.FiniteProbabilitySpace.integral_le_of_le, CommunicationComplexity.FiniteProbabilitySpace.lt_integral_of_lt, CommunicationComplexity.PublicCoin.Protocol.rrun, CommunicationComplexity.PublicCoin.Protocol.toDeterministic, CommunicationComplexity.PublicCoin.Protocol.toDeterministic_run, CommunicationComplexity.PublicCoin.communicationComplexity, CommunicationComplexity.PublicCoin.communicationComplexity_le_iff, CommunicationComplexity.PublicCoin.failureIntegral_swap}

Let $f : X \to Y \to \alpha$, $\varepsilon \in \mathbb{R}$, $n \in \mathbb{N}$, and let
$\mu$ be a finite probability distribution on $X \times Y$.  If every deterministic
protocol $p$ with $p.\mathrm{complexity} \le n$ satisfies
$p.\mathrm{distributionalError}(\mu, f) > \varepsilon$, then the public-coin randomized
communication complexity of $f$ at error $\varepsilon$ is strictly greater than $n$.
This is one direction of Yao's minimax principle: a hard distribution for all small
deterministic protocols certifies a lower bound on randomized complexity.
\end{theorem}

n19743.content:
\begin{definition}[Deterministic protocol from public-coin protocol]
\lean{CommunicationComplexity.PublicCoin.OneWay.Protocol.toDeterministic}
\label{CommunicationComplexity.PublicCoin.OneWay.Protocol.toDeterministic}
\leanok
\uses{CommunicationComplexity.Deterministic.OneWay.Protocol, CommunicationComplexity.PublicCoin.OneWay.Protocol}
Given a one-way public-coin protocol $p$ over a randomness space $\Omega$ and a fixed
coin outcome $\omega \in \Omega$, \texttt{toDeterministic}~$p$~$\omega$ is the
deterministic one-way protocol obtained by substituting $\omega$ for the public
randomness: it uses the same message type and sends/decodes by fixing $\omega$ in $p$.
\end{definition}

n19744.content:
\begin{theorem}[Run of derandomised protocol]
\lean{CommunicationComplexity.PublicCoin.OneWay.Protocol.toDeterministic_run}
\label{CommunicationComplexity.PublicCoin.OneWay.Protocol.toDeterministic_run}
\leanok
\uses{CommunicationComplexity.Deterministic.OneWay.Protocol.run, CommunicationComplexity.PublicCoin.OneWay.Protocol, CommunicationComplexity.PublicCoin.OneWay.Protocol.rrun, CommunicationComplexity.PublicCoin.OneWay.Protocol.toDeterministic}

For any public-coin protocol $p$, coin outcome $\omega$, and inputs $x \in X$,
$y \in Y$,
\[
  (p.\mathrm{toDeterministic}(\omega)).\mathrm{run}(x, y)
  \;=\;
  p.\mathrm{rrun}(x, y, \omega).
\]
That is, running the derandomised protocol on $(x,y)$ agrees with running the
randomised protocol on $(x,y)$ with fixed randomness $\omega$.
\end{theorem}

n19745.content:
\begin{theorem}[Cost of derandomised protocol]
\lean{CommunicationComplexity.PublicCoin.OneWay.Protocol.toDeterministic_cost}
\label{CommunicationComplexity.PublicCoin.OneWay.Protocol.toDeterministic_cost}
\leanok
\uses{CommunicationComplexity.Deterministic.OneWay.Protocol.cost, CommunicationComplexity.PublicCoin.OneWay.Protocol, CommunicationComplexity.PublicCoin.OneWay.Protocol.toDeterministic}

For any public-coin protocol $p$ and coin outcome $\omega$,
\[
  (p.\mathrm{toDeterministic}(\omega)).\mathrm{cost} \;=\; p.\mathrm{cost}.
\]
Fixing the randomness does not change the communication cost of the protocol.
\end{theorem}

n19746.content:
\begin{lemma}[Fubini swap for failure integrals]
\lean{CommunicationComplexity.PublicCoin.OneWay.failureIntegral_swap}
\label{CommunicationComplexity.PublicCoin.OneWay.failureIntegral_swap}
\leanok
\uses{CommunicationComplexity.CoinTape, CommunicationComplexity.FiniteProbabilitySpace, CommunicationComplexity.FiniteProbabilitySpace.measureReal_eq_integral_indicator_one, CommunicationComplexity.PublicCoin.OneWay.Protocol, CommunicationComplexity.PublicCoin.OneWay.Protocol.rrun}

Let $\mu$ be a finite probability measure on $X \times Y$, let $p$ be a one-way
public-coin protocol with coin tape of length $m$, and let $f : X \to Y \to \alpha$.
Then
\[
  \int_{\omega}\Pr_{(x,y)\sim\mu}\bigl[p.\mathrm{rrun}(x,y,\omega)\neq f(x,y)\bigr]\,d\omega
  \;=\;
  \int_{(x,y)\sim\mu}\Pr_{\omega}\bigl[p.\mathrm{rrun}(x,y,\omega)\neq f(x,y)\bigr]\,d\mu,
\]
i.e.\ the order of integration over the coin tape and the input distribution may be
exchanged (Fubini's theorem applied to the $\{0,1\}$-valued failure indicator).
\end{lemma}

n19748.content:
\begin{definition}[Cumulative distribution function on $\mathrm{Fin}\,m$]
\lean{CommunicationComplexity.Internal.cdf}
\label{CommunicationComplexity.Internal.cdf}
\leanok
Given a probability mass function $p$ on $\mathrm{Fin}\,m$ and a natural number $n$,
$\mathrm{cdf}(p, n)$ is the cumulative probability $\sum_{j < n} p(j)$, computed as an
extended non-negative real ($\mathbb{R}_{\ge 0}^\infty$).
\end{definition}

n19749.content:
\begin{lemma}[CDF at zero]
\lean{CommunicationComplexity.Internal.cdf_zero}
\label{CommunicationComplexity.Internal.cdf_zero}
\leanok
\uses{CommunicationComplexity.Internal.cdf}

For any PMF $p$ on $\mathrm{Fin}\,m$, $\mathrm{cdf}(p, 0) = 0$.
\end{lemma}

n19750.content:
\begin{lemma}[CDF successor recurrence]
\lean{CommunicationComplexity.Internal.cdf_succ}
\label{CommunicationComplexity.Internal.cdf_succ}
\leanok
\uses{CommunicationComplexity.Internal.cdf}

For any PMF $p$ on $\mathrm{Fin}\,m$ and index $n \in \mathrm{Fin}\,m$,
$\mathrm{cdf}(p, n+1) = \mathrm{cdf}(p, n) + p(n)$.
\end{lemma}

n19751.content:
\begin{lemma}[CDF at $m$ equals one]
\lean{CommunicationComplexity.Internal.cdf_one}
\label{CommunicationComplexity.Internal.cdf_one}
\leanok
\uses{CommunicationComplexity.Internal.cdf}

For any PMF $p$ on $\mathrm{Fin}\,m$, $\mathrm{cdf}(p, m) = 1$.
\end{lemma}

n19752.content:
\begin{lemma}[CDF is monotone]
\lean{CommunicationComplexity.Internal.cdf_mono}
\label{CommunicationComplexity.Internal.cdf_mono}
\leanok
\uses{CommunicationComplexity.Internal.cdf}

For any PMF $p$ on $\mathrm{Fin}\,m$, the function $n \mapsto \mathrm{cdf}(p, n)$ is
monotone non-decreasing.
\end{lemma}

n19753.content:
\begin{definition}[Inverse CDF]
\lean{CommunicationComplexity.Internal.invCdf}
\label{CommunicationComplexity.Internal.invCdf}
\leanok
\uses{CommunicationComplexity.Internal.cdf}
Given a PMF $p$ on $\mathrm{Fin}\,m$ (with $m \ge 1$) and a value $x \in \mathbb{R}_{\ge 0}^\infty$,
$\mathrm{invCdf}(p, x)$ is the largest index $i \in \mathrm{Fin}\,m$ satisfying
$\mathrm{cdf}(p, i) \le x$, i.e.\ the generalized inverse (quantile) of the CDF.
\end{definition}

n19754.content:
\begin{theorem}[Inverse CDF characterization]
\lean{CommunicationComplexity.Internal.invCdf_eq_iff}
\label{CommunicationComplexity.Internal.invCdf_eq_iff}
\leanok
\uses{CommunicationComplexity.Internal.cdf, CommunicationComplexity.Internal.cdf_mono, CommunicationComplexity.Internal.cdf_one, CommunicationComplexity.Internal.invCdf}

Let $p$ be a PMF on $\mathrm{Fin}\,m$ with $m \ge 1$, let $x < 1$ in
$\mathbb{R}_{\ge 0}^\infty$, and let $i \in \mathrm{Fin}\,m$.
Then $\mathrm{invCdf}(p, x) = i$ if and only if $\mathrm{cdf}(p, i) \le x < \mathrm{cdf}(p, i+1)$.
\end{theorem}

n19755.content:
\begin{definition}[Uniform approximation via inverse CDF]
\lean{CommunicationComplexity.Internal.uniformApprox}
\label{CommunicationComplexity.Internal.uniformApprox}
\leanok
\uses{CommunicationComplexity.Internal.invCdf}
Given a PMF $p$ on $\mathrm{Fin}\,m$ and a positive integer $n$, the map
$\mathrm{uniformApprox}(p, n) : \mathrm{Fin}\,n \to \mathrm{Fin}\,m$ sends
$j \mapsto \mathrm{invCdf}(p, j/n)$, discretizing the unit interval into $n$ equally
spaced points and mapping each through the quantile function of $p$.
\end{definition}

n19756.content:
\begin{lemma}[Counting bound in a real interval]
\lean{CommunicationComplexity.Internal.card_nat_in_Ico}
\label{CommunicationComplexity.Internal.card_nat_in_Ico}
\leanok

For any $n \in \mathbb{N}$ and real numbers $a \le b$, the number of indices
$j \in \mathrm{Fin}\,n$ satisfying $a \le j < b$ is at most $b - a + 1$.
\end{lemma}

n19757.content:
\begin{theorem}[Uniform approximation error bound]
\lean{CommunicationComplexity.Internal.uniformApprox_approx}
\label{CommunicationComplexity.Internal.uniformApprox_approx}
\leanok
\uses{CommunicationComplexity.Internal.card_nat_in_Ico, CommunicationComplexity.Internal.cdf, CommunicationComplexity.Internal.cdf_mono, CommunicationComplexity.Internal.cdf_one, CommunicationComplexity.Internal.cdf_succ, CommunicationComplexity.Internal.invCdf_eq_iff, CommunicationComplexity.Internal.uniformApprox}

For any PMF $p$ on $\mathrm{Fin}\,m$, positive $n$, and index $i \in \mathrm{Fin}\,m$,
the empirical frequency with which $\mathrm{uniformApprox}(p, n)$ outputs $i$ satisfies
\[
  \frac{|\{j \in \mathrm{Fin}\,n : \mathrm{uniformApprox}(p,n)(j) = i\}|}{n}
  \;\le\; p(i) + \frac{1}{n}.
\]
\end{theorem}

n19758.content:
\begin{theorem}[Single-space coin approximation]
\lean{CommunicationComplexity.Internal.single_coin_approx}
\label{CommunicationComplexity.Internal.single_coin_approx}
\leanok
\uses{CommunicationComplexity.CoinTape, CommunicationComplexity.FiniteProbabilitySpace, CommunicationComplexity.FiniteProbabilitySpace.hasSum_measure_singletons, CommunicationComplexity.FiniteProbabilitySpace.measureReal_preimage_finset, CommunicationComplexity.Internal.uniformApprox, CommunicationComplexity.Internal.uniformApprox_approx, CommunicationComplexity.uniformOn_univ_measureReal_eq_card_filter}

For any finite probability space $\Omega$ and any $\delta > 0$, there exist $n \in \mathbb{N}$
and a map $\varphi : \mathrm{CoinTape}(n) \to \Omega$ such that for every set $S \subseteq \Omega$,
\[
  \mu_{\mathrm{CoinTape}(n)}(\varphi^{-1}(S)) \;\le\; \mu_\Omega(S) + \delta.
\]
\end{theorem}

n19759.content:
\begin{lemma}[Weighted sum approximation]
\lean{CommunicationComplexity.Internal.weighted_sum_approx}
\label{CommunicationComplexity.Internal.weighted_sum_approx}
\leanok

Let $\alpha$ be a finite type, $p, q : \alpha \to \mathbb{R}$, and $g : \alpha \to \mathbb{R}$
with $0 \le g(a) \le 1$ for all $a$.
If $\sum_{a \in T} p(a) \le \sum_{a \in T} q(a) + \delta$ for every finite set $T$,
then $\sum_a p(a)\,g(a) \le \sum_a q(a)\,g(a) + \delta$.
\end{lemma}

n19760.content:
\begin{theorem}[Product-space coin approximation]
\lean{CommunicationComplexity.Internal.product_coin_approx}
\label{CommunicationComplexity.Internal.product_coin_approx}
\leanok
\uses{CommunicationComplexity.CoinTape, CommunicationComplexity.FiniteProbabilitySpace, CommunicationComplexity.FiniteProbabilitySpace.measureReal_finset, CommunicationComplexity.FiniteProbabilitySpace.measureReal_iUnion_fintype, CommunicationComplexity.FiniteProbabilitySpace.measureReal_preimage_finset, CommunicationComplexity.FiniteProbabilitySpace.measureReal_prod, CommunicationComplexity.Internal.single_coin_approx, CommunicationComplexity.Internal.weighted_sum_approx}

For any two finite probability spaces $\Omega_X$ and $\Omega_Y$ and any $\delta > 0$,
there exist $n_X, n_Y \in \mathbb{N}$ and maps $\varphi_X : \mathrm{CoinTape}(n_X) \to \Omega_X$,
$\varphi_Y : \mathrm{CoinTape}(n_Y) \to \Omega_Y$ such that for every set
$S \subseteq \Omega_X \times \Omega_Y$,
\[
  \mu((\varphi_X \times \varphi_Y)^{-1}(S)) \;\le\; \mu(S) + \delta.
\]
\end{theorem}

n19761.content:
\begin{definition}[Protocol conversion to coin tape]
\lean{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.toCoinTape}
\label{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.toCoinTape}
\leanok
\uses{CommunicationComplexity.CoinTape, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap, CommunicationComplexity.FiniteProbabilitySpace, CommunicationComplexity.Internal.product_coin_approx, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol}
Given a finite-message private-coin protocol $p$ over finite probability spaces $\Omega_X$
and $\Omega_Y$, and a tolerance $\delta > 0$, $\mathrm{toCoinTape}(p, \delta)$ produces
$n_X$, $n_Y$, and a new finite-message protocol over $\mathrm{CoinTape}(n_X) \times
\mathrm{CoinTape}(n_Y)$ obtained by precomposing $p$ with the inverse-CDF approximating
maps $\varphi_X$ and $\varphi_Y$.
\end{definition}

n19762.content:
\begin{theorem}[Coin-tape protocol preserves complexity]
\lean{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.toCoinTape_complexity}
\label{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.toCoinTape_complexity}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.FiniteProbabilitySpace, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.toCoinTape}

The coin-tape conversion $\mathrm{toCoinTape}(p, \delta, h_\delta)$ produces a protocol
of the same communication complexity as $p$, i.e.\
$\mathrm{toCoinTape}(p, \delta, h_\delta)\mathtt{.snd.snd.complexity} = p\mathtt{.complexity}$.
\end{theorem}

n19763.content:
\begin{theorem}[Coin-tape conversion preserves approximate correctness]
\lean{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.toCoinTape_approxSatisfies}
\label{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.toCoinTape_approxSatisfies}
\leanok
\uses{CommunicationComplexity.CoinTape, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap_run, CommunicationComplexity.FiniteProbabilitySpace, CommunicationComplexity.Internal.product_coin_approx, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.ApproxSatisfies, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.rrun, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.toCoinTape}

If a protocol $p$ approximately satisfies a predicate $Q$ with error at most $\varepsilon$,
then the coin-tape conversion $\mathrm{toCoinTape}(p, \delta, h_\delta)$ approximately
satisfies $Q$ with error at most $\varepsilon + \delta$.
\end{theorem}

n19764.content:
\begin{definition}[Private-coin protocol]
\lean{CommunicationComplexity.PrivateCoin.Protocol}
\label{CommunicationComplexity.PrivateCoin.Protocol}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol}
A \emph{private-coin protocol} with randomness spaces $\Omega_X$ and $\Omega_Y$, input
spaces $X$ and $Y$, and output type $\alpha$ is defined as a deterministic protocol
$\texttt{Deterministic.Protocol}\;(\Omega_X \times X)\;(\Omega_Y \times Y)\;\alpha$.
Alice's message function receives the pair $(\omega_x, x)$ and Bob's receives
$(\omega_y, y)$, so each player's coin flip is invisible to the other.
\end{definition}

n19765.content:
\begin{definition}[Output node]
\lean{CommunicationComplexity.PrivateCoin.Protocol.output}
\label{CommunicationComplexity.PrivateCoin.Protocol.output}
\leanok
\uses{CommunicationComplexity.PrivateCoin.Protocol}
The constant \emph{output node} of a private-coin protocol that immediately returns the
value $a : \alpha$, without any further communication.
\end{definition}

n19766.content:
\begin{definition}[Alice's message node]
\lean{CommunicationComplexity.PrivateCoin.Protocol.alice}
\label{CommunicationComplexity.PrivateCoin.Protocol.alice}
\leanok
\uses{CommunicationComplexity.PrivateCoin.Protocol}
Given a function $f : X \to \Omega_X \to \mathrm{Bool}$ and a continuation
$P : \mathrm{Bool} \to \mathrm{Protocol}\;\Omega_X\;\Omega_Y\;X\;Y\;\alpha$, constructs
the protocol node at which Alice sends the bit $f\,x\,\omega_x$ and execution
continues with $P(\text{bit})$.
\end{definition}

n19767.content:
\begin{definition}[Bob's message node]
\lean{CommunicationComplexity.PrivateCoin.Protocol.bob}
\label{CommunicationComplexity.PrivateCoin.Protocol.bob}
\leanok
\uses{CommunicationComplexity.PrivateCoin.Protocol}
Given a function $f : Y \to \Omega_Y \to \mathrm{Bool}$ and a continuation
$P : \mathrm{Bool} \to \mathrm{Protocol}\;\Omega_X\;\Omega_Y\;X\;Y\;\alpha$, constructs
the protocol node at which Bob sends the bit $f\,y\,\omega_y$ and execution continues
with $P(\text{bit})$.
\end{definition}

n19768.content:
\begin{definition}[Randomized execution]
\lean{CommunicationComplexity.PrivateCoin.Protocol.rrun}
\label{CommunicationComplexity.PrivateCoin.Protocol.rrun}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol.run, CommunicationComplexity.PrivateCoin.Protocol}
$\texttt{rrun}\;p\;x\;y\;\omega_x\;\omega_y$ executes the private-coin protocol $p$ on
inputs $x \in X$ and $y \in Y$ with Alice's private coin $\omega_x \in \Omega_X$ and
Bob's private coin $\omega_y \in \Omega_Y$, returning the output $\alpha$.  It is
defined by $p.\mathrm{run}\,(\omega_x, x)\,(\omega_y, y)$.
\end{definition}

n19769.content:
\begin{theorem}[Randomized execution unfolding]
\lean{CommunicationComplexity.PrivateCoin.Protocol.rrun_eq}
\label{CommunicationComplexity.PrivateCoin.Protocol.rrun_eq}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol.run, CommunicationComplexity.PrivateCoin.Protocol, CommunicationComplexity.PrivateCoin.Protocol.rrun}

For any private-coin protocol $p$ and any inputs $x$, $y$, $\omega_x$, $\omega_y$, we
have $p.\mathrm{rrun}\;x\;y\;\omega_x\;\omega_y = p.\mathrm{run}\,(\omega_x, x)\,(\omega_y, y)$.
This is a definitional equality used as a simp lemma to unfold the randomized
execution to the underlying deterministic run.
\end{theorem}

n19770.content:
\begin{definition}[Approximate satisfaction]
\lean{CommunicationComplexity.PrivateCoin.Protocol.ApproxSatisfies}
\label{CommunicationComplexity.PrivateCoin.Protocol.ApproxSatisfies}
\leanok
\uses{CommunicationComplexity.PrivateCoin.Protocol, CommunicationComplexity.PrivateCoin.Protocol.rrun}
A private-coin protocol $p$ \emph{$\varepsilon$-satisfies} a predicate
$Q : X \to Y \to \alpha \to \mathrm{Prop}$ if for every input pair $(x, y)$,
\[
  \mu\!\left\{\,\omega \in \Omega_X \times \Omega_Y \;\middle|\;
    \neg Q\,x\,y\,(p.\mathrm{rrun}\;x\;y\;\omega_1\;\omega_2)\,\right\} \;\le\; \varepsilon,
\]
where $\mu$ is the product measure on $\Omega_X \times \Omega_Y$.
\end{definition}

n19771.content:
\begin{definition}[Approximate computation]
\lean{CommunicationComplexity.PrivateCoin.Protocol.ApproxComputes}
\label{CommunicationComplexity.PrivateCoin.Protocol.ApproxComputes}
\leanok
\uses{CommunicationComplexity.PrivateCoin.Protocol, CommunicationComplexity.PrivateCoin.Protocol.rrun}
A private-coin protocol $p$ \emph{$\varepsilon$-computes} a function $f : X \to Y \to \alpha$ if
for every input pair $(x, y)$,
\[
  \mu\!\left\{\,\omega \in \Omega_X \times \Omega_Y \;\middle|\;
    p.\mathrm{rrun}\;x\;y\;\omega_1\;\omega_2 \ne f\,x\,y\,\right\} \;\le\; \varepsilon.
\]
This formalises the standard notion of bounded-error private-coin randomized
communication complexity.
\end{definition}

n19772.content:
\begin{theorem}[Approximate computation equals approximate satisfaction]
\lean{CommunicationComplexity.PrivateCoin.Protocol.ApproxComputes_eq_ApproxSatisfies}
\label{CommunicationComplexity.PrivateCoin.Protocol.ApproxComputes_eq_ApproxSatisfies}
\leanok
\uses{CommunicationComplexity.PrivateCoin.Protocol, CommunicationComplexity.PrivateCoin.Protocol.ApproxComputes, CommunicationComplexity.PrivateCoin.Protocol.ApproxSatisfies}

For any private-coin protocol $p$, function $f : X \to Y \to \alpha$, and error bound
$\varepsilon \in \mathbb{R}$,
\[
  p.\mathrm{ApproxComputes}\;f\;\varepsilon
  \;=\;
  p.\mathrm{ApproxSatisfies}\!\left(\lambda\,x\,y\,a,\; a = f\,x\,y\right)\varepsilon.
\]
In other words, $\varepsilon$-computing $f$ is the same as $\varepsilon$-satisfying the
equality predicate $a = f\,x\,y$.
\end{theorem}

n19773.content:
\begin{definition}[Private-coin communication complexity]
\lean{CommunicationComplexity.PrivateCoin.communicationComplexity}
\label{CommunicationComplexity.PrivateCoin.communicationComplexity}
\leanok
\uses{CommunicationComplexity.CoinTape, CommunicationComplexity.Deterministic.Protocol.complexity, CommunicationComplexity.PrivateCoin.Protocol, CommunicationComplexity.PrivateCoin.Protocol.ApproxComputes}
The $\varepsilon$-error private-coin randomized communication complexity of $f : X \to Y \to \alpha$
is the extended natural number
\[
  R_\varepsilon(f)
  \;=\;
  \inf_{\substack{n_X, n_Y \in \mathbb{N},\\ p : \mathrm{Protocol}(\{0,1\}^{n_X}, \{0,1\}^{n_Y}, X, Y, \alpha),\\ p.\mathrm{ApproxComputes}\,f\,\varepsilon}} p.\mathrm{complexity},
\]
i.e.\ the minimum worst-case number of bits exchanged over all private-coin randomized
protocols that compute $f$ with error at most $\varepsilon$ on every input.
\end{definition}

n19774.content:
\begin{theorem}[Upper-bound characterization]
\lean{CommunicationComplexity.PrivateCoin.communicationComplexity_le_iff}
\label{CommunicationComplexity.PrivateCoin.communicationComplexity_le_iff}
\leanok
\uses{CommunicationComplexity.CoinTape, CommunicationComplexity.Deterministic.Protocol.complexity, CommunicationComplexity.Internal.enat_iInf_le_coe_iff, CommunicationComplexity.PrivateCoin.Protocol, CommunicationComplexity.PrivateCoin.Protocol.ApproxComputes, CommunicationComplexity.PrivateCoin.communicationComplexity}

For any $n \in \mathbb{N}$, we have $R_\varepsilon(f) \le n$ if and only if there exist
coin-tape sizes $n_X, n_Y \in \mathbb{N}$ and a protocol
$p : \mathrm{Protocol}(\{0,1\}^{n_X}, \{0,1\}^{n_Y}, X, Y, \alpha)$ such that
$p$ $\varepsilon$-approximately computes $f$ and $p.\mathrm{complexity} \le n$.
\end{theorem}

n19775.content:
\begin{theorem}[Lower-bound characterization]
\lean{CommunicationComplexity.PrivateCoin.le_communicationComplexity_iff}
\label{CommunicationComplexity.PrivateCoin.le_communicationComplexity_iff}
\leanok
\uses{CommunicationComplexity.CoinTape, CommunicationComplexity.Deterministic.Protocol.complexity, CommunicationComplexity.PrivateCoin.Protocol, CommunicationComplexity.PrivateCoin.Protocol.ApproxComputes, CommunicationComplexity.PrivateCoin.communicationComplexity}

For any $n \in \mathbb{N}$, we have $n \le R_\varepsilon(f)$ (in $\mathbb{N}_\infty$) if and only if
every private-coin protocol $p$ over coin tapes of any size that $\varepsilon$-approximately
computes $f$ satisfies $n \le p.\mathrm{complexity}$.
\end{theorem}

n19776.content:
\begin{theorem}[Finite-message characterization]
\lean{CommunicationComplexity.PrivateCoin.communicationComplexity_le_iff_finiteMessage}
\label{CommunicationComplexity.PrivateCoin.communicationComplexity_le_iff_finiteMessage}
\leanok
\uses{CommunicationComplexity.CoinTape, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.ofProtocol_complexity, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.ofProtocol_run, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.toProtocol, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.toProtocol_complexity, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.toProtocol_run, CommunicationComplexity.Deterministic.Protocol.run, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.ApproxComputes, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.ofProtocol, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.rrun, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.toProtocol, CommunicationComplexity.PrivateCoin.communicationComplexity, CommunicationComplexity.PrivateCoin.communicationComplexity_le_iff}

For any $n \in \mathbb{N}$, $R_\varepsilon(f) \le n$ if and only if there exist coin-tape sizes
$n_X, n_Y \in \mathbb{N}$ and a \emph{finite-message} protocol
$p : \mathrm{FiniteMessage.Protocol}(\{0,1\}^{n_X}, \{0,1\}^{n_Y}, X, Y, \alpha)$ such that
$p$ $\varepsilon$-approximately computes $f$ and $p.\mathrm{complexity} \le n$.
This establishes that passing to the finite-message variant does not change the complexity measure.
\end{theorem}

n19777.content:
\begin{theorem}[Monotonicity in error]
\lean{CommunicationComplexity.PrivateCoin.communicationComplexity_mono}
\label{CommunicationComplexity.PrivateCoin.communicationComplexity_mono}
\leanok
\uses{CommunicationComplexity.PrivateCoin.communicationComplexity, CommunicationComplexity.PrivateCoin.communicationComplexity_le_iff}

If $\varepsilon' \le \varepsilon$, then $R_\varepsilon(f) \le R_{\varepsilon'}(f)$.
In other words, the private-coin communication complexity is monotone decreasing in the
error parameter: permitting more error can only reduce (or preserve) the required
communication.
\end{theorem}

n19778.content:
\begin{theorem}[Complexity upper bound from finite-probability protocol]
\lean{CommunicationComplexity.PrivateCoin.communicationComplexity_le_of_finiteMessage}
\label{CommunicationComplexity.PrivateCoin.communicationComplexity_le_of_finiteMessage}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.FiniteProbabilitySpace, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.ApproxComputes, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.ApproxComputes_eq_ApproxSatisfies, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.toCoinTape, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.toCoinTape_approxSatisfies, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.toCoinTape_complexity, CommunicationComplexity.PrivateCoin.communicationComplexity, CommunicationComplexity.PrivateCoin.communicationComplexity_le_iff_finiteMessage}

Let $\Omega_X$ and $\Omega_Y$ be finite probability spaces and let
$p : \mathrm{FiniteMessage.Protocol}(\Omega_X, \Omega_Y, X, Y, \alpha)$ be a finite-message
protocol that $\varepsilon'$-approximately computes $f$.
If $\varepsilon' < \varepsilon$, then $R_\varepsilon(f) \le p.\mathrm{complexity}$.
This is the key reduction step showing that protocols over arbitrary finite probability spaces
witness upper bounds on the private-coin complexity.
\end{theorem}

n19779.content:
\begin{definition}[Output map of a private-coin protocol]
\lean{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.map}
\label{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.map}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.map, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol}
Given a function $g : \alpha \to \beta$ and a private-coin protocol $p$ over randomness
spaces $\Omega_X, \Omega_Y$ with output type $\alpha$, \texttt{map}~$g$~$p$ is the
protocol that runs $p$ and then applies $g$ to its output, yielding a protocol with
output type $\beta$ and the same communication tree.
\end{definition}

n19780.content:
\begin{theorem}[Simulation of mapped protocol]
\lean{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.map_rrun}
\label{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.map_rrun}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.map_run, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.map, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.rrun}

For any inputs $x : X$, $y : Y$ and random coins $\omega_x : \Omega_X$,
$\omega_y : \Omega_Y$, the randomised run of the mapped protocol satisfies
\[
  (p.\mathrm{map}\;g).\mathrm{rrun}\;x\;y\;\omega_x\;\omega_y
  \;=\; g\,(p.\mathrm{rrun}\;x\;y\;\omega_x\;\omega_y).
\]
\end{theorem}

n19781.content:
\begin{theorem}[Complexity of mapped protocol]
\lean{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.map_complexity}
\label{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.map_complexity}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.map_complexity, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.map}

Mapping a function over the output of a protocol does not change its communication
complexity: $(p.\mathrm{map}\;g).\mathrm{complexity} = p.\mathrm{complexity}$.
\end{theorem}

n19782.content:
\begin{definition}[Monadic bind of private-coin protocols]
\lean{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.bind}
\label{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.bind}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.bind, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol}
Given a protocol $p$ with output type $\alpha$ and a family $q : \alpha \to \mathrm{Protocol}\;\Omega_X\;\Omega_Y\;X\;Y\;\beta$,
\texttt{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.bind}~$p$~$q$ is the protocol that runs $p$, observes its output $a$, and then
executes $q\,a$ on the same inputs using the same randomness spaces.
\end{definition}

n19783.content:
\begin{theorem}[Simulation of bound protocol]
\lean{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.bind_rrun}
\label{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.bind_rrun}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.bind_run, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.bind, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.rrun}

For all $x, y, \omega_x, \omega_y$, the randomised run of the bound protocol satisfies
\[
  (p.\mathrm{bind}\;q).\mathrm{rrun}\;x\;y\;\omega_x\;\omega_y
  \;=\; (q\,(p.\mathrm{rrun}\;x\;y\;\omega_x\;\omega_y)).\mathrm{rrun}\;x\;y\;\omega_x\;\omega_y.
\]
\end{theorem}

n19784.content:
\begin{definition}[Randomness reindexing]
\lean{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.comapRandomness}
\label{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.comapRandomness}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol}
Given functions $hX : \Omega_X' \to \Omega_X$ and $hY : \Omega_Y' \to \Omega_Y$,
\texttt{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.comapRandomness}~$hX$~$hY$~$p$ reindexes the randomness spaces of $p$, yielding
a protocol over $\Omega_X'$ and $\Omega_Y'$ that maps coins through $hX$ and $hY$
before passing them to $p$.
\end{definition}

n19785.content:
\begin{theorem}[Simulation after randomness reindexing]
\lean{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.comapRandomness_rrun}
\label{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.comapRandomness_rrun}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap_run, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.comapRandomness, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.rrun}

For all $x, y, \omega_x' : \Omega_X', \omega_y' : \Omega_Y'$,
\[
  (\mathrm{comapRandomness}\;hX\;hY\;p).\mathrm{rrun}\;x\;y\;\omega_x'\;\omega_y'
  \;=\; p.\mathrm{rrun}\;x\;y\;(hX\;\omega_x')\;(hY\;\omega_y').
\]
\end{theorem}

n19786.content:
\begin{theorem}[Complexity after randomness reindexing]
\lean{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.comapRandomness_complexity}
\label{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.comapRandomness_complexity}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.comapRandomness}

Reindexing the randomness spaces of a protocol does not change its communication
complexity: $(\mathrm{comapRandomness}\;hX\;hY\;p).\mathrm{complexity} = p.\mathrm{complexity}$.
\end{theorem}

n19787.content:
\begin{definition}[Product of two private-coin protocols]
\lean{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.prod}
\label{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.prod}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.prod, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol}
Given protocols $p_1$ and $p_2$ with potentially distinct randomness spaces
$(\Omega_{X_1}, \Omega_{Y_1})$ and $(\Omega_{X_2}, \Omega_{Y_2})$,
\texttt{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.prod}~$p_1$~$p_2$ runs them in parallel on the same inputs using independent
randomness drawn from $\Omega_{X_1} \times \Omega_{X_2}$ and $\Omega_{Y_1} \times \Omega_{Y_2}$,
returning the pair of their outputs in $\alpha_1 \times \alpha_2$.
\end{definition}

n19788.content:
\begin{theorem}[Simulation of product protocol]
\lean{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.prod_rrun}
\label{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.prod_rrun}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap_run, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.prod_run, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.prod, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.rrun}

For all $x, y, \omega_x : \Omega_{X_1} \times \Omega_{X_2},
\omega_y : \Omega_{Y_1} \times \Omega_{Y_2}$,
\[
  (\mathrm{prod}\;p_1\;p_2).\mathrm{rrun}\;x\;y\;\omega_x\;\omega_y
  \;=\; (p_1.\mathrm{rrun}\;x\;y\;\omega_x.1\;\omega_y.1,\;
         p_2.\mathrm{rrun}\;x\;y\;\omega_x.2\;\omega_y.2).
\]
\end{theorem}

n19789.content:
\begin{theorem}[Complexity of product protocol]
\lean{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.prod_complexity}
\label{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.prod_complexity}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.prod_complexity, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.prod}

The communication complexity of the product protocol is the sum of the individual
complexities: $(\mathrm{prod}\;p_1\;p_2).\mathrm{complexity} = p_1.\mathrm{complexity} + p_2.\mathrm{complexity}$.
\end{theorem}

n19790.content:
\begin{definition}[$k$-fold product of private-coin protocols]
\lean{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.pi}
\label{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.pi}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.pi, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol}
Given a family of protocols $p : (i : \mathrm{Fin}\,k) \to \mathrm{Protocol}\;(\Omega_{Xf}\,i)\;(\Omega_{Yf}\,i)\;X\;Y\;(\alpha_f\,i)$
with heterogeneous randomness and output types, \texttt{pi}~$p$ runs all $k$ protocols
in parallel on the same inputs using independent randomness from the product spaces
$(\prod_i \Omega_{Xf}\,i,\, \prod_i \Omega_{Yf}\,i)$, returning the tuple of outputs
$(i : \mathrm{Fin}\,k) \to \alpha_f\,i$.
\end{definition}

n19792.content:
\begin{theorem}[Complexity of $k$-fold product]
\lean{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.pi_complexity}
\label{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.pi_complexity}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.pi_complexity, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.pi}

The communication complexity of the $k$-fold product equals the sum of individual
complexities: $(\mathrm{pi}\;p).\mathrm{complexity} = \sum_{i} (p\,i).\mathrm{complexity}$.
\end{theorem}

n19793.content:
\begin{definition}[Bind with fresh independent randomness]
\lean{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.rbind}
\label{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.rbind}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.bind, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol}
Given a protocol $p$ over randomness $(\Omega_X, \Omega_Y)$ and a family
$q : \alpha \to \mathrm{Protocol}\;\Omega_X'\;\Omega_Y'\;X\;Y\;\beta$,
\texttt{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.rbind}~$p$~$q$ runs $p$ with the first component of the coin pair,
obtains its output $a$, then runs $q\,a$ using a fresh, independent second component,
yielding a protocol over $(\Omega_X \times \Omega_X', \Omega_Y \times \Omega_Y')$.
\end{definition}

n19794.content:
\begin{theorem}[Simulation of bind with fresh randomness]
\lean{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.rbind_rrun}
\label{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.rbind_rrun}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.bind_run, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap_run, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.rbind, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.rrun}

For all $x, y, \omega_x : \Omega_X \times \Omega_X', \omega_y : \Omega_Y \times \Omega_Y'$,
\[
  (\mathrm{rbind}\;p\;q).\mathrm{rrun}\;x\;y\;\omega_x\;\omega_y
  \;=\; (q\,(p.\mathrm{rrun}\;x\;y\;\omega_x.1\;\omega_y.1)).\mathrm{rrun}\;x\;y\;\omega_x.2\;\omega_y.2.
\]
\end{theorem}

n19795.content:
\begin{theorem}[Complexity of bind with fresh randomness (constant continuation)]
\lean{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.rbind_complexity_const}
\label{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.rbind_complexity_const}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.bind_complexity_const, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.rbind}

If the continuation $q\,a$ has the same complexity $c$ for every output $a$ of $p$,
then
\[
  (\mathrm{rbind}\;p\;q).\mathrm{complexity} \;=\; p.\mathrm{complexity} + c.
\]
\end{theorem}

n19796.content:
\begin{definition}[Product of private-coin and deterministic protocols]
\lean{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.prodDet}
\label{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.prodDet}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.map, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.bind}
Given a private-coin protocol $p_1$ and a deterministic protocol $p_2$,
\texttt{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.prodDet}~$p_1$~$p_2$ runs both on the same inputs and pairs their outputs
in $\alpha_1 \times \alpha_2$, with $p_2$ contributing no additional randomness.
\end{definition}

n19797.content:
\begin{theorem}[Simulation of private-coin times deterministic]
\lean{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.prodDet_rrun}
\label{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.prodDet_rrun}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.bind_run, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap_run, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.map_run, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.run, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.prodDet, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.rrun}

For all $x, y, \omega_x, \omega_y$,
\[
  (\mathrm{prodDet}\;p_1\;p_2).\mathrm{rrun}\;x\;y\;\omega_x\;\omega_y
  \;=\; (p_1.\mathrm{rrun}\;x\;y\;\omega_x\;\omega_y,\; p_2.\mathrm{run}\;x\;y).
\]
