n19814.content:
\begin{theorem}[Equivalence via finite-message embedding]
\lean{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.ofProtocol_equiv}
\label{CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.ofProtocol_equiv}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.Deterministic.Protocol.complexity, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.ofProtocol, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.ofProtocol_complexity, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.ofProtocol_rrun, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.rrun, CommunicationComplexity.PrivateCoin.Protocol, CommunicationComplexity.PrivateCoin.Protocol.rrun}

For every binary private-coin protocol $p$, there exists a finite-message protocol $P$
such that $P.\texttt{rrun}\,x\,y\,\omega_x\,\omega_y = p.\texttt{rrun}\,x\,y\,\omega_x\,\omega_y$
for all inputs and coins, and $P.\texttt{complexity} = p.\texttt{complexity}$.  The witness
is $P = \texttt{ofProtocol}\,p$.
\end{theorem}

n19815.content:
\begin{definition}[Conversion of a public-coin protocol to CoinTape]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toCoinTape}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toCoinTape}
\leanok
\uses{CommunicationComplexity.CoinTape, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap, CommunicationComplexity.FiniteProbabilitySpace, CommunicationComplexity.Internal.single_coin_approx, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol}
Given a public-coin finite-message protocol $p$ over an arbitrary finite probability
space $\Omega$ and a slack $\delta > 0$, this definition produces a natural number $n$
together with a finite-message protocol over $\mathrm{CoinTape}(n)$ that approximates
$p$. The construction works by pulling back $p$ along a measure-approximating map
$\varphi : \mathrm{CoinTape}(n) \to \Omega$ provided by
\texttt{CommunicationComplexity.Internal.single\_coin\_approx}.
\end{definition}

n19816.content:
\begin{theorem}[CoinTape approximation preserves complexity]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toCoinTape_complexity}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toCoinTape_complexity}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.FiniteProbabilitySpace, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toCoinTape}

For any finite-message protocol $p$ over a finite probability space $\Omega$ and any
$\delta > 0$, the complexity of the \texttt{CoinTape} approximation
$(p.\mathrm{toCoinTape}\;\delta).2$ equals the complexity of the original protocol $p$.
\end{theorem}

n19817.content:
\begin{theorem}[CoinTape approximation preserves ApproxSatisfies]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toCoinTape_approxSatisfies}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toCoinTape_approxSatisfies}
\leanok
\uses{CommunicationComplexity.CoinTape, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap_run, CommunicationComplexity.FiniteProbabilitySpace, CommunicationComplexity.Internal.single_coin_approx, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ApproxSatisfies, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rrun, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toCoinTape}

Let $p$ be a public-coin finite-message protocol over a finite probability space
$\Omega$, let $Q : X \to Y \to \alpha \to \mathrm{Prop}$ be a correctness predicate,
and let $\varepsilon, \delta > 0$. If $p$ approximately satisfies $Q$ with error at
most $\varepsilon$ (i.e.\ $p.\mathrm{ApproxSatisfies}\;Q\;\varepsilon$ holds), then
the \texttt{CoinTape} approximation $(p.\mathrm{toCoinTape}\;\delta).2$ approximately
satisfies $Q$ with error at most $\varepsilon + \delta$.
\end{theorem}

n19818.content:
\begin{definition}[Public-coin protocol]
\lean{CommunicationComplexity.PublicCoin.Protocol}
\label{CommunicationComplexity.PublicCoin.Protocol}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol}
A public-coin protocol over shared randomness $\Omega$, with Alice's private input
in $X$ and Bob's in $Y$ producing an output in $\alpha$, is a deterministic protocol
whose combined input types are $\Omega \times X$ (for Alice) and $\Omega \times Y$
(for Bob).  In other words, both players observe the same random string $\omega \in \Omega$
alongside their private inputs.
\end{definition}

n19819.content:
\begin{definition}[Output node]
\lean{CommunicationComplexity.PublicCoin.Protocol.output}
\label{CommunicationComplexity.PublicCoin.Protocol.output}
\leanok
\uses{CommunicationComplexity.PublicCoin.Protocol}
The leaf node of a public-coin protocol that returns the constant value $a \in \alpha$,
constructed by lifting the corresponding deterministic output node.
\end{definition}

n19820.content:
\begin{definition}[Alice's move]
\lean{CommunicationComplexity.PublicCoin.Protocol.alice}
\label{CommunicationComplexity.PublicCoin.Protocol.alice}
\leanok
\uses{CommunicationComplexity.PublicCoin.Protocol}
Constructs a public-coin protocol node at which Alice sends a single bit: given a
function $f : X \to \Omega \to \mathrm{Bool}$, Alice transmits $f\,x\,\omega$ and
the protocol continues according to $P : \mathrm{Bool} \to \mathrm{Protocol}$.
\end{definition}

n19821.content:
\begin{definition}[Bob's move]
\lean{CommunicationComplexity.PublicCoin.Protocol.bob}
\label{CommunicationComplexity.PublicCoin.Protocol.bob}
\leanok
\uses{CommunicationComplexity.PublicCoin.Protocol}
Constructs a public-coin protocol node at which Bob sends a single bit: given a
function $f : Y \to \Omega \to \mathrm{Bool}$, Bob transmits $f\,y\,\omega$ and
the protocol continues according to $P : \mathrm{Bool} \to \mathrm{Protocol}$.
\end{definition}

n19822.content:
\begin{definition}[Randomized execution]
\lean{CommunicationComplexity.PublicCoin.Protocol.rrun}
\label{CommunicationComplexity.PublicCoin.Protocol.rrun}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol.run, CommunicationComplexity.PublicCoin.Protocol}
Given a public-coin protocol $p$, private inputs $x \in X$, $y \in Y$, and a shared
random string $\omega \in \Omega$, $\texttt{rrun}\,p\,x\,y\,\omega$ executes the
underlying deterministic protocol on the paired inputs $(\omega, x)$ and $(\omega, y)$
and returns the resulting output.
\end{definition}

n19823.content:
\begin{theorem}[\texttt{rrun} unfolding]
\lean{CommunicationComplexity.PublicCoin.Protocol.rrun_eq}
\label{CommunicationComplexity.PublicCoin.Protocol.rrun_eq}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol.run, CommunicationComplexity.PublicCoin.Protocol, CommunicationComplexity.PublicCoin.Protocol.rrun}

For any public-coin protocol $p$, inputs $x$, $y$, and randomness $\omega$,
$p.\texttt{rrun}\,x\,y\,\omega = p.\texttt{run}\,(\omega, x)\,(\omega, y)$.
This is a definitional unfolding used as a \texttt{simp} lemma.
\end{theorem}

n19824.content:
\begin{definition}[$\varepsilon$-satisfies a predicate]
\lean{CommunicationComplexity.PublicCoin.Protocol.ApproxSatisfies}
\label{CommunicationComplexity.PublicCoin.Protocol.ApproxSatisfies}
\leanok
\uses{CommunicationComplexity.PublicCoin.Protocol, CommunicationComplexity.PublicCoin.Protocol.rrun}
A public-coin protocol $p$ \emph{$\varepsilon$-satisfies} a predicate
$Q : X \to Y \to \alpha \to \mathrm{Prop}$ if for every input pair $(x, y)$,
\[
  \mathrm{vol}\bigl\{\omega \in \Omega \mid \neg\, Q\,x\,y\,(p.\texttt{rrun}\,x\,y\,\omega)\bigr\} \;\le\; \varepsilon.
\]
\end{definition}

n19825.content:
\begin{definition}[$\varepsilon$-computes a function]
\lean{CommunicationComplexity.PublicCoin.Protocol.ApproxComputes}
\label{CommunicationComplexity.PublicCoin.Protocol.ApproxComputes}
\leanok
\uses{CommunicationComplexity.PublicCoin.Protocol, CommunicationComplexity.PublicCoin.Protocol.rrun}
A public-coin protocol $p$ \emph{$\varepsilon$-computes} a function
$f : X \to Y \to \alpha$ if for every input pair $(x, y)$,
\[
  \mathrm{vol}\bigl\{\omega \in \Omega \mid p.\texttt{rrun}\,x\,y\,\omega \ne f\,x\,y\bigr\} \;\le\; \varepsilon.
\]
Here the volume is taken with respect to the measure on $\Omega$ given by the
\texttt{MeasureSpace} instance.
\end{definition}

n19826.content:
\begin{theorem}[\texttt{ApproxComputes} equals \texttt{ApproxSatisfies} at equality]
\lean{CommunicationComplexity.PublicCoin.Protocol.ApproxComputes_eq_ApproxSatisfies}
\label{CommunicationComplexity.PublicCoin.Protocol.ApproxComputes_eq_ApproxSatisfies}
\leanok
\uses{CommunicationComplexity.PublicCoin.Protocol, CommunicationComplexity.PublicCoin.Protocol.ApproxComputes, CommunicationComplexity.PublicCoin.Protocol.ApproxSatisfies}

For any public-coin protocol $p$, function $f : X \to Y \to \alpha$, and
$\varepsilon \in \mathbb{R}$,
\[
  p.\texttt{ApproxComputes}\,f\,\varepsilon
  \;=\;
  p.\texttt{ApproxSatisfies}\,(\lambda\,x\,y\,a.\; a = f\,x\,y)\,\varepsilon.
\]
That is, $\varepsilon$-computing $f$ is exactly $\varepsilon$-satisfying the
pointwise equality predicate $a = f\,x\,y$.
\end{theorem}

n19827.content:
\begin{definition}[Public-coin communication complexity]
\lean{CommunicationComplexity.PublicCoin.communicationComplexity}
\label{CommunicationComplexity.PublicCoin.communicationComplexity}
\leanok
\uses{CommunicationComplexity.CoinTape, CommunicationComplexity.Deterministic.Protocol.complexity, CommunicationComplexity.PublicCoin.Protocol, CommunicationComplexity.PublicCoin.Protocol.ApproxComputes}
The $\varepsilon$-error public-coin randomized communication complexity of
$f : X \to Y \to \alpha$ is defined as
\[
  \mathrm{R}^{\mathrm{pub}}_\varepsilon(f)
  \;=\;
  \inf_{\substack{n \in \mathbb{N},\; p \text{ a protocol on } \mathrm{CoinTape}(n) \\ p \text{ $\varepsilon$-approximates } f}}
  p.\mathrm{complexity},
\]
the infimum (in $\mathbb{N}_\infty$) of the worst-case bit complexity over all
public-coin randomized protocols that compute $f$ with error at most $\varepsilon$ on
every input.
\end{definition}

n19828.content:
\begin{theorem}[Characterization of complexity bound]
\lean{CommunicationComplexity.PublicCoin.communicationComplexity_le_iff}
\label{CommunicationComplexity.PublicCoin.communicationComplexity_le_iff}
\leanok
\uses{CommunicationComplexity.CoinTape, CommunicationComplexity.Deterministic.Protocol.complexity, CommunicationComplexity.Internal.enat_iInf_le_coe_iff, CommunicationComplexity.PublicCoin.Protocol, CommunicationComplexity.PublicCoin.Protocol.ApproxComputes, CommunicationComplexity.PublicCoin.communicationComplexity}

For $f : X \to Y \to \alpha$, $\varepsilon \in \mathbb{R}$, and $m \in \mathbb{N}$,
we have $\mathrm{R}^{\mathrm{pub}}_\varepsilon(f) \le m$ if and only if there exist
$n \in \mathbb{N}$ and a public-coin protocol $p$ on $\mathrm{CoinTape}(n)$ such that
$p$ $\varepsilon$-approximates $f$ and $p.\mathrm{complexity} \le m$.
\end{theorem}

n19829.content:
\begin{theorem}[Lower bound characterization]
\lean{CommunicationComplexity.PublicCoin.le_communicationComplexity_iff}
\label{CommunicationComplexity.PublicCoin.le_communicationComplexity_iff}
\leanok
\uses{CommunicationComplexity.CoinTape, CommunicationComplexity.Deterministic.Protocol.complexity, CommunicationComplexity.PublicCoin.Protocol, CommunicationComplexity.PublicCoin.Protocol.ApproxComputes, CommunicationComplexity.PublicCoin.communicationComplexity}

For $f : X \to Y \to \alpha$, $\varepsilon \in \mathbb{R}$, and $m \in \mathbb{N}$,
we have $m \le \mathrm{R}^{\mathrm{pub}}_\varepsilon(f)$ if and only if every
public-coin protocol $p$ on any $\mathrm{CoinTape}(n)$ that $\varepsilon$-approximates
$f$ satisfies $m \le p.\mathrm{complexity}$.
\end{theorem}

n19830.content:
\begin{theorem}[Finite-message characterization of complexity bound]
\lean{CommunicationComplexity.PublicCoin.communicationComplexity_le_iff_finiteMessage}
\label{CommunicationComplexity.PublicCoin.communicationComplexity_le_iff_finiteMessage}
\leanok
\uses{CommunicationComplexity.CoinTape, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.ofProtocol_complexity, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.ofProtocol_run, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.toProtocol, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.toProtocol_complexity, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.toProtocol_run, CommunicationComplexity.Deterministic.Protocol.run, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ApproxComputes, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ofProtocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rrun, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toProtocol, CommunicationComplexity.PublicCoin.communicationComplexity, CommunicationComplexity.PublicCoin.communicationComplexity_le_iff}

For $f : X \to Y \to \alpha$, $\varepsilon \in \mathbb{R}$, and $m \in \mathbb{N}$,
we have $\mathrm{R}^{\mathrm{pub}}_\varepsilon(f) \le m$ if and only if there exist
$n \in \mathbb{N}$ and a finite-message public-coin protocol $p$ on
$\mathrm{CoinTape}(n)$ such that $p$ $\varepsilon$-approximates $f$ and
$p.\mathrm{complexity} \le m$. This shows that the binary-message and
finite-message formulations of public-coin complexity coincide.
\end{theorem}

n19831.content:
\begin{theorem}[Monotonicity in error]
\lean{CommunicationComplexity.PublicCoin.communicationComplexity_mono}
\label{CommunicationComplexity.PublicCoin.communicationComplexity_mono}
\leanok
\uses{CommunicationComplexity.PublicCoin.communicationComplexity, CommunicationComplexity.PublicCoin.communicationComplexity_le_iff}

Public-coin communication complexity is monotone in the error parameter: if
$\varepsilon' \le \varepsilon$, then
$\mathrm{R}^{\mathrm{pub}}_\varepsilon(f) \le \mathrm{R}^{\mathrm{pub}}_{\varepsilon'}(f)$.
Allowing more error can only make computation easier.
\end{theorem}

n19832.content:
\begin{theorem}[Upper bound from finite-message protocol on general probability space]
\lean{CommunicationComplexity.PublicCoin.communicationComplexity_le_of_finiteMessage}
\label{CommunicationComplexity.PublicCoin.communicationComplexity_le_of_finiteMessage}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.FiniteProbabilitySpace, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ApproxComputes, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ApproxComputes_eq_ApproxSatisfies, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toCoinTape, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toCoinTape_approxSatisfies, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toCoinTape_complexity, CommunicationComplexity.PublicCoin.communicationComplexity, CommunicationComplexity.PublicCoin.communicationComplexity_le_iff_finiteMessage}

Let $\Omega$ be a finite probability space, $f : X \to Y \to \alpha$, and $\varepsilon' < \varepsilon$.
If a finite-message public-coin protocol $p$ over $\Omega$ computes $f$ with error at most
$\varepsilon'$, then $\mathrm{R}^{\mathrm{pub}}_\varepsilon(f) \le p.\mathrm{complexity}$.
This allows one to transfer upper bounds from protocols over arbitrary finite probability
spaces to the coin-tape formulation.
\end{theorem}

n19833.content:
\begin{definition}[Map over protocol output]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.map}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.map}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.map, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol}
Given a function $g : \alpha \to \beta$ and a public-coin protocol
$p : \mathrm{Protocol}\;\Omega\;X\;Y\;\alpha$, the protocol $p.\mathrm{map}\;g$
is a $\mathrm{Protocol}\;\Omega\;X\;Y\;\beta$ that applies $g$ to the output of $p$
after every run, without changing the communication structure.
\end{definition}

n19834.content:
\begin{theorem}[Map commutes with running]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.map_rrun}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.map_rrun}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.map_run, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.map, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rrun}

For any $g : \alpha \to \beta$, protocol $p$, inputs $x \in X$, $y \in Y$, and randomness
$\omega \in \Omega$, running the mapped protocol satisfies
$(p.\mathrm{map}\;g).\mathrm{rrun}\;x\;y\;\omega = g\,(p.\mathrm{rrun}\;x\;y\;\omega)$.
\end{theorem}

n19835.content:
\begin{theorem}[Map preserves complexity]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.map_complexity}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.map_complexity}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.map_complexity, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.map}

For any $g : \alpha \to \beta$ and protocol $p$, the communication complexity of
$p.\mathrm{map}\;g$ equals that of $p$:
$(p.\mathrm{map}\;g).\mathrm{complexity} = p.\mathrm{complexity}$.
\end{theorem}

n19836.content:
\begin{definition}[Bind on protocols]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.bind}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.bind}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.bind, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol}
Given a protocol $p : \mathrm{Protocol}\;\Omega\;X\;Y\;\alpha$ and a family
$q : \alpha \to \mathrm{Protocol}\;\Omega\;X\;Y\;\beta$, the protocol $p.\mathrm{bind}\;q$
replaces each output $a$ of $p$ with the protocol $q\;a$, both sharing the same randomness
$\Omega$.
\end{definition}

n19837.content:
\begin{theorem}[Bind commutes with running]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.bind_rrun}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.bind_rrun}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.bind_run, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.bind, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rrun}

For any $p$, $q$, inputs $x \in X$, $y \in Y$, and shared randomness $\omega \in \Omega$,
running the bound protocol satisfies
$(p.\mathrm{bind}\;q).\mathrm{rrun}\;x\;y\;\omega =
  (q\,(p.\mathrm{rrun}\;x\;y\;\omega)).\mathrm{rrun}\;x\;y\;\omega$.
\end{theorem}

n19838.content:
\begin{definition}[Randomness reindexing]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.comapRandomness}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.comapRandomness}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol}
Given $h : \Omega' \to \Omega$ and a protocol $p : \mathrm{Protocol}\;\Omega\;X\;Y\;\alpha$,
the protocol $\mathrm{comapRandomness}\;h\;p$ is a
$\mathrm{Protocol}\;\Omega'\;X\;Y\;\alpha$ that runs $p$ after pre-composing the shared
randomness with $h$.
\end{definition}

n19839.content:
\begin{theorem}[Randomness reindexing commutes with running]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.comapRandomness_rrun}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.comapRandomness_rrun}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap_run, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.comapRandomness, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rrun}

For any $h : \Omega' \to \Omega$, protocol $p$, inputs $x \in X$, $y \in Y$, and
$\omega \in \Omega'$, running the reindexed protocol satisfies
$(\mathrm{comapRandomness}\;h\;p).\mathrm{rrun}\;x\;y\;\omega =
  p.\mathrm{rrun}\;x\;y\;(h\;\omega)$.
\end{theorem}

n19840.content:
\begin{theorem}[Randomness reindexing preserves complexity]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.comapRandomness_complexity}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.comapRandomness_complexity}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.comapRandomness}

For any $h : \Omega' \to \Omega$ and protocol $p$, reindexing the randomness does not
change the complexity:
$(\mathrm{comapRandomness}\;h\;p).\mathrm{complexity} = p.\mathrm{complexity}$.
\end{theorem}

n19841.content:
\begin{definition}[Product of two protocols]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.prod}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.prod}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.prod, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol}
Given protocols $p_1 : \mathrm{Protocol}\;\Omega_1\;X\;Y\;\alpha_1$ and
$p_2 : \mathrm{Protocol}\;\Omega_2\;X\;Y\;\alpha_2$, the product protocol
$\mathrm{prod}\;p_1\;p_2$ is a $\mathrm{Protocol}\;(\Omega_1 \times \Omega_2)\;X\;Y\;(\alpha_1 \times \alpha_2)$
that runs $p_1$ and $p_2$ independently on the same inputs, using the first and second
components of the shared randomness pair respectively.
\end{definition}

n19842.content:
\begin{theorem}[Product runs component-wise]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.prod_rrun}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.prod_rrun}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap_run, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.prod_run, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.prod, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rrun}

For protocols $p_1$, $p_2$, inputs $x \in X$, $y \in Y$, and randomness
$\omega \in \Omega_1 \times \Omega_2$, running the product satisfies
$(\mathrm{prod}\;p_1\;p_2).\mathrm{rrun}\;x\;y\;\omega =
  (p_1.\mathrm{rrun}\;x\;y\;\omega_1,\; p_2.\mathrm{rrun}\;x\;y\;\omega_2)$.
\end{theorem}

n19843.content:
\begin{theorem}[Product complexity is the sum]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.prod_complexity}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.prod_complexity}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.prod_complexity, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.prod}

The communication complexity of $\mathrm{prod}\;p_1\;p_2$ equals the sum of the
complexities of $p_1$ and $p_2$:
$(\mathrm{prod}\;p_1\;p_2).\mathrm{complexity} =
  p_1.\mathrm{complexity} + p_2.\mathrm{complexity}$.
\end{theorem}

n19844.content:
\begin{definition}[$k$-fold product of protocols]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.pi}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.pi}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.pi, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol}
Given a family of protocols $p : (i : \mathrm{Fin}\;k) \to \mathrm{Protocol}\;(\Omega_i)\;X\;Y\;(\alpha_i)$
with heterogeneous randomness and output types, the $\pi$-protocol
$\mathrm{pi}\;p$ is a $\mathrm{Protocol}\;(\prod_i \Omega_i)\;X\;Y\;(\prod_i \alpha_i)$
that runs each $p_i$ independently using its own component of the shared randomness tuple.
\end{definition}

n19845.content:
\begin{theorem}[$k$-fold product runs component-wise]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.pi_rrun}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.pi_rrun}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap_run, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.pi_run, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.pi, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rrun}

For a family $p$, inputs $x \in X$, $y \in Y$, and randomness tuple
$\omega : (i : \mathrm{Fin}\;k) \to \Omega_i$, running the $\pi$-protocol satisfies
$(\mathrm{pi}\;p).\mathrm{rrun}\;x\;y\;\omega = \lambda i,\; (p\;i).\mathrm{rrun}\;x\;y\;(\omega\;i)$.
\end{theorem}

n19846.content:
\begin{theorem}[$k$-fold product complexity is the sum]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.pi_complexity}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.pi_complexity}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.pi_complexity, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.pi}

The complexity of $\mathrm{pi}\;p$ equals the sum of the complexities of all components:
$(\mathrm{pi}\;p).\mathrm{complexity} = \sum_{i} (p\;i).\mathrm{complexity}$.
\end{theorem}

n19847.content:
\begin{definition}[Bind with fresh randomness]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rbind}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rbind}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.bind, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol}
Given $p : \mathrm{Protocol}\;\Omega\;X\;Y\;\alpha$ and
$q : \alpha \to \mathrm{Protocol}\;\Omega'\;X\;Y\;\beta$, the protocol
$\mathrm{rbind}\;p\;q$ is a $\mathrm{Protocol}\;(\Omega \times \Omega')\;X\;Y\;\beta$
that first runs $p$ using the $\Omega$-component of the shared randomness, then runs
$q$ on the result using the independent $\Omega'$-component.
\end{definition}

n19848.content:
\begin{theorem}[Fresh-randomness bind commutes with running]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rbind_rrun}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rbind_rrun}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.bind_run, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap_run, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rbind, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rrun}

For any $p$, $q$, inputs $x \in X$, $y \in Y$, and randomness pair
$\omega \in \Omega \times \Omega'$, running the fresh-randomness bound protocol satisfies
$(\mathrm{rbind}\;p\;q).\mathrm{rrun}\;x\;y\;\omega =
  (q\,(p.\mathrm{rrun}\;x\;y\;\omega_1)).\mathrm{rrun}\;x\;y\;\omega_2$.
\end{theorem}

n19849.content:
\begin{theorem}[Fresh-randomness bind complexity with constant continuation]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rbind_complexity_const}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rbind_complexity_const}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.bind_complexity_const, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rbind}

If every branch $q\;a$ has the same complexity $c \in \mathbb{N}$, then
$(\mathrm{rbind}\;p\;q).\mathrm{complexity} = p.\mathrm{complexity} + c$.
\end{theorem}

n19850.content:
\begin{definition}[Product with a deterministic protocol]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.prodDet}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.prodDet}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.map, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.bind}
Given a public-coin protocol $p_1 : \mathrm{Protocol}\;\Omega\;X\;Y\;\alpha_1$ and a
deterministic protocol $p_2 : \mathrm{Deterministic.FiniteMessage.Protocol}\;X\;Y\;\alpha_2$,
the protocol $\mathrm{prodDet}\;p_1\;p_2$ is a $\mathrm{Protocol}\;\Omega\;X\;Y\;(\alpha_1 \times \alpha_2)$
that runs both protocols on the same inputs and pairs their outputs,
reusing the same randomness $\Omega$.
\end{definition}

n19851.content:
\begin{theorem}[Mixed product runs component-wise]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.prodDet_rrun}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.prodDet_rrun}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.bind_run, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap_run, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.map_run, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.run, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.prodDet, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rrun}

For any $p_1$, $p_2$, inputs $x \in X$, $y \in Y$, and randomness $\omega \in \Omega$,
running the mixed product satisfies
$(\mathrm{prodDet}\;p_1\;p_2).\mathrm{rrun}\;x\;y\;\omega =
  (p_1.\mathrm{rrun}\;x\;y\;\omega,\; p_2.\mathrm{run}\;x\;y)$.
\end{theorem}

n19852.content:
\begin{theorem}[Mixed product complexity is the sum]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.prodDet_complexity}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.prodDet_complexity}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.bind_complexity_const, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.prodDet}

The complexity of $\mathrm{prodDet}\;p_1\;p_2$ equals the sum of the complexity of $p_1$
and the complexity of $p_2$:
$(\mathrm{prodDet}\;p_1\;p_2).\mathrm{complexity} =
  p_1.\mathrm{complexity} + p_2.\mathrm{complexity}$.
\end{theorem}

n19853.content:
\begin{definition}[Public-coin finite-message protocol]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol}
A public-coin finite-message protocol over shared-randomness space $\Omega$, private input
sets $X$ and $Y$, and output type $\alpha$ is a deterministic finite-message protocol in
which Alice's effective input is $\Omega \times X$ and Bob's effective input is
$\Omega \times Y$.
\end{definition}

n19854.content:
\begin{definition}[Output node]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.output}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.output}
\leanok
\uses{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol}
The terminal (output) node of a public-coin finite-message protocol returning the
constant value $a : \alpha$.
\end{definition}

n19855.content:
\begin{definition}[Alice's send step]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.alice}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.alice}
\leanok
\uses{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol}
Given a message function $f : X \to \Omega \to \beta$ and a continuation
$P : \beta \to \mathrm{Protocol}$, this constructs the protocol node in which Alice sends
a $\beta$-valued message determined by her private input $x$ and the shared randomness
$\omega$, then continues with $P$.
\end{definition}

n19856.content:
\begin{definition}[Bob's send step]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.bob}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.bob}
\leanok
\uses{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol}
Given a message function $f : Y \to \Omega \to \beta$ and a continuation
$P : \beta \to \mathrm{Protocol}$, this constructs the protocol node in which Bob sends
a $\beta$-valued message determined by his private input $y$ and the shared randomness
$\omega$, then continues with $P$.
\end{definition}

n19857.content:
\begin{definition}[Randomized execution]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rrun}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rrun}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.run, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol}
$\mathrm{rrun}(p, x, y, \omega)$ executes the protocol $p$ on private inputs $x$ and $y$
with shared randomness $\omega$, defined as $p.\mathrm{run}(\omega, x)\,(\omega, y)$.
\end{definition}

n19858.content:
\begin{theorem}[Randomized run equals underlying run]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rrun_eq}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rrun_eq}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.run, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rrun}

For any protocol $p$, inputs $x$, $y$, and shared randomness $\omega$,
$p.\mathrm{rrun}\,x\,y\,\omega = p.\mathrm{run}\,(\omega, x)\,(\omega, y)$.
This is a definitional unfolding used as a simp lemma.
\end{theorem}

n19859.content:
\begin{definition}[Approximate satisfaction of a predicate]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ApproxSatisfies}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ApproxSatisfies}
\leanok
\uses{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rrun}
A protocol $p$ $\varepsilon$-satisfies a predicate $Q : X \to Y \to \alpha \to \mathrm{Prop}$
if for every input pair $(x, y)$,
\[
  \Pr_{\omega}\bigl[\neg Q\,x\,y\,(p.\mathrm{rrun}\,x\,y\,\omega)\bigr] \;\le\; \varepsilon.
\]
\end{definition}

n19860.content:
\begin{definition}[Approximate computation of a function]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ApproxComputes}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ApproxComputes}
\leanok
\uses{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rrun}
A protocol $p$ $\varepsilon$-computes a function $f : X \to Y \to \alpha$ if for every
input pair $(x, y)$,
\[
  \Pr_{\omega}\bigl[p.\mathrm{rrun}\,x\,y\,\omega \ne f\,x\,y\bigr] \;\le\; \varepsilon.
\]
\end{definition}

n19861.content:
\begin{theorem}[Approximate computation equals approximate satisfaction]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ApproxComputes_eq_ApproxSatisfies}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ApproxComputes_eq_ApproxSatisfies}
\leanok
\uses{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ApproxComputes, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ApproxSatisfies}

For any protocol $p$, function $f$, and error bound $\varepsilon$,
$p.\mathrm{ApproxComputes}\,f\,\varepsilon = p.\mathrm{ApproxSatisfies}\,(\lambda\,x\,y\,a,\; a = f\,x\,y)\,\varepsilon$.
Thus approximate computation is a special case of approximate predicate satisfaction.
\end{theorem}

n19862.content:
\begin{definition}[Conversion to binary public-coin protocol]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toProtocol}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toProtocol}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.toProtocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.Protocol}
Converts a public-coin finite-message protocol to a binary public-coin protocol by
delegating to \texttt{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.toProtocol}.
\end{definition}

n19863.content:
\begin{theorem}[Conversion preserves run behavior]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toProtocol_rrun}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toProtocol_rrun}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.toProtocol_run, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rrun, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toProtocol, CommunicationComplexity.PublicCoin.Protocol.rrun}

For any protocol $p$, inputs $x$, $y$, and shared randomness $\omega$,
$(p.\mathrm{toProtocol}).\mathrm{rrun}\,x\,y\,\omega = p.\mathrm{rrun}\,x\,y\,\omega$.
\end{theorem}

n19864.content:
\begin{theorem}[Conversion preserves complexity]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toProtocol_complexity}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toProtocol_complexity}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.toProtocol_complexity, CommunicationComplexity.Deterministic.Protocol.complexity, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toProtocol}

For any protocol $p$, $(p.\mathrm{toProtocol}).\mathrm{complexity} = p.\mathrm{complexity}$.
\end{theorem}

n19865.content:
\begin{definition}[Embedding of binary public-coin protocol]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ofProtocol}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ofProtocol}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.ofProtocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.Protocol}
Embeds a binary public-coin protocol into a finite-message protocol by delegating to
\texttt{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.ofProtocol}.
\end{definition}

n19866.content:
\begin{theorem}[Embedding preserves run behavior]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ofProtocol_rrun}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ofProtocol_rrun}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.ofProtocol_run, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ofProtocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rrun, CommunicationComplexity.PublicCoin.Protocol, CommunicationComplexity.PublicCoin.Protocol.rrun}

For any binary public-coin protocol $p$, inputs $x$, $y$, and shared randomness $\omega$,
$(\mathrm{ofProtocol}\,p).\mathrm{rrun}\,x\,y\,\omega = p.\mathrm{rrun}\,x\,y\,\omega$.
\end{theorem}

n19867.content:
\begin{theorem}[Embedding preserves complexity]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ofProtocol_complexity}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ofProtocol_complexity}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.ofProtocol_complexity, CommunicationComplexity.Deterministic.Protocol.complexity, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ofProtocol, CommunicationComplexity.PublicCoin.Protocol}

For any binary public-coin protocol $p$,
$(\mathrm{ofProtocol}\,p).\mathrm{complexity} = p.\mathrm{complexity}$.
\end{theorem}

n19868.content:
\begin{theorem}[Finite-message equivalence of binary public-coin protocols]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ofProtocol_equiv}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ofProtocol_equiv}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.Deterministic.Protocol.complexity, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ofProtocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ofProtocol_complexity, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ofProtocol_rrun, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rrun, CommunicationComplexity.PublicCoin.Protocol, CommunicationComplexity.PublicCoin.Protocol.rrun}

For any binary public-coin protocol $p$, there exists a finite-message protocol $P$ such
that $P.\mathrm{rrun}\,x\,y\,\omega = p.\mathrm{rrun}\,x\,y\,\omega$ for all $x$, $y$,
$\omega$, and $P.\mathrm{complexity} = p.\mathrm{complexity}$.
\end{theorem}

n19869.content:
\begin{definition}[One-way public-coin protocol]
\lean{CommunicationComplexity.PublicCoin.OneWay.Protocol}
\label{CommunicationComplexity.PublicCoin.OneWay.Protocol}
\leanok
\uses{CommunicationComplexity.Deterministic.OneWay.Protocol}
A one-way public-coin protocol over shared randomness type $\Omega$ and
input types $X$, $Y$ with output type $\alpha$ is defined as a deterministic
one-way protocol whose Alice-input is $\Omega \times X$ and whose Bob-input is
$\Omega \times Y$.  The shared randomness $\omega \in \Omega$ is thus treated as
a component of both players' inputs.
\end{definition}

n19870.content:
\begin{definition}[Protocol execution with shared randomness]
\lean{CommunicationComplexity.PublicCoin.OneWay.Protocol.rrun}
\label{CommunicationComplexity.PublicCoin.OneWay.Protocol.rrun}
\leanok
\uses{CommunicationComplexity.PublicCoin.OneWay.Protocol}
Given a protocol $p$, inputs $x \in X$, $y \in Y$, and a shared random string
$\omega \in \Omega$, the execution $\mathrm{rrun}(p, x, y, \omega)$ runs $p$ on
the joint inputs $(\omega, x)$ for Alice and $(\omega, y)$ for Bob, returning
the decoded output $p.\mathrm{decode}(p.\mathrm{send}(\omega, x),\,(\omega, y))$.
\end{definition}

n19871.content:
\begin{definition}[$\varepsilon$-approximate computation]
\lean{CommunicationComplexity.PublicCoin.OneWay.Protocol.ApproxComputes}
\label{CommunicationComplexity.PublicCoin.OneWay.Protocol.ApproxComputes}
\leanok
\uses{CommunicationComplexity.PublicCoin.OneWay.Protocol, CommunicationComplexity.PublicCoin.OneWay.Protocol.rrun}
A protocol $p$ $\varepsilon$-computes a function $f : X \to Y \to \alpha$ if
for every input pair $(x, y)$ the measure of the set of shared strings on which
$p$ errs is at most $\varepsilon$:
\[
  \forall x,\, y,\quad
  \mu\bigl(\{\omega \mid p.\mathrm{rrun}(x,y,\omega) \ne f(x,y)\}\bigr) \;\le\; \varepsilon.
\]
\end{definition}

n19872.content:
\begin{definition}[$\varepsilon$-error one-way public-coin communication complexity]
\lean{CommunicationComplexity.PublicCoin.OneWay.communicationComplexity}
\label{CommunicationComplexity.PublicCoin.OneWay.communicationComplexity}
\leanok
\uses{CommunicationComplexity.CoinTape, CommunicationComplexity.Deterministic.OneWay.Protocol.cost, CommunicationComplexity.PublicCoin.OneWay.Protocol, CommunicationComplexity.PublicCoin.OneWay.Protocol.ApproxComputes}
The $\varepsilon$-error one-way public-coin communication complexity of
$f : X \to Y \to \alpha$ is the infimum (in $\mathbb{N}_\infty$) of the
one-way message cost $p.\mathrm{cost}$ over all $n \in \mathbb{N}$ and all
protocols $p$ over the coin-tape space $\mathrm{CoinTape}(n)$ that
$\varepsilon$-compute $f$.
\end{definition}

n19873.content:
\begin{theorem}[Upper bound characterisation]
\lean{CommunicationComplexity.PublicCoin.OneWay.communicationComplexity_le_iff}
\label{CommunicationComplexity.PublicCoin.OneWay.communicationComplexity_le_iff}
\leanok
\uses{CommunicationComplexity.CoinTape, CommunicationComplexity.Deterministic.OneWay.Protocol.cost, CommunicationComplexity.Internal.enat_iInf_le_coe_iff, CommunicationComplexity.PublicCoin.OneWay.Protocol, CommunicationComplexity.PublicCoin.OneWay.Protocol.ApproxComputes, CommunicationComplexity.PublicCoin.OneWay.communicationComplexity}

For $f : X \to Y \to \alpha$, $\varepsilon \in \mathbb{R}$, and $m \in \mathbb{N}$,
the complexity satisfies $\mathrm{CC}(f,\varepsilon) \le m$ if and only if there
exist $n \in \mathbb{N}$ and a protocol $p$ over $\mathrm{CoinTape}(n)$ such that
$p$ $\varepsilon$-computes $f$ and $p.\mathrm{cost} \le m$.
\end{theorem}

n19874.content:
\begin{theorem}[Lower bound characterisation]
\lean{CommunicationComplexity.PublicCoin.OneWay.le_communicationComplexity_iff}
\label{CommunicationComplexity.PublicCoin.OneWay.le_communicationComplexity_iff}
\leanok
\uses{CommunicationComplexity.CoinTape, CommunicationComplexity.Deterministic.OneWay.Protocol.cost, CommunicationComplexity.PublicCoin.OneWay.Protocol, CommunicationComplexity.PublicCoin.OneWay.Protocol.ApproxComputes, CommunicationComplexity.PublicCoin.OneWay.communicationComplexity}

For $f : X \to Y \to \alpha$, $\varepsilon \in \mathbb{R}$, and $m \in \mathbb{N}$,
the complexity satisfies $m \le \mathrm{CC}(f,\varepsilon)$ (as extended naturals)
if and only if every protocol $p$ over any $\mathrm{CoinTape}(n)$ that
$\varepsilon$-computes $f$ has $p.\mathrm{cost} \ge m$.
\end{theorem}

n19875.content:
\begin{theorem}[Monotonicity in error]
\lean{CommunicationComplexity.PublicCoin.OneWay.communicationComplexity_mono}
\label{CommunicationComplexity.PublicCoin.OneWay.communicationComplexity_mono}
\leanok
\uses{CommunicationComplexity.PublicCoin.OneWay.communicationComplexity, CommunicationComplexity.PublicCoin.OneWay.communicationComplexity_le_iff}

The $\varepsilon$-error one-way public-coin communication complexity of $f$ is
monotone non-increasing in $\varepsilon$: if $\varepsilon' \le \varepsilon$ then
$\mathrm{CC}(f,\varepsilon) \le \mathrm{CC}(f,\varepsilon')$.  Intuitively, a
stricter error budget can only demand a larger protocol cost.
\end{theorem}

n19876.content:
\begin{definition}[Schnorr transcript]
\lean{Schnorr.Transcript}
\label{Schnorr.Transcript}
\leanok
A Schnorr transcript is a triple $(a, c, s) \in G \times \mathbb{Z}_q \times
\mathbb{Z}_q$, where $a$ is the prover's commitment (an element of the group
$G$), $c \in \mathbb{Z}_q$ is the verifier's challenge, and $s \in \mathbb{Z}_q$
is the prover's response.
\end{definition}

n19877.content:
\begin{definition}[Prover commitment]
\lean{Schnorr.commit}
\label{Schnorr.commit}
\leanok
Given randomness $r \in \mathbb{Z}_q$ and a generator $g \in G$, the commitment
is $a := g^{r}$, where the exponent is taken via the canonical lift
$r.\mathrm{val} \in \mathbb{N}$.
\end{definition}

n19878.content:
\begin{definition}[Prover response]
\lean{Schnorr.respond}
\label{Schnorr.respond}
\leanok
Given witness $w$, randomness $r$, and challenge $c$ in $\mathbb{Z}_q$, the
response is $s := r + c \cdot w \in \mathbb{Z}_q$.
\end{definition}

n19879.content:
\begin{definition}[Verifier predicate]
\lean{Schnorr.Verify}
\label{Schnorr.Verify}
\leanok
The verifier accepts a transcript $(a, c, s)$ with respect to public key
$\mathit{pk} \in G$ when $g^s = a \cdot \mathit{pk}^{c}$, where the
exponents are taken via the canonical lifts to $\mathbb{N}$.
\end{definition}

n19880.content:
\begin{definition}[Honest transcript]
\lean{Schnorr.honest}
\label{Schnorr.honest}
\leanok
\uses{Schnorr.Transcript, Schnorr.commit, Schnorr.respond}
The honest prover's full transcript for witness $w$, randomness $r$, and
challenge $c$ is the triple $(\mathrm{commit}(g, r),\; c,\; \mathrm{respond}(w, r, c))$,
i.e.\ $(g^r,\, c,\, r + c \cdot w)$.
\end{definition}

n19881.content:
\begin{definition}[Simulator transcript]
\lean{Schnorr.simulate}
\label{Schnorr.simulate}
\leanok
\uses{Schnorr.Transcript}
The zero-knowledge simulator, given public key $\mathit{pk}$, challenge $c$,
and a fresh response $s$, outputs the transcript
$(g^s \cdot (\mathit{pk}^c)^{-1},\; c,\; s)$.
The commitment is chosen so that the transcript is accepting without using the
witness.
\end{definition}

n19882.content:
\begin{definition}[Witness extractor]
\lean{Schnorr.extract}
\label{Schnorr.extract}
\leanok
Given two challenges $c_1, c_2$ and corresponding responses $s_1, s_2$ in
$\mathbb{Z}_q$, the extractor returns
\[
  \frac{s_1 - s_2}{c_1 - c_2} \;\in\; \mathbb{Z}_q.
\]
\end{definition}

n19883.content:
\begin{theorem}[Completeness]
\lean{Schnorr.schnorr_completeness}
\label{Schnorr.schnorr_completeness}
\leanok
\uses{Schnorr.Verify, Schnorr.commit, Schnorr.respond}

Let $g \in G$ be an element of order $q$ and let $w, r, c \in \mathbb{Z}_q$.
Then the honest transcript $(g^r, c, r + c \cdot w)$ satisfies the verifier
equation with respect to the public key $\mathit{pk} = g^w$:
\[
  g^{(r + c \cdot w).\mathrm{val}} \;=\; g^{r.\mathrm{val}} \cdot (g^{w.\mathrm{val}})^{c.\mathrm{val}}.
\]
\end{theorem}

n19884.content:
\begin{theorem}[Special soundness]
\lean{Schnorr.schnorr_soundness}
\label{Schnorr.schnorr_soundness}
\leanok
\uses{Schnorr.Verify, Schnorr.extract}

Let $g \in G$ have order $q$, and let $a \in G$, $c_1 \neq c_2 \in \mathbb{Z}_q$,
$s_1, s_2 \in \mathbb{Z}_q$ be such that both transcripts $(a, c_1, s_1)$ and
$(a, c_2, s_2)$ satisfy $\mathrm{Verify}$ with respect to public key
$\mathit{pk} = g^w$.  Then the extractor recovers the witness:
\[
  \frac{s_1 - s_2}{c_1 - c_2} \;=\; w \;\in\; \mathbb{Z}_q.
\]
\end{theorem}

n19885.content:
\begin{definition}[Randomness reindexing]
\lean{Schnorr.reindex}
\label{Schnorr.reindex}
\leanok
For fixed $w, c \in \mathbb{Z}_q$, define the bijection
$\sigma_{w,c} : \mathbb{Z}_q \xrightarrow{\;\sim\;} \mathbb{Z}_q$ by
$r \mapsto r + c \cdot w$, with inverse $s \mapsto s - c \cdot w$.
\end{definition}

n19886.content:
\begin{theorem}[Honest-verifier zero knowledge]
\lean{Schnorr.schnorr_hvzk}
\label{Schnorr.schnorr_hvzk}
\leanok
\uses{Schnorr.commit, Schnorr.honest, Schnorr.reindex, Schnorr.respond, Schnorr.schnorr_completeness, Schnorr.simulate}

Let $g \in G$ have order $q$ and let $w, c \in \mathbb{Z}_q$.  The honest
transcript map $r \mapsto \mathrm{honest}(g, w, r, c)$ and the simulator map
$r \mapsto \mathrm{simulate}(g,\, g^w,\, c,\, \sigma_{w,c}(r))$ are equal as
functions $\mathbb{Z}_q \to \mathrm{Transcript}(G, q)$, where
$\sigma_{w,c} = \mathrm{reindex}(w, c)$ is the bijective shift $r \mapsto r + c \cdot w$.
\end{theorem}

n19887.content:
\begin{definition}[Linearity of a Boolean function]
\lean{BoolBLR.is_linear_bool}
\label{BoolBLR.is_linear_bool}
\leanok
\uses{BoolFourier.hypercube, BoolFourier.xor_vec}
A function $f : \{0,1\}^n \to \{0,1\}$ is \emph{linear} if for all
$x, y \in \{0,1\}^n$ we have
\[
  f(x \oplus y) = f(x) \oplus f(y),
\]
where $\oplus$ denotes bitwise XOR (i.e.\ \texttt{Bool.xor}).
\end{definition}

n19888.content:
\begin{definition}[$\pm 1$ lift of a Boolean function]
\lean{BoolBLR.lift_pm1}
\label{BoolBLR.lift_pm1}
\leanok
\uses{BoolFourier.BoolFun, BoolFourier.BoolToPM1, BoolFourier.hypercube}
Given $f : \{0,1\}^n \to \{0,1\}$, its \emph{$\pm 1$ lift}
$\texttt{BoolBLR.lift\_pm1}\,f : \{0,1\}^n \to \mathbb{R}$ is defined by
$x \mapsto (-1)^{f(x)}$, converting each Boolean output to a real sign via
\texttt{BoolToPM1}.
\end{definition}

n19889.content:
\begin{definition}[Boolean distance]
\lean{BoolBLR.bool_dist}
\label{BoolBLR.bool_dist}
\leanok
\uses{BoolFourier.expectation, BoolFourier.hypercube}
The \emph{distance} between two Boolean functions
$f, g : \{0,1\}^n \to \{0,1\}$ is
\[
  \dist(f, g) \;=\; \Pr_{x \sim \{0,1\}^n}[f(x) \ne g(x)],
\]
computed as the uniform expectation of the indicator $\mathbf{1}[f(x) \ne g(x)]$.
\end{definition}

n19890.content:
\begin{definition}[$\varepsilon$-far from linear]
\lean{BoolBLR.epsilon_far_from_linear}
\label{BoolBLR.epsilon_far_from_linear}
\leanok
\uses{BoolBLR.bool_dist, BoolBLR.is_linear_bool, BoolFourier.hypercube}
A function $f : \{0,1\}^n \to \{0,1\}$ is \emph{$\varepsilon$-far from linear}
if $0 \le \varepsilon \le 1$ and for every linear function
$g : \{0,1\}^n \to \{0,1\}$ we have $\dist(f, g) \ge \varepsilon$.
\end{definition}

n19891.content:
\begin{lemma}[Linear iff equal to a Fourier character]
\lean{BoolBLR.linear_bool_iff_character}
\label{BoolBLR.linear_bool_iff_character}
\leanok
\uses{BoolBLR.is_linear_bool, BoolBLR.lift_pm1, BoolFourier.BoolToPM1, BoolFourier.BoolToPM1_xor, BoolFourier.char_S, BoolFourier.hypercube, BoolFourier.xor_vec, BooleanAnalysis.boolToSign, BooleanAnalysis.chiS}

A Boolean function $f : \{0,1\}^n \to \{0,1\}$ is linear if and only if
there exists a set $S \subseteq [n]$ such that the $\pm 1$ lift
$\texttt{BoolBLR.lift\_pm1}\,f$ equals the Fourier character $\chi_S$.
\end{lemma}

n19893.content:
\begin{lemma}[BLR acceptance in $\pm 1$ form]
\lean{BoolBLR.BLR_accept_prob_pm1}
\label{BoolBLR.BLR_accept_prob_pm1}
\leanok
\uses{BoolBLR.BLR_accept_prob, BoolBLR.lift_pm1, BoolFourier.card_hypercube, BoolFourier.expectation, BoolFourier.hypercube, BoolFourier.xor_vec}

For any $f : \{0,1\}^n \to \{0,1\}$,
\[
  \Pr[\text{BLR accepts}]
  \;=\;
  \frac{1 + \mathbb{E}_x\!\left[\mathbb{E}_y\!\left[
    \texttt{BoolBLR.lift\_pm1}\,f(x)\cdot
    \texttt{BoolBLR.lift\_pm1}\,f(y)\cdot
    \texttt{BoolBLR.lift\_pm1}\,f(x \oplus y)
  \right]\right]}{2}.
\]
\end{lemma}

n19894.content:
\begin{lemma}[Triple expectation as convolution]
\lean{BoolBLR.triple_expectation_as_convolution}
\label{BoolBLR.triple_expectation_as_convolution}
\leanok
\uses{BoolFourier.BoolFun, BoolFourier.expectation, BoolFourier.xor_vec}

For any $f : \{0,1\}^n \to \mathbb{R}$,
\[
  \mathbb{E}_x\!\left[\mathbb{E}_y\!\left[f(x)\,f(y)\,f(x \oplus y)\right]\right]
  \;=\;
  \mathbb{E}_x\!\left[f(x)\cdot\mathbb{E}_y\!\left[f(y)\,f(x \oplus y)\right]\right].
\]
\end{lemma}

n19895.content:
\begin{lemma}[Triple expectation equals sum of cubed Fourier coefficients]
\lean{BoolBLR.triple_expectation_eq_cube_fourier}
\label{BoolBLR.triple_expectation_eq_cube_fourier}
\leanok
\uses{BoolBLR.lift_pm1, BoolFourier.char_S, BoolFourier.convolution, BoolFourier.expectation, BoolFourier.fourier_coeff, BoolFourier.fourier_coeff_convolution, BoolFourier.fourier_expansion, BoolFourier.hypercube, BoolFourier.xor_vec}

For any $f : \{0,1\}^n \to \{0,1\}$, letting $\hat{g}(S)$ denote the Fourier
coefficient of $g = \texttt{BoolBLR.lift\_pm1}\,f$,
\[
  \mathbb{E}_x\!\left[\mathbb{E}_y\!\left[g(x)\,g(y)\,g(x \oplus y)\right]\right]
  \;=\;
  \sum_{S \subseteq [n]} \hat{g}(S)^3.
\]
\end{lemma}

n19896.content:
\begin{lemma}[Fourier coefficient bound from distance]
\lean{BoolBLR.fourier_coeff_le_of_dist_ge}
\label{BoolBLR.fourier_coeff_le_of_dist_ge}
\leanok
