If $f : \{0,1\}^n \to \{0,1\}$ is $\varepsilon$-far from linear, then
\[
  \texttt{BoolBLR.BLR\_accept\_prob}\,f \;\le\; 1 - \varepsilon.
\]
That is, a function that is $\varepsilon$-far from every linear function
causes the BLR test to reject with probability at least $\varepsilon$.
\end{lemma}

n19902.content:
\begin{lemma}[Value of a linear function via its support]
\lean{BoolBLR.linear_bool_iff_character_aux_h_fx_2}
\label{BoolBLR.linear_bool_iff_character_aux_h_fx_2}
\leanok
\uses{BoolBLR.is_linear_bool, BoolBLR.linear_bool_iff_character_aux_h_fx_1, BoolFourier.hypercube, BooleanAnalysis.BoolCube}

Specialization of the previous lemma to the support of an arbitrary point:
if $f : \{0,1\}^n \to \{0,1\}$ is linear, then for every $x \in \{0,1\}^n$
the value $f(x)$ is the parity of the number of coordinates $i$ with
$x_i = \texttt{true}$ and $f(e_i) = \texttt{true}$.
\end{lemma}

n19903.content:
\begin{lemma}[Multiplicativity of the Fourier characters]
\lean{BoolBLR.linear_bool_iff_character_aux_h_char}
\label{BoolBLR.linear_bool_iff_character_aux_h_char}
\leanok
\uses{BoolFourier.BoolToPM1_xor, BoolFourier.char_S, BoolFourier.hypercube, BoolFourier.xor_vec, BooleanAnalysis.chiS}

For every $S \subseteq [n]$ and all $x, y \in \{0,1\}^n$,
\[
  \chi_S(x \oplus y) \;=\; \chi_S(x)\,\chi_S(y).
\]
\end{lemma}

n19904.content:
\begin{lemma}[$\pm 1$ lift of a character is XOR-additive]
\lean{BoolBLR.linear_bool_iff_character_aux_h_eq}
\label{BoolBLR.linear_bool_iff_character_aux_h_eq}
\leanok
\uses{BoolBLR.lift_pm1, BoolFourier.BoolToPM1, BoolFourier.BoolToPM1_xor, BoolFourier.char_S, BoolFourier.hypercube, BoolFourier.xor_vec}

Let $f : \{0,1\}^n \to \{0,1\}$ satisfy $\texttt{BoolBLR.lift\_pm1}\,f = \chi_S$
for some $S \subseteq [n]$, and let $x, y \in \{0,1\}^n$.  Assuming the
multiplicativity identity $\chi_S(x \oplus y) = \chi_S(x)\chi_S(y)$, one has
\[
  (-1)^{f(x \oplus y)} \;=\; (-1)^{f(x) \oplus f(y)}.
\]
\end{lemma}

n19905.content:
\begin{lemma}[Value of a linear function via its support, restated]
\lean{BoolBLR.linear_bool_iff_character_aux_h_fx}
