n20029.content:
\begin{lemma}[Upper bound on real part of Fourier coefficient]
\lean{ZkBLR.re_fourier_coeff_upper_bound}
\label{ZkBLR.re_fourier_coeff_upper_bound}
\leanok
\uses{ZkBLR.lift_omega, ZkBLR.linear_character, ZkBLR.re_toOmega_le_re_rootOfUnity, ZkBLR.zk_dist, ZkFourier.ZkVec, ZkFourier.char_s, ZkFourier.expectation, ZkFourier.fourier_coeff, ZkFourier.inner_product, ZkFourier.rootOfUnity, ZkFourier.toOmega, ZkFourier.toOmega_add, ZkFourier.toOmega_neg, ZkFourier.zkDot}

For $k \ge 2$ and $f : \mathbb{Z}_k^n \to \mathbb{Z}_k$, the real part of
the $s$-th Fourier coefficient of the lifted function $\widetilde{f}$ satisfies
\[
  \operatorname{Re}\bigl[\widehat{\widetilde{f}}(s)\bigr]
  \;\le\;
  1 - \bigl(1 - \cos(2\pi/k)\bigr)\cdot\mathrm{dist}(f,\chi_s).
\]
\end{lemma}

n20030.content:
\begin{lemma}[Fourier bound from $\varepsilon$-far hypothesis]
\lean{ZkBLR.re_epsilon_far_bounds_fourier}
\label{ZkBLR.re_epsilon_far_bounds_fourier}
\leanok
\uses{ZkBLR.epsilon_far_from_linear_normalized, ZkBLR.is_linear, ZkBLR.lift_omega, ZkBLR.linear_character, ZkBLR.re_fourier_coeff_upper_bound, ZkFourier.ZkVec, ZkFourier.fourier_coeff, ZkFourier.zkDot_add_right}

If $k \ge 2$ and $f$ is $\varepsilon$-far from linear (in the normalized sense),
then for every $s \in \mathbb{Z}_k^n$,
\[
  \operatorname{Re}\bigl[\widehat{\widetilde{f}}(s)\bigr]
  \;\le\; 1 - \bigl(1-\cos(2\pi/k)\bigr)\varepsilon.
\]
\end{lemma}

n20031.content:
\begin{definition}[$j$-twisted lift to roots of unity]
\lean{ZkBLR.lift_omega_j}
\label{ZkBLR.lift_omega_j}
\leanok
\uses{ZkFourier.ZkFun, ZkFourier.ZkVec, ZkFourier.toOmega}
For $j \in \mathbb{Z}_k$, the $j$-twisted lift of
$f : \mathbb{Z}_k^n \to \mathbb{Z}_k$ is
$\widetilde{f}_j(x) = \omega_k^{j \cdot f(x)}$.
The case $j=1$ recovers \texttt{ZkBLR.lift\_omega}; the case $j=0$ gives the
constant function $1$.
\end{definition}

n20032.content:
\begin{definition}[BLR acceptance probability]
\lean{ZkBLR.BLR_accept_prob}
\label{ZkBLR.BLR_accept_prob}
\leanok
\uses{ZkFourier.ZkVec}
The BLR acceptance probability of $f : \mathbb{Z}_k^n \to \mathbb{Z}_k$ is
\[
  \Pr_{x,y}\bigl[f(x+y) = f(x)+f(y)\bigr]
  \;=\; \frac{1}{k^{2n}}
    \sum_{x,y\in\mathbb{Z}_k^n}
    \mathbf{1}\bigl[f(x+y)=f(x)+f(y)\bigr].
\]
\end{definition}

n20033.content:
\begin{lemma}[BLR completeness]
\lean{ZkBLR.BLR_completeness}
\label{ZkBLR.BLR_completeness}
\leanok
\uses{ZkBLR.BLR_accept_prob, ZkBLR.is_linear, ZkFourier.ZkVec, ZkFourier.card_ZkVec}

If $f : \mathbb{Z}_k^n \to \mathbb{Z}_k$ is linear, then
$\Pr[{\rm BLR\ accepts}\ f] = 1$.
\end{lemma}

n20034.content:
\begin{lemma}[Geometric sum of twisted roots of unity]
\lean{ZkBLR.geom_sum_toOmega_dual}
\label{ZkBLR.geom_sum_toOmega_dual}
\leanok

\uses{ZkFourier.geom_sum_toOmega, ZkFourier.toOmega}

For any $a \in \mathbb{Z}_k$,
\[
  \sum_{j \in \mathbb{Z}_k} \omega_k^{ja}
  \;=\; \begin{cases} k & \text{if } a = 0, \\ 0 & \text{otherwise.} \end{cases}
\]
\end{lemma}

n20035.content:
\begin{lemma}[Indicator as character sum]
\lean{ZkBLR.indicator_eq_char_sum_re}
\label{ZkBLR.indicator_eq_char_sum_re}
\leanok
\uses{ZkBLR.geom_sum_toOmega_dual, ZkFourier.toOmega}

For any $a \in \mathbb{Z}_k$,
\[
  \mathbf{1}[a=0]
  \;=\; \frac{1}{k}\,\operatorname{Re}\!\left[\sum_{j\in\mathbb{Z}_k}\omega_k^{ja}\right].
\]
\end{lemma}

n20036.content:
\begin{lemma}[Parseval identity for $j$-twisted lift]
\lean{ZkBLR.parseval_lift_omega_j}
\label{ZkBLR.parseval_lift_omega_j}
\leanok
\uses{ZkBLR.lift_omega_j, ZkFourier.L2_norm_sq, ZkFourier.ZkVec, ZkFourier.card_ZkVec, ZkFourier.fourier_coeff, ZkFourier.norm_toOmega, ZkFourier.parseval_identity, ZkFourier.toOmega}

For any $j \in \mathbb{Z}_k$ and $f : \mathbb{Z}_k^n \to \mathbb{Z}_k$,
\[
  \sum_{s \in \mathbb{Z}_k^n}
  \bigl\|\widehat{(\widetilde{f}_j)}(s)\bigr\|^2 = 1.
\]
\end{lemma}

n20037.content:
\begin{lemma}[Triple-product Fourier expansion]
\lean{ZkBLR.triple_product_fourier}
\label{ZkBLR.triple_product_fourier}
\leanok
\uses{ZkBLR.lift_omega_j, ZkFourier.ZkFun, ZkFourier.ZkVec, ZkFourier.char_s, ZkFourier.char_s_add, ZkFourier.expectation, ZkFourier.fourier_coeff, ZkFourier.fourier_expansion, ZkFourier.inner_product}

For $j \in \mathbb{Z}_k$ and $F = \widetilde{f}_j$, the triple-product
expectation satisfies
\[
  \mathbb{E}_x\!\left[\mathbb{E}_y\!\left[
    F(x{+}y)\,\overline{F(x)}\,\overline{F(y)}
  \right]\right]
  = \sum_{s\in\mathbb{Z}_k^n}
    \|\widehat{F}(s)\|^2\,\overline{\widehat{F}(s)}.
\]
\end{lemma}

n20038.content:
\begin{lemma}[BLR probability as Fourier sum]
\lean{ZkBLR.BLR_accept_prob_eq_fourier_sum}
\label{ZkBLR.BLR_accept_prob_eq_fourier_sum}
\leanok
\uses{ZkBLR.BLR_accept_prob, ZkBLR.indicator_eq_char_sum_re, ZkBLR.lift_omega_j, ZkBLR.triple_product_fourier, ZkFourier.ZkVec, ZkFourier.expectation, ZkFourier.fourier_coeff, ZkFourier.toOmega, ZkFourier.toOmega_add, ZkFourier.toOmega_neg}

The BLR acceptance probability admits the Fourier representation
\[
  \Pr[{\rm accept}]
  = \frac{1}{k}
    \sum_{j\in\mathbb{Z}_k}
    \sum_{s\in\mathbb{Z}_k^n}
    \bigl\|\widehat{(\widetilde{f}_j)}(s)\bigr\|^2
    \operatorname{Re}\!\left[\widehat{(\widetilde{f}_j)}(s)\right].
\]
\end{lemma}

n20039.content:
\begin{lemma}[Zero-index contribution equals one]
\lean{ZkBLR.lift_omega_j_zero_contribution}
\label{ZkBLR.lift_omega_j_zero_contribution}
\leanok
\uses{ZkBLR.lift_omega_j, ZkFourier.ZkVec, ZkFourier.card_ZkVec, ZkFourier.char_s, ZkFourier.char_s_conj, ZkFourier.expectation, ZkFourier.expectation_char_nontrivial, ZkFourier.fourier_coeff, ZkFourier.inner_product, ZkFourier.toOmega_zero}

For any $f : \mathbb{Z}_k^n \to \mathbb{Z}_k$, the $j=0$ term of the Fourier
sum evaluates to $1$:
\[
  \sum_{s\in\mathbb{Z}_k^n}
  \bigl\|\widehat{(\widetilde{f}_0)}(s)\bigr\|^2\,
  \operatorname{Re}\!\left[\widehat{(\widetilde{f}_0)}(s)\right] = 1.
\]
\end{lemma}

n20040.content:
\begin{lemma}[Weighted Fourier sum at most one]
\lean{ZkBLR.weighted_fourier_sum_le_one}
\label{ZkBLR.weighted_fourier_sum_le_one}
\leanok
\uses{ZkBLR.lift_omega_j, ZkBLR.parseval_lift_omega_j, ZkFourier.ZkVec, ZkFourier.fourier_coeff}

For any $j \in \mathbb{Z}_k$ and $f : \mathbb{Z}_k^n \to \mathbb{Z}_k$,
\[
  \sum_{s\in\mathbb{Z}_k^n}
  \bigl\|\widehat{(\widetilde{f}_j)}(s)\bigr\|^2\,
  \operatorname{Re}\!\left[\widehat{(\widetilde{f}_j)}(s)\right] \;\le\; 1.
\]
\end{lemma}

n20041.content:
\begin{lemma}[Cube-sum bounded by max times square-sum]
\lean{ZkBLR.cube_sum_bound_by_max}
\label{ZkBLR.cube_sum_bound_by_max}
\leanok
\uses{ZkBLR.lift_omega, ZkFourier.ZkVec, ZkFourier.fourier_coeff}

If $\|\widehat{\widetilde{f}}(s)\| \le A$ for all $s \in \mathbb{Z}_p^n$, then
\[
  \sum_{s\in\mathbb{Z}_p^n}
  \bigl\|\widehat{\widetilde{f}}(s)\bigr\|^3
  \;\le\;
  A \cdot \sum_{s\in\mathbb{Z}_p^n}
  \bigl\|\widehat{\widetilde{f}}(s)\bigr\|^2.
\]
\end{lemma}

n20042.content:
\begin{lemma}[Parseval identity for lift\_omega]
\lean{ZkBLR.parseval_lift_omega}
\label{ZkBLR.parseval_lift_omega}
\leanok
\uses{ZkBLR.lift_omega, ZkFourier.L2_norm_sq, ZkFourier.ZkVec, ZkFourier.card_ZkVec, ZkFourier.fourier_coeff, ZkFourier.norm_toOmega, ZkFourier.parseval_identity}

For $f : \mathbb{Z}_p^n \to \mathbb{Z}_p$,
\[
  \sum_{s\in\mathbb{Z}_p^n}
  \bigl\|\widehat{\widetilde{f}}(s)\bigr\|^2 = 1.
\]
\end{lemma}

n20043.content:
\begin{lemma}[Weighted Fourier sum bounded by $\varepsilon$-far condition]
\lean{ZkBLR.weighted_fourier_sum_bound}
\label{ZkBLR.weighted_fourier_sum_bound}
\leanok
\uses{ZkBLR.epsilon_far_from_linear_normalized, ZkBLR.lift_omega, ZkBLR.parseval_lift_omega, ZkBLR.re_epsilon_far_bounds_fourier, ZkFourier.ZkVec, ZkFourier.fourier_coeff}

If $f : \mathbb{Z}_p^n \to \mathbb{Z}_p$ is $\varepsilon$-far from linear
(normalized), then
\[
  \sum_{s\in\mathbb{Z}_p^n}
  \bigl\|\widehat{\widetilde{f}}(s)\bigr\|^2\,
  \operatorname{Re}\!\left[\widehat{\widetilde{f}}(s)\right]
  \;\le\; 1 - \bigl(1-\cos(2\pi/p)\bigr)\varepsilon.
\]
\end{lemma}

n20044.content:
\begin{lemma}[Fourier coefficient real-part bound for $j$-twisted lift]
\lean{ZkBLR.re_fourier_coeff_lift_omega_j_bound}
\label{ZkBLR.re_fourier_coeff_lift_omega_j_bound}
\leanok
\uses{ZkBLR.epsilon_far_from_linear_normalized, ZkBLR.lift_omega_j, ZkBLR.re_epsilon_far_bounds_fourier, ZkBLR.zk_dist, ZkFourier.ZkVec, ZkFourier.fourier_coeff}

If $f : \mathbb{Z}_p^n \to \mathbb{Z}_p$ is $\varepsilon$-far from linear
(normalized), $j \ne 0$, and $s \in \mathbb{Z}_p^n$, then
\[
  \operatorname{Re}\!\left[\widehat{(\widetilde{f}_j)}(s)\right]
  \;\le\; 1 - \bigl(1-\cos(2\pi/p)\bigr)\varepsilon.
\]
\end{lemma}

n20045.content:
\begin{lemma}[Weighted sum bound for $j$-twisted lift]
\lean{ZkBLR.weighted_sum_lift_omega_j_bound}
\label{ZkBLR.weighted_sum_lift_omega_j_bound}
\leanok
\uses{ZkBLR.epsilon_far_from_linear_normalized, ZkBLR.lift_omega_j, ZkBLR.parseval_lift_omega_j, ZkBLR.re_fourier_coeff_lift_omega_j_bound, ZkFourier.ZkVec, ZkFourier.fourier_coeff}

If $f : \mathbb{Z}_p^n \to \mathbb{Z}_p$ is $\varepsilon$-far from linear
(normalized) and $j \ne 0$, then
\[
  \sum_{s\in\mathbb{Z}_p^n}
  \bigl\|\widehat{(\widetilde{f}_j)}(s)\bigr\|^2\,
  \operatorname{Re}\!\left[\widehat{(\widetilde{f}_j)}(s)\right]
  \;\le\; 1 - \bigl(1-\cos(2\pi/p)\bigr)\varepsilon.
\]
\end{lemma}

n20046.content:
\begin{lemma}[BLR soundness for prime fields]
\lean{ZkBLR.BLR_soundness}
\label{ZkBLR.BLR_soundness}
\leanok
\uses{ZkBLR.BLR_accept_prob, ZkBLR.BLR_accept_prob_eq_fourier_sum, ZkBLR.epsilon_far_from_linear_normalized, ZkBLR.lift_omega_j_zero_contribution, ZkBLR.weighted_sum_lift_omega_j_bound, ZkFourier.ZkVec}

If $f : \mathbb{Z}_p^n \to \mathbb{Z}_p$ is $\varepsilon$-far from linear
(normalized), then
\[
  \Pr[{\rm BLR\ accepts}\ f]
  \;\le\; 1 - \frac{p-1}{p}\bigl(1-\cos(2\pi/p)\bigr)\varepsilon.
\]
\end{lemma}

n20047.content:
\begin{lemma}[$\varepsilon$-farness preserved under unit scaling]
\lean{ZkBLR.unit_mul_epsilon_far}
\label{ZkBLR.unit_mul_epsilon_far}
\leanok
\uses{ZkBLR.epsilon_far_from_linear_normalized, ZkBLR.zk_dist, ZkFourier.ZkVec}

If $f : \mathbb{Z}_k^n \to \mathbb{Z}_k$ is $\varepsilon$-far from linear
(normalized) and $j \in \mathbb{Z}_k^\times$ is a unit, then the scaled
function $x \mapsto j \cdot f(x)$ is also $\varepsilon$-far from linear
(normalized).
\end{lemma}

n20048.content:
\begin{lemma}[Real-part bound for unit-twisted lift]
\lean{ZkBLR.re_fourier_coeff_lift_omega_j_unit_bound}
\label{ZkBLR.re_fourier_coeff_lift_omega_j_unit_bound}
\leanok
\uses{ZkBLR.epsilon_far_from_linear_normalized, ZkBLR.lift_omega_j, ZkBLR.re_epsilon_far_bounds_fourier, ZkBLR.unit_mul_epsilon_far, ZkFourier.ZkVec, ZkFourier.fourier_coeff}

If $k \ge 2$, $f$ is $\varepsilon$-far from linear (normalized), $j \in
\mathbb{Z}_k^\times$, and $s \in \mathbb{Z}_k^n$, then
\[
  \operatorname{Re}\!\left[\widehat{(\widetilde{f}_j)}(s)\right]
  \;\le\; 1 - \bigl(1-\cos(2\pi/k)\bigr)\varepsilon.
\]
\end{lemma}

n20049.content:
\begin{lemma}[Weighted sum bound for unit-twisted lift]
\lean{ZkBLR.weighted_sum_unit_bound}
\label{ZkBLR.weighted_sum_unit_bound}
\leanok
\uses{ZkBLR.epsilon_far_from_linear_normalized, ZkBLR.lift_omega_j, ZkBLR.parseval_lift_omega_j, ZkBLR.re_fourier_coeff_lift_omega_j_unit_bound, ZkFourier.ZkVec, ZkFourier.fourier_coeff}

If $k \ge 2$, $f$ is $\varepsilon$-far from linear (normalized), and $j \in
\mathbb{Z}_k^\times$, then
\[
  \sum_{s\in\mathbb{Z}_k^n}
  \bigl\|\widehat{(\widetilde{f}_j)}(s)\bigr\|^2\,
  \operatorname{Re}\!\left[\widehat{(\widetilde{f}_j)}(s)\right]
  \;\le\; 1 - \bigl(1-\cos(2\pi/k)\bigr)\varepsilon.
\]
\end{lemma}

n20050.content:
\begin{lemma}[BLR soundness for general $k$]
\lean{ZkBLR.BLR_soundness_general}
\label{ZkBLR.BLR_soundness_general}
\leanok
\uses{ZkBLR.BLR_accept_prob, ZkBLR.BLR_accept_prob_eq_fourier_sum, ZkBLR.epsilon_far_from_linear_normalized, ZkBLR.lift_omega_j, ZkBLR.weighted_fourier_sum_le_one, ZkBLR.weighted_sum_unit_bound, ZkFourier.ZkVec, ZkFourier.fourier_coeff}

For $k \ge 2$, if $f : \mathbb{Z}_k^n \to \mathbb{Z}_k$ is $\varepsilon$-far
from linear (normalized), then
\[
  \Pr[{\rm BLR\ accepts}\ f]
  \;\le\; 1 - \frac{\varphi(k)}{k}\bigl(1-\cos(2\pi/k)\bigr)\varepsilon,
\]
where $\varphi(k)$ denotes Euler's totient function.
\end{lemma}

n20052.content:
\begin{definition}[Vectors over $\mathbb{Z}/k\mathbb{Z}$]
\lean{ZkFourier.ZkVec}
\label{ZkFourier.ZkVec}
\leanok
$\texttt{ZkFourier.ZkVec}\ k\ n$ is the $n$-dimensional vector space over
$\mathbb{Z}/k\mathbb{Z}$, defined as the function type
$\mathrm{Fin}\,n \to \mathbb{Z}/k\mathbb{Z}$.  It carries the pointwise
additive group structure of $(\mathbb{Z}/k\mathbb{Z})^n$.
\end{definition}

n20053.content:
\begin{lemma}[Cardinality of $\mathbb{Z}_k^n$]
\lean{ZkFourier.card_ZkVec}
\label{ZkFourier.card_ZkVec}
\leanok
\uses{ZkFourier.ZkVec, ZkFourier.rootOfUnity}

For $k \geq 1$, the finite type $\texttt{ZkFourier.ZkVec}\ k\ n$ has
$|\mathbb{Z}_k^n| = k^n$ elements.
\end{lemma}

n20054.content:
\begin{definition}[Primitive $k$-th root of unity]
\lean{ZkFourier.rootOfUnity}
\label{ZkFourier.rootOfUnity}
\leanok

$\texttt{ZkFourier.rootOfUnity}\ k$ is the complex number
$\omega_k = e^{2\pi i / k}$, the primitive $k$-th root of unity used as the
base of the Fourier characters on $\mathbb{Z}_k^n$.
\end{definition}

n20055.content:
\begin{definition}[Embedding of $\mathbb{Z}/k\mathbb{Z}$ into $\mathbb{C}^\times$]
\lean{ZkFourier.toOmega}
\label{ZkFourier.toOmega}
\leanok

\uses{ZkFourier.rootOfUnity}
For $a : \mathbb{Z}/k\mathbb{Z}$, $\texttt{ZkFourier.toOmega}\ a = \omega_k^{a}$,
where $a$ is lifted to its canonical representative in
$\{0, \ldots, k-1\} \subset \mathbb{N}$.  This is the group homomorphism
$(\mathbb{Z}/k\mathbb{Z}, +) \to (\mathbb{C}^\times, \cdot)$.
\end{definition}

n20056.content:
\begin{lemma}[$\omega_k$ is a primitive $k$-th root]
\lean{ZkFourier.isPrimitiveRoot_rootOfUnity}
\label{ZkFourier.isPrimitiveRoot_rootOfUnity}
\leanok
\uses{ZkFourier.rootOfUnity}

$\omega_k = e^{2\pi i/k}$ is a primitive $k$-th root of unity in $\mathbb{C}$,
i.e.\ $\omega_k^k = 1$ and $\omega_k^j \neq 1$ for $0 < j < k$.
\end{lemma}

n20057.content:
\begin{lemma}[$\omega_k^k = 1$]
\lean{ZkFourier.rootOfUnity_pow_k}
\label{ZkFourier.rootOfUnity_pow_k}
\leanok
\uses{ZkFourier.isPrimitiveRoot_rootOfUnity, ZkFourier.rootOfUnity}

The $k$-th power of the root of unity satisfies $\omega_k^k = 1$.
\end{lemma}

n20058.content:
\begin{lemma}[$\omega_k^0 = 1$]
\lean{ZkFourier.toOmega_zero}
\label{ZkFourier.toOmega_zero}
\leanok
\uses{ZkFourier.toOmega}

The embedding sends zero to one: $\texttt{ZkFourier.toOmega}\ (0 : \mathbb{Z}/k\mathbb{Z}) = 1$.
\end{lemma}

n20059.content:
\begin{lemma}[Additivity of the embedding]
\lean{ZkFourier.toOmega_add}
\label{ZkFourier.toOmega_add}
\leanok
\uses{ZkFourier.rootOfUnity_pow_k, ZkFourier.toOmega}

For $a, b : \mathbb{Z}/k\mathbb{Z}$,
$\omega_k^{a+b} = \omega_k^a \cdot \omega_k^b$.
That is, $\texttt{ZkFourier.toOmega}$ is a group homomorphism from
$(\mathbb{Z}/k\mathbb{Z}, +)$ to $(\mathbb{C}^\times, \cdot)$.
\end{lemma}

n20060.content:
\begin{lemma}[Negation and complex conjugation]
\lean{ZkFourier.toOmega_neg}
\label{ZkFourier.toOmega_neg}
\leanok
\uses{ZkFourier.rootOfUnity, ZkFourier.toOmega}

For $a : \mathbb{Z}/k\mathbb{Z}$,
$\omega_k^{-a} = \overline{\omega_k^a}$,
i.e.\ $\texttt{ZkFourier.toOmega}\ (-a) = \overline{\texttt{ZkFourier.toOmega}\ a}$.
\end{lemma}

n20061.content:
\begin{lemma}[Unit norm of the embedding]
\lean{ZkFourier.norm_toOmega}
\label{ZkFourier.norm_toOmega}
\leanok
\uses{ZkFourier.rootOfUnity, ZkFourier.toOmega}

For every $a : \mathbb{Z}/k\mathbb{Z}$, $\|\omega_k^a\| = 1$; the image of
$\texttt{ZkFourier.toOmega}$ lies on the complex unit circle.
\end{lemma}

n20062.content:
\begin{lemma}[Multiplicativity of the embedding]
\lean{ZkFourier.toOmega_mul}
\label{ZkFourier.toOmega_mul}
\leanok
\uses{ZkFourier.rootOfUnity, ZkFourier.rootOfUnity_pow_k, ZkFourier.toOmega}

For $j, a : \mathbb{Z}/k\mathbb{Z}$,
$\omega_k^{j \cdot a} = (\omega_k^j)^a$, i.e.\
$\texttt{ZkFourier.toOmega}\ (j \cdot a) = (\omega_k^{j.\mathrm{val}})^{a.\mathrm{val}}$.
\end{lemma}

n20063.content:
\begin{lemma}[Geometric sum orthogonality]
\lean{ZkFourier.geom_sum_toOmega}

\label{ZkFourier.geom_sum_toOmega}
\leanok
\uses{ZkFourier.isPrimitiveRoot_rootOfUnity, ZkFourier.rootOfUnity, ZkFourier.rootOfUnity_pow_k, ZkFourier.toOmega, ZkFourier.toOmega_mul}

For $j : \mathbb{Z}/k\mathbb{Z}$,
\[
  \sum_{a \in \mathbb{Z}/k\mathbb{Z}} \omega_k^{j \cdot a}
  = \begin{cases} k & \text{if } j = 0, \\ 0 & \text{if } j \neq 0. \end{cases}
\]
This is the fundamental character-orthogonality identity for $\mathbb{Z}/k\mathbb{Z}$.
\end{lemma}

n20064.content:
\begin{definition}[Functions on $\mathbb{Z}_k^n$]
\lean{ZkFourier.ZkFun}
\label{ZkFourier.ZkFun}
\leanok

\uses{ZkFourier.ZkVec}
$\texttt{ZkFourier.ZkFun}\ k\ n$ is the type of complex-valued functions on
$\mathbb{Z}_k^n$, defined as $\mathbb{Z}_k^n \to \mathbb{C}$.  These are the
objects whose Fourier transforms are studied.
\end{definition}

n20065.content:
\begin{definition}[Expectation]
\lean{ZkFourier.expectation}
\label{ZkFourier.expectation}
\leanok
\uses{ZkFourier.ZkFun, ZkFourier.ZkVec}
The expectation of $f : \mathbb{Z}_k^n \to \mathbb{C}$ is the uniform average
\[
  \mathbb{E}[f] = \frac{1}{k^n} \sum_{x \in \mathbb{Z}_k^n} f(x).
\]
\end{definition}

n20066.content:
\begin{definition}[Hermitian inner product]
\lean{ZkFourier.inner_product}
\label{ZkFourier.inner_product}
\leanok

\uses{ZkFourier.ZkFun, ZkFourier.expectation}
The Hermitian inner product of $f, g : \mathbb{Z}_k^n \to \mathbb{C}$ is
\[
  \langle f, g \rangle = \mathbb{E}\!\left[f(x)\,\overline{g(x)}\right].
\]
\end{definition}

n20067.content:
\begin{definition}[Squared $L^2$ norm]
\lean{ZkFourier.L2_norm_sq}
\label{ZkFourier.L2_norm_sq}
\leanok
\uses{ZkFourier.ZkFun, ZkFourier.ZkVec}
The squared $L^2$ norm of $f : \mathbb{Z}_k^n \to \mathbb{C}$ is the
real-valued quantity
\[
  \|f\|_2^2 = \frac{1}{k^n} \sum_{x \in \mathbb{Z}_k^n} |f(x)|^2.
\]
\end{definition}

n20068.content:
\begin{definition}[Convolution]
\lean{ZkFourier.convolution}
\label{ZkFourier.convolution}
\leanok

\uses{ZkFourier.ZkFun, ZkFourier.expectation}
The convolution of $f, g : \mathbb{Z}_k^n \to \mathbb{C}$ is
\[
  (f * g)(x) = \mathbb{E}_{y}\!\left[f(y)\,g(x - y)\right].
\]
\end{definition}

n20069.content:
\begin{definition}[Dot product on $\mathbb{Z}_k^n$]
\lean{ZkFourier.zkDot}
\label{ZkFourier.zkDot}
\leanok
\uses{ZkFourier.ZkVec}
For $s, x \in \mathbb{Z}_k^n$, the dot product is
$s \cdot x = \sum_{i=0}^{n-1} s_i \, x_i \in \mathbb{Z}/k\mathbb{Z}$,
computed componentwise modulo $k$.
\end{definition}

n20070.content:
\begin{definition}[Fourier character]
\lean{ZkFourier.char_s}
\label{ZkFourier.char_s}
\leanok

\uses{ZkFourier.ZkFun, ZkFourier.ZkVec, ZkFourier.toOmega, ZkFourier.zkDot}
For $s \in \mathbb{Z}_k^n$, the Fourier character indexed by $s$ is
$\chi_s : \mathbb{Z}_k^n \to \mathbb{C}$ defined by
$\chi_s(x) = \omega_k^{s \cdot x}$.
The $k^n$ characters $\{\chi_s\}_{s \in \mathbb{Z}_k^n}$ form an orthonormal
basis of $L^2(\mathbb{Z}_k^n)$.
\end{definition}

n20071.content:
\begin{lemma}[Dot product is additive in the right argument]
\lean{ZkFourier.zkDot_add_right}
\label{ZkFourier.zkDot_add_right}
\leanok
\uses{ZkFourier.ZkVec, ZkFourier.zkDot}

For $s, x, y \in \mathbb{Z}_k^n$,
$s \cdot (x + y) = s \cdot x + s \cdot y$.
\end{lemma}

n20072.content:
\begin{lemma}[Zero vector on the left]
\lean{ZkFourier.zkDot_zero_left}
\label{ZkFourier.zkDot_zero_left}
\leanok
\uses{ZkFourier.ZkVec, ZkFourier.zkDot}

For any $x \in \mathbb{Z}_k^n$, $0 \cdot x = 0$.
\end{lemma}

n20073.content:
\begin{lemma}[Zero vector on the right]
\lean{ZkFourier.zkDot_zero_right}
\label{ZkFourier.zkDot_zero_right}
\leanok
\uses{ZkFourier.ZkVec, ZkFourier.zkDot}

For any $s \in \mathbb{Z}_k^n$, $s \cdot 0 = 0$.
\end{lemma}

n20074.content:
\begin{lemma}[Negation on the left argument of the dot product]
\lean{ZkFourier.zkDot_neg_left}
