\leanok
\uses{ZkFourier.ZkVec, ZkFourier.zkDot}

For $s, x \in \mathbb{Z}_k^n$,
$(-s) \cdot x = -(s \cdot x)$.
\end{lemma}

n20075.content:
\begin{lemma}[Subtraction on the left argument of the dot product]
\lean{ZkFourier.zkDot_sub}
