\leanok
\uses{ZkFourier.ZkVec, ZkFourier.zkDot}

For $s, t, x \in \mathbb{Z}_k^n$,
$(s - t) \cdot x = s \cdot x - t \cdot x$.
\end{lemma}

n20076.content:
\begin{lemma}[Characters are multiplicative in the input]
\lean{ZkFourier.char_s_add}

