\leanok
\uses{ZkFourier.ZkVec, ZkFourier.char_s, ZkFourier.toOmega_add, ZkFourier.zkDot_add_right}

For $s, x, y \in \mathbb{Z}_k^n$,
$\chi_s(x + y) = \chi_s(x) \cdot \chi_s(y)$.
Each character is a group homomorphism from $(\mathbb{Z}_k^n, +)$ to
$(\mathbb{C}^\times, \cdot)$.
\end{lemma}

n20077.content:
\begin{lemma}[Character at zero input]
\lean{ZkFourier.char_s_zero_vec}
