frequency indices.
\end{lemma}

n20083.content:
\begin{lemma}[Expectation of a nontrivial character is zero]
\lean{ZkFourier.expectation_char_nontrivial}

\label{ZkFourier.expectation_char_nontrivial}
\leanok
\uses{ZkFourier.ZkVec, ZkFourier.char_s, ZkFourier.expectation, ZkFourier.geom_sum_toOmega, ZkFourier.toOmega, ZkFourier.toOmega_add, ZkFourier.zkDot}

If $s \neq 0$, then $\mathbb{E}[\chi_s] = 0$.
This follows from the geometric sum identity: when some coordinate $s_i \neq 0$,
the sum over that coordinate vanishes.
\end{lemma}

n20084.content:
\begin{lemma}[Expectation of the trivial character is one]
\lean{ZkFourier.expectation_char_trivial}
\label{ZkFourier.expectation_char_trivial}
\leanok
\uses{ZkFourier.ZkVec, ZkFourier.card_ZkVec, ZkFourier.char_s, ZkFourier.expectation}

$\mathbb{E}[\chi_0] = 1$, since $\chi_0 \equiv 1$ and the sum of $k^n$ ones
divided by $k^n$ equals one.
\end{lemma}

n20085.content:
\begin{lemma}[Self-inner-product of a character]
\lean{ZkFourier.inner_product_char_self}

\label{ZkFourier.inner_product_char_self}
\leanok





















\uses{ZkFourier.ZkVec, ZkFourier.card_ZkVec, ZkFourier.char_s, ZkFourier.expectation, ZkFourier.inner_product, ZkFourier.norm_char_s}

For any $s \in \mathbb{Z}_k^n$, $\langle \chi_s, \chi_s \rangle = 1$.
Every character is a unit-norm vector in $L^2(\mathbb{Z}_k^n)$.
\end{lemma}

n20086.content:
