\end{lemma}

n20087.content:
\begin{definition}[Fourier coefficient]
\lean{ZkFourier.fourier_coeff}
\label{ZkFourier.fourier_coeff}
\leanok

\uses{ZkFourier.ZkFun, ZkFourier.ZkVec, ZkFourier.char_s, ZkFourier.inner_product}
The Fourier coefficient of $f : \mathbb{Z}_k^n \to \mathbb{C}$ at frequency
$s$ is
\[
  \hat{f}(s) = \langle f, \chi_s \rangle
             = \mathbb{E}_{x}\!\left[f(x)\,\overline{\chi_s(x)}\right].
\]
\end{definition}

n20088.content:
\begin{lemma}[Fourier coefficient of a character at its own frequency]
\lean{ZkFourier.fourier_coeff_char_self}

\label{ZkFourier.fourier_coeff_char_self}
\leanok























\uses{ZkFourier.ZkVec, ZkFourier.char_s, ZkFourier.fourier_coeff, ZkFourier.inner_product_char_self}

For any $s \in \mathbb{Z}_k^n$,
$\widehat{\chi_s}(s) = \langle \chi_s, \chi_s \rangle = 1$.
\end{lemma}

n20089.content:
\begin{lemma}[Fourier coefficient of a character at a different frequency]
\lean{ZkFourier.fourier_coeff_char_of_ne}

\label{ZkFourier.fourier_coeff_char_of_ne}
\leanok






























\uses{ZkFourier.ZkVec, ZkFourier.char_s, ZkFourier.fourier_coeff, ZkFourier.inner_product_char_nonself}

If $s \neq t$, then $\widehat{\chi_s}(t) = \langle \chi_s, \chi_t \rangle = 0$.
\end{lemma}

n20090.content:
\begin{lemma}[Fourier expansion]
\lean{ZkFourier.fourier_expansion}
\label{ZkFourier.fourier_expansion}
\leanok

\uses{ZkFourier.ZkFun, ZkFourier.ZkVec, ZkFourier.card_ZkVec, ZkFourier.char_s, ZkFourier.char_s_add, ZkFourier.char_s_conj, ZkFourier.expectation, ZkFourier.expectation_char_nontrivial, ZkFourier.fourier_coeff, ZkFourier.inner_product, ZkFourier.zkDot}

Every function $f : \mathbb{Z}_k^n \to \mathbb{C}$ admits the Fourier expansion
\[
  f(x) = \sum_{s \in \mathbb{Z}_k^n} \hat{f}(s)\,\chi_s(x).
\]
The characters form a complete orthonormal basis of $L^2(\mathbb{Z}_k^n)$.
\end{lemma}

n20091.content:
\begin{lemma}[Parseval's identity]
\lean{ZkFourier.parseval_identity}

\label{ZkFourier.parseval_identity}
\leanok

































\uses{ZkFourier.L2_norm_sq, ZkFourier.ZkFun, ZkFourier.ZkVec, ZkFourier.char_s, ZkFourier.fourier_coeff, ZkFourier.fourier_expansion}

For any $f : \mathbb{Z}_k^n \to \mathbb{C}$,
\[
  \sum_{s \in \mathbb{Z}_k^n} |\hat{f}(s)|^2 = \|f\|_2^2.
\]
Parseval's identity expresses the conservation of $L^2$ energy under the
Fourier transform.
\end{lemma}

n20092.content:
\begin{lemma}[Convolution theorem]
\lean{ZkFourier.fourier_coeff_convolution}

\label{ZkFourier.fourier_coeff_convolution}
\leanok
\uses{ZkFourier.ZkFun, ZkFourier.ZkVec, ZkFourier.char_s_add, ZkFourier.convolution, ZkFourier.expectation, ZkFourier.fourier_coeff, ZkFourier.inner_product}

For $f, g : \mathbb{Z}_k^n \to \mathbb{C}$ and $s \in \mathbb{Z}_k^n$,
\[
  \widehat{f * g}(s) = \hat{f}(s)\,\hat{g}(s).
\]
Convolution in the spatial domain corresponds to pointwise multiplication in
the frequency domain.
\end{lemma}

n20093.content:
\begin{lemma}[Positive leaf count]
\lean{CommunicationComplexity.Deterministic.Protocol.numLeaves_pos}
\label{CommunicationComplexity.Deterministic.Protocol.numLeaves_pos}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.numLeaves, CommunicationComplexity.Deterministic.Protocol.shape}

For every deterministic protocol $p : \mathrm{Protocol}\;X\;Y\;\alpha$, the number of
leaves satisfies $0 < \texttt{CommunicationComplexity.Deterministic.Protocol.numLeaves}\;p$.
In particular, the leaf count of a protocol is always at least one.
\end{lemma}

n20094.content:
\begin{lemma}[Zero complexity when one leaf]
\lean{CommunicationComplexity.Deterministic.Protocol.complexity_eq_zero_of_numLeaves_eq_one}
\label{CommunicationComplexity.Deterministic.Protocol.complexity_eq_zero_of_numLeaves_eq_one}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.complexity, CommunicationComplexity.Deterministic.Protocol.numLeaves, CommunicationComplexity.Deterministic.Protocol.numLeaves_pos, CommunicationComplexity.Deterministic.Protocol.shape}

If a protocol $p$ has exactly one leaf (i.e.\ $p.\mathrm{numLeaves} = 1$), then its
communication complexity satisfies $p.\mathrm{complexity} = 0$.
The only protocol with a single leaf is an immediate output node, which requires no
communication.
\end{lemma}

n20095.content:
\begin{lemma}[Balanced splitting bound on squared maximum]
\lean{CommunicationComplexity.Deterministic.Protocol.max_sq_le_of_balanced}
\label{CommunicationComplexity.Deterministic.Protocol.max_sq_le_of_balanced}
\leanok

Let $m, n \in \mathbb{N}$ with $3m \le 2n$ and $3(n - m) \le 2n$.
Then $9 \cdot \max(m^2,\,(n-m)^2) \le 4n^2$.
This arithmetic inequality captures the key quantitative gain obtained when a split is
\emph{balanced}: neither piece exceeds $\tfrac{2}{3}$ of the total.
\end{lemma}

n20096.content:
\begin{theorem}[Balanced simulation of deterministic protocols]
\lean{CommunicationComplexity.Deterministic.Protocol.exists_balanced_simulation}
\label{CommunicationComplexity.Deterministic.Protocol.exists_balanced_simulation}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol, CommunicationComplexity.Deterministic.Protocol.balanced_subprotocol, CommunicationComplexity.Deterministic.Protocol.complexity, CommunicationComplexity.Deterministic.Protocol.complexity_eq_zero_of_numLeaves_eq_one, CommunicationComplexity.Deterministic.Protocol.max_sq_le_of_balanced, CommunicationComplexity.Deterministic.Protocol.numLeaves, CommunicationComplexity.Deterministic.Protocol.numLeaves_pos, CommunicationComplexity.Deterministic.Protocol.prune, CommunicationComplexity.Deterministic.Protocol.prune_numLeaves_of_lt, CommunicationComplexity.Deterministic.Protocol.prune_run_outside_of_lt, CommunicationComplexity.Deterministic.Protocol.reaches, CommunicationComplexity.Deterministic.Protocol.run, CommunicationComplexity.Deterministic.Protocol.subprotocol_run_eq_of_reaches, CommunicationComplexity.Deterministic.Protocol.testSubprotocol, CommunicationComplexity.Deterministic.Protocol.testSubprotocol_complexity, CommunicationComplexity.Deterministic.Protocol.testSubprotocol_run_inside, CommunicationComplexity.Deterministic.Protocol.testSubprotocol_run_outside}

For every deterministic protocol $p : \mathrm{Protocol}\;X\;Y\;\alpha$ there exists a
protocol $q$ such that $q.\mathrm{run} = p.\mathrm{run}$ (i.e.\ $q$ computes the same
function as $p$) and
\[
  3^{c(q)} \;\le\; 2^{c(q)} \cdot (\#\mathrm{leaves}(p))^{2},
\]
where $c(q)$ denotes the communication complexity of $q$.
\end{theorem}

n20097.content:
\begin{definition}[Bit string]
\lean{CommunicationComplexity.BitString}
\label{CommunicationComplexity.BitString}
\leanok
An $n$-bit string is a function $x : \mathrm{Fin}\,n \to \mathrm{Bool}$.
The type $\texttt{CommunicationComplexity.BitString}\,n$ is an abbreviation for
$\mathrm{Fin}\,n \to \mathrm{Bool}$.
\end{definition}

n20098.content:
\begin{definition}[Signed inner product]
\lean{CommunicationComplexity.BitString.signedInner}
\label{CommunicationComplexity.BitString.signedInner}
\leanok
\uses{CommunicationComplexity.BitString}
Given two $n$-bit strings $x, y : \mathrm{Fin}\,n \to \mathrm{Bool}$, their
\emph{signed inner product} is the integer
\[
  \mathrm{signedInner}(x, y) \;=\; \sum_{i=0}^{n-1}
    \begin{cases} 1 & \text{if } x_i = y_i,\\ -1 & \text{if } x_i \neq y_i.\end{cases}
\]
Each coordinate where $x$ and $y$ agree contributes $+1$, and each disagreeing
coordinate contributes $-1$.
\end{definition}

n20099.content:
\begin{definition}[Agreement count]
\lean{CommunicationComplexity.BitString.agreementCount}
\label{CommunicationComplexity.BitString.agreementCount}
\leanok
\uses{CommunicationComplexity.BitString}
The \emph{agreement count} of two $n$-bit strings $x$ and $y$ is the number of
coordinates $i \in \mathrm{Fin}\,n$ on which $x_i = y_i$, i.e.,
$\#\{i : x_i = y_i\}$ as a natural number.
\end{definition}

n20100.content:
\begin{theorem}[Agreement count plus Hamming distance equals length]
\lean{CommunicationComplexity.BitString.agreementCount_add_hammingDist_eq_length}
\label{CommunicationComplexity.BitString.agreementCount_add_hammingDist_eq_length}
\leanok
\uses{CommunicationComplexity.BitString, CommunicationComplexity.BitString.agreementCount}

For any two $n$-bit strings $x$ and $y$,
\[
  \mathrm{agreementCount}(x, y) + \mathrm{hammingDist}(x, y) = n.
\]
The agreeing and disagreeing coordinates partition $\{0, \ldots, n-1\}$.
\end{theorem}

n20101.content:
\begin{theorem}[Agreement count as complement of Hamming distance]
\lean{CommunicationComplexity.BitString.agreementCount_eq_length_sub_hammingDist}
\label{CommunicationComplexity.BitString.agreementCount_eq_length_sub_hammingDist}
\leanok
\uses{CommunicationComplexity.BitString, CommunicationComplexity.BitString.agreementCount, CommunicationComplexity.BitString.agreementCount_add_hammingDist_eq_length}

For any two $n$-bit strings $x$ and $y$, the agreement count satisfies
\[
  \mathrm{agreementCount}(x, y) = n - \mathrm{hammingDist}(x, y)
\]
as an equality of integers (after casting the natural numbers to $\mathbb{Z}$).
\end{theorem}

n20102.content:
\begin{theorem}[Signed inner product via Hamming distance]
\lean{CommunicationComplexity.BitString.signedInner_eq_length_sub_twice_hammingDist}
\label{CommunicationComplexity.BitString.signedInner_eq_length_sub_twice_hammingDist}
\leanok
\uses{CommunicationComplexity.BitString, CommunicationComplexity.BitString.signedInner, CommunicationComplexity.BitString.signedInner_append}

For any two $n$-bit strings $x$ and $y$,
\[
  \mathrm{signedInner}(x, y) \;=\; n - 2\,\mathrm{hammingDist}(x, y).
\]
\end{theorem}

n20103.content:
\begin{theorem}[Signed inner product via agreement and disagreement counts]
\lean{CommunicationComplexity.BitString.signedInner_eq_agreementCount_sub_hammingDist}
\label{CommunicationComplexity.BitString.signedInner_eq_agreementCount_sub_hammingDist}
\leanok
\uses{CommunicationComplexity.BitString, CommunicationComplexity.BitString.agreementCount, CommunicationComplexity.BitString.agreementCount_eq_length_sub_hammingDist, CommunicationComplexity.BitString.signedInner, CommunicationComplexity.BitString.signedInner_eq_length_sub_twice_hammingDist}

For any two $n$-bit strings $x$ and $y$,
\[
  \mathrm{signedInner}(x, y) \;=\; \mathrm{agreementCount}(x, y) - \mathrm{hammingDist}(x, y).
\]
That is, the signed inner product equals the number of agreeing coordinates minus
the number of disagreeing coordinates.
\end{theorem}

n20104.content:
\begin{theorem}[Signed inner product is additive under concatenation]
\lean{CommunicationComplexity.BitString.signedInner_append}
\label{CommunicationComplexity.BitString.signedInner_append}
\leanok
\uses{CommunicationComplexity.BitString.signedInner}

For strings $x_1, y_1 : \mathrm{Fin}\,m \to \mathrm{Bool}$ and
$x_2, y_2 : \mathrm{Fin}\,n \to \mathrm{Bool}$,
\[
  \mathrm{signedInner}(\mathrm{append}(x_1, x_2),\,\mathrm{append}(y_1, y_2))
  \;=\; \mathrm{signedInner}(x_1, y_1) + \mathrm{signedInner}(x_2, y_2).
\]
Concatenating both pairs of bit strings adds their signed inner products.
\end{theorem}

n20105.content:
\begin{theorem}[Signed inner product is invariant under index recast]
\lean{CommunicationComplexity.BitString.signedInner_comp_cast}
\label{CommunicationComplexity.BitString.signedInner_comp_cast}
\leanok
\uses{CommunicationComplexity.BitString.signedInner}

If $m = n$ and $x, y : \mathrm{Fin}\,n \to \mathrm{Bool}$, then
\[
  \mathrm{signedInner}(x \circ \mathrm{Fin.cast}\,h,\; y \circ \mathrm{Fin.cast}\,h)
  \;=\; \mathrm{signedInner}(x, y).
\]
Reindexing both inputs along a $\mathrm{Fin.cast}$ does not change the signed inner product.
\end{theorem}

n20106.content:
\begin{theorem}[Signed inner product scales under repetition]
\lean{CommunicationComplexity.BitString.signedInner_amplify}
\label{CommunicationComplexity.BitString.signedInner_amplify}
\leanok
\uses{CommunicationComplexity.BitString, CommunicationComplexity.BitString.signedInner, CommunicationComplexity.BitString.signedInner_append, CommunicationComplexity.BitString.signedInner_comp_cast}

For any $n$-bit strings $x$ and $y$ and any $a : \mathbb{N}$,
\[
  \mathrm{signedInner}(\mathrm{Fin.repeat}\,a\,x,\;\mathrm{Fin.repeat}\,a\,y)
  \;=\; a \cdot \mathrm{signedInner}(x, y).
\]
Repeating both inputs $a$ times multiplies the signed inner product by $a$.
\end{theorem}

n20107.content:
\begin{definition}[Equality function on $n$-bit strings]
\lean{CommunicationComplexity.Functions.Equality.equality}
\label{CommunicationComplexity.Functions.Equality.equality}
\leanok
\uses{CommunicationComplexity.BoolInput}
For a natural number $n$, \texttt{CommunicationComplexity.Functions.Equality.equality}
is the Boolean function
$\mathrm{equality}_n : \mathrm{BoolInput}\,n \times \mathrm{BoolInput}\,n \to \mathrm{Bool}$
that returns \texttt{true} if and only if Alice's input $x$ equals Bob's input $y$.
\end{definition}

n20108.content:
\begin{definition}[Hash space for the equality protocol]
\lean{CommunicationComplexity.Functions.Equality.HashSpace}
\label{CommunicationComplexity.Functions.Equality.HashSpace}
\leanok
\uses{CommunicationComplexity.BoolInput, CommunicationComplexity.Functions.Hash.HashSpace}
$\mathrm{HashSpace}(n, k)$ is the type of all hash functions from $n$-bit strings
into $\mathrm{Fin}(2^k)$; it serves as the public-randomness space for the
hashing-based equality protocol.
\end{definition}

n20109.content:
\begin{theorem}[Deterministic complexity upper bound for equality]
\lean{CommunicationComplexity.Functions.Equality.communicationComplexity_le}
\label{CommunicationComplexity.Functions.Equality.communicationComplexity_le}
\leanok
\uses{CommunicationComplexity.Deterministic.communicationComplexity, CommunicationComplexity.Deterministic.communicationComplexity_le_clog_card_X_alpha, CommunicationComplexity.Functions.Equality.equality}

For every $n \in \mathbb{N}$,
\[
  D(\mathrm{equality}_n) \;\le\; n + 1.
\]
This follows from the naive protocol in which Alice transmits her entire $n$-bit
input and Bob sends back the single comparison bit.
\end{theorem}

n20110.content:
\begin{theorem}[Deterministic complexity of equality at $n = 0$]
\lean{CommunicationComplexity.Functions.Equality.communicationComplexity_zero}
\label{CommunicationComplexity.Functions.Equality.communicationComplexity_zero}
\leanok
\uses{CommunicationComplexity.Deterministic.Protocol.complexity, CommunicationComplexity.Deterministic.Protocol.run, CommunicationComplexity.Deterministic.communicationComplexity, CommunicationComplexity.Deterministic.communicationComplexity_le_iff, CommunicationComplexity.Functions.Equality.equality}

When $n = 0$ both inputs are the unique empty string, so the equality function
is constantly \texttt{true} and requires zero communication:
\[
  D(\mathrm{equality}_0) = 0.
\]
\end{theorem}

n20112.content:
\begin{theorem}[Exact deterministic complexity of equality]
\lean{CommunicationComplexity.Functions.Equality.communicationComplexity_eq}
\label{CommunicationComplexity.Functions.Equality.communicationComplexity_eq}
\leanok
\uses{CommunicationComplexity.Deterministic.communicationComplexity, CommunicationComplexity.Functions.Equality.communicationComplexity_le, CommunicationComplexity.Functions.Equality.communicationComplexity_zero, CommunicationComplexity.Functions.Equality.equality, CommunicationComplexity.Functions.Equality.le_communicationComplexity}

The deterministic communication complexity of the equality function on $n$-bit
strings is
\[
  D(\mathrm{equality}_n) \;=\; \begin{cases} 0 & \text{if } n = 0, \\ n + 1 & \text{otherwise.} \end{cases}
\]
\end{theorem}

n20113.content:
\begin{definition}[Equality hashing protocol]
\lean{CommunicationComplexity.Functions.Equality.equalityHashProtocol}
\label{CommunicationComplexity.Functions.Equality.equalityHashProtocol}
\leanok
\uses{CommunicationComplexity.BoolInput, CommunicationComplexity.Functions.Equality.HashSpace, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.alice, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.bob, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.output}
$\mathrm{equalityHashProtocol}(n, k)$ is the standard public-coin protocol for
equality in which, given a shared random hash $h \in \mathrm{HashSpace}(n, k)$,
Alice sends $h(x) \in \mathrm{Fin}(2^k)$ and Bob replies with
$\mathtt{decide}(h(y) = h(x))$.
\end{definition}

n20114.content:
\begin{theorem}[Run semantics of the equality hashing protocol]
\lean{CommunicationComplexity.Functions.Equality.equalityHashProtocol_rrun}
\label{CommunicationComplexity.Functions.Equality.equalityHashProtocol_rrun}
\leanok
\uses{CommunicationComplexity.BoolInput, CommunicationComplexity.Functions.Equality.HashSpace, CommunicationComplexity.Functions.Equality.equalityHashProtocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rrun}

For all $x, y : \mathrm{BoolInput}\,n$ and $h : \mathrm{HashSpace}(n,k)$,
\[
  (\mathrm{equalityHashProtocol}\,n\,k).\mathrm{rrun}\,x\,y\,h
  \;=\; \mathtt{decide}(h(x) = h(y)).
\]
\end{theorem}

n20115.content:
\begin{theorem}[Complexity of the equality hashing protocol]
\lean{CommunicationComplexity.Functions.Equality.equalityHashProtocol_complexity}
\label{CommunicationComplexity.Functions.Equality.equalityHashProtocol_complexity}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.Functions.Equality.equalityHashProtocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.alice, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.bob, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.output}

The worst-case communication cost of $\mathrm{equalityHashProtocol}(n, k)$ is
exactly $k + 1$ bits.
\end{theorem}

n20116.content:
\begin{theorem}[Public-coin upper bound for equality via hash parameter]
\lean{CommunicationComplexity.Functions.Equality.publicCoin_communicationComplexity_le_of_hε}
\label{CommunicationComplexity.Functions.Equality.publicCoin_communicationComplexity_le_of_hε}
\leanok
\uses{CommunicationComplexity.BoolInput, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.Functions.Equality.HashSpace, CommunicationComplexity.Functions.Equality.equality, CommunicationComplexity.Functions.Equality.equalityHashProtocol, CommunicationComplexity.Functions.Equality.equalityHashProtocol_complexity, CommunicationComplexity.Functions.Equality.equalityHashProtocol_rrun, CommunicationComplexity.Functions.Hash.collision_prob_le, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.rrun, CommunicationComplexity.PublicCoin.communicationComplexity, CommunicationComplexity.PublicCoin.communicationComplexity_le_of_finiteMessage}

If $\varepsilon > 0$ and $1/2^k < \varepsilon$, then the public-coin
communication complexity of $\mathrm{equality}_n$ with error at most $\varepsilon$
satisfies
\[
  R_\varepsilon(\mathrm{equality}_n) \;\le\; k + 1.
\]
The error bound follows from the collision probability of the random hash family.
\end{theorem}

n20117.content:
\begin{theorem}[Public-coin upper bound for equality via $\varepsilon$]
\lean{CommunicationComplexity.Functions.Equality.publicCoin_communicationComplexity_le}
\label{CommunicationComplexity.Functions.Equality.publicCoin_communicationComplexity_le}
\leanok
\uses{CommunicationComplexity.Functions.Equality.equality, CommunicationComplexity.Functions.Equality.publicCoin_communicationComplexity_le_of_hε, CommunicationComplexity.PublicCoin.communicationComplexity}

For every $n \in \mathbb{N}$ and every $\varepsilon > 0$,
\[
  R_\varepsilon(\mathrm{equality}_n)
  \;\le\; \left\lfloor \log_2\!\left(\lceil \varepsilon^{-1} \rceil + 1\right)\right\rfloor + 1.
\]
\end{theorem}

n20118.content:
\begin{definition}[Word]
\lean{CommunicationComplexity.Word}
\label{CommunicationComplexity.Word}
\leanok
A \emph{word} of length $n$ over alphabet $\alpha$ is a function
$\mathrm{Fin}\,n \to \alpha$; it is an abbreviation for the type of
length-$n$ codewords used throughout this module.
\end{definition}

n20119.content:
\begin{definition}[Hamming ball]
\lean{CommunicationComplexity.hammingBall}
\label{CommunicationComplexity.hammingBall}
\leanok

\uses{CommunicationComplexity.Word}
The \emph{Hamming ball} of radius $r$ centred at $u \in \alpha^n$ is the finset
\[
  B_r(u) = \{v \in \alpha^n : \mathrm{hammingDist}(u,v) \le r\}.
\]
\end{definition}

n20120.content:
\begin{definition}[Hamming sphere]
\lean{CommunicationComplexity.hammingSphere}
\label{CommunicationComplexity.hammingSphere}
\leanok
\uses{CommunicationComplexity.Word}
The \emph{Hamming sphere} of radius $r$ centred at $u \in \alpha^n$ is the finset
\[
  S_r(u) = \{v \in \alpha^n : \mathrm{hammingDist}(u,v) = r\}.
\]
\end{definition}

n20121.content:
\begin{definition}[Ball volume]
\lean{CommunicationComplexity.ballVol}
\label{CommunicationComplexity.ballVol}
\leanok

For a length-$n$ code over an alphabet of size $q$, the \emph{ball volume} at radius $t$ is
\[
  \mathrm{ballVol}(n,t,q) = \sum_{i=0}^{t} \binom{n}{i}(q-1)^i \in \mathbb{N}.
\]
\end{definition}

n20122.content:
\begin{lemma}[Spheres of different radii are disjoint]
\lean{CommunicationComplexity.hammingSpheres_disjoint}
\label{CommunicationComplexity.hammingSpheres_disjoint}
\leanok
\uses{CommunicationComplexity.Word, CommunicationComplexity.hammingSphere}

For any centre $u$ and distinct radii $r \ne t$, the Hamming spheres
$S_r(u)$ and $S_t(u)$ are disjoint finsets.
\end{lemma}

n20123.content:
\begin{lemma}[Spheres are pairwise disjoint]
\lean{CommunicationComplexity.hammingSpheres_pairwise_disjoint}
\label{CommunicationComplexity.hammingSpheres_pairwise_disjoint}
\leanok
\uses{CommunicationComplexity.Word, CommunicationComplexity.hammingSphere, CommunicationComplexity.hammingSpheres_disjoint}

For any centre $u$ and bound $r$, the family $\{S_t(u)\}_{t < r}$ is pairwise disjoint
as a family of finsets indexed by $\{0,\ldots,r-1\}$.
\end{lemma}

n20124.content:
\begin{lemma}[Ball equals disjoint union of spheres]
\lean{CommunicationComplexity.hammingBall_eq_hammingSpheres}
\label{CommunicationComplexity.hammingBall_eq_hammingSpheres}
\leanok
\uses{CommunicationComplexity.Word, CommunicationComplexity.hammingBall, CommunicationComplexity.hammingSphere, CommunicationComplexity.hammingSpheres_pairwise_disjoint}

The Hamming ball of radius $r$ decomposes as the disjoint union
\[
  B_r(u) = \bigsqcup_{k=0}^{r} S_k(u).
\]
\end{lemma}

n20125.content:
\begin{definition}[Support of a pair of words]
\lean{CommunicationComplexity.support}
\label{CommunicationComplexity.support}
\leanok
\uses{CommunicationComplexity.Word}
The \emph{support} of $v$ relative to $u$ is the finset of coordinate positions
where the two words differ:
$\mathrm{support}(u,v) = \{i \in \mathrm{Fin}\,n : u_i \ne v_i\}$.
\end{definition}

n20126.content:
\begin{lemma}[Support card equals Hamming distance]
\lean{CommunicationComplexity.support_dist}
\label{CommunicationComplexity.support_dist}
\leanok
\uses{CommunicationComplexity.Word, CommunicationComplexity.support}

For any two words $u,v$, the Hamming distance equals the cardinality of their support:
$\mathrm{hammingDist}(u,v) = |\mathrm{support}(u,v)|$.
\end{lemma}

n20127.content:
\begin{definition}[Support fiber]
\lean{CommunicationComplexity.supportFiber}
\label{CommunicationComplexity.supportFiber}
\leanok
\uses{CommunicationComplexity.Word, CommunicationComplexity.support}
For a word $u$ and a finset $S \subseteq \mathrm{Fin}\,n$, the \emph{support fiber}
is the set of words that differ from $u$ at exactly the positions in $S$:
$\mathrm{supportFiber}(u,S) = \{v : \mathrm{support}(u,v) = S\}$.
\end{definition}

n20128.content:
\begin{lemma}[Support fibers over distinct sets are disjoint]
\lean{CommunicationComplexity.supportFiber_disjoint}
\label{CommunicationComplexity.supportFiber_disjoint}
\leanok
\uses{CommunicationComplexity.Word, CommunicationComplexity.support, CommunicationComplexity.supportFiber}

If $S \ne T$ are distinct finsets of coordinate positions, then
$\mathrm{supportFiber}(u,S)$ and $\mathrm{supportFiber}(u,T)$ are disjoint finsets.
\end{lemma}

n20129.content:
\begin{lemma}[Sphere as union of support fibers]
\lean{CommunicationComplexity.hammingSphere_eq_biUnion}
\label{CommunicationComplexity.hammingSphere_eq_biUnion}
\leanok
\uses{CommunicationComplexity.Word, CommunicationComplexity.hammingSphere, CommunicationComplexity.support, CommunicationComplexity.supportFiber}

The Hamming sphere of radius $r$ centred at $u$ equals the union of support fibers over
all size-$r$ subsets of $\mathrm{Fin}\,n$:
\[
  S_r(u) = \bigcup_{S \in \binom{[n]}{r}} \mathrm{supportFiber}(u,S).
\]
\end{lemma}

n20130.content:
\begin{definition}[Alternative symbol choices]
\lean{CommunicationComplexity.choices}
\label{CommunicationComplexity.choices}
\leanok
\uses{CommunicationComplexity.Word}
For a word $u$ and position $i$, the \emph{choices} at $i$ is the finset of symbols
$a \in \alpha$ with $a \ne u_i$, i.e.\ the non-trivial alternatives for position $i$.
\end{definition}

n20131.content:
\begin{lemma}[Choices cardinality]
\lean{CommunicationComplexity.choices_card}
\label{CommunicationComplexity.choices_card}
\leanok
\uses{CommunicationComplexity.Word, CommunicationComplexity.choices}

For any word $u$ and position $i$, the number of alternative symbols at $i$ is
$|\mathrm{choices}(u,i)| = |\alpha| - 1$.
\end{lemma}

n20132.content:
\begin{lemma}[Choices partition a support fiber]
\lean{CommunicationComplexity.choices_partition_supportFiber}
\label{CommunicationComplexity.choices_partition_supportFiber}
\leanok
\uses{CommunicationComplexity.Word, CommunicationComplexity.choices, CommunicationComplexity.support, CommunicationComplexity.supportFiber}

For a word $u$, a set $S$ of positions, and a position $i$, the support fiber over
$\{i\} \cup S$ is partitioned by the value chosen at position $i$:
\[
  \mathrm{supportFiber}(u, \{i\} \cup S)
  = \bigsqcup_{a \in \mathrm{choices}(u,i)}
    \{v \in \mathrm{supportFiber}(u,\{i\}\cup S) : v_i = a\}.
\]
\end{lemma}

n20133.content:
\begin{lemma}[Each piece has the same cardinality]
\lean{CommunicationComplexity.piece_card}
\label{CommunicationComplexity.piece_card}
\leanok
\uses{CommunicationComplexity.Word, CommunicationComplexity.choices, CommunicationComplexity.support, CommunicationComplexity.supportFiber}

For $i \notin S$ and any alternative symbol $a \in \mathrm{choices}(u,i)$, the slice
$\{v \in \mathrm{supportFiber}(u,\{i\}\cup S) : v_i = a\}$
has the same cardinality as $\mathrm{supportFiber}(u,S)$.
\end{lemma}

n20134.content:
\begin{lemma}[Support fiber cardinality]
\lean{CommunicationComplexity.card_supportFiber}
\label{CommunicationComplexity.card_supportFiber}
\leanok

\uses{CommunicationComplexity.Word, CommunicationComplexity.choices_card, CommunicationComplexity.choices_partition_supportFiber, CommunicationComplexity.piece_card, CommunicationComplexity.support, CommunicationComplexity.supportFiber}

For any word $u$ and finset $S \subseteq \mathrm{Fin}\,n$,
\[
  |\mathrm{supportFiber}(u,S)| = (|\alpha| - 1)^{|S|}.
\]
\end{lemma}

n20135.content:
\begin{lemma}[Hamming sphere cardinality]
\lean{CommunicationComplexity.hammingSphere_card}
\label{CommunicationComplexity.hammingSphere_card}
\leanok













\uses{CommunicationComplexity.Word, CommunicationComplexity.card_supportFiber, CommunicationComplexity.hammingSphere, CommunicationComplexity.hammingSphere_eq_biUnion, CommunicationComplexity.supportFiber_disjoint}

For any centre $u \in \alpha^n$ and radius $k$,
\[
  |S_k(u)| = \binom{n}{k}(|\alpha|-1)^k.
\]
\end{lemma}

n20136.content:
\begin{lemma}[Hamming ball cardinality]
\lean{CommunicationComplexity.hammingBall_card}
\label{CommunicationComplexity.hammingBall_card}
\leanok
















\uses{CommunicationComplexity.Word, CommunicationComplexity.ballVol, CommunicationComplexity.hammingBall, CommunicationComplexity.hammingSphere, CommunicationComplexity.hammingSphere_card}

For any centre $u \in \alpha^n$ and radius $r$,
\[
  |B_r(u)| = \mathrm{ballVol}(n,r,|\alpha|) = \sum_{i=0}^{r}\binom{n}{i}(|\alpha|-1)^i.
\]
\end{lemma}

n20137.content:
\begin{lemma}[Binary ball volume]
\lean{CommunicationComplexity.ballVol_binary}
\label{CommunicationComplexity.ballVol_binary}
\leanok
\uses{CommunicationComplexity.ballVol}

In the binary case $q = 2$, the ball volume simplifies to
\[
  \mathrm{ballVol}(n,t,2) = \sum_{i=0}^{t}\binom{n}{i}.
\]
\end{lemma}

n20138.content:
\begin{definition}[Boolean function matrix]
\lean{CommunicationComplexity.Deterministic.Rank.boolFunctionMatrix}
\label{CommunicationComplexity.Deterministic.Rank.boolFunctionMatrix}
\leanok
Given a Boolean function $f : X \to Y \to \mathrm{Bool}$, the matrix
$M_f \in \mathbb{R}^{X \times Y}$ is defined by $(M_f)_{x,y} = 1$ if
$f\,x\,y = \mathrm{true}$ and $(M_f)_{x,y} = 0$ otherwise.
\end{definition}

n20139.content:
\begin{definition}[Rank of a Boolean function]
\lean{CommunicationComplexity.Deterministic.Rank.boolFunctionRank}
\label{CommunicationComplexity.Deterministic.Rank.boolFunctionRank}
\leanok
\uses{CommunicationComplexity.Deterministic.Rank.boolFunctionMatrix}
The rank of a Boolean function $f : X \to Y \to \mathrm{Bool}$ is the
$\mathbb{R}$-rank of its $0/1$ matrix $M_f$, i.e.\
$\mathrm{rank}(f) = \mathrm{rank}_{\mathbb{R}}(M_f) \in \mathbb{N}$.
\end{definition}

n20140.content:
\begin{definition}[Rectangle indicator matrix]
\lean{CommunicationComplexity.Deterministic.Rank.rectMatrix}
\label{CommunicationComplexity.Deterministic.Rank.rectMatrix}
\leanok
For a subset $R \subseteq X \times Y$, the matrix $M_R \in \mathbb{R}^{X \times Y}$
is defined by $(M_R)_{x,y} = 1$ if $(x,y) \in R$ and $(M_R)_{x,y} = 0$ otherwise.
\end{definition}

n20141.content:
\begin{theorem}[Rectangle matrix has rank at most one]
\lean{CommunicationComplexity.Deterministic.Rank.rank_rectMatrix_le_one}
\label{CommunicationComplexity.Deterministic.Rank.rank_rectMatrix_le_one}
\leanok
\uses{CommunicationComplexity.Deterministic.Rank.rectMatrix, CommunicationComplexity.Rectangle.IsRectangle}

If $R \subseteq X \times Y$ is a combinatorial rectangle, i.e.\ $R = A \times B$
for some $A \subseteq X$ and $B \subseteq Y$, then $\mathrm{rank}(M_R) \le 1$.
This follows because $M_R$ is an outer product of the indicator vectors of $A$ and $B$.
\end{theorem}

n20142.content:
\begin{theorem}[Rank is subadditive for two matrices]
\lean{Matrix.rank_add_le}
\label{Matrix.rank_add_le}
\leanok

For any two matrices $A, B \in \mathbb{R}^{X \times Y}$,
\[
  \mathrm{rank}(A + B) \le \mathrm{rank}(A) + \mathrm{rank}(B).
\]
\end{theorem}

n20143.content:
\begin{theorem}[Rank is subadditive over finite sums]
\lean{Matrix.rank_sum_le}
\label{Matrix.rank_sum_le}
\leanok
\uses{Matrix.rank_add_le}

For any finite index set $\iota$, a finite set $s \subseteq \iota$, and a family
of matrices $A : \iota \to \mathbb{R}^{X \times Y}$,
\[
  \mathrm{rank}\!\left(\sum_{i \in s} A_i\right) \le \sum_{i \in s} \mathrm{rank}(A_i).
\]
\end{theorem}

n20144.content:
\begin{theorem}[Rank bounded by partition size]
\lean{CommunicationComplexity.Deterministic.Rank.boolFunctionRank_le_ncard}
\label{CommunicationComplexity.Deterministic.Rank.boolFunctionRank_le_ncard}
\leanok
\uses{CommunicationComplexity.Deterministic.Rank.boolFunctionMatrix, CommunicationComplexity.Deterministic.Rank.boolFunctionRank, CommunicationComplexity.Deterministic.Rank.rank_rectMatrix_le_one, CommunicationComplexity.Deterministic.Rank.rectMatrix, CommunicationComplexity.Rectangle.IsMonoPartition, CommunicationComplexity.Rectangle.monoPartition_part_unique, CommunicationComplexity.Rectangle.monoPartition_point_mem, CommunicationComplexity.Rectangle.monoPartition_values_eq, Matrix.rank_sum_le}

If $\mathcal{P}$ is a monochromatic rectangle partition of a Boolean function
$f : X \to Y \to \mathrm{Bool}$, then
$\mathrm{rank}(f) \le |\mathcal{P}|$.
The proof decomposes $M_f$ as a sum of the indicator matrices of the
$1$-coloured rectangles in $\mathcal{P}$ and applies subadditivity of rank together
with the fact that each such rectangle matrix has rank at most $1$.
\end{theorem}

n20145.content:
\begin{theorem}[Rank bounded by $2^n$ when complexity is at most $n$]
\lean{CommunicationComplexity.Deterministic.Rank.boolFunctionRank_le_pow_of_communicationComplexity_le}
\label{CommunicationComplexity.Deterministic.Rank.boolFunctionRank_le_pow_of_communicationComplexity_le}
\leanok
\uses{CommunicationComplexity.Deterministic.Rank.boolFunctionRank, CommunicationComplexity.Deterministic.Rank.boolFunctionRank_le_ncard, CommunicationComplexity.Deterministic.communicationComplexity, CommunicationComplexity.Deterministic.mono_partition_of_communicationComplexity_le}

If the deterministic communication complexity of $f : X \to Y \to \mathrm{Bool}$
is at most $n \in \mathbb{N}$, then $\mathrm{rank}(f) \le 2^n$.
\end{theorem}

n20146.content:
\begin{theorem}[Log-rank lower bound]
\lean{CommunicationComplexity.Deterministic.Rank.clog_boolFunctionRank_le_communicationComplexity}
\label{CommunicationComplexity.Deterministic.Rank.clog_boolFunctionRank_le_communicationComplexity}
\leanok
\uses{CommunicationComplexity.Deterministic.Rank.boolFunctionRank, CommunicationComplexity.Deterministic.Rank.boolFunctionRank_le_pow_of_communicationComplexity_le, CommunicationComplexity.Deterministic.communicationComplexity}

For any Boolean function $f : X \to Y \to \mathrm{Bool}$ (with $X$ finite and $Y$
a \texttt{Fintype}),
\[
  \lceil \log_2 \mathrm{rank}(f) \rceil \;\le\;
  \mathrm{DC}(f),
\]
where $\mathrm{DC}(f)$ is the deterministic communication complexity of $f$,
taken as an element of $\mathbb{N}_\infty$.
\end{theorem}

n20147.content:
\begin{definition}[Newman index space]
\lean{CommunicationComplexity.PublicCoin.newmanIndexSpace}
\label{CommunicationComplexity.PublicCoin.newmanIndexSpace}
\leanok
\uses{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.derandomizationSamples}
Given finite input types $X$ and $Y$ and parameters $\varepsilon, c \in \mathbb{R}$,
the \emph{Newman index space} is $\mathrm{Fin}(\mathtt{derandomizationSamples}\;X\;Y\;\varepsilon\;c)$,
i.e.\ the finite type indexing the table of random seeds that Alice samples from in the Newman
reduction.
\end{definition}

n20148.content:
\begin{definition}[Newman protocol]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.newmanProtocol}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.newmanProtocol}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.toPrivateCoin, CommunicationComplexity.FiniteProbabilitySpace, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.alice, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ApproxComputes, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.exists_good_randomness, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toDeterministic, CommunicationComplexity.PublicCoin.newmanIndexSpace}
Given a public-coin finite-message protocol $p$ over a probability space $\Omega$ that
$\varepsilon$-computes $f : X \to Y \to \alpha$, and a constant $c > 1$, the Newman protocol
is a private-coin finite-message protocol in which Alice draws a random index $i$ from
$\mathtt{newmanIndexSpace}\;X\;Y\;\varepsilon\;c$ and sends it to Bob; both players then
run the $i$-th seed from a fixed table of good randomness values (obtained via a Chernoff
and union-bound argument) through the original public-coin protocol deterministically.
\end{definition}

n20149.content:
\begin{theorem}[Newman protocol approximately computes $f$]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.newmanProtocol_ApproxComputes}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.newmanProtocol_ApproxComputes}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.comap_run, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.run, CommunicationComplexity.FiniteProbabilitySpace, CommunicationComplexity.FiniteProbabilitySpace.measureReal_prod, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.ApproxComputes, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.alice, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.rrun, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ApproxComputes, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.exists_good_randomness, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.newmanProtocol, CommunicationComplexity.PublicCoin.newmanIndexSpace, CommunicationComplexity.uniformOn_univ_measureReal_eq_card_filter}

If $p$ is a public-coin finite-message protocol that $\varepsilon$-computes $f$, and $c > 1$,
then the Newman protocol $(p.\mathtt{newmanProtocol}\;f\;\varepsilon\;c)$
is a private-coin protocol that $(c \cdot \varepsilon)$-computes $f$, i.e.\
for all inputs $x \in X$ and $y \in Y$ the probability that the protocol's output
differs from $f(x, y)$ is at most $c \cdot \varepsilon$.
\end{theorem}

n20150.content:
\begin{theorem}[Newman protocol complexity]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.newmanProtocol_complexity}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.newmanProtocol_complexity}
\leanok
\uses{CommunicationComplexity.Deterministic.FiniteMessage.Protocol.complexity, CommunicationComplexity.Deterministic.FiniteMessage.Protocol.toPrivateCoin_complexity, CommunicationComplexity.FiniteProbabilitySpace, CommunicationComplexity.PrivateCoin.FiniteMessage.Protocol.alice, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.ApproxComputes, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.derandomizationSamples, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.newmanProtocol, CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.toDeterministic_complexity, CommunicationComplexity.PublicCoin.newmanIndexSpace}

If $p$ is a public-coin finite-message protocol that $\varepsilon$-computes $f$, and $c > 1$,
then the communication complexity of the Newman protocol equals
$\lceil \log_2(\mathtt{derandomizationSamples}\;X\;Y\;\varepsilon\;c) \rceil + p.\mathtt{complexity}$,
i.e.\ the original complexity plus the number of bits needed to index the seed table.
\end{theorem}

n20152.content:
\begin{theorem}[Hoeffding tail bound for many events]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.prob_many_events_le}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.prob_many_events_le}
\leanok

Let $(\Omega', \mu)$ be a probability space and let $Y_0, \dots, Y_{t-1} : \Omega' \to
\mathbb{R}$ be mutually independent, a.e.\ $[0,1]$-valued random variables satisfying
$\mathbb{E}[Y_i] \le \varepsilon$ for all $i$, with $\varepsilon \ge 0$ and $c > 1$.
Then
\[
  \mu\!\left\{\omega \;\middle|\; c\,\varepsilon\,t \le \sum_{i=0}^{t-1} Y_i(\omega)\right\}
  \;\le\;
  \exp\!\left(-2(c-1)^2\varepsilon^2 t\right).
\]
\end{theorem}

n20153.content:
\begin{definition}[Derandomization sample count]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.derandomizationSamples}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.derandomizationSamples}
\leanok
Given finite types $X$ and $Y$ and real parameters $\varepsilon, c$, the number of random
samples required for derandomization via Chernoff and union bound is
\[
  t(X, Y, \varepsilon, c) \;=\;
  \left\lceil
    \frac{\log(|X|\cdot|Y|)}{2\,(c-1)^2\,\varepsilon^2}
  \right\rceil_{\!+} + 1,
\]
where $\lceil\cdot\rceil_{+}$ denotes the natural-number ceiling.
\end{definition}

n20154.content:
\begin{theorem}[Existence of good randomness]
\lean{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.exists_good_randomness}
\label{CommunicationComplexity.PublicCoin.FiniteMessage.Protocol.exists_good_randomness}
\leanok
