n20592.content:
\begin{lemma}[Sum of squares equals sum over pairs]
\lean{CommunicationComplexity.Functions.InnerProduct.sum_sq_eq_sum_prod}
\label{CommunicationComplexity.Functions.InnerProduct.sum_sq_eq_sum_prod}
\leanok

For finite types $\alpha$ and $\beta$ and $f : \alpha \to \beta \to \mathbb{R}$,
\[
  \sum_{x : \alpha} \Bigl(\sum_{y : \beta} f(x, y)\Bigr)^2
  \;=\; \sum_{(y_1, y_2) : \beta \times \beta} \sum_{x : \alpha} f(x, y_1) \cdot f(x, y_2).
\]
\end{lemma}

n20595.content:
\begin{lemma}[Weighted orthogonality identity]
\lean{CommunicationComplexity.Functions.InnerProduct.sum_sq_mul_of_orthogonal}
\label{CommunicationComplexity.Functions.InnerProduct.sum_sq_mul_of_orthogonal}
\leanok
\uses{CommunicationComplexity.Functions.InnerProduct.sum_mul_ite_eq_diag, CommunicationComplexity.Functions.InnerProduct.sum_mul_mul, CommunicationComplexity.Functions.InnerProduct.sum_sq_eq_sum_prod}

Let $\phi : \alpha \to \beta \to \mathbb{R}$ be a family of functions satisfying the
orthogonality condition $\sum_{x:\alpha} \phi(x,y)\,\phi(x,z) = c \cdot [\![y=z]\!]$
for a constant $c$.  Then for any weights $b : \beta \to \mathbb{R}$,
\[
  \sum_{x:\alpha} \Bigl(\sum_{y:\beta} b(y)\,\phi(x,y)\Bigr)^2
  \;=\; \sum_{y:\beta} b(y)^2 \cdot c.
\]
\end{lemma}

n20596.content:
\begin{lemma}[Parseval identity for inner product Walsh characters]
