For any $b : \mathrm{BoolInput}\,n \to \mathbb{R}$,
\[
  \sum_{x : \mathrm{BoolInput}\,n}
    \Bigl(\sum_{y : \mathrm{BoolInput}\,n} b(y)\,\mathrm{boolSign}(\mathrm{IP}(x,y))\Bigr)^2
  \;=\; \sum_{y : \mathrm{BoolInput}\,n} b(y)^2 \cdot 2^n.
\]
\end{lemma}

n20597.content:
\begin{lemma}[Second moment of indicator-weighted Walsh sum is bounded]
\lean{CommunicationComplexity.Functions.InnerProduct.sum_sq_indicator_mul_boolSign_innerProduct_le}
