n20598.content:
\begin{lemma}[Integral second moment bound for discrepancy computation]
\lean{CommunicationComplexity.Functions.InnerProduct.integral_sq_indicator_mul_boolSign_innerProduct_le}
\label{CommunicationComplexity.Functions.InnerProduct.integral_sq_indicator_mul_boolSign_innerProduct_le}
