For any set $B \subseteq \mathrm{BoolInput}\,n$,
\[
  \int_{x} \Bigl(\int_{y}
    \mathbf{1}_B(y)\,\mathrm{boolSign}(\mathrm{IP}(x,y))\Bigr)^2
  \;\le\; \frac{1}{2^n}.
\]
This is the key second-moment estimate used in the discrepancy bound.
\end{lemma}

n20599.content:
\begin{lemma}[Discrepancy of a rectangle as a product integral]
\lean{CommunicationComplexity.Functions.InnerProduct.discrepancy_prod_eq_integral}
\label{CommunicationComplexity.Functions.InnerProduct.discrepancy_prod_eq_integral}
\leanok
\uses{CommunicationComplexity.BoolInput, CommunicationComplexity.Functions.InnerProduct.innerProduct, CommunicationComplexity.boolSign, CommunicationComplexity.discrepancy}

For sets $A, B \subseteq \mathrm{BoolInput}\,n$, the discrepancy of the rectangle
$A \times B$ for the inner product function equals
\[
  \mathrm{disc}(\mathrm{IP}, A \times B)
  = \int_x \mathbf{1}_A(x)
      \int_y \mathbf{1}_B(y)\,\mathrm{boolSign}(\mathrm{IP}(x,y)).
\]
\end{lemma}

