If $k, n \in \mathbb{N}$ and $\varepsilon \in \mathbb{R}$ satisfy
$2^k \cdot \sqrt{1/2^n} < 1 - 2\varepsilon$, then
\[
  k \;<\; \mathrm{CC}_{\varepsilon}^{\mathrm{pub}}(\mathrm{IP}_n),
\]
providing a public-coin communication complexity lower bound for the inner product
function via the discrepancy method.
\end{theorem}

n20603.content:
\begin{theorem}[KL divergence as log-likelihood ratio sum (absolutely continuous case)]
\lean{CommunicationComplexity.klDiv_eq_sum_llr_of_ac}
\label{CommunicationComplexity.klDiv_eq_sum_llr_of_ac}
\leanok
\uses{CommunicationComplexity.FiniteMeasureSpace}

Let $\Omega$ be a finite measurable space and let $\mu, \nu$ be finite measures on $\Omega$
with $\mu \ll \nu$.  Then
\[
  D_{\mathrm{KL}}(\mu \,\|\, \nu)
  = \mathrm{ofReal}\!\left(
      \sum_{\omega : \Omega} \mu.\mathrm{real}\,\{\omega\} \cdot \mathrm{llr}(\mu,\nu,\omega)
      + \nu.\mathrm{real}\,\mathrm{univ}
      - \mu.\mathrm{real}\,\mathrm{univ}
    \right),
\]
where $\mathrm{llr}(\mu,\nu,\omega) = \log \frac{d\mu}{d\nu}(\omega)$ is the
log-likelihood ratio at $\omega$.
\end{theorem}

n20604.content:
\begin{theorem}[KL divergence as log-likelihood ratio sum]
\lean{CommunicationComplexity.FiniteMeasureSpace.klDiv_eq_sum_llr}
\label{CommunicationComplexity.FiniteMeasureSpace.klDiv_eq_sum_llr}
\leanok
\uses{CommunicationComplexity.FiniteMeasureSpace, CommunicationComplexity.FiniteMeasureSpace.absolutelyContinuous_iff_forall_singletons, CommunicationComplexity.klDiv_eq_sum_llr_of_ac}

Let $\Omega$ be a finite measurable space and let $\mu, \nu$ be finite measures on $\Omega$.
Then
\[
  D_{\mathrm{KL}}(\mu \,\|\, \nu)
  = \begin{cases}
      \infty & \text{if } \exists\,\omega,\; \nu\{\omega\} = 0 \text{ and } \mu\{\omega\} \neq 0,\\[4pt]
      \mathrm{ofReal}\!\displaystyle\left(
        \sum_{\omega}\mu.\mathrm{real}\,\{\omega\}\cdot\mathrm{llr}(\mu,\nu,\omega)
        +\nu.\mathrm{real}\,\mathrm{univ}-\mu.\mathrm{real}\,\mathrm{univ}
      \right) & \text{otherwise.}
    \end{cases}
\]
\end{theorem}

n20605.content:
\begin{theorem}[KL divergence between PMFs as log-likelihood ratio sum]
\lean{CommunicationComplexity.FiniteMeasureSpace.pmf_klDiv_eq_sum_llr}
\label{CommunicationComplexity.FiniteMeasureSpace.pmf_klDiv_eq_sum_llr}
\leanok
\uses{CommunicationComplexity.FiniteMeasureSpace, CommunicationComplexity.FiniteMeasureSpace.klDiv_eq_sum_llr}

Let $\Omega$ be a finite measurable space and let $p, q$ be PMFs on $\Omega$.  Then
\[
  D_{\mathrm{KL}}(p \,\|\, q)
  = \begin{cases}
      \infty & \text{if } \exists\,\omega,\; q(\omega) = 0 \text{ and } p(\omega) \neq 0,\\[4pt]
      \mathrm{ofReal}\!\displaystyle\left(
        \sum_{\omega} p(\omega).\mathrm{toReal} \cdot \mathrm{llr}(p,q,\omega)
      \right) & \text{otherwise.}
    \end{cases}
\]
\end{theorem}

n20606.content:
\begin{theorem}[Radon--Nikodym derivative equals singleton mass ratio]
\lean{CommunicationComplexity.rnDeriv_toReal_eq_singleton_ratio}
\label{CommunicationComplexity.rnDeriv_toReal_eq_singleton_ratio}
\leanok
\uses{CommunicationComplexity.FiniteMeasureSpace}

Let $\Omega$ be a finite measurable space, $\mu \ll \nu$ finite measures, and $\omega \in \Omega$
with $\nu\{\omega\} \neq 0$.  Then the real-valued Radon--Nikodym derivative satisfies
\[
  \left(\frac{d\mu}{d\nu}(\omega)\right).\mathrm{toReal}
  = \frac{\mu.\mathrm{real}\,\{\omega\}}{\nu.\mathrm{real}\,\{\omega\}}.
\]
\end{theorem}

n20607.content:
\begin{theorem}[Singleton mass times log-likelihood ratio equals log of mass ratio]
\lean{CommunicationComplexity.singleton_mass_mul_llr_eq_log_ratio}
\label{CommunicationComplexity.singleton_mass_mul_llr_eq_log_ratio}
\leanok
\uses{CommunicationComplexity.FiniteMeasureSpace, CommunicationComplexity.rnDeriv_toReal_eq_singleton_ratio}

Let $\Omega$ be a finite measurable space, $\mu \ll \nu$ finite measures, and $\omega \in \Omega$.
Then
\[
  \mu.\mathrm{real}\,\{\omega\} \cdot \mathrm{llr}(\mu,\nu,\omega)
  = \mu.\mathrm{real}\,\{\omega\}
    \cdot \log\!\left(
      \frac{\mu.\mathrm{real}\,\{\omega\}}{\nu.\mathrm{real}\,\{\omega\}}
    \right).
\]
\end{theorem}

n20608.content:
\begin{theorem}[KL divergence as logarithmic mass ratio sum]
\lean{CommunicationComplexity.FiniteMeasureSpace.klDiv_eq_sum_log}
\label{CommunicationComplexity.FiniteMeasureSpace.klDiv_eq_sum_log}
\leanok
\uses{CommunicationComplexity.FiniteMeasureSpace, CommunicationComplexity.FiniteMeasureSpace.absolutelyContinuous_iff_forall_singletons, CommunicationComplexity.FiniteMeasureSpace.klDiv_eq_sum_llr, CommunicationComplexity.singleton_mass_mul_llr_eq_log_ratio}

Let $\Omega$ be a finite measurable space and let $\mu, \nu$ be finite measures on $\Omega$.
Then
\[
  D_{\mathrm{KL}}(\mu \,\|\, \nu)
  = \begin{cases}
      \infty & \text{if } \exists\,\omega,\; \nu\{\omega\} = 0 \text{ and } \mu\{\omega\} \neq 0,\\[4pt]
      \mathrm{ofReal}\!\displaystyle\left(
        \sum_{\omega}
          \mu.\mathrm{real}\,\{\omega\}
          \cdot\log\!\frac{\mu.\mathrm{real}\,\{\omega\}}{\nu.\mathrm{real}\,\{\omega\}}
        +\nu.\mathrm{real}\,\mathrm{univ}-\mu.\mathrm{real}\,\mathrm{univ}
      \right) & \text{otherwise.}
    \end{cases}
\]
\end{theorem}

n20609.content:
\begin{theorem}[KL divergence is finite to full-support probability measure]
\lean{CommunicationComplexity.FiniteMeasureSpace.klDiv_ne_top_of_forall_toPMF_ne_zero}
\label{CommunicationComplexity.FiniteMeasureSpace.klDiv_ne_top_of_forall_toPMF_ne_zero}
\leanok
