n20611.content:
\begin{theorem}[Boolean KL divergence matches PFR \texttt{KLDiv}]
\lean{ProbabilityTheory.toReal_klDiv_bool_eq_KLDiv}
\label{ProbabilityTheory.toReal_klDiv_bool_eq_KLDiv}
\leanok
\uses{CommunicationComplexity.FiniteMeasureSpace.klDiv_eq_sum_log}

Let $\mu, \nu$ be probability measures on $\mathrm{Bool}$ with $\nu$ of full support.  Then
\[
  \bigl(D_{\mathrm{KL}}(\mu \,\|\, \nu)\bigr).\mathrm{toReal}
  = \mathrm{KL}[\mathrm{id};\mu \,\#\, \mathrm{id};\nu],
\]
where the right-hand side is the PFR real-valued KL divergence of the identity random variable.
\end{theorem}

n20612.content:
\begin{theorem}[KL divergence of pushed-forward Boolean variable matches PFR \texttt{KLDiv}]
\lean{ProbabilityTheory.toReal_klDiv_map_bool_eq_KLDiv_of_measureReal_ne_zero}
\label{ProbabilityTheory.toReal_klDiv_map_bool_eq_KLDiv_of_measureReal_ne_zero}
\leanok
\uses{ProbabilityTheory.toReal_klDiv_bool_eq_KLDiv}

Let $\mu$ be a finite measure on a measurable space $\Omega$, $X : \Omega \to \mathrm{Bool}$
a measurable function, $S \subseteq \Omega$ a set with $\mu.\mathrm{real}\,S \neq 0$, and $\nu$
a full-support probability measure on $\mathrm{Bool}$.  Then
\[
  \bigl(D_{\mathrm{KL}}(X_*(\mu[\cdot|S]) \,\|\, \nu)\bigr).\mathrm{toReal}
  = \mathrm{KL}[X;\mu[\cdot|S] \,\#\, \mathrm{id};\nu].
\]
\end{theorem}

n20613.content:
\begin{definition}[Radon-Nikodym density]
\lean{CommunicationComplexity.rnDensity}
\label{CommunicationComplexity.rnDensity}
\leanok
For two probability measures $\mu$ and $\nu$ on a measurable space $\Omega$, the
\emph{Radon-Nikodym density} $\mathrm{rnDensity}(\mu,\nu)(x) \in \mathbb{R}$ is
the real part of the Radon-Nikodym derivative $\frac{d\mu}{d\nu}(x)$, obtained by
converting the extended non-negative real value $\mu.\mathrm{rnDeriv}\,\nu\,x$
to a real number via \texttt{ENNReal.toReal}.
\end{definition}

