\uses{CommunicationComplexity.integrable_rnDensity, CommunicationComplexity.rnDensity}

If $\mu \ll \nu$ and $S \subseteq \Omega$ is measurable, then
\[
  \mu(S) - \nu(S) \;=\; \int_S \bigl(\mathrm{rnDensity}(\mu,\nu)(x) - 1\bigr)\,d\nu.
\]
\end{theorem}

n20622.content:
\begin{theorem}[Nonneg-part integral equals half the $L^1$ norm when mean is zero]
\lean{CommunicationComplexity.integral_nonneg_part_eq_half_integral_abs_of_integral_eq_zero}
\label{CommunicationComplexity.integral_nonneg_part_eq_half_integral_abs_of_integral_eq_zero}
\leanok

Let $\mu$ be a finite measure and $g : \Omega \to \mathbb{R}$ measurable, integrable,
and mean-zero ($\int g\,d\mu = 0$).  Then
\[
  \int_{\{x\,:\,g(x)\ge 0\}} g(x)\,d\mu \;=\; \tfrac{1}{2}\int |g(x)|\,d\mu.
\]
\end{theorem}

n20623.content:
\begin{theorem}[Supremum of absolute set-integrals equals nonneg part when mean is zero]
\lean{CommunicationComplexity.sSup_abs_setIntegral_eq_nonneg_part_of_integral_eq_zero}
\label{CommunicationComplexity.sSup_abs_setIntegral_eq_nonneg_part_of_integral_eq_zero}
\leanok

Let $\mu$ be a finite measure and $g$ measurable, integrable, and mean-zero.  Then
\[
  \sup_{S\text{ measurable}}\Bigl|\int_S g\,d\mu\Bigr|
  \;=\; \int_{\{g \ge 0\}} g\,d\mu.
\]
\end{theorem}

n20624.content:
\begin{definition}[Density absolute integral]
\lean{CommunicationComplexity.densityAbsIntegral}
\label{CommunicationComplexity.densityAbsIntegral}
\leanok
\uses{CommunicationComplexity.rnDensity}
The quantity $\mathrm{densityAbsIntegral}(\mu,\nu) := \int |\mathrm{rnDensity}(\mu,\nu)(x) - 1|\,d\nu$ is the $L^1(\nu)$-distance of the Radon-Nikodym density from $1$.
\end{definition}

n20625.content:
\begin{definition}[Density positive set]
\lean{CommunicationComplexity.densityPositiveSet}
\label{CommunicationComplexity.densityPositiveSet}
\leanok
\uses{CommunicationComplexity.rnDensity}
The \emph{density positive set} is $\{x \in \Omega : \mathrm{rnDensity}(\mu,\nu)(x) \ge 1\}$,
the region where $\mu$ locally dominates $\nu$.
\end{definition}

n20626.content:
\begin{theorem}[Density positive set is measurable]
\lean{CommunicationComplexity.measurableSet_densityPositiveSet}
\label{CommunicationComplexity.measurableSet_densityPositiveSet}
\leanok
\uses{CommunicationComplexity.densityPositiveSet, CommunicationComplexity.measurable_rnDensity}

The density positive set $\{x : \mathrm{rnDensity}(\mu,\nu)(x) \ge 1\}$ is a measurable subset of $\Omega$.
\end{theorem}

n20627.content:
\begin{definition}[Density positive integral]
\lean{CommunicationComplexity.densityPositiveIntegral}
\label{CommunicationComplexity.densityPositiveIntegral}
\leanok
\uses{CommunicationComplexity.densityPositiveSet, CommunicationComplexity.rnDensity}
The \emph{density positive integral} is
$\mathrm{densityPositiveIntegral}(\mu,\nu) := \int_{\mathrm{densityPositiveSet}} (\mathrm{rnDensity}(\mu,\nu)(x)-1)\,d\nu$,
the excess mass of $\mu$ over $\nu$ on the region where $\mu$ dominates.
\end{definition}

n20628.content:
\begin{theorem}[TV distance supremum equals density positive integral under absolute continuity]
\lean{CommunicationComplexity.tvDistanceSup_eq_densityPositiveIntegral_of_ac}
\label{CommunicationComplexity.tvDistanceSup_eq_densityPositiveIntegral_of_ac}
\leanok
\uses{CommunicationComplexity.densityPositiveIntegral, CommunicationComplexity.densityPositiveSet, CommunicationComplexity.integrable_rnDensity_sub_one, CommunicationComplexity.integral_rnDensity_sub_one_eq_zero_of_ac, CommunicationComplexity.measurable_rnDensity, CommunicationComplexity.measureReal_sub_eq_setIntegral_rnDensity_sub_one, CommunicationComplexity.rnDensity, CommunicationComplexity.sSup_abs_setIntegral_eq_nonneg_part_of_integral_eq_zero, CommunicationComplexity.tvDistanceSup}

If $\mu \ll \nu$, then
$\mathrm{tvDistanceSup}(\mu,\nu) = \mathrm{densityPositiveIntegral}(\mu,\nu)$.
\end{theorem}

n20629.content:
\begin{theorem}[TV distance equals density positive integral under absolute continuity]
\lean{CommunicationComplexity.tvDistance_eq_densityPositiveIntegral_of_ac}
\label{CommunicationComplexity.tvDistance_eq_densityPositiveIntegral_of_ac}
\leanok
\uses{CommunicationComplexity.TVDistance.tvDistance_eq_tvDistanceSup, CommunicationComplexity.densityPositiveIntegral, CommunicationComplexity.tvDistance, CommunicationComplexity.tvDistanceSup_eq_densityPositiveIntegral_of_ac}

If $\mu \ll \nu$, then $\mathrm{TV}(\mu,\nu) = \mathrm{densityPositiveIntegral}(\mu,\nu)$.
\end{theorem}

n20630.content:
\begin{theorem}[Density positive integral equals half the density absolute integral]
\lean{CommunicationComplexity.densityPositiveIntegral_eq_half_densityAbsIntegral_of_ac}
\label{CommunicationComplexity.densityPositiveIntegral_eq_half_densityAbsIntegral_of_ac}
\leanok
\uses{CommunicationComplexity.densityAbsIntegral, CommunicationComplexity.densityPositiveIntegral, CommunicationComplexity.densityPositiveSet, CommunicationComplexity.integrable_rnDensity_sub_one, CommunicationComplexity.integral_nonneg_part_eq_half_integral_abs_of_integral_eq_zero, CommunicationComplexity.integral_rnDensity_sub_one_eq_zero_of_ac, CommunicationComplexity.measurable_rnDensity, CommunicationComplexity.rnDensity}

If $\mu \ll \nu$, then
$\mathrm{densityPositiveIntegral}(\mu,\nu) = \tfrac{1}{2}\,\mathrm{densityAbsIntegral}(\mu,\nu)$.
\end{theorem}

n20631.content:
\begin{theorem}[Pointwise KL inequality: $u y \le \mathrm{klFun}(u) + e^y - 1$]
\lean{CommunicationComplexity.mul_le_klFun_add_exp_sub_one}
\label{CommunicationComplexity.mul_le_klFun_add_exp_sub_one}
\leanok

For real numbers $u \ge 0$ and $y$, one has $u \cdot y \le \mathrm{klFun}(u) + e^y - 1$,
where $\mathrm{klFun}(u) = u \ln u - u + 1$.
\end{theorem}

n20632.content:
\begin{theorem}[Integral of $e^{tX - \Lambda(t)}$ equals one]
\lean{CommunicationComplexity.integral_exp_sub_cgf_eq_one}
\label{CommunicationComplexity.integral_exp_sub_cgf_eq_one}
\leanok

Let $\mu$ be a probability measure, $X : \Omega \to \mathbb{R}$ and $t \in \mathbb{R}$.
If $e^{tX}$ is $\mu$-integrable, then
$\int e^{t X(x) - \Lambda_\mu(t)}\,d\mu = 1$,
where $\Lambda_\mu(t) = \log\int e^{tX}\,d\mu$ is the cumulant generating function.
\end{theorem}

n20633.content:
\begin{theorem}[$e^{tX - \Lambda(t)}$ is integrable]
\lean{CommunicationComplexity.integrable_exp_sub_cgf}
\label{CommunicationComplexity.integrable_exp_sub_cgf}
\leanok

If $e^{tX}$ is $\mu$-integrable, then so is $x \mapsto e^{t X(x) - \Lambda_\mu(t)}$.
\end{theorem}

n20634.content:
\begin{theorem}[Variational bound: $t \int f X\,d\mu \le \int \mathrm{klFun}(f)\,d\mu + \Lambda_\mu(t)$]
\lean{CommunicationComplexity.variational_integral_mul_le_integral_klFun_add_cgf}
\label{CommunicationComplexity.variational_integral_mul_le_integral_klFun_add_cgf}
\leanok
\uses{CommunicationComplexity.integrable_exp_sub_cgf, CommunicationComplexity.integral_exp_sub_cgf_eq_one, CommunicationComplexity.mul_le_klFun_add_exp_sub_one}

Let $f, X : \Omega \to \mathbb{R}$ with $f \ge 0$ and $\int f\,d\mu = 1$.  Under suitable
integrability conditions on $f$, $X$, and $e^{tX}$,
\[
  t \int f(x)\,X(x)\,d\mu \;\le\; \int \mathrm{klFun}(f(x))\,d\mu + \Lambda_\mu(t).
\]
\end{theorem}

n20635.content:
\begin{theorem}[$\tfrac{1}{2}(\int|f-1|)^2 \le \int \mathrm{klFun}(f)$]
\lean{CommunicationComplexity.half_integral_abs_sub_one_sq_le_integral_klFun}
\label{CommunicationComplexity.half_integral_abs_sub_one_sq_le_integral_klFun}
\leanok
\uses{CommunicationComplexity.variational_integral_mul_le_integral_klFun_add_cgf}

Let $f : \Omega \to \mathbb{R}$ with $f \ge 0$, $\int f\,d\mu = 1$, $f$ integrable,
and $\mathrm{klFun}(f)$ integrable.  Then
\[
  \tfrac{1}{2}\Bigl(\int |f(x) - 1|\,d\mu\Bigr)^2 \;\le\; \int \mathrm{klFun}(f(x))\,d\mu.
\]
\end{theorem}

n20636.content:
\begin{theorem}[TV distance equals half density absolute integral under absolute continuity]
\lean{CommunicationComplexity.tvDistance_eq_half_densityAbsIntegral_of_ac}
\label{CommunicationComplexity.tvDistance_eq_half_densityAbsIntegral_of_ac}
\leanok
\uses{CommunicationComplexity.densityAbsIntegral, CommunicationComplexity.densityPositiveIntegral_eq_half_densityAbsIntegral_of_ac, CommunicationComplexity.tvDistance, CommunicationComplexity.tvDistance_eq_densityPositiveIntegral_of_ac}

If $\mu \ll \nu$, then
$\mathrm{TV}(\mu,\nu) = \tfrac{1}{2}\,\mathrm{densityAbsIntegral}(\mu,\nu)$.
\end{theorem}

n20637.content:
\begin{theorem}[$\tfrac{1}{2}(\mathrm{densityAbsIntegral})^2 \le \int\mathrm{klFun}(\mathrm{rnDensity})$]
\lean{CommunicationComplexity.half_densityAbsIntegral_sq_le_integral_klFun_rnDensity}
\label{CommunicationComplexity.half_densityAbsIntegral_sq_le_integral_klFun_rnDensity}
\leanok
\uses{CommunicationComplexity.densityAbsIntegral, CommunicationComplexity.half_integral_abs_sub_one_sq_le_integral_klFun, CommunicationComplexity.integrable_rnDensity, CommunicationComplexity.integral_rnDensity_eq_one_of_ac, CommunicationComplexity.measurable_rnDensity, CommunicationComplexity.rnDensity, CommunicationComplexity.rnDensity_nonneg}

If $\mu \ll \nu$ and the log-likelihood ratio $\mathrm{llr}(\mu,\nu)$ is $\mu$-integrable,
then
\[
  \tfrac{1}{2}\,\mathrm{densityAbsIntegral}(\mu,\nu)^2
  \;\le\;
  \int \mathrm{klFun}\bigl(\mathrm{rnDensity}(\mu,\nu)(x)\bigr)\,d\nu.
\]
\end{theorem}

n20638.content:
\begin{theorem}[KL-function integral equals log-likelihood integral]
\lean{CommunicationComplexity.integral_klFun_rnDeriv_eq_kl_integral}
\label{CommunicationComplexity.integral_klFun_rnDeriv_eq_kl_integral}
\leanok
\uses{CommunicationComplexity.rnDensity}

If $\mu \ll \nu$ and $\mathrm{llr}(\mu,\nu)$ is $\mu$-integrable, then
\[
  \int \mathrm{klFun}\bigl(\mathrm{rnDensity}(\mu,\nu)(x)\bigr)\,d\nu
  \;=\;
  \int \mathrm{llr}(\mu,\nu)(x)\,d\mu.
\]
\end{theorem}

n20639.content:
\begin{theorem}[Density $L^1$ Pinsker bound via KL integral]
\lean{CommunicationComplexity.density_l1_pinsker_le_kl_integral}
\label{CommunicationComplexity.density_l1_pinsker_le_kl_integral}
\leanok
\uses{CommunicationComplexity.densityAbsIntegral, CommunicationComplexity.half_densityAbsIntegral_sq_le_integral_klFun_rnDensity, CommunicationComplexity.integral_klFun_rnDeriv_eq_kl_integral, CommunicationComplexity.rnDensity}

If $\mu \ll \nu$ and $\mathrm{llr}(\mu,\nu)$ is $\mu$-integrable, then
\[
  \tfrac{1}{2}\,\mathrm{densityAbsIntegral}(\mu,\nu)^2
  \;\le\; \int \mathrm{llr}(\mu,\nu)(x)\,d\mu.
\]
\end{theorem}

n20640.content:
\begin{theorem}[Real Pinsker inequality under absolute continuity and integrability]
\lean{CommunicationComplexity.real_pinsker_inequality_of_ac_of_integrable}
\label{CommunicationComplexity.real_pinsker_inequality_of_ac_of_integrable}
\leanok
\uses{CommunicationComplexity.densityAbsIntegral, CommunicationComplexity.density_l1_pinsker_le_kl_integral, CommunicationComplexity.tvDistance, CommunicationComplexity.tvDistance_eq_half_densityAbsIntegral_of_ac}

If $\mu \ll \nu$ and $\mathrm{llr}(\mu,\nu)$ is $\mu$-integrable, then
\[
  2\,\mathrm{TV}(\mu,\nu)^2 \;\le\; \int \mathrm{llr}(\mu,\nu)(x)\,d\mu.
\]
\end{theorem}

n20641.content:
\begin{theorem}[Pinsker inequality ($\mathbb{R}_{\ge 0}^\infty$ form) under absolute continuity and integrability]
\lean{CommunicationComplexity.pinsker_inequality_of_ac_of_integrable}
\label{CommunicationComplexity.pinsker_inequality_of_ac_of_integrable}
\leanok
\uses{CommunicationComplexity.real_pinsker_inequality_of_ac_of_integrable, CommunicationComplexity.tvDistance}

If $\mu \ll \nu$ and $\mathrm{llr}(\mu,\nu)$ is $\mu$-integrable, then
\[
  \mathrm{ofReal}\bigl(2\,\mathrm{TV}(\mu,\nu)^2\bigr) \;\le\; \mathrm{KL}(\mu \| \nu)
\]
in $\mathbb{R}_{\ge 0}^\infty$.
\end{theorem}

n20642.content:
\begin{theorem}[Pinsker inequality under absolute continuity]
\lean{CommunicationComplexity.pinsker_inequality_of_ac}
\label{CommunicationComplexity.pinsker_inequality_of_ac}
\leanok
\uses{CommunicationComplexity.pinsker_inequality_of_ac_of_integrable, CommunicationComplexity.tvDistance}

If $\mu \ll \nu$ (without any integrability assumption), then
$\mathrm{ofReal}(2\,\mathrm{TV}(\mu,\nu)^2) \le \mathrm{KL}(\mu \| \nu)$ in $\mathbb{R}_{\ge 0}^\infty$.
\end{theorem}

n20643.content:
\begin{theorem}[Pinsker's inequality]
\lean{CommunicationComplexity.pinsker_inequality}
\label{CommunicationComplexity.pinsker_inequality}
\leanok
\uses{CommunicationComplexity.pinsker_inequality_of_ac, CommunicationComplexity.tvDistance}

For any two probability measures $\mu$ and $\nu$ on $\Omega$,
\[
  \mathrm{ofReal}\bigl(2\,\mathrm{TV}(\mu,\nu)^2\bigr) \;\le\; \mathrm{KL}(\mu \| \nu),
\]
where the inequality is in $\mathbb{R}_{\ge 0}^\infty$ and KL divergence uses natural logarithms.
\end{theorem}

n20644.content:
\begin{theorem}[Real-valued Pinsker corollary for finite KL divergence]
\lean{CommunicationComplexity.two_mul_tvDistance_sq_le_toReal_klDiv}
\label{CommunicationComplexity.two_mul_tvDistance_sq_le_toReal_klDiv}
\leanok
\uses{CommunicationComplexity.pinsker_inequality, CommunicationComplexity.tvDistance}

If $\mathrm{KL}(\mu \| \nu) \ne \infty$, then
\[
  2\,\mathrm{TV}(\mu,\nu)^2 \;\le\; \mathrm{KL}(\mu \| \nu).\mathrm{toReal},
\]
providing a real-valued form of Pinsker's inequality convenient when finiteness of
the KL divergence is already known.
\end{theorem}

n20645.content:
\begin{definition}[Signed measure difference]
\lean{CommunicationComplexity.signedMeasureDiff}
\label{CommunicationComplexity.signedMeasureDiff}
\leanok
Given two probability measures $\mu$ and $\nu$ on a measurable space $\Omega$, the
\emph{signed measure difference} $\mu - \nu$ is the signed measure on $\Omega$ obtained
by taking the difference of $\mu$ and $\nu$ as measures.
\end{definition}

n20646.content:
\begin{definition}[Total variation distance]
\lean{CommunicationComplexity.tvDistance}
\label{CommunicationComplexity.tvDistance}
\leanok
\uses{CommunicationComplexity.signedMeasureDiff}
The \emph{total variation distance} between two probability measures $\mu$ and $\nu$ on
$\Omega$ is defined as $\tfrac{1}{2}$ times the total variation norm of the signed
measure $\mu - \nu$, i.e.\
$\mathrm{TV}(\mu,\nu) = \tfrac{1}{2}\|\mu - \nu\|_{\mathrm{TV}}$.
\end{definition}

n20647.content:
\begin{definition}[Total variation distance via event supremum]
\lean{CommunicationComplexity.tvDistanceSup}
\label{CommunicationComplexity.tvDistanceSup}
\leanok
The \emph{supremum definition} of total variation distance between $\mu$ and $\nu$ is
\[
  \mathrm{TV}_{\sup}(\mu,\nu)
  \;=\; \sup\bigl\{|\mu(S) - \nu(S)| : S \subseteq \Omega \text{ measurable}\bigr\}.
\]
\end{definition}

n20648.content:
\begin{lemma}[Signed measure via Jordan decomposition]
\lean{CommunicationComplexity.TVDistance.signedMeasure_apply_eq_posPart_sub_negPart}
\label{CommunicationComplexity.TVDistance.signedMeasure_apply_eq_posPart_sub_negPart}
\leanok

For any signed measure $s$ on $\Omega$ and any measurable set $S$, the value $s(S)$
equals the difference of its Jordan positive and negative parts:
$s(S) = s^+(S) - s^-(S)$.
\end{lemma}

n20649.content:
\begin{lemma}[Signed difference vanishes on the whole space]
\lean{CommunicationComplexity.TVDistance.signedMeasureDiff_univ}
\label{CommunicationComplexity.TVDistance.signedMeasureDiff_univ}
\leanok
\uses{CommunicationComplexity.signedMeasureDiff}

For any two probability measures $\mu$ and $\nu$, the signed difference satisfies
$(\mu - \nu)(\Omega) = 0$.
\end{lemma}

n20650.content:
\begin{lemma}[Jordan parts agree on the whole space]
\lean{CommunicationComplexity.TVDistance.jordan_posPart_real_univ_eq_negPart_real_univ}
\label{CommunicationComplexity.TVDistance.jordan_posPart_real_univ_eq_negPart_real_univ}
\leanok
\uses{CommunicationComplexity.TVDistance.signedMeasureDiff_univ, CommunicationComplexity.TVDistance.signedMeasure_apply_eq_posPart_sub_negPart, CommunicationComplexity.signedMeasureDiff}

For probability measures $\mu$ and $\nu$, the Jordan positive part and the Jordan
negative part of $\mu - \nu$ assign equal real mass to $\Omega$:
$((\mu-\nu)^+)(\Omega) = ((\mu-\nu)^-)(\Omega)$.
\end{lemma}

n20651.content:
\begin{lemma}[Total variation mass of the whole space]
\lean{CommunicationComplexity.TVDistance.totalVariation_real_univ}
\label{CommunicationComplexity.TVDistance.totalVariation_real_univ}
\leanok

For any signed measure $s$, the real-valued total variation mass of $\Omega$ equals the
sum of the Jordan positive and negative part masses:
$\|s\|_{\mathrm{TV}}(\Omega) = s^+(\Omega) + s^-(\Omega)$.
\end{lemma}

n20652.content:
\begin{lemma}[Half total variation equals positive Jordan part]
\lean{CommunicationComplexity.TVDistance.half_totalVariation_real_univ_eq_posPart_real_univ}
\label{CommunicationComplexity.TVDistance.half_totalVariation_real_univ_eq_posPart_real_univ}
\leanok
\uses{CommunicationComplexity.TVDistance.jordan_posPart_real_univ_eq_negPart_real_univ, CommunicationComplexity.TVDistance.totalVariation_real_univ, CommunicationComplexity.signedMeasureDiff}

For probability measures $\mu$ and $\nu$,
$\tfrac{1}{2}\|\mu-\nu\|_{\mathrm{TV}}(\Omega) = ((\mu-\nu)^+)(\Omega)$.
\end{lemma}

n20653.content:
\begin{lemma}[Event gap bounded by half total variation]
\lean{CommunicationComplexity.TVDistance.event_abs_signedMeasureDiff_le_half_totalVariation}
\label{CommunicationComplexity.TVDistance.event_abs_signedMeasureDiff_le_half_totalVariation}
\leanok
\uses{CommunicationComplexity.TVDistance.half_totalVariation_real_univ_eq_posPart_real_univ, CommunicationComplexity.TVDistance.jordan_posPart_real_univ_eq_negPart_real_univ, CommunicationComplexity.TVDistance.signedMeasure_apply_eq_posPart_sub_negPart, CommunicationComplexity.signedMeasureDiff}

For every measurable set $S \subseteq \Omega$,
$|(\mu-\nu)(S)| \le \tfrac{1}{2}\|\mu-\nu\|_{\mathrm{TV}}(\Omega)$.
\end{lemma}

n20654.content:
\begin{lemma}[Probability gap bounded by half total variation]
\lean{CommunicationComplexity.TVDistance.event_abs_measureReal_sub_le_half_totalVariation}
\label{CommunicationComplexity.TVDistance.event_abs_measureReal_sub_le_half_totalVariation}
\leanok
\uses{CommunicationComplexity.TVDistance.event_abs_signedMeasureDiff_le_half_totalVariation, CommunicationComplexity.signedMeasureDiff}

For every measurable set $S \subseteq \Omega$,
$|\mu(S) - \nu(S)| \le \tfrac{1}{2}\|\mu-\nu\|_{\mathrm{TV}}(\Omega)$.
\end{lemma}

n20655.content:
\begin{lemma}[Attainment of the signed measure bound]
\lean{CommunicationComplexity.TVDistance.exists_event_abs_signedMeasureDiff_eq_half_totalVariation}
\label{CommunicationComplexity.TVDistance.exists_event_abs_signedMeasureDiff_eq_half_totalVariation}
\leanok
\uses{CommunicationComplexity.TVDistance.half_totalVariation_real_univ_eq_posPart_real_univ, CommunicationComplexity.TVDistance.signedMeasure_apply_eq_posPart_sub_negPart, CommunicationComplexity.signedMeasureDiff}

There exists a measurable set $S \subseteq \Omega$ for which the bound is tight:
