n20659.content:
\begin{theorem}[TV distance is nonneg]
\lean{CommunicationComplexity.TVDistance.tvDistance_nonneg}
\label{CommunicationComplexity.TVDistance.tvDistance_nonneg}
\leanok
\uses{CommunicationComplexity.tvDistance}

