n20664.content:
\begin{definition}[Singleton mass difference]
\lean{CommunicationComplexity.TVDistance.singletonMassDiff}
\label{CommunicationComplexity.TVDistance.singletonMassDiff}
\leanok
For probability measures $\mu$ and $\nu$ on $\Omega$ and a point $\omega \in \Omega$,
the \emph{singleton mass difference} is $\mu(\{\omega\}) - \nu(\{\omega\}) \in \mathbb{R}$.
\end{definition}

n20665.content:
\begin{lemma}[Probability gap as sum of singleton mass differences]
\lean{CommunicationComplexity.TVDistance.measureReal_sub_eq_sum_indicator_singletonMassDiff}
\label{CommunicationComplexity.TVDistance.measureReal_sub_eq_sum_indicator_singletonMassDiff}
\leanok
\uses{CommunicationComplexity.FiniteMeasureSpace, CommunicationComplexity.FiniteMeasureSpace.measureReal_eq_sum_singletons, CommunicationComplexity.TVDistance.singletonMassDiff}

On a finite measurable space, for any measurable set $S$,
$\mu(S) - \nu(S) = \sum_{\omega \in S} (\mu(\{\omega\}) - \nu(\{\omega\}))$.
\end{lemma}

n20666.content:
\begin{lemma}[Singleton mass differences sum to zero]
\lean{CommunicationComplexity.TVDistance.sum_singletonMassDiff_eq_zero}
\label{CommunicationComplexity.TVDistance.sum_singletonMassDiff_eq_zero}
\leanok
\uses{CommunicationComplexity.FiniteMeasureSpace, CommunicationComplexity.FiniteMeasureSpace.measureReal_eq_sum_singletons, CommunicationComplexity.TVDistance.singletonMassDiff}

On a finite measurable space, the singleton mass differences sum to zero:
$\sum_{\omega : \Omega} (\mu(\{\omega\}) - \nu(\{\omega\})) = 0$.
\end{lemma}

n20667.content:
\begin{theorem}[TV distance as half $\ell^1$ distance on finite spaces (supremum form)]
\lean{CommunicationComplexity.TVDistance.tvDistanceSup_eq_half_sum}
\label{CommunicationComplexity.TVDistance.tvDistanceSup_eq_half_sum}
\leanok
\uses{CommunicationComplexity.FiniteMeasureSpace, CommunicationComplexity.TVDistance.abs_sum_indicator_le_half_sum_abs, CommunicationComplexity.TVDistance.abs_sum_pos_indicator_eq_half_sum_abs, CommunicationComplexity.TVDistance.measureReal_sub_eq_sum_indicator_singletonMassDiff, CommunicationComplexity.TVDistance.singletonMassDiff, CommunicationComplexity.TVDistance.sum_singletonMassDiff_eq_zero, CommunicationComplexity.tvDistanceSup}

On a finite measurable space $\Omega$, the supremum form of total variation distance
satisfies
\[
  \mathrm{TV}_{\sup}(\mu,\nu) \;=\; \frac{1}{2}\sum_{\omega:\Omega}
    |\mu(\{\omega\}) - \nu(\{\omega\})|.
\]
\end{theorem}

n20668.content:
\begin{theorem}[TV distance as half $\ell^1$ distance on finite spaces]
\lean{CommunicationComplexity.TVDistance.tvDistance_eq_half_sum}
\label{CommunicationComplexity.TVDistance.tvDistance_eq_half_sum}
\leanok
\uses{CommunicationComplexity.FiniteMeasureSpace, CommunicationComplexity.TVDistance.tvDistanceSup_eq_half_sum, CommunicationComplexity.TVDistance.tvDistance_eq_tvDistanceSup, CommunicationComplexity.tvDistance}

On a finite measurable space $\Omega$,
\[
  \mathrm{TV}(\mu,\nu) \;=\; \frac{1}{2}\sum_{\omega:\Omega}
    |\mu(\{\omega\}) - \nu(\{\omega\})|.
\]
\end{theorem}

n20669.content:
\begin{theorem}[TV distance on Bool equals gap at true]
\lean{CommunicationComplexity.TVDistance.tvDistance_bool_eq_abs_true}
\label{CommunicationComplexity.TVDistance.tvDistance_bool_eq_abs_true}
\leanok
\uses{CommunicationComplexity.TVDistance.tvDistance_eq_half_sum, CommunicationComplexity.tvDistance}

For probability measures $\mu$ and $\nu$ on $\mathrm{Bool}$,
$\mathrm{TV}(\mu,\nu) = |\mu(\{\mathrm{true}\}) - \nu(\{\mathrm{true}\})|$.
\end{theorem}

n20670.content:
\begin{theorem}[TV distance sub-additivity for product measures]
\lean{CommunicationComplexity.TVDistance.tvDistance_prod_le}
\label{CommunicationComplexity.TVDistance.tvDistance_prod_le}
\leanok
\uses{CommunicationComplexity.FiniteMeasureSpace, CommunicationComplexity.TVDistance.tvDistance_eq_half_sum, CommunicationComplexity.tvDistance}

For probability measures $\mu_1, \nu_1$ on $\alpha$ and $\mu_2, \nu_2$ on $\beta$
(both finite measurable spaces),
\[
  \mathrm{TV}(\mu_1 \otimes \mu_2,\, \nu_1 \otimes \nu_2)
  \;\le\;
  \mathrm{TV}(\mu_1,\nu_1) + \mathrm{TV}(\mu_2,\nu_2).
\]
\end{theorem}

n20672.content:
\begin{definition}[NAE-SAT instance]
\lean{NAEtoColor.NAESat3}
\label{NAEtoColor.NAESat3}
\leanok
A NAE-SAT instance over variable type $V$ is defined as a list of NAE clauses,
i.e.\ $\texttt{NAEtoColor.NAESat3}\;V = \mathtt{List}\;(\mathtt{NAEclause}\;V)$.
\end{definition}

n20673.content:
\begin{definition}[Global NAE-SAT satisfaction]
\lean{NAEtoColor.SatisfiesNAE3}
\label{NAEtoColor.SatisfiesNAE3}
\leanok
\uses{NAEtoColor.NAESat3, NAEtoColor.SatisfiesClause}
Given an assignment $\mathit{assign} : V \to \mathtt{Bool}$ and a NAE-SAT
instance $f$, $\texttt{NAEtoColor.SatisfiesNAE3}$ returns $\mathtt{true}$ if
and only if every clause in $f$ is satisfied by $\mathit{assign}$
(i.e.\ $\texttt{NAEtoColor.SatisfiesClause}$ holds for each clause).
\end{definition}

n20674.content:
\begin{definition}[NAE-SAT satisfiability]
\lean{NAEtoColor.IsSatisfiable}
\label{NAEtoColor.IsSatisfiable}
\leanok
\uses{NAEtoColor.NAESat3, NAEtoColor.SatisfiesNAE3}
A NAE-SAT instance $f$ over variable type $V$ is \emph{satisfiable} if there
exists a Boolean assignment $\mathit{assign} : V \to \mathtt{Bool}$ such that
$\texttt{NAEtoColor.SatisfiesNAE3}\;\mathit{assign}\;f = \mathtt{true}$.
\end{definition}

n20675.content:
\begin{definition}[Example NAE-SAT instance]
\lean{NAEtoColor.NAE_SAT_Example.nae_sat_eg}
\label{NAEtoColor.NAE_SAT_Example.nae_sat_eg}
\leanok
\uses{NAEtoColor.NAESat3}
A concrete NAE-SAT instance over $\mathrm{Fin}\,5$ consisting of three clauses:
$\langle 0,1,2\rangle$, $\langle 0,1,3\rangle$, $\langle 0,2,4\rangle$.
\end{definition}

n20676.content:
\begin{definition}[Example assignment]
\lean{NAEtoColor.NAE_SAT_Example.assign_eg}
\label{NAEtoColor.NAE_SAT_Example.assign_eg}
\leanok
A concrete Boolean assignment for $\mathrm{Fin}\,5$ given by
$\![{\mathtt{true}},{\mathtt{true}},{\mathtt{false}},{\mathtt{false}},{\mathtt{false}}]$,
which witnesses satisfiability of \texttt{NAEtoColor.NAE\_SAT\_Example.nae\_sat\_eg}.
\end{definition}

n20677.content:
\begin{definition}[3-colorability]
\lean{NAEtoColor.Is3Colorable}
\label{NAEtoColor.Is3Colorable}
\leanok
A simple graph $G$ on vertex type $V'$ is \emph{3-colorable} if there exists
a proper coloring $G.\mathtt{Coloring}\;(\mathrm{Fin}\,3)$, i.e.\ a map
from vertices to $\{0,1,2\}$ such that no two adjacent vertices share the same
color.
\end{definition}

n20678.content:
\begin{definition}[Reduction vertex type]
\lean{NAEtoColor.OutputVertex}
\label{NAEtoColor.OutputVertex}
\leanok
The vertex set of the reduction graph is an inductive type with three
constructors:
\begin{itemize}
  \item $\mathtt{groundNode}$ --- a single ground vertex (colored ``neutral'');
  \item $\mathtt{varNode}\;v$ --- one vertex per variable $v \in V$;
  \item $\mathtt{clauseNode}\;c\;k$ --- three internal gadget vertices
        ($k \in \mathrm{Fin}\,3$) for each clause $c$.
\end{itemize}
\end{definition}

n20679.content:
\begin{definition}[Reduction edge relation]
\lean{NAEtoColor.EdgeRelation}
\label{NAEtoColor.EdgeRelation}
\leanok
\uses{NAEtoColor.NAESat3, NAEtoColor.OutputVertex}
Given a NAE-SAT instance $\mathit{clauses}$, the directed edge relation on
$\texttt{NAEtoColor.OutputVertex}\;V$ is defined by:
(1) $\mathtt{groundNode}$ is adjacent to every $\mathtt{varNode}$;
(2) $\mathtt{varNode}\;v$ is adjacent to $\mathtt{clauseNode}\;c\;i$ when $v$
is the $i$-th variable of clause $c$;
(3) two clause-gadget nodes $\mathtt{clauseNode}\;c\;i$ and
$\mathtt{clauseNode}\;c\;j$ are adjacent when $c \in \mathit{clauses}$ and
$i \neq j$ (forming a triangle within each clause gadget).
All other pairs are non-adjacent.
\end{definition}

n20680.content:
\begin{definition}[Reduction graph]
\lean{NAEtoColor.ReductionGraph}
\label{NAEtoColor.ReductionGraph}
\leanok
\uses{NAEtoColor.EdgeRelation, NAEtoColor.NAESat3, NAEtoColor.OutputVertex}
Given a NAE-SAT instance $f$, $\texttt{NAEtoColor.ReductionGraph}\;f$ is the
simple graph on $\texttt{NAEtoColor.OutputVertex}\;V$ whose adjacency is the
symmetrization of $\texttt{NAEtoColor.EdgeRelation}\;f$ restricted to distinct
pairs (no self-loops).
\end{definition}

n20682.content:
\begin{definition}[NAE-to-coloring coloring map]
\lean{NAEtoColor.naeColoring}
\label{NAEtoColor.naeColoring}
\leanok
\uses{NAEtoColor.OutputVertex, NAEtoColor.clauseNodeColor}
Given a Boolean assignment $\mathit{assign} : V \to \mathtt{Bool}$, defines a
coloring of all vertices of the reduction graph by:
$\mathtt{groundNode} \mapsto 0$;
$\mathtt{varNode}\;v \mapsto 1$ if $\mathit{assign}(v) = \mathtt{true}$, else $2$;
$\mathtt{clauseNode}\;c\;k \mapsto
\texttt{NAEtoColor.clauseNodeColor}\;(\mathit{assign}(c.v_0))\;(\mathit{assign}(c.v_1))\;(\mathit{assign}(c.v_2))\;k$.
\end{definition}

n20683.content:
\begin{lemma}[Completeness of reduction]
\lean{NAEtoColor.NAEtoColorCompleteness}
\label{NAEtoColor.NAEtoColorCompleteness}
\leanok
\uses{NAEtoColor.EdgeRelation, NAEtoColor.Is3Colorable, NAEtoColor.IsSatisfiable, NAEtoColor.NAESat3, NAEtoColor.OutputVertex, NAEtoColor.ReductionGraph, NAEtoColor.SatisfiesClause, NAEtoColor.clauseNodeColor, NAEtoColor.naeColoring}

If a NAE-SAT instance $f$ over variable type $V$ is satisfiable, then the
reduction graph $\texttt{NAEtoColor.ReductionGraph}\;f$ is 3-colorable.
Concretely, any satisfying assignment yields the proper coloring
$\texttt{NAEtoColor.naeColoring}$.
\end{lemma}

n20684.content:
\begin{lemma}[Soundness of reduction]
\lean{NAEtoColor.NAEtoColorSoundness}
\label{NAEtoColor.NAEtoColorSoundness}
\leanok
\uses{NAEtoColor.EdgeRelation, NAEtoColor.Is3Colorable, NAEtoColor.IsSatisfiable, NAEtoColor.NAESat3, NAEtoColor.OutputVertex, NAEtoColor.ReductionGraph, NAEtoColor.SatisfiesClause, NAEtoColor.SatisfiesNAE3}

If the reduction graph $\texttt{NAEtoColor.ReductionGraph}\;f$ is 3-colorable,
then the NAE-SAT instance $f$ is satisfiable.
The assignment is recovered by comparing each variable-node color to the
``true'' color (ground color $+1 \pmod{3}$); the triangle gadgets within each
clause force the three variable colors to be not all equal, yielding a
NAE-satisfying assignment.
\end{lemma}

n20685.content:
\begin{theorem}[NAE-SAT iff 3-colorable]
\lean{NAEtoColor.NAEtoColorReduction}
\label{NAEtoColor.NAEtoColorReduction}
\leanok
\uses{NAEtoColor.Is3Colorable, NAEtoColor.IsSatisfiable, NAEtoColor.NAESat3, NAEtoColor.NAEtoColorCompleteness, NAEtoColor.NAEtoColorSoundness, NAEtoColor.ReductionGraph}

For any NAE-SAT instance $f$ over variable type $V$,
\[
  \texttt{NAEtoColor.IsSatisfiable}\;f
  \;\iff\;
  \texttt{NAEtoColor.Is3Colorable}\;(\texttt{NAEtoColor.ReductionGraph}\;f).
\]
This is the main reduction theorem, combining completeness and soundness.
\end{theorem}

n20686.content:
\begin{definition}[Clause]
\lean{SATTo3SAT.Clause}
\label{SATTo3SAT.Clause}
\leanok
A clause over variable type $V$ is a disjunction represented as a list of literals,
i.e.\ $\mathtt{Clause}\,V = \mathtt{List}\,(\mathtt{Literal}\,V)$.
\end{definition}

n20687.content:
\begin{definition}[CNF formula]
\lean{SATTo3SAT.CNFFormula}
\label{SATTo3SAT.CNFFormula}
\leanok
\uses{SATTo3SAT.Clause}
A CNF formula over $V$ is a conjunction of clauses, represented as a list of clauses:
$\mathtt{CNFFormula}\,V = \mathtt{List}\,(\mathtt{Clause}\,V)$.
\end{definition}

n20688.content:
\begin{definition}[Literal evaluation]
\lean{SATTo3SAT.evalLiteral}
\label{SATTo3SAT.evalLiteral}
\leanok
Given an assignment $\alpha : V \to \mathrm{Prop}$, \texttt{SATTo3SAT.evalLiteral} maps
a literal to its truth value: a positive literal $\mathtt{pos}\,v$ is true iff $\alpha(v)$
holds, and a negative literal $\mathtt{neg}\,v$ is true iff $\alpha(v)$ does not hold.
\end{definition}

n20689.content:
\begin{definition}[Clause satisfaction]
\lean{SATTo3SAT.clauseSatisfied}
\label{SATTo3SAT.clauseSatisfied}
\leanok
\uses{SATTo3SAT.Clause, SATTo3SAT.evalLiteral}
A clause $c$ is satisfied by assignment $\alpha$ if at least one literal in $c$ evaluates
to true under $\alpha$, i.e.\ $\exists\, l \in c,\; \texttt{SATTo3SAT.evalLiteral}\,\alpha\,l$.
\end{definition}

n20690.content:
\begin{definition}[Formula satisfaction]
\lean{SATTo3SAT.formulaSatisfied}
\label{SATTo3SAT.formulaSatisfied}
\leanok
\uses{SATTo3SAT.CNFFormula, SATTo3SAT.clauseSatisfied}
A CNF formula $f$ is satisfied by assignment $\alpha$ if every clause in $f$ is satisfied
by $\alpha$.
\end{definition}

n20691.content:
\begin{definition}[Satisfiability of a CNF formula]
\lean{SATTo3SAT.isSatisfiable}
\label{SATTo3SAT.isSatisfiable}
\leanok
\uses{SATTo3SAT.CNFFormula, SATTo3SAT.formulaSatisfied}
A CNF formula $f$ is satisfiable if there exists an assignment $\alpha$ such that
$\texttt{SATTo3SAT.formulaSatisfied}\,\alpha\,f$ holds.
\end{definition}

n20692.content:
\begin{definition}[3-clause]
\lean{SATTo3SAT.Clause3}
\label{SATTo3SAT.Clause3}
\leanok
A 3-clause over $V$ is a structure carrying exactly three literals $l_1, l_2, l_3 :
\mathtt{Literal}\,V$; a 3-clause is satisfied when at least one of the three literals is true.
\end{definition}

n20693.content:
\begin{definition}[3-CNF formula]
\lean{SATTo3SAT.Formula3}
\label{SATTo3SAT.Formula3}
\leanok
\uses{SATTo3SAT.Clause3}
A 3-CNF formula over $V$ is a list of 3-clauses:
$\mathtt{Formula3}\,V = \mathtt{List}\,(\mathtt{Clause3}\,V)$.
\end{definition}

n20694.content:
\begin{definition}[3-clause satisfaction]
\lean{SATTo3SAT.clause3Satisfied}
\label{SATTo3SAT.clause3Satisfied}
\leanok
\uses{SATTo3SAT.Clause3, SATTo3SAT.evalLiteral}
A 3-clause $c$ is satisfied by assignment $\alpha$ if at least one of its three literals
$c.l_1$, $c.l_2$, $c.l_3$ evaluates to true under $\alpha$.
\end{definition}

n20695.content:
\begin{definition}[3-CNF formula satisfaction]
\lean{SATTo3SAT.formula3Satisfied}
\label{SATTo3SAT.formula3Satisfied}
\leanok
\uses{SATTo3SAT.Formula3, SATTo3SAT.clause3Satisfied}
A 3-CNF formula $f$ is satisfied by assignment $\alpha$ if every 3-clause in $f$ is
satisfied by $\alpha$.
\end{definition}

n20696.content:
\begin{definition}[3-SAT satisfiability]
\lean{SATTo3SAT.is3Satisfiable}
\label{SATTo3SAT.is3Satisfiable}
\leanok
\uses{SATTo3SAT.Formula3, SATTo3SAT.formula3Satisfied}
A 3-CNF formula $f$ is 3-satisfiable if there exists an assignment $\alpha$ such that
$\texttt{SATTo3SAT.formula3Satisfied}\,\alpha\,f$ holds.
\end{definition}

n20697.content:
\begin{definition}[Auxiliary variable type]
\lean{SATTo3SAT.AuxVar}
\label{SATTo3SAT.AuxVar}
\leanok
The inductive type $\mathtt{AuxVar}\,V$ extends a variable type $V$ with two constructors:
$\mathtt{orig}\,v$ wraps an original variable $v : V$, and $\mathtt{extra}\,i\,j$
introduces a fresh auxiliary variable $y_{i,j}$ used as a chain link when encoding clause
$i$ of length greater than three.
\end{definition}

n20698.content:
\begin{definition}[Lift a literal to the extended type]
\lean{SATTo3SAT.liftLit}
\label{SATTo3SAT.liftLit}
\leanok
\uses{SATTo3SAT.AuxVar}
\texttt{SATTo3SAT.liftLit} maps a literal over $V$ to the corresponding literal over
$\mathtt{AuxVar}\,V$ by wrapping each variable with $\mathtt{orig}$, preserving polarity.
\end{definition}

n20699.content:
\begin{definition}[Build chain clauses]
\lean{SATTo3SAT.buildChain}
\label{SATTo3SAT.buildChain}
\leanok
\uses{SATTo3SAT.AuxVar, SATTo3SAT.Clause3}
Given a clause index $c\_idx$, a lifting map $ml$, a suffix list of literals $\mathit{lits}$,
and a chain counter $j \ge 1$, \texttt{SATTo3SAT.buildChain} produces the middle and final
3-clauses of the chain encoding.  Each middle step emits $\langle \lnot y_{j-1},\, l_i,\, y_j\rangle$;
the final step emits $\langle \lnot y_{j-1},\, l_{n-1},\, l_n\rangle$ when only two literals remain.
\end{definition}

n20700.content:
\begin{definition}[Encode a single clause as 3-clauses]
\lean{SATTo3SAT.transformClause}
\label{SATTo3SAT.transformClause}
\leanok
\uses{SATTo3SAT.AuxVar, SATTo3SAT.Clause3, SATTo3SAT.buildChain}
\texttt{SATTo3SAT.transformClause} maps a single clause (at index $c\_idx$) to a list of
3-clauses: the empty clause becomes two contradictory 3-clauses (unsatisfiable), a
1-literal clause becomes $\langle l_1,l_1,l_1\rangle$, a 2-literal clause becomes
$\langle l_1,l_2,l_2\rangle$, a 3-literal clause is copied as-is, and any longer clause
$l_1 :: l_2 :: \mathit{rest}$ becomes $\langle l_1, l_2, y_0\rangle$ followed by
$\texttt{SATTo3SAT.buildChain}$ on $\mathit{rest}$.
\end{definition}

n20701.content:
\begin{definition}[Recursive SAT-to-3SAT worker]
\lean{SATTo3SAT.to3SATAux}
\label{SATTo3SAT.to3SATAux}
\leanok
\uses{SATTo3SAT.AuxVar, SATTo3SAT.Clause, SATTo3SAT.Clause3, SATTo3SAT.transformClause}
The auxiliary recursive function \texttt{SATTo3SAT.to3SATAux} iterates
\texttt{SATTo3SAT.transformClause} over a list of clauses, threading a clause index
counter to ensure each clause uses distinct auxiliary variables.
\end{definition}

n20702.content:
\begin{definition}[SAT to 3-SAT encoding]
\lean{SATTo3SAT.to3SAT}
\label{SATTo3SAT.to3SAT}
\leanok
\uses{SATTo3SAT.AuxVar, SATTo3SAT.CNFFormula, SATTo3SAT.Formula3, SATTo3SAT.to3SATAux}
\texttt{SATTo3SAT.to3SAT} converts a CNF formula $f$ over $V$ into a 3-CNF formula over
$\mathtt{AuxVar}\,V$ by calling \texttt{SATTo3SAT.to3SATAux} starting at index $0$.
\end{definition}

n20703.content:
\begin{definition}[Auxiliary variable valuation]
\lean{SATTo3SAT.extraVal}
\label{SATTo3SAT.extraVal}
\leanok
\uses{SATTo3SAT.evalLiteral}
For a list of literals $\mathit{lits}$ and index $j$, $\texttt{SATTo3SAT.extraVal}\,\alpha\,\mathit{lits}\,j$
holds iff every literal in $\mathit{lits}.\mathtt{take}(j + 2)$ is false under $\alpha$.
This is the intended truth value of the auxiliary chain variable $y_j$ in the encoding
of $\mathit{lits}$.
\end{definition}

n20704.content:
\begin{lemma}[extraVal as prefix-all-false]
\lean{SATTo3SAT.extraVal_iff_prefix_all_false}
\label{SATTo3SAT.extraVal_iff_prefix_all_false}
\leanok
\uses{SATTo3SAT.evalLiteral, SATTo3SAT.extraVal}

Provided $j + 2 \le |\mathit{lits}|$, \texttt{SATTo3SAT.extraVal} $\alpha$ $\mathit{lits}$ $j$
is logically equivalent to the condition that every element of $\mathit{lits}.\mathtt{take}(j+2)$
is false under $\alpha$.
\end{lemma}

n20705.content:
\begin{definition}[Global assignment lift]
\lean{SATTo3SAT.globalAssignment}
\label{SATTo3SAT.globalAssignment}
\leanok
\uses{SATTo3SAT.AuxVar, SATTo3SAT.CNFFormula, SATTo3SAT.extraVal}
Given $\alpha : \mathtt{Assignment}\,V$ and a formula $f$, \texttt{SATTo3SAT.globalAssignment}
$\alpha\,f$ is the assignment on $\mathtt{AuxVar}\,V$ that maps each original variable
$\mathtt{orig}\,v$ to $\alpha(v)$ and each auxiliary variable $\mathtt{extra}\,i\,j$ to
$\texttt{SATTo3SAT.extraVal}\,\alpha\,(f.\mathtt{get}\,i)\,j$, i.e.\ the chain invariant
``the first $j+2$ literals of clause $i$ are all false.''
\end{definition}

n20706.content:
\begin{lemma}[Membership in to3SATAux]
\lean{SATTo3SAT.mem_to3SATAux_iff}
\label{SATTo3SAT.mem_to3SATAux_iff}
\leanok
\uses{SATTo3SAT.AuxVar, SATTo3SAT.Clause, SATTo3SAT.Clause3, SATTo3SAT.to3SATAux, SATTo3SAT.transformClause}

A 3-clause $c_3$ belongs to $\texttt{SATTo3SAT.to3SATAux}\,\mathit{cs}\,\mathit{idx}$ if
and only if there exists $i < |\mathit{cs}|$ such that $c_3$ belongs to
$\texttt{SATTo3SAT.transformClause}\,(\mathit{idx} + i)\,(\mathit{cs}_i)$.
\end{lemma}

n20707.content:
\begin{lemma}[Membership in to3SAT]
\lean{SATTo3SAT.mem_to3SAT_iff}
\label{SATTo3SAT.mem_to3SAT_iff}
\leanok
\uses{SATTo3SAT.AuxVar, SATTo3SAT.CNFFormula, SATTo3SAT.Clause3, SATTo3SAT.mem_to3SATAux_iff, SATTo3SAT.to3SAT, SATTo3SAT.transformClause}

A 3-clause $c_3$ belongs to $\texttt{SATTo3SAT.to3SAT}\,f$ if and only if there exists
$i < |f|$ such that $c_3$ belongs to $\texttt{SATTo3SAT.transformClause}\,i\,(f_i)$.
\end{lemma}

n20708.content:
\begin{lemma}[List take after drop-cons]
\lean{SATTo3SAT.List.take_succ_of_drop_cons}
\label{SATTo3SAT.List.take_succ_of_drop_cons}
\leanok

If $l.\mathtt{drop}\,n = a :: \mathit{rest}$, then $l.\mathtt{take}\,(n+1) = l.\mathtt{take}\,n \mathbin{+\!\!+} [a]$.
\end{lemma}

n20709.content:
\begin{lemma}[Chain clauses all satisfied under completeness]
\lean{SATTo3SAT.buildChain_all_satisfied}
\label{SATTo3SAT.buildChain_all_satisfied}
\leanok
\uses{SATTo3SAT.AuxVar, SATTo3SAT.List.take_succ_of_drop_cons, SATTo3SAT.buildChain, SATTo3SAT.clause3Satisfied, SATTo3SAT.evalLiteral, SATTo3SAT.extraVal}

Let $\alpha$ be an assignment satisfying at least one literal of a clause, and let
$\alpha_3$ be an assignment on $\mathtt{AuxVar}\,V$ that evaluates auxiliary variables via
\texttt{SATTo3SAT.extraVal} and lifted literals faithfully.  Then every 3-clause produced
by $\texttt{SATTo3SAT.buildChain}\,c\_idx\,ml\,\mathit{lits}\,j$ (with $j \ge 1$ and
$\mathit{lits} = \mathit{clause}.\mathtt{drop}(j+1)$) is satisfied by $\alpha_3$.
\end{lemma}

n20710.content:
\begin{definition}[Local literal predicate]
\lean{SATTo3SAT.IsLocalVar}
\label{SATTo3SAT.IsLocalVar}
\leanok
\uses{SATTo3SAT.AuxVar}
A literal $l$ in $\mathtt{Literal}\,(\mathtt{AuxVar}\,V)$ is \emph{local to index $i$} if
every auxiliary variable appearing in $l$ carries index $i$.  Literals over original
variables are always local.
\end{definition}

n20711.content:
\begin{lemma}[Global and local assignments agree on local literals]
\lean{SATTo3SAT.eval_local_eq_global}
\label{SATTo3SAT.eval_local_eq_global}
\leanok
\uses{SATTo3SAT.AuxVar, SATTo3SAT.CNFFormula, SATTo3SAT.Clause, SATTo3SAT.IsLocalVar, SATTo3SAT.evalLiteral, SATTo3SAT.extraVal, SATTo3SAT.globalAssignment}

For a literal $l$ local to index $i$, the evaluation of $l$ under the global assignment
\texttt{SATTo3SAT.globalAssignment} $\alpha\,f$ agrees with its evaluation under the local
assignment that maps $\mathtt{extra}\,i\,j \mapsto \texttt{SATTo3SAT.extraVal}\,\alpha\,(f_i)\,j$.
\end{lemma}

n20712.content:
\begin{lemma}[buildChain produces local literals]
\lean{SATTo3SAT.buildChain_isLocal}
\label{SATTo3SAT.buildChain_isLocal}
\leanok
\uses{SATTo3SAT.AuxVar, SATTo3SAT.Clause3, SATTo3SAT.IsLocalVar, SATTo3SAT.buildChain}

Every literal in any 3-clause produced by $\texttt{SATTo3SAT.buildChain}\,i\,ml\,\ldots$
is local to index $i$, provided the lifting map $ml$ itself produces only literals local
to $i$.
\end{lemma}

n20713.content:
\begin{lemma}[transformClause produces local literals]
\lean{SATTo3SAT.transformClause_isLocal}
\label{SATTo3SAT.transformClause_isLocal}
\leanok
\uses{SATTo3SAT.AuxVar, SATTo3SAT.Clause, SATTo3SAT.Clause3, SATTo3SAT.IsLocalVar, SATTo3SAT.buildChain_isLocal, SATTo3SAT.transformClause}

Every literal in any 3-clause produced by $\texttt{SATTo3SAT.transformClause}\,i\,\mathit{clause}$
is local to index $i$.
\end{lemma}

n20714.content:
\begin{lemma}[Global matches local for transformClause]
\lean{SATTo3SAT.global_matches_local}
\label{SATTo3SAT.global_matches_local}
\leanok
\uses{SATTo3SAT.AuxVar, SATTo3SAT.CNFFormula, SATTo3SAT.Clause, SATTo3SAT.Clause3, SATTo3SAT.clause3Satisfied, SATTo3SAT.eval_local_eq_global, SATTo3SAT.extraVal, SATTo3SAT.globalAssignment, SATTo3SAT.transformClause, SATTo3SAT.transformClause_isLocal}

For a 3-clause $c_3$ produced by $\texttt{SATTo3SAT.transformClause}\,i\,\mathit{clause}$
(where $\mathit{clause} = f_i$), satisfaction of $c_3$ under the global assignment
\texttt{SATTo3SAT.globalAssignment} $\alpha\,f$ is equivalent to satisfaction under the
local assignment $\mathtt{extra}\,i\,j \mapsto \texttt{SATTo3SAT.extraVal}\,\alpha\,\mathit{clause}\,j$.
\end{lemma}

n20715.content:
\begin{lemma}[Satisfied clause yields satisfied 3-clause encoding]
\lean{SATTo3SAT.transformClause_satisfied}
\label{SATTo3SAT.transformClause_satisfied}
\leanok
\uses{SATTo3SAT.AuxVar, SATTo3SAT.Clause, SATTo3SAT.buildChain_all_satisfied, SATTo3SAT.clause3Satisfied, SATTo3SAT.evalLiteral, SATTo3SAT.extraVal, SATTo3SAT.transformClause}

If a clause has at least one true literal under $\alpha$, then every 3-clause in its
encoding $\texttt{SATTo3SAT.transformClause}\,c\_idx\,\mathit{clause}$ is satisfied by
the local assignment $\mathtt{extra}\,c\_idx\,j \mapsto \texttt{SATTo3SAT.extraVal}\,\alpha\,\mathit{clause}\,j$.
\end{lemma}

n20716.content:
\begin{theorem}[SAT to 3-SAT completeness]
\lean{SATTo3SAT.SAT_to_3SAT_completeness}
\label{SATTo3SAT.SAT_to_3SAT_completeness}
\leanok
\uses{SATTo3SAT.CNFFormula, SATTo3SAT.clauseSatisfied, SATTo3SAT.globalAssignment, SATTo3SAT.global_matches_local, SATTo3SAT.is3Satisfiable, SATTo3SAT.isSatisfiable, SATTo3SAT.mem_to3SAT_iff, SATTo3SAT.to3SAT, SATTo3SAT.transformClause_satisfied}

If a CNF formula $f$ is satisfiable, then $\texttt{SATTo3SAT.to3SAT}\,f$ is 3-satisfiable.
The witnessing 3-SAT assignment is \texttt{SATTo3SAT.globalAssignment} $\alpha\,f$, where
$\alpha$ is the original satisfying assignment.
\end{theorem}

n20717.content:
\begin{lemma}[Chain contradiction under all-false literals]
\lean{SATTo3SAT.buildChain_forced_false}
\label{SATTo3SAT.buildChain_forced_false}
\leanok
\uses{SATTo3SAT.AuxVar, SATTo3SAT.buildChain, SATTo3SAT.clause3Satisfied, SATTo3SAT.evalLiteral}

If $y_{j-1}$ is true, every $ml$-lifted literal in $\mathit{lits}$ is false under $\alpha_3$,
and every 3-clause in $\texttt{SATTo3SAT.buildChain}\,c\_idx\,ml\,\mathit{lits}\,j$ is satisfied
by $\alpha_3$ (with $j \ge 1$ and $|\mathit{lits}| \ge 2$), then a contradiction follows:
the auxiliary variables are forced true one by one until the final chain clause has all
three disjuncts false.
\end{lemma}

n20718.content:
\begin{lemma}[Satisfied 3-clause encoding yields satisfied clause]
\lean{SATTo3SAT.transformClause_soundness}
\label{SATTo3SAT.transformClause_soundness}
\leanok
\uses{SATTo3SAT.AuxVar, SATTo3SAT.Clause, SATTo3SAT.buildChain_forced_false, SATTo3SAT.clause3Satisfied, SATTo3SAT.evalLiteral, SATTo3SAT.transformClause}

If every 3-clause in $\texttt{SATTo3SAT.transformClause}\,c\_idx\,\mathit{clause}$ is
satisfied by $\alpha_3$, then the original clause has at least one true literal under
the restriction $v \mapsto \alpha_3(\mathtt{orig}\,v)$.
\end{lemma}

n20719.content:
\begin{theorem}[SAT to 3-SAT soundness]
\lean{SATTo3SAT.SAT_to_3SAT_soundness}
\label{SATTo3SAT.SAT_to_3SAT_soundness}
\leanok
\uses{SATTo3SAT.CNFFormula, SATTo3SAT.is3Satisfiable, SATTo3SAT.isSatisfiable, SATTo3SAT.mem_to3SAT_iff, SATTo3SAT.to3SAT, SATTo3SAT.transformClause_soundness}

If $\texttt{SATTo3SAT.to3SAT}\,f$ is 3-satisfiable, then the original CNF formula $f$ is
satisfiable.  The witnessing assignment for $f$ is the restriction of any 3-SAT
satisfying assignment $\alpha_3$ to original variables, $v \mapsto \alpha_3(\mathtt{orig}\,v)$.
\end{theorem}

n20720.content:
\begin{theorem}[SAT to 3-SAT equivalence]
\lean{SATTo3SAT.SAT_to_3SAT_equivalence}
\label{SATTo3SAT.SAT_to_3SAT_equivalence}
\leanok
\uses{SATTo3SAT.CNFFormula, SATTo3SAT.SAT_to_3SAT_completeness, SATTo3SAT.SAT_to_3SAT_soundness, SATTo3SAT.is3Satisfiable, SATTo3SAT.isSatisfiable, SATTo3SAT.to3SAT}

A CNF formula $f$ over $V$ is satisfiable if and only if the 3-CNF formula
$\texttt{SATTo3SAT.to3SAT}\,f$ (over $\mathtt{AuxVar}\,V$) is 3-satisfiable.
This combines \texttt{SATTo3SAT.SAT\_to\_3SAT\_completeness} and
\texttt{SATTo3SAT.SAT\_to\_3SAT\_soundness} into a single biconditional.
\end{theorem}

n20721.content:
\begin{definition}[Clause]
\lean{ThreeSATToClique.Clause}
\label{ThreeSATToClique.Clause}
\leanok
A clause is a list of literals over a variable type $V$; it represents a
disjunction of those literals.
\end{definition}

n20722.content:
\begin{definition}[CNF formula]
\lean{ThreeSATToClique.CNFFormula}
\label{ThreeSATToClique.CNFFormula}
\leanok
\uses{ThreeSATToClique.Clause}
A CNF formula over $V$ is a list of clauses, representing the conjunction of those
clauses.
\end{definition}

n20723.content:
\begin{definition}[Literal evaluation]
\lean{ThreeSATToClique.evalLiteral}
\label{ThreeSATToClique.evalLiteral}
\leanok
Given a truth assignment $\alpha : V \to \mathrm{Prop}$, the evaluation of a
literal $\ell$ under $\alpha$ is $\alpha(v)$ when $\ell = \texttt{pos}\,v$ and
$\neg\,\alpha(v)$ when $\ell = \texttt{neg}\,v$.
\end{definition}

n20724.content:
\begin{definition}[Clause satisfaction]
\lean{ThreeSATToClique.clauseSatisfied}
\label{ThreeSATToClique.clauseSatisfied}
\leanok
\uses{ThreeSATToClique.Clause, ThreeSATToClique.evalLiteral}
A clause $c$ is \emph{satisfied} by assignment $\alpha$ if at least one literal
$\ell \in c$ satisfies $\mathtt{evalLiteral}\,\alpha\,\ell$.
\end{definition}

n20725.content:
\begin{definition}[CNF formula satisfaction]
\lean{ThreeSATToClique.formulaSatisfied}
\label{ThreeSATToClique.formulaSatisfied}
\leanok
\uses{ThreeSATToClique.CNFFormula, ThreeSATToClique.clauseSatisfied}
A CNF formula $f$ is \emph{satisfied} by $\alpha$ if every clause $c \in f$ is
satisfied by $\alpha$.
\end{definition}

n20726.content:
\begin{definition}[CNF satisfiability]
\lean{ThreeSATToClique.isSatisfiable}
\label{ThreeSATToClique.isSatisfiable}
\leanok
\uses{ThreeSATToClique.CNFFormula, ThreeSATToClique.formulaSatisfied}
A CNF formula $f$ is \emph{satisfiable} if there exists an assignment $\alpha$
that satisfies $f$.
\end{definition}

n20727.content:
\begin{definition}[3-clause]
\lean{ThreeSATToClique.Clause3}
\label{ThreeSATToClique.Clause3}
\leanok
A 3-clause over $V$ is a structure with exactly three literals $l_1, l_2, l_3 :
\mathtt{Literal}\,V$, representing a disjunction of precisely three literals.
\end{definition}

n20728.content:
\begin{definition}[3-CNF formula]
\lean{ThreeSATToClique.Formula3}
\label{ThreeSATToClique.Formula3}
\leanok
\uses{ThreeSATToClique.Clause3}
A 3-CNF formula over $V$ is a list of 3-clauses, representing their conjunction.
\end{definition}

n20729.content:
\begin{definition}[3-clause satisfaction]
\lean{ThreeSATToClique.clause3Satisfied}
\label{ThreeSATToClique.clause3Satisfied}
\leanok
\uses{ThreeSATToClique.Clause3, ThreeSATToClique.evalLiteral}
A 3-clause $c$ is satisfied by $\alpha$ if at least one of its three literals
$c.l_1$, $c.l_2$, $c.l_3$ evaluates to true under $\alpha$.
\end{definition}

n20730.content:
\begin{definition}[3-CNF formula satisfaction]
\lean{ThreeSATToClique.formula3Satisfied}
\label{ThreeSATToClique.formula3Satisfied}
\leanok
\uses{ThreeSATToClique.Formula3, ThreeSATToClique.clause3Satisfied}
A 3-CNF formula $f$ is satisfied by $\alpha$ if every 3-clause $c \in f$ is
satisfied by $\alpha$.
\end{definition}

n20731.content:
\begin{definition}[3-CNF satisfiability]
\lean{ThreeSATToClique.is3Satisfiable}
\label{ThreeSATToClique.is3Satisfiable}
\leanok
\uses{ThreeSATToClique.Formula3, ThreeSATToClique.formula3Satisfied}
A 3-CNF formula $f$ is satisfiable if there exists an assignment $\alpha$ such
that $\alpha$ satisfies $f$.
\end{definition}

n20732.content:
\begin{definition}[Clique vertex]
\lean{ThreeSATToClique.CliqueVertex}
\label{ThreeSATToClique.CliqueVertex}
\leanok
A vertex of the conflict graph for a formula with $m$ clauses is a pair
$\langle c\_idx, l\_idx \rangle$ where $c\_idx : \mathrm{Fin}\,m$ is a clause index
and $l\_idx : \mathrm{Fin}\,3$ is a literal position within that clause.
\end{definition}

n20733.content:
\begin{definition}[Literal extraction from a 3-clause]
\lean{ThreeSATToClique.getLitInClause}
\label{ThreeSATToClique.getLitInClause}
\leanok
\uses{ThreeSATToClique.Clause3}
Given a 3-clause $c$ and a position $p : \mathrm{Fin}\,3$, returns the $p$-th
literal of $c$: $c.l_1$ at position $0$, $c.l_2$ at position $1$, and $c.l_3$ at
position $2$.
\end{definition}

n20734.content:
\begin{definition}[Literal named by a vertex]
\lean{ThreeSATToClique.getLitAt}
\label{ThreeSATToClique.getLitAt}
\leanok
\uses{ThreeSATToClique.CliqueVertex, ThreeSATToClique.Formula3, ThreeSATToClique.getLitInClause}
Given a 3-CNF formula $f$ and a vertex $v : \mathtt{CliqueVertex}\,f.\mathtt{length}$,
returns the literal at position $v.l\_idx$ within clause $f[v.c\_idx]$.  The type of
$v$ guarantees the index is always in bounds.
\end{definition}

n20735.content:
\begin{definition}[Literal conflict]
\lean{ThreeSATToClique.literalsConflict}
\label{ThreeSATToClique.literalsConflict}
\leanok
Two literals $l_1$ and $l_2$ \emph{conflict} if one is the positive and the other
the negative occurrence of the same variable, i.e.\ $l_1 = \texttt{pos}\,v$ and
$l_2 = \texttt{neg}\,v$ (or vice versa) for some $v$.
\end{definition}

n20736.content:
\begin{theorem}[Symmetry of literal conflict]
\lean{ThreeSATToClique.literalsConflict_symm}
\label{ThreeSATToClique.literalsConflict_symm}
\leanok
\uses{ThreeSATToClique.literalsConflict}

For any two literals $l_1$ and $l_2$, $\mathtt{literalsConflict}\,l_1\,l_2 \iff
\mathtt{literalsConflict}\,l_2\,l_1$.
\end{theorem}

n20737.content:
\begin{definition}[Conflict graph]
\lean{ThreeSATToClique.toCliqueGraph}
\label{ThreeSATToClique.toCliqueGraph}
\leanok
\uses{ThreeSATToClique.CliqueVertex, ThreeSATToClique.Formula3, ThreeSATToClique.getLitAt, ThreeSATToClique.literalsConflict, ThreeSATToClique.literalsConflict_symm}
The conflict graph of a 3-CNF formula $f$ is the simple graph on vertex set
$\mathtt{CliqueVertex}\,f.\mathtt{length}$ in which two vertices $u$ and $v$ are
adjacent if and only if they come from \emph{different} clauses ($u.c\_idx \ne
v.c\_idx$) and their respective literals do not conflict.
\end{definition}

n20738.content:
\begin{definition}[$k$-clique existence]
\lean{ThreeSATToClique.hasClique}
\label{ThreeSATToClique.hasClique}
\leanok
A graph $G$ on vertex type $V$ \emph{has a $k$-clique} if there exists a finite set
$s \subseteq V$ of $k$ vertices that are pairwise adjacent in $G$.
\end{definition}

n20739.content:
\begin{lemma}[Simultaneously true literals do not conflict]
\lean{ThreeSATToClique.no_conflict_of_true}
\label{ThreeSATToClique.no_conflict_of_true}
\leanok
\uses{ThreeSATToClique.evalLiteral, ThreeSATToClique.literalsConflict}

If an assignment $\alpha$ makes both $l_1$ and $l_2$ true, then $l_1$ and $l_2$
do not conflict: $\mathtt{evalLiteral}\,\alpha\,l_1 \to \mathtt{evalLiteral}\,\alpha\,l_2
\to \neg\,\mathtt{literalsConflict}\,l_1\,l_2$.
\end{lemma}

n20740.content:
\begin{lemma}[Clique vertices represent one literal per clause]
\lean{ThreeSATToClique.clique_vertices_choose_one_per_clause}
\label{ThreeSATToClique.clique_vertices_choose_one_per_clause}
\leanok
\uses{ThreeSATToClique.CliqueVertex, ThreeSATToClique.Formula3, ThreeSATToClique.toCliqueGraph}

If $s$ is a set of $m$ vertices forming a clique in the conflict graph of a formula
$f$ with $m$ clauses, then for every clause index $i : \mathrm{Fin}\,m$ there is
exactly one vertex $u \in s$ with $u.c\_idx = i$.
\end{lemma}

n20741.content:
\begin{lemma}[Vertex literal belongs to its clause]
\lean{ThreeSATToClique.getLitAt_mem_clause}
\label{ThreeSATToClique.getLitAt_mem_clause}
\leanok
\uses{ThreeSATToClique.CliqueVertex, ThreeSATToClique.Formula3, ThreeSATToClique.getLitAt, ThreeSATToClique.getLitInClause}

If $v$ is a clique vertex with $v.c\_idx = i$, then the literal
$\mathtt{getLitAt}\,f\,v$ is one of the three literals $l_1$, $l_2$, $l_3$ of
clause $f[i]$.
\end{lemma}

n20742.content:
\begin{theorem}[Completeness of the reduction]
\lean{ThreeSATToClique.ThreeSAT_to_Clique_completeness}
\label{ThreeSATToClique.ThreeSAT_to_Clique_completeness}
\leanok
\uses{ThreeSATToClique.CliqueVertex, ThreeSATToClique.Formula3, ThreeSATToClique.evalLiteral, ThreeSATToClique.getLitAt, ThreeSATToClique.hasClique, ThreeSATToClique.is3Satisfiable, ThreeSATToClique.no_conflict_of_true, ThreeSATToClique.toCliqueGraph}

If a 3-CNF formula $f$ with $m$ clauses is satisfiable, then the conflict graph
$\mathtt{toCliqueGraph}\,f$ contains an $m$-clique: $\mathtt{is3Satisfiable}\,f \to
\mathtt{hasClique}\,(\mathtt{toCliqueGraph}\,f)\,f.\mathtt{length}$.
\end{theorem}

n20743.content:
\begin{theorem}[Soundness of the reduction]
\lean{ThreeSATToClique.ThreeSAT_to_Clique_soundness}
\label{ThreeSATToClique.ThreeSAT_to_Clique_soundness}
\leanok
\uses{ThreeSATToClique.Formula3, ThreeSATToClique.clique_vertices_choose_one_per_clause, ThreeSATToClique.evalLiteral, ThreeSATToClique.getLitAt, ThreeSATToClique.getLitAt_mem_clause, ThreeSATToClique.hasClique, ThreeSATToClique.is3Satisfiable, ThreeSATToClique.toCliqueGraph}

If the conflict graph of a 3-CNF formula $f$ with $m$ clauses contains an
$m$-clique, then $f$ is satisfiable:
$\mathtt{hasClique}\,(\mathtt{toCliqueGraph}\,f)\,f.\mathtt{length} \to
\mathtt{is3Satisfiable}\,f$.
\end{theorem}

n20744.content:
\begin{theorem}[3-SAT $\Leftrightarrow$ Clique equivalence]
\lean{ThreeSATToClique.ThreeSAT_to_Clique_equivalence}
\label{ThreeSATToClique.ThreeSAT_to_Clique_equivalence}
\leanok
\uses{ThreeSATToClique.Formula3, ThreeSATToClique.ThreeSAT_to_Clique_completeness, ThreeSATToClique.ThreeSAT_to_Clique_soundness, ThreeSATToClique.hasClique, ThreeSATToClique.is3Satisfiable, ThreeSATToClique.toCliqueGraph}

A 3-CNF formula $f$ is satisfiable if and only if its conflict graph contains a
clique of size $f.\mathtt{length}$:
\[
  \mathtt{is3Satisfiable}\,f \;\iff\;
  \mathtt{hasClique}\,(\mathtt{toCliqueGraph}\,f)\,f.\mathtt{length}.
\]
\end{theorem}

n20745.content:
\begin{definition}[Clause]
\lean{SATtoColor.Clause}
\label{SATtoColor.Clause}
\leanok
A \emph{clause} over a variable type $V$ is a structure bundling exactly three
literals $\ell_1, \ell_2, \ell_3 : \mathrm{Literal}\,V$.  Each literal is
either a positive or a negative occurrence of some variable.
\end{definition}

n20746.content:
\begin{definition}[Literal satisfaction]
\lean{SATtoColor.SatisfiesLiteral}
\label{SATtoColor.SatisfiesLiteral}
\leanok
Given a Boolean assignment $\mathrm{assign} : V \to \mathrm{Bool}$, the
function $\texttt{SATtoColor.SatisfiesLiteral}$ evaluates a literal: a positive
literal $\mathrm{pos}(v)$ evaluates to $\mathrm{assign}(v)$, and a negative
literal $\mathrm{neg}(v)$ evaluates to $\neg\,\mathrm{assign}(v)$.
\end{definition}

n20747.content:
\begin{definition}[Clause satisfaction]
\lean{SATtoColor.SatisfiesClause}
\label{SATtoColor.SatisfiesClause}
\leanok
\uses{SATtoColor.Clause, SATtoColor.SatisfiesLiteral}
Under assignment $\mathrm{assign}$, a clause $c$ is satisfied if at least one
of its three literals evaluates to \texttt{true}:
\[
  \mathrm{SatisfiesClause}(\mathrm{assign}, c)
  \;=\;
  \mathrm{SatisfiesLiteral}(\mathrm{assign}, c.\ell_1)
  \;\vee\;
  \mathrm{SatisfiesLiteral}(\mathrm{assign}, c.\ell_2)
  \;\vee\;
  \mathrm{SatisfiesLiteral}(\mathrm{assign}, c.\ell_3).
\]
\end{definition}

n20748.content:
\begin{definition}[3-SAT instance]
\lean{SATtoColor.Sat3}
\label{SATtoColor.Sat3}
\leanok
\uses{SATtoColor.Clause}
A 3-SAT instance over variable type $V$ is defined as a list of clauses,
i.e.\ $\mathrm{Sat3}(V) := \mathrm{List}(\mathrm{Clause}\,V)$.
\end{definition}

n20749.content:
\begin{definition}[Simultaneous clause satisfaction]
\lean{SATtoColor.SatisfiesSat3}
\label{SATtoColor.SatisfiesSat3}
\leanok
\uses{SATtoColor.Sat3, SATtoColor.SatisfiesClause}
An assignment $\mathrm{assign}$ \emph{satisfies} a 3-SAT instance $f$ if every
clause in the list $f$ is satisfied by $\mathrm{assign}$, i.e.\
$\mathrm{SatisfiesSat3}(\mathrm{assign}, f) = \texttt{true}$ iff
$\forall c \in f,\; \mathrm{SatisfiesClause}(\mathrm{assign}, c) = \texttt{true}$.
\end{definition}

n20750.content:
\begin{definition}[Satisfiability]
\lean{SATtoColor.IsSatisfiable}
\label{SATtoColor.IsSatisfiable}
\leanok
\uses{SATtoColor.Sat3, SATtoColor.SatisfiesSat3}
A 3-SAT instance $f$ is \emph{satisfiable} if there exists a Boolean
assignment that satisfies it:
\[
  \mathrm{IsSatisfiable}(f)
  \;:=\;
  \exists\,\mathrm{assign}: V \to \mathrm{Bool},\;
  \mathrm{SatisfiesSat3}(\mathrm{assign}, f) = \texttt{true}.
\]
\end{definition}

n20751.content:
\begin{definition}[Concrete 3-SAT example]
\lean{SATtoColor.SAT3_Example.sat3_inst}
\label{SATtoColor.SAT3_Example.sat3_inst}
\leanok
\uses{SATtoColor.Sat3}
A specific 3-SAT instance over four Boolean variables $x_0, x_1, x_2, x_3$
($V = \mathrm{Fin}\,4$), consisting of three clauses:
$(x_0 \vee \neg x_1 \vee \neg x_2)$,
$(\neg x_0 \vee x_1 \vee \neg x_2)$, and
$(\neg x_0 \vee \neg x_1 \vee \neg x_3)$.
\end{definition}

n20752.content:
\begin{definition}[Example assignment]
\lean{SATtoColor.SAT3_Example.ex_assign_1}
\label{SATtoColor.SAT3_Example.ex_assign_1}
\leanok
A concrete Boolean assignment for the example instance
$\texttt{SATtoColor.SAT3\_Example.sat3\_inst}$, defined as the vector
$[{\tt true},\,{\tt true},\,{\tt false},\,{\tt false}]$ indexed by
$\mathrm{Fin}\,4$.
\end{definition}

n20753.content:
\begin{definition}[Reduction vertex type]
\lean{SATtoColor.OutputVertex}
\label{SATtoColor.OutputVertex}
\leanok
\uses{SATtoColor.Clause}
The vertex set of the reduction graph is the inductive type
$\mathrm{OutputVertex}(V)$ with three constructors:
\begin{itemize}
  \item $\mathrm{palette}(p)$ for $p : \mathrm{Fin}\,3$ --- the three special
        palette nodes (Base $= 0$, True $= 1$, False $= 2$) forming a triangle
        that fixes color semantics;
  \item $\mathrm{literalNode}(\ell)$ --- one node per literal over $V$
        (positive and negative occurrences are separate nodes);
  \item $\mathrm{clauseGadget}(c, k)$ for $k : \mathrm{Fin}\,6$ --- six
        internal nodes per clause $c$ encoding the OR constraint.
\end{itemize}
\end{definition}

n20754.content:
\begin{definition}[3-colorability]
\lean{SATtoColor.Is3Colorable}
\label{SATtoColor.Is3Colorable}
\leanok
A simple graph $G$ on vertex type $V'$ is \emph{3-colorable} if there exists a
proper graph coloring with colors $\mathrm{Fin}\,3$, i.e.\
$\mathrm{Nonempty}(G.\mathrm{Coloring}(\mathrm{Fin}\,3))$.
\end{definition}

n20755.content:
\begin{definition}[Reduction edge relation]
\lean{SATtoColor.EdgeRelation}
\label{SATtoColor.EdgeRelation}
\leanok
\uses{SATtoColor.OutputVertex, SATtoColor.Sat3}
$\mathrm{EdgeRelation}(f, u, v)$ defines the (undirected) adjacency structure
of the reduction graph.  The edges are:
all pairs of distinct palette nodes;
every literal node to the Base palette node;
$\mathrm{pos}(x)$ to $\mathrm{neg}(x)$ for each variable $x$;
specific pairs of clause gadget nodes within the same clause (encoding two
internal triangles on nodes $\{0,1,2\}$ and $\{3,4,5\}$ plus the bridge
$2$--$3$);
each clause's three literal nodes to gadget nodes $0$, $1$, and $4$
respectively;
and gadget node $5$ of every clause to both the Base and the False palette
nodes.
\end{definition}

n20756.content:
\begin{definition}[Reduction graph]
\lean{SATtoColor.ReductionGraph}
\label{SATtoColor.ReductionGraph}
\leanok
\uses{SATtoColor.EdgeRelation, SATtoColor.OutputVertex, SATtoColor.Sat3}
Given a 3-SAT instance $f$ over variables $V$, the \emph{reduction graph}
$\mathrm{ReductionGraph}(f)$ is the \texttt{SimpleGraph} on
$\mathrm{OutputVertex}(V)$ whose adjacency relation is the symmetrisation of
$\mathrm{EdgeRelation}(f)$: two distinct vertices are adjacent iff
$\mathrm{EdgeRelation}(f, u, v)$ or $\mathrm{EdgeRelation}(f, v, u)$ holds.
\end{definition}

n20757.content:
\begin{definition}[Clause gadget coloring]
\lean{SATtoColor.clauseGadgetColor}
\label{SATtoColor.clauseGadgetColor}
\leanok
Given the Boolean truth values $a, b, c_3$ of the three literals of a clause,
$\mathrm{clauseGadgetColor}(a, b, c_3, k)$ assigns a color in $\mathrm{Fin}\,3$
to gadget node $k \in \{0,\ldots,5\}$.  In particular, node $5$ always receives
color $1$ (True), and the remaining nodes are colored so that all internal
gadget edges receive distinct colors whenever at least one literal is true.
\end{definition}

n20759.content:
\begin{lemma}[Literal node color formula]
\lean{SATtoColor.sat3Coloring_litNode}
\label{SATtoColor.sat3Coloring_litNode}
\leanok
\uses{SATtoColor.SatisfiesLiteral, SATtoColor.sat3Coloring}

For any assignment $\mathrm{assign}$ and literal $\ell$,
\[
  \mathrm{sat3Coloring}(\mathrm{assign},\,\mathrm{literalNode}(\ell))
  \;=\;
  \text{if } \mathrm{SatisfiesLiteral}(\mathrm{assign}, \ell) \text{ then } 1 \text{ else } 2.
\]
\end{lemma}

n20760.content:
\begin{lemma}[Completeness of reduction]
\lean{SATtoColor.SATtoColorCompleteness}
\label{SATtoColor.SATtoColorCompleteness}
\leanok
\uses{SATtoColor.EdgeRelation, SATtoColor.Is3Colorable, SATtoColor.IsSatisfiable, SATtoColor.OutputVertex, SATtoColor.ReductionGraph, SATtoColor.Sat3, SATtoColor.SatisfiesClause, SATtoColor.SatisfiesLiteral, SATtoColor.clauseGadgetColor, SATtoColor.sat3Coloring, SATtoColor.sat3Coloring_litNode}

If the 3-SAT instance $f$ is satisfiable, then the reduction graph
$\mathrm{ReductionGraph}(f)$ is 3-colorable.  Formally:
\[
  \mathrm{IsSatisfiable}(f) \;\Longrightarrow\;
  \mathrm{Is3Colorable}(\mathrm{ReductionGraph}(f)).
\]
\end{lemma}

n20761.content:
\begin{lemma}[Soundness of reduction]
\lean{SATtoColor.SATtoColorSoundness}
\label{SATtoColor.SATtoColorSoundness}
\leanok
\uses{SATtoColor.Clause, SATtoColor.EdgeRelation, SATtoColor.Is3Colorable, SATtoColor.IsSatisfiable, SATtoColor.OutputVertex, SATtoColor.ReductionGraph, SATtoColor.Sat3, SATtoColor.SatisfiesClause, SATtoColor.SatisfiesLiteral, SATtoColor.SatisfiesSat3}

If the reduction graph $\mathrm{ReductionGraph}(f)$ is 3-colorable, then the
3-SAT instance $f$ is satisfiable.  Formally:
\[
  \mathrm{Is3Colorable}(\mathrm{ReductionGraph}(f)) \;\Longrightarrow\;
  \mathrm{IsSatisfiable}(f).
\]
\end{lemma}

n20762.content:
\begin{theorem}[3-SAT to 3-Coloring reduction]
\lean{SATtoColor.SATtoColorReduction}
\label{SATtoColor.SATtoColorReduction}
\leanok
\uses{SATtoColor.Is3Colorable, SATtoColor.IsSatisfiable, SATtoColor.ReductionGraph, SATtoColor.SATtoColorCompleteness, SATtoColor.SATtoColorSoundness, SATtoColor.Sat3}

A 3-SAT instance $f$ is satisfiable if and only if the reduction graph is
3-colorable:
\[
  \mathrm{IsSatisfiable}(f)
  \;\longleftrightarrow\;
  \mathrm{Is3Colorable}(\mathrm{ReductionGraph}(f)).
\]
This is the conjunction of completeness and soundness of the reduction.
\end{theorem}

n20763.content:
\begin{definition}[Weighted edge]
\lean{Kruskal.WEdge}
\label{Kruskal.WEdge}
\leanok
A \emph{weighted edge} over $n$ vertices is a structure with two endpoints
$u, v : \mathrm{Fin}\,n$ and a natural-number weight $w : \mathbb{N}$.
\end{definition}

n20764.content:
\begin{definition}[Union-find type]
\lean{Kruskal.UF}
\label{Kruskal.UF}
\leanok
The union-find state for $n$ nodes is defined as a function
$\mathrm{Fin}\,n \to \mathbb{N}$ mapping each node to its current
representative (component label).
\end{definition}

n20765.content:
\begin{definition}[Initial union-find]
\lean{Kruskal.UF.init}
\label{Kruskal.UF.init}
\leanok
\uses{Kruskal.UF}
$\mathtt{init}\,n$ constructs the identity union-find on $n$ nodes: every node
$i$ is its own representative, i.e.\ $\mathtt{init}\,n\,(i) = i$.
\end{definition}

n20766.content:
\begin{definition}[Find representative]
\lean{Kruskal.UF.find}
\label{Kruskal.UF.find}
\leanok
\uses{Kruskal.UF}
$\mathtt{find}\,\mathit{uf}\,i$ returns the representative of node $i$ in
the union-find state $\mathit{uf}$, defined simply as $\mathit{uf}(i)$.
\end{definition}

n20767.content:
\begin{definition}[Merge two components]
\lean{Kruskal.UF.merge}
\label{Kruskal.UF.merge}
\leanok
\uses{Kruskal.UF}
$\mathtt{merge}\,\mathit{uf}\,i\,j$ unifies the components of nodes $i$ and
$j$ by reassigning every node whose representative equals $\mathit{uf}(j)$ to
instead carry the representative $\mathit{uf}(i)$.
\end{definition}

n20768.content:
\begin{lemma}[Initial find is identity]
\lean{Kruskal.UF.init_find}
\label{Kruskal.UF.init_find}
\leanok
\uses{Kruskal.UF.find, Kruskal.UF.init}

For every $i : \mathrm{Fin}\,n$, the find operation on the initial
union-find returns $i$'s numeric value: $(\mathtt{init}\,n).\mathtt{find}\,i = i.\mathtt{val}$.
\end{lemma}

n20769.content:
\begin{lemma}[Find unfolds to array lookup]
\lean{Kruskal.UF.find_def}
\label{Kruskal.UF.find_def}
\leanok
\uses{Kruskal.UF, Kruskal.UF.find}

For any union-find state $\mathit{uf}$ and index $i$,
$\mathit{uf}.\mathtt{find}\,i = \mathit{uf}(i)$; this is the unfolding
simp-lemma for \texttt{find}.
\end{lemma}

n20770.content:
\begin{definition}[Merge all edges into union-find]
\lean{Kruskal.UF.mergeAll}
\label{Kruskal.UF.mergeAll}
\leanok
\uses{Kruskal.UF, Kruskal.UF.merge, Kruskal.WEdge}
$\mathtt{mergeAll}\,\mathit{uf}\,\mathit{es}$ folds a list of weighted edges
$\mathit{es}$ into the union-find $\mathit{uf}$ by calling \texttt{merge} on
each edge's endpoints in sequence.
\end{definition}

n20771.content:
\begin{definition}[Same partition predicate]
\lean{Kruskal.UF.SamePartition}
\label{Kruskal.UF.SamePartition}
\leanok
\uses{Kruskal.UF}
$\mathtt{SamePartition}\,\mathit{uf}_1\,\mathit{uf}_2$ holds when two
union-find states induce the same equivalence relation on nodes: for all
$i, j : \mathrm{Fin}\,n$, $\mathit{uf}_1(i) = \mathit{uf}_1(j)$ if and
only if $\mathit{uf}_2(i) = \mathit{uf}_2(j)$.
\end{definition}

n20772.content:
\begin{definition}[Edge-selection sweep]
\lean{Kruskal.processEdges}
\label{Kruskal.processEdges}
\leanok
\uses{Kruskal.UF, Kruskal.UF.find, Kruskal.UF.merge, Kruskal.WEdge}
$\mathtt{processEdges}\,\mathit{es}\,\mathit{uf}\,\mathit{acc}$ scans the
edge list $\mathit{es}$ left-to-right: an edge $e$ is added to the
accumulator and its endpoints are merged whenever
$\mathit{uf}.\mathtt{find}\,e.u \ne \mathit{uf}.\mathtt{find}\,e.v$;
otherwise $e$ is skipped.  The reversed accumulator is returned when the
list is exhausted.
\end{definition}

n20773.content:
\begin{definition}[Kruskal's algorithm]
\lean{Kruskal.kruskal}
\label{Kruskal.kruskal}
\leanok
\uses{Kruskal.UF.init, Kruskal.WEdge, Kruskal.processEdges}
$\mathtt{kruskal}\,n\,\mathit{edges}$ sorts the edge list by weight and then
runs \texttt{processEdges} on the sorted list starting from the identity
union-find, returning the selected spanning-tree edges.
\end{definition}

n20774.content:
\begin{lemma}[Output of processEdges comes from input or accumulator]
\lean{Kruskal.processEdges_mem}
\label{Kruskal.processEdges_mem}
\leanok
\uses{Kruskal.UF, Kruskal.WEdge, Kruskal.processEdges}

Let $\mathit{es}$ be a list of weighted edges, $\mathit{uf}$ a union-find
state, $\mathit{acc}$ an accumulator list, and $e$ an edge.  If
$e \in \mathtt{processEdges}\,\mathit{es}\,\mathit{uf}\,\mathit{acc}$, then
$e \in \mathit{acc}$ or $e \in \mathit{es}$.
\end{lemma}

n20775.content:
\begin{lemma}[Kruskal output is a subset of the input]
\lean{Kruskal.kruskal_subset}
\label{Kruskal.kruskal_subset}
\leanok
\uses{Kruskal.WEdge, Kruskal.kruskal, Kruskal.processEdges_mem}

Every edge $e$ returned by $\mathtt{kruskal}\,n\,\mathit{edges}$ was already
present in $\mathit{edges}$: if $e \in \mathtt{kruskal}\,n\,\mathit{edges}$
then $e \in \mathit{edges}$.
\end{lemma}

n20776.content:
\begin{definition}[Symmetric adjacency]
\lean{Kruskal.SymAdj}
\label{Kruskal.SymAdj}
\leanok
\uses{Kruskal.WEdge}
Given a list of weighted edges $\mathit{edges}$ on $n$ vertices, $\mathtt{SymAdj}\,\mathit{edges}\,u\,v$
holds when there exists an edge $e \in \mathit{edges}$ whose endpoints are $\{u, v\}$
(in either order), i.e.\ $(e.u = u \wedge e.v = v) \vee (e.u = v \wedge e.v = u)$.
\end{definition}

n20777.content:
\begin{definition}[Reachability]
\lean{Kruskal.Reach}
\label{Kruskal.Reach}
\leanok
\uses{Kruskal.SymAdj, Kruskal.WEdge}
$\mathtt{Reach}\,\mathit{edges}$ is the reflexive--transitive closure of
$\mathtt{SymAdj}\,\mathit{edges}$; that is, $\mathtt{Reach}\,\mathit{edges}\,u\,v$
holds when $u$ and $v$ are connected by a path through edges in $\mathit{edges}$.
\end{definition}

n20778.content:
\begin{definition}[Total weight]
\lean{Kruskal.totalWeight}
\label{Kruskal.totalWeight}
\leanok
\uses{Kruskal.WEdge}
The total weight of an edge list is the sum of the weights of all its edges:
$\mathtt{totalWeight}\,\mathit{edges} = \sum_{e \in \mathit{edges}} e.\mathit{weight}$.
\end{definition}

n20779.content:
\begin{definition}[Spanning like]
\lean{Kruskal.SpansLike}
\label{Kruskal.SpansLike}
\leanok
\uses{Kruskal.Reach, Kruskal.WEdge}
$\mathtt{SpansLike}\,F\,E$ holds when the edge list $F$ is at least as connected as $E$:
for every pair of vertices $u, v$, if $u$ and $v$ are reachable in $E$ then they are
also reachable in $F$.
\end{definition}

n20780.content:
\begin{lemma}[Symmetry of symmetric adjacency]
\lean{Kruskal.symAdj_symm}
\label{Kruskal.symAdj_symm}
\leanok
\uses{Kruskal.SymAdj, Kruskal.WEdge}

If $\mathtt{SymAdj}\,\mathit{edges}\,u\,v$ then $\mathtt{SymAdj}\,\mathit{edges}\,v\,u$.
\end{lemma}

n20781.content:
\begin{lemma}[Monotonicity of symmetric adjacency]
\lean{Kruskal.symAdj_mono}
\label{Kruskal.symAdj_mono}
\leanok
\uses{Kruskal.SymAdj, Kruskal.WEdge}

If $\mathtt{SymAdj}\,e_1\,u\,v$ and every edge of $e_1$ also belongs to $e_2$, then
$\mathtt{SymAdj}\,e_2\,u\,v$.
\end{lemma}

n20782.content:
\begin{lemma}[Symmetry of reachability]
\lean{Kruskal.reach_symm}
\label{Kruskal.reach_symm}
\leanok
\uses{Kruskal.Reach, Kruskal.WEdge, Kruskal.symAdj_symm}

If $\mathtt{Reach}\,\mathit{edges}\,u\,v$ then $\mathtt{Reach}\,\mathit{edges}\,v\,u$.
\end{lemma}

n20783.content:
\begin{lemma}[Monotonicity of reachability]
\lean{Kruskal.reach_mono}
\label{Kruskal.reach_mono}
\leanok
\uses{Kruskal.Reach, Kruskal.WEdge, Kruskal.symAdj_mono}

If $\mathtt{Reach}\,e_1\,u\,v$ and every edge of $e_1$ also belongs to $e_2$, then
$\mathtt{Reach}\,e_2\,u\,v$.
\end{lemma}

n20784.content:
\begin{lemma}[Reachability from a membership witness]
\lean{Kruskal.reach_of_mem}
\label{Kruskal.reach_of_mem}
\leanok
\uses{Kruskal.Reach, Kruskal.WEdge}

If $e \in \mathit{edges}$ then $\mathtt{Reach}\,\mathit{edges}\,e.u\,e.v$; that is,
the two endpoints of any listed edge are immediately reachable from each other.
\end{lemma}

n20785.content:
\begin{lemma}[Reachability lifting]
\lean{Kruskal.reach_lift}
\label{Kruskal.reach_lift}
\leanok
\uses{Kruskal.Reach, Kruskal.SymAdj, Kruskal.WEdge, Kruskal.reach_mem_iff}

If every symmetric adjacency in $\mathit{edges}$ implies reachability in
$\mathit{edges}'$, and $\mathtt{Reach}\,\mathit{edges}\,u\,v$, then
$\mathtt{Reach}\,\mathit{edges}'\,u\,v$.
\end{lemma}

n20786.content:
\begin{lemma}[Cons decomposition of reachability]
\lean{Kruskal.reach_cons_iff}
\label{Kruskal.reach_cons_iff}
\leanok
\uses{Kruskal.Reach, Kruskal.WEdge, Kruskal.reach_mono, Kruskal.reach_of_mem, Kruskal.reach_symm}

For a non-empty edge list $(g :: \mathit{rest})$, $\mathtt{Reach}\,(g :: \mathit{rest})\,a\,b$
if and only if one of three cases holds: (1) $\mathtt{Reach}\,\mathit{rest}\,a\,b$;
(2) $\mathtt{Reach}\,\mathit{rest}\,a\,g.u$ and $\mathtt{Reach}\,\mathit{rest}\,g.v\,b$;
or (3) $\mathtt{Reach}\,\mathit{rest}\,a\,g.v$ and $\mathtt{Reach}\,\mathit{rest}\,g.u\,b$.
\end{lemma}

n20787.content:
\begin{lemma}[Reachability depends only on membership]
\lean{Kruskal.reach_mem_iff}
\label{Kruskal.reach_mem_iff}
\leanok
\uses{Kruskal.Reach, Kruskal.WEdge, Kruskal.reach_mono}

If two edge lists $l_1$ and $l_2$ have the same elements (i.e.\
$\forall x,\; x \in l_1 \leftrightarrow x \in l_2$), then
$\mathtt{Reach}\,l_1\,a\,b \leftrightarrow \mathtt{Reach}\,l_2\,a\,b$.
\end{lemma}

n20789.content:
\begin{lemma}[Total weight after erasing an edge]
\lean{Kruskal.totalWeight_erase}
\label{Kruskal.totalWeight_erase}
\leanok
\uses{Kruskal.WEdge, Kruskal.totalWeight}

If $e \in \mathit{edges}$ then
$\mathtt{totalWeight}\,\mathit{edges} = e.\mathit{weight} + \mathtt{totalWeight}\,(\mathit{edges}.\mathtt{erase}\,e)$.
\end{lemma}

n20790.content:
\begin{definition}[Vote set for a label]
\lean{Halving.voteFor}
\label{Halving.voteFor}
\leanok
Given an evaluation map $\mathtt{eval} : \mathit{Hyp} \to X \to \mathsf{Bool}$, a
version space $V \subseteq \mathit{Hyp}$, an input $x \in X$, and a label
$y \in \mathsf{Bool}$, $\mathtt{voteFor}(\mathtt{eval}, V, x, y)$ is the subset of $V$
consisting of all hypotheses that predict label $y$ on input $x$.
\end{definition}

n20791.content:
\begin{definition}[Halving prediction]
\lean{Halving.predict}
\label{Halving.predict}
\leanok
\uses{Halving.voteFor}
The Halving Algorithm predicts on input $x$ by taking a majority vote of the current
version space $V$: it returns $\mathsf{true}$ whenever the number of hypotheses in $V$
that predict $\mathsf{true}$ is at least as large as the number that predict
$\mathsf{false}$ (ties are broken in favour of $\mathsf{true}$).
\end{definition}

n20792.content:
\begin{definition}[Version-space update]
\lean{Halving.update}
\label{Halving.update}
\leanok
\uses{Halving.voteFor}
After observing that the correct label for input $x$ is $y$, the version space is
updated to $\mathtt{update}(\mathtt{eval}, V, x, y) = \mathtt{voteFor}(\mathtt{eval},
V, x, y)$, i.e.\ only the hypotheses that correctly predict $y$ on $x$ are retained.
\end{definition}

n20793.content:
\begin{lemma}[Partition of version space by vote]
\lean{Halving.voteFor_false_add_true}
\label{Halving.voteFor_false_add_true}
\leanok
\uses{Halving.voteFor}

For any version space $V$ and input $x$, the false-voters and true-voters partition
$V$:
\[
  |\mathtt{voteFor}(\mathtt{eval}, V, x, \mathsf{false})| +
  |\mathtt{voteFor}(\mathtt{eval}, V, x, \mathsf{true})| = |V|.
\]
\end{lemma}

n20794.content:
\begin{lemma}[Update is a subset]
\lean{Halving.update_subset}
\label{Halving.update_subset}
\leanok
\uses{Halving.update, Halving.voteFor}

The updated version space is always a subset of the previous one:
$\mathtt{update}(\mathtt{eval}, V, x, y) \subseteq V$.
\end{lemma}

n20795.content:
\begin{lemma}[Target survives every update]
\lean{Halving.target_mem_update}
\label{Halving.target_mem_update}
\leanok
\uses{Halving.update, Halving.voteFor}

In the realizable setting, if $\mathtt{target} \in V$ then after updating on the
correctly labelled example $(x,\, \mathtt{eval}\;\mathtt{target}\;x)$ the target
hypothesis remains in the new version space:
$\mathtt{target} \in \mathtt{update}(\mathtt{eval}, V, x, \mathtt{eval}\;\mathtt{target}\;x)$.
\end{lemma}

n20796.content:
\begin{lemma}[Mistakes halve the version space]
\lean{Halving.mistake_halves}
\label{Halving.mistake_halves}
\leanok
\uses{Halving.predict, Halving.update, Halving.voteFor, Halving.voteFor_false_add_true}

If the algorithm makes a mistake on input $x$ with true label $y$ (i.e.\
$\mathtt{predict}(\mathtt{eval}, V, x) \ne y$), then after the update at most half
the hypotheses survive:
\[
  2 \cdot |\mathtt{update}(\mathtt{eval}, V, x, y)| \;\le\; |V|.
\]
\end{lemma}

n20797.content:
\begin{lemma}[Logarithm step from doubling]
\lean{Halving.log_succ_le_log_of_double_le}
\label{Halving.log_succ_le_log_of_double_le}
\leanok

For natural numbers $a$ and $b$ with $b > 0$ and $2b \le a$,
\[
  \lfloor\log_2 b\rfloor + 1 \;\le\; \lfloor\log_2 a\rfloor.
\]
\end{lemma}

n20798.content:
\begin{definition}[Mistake count over a sequence]
\lean{Halving.mistakes}
\label{Halving.mistakes}
\leanok
\uses{Halving.predict, Halving.update}
$\mathtt{mistakes}(\mathtt{eval}, \mathtt{target}, V, xs)$ is the total number of
prediction errors made by the Halving Algorithm when it processes the input list $xs$,
using the version space $V$, with the true label at each step supplied by
$\mathtt{target}$.  It is defined recursively: the empty list yields zero mistakes, and
for a list $x :: xs$ the count is $1$ if the algorithm mispredicts on $x$ (else $0$),
plus the mistakes on the remainder using the updated version space.
\end{definition}

n20799.content:
\begin{theorem}[Mistake bound — general version space]
\lean{Halving.mistakes_bound}
\label{Halving.mistakes_bound}
\leanok
\uses{Halving.log_succ_le_log_of_double_le, Halving.mistake_halves, Halving.mistakes, Halving.predict, Halving.target_mem_update, Halving.update, Halving.update_subset}

In the realizable setting ($\mathtt{target} \in V$), the total number of mistakes made
by the Halving Algorithm on any input sequence $xs$ is at most $\lfloor\log_2
|V|\rfloor$:
\[
  \mathtt{mistakes}(\mathtt{eval}, \mathtt{target}, V, xs)
  \;\le\; \lfloor\log_2 |V|\rfloor.
\]
\end{theorem}

n20800.content:
\begin{theorem}[Halving mistake bound]
\lean{Halving.halving_bound}
\label{Halving.halving_bound}
\leanok
\uses{Halving.mistakes, Halving.mistakes_bound}

Specialising to the initial hypothesis class $H$ (with $\mathtt{target} \in H$), the
Halving Algorithm makes at most $\lfloor\log_2 |H|\rfloor$ mistakes on any input
sequence:
\[
  \mathtt{mistakes}(\mathtt{eval}, \mathtt{target}, H, xs)
  \;\le\; \lfloor\log_2 |H|\rfloor.
\]
\end{theorem}

n20801.content:
\begin{definition}[Loss sequence]
\lean{LossSeq}
\label{LossSeq}
\leanok
A \emph{loss sequence} $\ell$ for $N$ experts over $T$ rounds is a function
$\ell : \mathrm{Fin}\,T \to \mathrm{Fin}\,N \to \mathbb{R}$, i.e., at each round
$t < T$ the adversary reveals a loss vector $\ell_t : \mathrm{Fin}\,N \to \mathbb{R}$
whose values are intended to lie in $[0,1]$.
\end{definition}

n20802.content:
\begin{definition}[Valid loss sequence]
\lean{LossSeq.Valid}
\label{LossSeq.Valid}
\leanok
\uses{LossSeq}
A loss sequence $\ell$ is \emph{valid} if all individual losses are in $[0,1]$:
$\forall t\,i,\; 0 \le \ell_t(i) \le 1$.
\end{definition}

n20803.content:
\begin{definition}[Cumulative loss]
\lean{cumLoss}
\label{cumLoss}
\leanok
\uses{LossSeq}
The \emph{cumulative loss} of expert $i$ through the first $t$ rounds is
\[
  L_t(i) \;=\; \sum_{s < t} \ell_s(i),
\]
where the sum ranges over all rounds $s \in \mathrm{Fin}\,T$ with $s < t$.
\end{definition}

n20804.content:
\begin{definition}[Hedge weight]
\lean{hedgeWeight}
\label{hedgeWeight}
\leanok
\uses{LossSeq, cumLoss}
The \emph{unnormalized Hedge weight} of expert $i$ at time $t$ with learning
rate $\eta$ is
\[
  w_t(i) \;=\; \exp\!\bigl(-\eta \cdot L_t(i)\bigr).
\]
Experts with smaller cumulative loss receive larger weight.
\end{definition}

n20805.content:
\begin{definition}[Potential]
\lean{potential}
\label{potential}
\leanok
\uses{LossSeq, hedgeWeight}
The \emph{potential} (sum of unnormalized weights) at time $t$ is
\[
  W_t \;=\; \sum_{i=1}^{N} w_t(i).
\]
The potential telescopes to relate the learner's cumulative loss to the best
expert's loss.
\end{definition}

n20806.content:
\begin{definition}[Hedge distribution]
\lean{hedgeDist}
\label{hedgeDist}
\leanok
\uses{LossSeq, hedgeWeight, potential}
The \emph{Hedge distribution} at round $t$ is the normalization of the weight
vector:
\[
  p_t(i) \;=\; \frac{w_t(i)}{W_t}.
\]
\end{definition}

n20807.content:
\begin{definition}[Expected loss of Hedge]
\lean{hedgeLoss}
\label{hedgeLoss}
\leanok
\uses{LossSeq, hedgeDist}
The \emph{expected loss} of the learner at round $t$ under the Hedge
distribution is
\[
  \widehat{\ell}_t \;=\; \sum_{i=1}^{N} p_t(i)\,\ell_t(i).
\]
\end{definition}

n20808.content:
\begin{definition}[Cumulative loss of Hedge]
\lean{hedgeCumLoss}
\label{hedgeCumLoss}
\leanok
\uses{LossSeq, hedgeLoss}
The \emph{cumulative loss} of the Hedge algorithm over all $T$ rounds is
\[
  \widehat{L}_T \;=\; \sum_{t=0}^{T-1} \widehat{\ell}_t.
\]
\end{definition}

n20809.content:
\begin{definition}[Best expert loss]
\lean{bestExpertLoss}
\label{bestExpertLoss}
\leanok
\uses{LossSeq, cumLoss}
The \emph{best expert loss in hindsight} is the minimum cumulative loss
achieved by any single expert:
\[
  L^* \;=\; \min_{i \in [N]} L_T(i) \;=\; \inf_{i : \mathrm{Fin}\,N} \,L_T(i).
\]
\end{definition}

n20810.content:
\begin{definition}[Regret]
\lean{regret}
\label{regret}
\leanok
\uses{LossSeq, bestExpertLoss, hedgeCumLoss}
The \emph{regret} of the Hedge algorithm is the excess cumulative loss over the
best expert in hindsight:
\[
  R_T(\eta) \;=\; \widehat{L}_T - L^*.
\]
\end{definition}

n20811.content:
\begin{lemma}[Potential at time zero]
\lean{potential_zero}
\label{potential_zero}
\leanok
\uses{LossSeq, cumLoss, hedgeWeight, potential}

At time $0$, all cumulative losses are zero, so every weight equals $1$, and
the potential equals the number of experts: $W_0 = N$.
\end{lemma}

n20812.content:
\begin{lemma}[Positivity of weights]
\lean{hedgeWeight_pos}
\label{hedgeWeight_pos}
\leanok
\uses{LossSeq, hedgeWeight}

For any $\eta$, loss sequence $\ell$, time $t$, and expert $i$, the weight
$w_t(i) = \exp(-\eta \cdot L_t(i))$ is strictly positive.
\end{lemma}

n20813.content:
\begin{lemma}[Positivity of the potential]
\lean{potential_pos}
\label{potential_pos}
\leanok
\uses{LossSeq, hedgeWeight_pos, potential}

For any $\eta$, loss sequence $\ell$, and time $t$, the potential $W_t > 0$.
This follows because $W_t$ is a finite sum of positive terms over the nonempty
set of $N \ge 1$ experts.
\end{lemma}

n20815.content:
\begin{lemma}[Cumulative loss successor step]
\lean{cumLoss_succ}
\label{cumLoss_succ}
\leanok
\uses{LossSeq, cumLoss}

The cumulative loss satisfies the recurrence
\[
  L_{t+1}(i) \;=\; L_t(i) + \ell_t(i)
\]
for every $t < T$ and expert $i$.
\end{lemma}

n20816.content:
\begin{lemma}[Cumulative loss at the horizon]
\lean{cumLoss_horizon}
\label{cumLoss_horizon}
\leanok
\uses{LossSeq, cumLoss}

At the final horizon, $L_T(i) = \sum_{t : \mathrm{Fin}\,T} \ell_t(i)$, i.e.,
the cumulative loss through $T$ equals the full sum over all rounds.
\end{lemma}

n20817.content:
\begin{lemma}[Weight successor factorization]
\lean{hedgeWeight_succ}
\label{hedgeWeight_succ}
\leanok
\uses{LossSeq, cumLoss_succ, hedgeWeight}

The weight factorizes across rounds:
\[
  w_{t+1}(i) \;=\; w_t(i) \cdot \exp\!\bigl(-\eta\,\ell_t(i)\bigr).
\]
\end{lemma}

n20818.content:
\begin{lemma}[Hedge distribution sums to one]
\lean{hedgeDist_sum}
\label{hedgeDist_sum}
\leanok
\uses{LossSeq, hedgeDist, potential_pos}

For any $\eta$, valid loss sequence $\ell$, and time $t$,
$\sum_{i=1}^{N} p_t(i) = 1$, so the Hedge distribution is a proper probability
distribution.
\end{lemma}

n20819.content:
\begin{lemma}[Potential ratio bound]
\lean{potential_ratio_le}
\label{potential_ratio_le}
\leanok
\uses{LossSeq, LossSeq.Valid, exp_neg_le_linear, hedgeDist, hedgeLoss, hedgeWeight, hedgeWeight_pos, hedgeWeight_succ, potential, potential_pos}

For a valid loss sequence and $\eta > 0$, the ratio of consecutive potentials
satisfies
\[
  \frac{W_{t+1}}{W_t} \;\le\; 1 - (1 - e^{-\eta})\,\widehat{\ell}_t,
\]
where $\widehat{\ell}_t = \sum_i p_t(i)\,\ell_t(i)$ is the expected loss at
round $t$.  This is the key potential-ratio lemma of Cesa-Bianchi and Lugosi.
\end{lemma}

n20820.content:
\begin{lemma}[Logarithmic potential step bound]
\lean{log_potential_step}
\label{log_potential_step}
\leanok
\uses{LossSeq, LossSeq.Valid, hedgeLoss, potential, potential_pos, potential_ratio_le}

For a valid loss sequence, $\eta > 0$, and $t < T$,
\[
  \ln W_{t+1} - \ln W_t \;\le\; -(1 - e^{-\eta})\,\widehat{\ell}_t,
\]
which follows from $\ln(1-x) \le -x$ applied to the potential ratio bound.
\end{lemma}

n20821.content:
\begin{lemma}[Quadratic upper bound on $e^{-t}$]
\lean{exp_neg_le_quadratic}
\label{exp_neg_le_quadratic}
\leanok

For $t \ge 0$,
\[
  e^{-t} \;\le\; 1 - t + \frac{t^2}{2}.
\]
\end{lemma}

n20822.content:
\begin{lemma}[Lower bound on $1 - e^{-\eta}$]
\lean{one_sub_exp_neg_ge}
\label{one_sub_exp_neg_ge}
\leanok
\uses{exp_neg_le_quadratic}

For $\eta > 0$,
\[
  1 - e^{-\eta} \;\ge\; \eta - \frac{\eta^2}{2}.
\]
This follows directly from the quadratic bound $e^{-\eta} \le 1 - \eta + \eta^2/2$.
\end{lemma}

n20823.content:
\begin{lemma}[Lower bound on potential via best expert]
\lean{potential_ge_best_expert}
\label{potential_ge_best_expert}
\leanok
\uses{LossSeq, bestExpertLoss, cumLoss, hedgeWeight, potential}

The final potential is at least the weight of the best expert:
\[
  W_T \;\ge\; \exp\!\bigl(-\eta \cdot L^*\bigr),
\]
where $L^* = \min_i L_T(i)$ is the best expert's cumulative loss.
\end{lemma}

n20824.content:
\begin{lemma}[Hedge distribution is nonnegative]
\lean{hedgeDist_nonneg}
\label{hedgeDist_nonneg}
\leanok
\uses{LossSeq, hedgeDist, hedgeWeight_pos, potential_pos}

For any $\eta$, loss sequence $\ell$, time $t$, and expert $i$, the Hedge
distribution satisfies $p_t(i) \ge 0$.
\end{lemma}

n20825.content:
\begin{lemma}[Expected loss at most one]
\lean{hedgeLoss_le_one}
\label{hedgeLoss_le_one}
\leanok
\uses{LossSeq, LossSeq.Valid, hedgeDist, hedgeDist_nonneg, hedgeDist_sum, hedgeLoss}

For a valid loss sequence, the expected loss at each round satisfies
$\widehat{\ell}_t \le 1$, since individual losses are at most $1$ and the
Hedge distribution is a probability measure.
\end{lemma}

n20826.content:
\begin{lemma}[Expected loss nonnegative]
\lean{hedgeLoss_nonneg}
\label{hedgeLoss_nonneg}
\leanok
\uses{LossSeq, LossSeq.Valid, hedgeDist_nonneg, hedgeLoss}

For a valid loss sequence, the expected loss at each round satisfies
$\widehat{\ell}_t \ge 0$, since individual losses are nonnegative and the
Hedge distribution is nonnegative.
\end{lemma}

n20827.content:
\begin{theorem}[Hedge regret bound]
\lean{hedge_regret_bound}
\label{hedge_regret_bound}
\leanok
\uses{LossSeq, LossSeq.Valid, bestExpertLoss, hedgeCumLoss, hedgeLoss, hedgeLoss_le_one, hedgeLoss_nonneg, log_potential_step, one_sub_exp_neg_ge, potential, potential_ge_best_expert, potential_zero, regret}

\textbf{Hedge Regret Bound} (Cesa-Bianchi \& Lugosi, Theorem 2.2).
For any valid loss sequence with $N$ experts, $T$ rounds, and $\eta \in (0,1]$,
\[
  R_T(\eta) \;\le\; \frac{\ln N}{\eta} + \frac{\eta T}{2}.
\]
\end{theorem}

n20828.content:
\begin{definition}[Optimal learning rate]
\lean{optimalEta}
\label{optimalEta}
\leanok
The \emph{optimal learning rate} balancing the two terms of the Hedge regret
bound is
\[
  \eta^* \;=\; \sqrt{\frac{2\ln N}{T}}.
\]
\end{definition}

n20829.content:
\begin{theorem}[Hedge with optimal learning rate]
\lean{hedge_regret_optimal}
\label{hedge_regret_optimal}
\leanok
\uses{LossSeq, LossSeq.Valid, hedge_regret_bound, optimalEta, regret}

If $T \ge 2\ln N$ (so that $\eta^* \le 1$), then for any valid loss sequence,
\[
  R_T(\eta^*) \;\le\; \sqrt{2\,T\ln N}.
\]
\end{theorem}

n20830.content:
\begin{theorem}[Hedge is no-regret]
\lean{hedge_no_regret}
\label{hedge_no_regret}
\leanok
\uses{LossSeq, LossSeq.Valid, hedge_regret_optimal, optimalEta, regret}

If $T \ge 2\ln N$, then for any valid loss sequence the \emph{average regret}
satisfies
\[
  \frac{R_T(\eta^*)}{T} \;\le\; \sqrt{\frac{2\ln N}{T}},
\]
which tends to $0$ as $T \to \infty$ with $N$ fixed, confirming that Hedge is
a no-regret algorithm.
\end{theorem}

n20831.content:
\begin{lemma}[Hoeffding's lemma]
\lean{hoeffding_lemma}
\label{hoeffding_lemma}
\leanok
\uses{bernoulli_mgf_bound}

For $p \in [0,1]$ and any $h \in \mathbb{R}$,
\[
  \ln\!\bigl((1-p) + p\,e^h\bigr) \;\le\; p\,h + \frac{h^2}{8}.
\]
This specializes the Bernoulli moment-generating-function bound from
\texttt{bernoulli\_mgf\_bound} by substituting $\eta = -h$.
\end{lemma}

n20832.content:
\begin{lemma}[Tight per-step logarithmic potential bound]
\lean{log_potential_step_tight}
\label{log_potential_step_tight}
\leanok
\uses{LossSeq, LossSeq.Valid, hedgeLoss, hedgeLoss_le_one, hedgeLoss_nonneg, hoeffding_lemma, potential, potential_pos, potential_ratio_le}

For a valid loss sequence and $\eta > 0$, applying Hoeffding's lemma gives the
tighter per-step bound
\[
  \ln W_{t+1} - \ln W_t \;\le\; -\eta\,\widehat{\ell}_t + \frac{\eta^2}{8}.
\]
\end{lemma}

n20833.content:
\begin{theorem}[Tight Hedge regret bound]
\lean{hedge_regret_bound_tight}
\label{hedge_regret_bound_tight}
\leanok
\uses{LossSeq, LossSeq.Valid, bestExpertLoss, hedgeCumLoss, hedgeLoss, log_potential_step_tight, potential, potential_ge_best_expert, potential_zero, regret}

\textbf{Tight Hedge Regret Bound} (Cesa-Bianchi \& Lugosi).
For any valid loss sequence with $N$ experts, $T$ rounds, and $\eta > 0$,
\[
  R_T(\eta) \;\le\; \frac{\ln N}{\eta} + \frac{\eta T}{8}.
\]
\end{theorem}

n20834.content:
\begin{definition}[Tight optimal learning rate]
\lean{optimalEtaTight}
\label{optimalEtaTight}
\leanok
The learning rate that optimizes the tight Hedge bound is
\[
  \eta_{\mathrm{tight}} \;=\; \sqrt{\frac{8\ln N}{T}}.
\]
\end{definition}

n20835.content:
\begin{theorem}[Tight Hedge with optimal learning rate]
\lean{hedge_regret_tight_optimal}
\label{hedge_regret_tight_optimal}
\leanok
\uses{LossSeq, LossSeq.Valid, hedge_regret_bound_tight, optimalEtaTight, regret}

For any valid loss sequence with $N > 1$ experts, $T \ge 1$ rounds, using
$\eta_{\mathrm{tight}} = \sqrt{8\ln N / T}$,
\[
  R_T(\eta_{\mathrm{tight}}) \;\le\; \sqrt{\frac{T}{2}\ln N}.
\]
\end{theorem}

n20836.content:
\begin{definition}[Induced loss sequence]
\lean{inducedLoss}
\label{inducedLoss}
\leanok
\uses{LossSeq}
Given a loss function $\ell : \mathbb{R} \to \Omega \to \mathbb{R}$, expert predictions
$p : \mathrm{Fin}\,T \to \mathrm{Fin}\,N \to \mathbb{R}$, and a sequence of outcomes
$o : \mathrm{Fin}\,T \to \Omega$, the \emph{induced loss sequence} is the abstract
loss table $L : \mathrm{LossSeq}\,N\,T$ defined by $L_{t,i} = \ell(p_t(i),\, o_t)$,
i.e.\ expert $i$ at round $t$ incurs the loss its own prediction receives under the
realized outcome.
\end{definition}

n20838.content:
\begin{definition}[Cumulative loss of Hedge's predictions]
\lean{hedgePredictionCumLoss}
\label{hedgePredictionCumLoss}
\leanok
\uses{hedgePrediction}
The \emph{actual cumulative prediction loss} of Hedge is
\[
  \mathcal{L}^{\mathrm{pred}}_T \;=\; \sum_{t=0}^{T-1} \ell\!\left(\widehat{x}_t,\, o_t\right),
\]
where $\widehat{x}_t$ is the Hedge weighted-average prediction at round $t$.  This
differs from \texttt{hedgeCumLoss}: here the loss is applied to the averaged
prediction, not to a weighted average of expert losses.
\end{definition}

n20839.content:
\begin{lemma}[Weighted average stays in convex set]
\lean{hedgePrediction_mem}
\label{hedgePrediction_mem}
\leanok
\uses{hedgeDist, hedgeDist_nonneg, hedgeDist_sum, hedgePrediction, inducedLoss}

Let $S \subseteq \mathbb{R}$ be a convex set and suppose every expert prediction
satisfies $p_t(i) \in S$ for all $t$ and $i$.  Then Hedge's weighted-average
prediction $\widehat{x}_t \in S$ for every round $t$.  The result follows because
the Hedge weights are nonneg\-ative and sum to one, so the weighted average is a
convex combination of points in $S$.
\end{lemma}

n20840.content:
\begin{lemma}[Jensen bridge: prediction loss bounded by Hedge loss]
\lean{hedgePrediction_loss_le_hedgeLoss}
\label{hedgePrediction_loss_le_hedgeLoss}
\leanok
\uses{hedgeDist, hedgeDist_nonneg, hedgeDist_sum, hedgeLoss, hedgePrediction, hedgePrediction_mem, inducedLoss}

Under the same hypotheses as above, assume additionally that for each round $t$ the
map $x \mapsto \ell(x, o_t)$ is convex on $S$.  Then Jensen's inequality gives, for
every $t$,
\[
  \ell\!\left(\widehat{x}_t,\, o_t\right)
  \;\le\;
  \texttt{hedgeLoss}\,\eta\,L\,t
  \;=\;
  \sum_{i} w^{(\eta)}_{t,i}\,\ell(p_t(i),\, o_t).
\]
That is, the loss of the averaged prediction is at most the Hedge-weighted average of
the individual expert losses.
\end{lemma}

n20841.content:
\begin{lemma}[Cumulative Jensen inequality]
\lean{hedgePredictionCumLoss_le_hedgeCumLoss}
\label{hedgePredictionCumLoss_le_hedgeCumLoss}
\leanok
\uses{hedgeCumLoss, hedgePredictionCumLoss, hedgePrediction_loss_le_hedgeLoss, inducedLoss}

Summing the per-round Jensen bound over all $T$ rounds, we obtain
\[
  \mathcal{L}^{\mathrm{pred}}_T
  \;\le\;
  \texttt{hedgeCumLoss}\,\eta\,L,
\]
i.e.\ the actual cumulative loss of Hedge's convex-combination predictions is at most
the abstract cumulative Hedge loss on the induced expert loss table.
\end{lemma}

n20843.content:
\begin{theorem}[Optimal-rate regret bound for convex prediction]
\lean{hedgePrediction_regret_tight_optimal}
\label{hedgePrediction_regret_tight_optimal}
\leanok
\uses{LossSeq.Valid, bestExpertLoss, hedgePredictionCumLoss, hedgePredictionCumLoss_le_hedgeCumLoss, hedge_regret_tight_optimal, inducedLoss, optimalEtaTight, regret}

Under the same convexity hypotheses, with $T > 0$, $N > 1$, and the learning rate set
to $\eta^* = \texttt{optimalEtaTight}\,N\,T$, the regret satisfies
\[
  \mathcal{L}^{\mathrm{pred}}_T
    - \min_{i}\,\sum_{t} \ell(p_t(i),\, o_t)
  \;\le\;
  \sqrt{\tfrac{T}{2}\ln N}.
\]
\end{theorem}

n20844.content:
\begin{definition}[Loss history]
\lean{LossHistory}
\label{LossHistory}
\leanok
$\texttt{LossHistory}\ N\ t$ is the type of length-$t$ histories of loss vectors
for $N$ experts: it is the function type $\mathrm{Fin}\,t \to \mathrm{Fin}\,N \to \mathbb{R}$,
recording all loss vectors that have been revealed in the past $t$ rounds.
\end{definition}

n20845.content:
\begin{definition}[History to loss sequence]
\lean{LossHistory.toLossSeq}
\label{LossHistory.toLossSeq}
\leanok
\uses{LossHistory, LossSeq}
Given a history $h : \texttt{LossHistory}\ N\ t$, $\text{\texttt{LossHistory.toLossSeq}}\ h$ coerces it
to a $\texttt{LossSeq}\ N\ t$, enabling the reuse of definitions and theorems from
the pathwise Hedge formalization that are stated over finite loss sequences.
\end{definition}

n20846.content:
\begin{definition}[Learner policy]
\lean{LearnerPolicy}
\label{LearnerPolicy}
\leanok
\uses{LossHistory}
A $\texttt{LearnerPolicy}\ N$ is a deterministic online strategy for a learner
interacting with $N$ experts: it provides a weight function
$\mathrm{weights} : (t : \mathbb{N}) \to \texttt{LossHistory}\ N\ t \to \mathrm{Fin}\,N \to \mathbb{R}$
together with proofs that the weights are nonnegative and sum to one,
so that the weight vector at each round forms a valid mixed strategy.
\end{definition}

n20847.content:
\begin{definition}[Adaptive adversary]
\lean{AdaptiveAdversary}
\label{AdaptiveAdversary}
\leanok
\uses{LossHistory}
An $\texttt{AdaptiveAdversary}\ N$ is an online strategy for the adversary:
it provides a loss-selection function
$\mathrm{loss} : (t : \mathbb{N}) \to \texttt{LossHistory}\ N\ t \to (\mathrm{Fin}\,N \to \mathbb{R}) \to \mathrm{Fin}\,N \to \mathbb{R}$
that maps the current round index, the past loss history, and the learner's
current mixed strategy to a loss vector, subject to the validity condition
that every coordinate of the chosen loss vector lies in $[0, 1]$.
\end{definition}

n20848.content:
\begin{definition}[Hedge learner policy]
\lean{hedgePolicy}
\label{hedgePolicy}
\leanok
\uses{LearnerPolicy, LossHistory.toLossSeq, hedgeDist, hedgeDist_nonneg, hedgeDist_sum}
$\texttt{hedgePolicy}\ N\ \eta$ is the $\texttt{LearnerPolicy}$ that implements the
Hedge algorithm with learning rate $\eta > 0$: at each round $t$ and for each
loss history $h$, the weights are given by $\texttt{hedgeDist}\ \eta\ (\text{\texttt{LossHistory.toLossSeq}}\ h)\ t$,
the exponential-weights distribution derived from the past realized losses.
\end{definition}

n20849.content:
\begin{definition}[Episode loss at natural time]
\lean{episodeLossNat}
\label{episodeLossNat}
\leanok
\uses{AdaptiveAdversary, LearnerPolicy}
$\texttt{episodeLossNat}\ \mathrm{learner}\ \mathrm{adversary}\ t : \mathrm{Fin}\,N \to \mathbb{R}$
is the loss vector produced at round $t$ when the learner and adversary interact
adaptively: the adversary sees the prefix of losses from rounds $0, \ldots, t-1$
and the learner's mixed strategy for round $t$, then returns the loss vector for
round $t$.  The definition is well-founded because the recursion only refers to
strictly earlier rounds.
\end{definition}

n20850.content:
\begin{definition}[Episode loss sequence]
\lean{episodeLossSeq}
\label{episodeLossSeq}
\leanok
\uses{AdaptiveAdversary, LearnerPolicy, LossSeq, episodeLossNat}
$\texttt{episodeLossSeq}\ T\ \mathrm{learner}\ \mathrm{adversary} : \texttt{LossSeq}\ N\ T$
is the finite loss sequence realized over $T$ rounds by running the learner
against the adaptive adversary, obtained by restricting $\texttt{episodeLossNat}$
to the first $T$ rounds.
\end{definition}

n20851.content:
\begin{definition}[Episode]
\lean{Episode}
\label{Episode}
\leanok
\uses{AdaptiveAdversary, LearnerPolicy, LossSeq, episodeLossSeq}
An $\texttt{Episode}\ N\ T$ packages a learner policy, an adaptive adversary, and
a finite loss sequence of length $T$ for $N$ experts, together with a consistency
proof that the stored loss sequence equals the one generated by running
$\texttt{episodeLossSeq}\ T\ \mathrm{learner}\ \mathrm{adversary}$.
\end{definition}

n20852.content:
\begin{definition}[Generated episode]
\lean{Episode.generated}
\label{Episode.generated}
\leanok
\uses{AdaptiveAdversary, Episode, LearnerPolicy, episodeLossSeq}
$\texttt{Episode.generated}\ \mathrm{learner}\ \mathrm{adversary}$ is the canonical
$\texttt{Episode}\ N\ T$ constructed by taking the loss sequence to be exactly
$\texttt{episodeLossSeq}\ T\ \mathrm{learner}\ \mathrm{adversary}$; the consistency
condition is satisfied by reflexivity.
\end{definition}

n20853.content:
\begin{theorem}[Validity of generated episode loss sequence]
\lean{episodeLossSeq_valid}
\label{episodeLossSeq_valid}
\leanok
\uses{AdaptiveAdversary, LearnerPolicy, LossSeq.Valid, episodeLossNat, episodeLossSeq}

For any learner policy and adaptive adversary, the generated loss sequence
$\texttt{episodeLossSeq}\ T\ \mathrm{learner}\ \mathrm{adversary}$ is valid,
meaning every entry lies in $[0, 1]$.  Validity is inherited directly from the
adversary's range condition.
\end{theorem}

n20854.content:
\begin{theorem}[Episode losses are valid]
\lean{Episode.losses_valid}
\label{Episode.losses_valid}
\leanok
\uses{Episode, LossSeq.Valid, episodeLossSeq_valid}

For any $\texttt{Episode}\ N\ T$, the stored loss sequence $\mathrm{episode.losses}$
is valid, i.e., every loss coordinate lies in $[0, 1]$.
\end{theorem}

n20855.content:
\begin{theorem}[Hedge regret bound for adaptive episodes]
\lean{hedge_regret_bound_tight_episode}
\label{hedge_regret_bound_tight_episode}
\leanok
\uses{AdaptiveAdversary, episodeLossSeq, episodeLossSeq_valid, hedgePolicy, hedge_regret_bound_tight, regret}

For any $N, T \ge 1$, learning rate $\eta > 0$, and adaptive adversary,
the regret of the Hedge policy with rate $\eta$ on the generated episode
satisfies
\[
  \mathrm{regret}(\eta,\; \texttt{episodeLossSeq}\ T\ (\texttt{hedgePolicy}\ N\ \eta)\ \mathrm{adversary})
  \;\le\; \frac{\ln N}{\eta} + \frac{\eta T}{8}.
\]
\end{theorem}

n20856.content:
\begin{theorem}[Hedge regret bound from a packaged episode]
\lean{hedge_regret_bound_tight_of_episode}
\label{hedge_regret_bound_tight_of_episode}
\leanok
\uses{Episode, hedgePolicy, hedge_regret_bound_tight_episode, regret}

Let $\mathrm{episode}$ be an $\texttt{Episode}\ N\ T$ whose learner equals
$\texttt{hedgePolicy}\ N\ \eta$ for some $\eta > 0$.  Then
\[
  \mathrm{regret}(\eta,\; \mathrm{episode.losses}) \;\le\; \frac{\ln N}{\eta} + \frac{\eta T}{8}.
\]
\end{theorem}

n20858.content:
\begin{theorem}[Convexity bound for the exponential]
\lean{exp_convexity_bound'}
\label{exp_convexity_bound'}
\leanok

For any $\eta, x \in \mathbb{R}$ with $x \in [0,1]$, convexity of $\exp$ gives
\[
  e^{-\eta x} \;\le\; 1 - x + x\,e^{-\eta}.
\]
\end{theorem}

n20859.content:
\begin{theorem}[Weighted exponential sum vs.\ affine upper bound]
\lean{weighted_exp_le_affine}
\label{weighted_exp_le_affine}
\leanok
\uses{exp_convexity_bound'}

Let $p : \mathrm{Fin}\,n \to \mathbb{R}$ be a probability vector ($p_i \ge 0$,
$\sum_i p_i = 1$) and let $\ell : \mathrm{Fin}\,n \to \mathbb{R}$ satisfy $0 \le \ell_i \le 1$
for all $i$.  For any $\eta \in \mathbb{R}$,
\[
  \sum_{i} p_i \,e^{-\eta\,\ell_i}
  \;\le\;
  1 - \bigl(1 - e^{-\eta}\bigr)\!\sum_{i} p_i\,\ell_i.
\]
\end{theorem}

n20862.content:
\begin{theorem}[Weak Hoeffding log-MGF bound]
\lean{hoeffding_log_mgf_weak}
\label{hoeffding_log_mgf_weak}
\leanok
\uses{eta_exp_bound}

Let $p$ be a probability vector on $\mathrm{Fin}\,n$ and let $\ell_i \in [0,1]$ for all
$i$.  For $\eta > 0$, setting $L = \sum_i p_i \ell_i$,
\[
  \ln\!\Bigl(\sum_{i} p_i\,e^{-\eta\,\ell_i}\Bigr)
  \;\le\;
  -\eta L + \frac{\eta^2}{2}.
\]
\end{theorem}

n20864.content:
\begin{theorem}[Tight Hoeffding log-MGF bound]
\lean{hoeffding_log_mgf_tight}
\label{hoeffding_log_mgf_tight}
\leanok
\uses{bernoulli_mgf_bound, weighted_exp_le_affine}

Under the same hypotheses as \texttt{hoeffding\_log\_mgf\_weak}, the tighter bound holds:
\[
  \ln\!\Bigl(\sum_{i} p_i\,e^{-\eta\,\ell_i}\Bigr)
  \;\le\;
  -\eta L + \frac{\eta^2}{8}.
\]
This follows by first applying \texttt{weighted\_exp\_le\_affine} and then
\texttt{bernoulli\_mgf\_bound}.
\end{theorem}

n20866.content:
\begin{lemma}[iid closure of the Bernstein MGF condition]
\lean{ProbabilityTheory.HasBernsteinMGF.sum_of_iIndepFun}
\label{ProbabilityTheory.HasBernsteinMGF.sum_of_iIndepFun}
\leanok
\uses{ProbabilityTheory.HasBernsteinMGF}

Let $\{X_i\}_{i \in s}$ be a mutually independent family of measurable
real random variables on a probability space, each satisfying
$\texttt{ProbabilityTheory.HasBernsteinMGF}\ (X_i)\ \mu\ c_i\ t_{\max}$ for
a common radius $t_{\max}$.  Then the finite sum
$\sum_{i \in s} X_i$ satisfies
$\texttt{ProbabilityTheory.HasBernsteinMGF}\ (\sum_{i\in s} X_i)\ \mu\ (\sum_{i\in s} c_i)\ t_{\max}$.
\end{lemma}

n20867.content:
\begin{lemma}[Upper-tail Bernstein bound]
\lean{ProbabilityTheory.HasBernsteinMGF.measure_ge_le}
\label{ProbabilityTheory.HasBernsteinMGF.measure_ge_le}
\leanok
\uses{ProbabilityTheory.HasBernsteinMGF}

Let $X$ satisfy $\texttt{ProbabilityTheory.HasBernsteinMGF}\ X\ \mu\ c\ t_{\max}$
with $c > 0$.  For every $s$ with $0 \le s \le 2c\,t_{\max}$,
\[
  \mu\bigl(\{\omega \mid s \le X(\omega)\}\bigr) \;\le\;
  \exp\!\Bigl(-\tfrac{s^2}{4c}\Bigr).
\]
The condition $s \le 2c\,t_{\max}$ ensures that the Chernoff-optimal
parameter $t = s/(2c)$ lies in the validity region $|t| \le t_{\max}$.
\end{lemma}

n20868.content:
\begin{lemma}[Lower-tail Bernstein bound]
\lean{ProbabilityTheory.HasBernsteinMGF.measure_le_le}
\label{ProbabilityTheory.HasBernsteinMGF.measure_le_le}
\leanok
\uses{ProbabilityTheory.HasBernsteinMGF}

Let $X$ satisfy $\texttt{ProbabilityTheory.HasBernsteinMGF}\ X\ \mu\ c\ t_{\max}$
with $c > 0$.  For every $s$ with $0 \le s \le 2c\,t_{\max}$,
\[
  \mu\bigl(\{\omega \mid X(\omega) \le -s\}\bigr) \;\le\;
  \exp\!\Bigl(-\tfrac{s^2}{4c}\Bigr).
\]
This is the symmetric lower-tail analogue of
$\texttt{ProbabilityTheory.HasBernsteinMGF.measure\_ge\_le}$,
obtained by applying the upper-tail bound to $-X$.
\end{lemma}

n20869.content:
\begin{lemma}[Two-sided Bernstein bound]
\lean{ProbabilityTheory.HasBernsteinMGF.measure_abs_gt_le}
\label{ProbabilityTheory.HasBernsteinMGF.measure_abs_gt_le}
\leanok
\uses{ProbabilityTheory.HasBernsteinMGF, ProbabilityTheory.HasBernsteinMGF.measure_ge_le, ProbabilityTheory.HasBernsteinMGF.measure_le_le}

Let $X$ satisfy $\texttt{ProbabilityTheory.HasBernsteinMGF}\ X\ \mu\ c\ t_{\max}$
with $c > 0$.  For every $s$ with $0 \le s \le 2c\,t_{\max}$,
\[
  \mu\bigl(\{\omega \mid s < |X(\omega)|\}\bigr) \;\le\;
  2\exp\!\Bigl(-\tfrac{s^2}{4c}\Bigr).
\]
The bound follows by combining the upper- and lower-tail bounds via a
union bound.
\end{lemma}

n20870.content:
\begin{lemma}[Centered squared iid Bernstein tail bound]
\lean{ProbabilityTheory.centered_squared_iid_tail}
\label{ProbabilityTheory.centered_squared_iid_tail}
\leanok
\uses{ProbabilityTheory.HasBernsteinMGF, ProbabilityTheory.HasBernsteinMGF.measure_abs_gt_le, ProbabilityTheory.HasBernsteinMGF.sum_of_iIndepFun}

Let $\{Y_i\}_{i \in \iota}$ be a mutually independent, identically
distributed family of measurable real random variables on a probability
space $(\Omega, \mu)$, where $|\iota| = n$.  Suppose that for each $i$
the centered square $Y_i^2 - \sigma^2$ satisfies
$\texttt{ProbabilityTheory.HasBernsteinMGF}\ (Y_i^2 - \sigma^2)\ \mu\ c\ t_{\max}$
with $c > 0$.  Then for every $s$ with
$0 \le s \le 2n c\, t_{\max}$,
\[
  \mu\!\left(\left\{\omega \;\middle|\;
    s < \left|\sum_{i} Y_i(\omega)^2 - n\sigma^2\right|\right\}\right)
  \;\le\;
  2\exp\!\Bigl(-\tfrac{s^2}{4nc}\Bigr).
\]
\end{lemma}

n20873.content:
\begin{lemma}[Scalar multiple of a centered Gaussian]
\lean{map_const_mul_gaussian}
\label{map_const_mul_gaussian}
\leanok

Let $X : \Omega \to \mathbb{R}$ be measurable with $X_*\mu = N(0,\sigma_0)$.
Then for any constant $c\in\mathbb{R}$,
\[
  (c\,X)_*\mu \;=\; N\!\bigl(0,\,c^2\cdot\sigma_0\bigr).
\]
This is an auxiliary restatement of \texttt{gaussianReal\_map\_const\_mul}
phrased for easy application in the inductive step of
\texttt{sum\_scaled\_iid\_gaussian\_map}.
\end{lemma}

n20878.content:
\begin{lemma}[Derivative of Taylor auxiliary function]
\lean{taylorAux_hasDerivAt}
\label{taylorAux_hasDerivAt}
\leanok

The function $h(u) = u^2 + u + \log(1-u)$ has derivative
$h'(u) = u(1-2u)/(1-u)$ at every $u < 1$.
This derivative identity is the key ingredient in the monotonicity argument
used to bound the centered chi-squared log-MGF.
\end{lemma}

n20879.content:
\begin{lemma}[Taylor auxiliary function vanishes at zero]
\lean{taylorAux_zero}
\label{taylorAux_zero}
\leanok

The evaluation $0^2 + 0 + \log(1-0) = 0$ establishes the base case for the
Taylor bound, confirming that $h(0)=0$ in the derivative argument for
\texttt{neg\_log\_one\_sub\_two\_mul\_le\_two\_sq}.
\end{lemma}

n20882.content:
\begin{lemma}[Quadratic MGF of a general centered Gaussian]
\lean{integral_exp_mul_sq_gaussianReal_zero}
\label{integral_exp_mul_sq_gaussianReal_zero}
\leanok
\uses{integral_exp_mul_sq_standardGaussian}

For $Y\sim N(0,v)$ with $v\ne 0$ and $2tv < 1$,
\[
  \int y.\, e^{t y^2}\,\mathrm{d}(N(0,v))
  \;=\; \frac{1}{\sqrt{1-2tv}}.
\]
This generalizes \texttt{integral\_exp\_mul\_sq\_standardGaussian} from unit
variance to an arbitrary non-zero NNReal variance $v$.
\end{lemma}

n20883.content:
\begin{lemma}[Integrability of $e^{ty^2}$ under $N(0,v)$]
\lean{integrable_exp_mul_sq_gaussianReal_zero}
\label{integrable_exp_mul_sq_gaussianReal_zero}
\leanok

For $v\ne 0$ and $2tv < 1$, the function $y\mapsto e^{t y^2}$ is integrable
with respect to $N(0,v)$.  This integrability statement accompanies
\texttt{integral\_exp\_mul\_sq\_gaussianReal\_zero} and is a prerequisite for
the Fubini and interchange-of-expectation arguments in
\texttt{centered\_chi\_squared\_step}.
\end{lemma}

n20885.content:
\begin{theorem}[Bernstein MGF instance for centered chi-squared]
\lean{hasBernsteinMGF_centered_chi_squared}
\label{hasBernsteinMGF_centered_chi_squared}
\leanok
\uses{ProbabilityTheory.HasBernsteinMGF, centered_chi_squared_step}

Under the same hypotheses as \texttt{centered\_chi\_squared\_step}, the
centered summand $Y^2 - 1/k$ satisfies
$\text{\texttt{ProbabilityTheory.HasBernsteinMGF}}\bigl(2/k^2,\;k/4\bigr)$ under $\mu$.
This packages the chi-squared MGF bound into the abstract Bernstein form, so
that the i.i.d.-sum tail-bound machinery of \texttt{bernstein.lean} can be
applied uniformly to Gaussian and other sub-Gaussian matrix families.
\end{theorem}

n20886.content:
\begin{lemma}[Chi-squared tail bound for i.i.d.\ $N(0,1/k)$ variables]
\lean{chi_squared_tail}
\label{chi_squared_tail}
\leanok
\uses{ProbabilityTheory.HasBernsteinMGF, ProbabilityTheory.HasBernsteinMGF.measure_abs_gt_le, ProbabilityTheory.HasBernsteinMGF.sum_of_iIndepFun, hasBernsteinMGF_centered_chi_squared}

Let $Y_1,\dots,Y_k:\Omega\to\mathbb{R}$ be i.i.d.\ with law $N(0,1/k)$ under
a probability measure $\mu$, and let $0<\varepsilon<1$.  Then
\[
  \mu\!\left\{\omega \;\middle|\; \varepsilon
    < \Bigl|\textstyle\sum_{i=1}^k Y_i(\omega)^2 - 1\Bigr|\right\}
  \;\le\; 2\exp\!\Bigl(-\frac{k\,\varepsilon^2}{8}\Bigr).
\]
The proof applies the Bernstein tail bound to the i.i.d.\ sum of centered
chi-squared summands, using \texttt{hasBernsteinMGF\_centered\_chi\_squared} and
the generic sum and tail-bound lemmas from the Bernstein framework.
\end{lemma}

n20889.content:
\begin{definition}[Single-pair distortion bound]
\lean{JLDistortion}
\label{JLDistortion}
\leanok
For $\varepsilon \in \mathbb{R}$, vectors $u, v \in \mathbb{R}^d$, and their
images $u', v' \in \mathbb{R}^k$, \texttt{JLDistortion} asserts the two-sided
squared-distance inequality
\[
  (1 - \varepsilon)\,\|u - v\|^2 \;\le\; \|u' - v'\|^2 \;\le\;
  (1 + \varepsilon)\,\|u - v\|^2.
\]
\end{definition}

n20890.content:
\begin{definition}[$\varepsilon$-JL embedding]
\lean{IsJLEmbedding}
\label{IsJLEmbedding}
\leanok
\uses{JLDistortion}
A linear map $f : \mathbb{R}^d \to_L[\mathbb{R}] \mathbb{R}^k$ is an
\emph{$\varepsilon$-JL embedding} of a finite set $V$ if, for every ordered
pair $(u, v) \in V \times V$, the pair $(f(u), f(v))$ satisfies
\texttt{JLDistortion} $\varepsilon\; u\; v$.
\end{definition}

n20891.content:
\begin{definition}[Bad-pair event]
\lean{BadPair}
\label{BadPair}
\leanok
\uses{JLDistortion}
Given a $k \times d$ matrix $A$ and a finite set
$V \subseteq \mathbb{R}^d$, \texttt{BadPair} $\varepsilon\; V\; A$ holds when
there exists some ordered pair $(u, v) \in V \times V$ whose images under $A$
fail the distortion predicate, i.e.\ the projection distorts that pair by
more than a factor of $\varepsilon$.
\end{definition}

n20892.content:
\begin{theorem}[JL concentration --- single vector]
\lean{jl_concentration_single}
\label{jl_concentration_single}
\leanok
\uses{BadSingle, jl_concentration_single_via_chi_squared}

Let $A$ be a random $k \times d$ matrix whose entries are i.i.d.\
$\mathcal{N}(0, 1/k)$ (rows mutually independent, entries independent within
each row).  For any fixed $x \in \mathbb{R}^d$ and any $0 < \varepsilon < 1$,
\[
  \Pr\bigl[\text{BadSingle}\;\varepsilon\;A\;x\bigr] \;\le\;
  2\,\exp\!\bigl(-k\varepsilon^2/8\bigr).
\]
\end{theorem}

n20893.content:
\begin{lemma}[Distortion from non-bad single]
\lean{JLDistortion.of_not_bad}
\label{JLDistortion.of_not_bad}
\leanok
\uses{BadSingle, JLDistortion}

If the matrix $A$ does \emph{not} trigger the bad-single event for the
difference $u - v$, then \texttt{JLDistortion} $\varepsilon\; u\; v\;
(A.toEuclideanLin\; u)\; (A.toEuclideanLin\; v)$ holds; that is, the
squared-distance of the images is within a factor of $(1 \pm \varepsilon)$
of the squared-distance of the originals.
\end{lemma}

n20894.content:
\begin{theorem}[JL union bound]
\lean{jl_union_bound}
\label{jl_union_bound}
\leanok
\uses{BadPair, BadSingle, JLDistortion.of_not_bad}

Suppose each per-pair bad event satisfies
$\Pr[\text{BadSingle}\;\varepsilon\;A\;\cdot] \le 2\exp(-k\varepsilon^2/8)$.
Then the probability that \emph{some} ordered pair in $V \times V$ is
distorted is at most
\[
  |V|^2 \cdot 2\,\exp\!\bigl(-k\varepsilon^2/8\bigr).
\]
\end{theorem}

n20895.content:
\begin{theorem}[Structural JL --- Gaussian probabilistic method]
\lean{johnson_lindenstrauss_of_gaussian}
\label{johnson_lindenstrauss_of_gaussian}
\leanok
\uses{BadPair, BadSingle, IsJLEmbedding, jl_concentration_single, jl_union_bound}

Let $A$ be a random Gaussian $k \times d$ matrix as above.  If the union-bound
failure probability satisfies
$|V|^2 \cdot 2\exp(-k\varepsilon^2/8) < 1$,
then there exists a linear map $f : \mathbb{R}^d \to_L \mathbb{R}^k$ that is an
$\varepsilon$-JL embedding of $V$, extracted from the positive-measure good
event.
\end{theorem}

n20896.content:
\begin{theorem}[Structural JL --- sub-Gaussian probabilistic method]
\lean{johnson_lindenstrauss_of_subgaussian}
\label{johnson_lindenstrauss_of_subgaussian}
\leanok
\uses{BadPair, BadSingle, IsJLEmbedding, concentration_zero, jl_concentration_single_subgaussian, jl_union_bound}

Sub-Gaussian analogue of \texttt{johnson\_lindenstrauss\_of\_gaussian}: the Gaussian
entry hypotheses are replaced by the assumptions that each row projection
$(Ax)_i$ is sub-Gaussian with parameter $\|x\|^2/k$ and has variance exactly
$\|x\|^2/k$.  Under the same failure-probability bound
$|V|^2 \cdot 2\exp(-k\varepsilon^2/8) < 1$, an $\varepsilon$-JL embedding of
$V$ is guaranteed to exist; this covers, for instance, Rademacher ($\pm 1/\sqrt{k}$)
matrices.
\end{theorem}

n20897.content:
\begin{lemma}[Measurability of bad-single event]
\lean{measurableSet_badSingle}
\label{measurableSet_badSingle}
\leanok
\uses{BadSingle}

For any measurable map $A : \Omega \to \mathrm{Matrix}(\mathrm{Fin}\,k,
\mathrm{Fin}\,d,\mathbb{R})$, fixed $x \in \mathbb{R}^d$, and $\varepsilon \in
\mathbb{R}$, the set $\{\omega \mid \text{BadSingle}\;\varepsilon\;(A\,\omega)\;x\}$
is measurable.  The key step is that each coordinate map
$\omega \mapsto (A\,\omega \cdot \text{toEuclideanLin}\; x)_i$ is measurable, hence
so is the squared norm.
\end{lemma}

n20898.content:
\begin{lemma}[Existence of i.i.d.\ Gaussian matrix]
\lean{exists_iid_gaussian_matrix}
\label{exists_iid_gaussian_matrix}
\leanok

For any $k > 0$ and $d \ge 0$, there exists a probability space
$(\Omega, \mathcal{F}, \mu)$ carrying a measurable random matrix
$A : \Omega \to \mathrm{Matrix}(\mathrm{Fin}\,k, \mathrm{Fin}\,d, \mathbb{R})$
whose entries are i.i.d.\ $\mathcal{N}(0, 1/k)$, with rows mutually independent
and entries within each row jointly independent.
\end{lemma}

n20899.content:
\begin{lemma}[Numerical failure-probability bound]
\lean{jl_failure_bound_of_dim}
\label{jl_failure_bound_of_dim}
\leanok

Given $0 < \varepsilon$, $n \ge 2$, $k \ge 32 \log n / \varepsilon^2$, and
$|V| \le n$, this lemma derives (i) $k > 0$ and (ii)
$|V|^2 \cdot 2\exp(-k\varepsilon^2/8) < 1$, the numerical precondition
consumed by both \texttt{johnson\_lindenstrauss\_of\_gaussian} and
\texttt{johnson\_lindenstrauss\_of\_subgaussian}.
\end{lemma}

n20900.content:
\begin{theorem}[Johnson--Lindenstrauss flattening lemma (Gaussian)]
\lean{johnson_lindenstrauss}
\label{johnson_lindenstrauss}
\leanok
\uses{BadSingle, IsJLEmbedding, exists_iid_gaussian_matrix, jl_failure_bound_of_dim, johnson_lindenstrauss_of_gaussian, measurableSet_badSingle}

For any $0 < \varepsilon < 1$, $n \ge 2$, $k \ge 32 \log n / \varepsilon^2$,
and any finite set $V \subseteq \mathbb{R}^d$ of at most $n$ points, there
exists a linear map $f : \mathbb{R}^d \to_L \mathbb{R}^k$ that is an
$\varepsilon$-JL embedding of $V$, i.e.\ it satisfies
$(1 - \varepsilon)\|u-v\|^2 \le \|f(u)-f(v)\|^2 \le (1+\varepsilon)\|u-v\|^2$
for all $u, v \in V$.
\end{theorem}

n20901.content:
\begin{theorem}[Johnson--Lindenstrauss flattening lemma (sub-Gaussian)]
\lean{johnson_lindenstrauss_subgaussian}
\label{johnson_lindenstrauss_subgaussian}
\leanok
\uses{BadSingle, IsJLEmbedding, hasSubgaussianMGF_row_proj, integral_sq_row_proj, jl_failure_bound_of_dim, johnson_lindenstrauss_of_subgaussian, measurableSet_badSingle, measurable_radMatrix, radJointMeasure, radMatrix, radMatrix_proj_indep, radMatrix_proj_meas}

Rademacher ($\pm 1/\sqrt{k}$ entries) analogue of \texttt{johnson\_lindenstrauss}:
same hypotheses on $\varepsilon$, $n$, $k$, and $V$, same conclusion---an
$\varepsilon$-JL embedding of $V$ exists---but now realized by a Rademacher
matrix.  The proof uses the sub-Gaussian concentration bound
\texttt{jl\_concentration\_single\_subgaussian} (which inherits the Hanson-Wright
axiom) and the identical union-bound argument.
\end{theorem}

n20902.content:
\begin{lemma}[Distance form of embedding]
\lean{jl_dist_of_embedding}
\label{jl_dist_of_embedding}
\leanok
\uses{IsJLEmbedding, JLDistortion}

If $f$ is an $\varepsilon$-JL embedding of $V$ (in the squared-distance sense),
then for all $u, v \in V$,
\[
  \sqrt{1-\varepsilon}\,\|u - v\| \;\le\; \|f(u) - f(v)\| \;\le\;
  \sqrt{1+\varepsilon}\,\|u - v\|,
\]
obtained by taking square roots of the \texttt{JLDistortion} bounds.
\end{lemma}

n20903.content:
\begin{theorem}[JL flattening --- distance form (Gaussian)]
\lean{johnson_lindenstrauss_dist}
\label{johnson_lindenstrauss_dist}
\leanok
\uses{jl_dist_of_embedding, johnson_lindenstrauss}

Under the same hypotheses as \texttt{johnson\_lindenstrauss}, there exists a linear
map $f : \mathbb{R}^d \to_L \mathbb{R}^k$ such that for all $u, v \in V$,
\[
  \sqrt{1-\varepsilon}\,\|u - v\| \;\le\; \|f(u) - f(v)\| \;\le\;
  \sqrt{1+\varepsilon}\,\|u - v\|.
\]
\end{theorem}

n20904.content:
\begin{theorem}[JL flattening --- distance form (sub-Gaussian)]
\lean{johnson_lindenstrauss_subgaussian_dist}
\label{johnson_lindenstrauss_subgaussian_dist}
\leanok
\uses{jl_dist_of_embedding, johnson_lindenstrauss_subgaussian}

Under the same hypotheses as \texttt{johnson\_lindenstrauss\_subgaussian}, there
exists a linear map $f : \mathbb{R}^d \to_L \mathbb{R}^k$ satisfying the same
two-sided distance-ratio bounds as \texttt{johnson\_lindenstrauss\_dist}, now
realized by a Rademacher random matrix.
\end{theorem}

n20905.content:
\begin{theorem}[Logarithmic dimension bound (Gaussian)]
\lean{johnson_lindenstrauss_dim_bound}
\label{johnson_lindenstrauss_dim_bound}
\leanok
\uses{IsJLEmbedding, johnson_lindenstrauss}

For any $0 < \varepsilon < 1$ and $n \ge 2$, there exists a threshold
$k_0 \in \mathbb{N}$ such that for every $k \ge k_0$, every ambient
dimension $d$, and every set $V \subseteq \mathbb{R}^d$ of at most $n$ points,
an $\varepsilon$-JL embedding $f : \mathbb{R}^d \to_L \mathbb{R}^k$ of $V$
exists.  In particular the target dimension is $O(\log n / \varepsilon^2)$.
\end{theorem}

n20906.content:
\begin{theorem}[Logarithmic dimension bound (sub-Gaussian)]
\lean{johnson_lindenstrauss_subgaussian_dim_bound}
\label{johnson_lindenstrauss_subgaussian_dim_bound}
\leanok
\uses{IsJLEmbedding, johnson_lindenstrauss_subgaussian}

Sub-Gaussian (Rademacher) analogue of \texttt{johnson\_lindenstrauss\_dim\_bound}:
same threshold $k_0 = O(\log n / \varepsilon^2)$, same universal conclusion for
all $k \ge k_0$, $d$, and $V$ of size at most $n$, but inheriting the
Hanson-Wright axiom from the sub-Gaussian concentration chain.
\end{theorem}

n20908.content:
\begin{definition}[Rademacher distribution on $\mathbb{R}$]
\lean{rademacherReal}
\label{rademacherReal}
\leanok
The Rademacher distribution $\mathrm{Rad}$ on $\mathbb{R}$ is the measure
$\tfrac{1}{2}\delta_{-1} + \tfrac{1}{2}\delta_{+1}$, placing equal mass $1/2$
at $-1$ and at $+1$.
\end{definition}

n20909.content:
\begin{lemma}[$1/2$ is finite as an extended non-negative real]
\lean{rad_half_ne_top}
\label{rad_half_ne_top}
\leanok

The value $1/2$, viewed as an element of $\mathbb{R}_{\geq 0}^\infty$, is not
equal to $\top$.
\end{lemma}

n20910.content:
\begin{lemma}[{Rademacher support in $[-1,1]$}]
\lean{rademacherReal_mem_Icc}
\label{rademacherReal_mem_Icc}
\leanok
\uses{rademacherReal}

Almost every sample from the Rademacher distribution lies in the interval
$[-1, 1]$: $\mathrm{Rad}$-a.e.\ $y \in [-1, 1]$.
\end{lemma}

n20911.content:
\begin{lemma}[Integrability under a scaled Dirac measure]
\lean{integrable_smul_dirac}
\label{integrable_smul_dirac}
\leanok
\uses{rad_half_ne_top}

For any $a \in \mathbb{R}$ and any measurable function $f : \mathbb{R} \to
\mathbb{R}$, the function $f$ is integrable with respect to the measure
$\tfrac{1}{2}\,\delta_a$.
\end{lemma}

n20912.content:
\begin{lemma}[Every function is integrable under the Rademacher measure]
\lean{integrable_rademacherReal}
\label{integrable_rademacherReal}
\leanok
\uses{integrable_smul_dirac, rademacherReal}

For any $f : \mathbb{R} \to \mathbb{R}$, the function $f$ is integrable with
respect to the Rademacher measure $\mathrm{Rad}$.
\end{lemma}

n20913.content:
\begin{lemma}[Mean of the Rademacher distribution is zero]
\lean{integral_id_rademacherReal}
\label{integral_id_rademacherReal}
\leanok
\uses{integrable_smul_dirac, rademacherReal}

The expected value of the identity under the Rademacher distribution is zero:
$\int y \, d\mathrm{Rad}(y) = 0$.
\end{lemma}

n20914.content:
\begin{lemma}[Second moment of the Rademacher distribution is one]
\lean{integral_sq_rademacherReal}
\label{integral_sq_rademacherReal}
\leanok
\uses{integrable_smul_dirac, rademacherReal}

The second moment of the Rademacher distribution equals one:
$\int y^2 \, d\mathrm{Rad}(y) = 1$.
\end{lemma}

n20915.content:
\begin{lemma}[Identity is sub-Gaussian with parameter $1$ under $\mathrm{Rad}$]
\lean{hasSubgaussianMGF_id_rademacherReal}
\label{hasSubgaussianMGF_id_rademacherReal}
\leanok
\uses{integral_id_rademacherReal, rademacherReal, rademacherReal_mem_Icc}

The identity function $\mathrm{id} : \mathbb{R} \to \mathbb{R}$ satisfies
$\mathrm{HasSubgaussianMGF}(\mathrm{id}, 1, \mathrm{Rad})$, i.e.\ its MGF is
bounded by $e^{t^2/2}$ for all $t \in \mathbb{R}$.  This follows from
Hoeffding's lemma applied to the centred random variable supported in $[-1, 1]$,
whose sub-Gaussian parameter is $\bigl((1-(-1))/2\bigr)^2 = 1$.
\end{lemma}

n20916.content:
\begin{definition}[Rademacher matrix sample space]
\lean{RadΩ}
\label{RadΩ}
\leanok
The sample space for the Rademacher matrix is $\mathrm{Fin}\,k \to
\mathrm{Fin}\,d \to \mathbb{R}$, i.e.\ the type of $k \times d$ arrays of
real numbers, indexed by $(i,j) \in \mathrm{Fin}\,k \times \mathrm{Fin}\,d$.
\end{definition}

n20917.content:
\begin{definition}[Joint Rademacher product measure]
\lean{radJointMeasure}
\label{radJointMeasure}
\leanok
\uses{RadΩ, rademacherReal}
The joint measure on $\mathrm{Rad\Omega}(k,d)$ is the product measure
$\bigotimes_{(i,j)} \mathrm{Rad}$, making all $k \cdot d$ entries i.i.d.\
Rademacher.
\end{definition}

n20918.content:
\begin{definition}[Rademacher matrix]
\lean{radMatrix}
\label{radMatrix}
\leanok
\uses{RadΩ}
The Rademacher matrix $A : \mathrm{Rad\Omega}(k,d) \to \mathbb{R}^{k\times d}$
maps a sample $\omega$ to the matrix with entries
$A(\omega)_{ij} = \omega_{ij}/\sqrt{k}$, scaling the raw $\pm 1$ entries by
$1/\sqrt{k}$.
\end{definition}

n20919.content:
\begin{lemma}[Measurability of the Rademacher matrix]
\lean{measurable_radMatrix}
\label{measurable_radMatrix}
\leanok
\uses{radMatrix}

The map $\omega \mapsto \mathrm{radMatrix}(k,d,\omega)$ is measurable with
respect to the product $\sigma$-algebra on $\mathrm{Rad\Omega}(k,d)$.
\end{lemma}

n20920.content:
\begin{lemma}[Row marginal of the joint measure]
\lean{radJointMeasure_row_marginal}
\label{radJointMeasure_row_marginal}
\leanok
\uses{RadΩ, radJointMeasure, rademacherReal}

The pushforward of the joint measure along the $i$-th row projection
$\omega \mapsto \omega_i$ equals the product measure
$\bigotimes_{j \in \mathrm{Fin}\,d} \mathrm{Rad}$.
\end{lemma}

n20921.content:
\begin{lemma}[Entry marginal of the joint measure]
\lean{radJointMeasure_entry_marginal}
\label{radJointMeasure_entry_marginal}
\leanok
\uses{RadΩ, radJointMeasure, radJointMeasure_row_marginal, rademacherReal}

The pushforward of the joint measure along the $(i,j)$-entry projection
$\omega \mapsto \omega_{ij}$ equals $\mathrm{Rad}$.
\end{lemma}

n20922.content:
\begin{lemma}[Within-row entries are i.i.d.\ Rademacher]
\lean{radJointMeasure_row_iid}
\label{radJointMeasure_row_iid}
\leanok
\uses{RadΩ, radJointMeasure, radJointMeasure_entry_marginal, radJointMeasure_row_marginal, rademacherReal}

For each fixed row $i \in \mathrm{Fin}\,k$, the $d$ functions
$j \mapsto \omega_{ij}$ are mutually independent under the joint measure.
\end{lemma}

n20923.content:
\begin{lemma}[Rows are mutually independent]
\lean{radJointMeasure_rows_iid}
\label{radJointMeasure_rows_iid}
\leanok
\uses{RadΩ, radJointMeasure}

The $k$ row vectors $i \mapsto (\omega_{ij})_{j}$, viewed as
$\mathrm{Fin}\,d \to \mathbb{R}$-valued random variables, are mutually
independent under the joint measure.
\end{lemma}

n20924.content:
\begin{lemma}[Each entry is sub-Gaussian with parameter $1$]
\lean{hasSubgaussianMGF_entry}
\label{hasSubgaussianMGF_entry}
\leanok
\uses{RadΩ, hasSubgaussianMGF_id_rademacherReal, radJointMeasure, radJointMeasure_entry_marginal, rademacherReal}

For each $(i,j) \in \mathrm{Fin}\,k \times \mathrm{Fin}\,d$, the function
$\omega \mapsto \omega_{ij}$ satisfies
$\mathrm{HasSubgaussianMGF}(\cdot, 1, \mathrm{radJointMeasure})$ under the
joint product measure.
\end{lemma}

n20925.content:
\begin{lemma}[Scaled entry is sub-Gaussian with parameter $x_j^2/k$]
\lean{hasSubgaussianMGF_scaled_entry}
\label{hasSubgaussianMGF_scaled_entry}
\leanok
\uses{RadΩ, integral_id_rademacherReal, radJointMeasure, radJointMeasure_entry_marginal, rademacherReal, rademacherReal_mem_Icc}

For $k > 0$, $x \in \mathbb{R}^d$, and indices $i,j$, the function
$\omega \mapsto (x_j / \sqrt{k})\,\omega_{ij}$ satisfies
$\mathrm{HasSubgaussianMGF}(\cdot, x_j^2/k, \mathrm{radJointMeasure})$.
\end{lemma}

n20926.content:
\begin{lemma}[Row projection is sub-Gaussian with parameter $\lVert x\rVert^2/k$]
\lean{hasSubgaussianMGF_row_proj}
\label{hasSubgaussianMGF_row_proj}
\leanok
\uses{RadΩ, hasSubgaussianMGF_scaled_entry, radJointMeasure, radJointMeasure_row_iid, radMatrix}

For $k > 0$, $x \in \mathbb{R}^d$, and $i \in \mathrm{Fin}\,k$, the $i$-th row
projection $\omega \mapsto (A(\omega)\,x)_i = (1/\sqrt{k})\sum_j \omega_{ij} x_j$
satisfies $\mathrm{HasSubgaussianMGF}(\cdot, \lVert x\rVert^2/k,
\mathrm{radJointMeasure})$.  This follows by combining per-summand Hoeffding
bounds with independence of the within-row entries.
\end{lemma}

n20927.content:
\begin{lemma}[Variance of $\mathrm{id}$ under $\mathrm{Rad}$ is $1$]
\lean{variance_id_rademacherReal}
\label{variance_id_rademacherReal}
\leanok
\uses{integral_id_rademacherReal, integral_sq_rademacherReal, rademacherReal, rademacherReal_mem_Icc}

The variance of the identity function under the Rademacher distribution is $1$:
$\mathrm{Var}[\mathrm{id}; \mathrm{Rad}] = 1$.
\end{lemma}

n20928.content:
\begin{lemma}[Variance of a single entry is $1$]
\lean{variance_entry}
\label{variance_entry}
\leanok
\uses{RadΩ, radJointMeasure, radJointMeasure_entry_marginal, variance_id_rademacherReal}

For any $(i,j)$, the variance of the entry $\omega \mapsto \omega_{ij}$ under
the joint measure is $1$:
$\mathrm{Var}[\omega \mapsto \omega_{ij}; \mathrm{radJointMeasure}] = 1$.
\end{lemma}

n20929.content:
\begin{lemma}[Mean of a single entry is $0$]
\lean{integral_entry}
\label{integral_entry}
\leanok
\uses{RadΩ, integral_id_rademacherReal, radJointMeasure, radJointMeasure_entry_marginal, rademacherReal}

For any $(i,j)$, the expected value of $\omega_{ij}$ under the joint measure is
$0$: $\int \omega_{ij} \, d\mathrm{radJointMeasure} = 0$.
\end{lemma}

n20930.content:
\begin{lemma}[Scaled entry belongs to $L^2$]
\lean{memLp_scaled_entry}
\label{memLp_scaled_entry}
\leanok
\uses{RadΩ, radJointMeasure, radJointMeasure_entry_marginal, rademacherReal_mem_Icc}

For $k > 0$, $x \in \mathbb{R}^d$, and indices $i,j$, the function
$\omega \mapsto (x_j/\sqrt{k})\,\omega_{ij}$ belongs to $L^2(\mathrm{radJointMeasure})$.
\end{lemma}

n20931.content:
\begin{lemma}[Variance of a scaled entry is $x_j^2/k$]
\lean{variance_scaled_entry}
\label{variance_scaled_entry}
\leanok
\uses{RadΩ, radJointMeasure, variance_entry}

For $k > 0$, $x \in \mathbb{R}^d$, and indices $i,j$,
$\mathrm{Var}[\omega \mapsto (x_j/\sqrt{k})\,\omega_{ij}; \mathrm{radJointMeasure}]
= x_j^2/k$.
\end{lemma}

n20932.content:
\begin{lemma}[Variance of the row projection is $\lVert x\rVert^2/k$]
\lean{variance_row_proj}
\label{variance_row_proj}
\leanok
\uses{RadΩ, memLp_scaled_entry, radJointMeasure, radJointMeasure_row_iid, radMatrix, variance_scaled_entry}

For $k > 0$, $x \in \mathbb{R}^d$, and $i \in \mathrm{Fin}\,k$,
\[
  \mathrm{Var}\!\bigl[\omega \mapsto (A(\omega)\,x)_i;\,\mathrm{radJointMeasure}\bigr]
  = \frac{\lVert x\rVert^2}{k}.
\]
This follows from per-summand variance $x_j^2/k$ together with
within-row independence.
\end{lemma}

n20933.content:
\begin{lemma}[Mean of the row projection is $0$]
\lean{integral_row_proj}
\label{integral_row_proj}
\leanok
\uses{RadΩ, integral_entry, memLp_scaled_entry, radJointMeasure, radMatrix}

For $k > 0$, $x \in \mathbb{R}^d$, and $i \in \mathrm{Fin}\,k$,
$\int (A(\omega)\,x)_i \, d\mathrm{radJointMeasure} = 0$.
\end{lemma}

n20934.content:
\begin{lemma}[Second moment of the row projection equals $\lVert x\rVert^2/k$]
\lean{integral_sq_row_proj}
\label{integral_sq_row_proj}
\leanok
\uses{RadΩ, hasSubgaussianMGF_row_proj, integral_row_proj, memLp_scaled_entry, radJointMeasure, radMatrix, variance_row_proj}

For $k > 0$, $x \in \mathbb{R}^d$, and $i \in \mathrm{Fin}\,k$,
\[
  \int \bigl((A(\omega)\,x)_i\bigr)^2 \, d\mathrm{radJointMeasure}
  = \frac{\lVert x\rVert^2}{k}.
\]
This follows from $\int Y^2 = \mathrm{Var}[Y] + (\int Y)^2 = \lVert x\rVert^2/k + 0$.
\end{lemma}

n20935.content:
\begin{lemma}[Row projections are mutually independent]
\lean{radMatrix_proj_indep}
\label{radMatrix_proj_indep}
\leanok
\uses{RadΩ, radJointMeasure, radJointMeasure_rows_iid, radMatrix}

For any $x \in \mathbb{R}^d$, the $k$ row projections
$i \mapsto (A(\omega)\,x)_i$ are mutually independent random variables under
the joint Rademacher measure.
\end{lemma}

n20936.content:
\begin{lemma}[Row projections are measurable]
\lean{radMatrix_proj_meas}
\label{radMatrix_proj_meas}
\leanok
\uses{RadΩ, radMatrix}

For any $x \in \mathbb{R}^d$ and $i \in \mathrm{Fin}\,k$, the map
$\omega \mapsto (A(\omega)\,x)_i$ is measurable.
\end{lemma}

n20938.content:
\begin{definition}[Two-player finite game]
\lean{Game}
\label{Game}
\leanok
A finite two-player game with $M$ row actions and $N$ column actions, specified
by a row utility function $u_r : \mathrm{Fin}\,M \times \mathrm{Fin}\,N \to \mathbb{R}$
and a column utility function $u_c : \mathrm{Fin}\,M \times \mathrm{Fin}\,N \to \mathbb{R}$.
Both players are utility maximizers.
\end{definition}

n20939.content:
\begin{definition}[Embedding a zero-sum game]
\lean{ZeroSumGame.toGame}
\label{ZeroSumGame.toGame}
\leanok
\uses{Game, ZeroSumGame}
Given a zero-sum game $G$ with payoff matrix $A$, this embeds it into the
general two-player framework by setting the row utility to $A$ and the column
utility to $-A$, so that both players are maximizers of their respective
utilities.
\end{definition}

n20940.content:
\begin{definition}[Joint distribution over action profiles]
\lean{JointDistribution}
\label{JointDistribution}
\leanok
A joint distribution $\sigma$ on $\mathrm{Fin}\,M \times \mathrm{Fin}\,N$ is a
nonnegative function $\sigma_{ij} \ge 0$ satisfying
$\sum_{i,j} \sigma_{ij} = 1$.  It represents a correlated distribution over
pure action profiles of the two players.
\end{definition}

n20941.content:
\begin{definition}[Row marginal]
\lean{JointDistribution.rowMarginal}
\label{JointDistribution.rowMarginal}
\leanok
\uses{JointDistribution}
The row marginal of $\sigma$ at row action $i$ is
$\sigma^{\mathrm{row}}_i = \sum_{j} \sigma_{ij}$,
i.e.\ the probability that the row player plays $i$ under $\sigma$.
\end{definition}

n20942.content:
\begin{definition}[Column marginal]
\lean{JointDistribution.colMarginal}
\label{JointDistribution.colMarginal}
\leanok
\uses{JointDistribution}
The column marginal of $\sigma$ at column action $j$ is
$\sigma^{\mathrm{col}}_j = \sum_{i} \sigma_{ij}$,
i.e.\ the probability that the column player plays $j$ under $\sigma$.
\end{definition}

n20943.content:
\begin{lemma}[Row marginals are nonnegative]
\lean{JointDistribution.rowMarginal_nonneg}
\label{JointDistribution.rowMarginal_nonneg}
\leanok
\uses{JointDistribution, JointDistribution.rowMarginal}

For any joint distribution $\sigma$ and row action $i$,
$\sigma^{\mathrm{row}}_i \ge 0$.
\end{lemma}

n20944.content:
\begin{lemma}[Column marginals are nonnegative]
\lean{JointDistribution.colMarginal_nonneg}
\label{JointDistribution.colMarginal_nonneg}
\leanok
\uses{JointDistribution, JointDistribution.colMarginal}

For any joint distribution $\sigma$ and column action $j$,
$\sigma^{\mathrm{col}}_j \ge 0$.
\end{lemma}

n20945.content:
\begin{lemma}[Row marginals sum to one]
\lean{JointDistribution.rowMarginal_sum_one}
\label{JointDistribution.rowMarginal_sum_one}
\leanok
\uses{JointDistribution, JointDistribution.rowMarginal}

The row marginals form a valid probability distribution:
$\sum_{i} \sigma^{\mathrm{row}}_i = 1$.
\end{lemma}

n20946.content:
\begin{lemma}[Column marginals sum to one]
\lean{JointDistribution.colMarginal_sum_one}
\label{JointDistribution.colMarginal_sum_one}
\leanok
\uses{JointDistribution, JointDistribution.colMarginal}

The column marginals form a valid probability distribution:
$\sum_{j} \sigma^{\mathrm{col}}_j = 1$.
\end{lemma}

n20947.content:
\begin{definition}[Row expected utility]
\lean{JointDistribution.rowExpectedUtility}
\label{JointDistribution.rowExpectedUtility}
\leanok
\uses{Game, JointDistribution}
The row player's expected utility under $\sigma$ in game $G$ is
$\sum_{i,j} \sigma_{ij} \cdot u_r(i,j)$.
\end{definition}

n20948.content:
\begin{definition}[Column expected utility]
\lean{JointDistribution.colExpectedUtility}
\label{JointDistribution.colExpectedUtility}
\leanok
\uses{Game, JointDistribution}
The column player's expected utility under $\sigma$ in game $G$ is
$\sum_{i,j} \sigma_{ij} \cdot u_c(i,j)$.
\end{definition}

n20949.content:
\begin{definition}[Row deviation utility]
\lean{JointDistribution.rowDeviationUtility}
\label{JointDistribution.rowDeviationUtility}
\leanok
\uses{Game, JointDistribution, JointDistribution.colMarginal}
The row player's expected utility from unilaterally deviating to the fixed
pure action $i'$, while the column player keeps $\sigma$'s column marginal:
$\sum_{j} \sigma^{\mathrm{col}}_j \cdot u_r(i', j)$.
\end{definition}

n20950.content:
\begin{definition}[Column deviation utility]
\lean{JointDistribution.colDeviationUtility}
\label{JointDistribution.colDeviationUtility}
\leanok
\uses{Game, JointDistribution, JointDistribution.rowMarginal}
The column player's expected utility from unilaterally deviating to the fixed
pure action $j'$, while the row player keeps $\sigma$'s row marginal:
$\sum_{i} \sigma^{\mathrm{row}}_i \cdot u_c(i, j')$.
\end{definition}

n20951.content:
\begin{definition}[Coarse correlated equilibrium]
\lean{IsCoarseCorrelatedEquilibrium}
\label{IsCoarseCorrelatedEquilibrium}
\leanok
\uses{Game, JointDistribution, JointDistribution.rowDeviationUtility, JointDistribution.rowExpectedUtility, JointDistribution.colDeviationUtility, JointDistribution.colExpectedUtility}
A joint distribution $\sigma$ is a \emph{coarse correlated equilibrium} (CCE)
of game $G$ if neither player can improve their expected utility by committing
in advance to any fixed pure action: for all $i'$,
$\mathrm{rowDevUtil}(\sigma, G, i') \le \mathrm{rowExpUtil}(\sigma, G)$, and
for all $j'$, $\mathrm{colDevUtil}(\sigma, G, j') \le \mathrm{colExpUtil}(\sigma, G)$.
\end{definition}

n20952.content:
\begin{definition}[$\varepsilon$-coarse correlated equilibrium]
\lean{IsApproxCoarseCorrelatedEquilibrium}
\label{IsApproxCoarseCorrelatedEquilibrium}
\leanok
\uses{Game, JointDistribution, JointDistribution.rowDeviationUtility, JointDistribution.rowExpectedUtility, JointDistribution.colDeviationUtility, JointDistribution.colExpectedUtility}
A joint distribution $\sigma$ is an \emph{$\varepsilon$-coarse correlated
equilibrium} ($\varepsilon$-CCE) of game $G$ if each player's gain from any
unilateral pure deviation is at most $\varepsilon$: for all $i'$,
$\mathrm{rowDevUtil}(\sigma, G, i') \le \mathrm{rowExpUtil}(\sigma, G) + \varepsilon$,
and similarly for the column player.
\end{definition}

n20953.content:
\begin{lemma}[Exact CCE implies approximate CCE]
\lean{IsCoarseCorrelatedEquilibrium.toApprox}
\label{IsCoarseCorrelatedEquilibrium.toApprox}
\leanok
\uses{Game, IsCoarseCorrelatedEquilibrium, IsApproxCoarseCorrelatedEquilibrium, JointDistribution, productDistribution}

If $\sigma$ is an exact CCE of $G$ and $\varepsilon \ge 0$, then $\sigma$ is
also an $\varepsilon$-CCE of $G$.
\end{lemma}

n20954.content:
\begin{definition}[Product distribution]
\lean{productDistribution}
\label{productDistribution}
\leanok
\uses{JointDistribution, MixedStrategy}
Given mixed strategies $p$ for the row player and $q$ for the column player,
the product (independent) joint distribution assigns to each profile $(i,j)$
the probability $p_i \cdot q_j$.
\end{definition}

n20955.content:
\begin{lemma}[Product distribution row marginal]
\lean{productDistribution_rowMarginal}
\label{productDistribution_rowMarginal}
\leanok
\uses{JointDistribution.rowMarginal, MixedStrategy, productDistribution}

For the product distribution of $p$ and $q$, the row marginal at $i$ equals
$p_i$ (the original row mixed-strategy weight).
\end{lemma}

n20956.content:
\begin{lemma}[Product distribution column marginal]
\lean{productDistribution_colMarginal}
\label{productDistribution_colMarginal}
\leanok
\uses{JointDistribution.colMarginal, MixedStrategy, productDistribution}

For the product distribution of $p$ and $q$, the column marginal at $j$ equals
$q_j$ (the original column mixed-strategy weight).
\end{lemma}

n20957.content:
\begin{definition}[Empirical joint distribution]
\lean{empiricalJoint}
\label{empiricalJoint}
\leanok
\uses{JointDistribution, MixedStrategy}
Given $T > 0$ rounds of play in which the row player uses mixed strategy $p_t$
and the column player uses $q_t$, the empirical joint distribution assigns to
each profile $(i,j)$ the time-averaged probability
$\frac{1}{T}\sum_{t=1}^{T} (p_t)_i \cdot (q_t)_j$.
\end{definition}

n20958.content:
\begin{lemma}[Empirical joint row marginal]
\lean{empiricalJoint_rowMarginal}
\label{empiricalJoint_rowMarginal}
\leanok
\uses{JointDistribution.rowMarginal, MixedStrategy, empiricalJoint}

The row marginal of the empirical joint distribution at action $i$ equals the
time-average of the row player's mixed-strategy weights:
$(1/T)\sum_{t} (p_t)_i$.
\end{lemma}

n20959.content:
\begin{lemma}[Empirical joint column marginal]
\lean{empiricalJoint_colMarginal}
\label{empiricalJoint_colMarginal}
\leanok
\uses{JointDistribution.colMarginal, MixedStrategy, empiricalJoint}

The column marginal of the empirical joint distribution at action $j$ equals
the time-average of the column player's mixed-strategy weights:
$(1/T)\sum_{t} (q_t)_j$.
\end{lemma}

n20960.content:
\begin{lemma}[Empirical utility sum factorization]
\lean{empiricalJoint_sum_prob_mul}
\label{empiricalJoint_sum_prob_mul}
\leanok
\uses{MixedStrategy, empiricalJoint}

For any function $f : \mathrm{Fin}\,M \to \mathrm{Fin}\,N \to \mathbb{R}$,
the sum $\sum_{i,j} \sigma_{ij} \cdot f(i,j)$ over the empirical joint
distribution equals the time-average
$(1/T)\sum_{t}\sum_{i,j}(p_t)_i(q_t)_j f(i,j)$.
\end{lemma}

n20961.content:
\begin{lemma}[Empirical row expected utility]
\lean{empiricalJoint_rowExpectedUtility}
\label{empiricalJoint_rowExpectedUtility}
\leanok
\uses{Game, JointDistribution.rowExpectedUtility, MixedStrategy, empiricalJoint, empiricalJoint_sum_prob_mul}

The row player's expected utility under the empirical joint distribution equals
the time-average of the per-round bilinear utilities:
\[
  \mathrm{rowExpUtil}(\sigma^{\mathrm{emp}}, G) =
  \frac{1}{T}\sum_{t}\sum_{i,j}(p_t)_i\,(q_t)_j\,u_r(i,j).
\]
\end{lemma}

n20962.content:
\begin{lemma}[Empirical column expected utility]
\lean{empiricalJoint_colExpectedUtility}
\label{empiricalJoint_colExpectedUtility}
\leanok
\uses{Game, JointDistribution.colExpectedUtility, MixedStrategy, empiricalJoint, empiricalJoint_sum_prob_mul}

The column player's expected utility under the empirical joint distribution
equals the time-average of the per-round bilinear column utilities:
\[
  \mathrm{colExpUtil}(\sigma^{\mathrm{emp}}, G) =
  \frac{1}{T}\sum_{t}\sum_{i,j}(p_t)_i\,(q_t)_j\,u_c(i,j).
\]
\end{lemma}

n20963.content:
\begin{lemma}[Empirical row deviation utility]
\lean{empiricalJoint_rowDeviationUtility}
\label{empiricalJoint_rowDeviationUtility}
\leanok
\uses{Game, JointDistribution.rowDeviationUtility, MixedStrategy, empiricalJoint, empiricalJoint_colMarginal}

The row player's deviation utility for pure action $i'$ in the empirical
distribution equals the time-average utility of always playing $i'$:
\[
  \mathrm{rowDevUtil}(\sigma^{\mathrm{emp}}, G, i') =
  \frac{1}{T}\sum_{t}\sum_{j}(q_t)_j\,u_r(i',j).
\]
\end{lemma}

n20964.content:
\begin{lemma}[Empirical column deviation utility]
\lean{empiricalJoint_colDeviationUtility}
\label{empiricalJoint_colDeviationUtility}
\leanok
\uses{Game, JointDistribution.colDeviationUtility, MixedStrategy, empiricalJoint, empiricalJoint_rowMarginal}

The column player's deviation utility for pure action $j'$ in the empirical
distribution equals the time-average utility of always playing $j'$:
\[
  \mathrm{colDevUtil}(\sigma^{\mathrm{emp}}, G, j') =
  \frac{1}{T}\sum_{t}\sum_{i}(p_t)_i\,u_c(i,j').
\]
\end{lemma}

n20966.content:
\begin{definition}[Arbitrary mixed strategy]
\lean{OnlineLearning.arbitraryMixedStrategy}
\label{OnlineLearning.arbitraryMixedStrategy}
\leanok
\uses{MixedStrategy}
Given $n \geq 1$, \texttt{OnlineLearning.arbitraryMixedStrategy} is a concrete
element of $\mathrm{MixedStrategy}(n)$ that places all probability mass on a
single arbitrarily chosen action. It is used solely to witness that the type
of mixed strategies is nonempty.
\end{definition}

n20967.content:
\begin{definition}[Lower value of a finite game]
\lean{OnlineLearning.finiteLowerValue}
\label{OnlineLearning.finiteLowerValue}
\leanok
\uses{MixedStrategy, ZeroSumGame, payoffVsPure}
For a finite zero-sum game $G$ with $M$ row actions and $N$ column actions,
the \emph{lower value} is
\[
  v^- (G) \;=\; \sup_{p \in \Delta_M}\; \inf_{j \in [N]}\; \mathrm{payoffVsPure}(G,p,j),
\]
where the row player maximises over mixed strategies and the column player
minimises over pure responses.
\end{definition}

n20968.content:
\begin{definition}[Upper value of a finite game]
\lean{OnlineLearning.finiteUpperValue}
\label{OnlineLearning.finiteUpperValue}
\leanok
\uses{MixedStrategy, ZeroSumGame, pureVsPayoff}
The \emph{upper value} of $G$ is
\[
  v^+(G) \;=\; \inf_{q \in \Delta_N}\; \sup_{i \in [M]}\; \mathrm{pureVsPayoff}(G,i,q),
\]
where the column player minimises over mixed strategies and the row player
maximises over pure responses.
\end{definition}

n20969.content:
\begin{lemma}[Payoff vs.\ pure column is nonnegative]
\lean{OnlineLearning.payoffVsPure_nonneg}
\label{OnlineLearning.payoffVsPure_nonneg}
\leanok
\uses{MixedStrategy, ZeroSumGame, payoffVsPure}

For any game $G$, mixed row strategy $p$, and pure column action $j$,
$\mathrm{payoffVsPure}(G,p,j) \geq 0$. This follows because every entry
of $G$ is nonnegative and the mixing weights are nonnegative.
\end{lemma}

n20970.content:
\begin{lemma}[Payoff vs.\ pure column is at most one]
\lean{OnlineLearning.payoffVsPure_le_one}
\label{OnlineLearning.payoffVsPure_le_one}
\leanok
\uses{MixedStrategy, ZeroSumGame, payoffVsPure}

For any game $G$, mixed row strategy $p$, and pure column action $j$,
$\mathrm{payoffVsPure}(G,p,j) \leq 1$. This follows because every entry
of $G$ is at most one and the mixing weights sum to one.
\end{lemma}

n20971.content:
\begin{lemma}[Pure row payoff vs.\ mixed column is nonnegative]
\lean{OnlineLearning.pureVsPayoff_nonneg}
\label{OnlineLearning.pureVsPayoff_nonneg}
\leanok
\uses{MixedStrategy, ZeroSumGame, pureVsPayoff}

For any game $G$, pure row action $i$, and mixed column strategy $q$,
$\mathrm{pureVsPayoff}(G,i,q) \geq 0$.
\end{lemma}

n20972.content:
\begin{lemma}[Pure row payoff vs.\ mixed column is at most one]
\lean{OnlineLearning.pureVsPayoff_le_one}
\label{OnlineLearning.pureVsPayoff_le_one}
\leanok
\uses{MixedStrategy, ZeroSumGame, pureVsPayoff}

For any game $G$, pure row action $i$, and mixed column strategy $q$,
$\mathrm{pureVsPayoff}(G,i,q) \leq 1$.
\end{lemma}

n20973.content:
\begin{lemma}[Row-guaranteed payoffs bounded above]
\lean{OnlineLearning.finiteLowerValue_bddAbove}
\label{OnlineLearning.finiteLowerValue_bddAbove}
\leanok
\uses{MixedStrategy, OnlineLearning.payoffVsPure_le_one, OnlineLearning.payoffVsPure_nonneg, ZeroSumGame, payoffVsPure}

When $N \geq 1$, the set
$\bigl\{\inf_{j}\,\mathrm{payoffVsPure}(G,p,j) : p \in \Delta_M\bigr\}$
is bounded above by~$1$.
\end{lemma}

n20974.content:
\begin{lemma}[Column-induced upper values bounded below]
\lean{OnlineLearning.finiteUpperValue_bddBelow}
\label{OnlineLearning.finiteUpperValue_bddBelow}
\leanok
\uses{MixedStrategy, OnlineLearning.pureVsPayoff_le_one, OnlineLearning.pureVsPayoff_nonneg, ZeroSumGame, pureVsPayoff}

When $M \geq 1$, the set
$\bigl\{\sup_{i}\,\mathrm{pureVsPayoff}(G,i,q) : q \in \Delta_N\bigr\}$
is bounded below by~$0$.
\end{lemma}

n20975.content:
\begin{lemma}[Weak duality for finite games]
\lean{OnlineLearning.finiteLowerValue_le_upperValue}
\label{OnlineLearning.finiteLowerValue_le_upperValue}
\leanok
\uses{OnlineLearning.finiteLowerValue, OnlineLearning.finiteUpperValue, ZeroSumGame, weak_duality}

For any finite zero-sum game $G$ (with $M,N \geq 1$),
$v^-(G) \leq v^+(G)$.
\end{lemma}

n20976.content:
\begin{theorem}[Exact finite minimax value]
\lean{OnlineLearning.finite_minimax_value}
\label{OnlineLearning.finite_minimax_value}
\leanok
\uses{OnlineLearning.finiteLowerValue, OnlineLearning.finiteLowerValue_bddAbove, OnlineLearning.finiteLowerValue_le_upperValue, OnlineLearning.finiteUpperValue, OnlineLearning.finiteUpperValue_bddBelow, OnlineLearning.pureVsPayoff_le_one, ZeroSumGame, approx_minimax, payoffVsPure, pureVsPayoff}

For a finite zero-sum game $G$ with $M > 1$ rows and $N \geq 1$ columns,
the lower and upper values coincide:
\[
  v^-(G) \;=\; v^+(G).
\]
The proof extracts arbitrarily good approximate saddle points from the Hedge
algorithm, then passes to the limit in~$\varepsilon$.
\end{theorem}

n20978.content:
\begin{definition}[Convex-compact minimax hypotheses]
\lean{OnlineLearning.ConvexCompactMinimaxHypotheses}
\label{OnlineLearning.ConvexCompactMinimaxHypotheses}
\leanok
A structure bundling the assumptions of Cesa-Bianchi--Lugosi Theorem~7.1
for $f : \mathbb{R}\to \mathbb{R}\to \mathbb{R}$ on sets $X, Y \subseteq \mathbb{R}$: both sets
are nonempty, $X$ is compact and convex, $Y$ is convex, $f(\cdot,y)$ is
continuous and convex on $X$ for every $y \in Y$, $f(x,\cdot)$ is concave on
$Y$ for every $x \in X$, and $f$ is bounded above and below on $X \times Y$.
\end{definition}

n20979.content:
\begin{lemma}[Mixed-strategy convex combination stays in convex set]
\lean{OnlineLearning.mixed_sum_mem_convex}
\label{OnlineLearning.mixed_sum_mem_convex}
\leanok
\uses{MixedStrategy}

If $S \subseteq \mathbb{R}$ is convex, $p \in \Delta_n$ is a mixed strategy, and
$x_1,\dots,x_n \in S$, then
$\sum_{i} p_i\, x_i \in S$.
\end{lemma}

n20980.content:
\begin{lemma}[Jensen's inequality for mixed-strategy combinations (convex)]
\lean{OnlineLearning.convexOn_mixed_sum_le}
\label{OnlineLearning.convexOn_mixed_sum_le}
\leanok
\uses{MixedStrategy}

If $g$ is convex on $S \subseteq \mathbb{R}$, $p \in \Delta_n$, and every $x_i \in S$,
then
\[
  g\!\left(\sum_{i} p_i\, x_i\right)
  \;\leq\;
  \sum_{i} p_i\, g(x_i).
\]
\end{lemma}

n20981.content:
\begin{lemma}[Jensen's inequality for mixed-strategy combinations (concave)]
\lean{OnlineLearning.concaveOn_le_mixed_sum}
\label{OnlineLearning.concaveOn_le_mixed_sum}
\leanok
\uses{MixedStrategy}

If $g$ is concave on $S \subseteq \mathbb{R}$, $p \in \Delta_n$, and every $y_j \in S$,
then
\[
  \sum_{j} p_j\, g(y_j)
  \;\leq\;
  g\!\left(\sum_{j} p_j\, y_j\right).
\]
\end{lemma}

n20982.content:
\begin{definition}[Sampled finite game]
\lean{OnlineLearning.sampledGame}
\label{OnlineLearning.sampledGame}
\leanok
\uses{ZeroSumGame}
Given a payoff function $f : \mathbb{R}\to \mathbb{R}\to \mathbb{R}$ with values in $[0,1]$,
finite families of row points $x : [M] \to \mathbb{R}$ and column points
$y : [N] \to \mathbb{R}$, the \emph{sampled game} is the $M\times N$ matrix game
whose $(i,j)$ entry is $f(x_i, y_j)$.
\end{definition}

n20983.content:
\begin{theorem}[Finite minimax for sampled games]
\lean{OnlineLearning.finite_sampled_minimax_value}
\label{OnlineLearning.finite_sampled_minimax_value}
\leanok
\uses{OnlineLearning.finiteLowerValue, OnlineLearning.finiteUpperValue, OnlineLearning.finite_minimax_value, OnlineLearning.sampledGame}

Under the same size hypotheses as \texttt{OnlineLearning.finite\_minimax\_value},
the sampled game satisfies $v^-(\mathrm{sampledGame}) = v^+(\mathrm{sampledGame})$.
\end{theorem}

n20984.content:
\begin{lemma}[Convexity gives lower bound on sampled payoff vs.\ pure column]
\lean{OnlineLearning.sampled_payoffVsPure_ge_convex_combo}
\label{OnlineLearning.sampled_payoffVsPure_ge_convex_combo}
\leanok
\uses{MixedStrategy, OnlineLearning.convexOn_mixed_sum_le, OnlineLearning.sampledGame, payoffVsPure}

If $f(\cdot, y_j)$ is convex on $X$ and every $x_i \in X$, then for any mixed
row strategy $p \in \Delta_M$,
\[
  f\!\left(\sum_i p_i\,x_i,\; y_j\right)
  \;\leq\;
  \mathrm{payoffVsPure}(\mathrm{sampledGame},\,p,\,j).
\]
That is, convexity in the row variable means the continuous mixed-action payoff
is at most the finite-game expected payoff.
\end{lemma}

n20985.content:
\begin{lemma}[Concavity gives upper bound on sampled payoff vs.\ mixed column]
\lean{OnlineLearning.sampled_pureVsPayoff_le_concave_combo}
\label{OnlineLearning.sampled_pureVsPayoff_le_concave_combo}
\leanok
\uses{MixedStrategy, OnlineLearning.concaveOn_le_mixed_sum, OnlineLearning.sampledGame, pureVsPayoff}

If $f(x_i,\cdot)$ is concave on $Y$ and every $y_j \in Y$, then for any mixed
column strategy $q \in \Delta_N$,
\[
  \mathrm{pureVsPayoff}(\mathrm{sampledGame},\,i,\,q)
  \;\leq\;
  f\!\left(x_i,\; \sum_j q_j\,y_j\right).
\]
\end{lemma}

n20986.content:
\begin{lemma}[Weak minimax inequality for convex-compact games]
\lean{OnlineLearning.weak_convex_compact_minimax}
\label{OnlineLearning.weak_convex_compact_minimax}
\leanok
\uses{OnlineLearning.ConvexCompactMinimaxHypotheses}

Under the hypotheses \texttt{OnlineLearning.ConvexCompactMinimaxHypotheses},
\[
  \sup_{y \in Y}\,\inf_{x \in X}\,f(x,y)
  \;\leq\;
  \inf_{x \in X}\,\sup_{y \in Y}\,f(x,y).
\]
This is the easy direction of the minimax theorem: for every fixed $(x,y)$,
$\inf_{x'} f(x',y) \leq f(x,y) \leq \sup_{y'} f(x,y')$, and the inequality
is preserved when taking $\sup$ then $\inf$.
\end{lemma}

n20987.content:
\begin{definition}[Minimax sublevel set]
\lean{OnlineLearning.minimaxSublevel}
\label{OnlineLearning.minimaxSublevel}
\leanok
For a set $X \subseteq \mathbb{R}$, a payoff function $f$, a column point $y$, and
a threshold $c \in \mathbb{R}$, the \emph{minimax sublevel set} is
\[
  \mathrm{sublevel}(X,f,y,c) \;=\; X \cap \{x \in \mathbb{R}: f(x,y) \leq c\}.
\]
\end{definition}

n20988.content:
\begin{lemma}[Sublevel set contained in row set]
\lean{OnlineLearning.minimaxSublevel_subset}
\label{OnlineLearning.minimaxSublevel_subset}
\leanok
\uses{OnlineLearning.minimaxSublevel}

$\mathrm{sublevel}(X,f,y,c) \subseteq X$ for all $f$, $y$, $c$.
\end{lemma}

n20989.content:
\begin{lemma}[Sublevel set is closed]
\lean{OnlineLearning.minimaxSublevel_isClosed}
\label{OnlineLearning.minimaxSublevel_isClosed}
\leanok
\uses{OnlineLearning.minimaxSublevel}

If $X$ is closed and $f(\cdot,y)$ is continuous on $X$, then
$\mathrm{sublevel}(X,f,y,c)$ is closed.
\end{lemma}

n20990.content:
\begin{lemma}[Sublevel set is compact]
\lean{OnlineLearning.minimaxSublevel_isCompact}
\label{OnlineLearning.minimaxSublevel_isCompact}
\leanok
\uses{OnlineLearning.minimaxSublevel, OnlineLearning.minimaxSublevel_isClosed, OnlineLearning.minimaxSublevel_subset}

If $X$ is compact and $f(\cdot,y)$ is continuous on $X$, then
$\mathrm{sublevel}(X,f,y,c)$ is compact (as a closed subset of a compact set).
\end{lemma}

n20991.content:
\begin{lemma}[Finite-intersection gives global row minimiser]
\lean{OnlineLearning.exists_forall_le_of_finite_sublevel_intersections}
\label{OnlineLearning.exists_forall_le_of_finite_sublevel_intersections}
\leanok
\uses{OnlineLearning.ConvexCompactMinimaxHypotheses, OnlineLearning.minimaxSublevel, OnlineLearning.minimaxSublevel_isClosed}

Under \texttt{OnlineLearning.ConvexCompactMinimaxHypotheses}, let $c \in \mathbb{R}$.
If for every finite subset $u \subseteq Y$ there exists $x \in X$ with
$f(x,y) \leq c$ for all $y \in u$, then there exists $x \in X$ with
$f(x,y) \leq c$ for \emph{all} $y \in Y$. The proof applies the
finite-intersection property to the compact collection of sublevel sets.
\end{lemma}

n20993.content:
\begin{definition}[Finite no-regret bound predicate]
\lean{OnlineLearning.Theorem71FiniteNoRegretBound}
\label{OnlineLearning.Theorem71FiniteNoRegretBound}
\leanok
\uses{OnlineLearning.finiteRowSampleLowerValue}
$\texttt{OnlineLearning.Theorem71FiniteNoRegretBound}$ is the proposition asserting that
for every nonempty finite row sample $u \subseteq X$,
\[
  \inf_{x \in X} \sup_{y \in Y} f(x,y)
    \;\le\;
  \sup_{y \in Y} \inf_{x \in u} f(x, y).
\]
This is the finite-game no-regret ingredient in the Theorem~7.1 proof route.
\end{definition}

n20994.content:
\begin{definition}[Compact approximation predicate]
\lean{OnlineLearning.Theorem71CompactApproximation}
\label{OnlineLearning.Theorem71CompactApproximation}
\leanok
\uses{OnlineLearning.finiteRowSampleLowerValue}
$\texttt{OnlineLearning.Theorem71CompactApproximation}$ is the proposition asserting that
for every $\varepsilon > 0$ there exists a nonempty finite sample $u \subseteq X$ such
that
\[
  \sup_{y \in Y} \inf_{x \in u} f(x, y)
    \;\le\;
  \sup_{y \in Y} \inf_{x \in X} f(x, y) + \varepsilon.
\]
This encodes the ``let the net size go to zero'' compactness step of the textbook proof.
\end{definition}

n20998.content:
\begin{theorem}[Compact approximation from uniform equicontinuity]
\lean{OnlineLearning.theorem71_compactApproximation_of_uniformEquicontinuity}
\label{OnlineLearning.theorem71_compactApproximation_of_uniformEquicontinuity}
\leanok
\uses{OnlineLearning.ConvexCompactMinimaxHypotheses, OnlineLearning.Theorem71CompactApproximation, OnlineLearning.Theorem71UniformEquicontinuity, OnlineLearning.finiteRowSampleLowerValue}

Under the convex-compact minimax hypotheses, if $f$ satisfies
$\texttt{OnlineLearning.Theorem71UniformEquicontinuity}$, then
$\texttt{OnlineLearning.Theorem71CompactApproximation}$ holds: a finite cover of the
compact set $X$ together with equicontinuity shows that the finite sample lower value
approximates the full lower value to within any $\varepsilon > 0$.
\end{theorem}

n20999.content:
\begin{theorem}[Uniform equicontinuity from joint continuity on compact $X \times Y$]
\lean{OnlineLearning.theorem71_uniformEquicontinuity_of_jointContinuous_compact}
\label{OnlineLearning.theorem71_uniformEquicontinuity_of_jointContinuous_compact}
\leanok
\uses{OnlineLearning.ConvexCompactMinimaxHypotheses, OnlineLearning.Theorem71UniformEquicontinuity}

If the convex-compact minimax hypotheses hold, $Y$ is compact, and
$(x,y) \mapsto f(x,y)$ is continuous on $X \times Y$, then
$\texttt{OnlineLearning.Theorem71UniformEquicontinuity}$ holds.  The proof applies the
Heine--Cantor theorem to upgrade joint continuity on the compact product $X \times Y$ to
uniform continuity, then restricts variation to the first coordinate.
\end{theorem}

n21000.content:
\begin{theorem}[Compact approximation from joint continuity on compact $X \times Y$]
\lean{OnlineLearning.theorem71_compactApproximation_of_jointContinuous_compact}
\label{OnlineLearning.theorem71_compactApproximation_of_jointContinuous_compact}
\leanok
\uses{OnlineLearning.ConvexCompactMinimaxHypotheses, OnlineLearning.Theorem71CompactApproximation, OnlineLearning.theorem71_compactApproximation_of_uniformEquicontinuity, OnlineLearning.theorem71_uniformEquicontinuity_of_jointContinuous_compact}

Under the convex-compact minimax hypotheses, if $Y$ is compact and $f$ is jointly
continuous on $X \times Y$, then $\texttt{OnlineLearning.Theorem71CompactApproximation}$
holds.  This is obtained by combining
$\texttt{OnlineLearning.theorem71\_uniformEquicontinuity\_of\_jointContinuous\_compact}$ with
$\texttt{OnlineLearning.theorem71\_compactApproximation\_of\_uniformEquicontinuity}$.
\end{theorem}

n21001.content:
\begin{theorem}[Finite indexed no-regret bound (normalized)]
\lean{OnlineLearning.theorem71_finiteIndexedNoRegretBound_normalized}
\label{OnlineLearning.theorem71_finiteIndexedNoRegretBound_normalized}
\leanok
\uses{OnlineLearning.ConvexCompactMinimaxHypotheses, OnlineLearning.exists_forall_le_of_finite_sublevel_intersections, OnlineLearning.finiteIndexedRowSampleLowerValue, OnlineLearning.finiteLowerValue, OnlineLearning.finiteUpperValue, OnlineLearning.finite_minimax_value, OnlineLearning.minimaxSublevel, OnlineLearning.payoffVsPure_nonneg, OnlineLearning.pureVsPayoff_le_one, ZeroSumGame, payoffVsPure, pureVsPayoff}

Under the convex-compact minimax hypotheses and the normalization $0 \le f \le 1$, for
any row sample $x : \mathrm{Fin}\,M \to X$ with $M \ge 2$,
\[
  \inf_{x' \in X} \sup_{y \in Y} f(x', y)
    \;\le\;
  \sup_{y \in Y} \inf_{i \in \mathrm{Fin}\,M} f(x_i, y).
\]
The proof constructs a finite matrix game with payoff $1 - f$ on each finite column
subset, applies the finite minimax theorem (via the upstream no-regret development), and
uses compactness of $X$ to pass to all columns.
\end{theorem}

n21002.content:
\begin{theorem}[Finite no-regret bound (normalized, Finset version)]
\lean{OnlineLearning.theorem71_finiteNoRegretBound_normalized}
\label{OnlineLearning.theorem71_finiteNoRegretBound_normalized}
\leanok
\uses{OnlineLearning.ConvexCompactMinimaxHypotheses, OnlineLearning.Theorem71FiniteNoRegretBound, OnlineLearning.finiteIndexedRowSampleLowerValue, OnlineLearning.finiteRowSampleLowerValue, OnlineLearning.theorem71_finiteIndexedNoRegretBound_normalized}

Under the convex-compact minimax hypotheses and $0 \le f \le 1$,
$\texttt{OnlineLearning.Theorem71FiniteNoRegretBound}$ holds.  This removes the artificial
$\mathrm{Fin}\,M$ indexing from
$\texttt{OnlineLearning.theorem71\_finiteIndexedNoRegretBound\_normalized}$; the singleton
case is handled separately since the finite minimax theorem requires at least two row
actions.
\end{theorem}

n21004.content:
\begin{definition}[Finite zero-sum game]
\lean{ZeroSumGame}
\label{ZeroSumGame}
\leanok
A \emph{finite two-player zero-sum game} with $M$ row actions and $N$ column
actions is a record consisting of a payoff matrix $A : \mathrm{Fin}\,M \to
\mathrm{Fin}\,N \to \mathbb{R}$ together with proofs that every entry satisfies
$0 \le A_{ij} \le 1$.  The row player seeks to maximise the payoff; the column
player seeks to minimise it.
\end{definition}

n21005.content:
\begin{definition}[Mixed strategy]
\lean{MixedStrategy}
\label{MixedStrategy}
\leanok
A \emph{mixed strategy} over $n$ actions is a record consisting of a weight
function $w : \mathrm{Fin}\,n \to \mathbb{R}$ together with proofs that every
weight is non-negative and that the weights sum to $1$, i.e.\ $w$ is a
probability distribution over $\mathrm{Fin}\,n$.
\end{definition}

n21006.content:
\begin{definition}[Row mixed payoff against a pure column]
\lean{payoffVsPure}
\label{payoffVsPure}
\leanok
\uses{MixedStrategy, ZeroSumGame}
Given a game $G$, a mixed row strategy $p$, and a pure column $j$, the
\emph{expected payoff against column $j$} is
\[
  \mathrm{payoffVsPure}(G, p, j) \;=\; \sum_{i} p_i \cdot A_{ij}.
\]
\end{definition}

n21007.content:
\begin{definition}[Pure row payoff against a mixed column]
\lean{pureVsPayoff}
\label{pureVsPayoff}
\leanok
\uses{MixedStrategy, ZeroSumGame}
Given a game $G$, a pure row $i$, and a mixed column strategy $q$, the
\emph{expected payoff of row $i$ against $q$} is
\[
  \mathrm{pureVsPayoff}(G, i, q) \;=\; \sum_{j} A_{ij} \cdot q_j.
\]
\end{definition}

n21008.content:
\begin{definition}[Column best response]
\lean{bestColumn}
\label{bestColumn}
\leanok
\uses{MixedStrategy, ZeroSumGame, payoffVsPure}
Given a game $G$ and a mixed row strategy $p$, \texttt{bestColumn} is the pure
column $j^* \in \mathrm{Fin}\,N$ that minimises $\mathrm{payoffVsPure}(G, p,
\cdot)$, chosen via the classical axiom of choice from the finite minimiser.
\end{definition}

n21009.content:
\begin{lemma}[Best-column minimality]
\lean{bestColumn_spec}
\label{bestColumn_spec}
\leanok
\uses{MixedStrategy, ZeroSumGame, bestColumn, payoffVsPure}

For any game $G$, mixed row strategy $p$, and pure column $j$,
\[
  \mathrm{payoffVsPure}(G, p, \mathrm{bestColumn}(G, p))
  \;\le\;
  \mathrm{payoffVsPure}(G, p, j).
\]
That is, the chosen column is indeed a minimiser.
\end{lemma}

n21010.content:
\begin{definition}[Row best response]
\lean{bestRow}
\label{bestRow}
\leanok
\uses{MixedStrategy, ZeroSumGame, pureVsPayoff}
Given a game $G$ and a mixed column strategy $q$, \texttt{bestRow} is the pure
row $i^* \in \mathrm{Fin}\,M$ that maximises $\mathrm{pureVsPayoff}(G, \cdot,
q)$, chosen classically from the finite maximiser.
\end{definition}

n21011.content:
\begin{lemma}[Best-row maximality]
\lean{bestRow_spec}
\label{bestRow_spec}
\leanok
\uses{MixedStrategy, ZeroSumGame, bestRow, pureVsPayoff}

For any game $G$, mixed column strategy $q$, and pure row $i$,
\[
  \mathrm{pureVsPayoff}(G, i, q)
  \;\le\;
  \mathrm{pureVsPayoff}(G, \mathrm{bestRow}(G, q), q).
\]
\end{lemma}

n21012.content:
\begin{theorem}[Weak duality]
\lean{weak_duality}
\label{weak_duality}
\leanok
\uses{MixedStrategy, ZeroSumGame, ZeroSumGame.toLossSeq, payoffVsPure, pureVsPayoff}

For any game $G$ and any mixed strategies $p$ (row) and $q$ (column),
\[
  \inf_{j \in \mathrm{Fin}\,N} \mathrm{payoffVsPure}(G, p, j)
  \;\le\;
  \sup_{i \in \mathrm{Fin}\,M} \mathrm{pureVsPayoff}(G, i, q).
\]
The row player's worst-case mixed payoff never exceeds the column player's
best-case mixed payoff.
\end{theorem}

n21013.content:
\begin{definition}[Loss sequence induced by a game]
\lean{ZeroSumGame.toLossSeq}
\label{ZeroSumGame.toLossSeq}
\leanok
\uses{LossSeq, ZeroSumGame}
Given a game $G$ and a sequence of column responses $j_0, \dots, j_{T-1}$, the
induced \emph{loss sequence} for the row player is $\ell_t(i) = 1 - A_{i,j_t}
\in [0,1]$.  This translates a zero-sum game into the abstract loss-sequence
framework used by Hedge.
\end{definition}

n21014.content:
\begin{lemma}[Induced loss sequence is valid]
\lean{ZeroSumGame.toLossSeq_valid}
\label{ZeroSumGame.toLossSeq_valid}
\leanok
\uses{LossSeq.Valid, ZeroSumGame, ZeroSumGame.toLossSeq}

The loss sequence $G.\mathrm{toLossSeq}(\mathrm{colResponse})$ is valid, i.e.\
every loss lies in $[0, 1]$, because the payoffs satisfy $0 \le A_{ij} \le 1$.
\end{lemma}

n21015.content:
\begin{definition}[Average strategy]
\lean{averageStrategy}
\label{averageStrategy}
\leanok
\uses{MixedStrategy}
Given $T$ distributions $p_0, \dots, p_{T-1}$ over $\mathrm{Fin}\,n$ (each
presented as non-negative weights summing to $1$) and $T > 0$, the
\emph{average strategy} is the mixed strategy with weights
\[
  \bar{p}_i \;=\; \frac{1}{T} \sum_{t=0}^{T-1} p_t(i).
\]
\end{definition}

n21016.content:
\begin{definition}[Hedge mixed strategy]
\lean{hedgeMixedStrategy}
\label{hedgeMixedStrategy}
\leanok
\uses{LossSeq, MixedStrategy, hedgeDist, hedgeDist_nonneg, hedgeDist_sum}
The Hedge distribution at round $t$ for learning rate $\eta$ and loss sequence
$\ell$, packaged as a \texttt{MixedStrategy} by bundling the non-negativity and
sum-one proofs from \texttt{hedgeDist}.
\end{definition}

n21017.content:
\begin{definition}[Empirical strategy]
\lean{empiricalStrategy}
\label{empiricalStrategy}
\leanok
\uses{MixedStrategy}
Given $T > 0$ pure actions $a_0, \dots, a_{T-1} \in \mathrm{Fin}\,n$, the
\emph{empirical strategy} is the mixed strategy assigning to each $i$ the
fraction of rounds on which action $i$ was played:
\[
  q_i \;=\; \frac{1}{T}\#\{t : a_t = i\}.
\]
\end{definition}

n21018.content:
\begin{lemma}[Payoff under average strategy]
\lean{payoffVsPure_averageStrategy}
\label{payoffVsPure_averageStrategy}
\leanok
\uses{ZeroSumGame, averageStrategy, payoffVsPure}

For a game $G$, a column $j$, and $T$ row distributions
$p_0, \dots, p_{T-1}$,
\[
  \mathrm{payoffVsPure}(G, \bar{p}, j)
  \;=\;
  \frac{1}{T} \sum_{t=0}^{T-1} \sum_{i} p_t(i) \cdot A_{ij},
\]
where $\bar{p}$ is the average strategy.
\end{lemma}

n21019.content:
\begin{lemma}[Payoff of pure row under empirical column]
\lean{pureVsPayoff_empiricalStrategy}
\label{pureVsPayoff_empiricalStrategy}
\leanok
\uses{ZeroSumGame, empiricalStrategy, pureVsPayoff}

For a game $G$, a pure row $i$, and a sequence of pure column actions
$a_0, \dots, a_{T-1}$,
\[
  \mathrm{pureVsPayoff}(G, i, \hat{q})
  \;=\;
  \frac{1}{T} \sum_{t=0}^{T-1} A_{i, a_t},
\]
where $\hat{q}$ is the empirical column strategy.
\end{lemma}

n21020.content:
\begin{definition}[Prefix cumulative game loss]
\lean{prefixGameLoss}
\label{prefixGameLoss}
\leanok
\uses{ZeroSumGame}
Given a game $G$, a prefix of $t$ column actions, and a row $i$, the
\emph{prefix cumulative loss} of row $i$ is
\[
  L_t(i) \;=\; \sum_{s=0}^{t-1} \bigl(1 - A_{i, a_s}\bigr).
\]
This mirrors \texttt{cumLoss} from the abstract Hedge framework, expressed
directly in terms of game payoffs.
\end{definition}

n21021.content:
\begin{definition}[Prefix Hedge weight]
\lean{prefixHedgeWeight}
\label{prefixHedgeWeight}
\leanok
\uses{ZeroSumGame, prefixGameLoss}
The unnormalised Hedge weight of row $i$ after seeing a prefix of column
actions at learning rate $\eta$ is
\[
  w_t(i) \;=\; \exp\!\bigl(-\eta \cdot L_t(i)\bigr),
\]
where $L_t(i)$ is the prefix cumulative loss.
\end{definition}

n21022.content:
\begin{definition}[Prefix potential]
\lean{prefixPotential}
\label{prefixPotential}
\leanok
\uses{ZeroSumGame, prefixHedgeWeight}
The \emph{prefix potential} is the sum of prefix Hedge weights over all rows:
\[
  \Phi_t \;=\; \sum_{i \in \mathrm{Fin}\,M} w_t(i).
\]
\end{definition}

n21023.content:
\begin{lemma}[Prefix Hedge weight is positive]
\lean{prefixHedgeWeight_pos}
\label{prefixHedgeWeight_pos}
\leanok
\uses{ZeroSumGame, prefixHedgeWeight}

For any game $G$, learning rate $\eta$, prefix of column actions, and row $i$,
the prefix Hedge weight $w_t(i) = \exp(-\eta L_t(i)) > 0$.
\end{lemma}

n21024.content:
\begin{lemma}[Prefix potential is positive]
\lean{prefixPotential_pos}
\label{prefixPotential_pos}
\leanok
\uses{ZeroSumGame, prefixHedgeWeight_pos, prefixPotential}

When $M \ge 1$, the prefix potential $\Phi_t > 0$, since it is a non-empty sum
of positive terms.
\end{lemma}

n21025.content:
\begin{definition}[Prefix Hedge mixed strategy]
\lean{prefixHedgeMixedStrategy}
\label{prefixHedgeMixedStrategy}
\leanok
\uses{MixedStrategy, ZeroSumGame, prefixHedgeWeight, prefixHedgeWeight_pos, prefixPotential, prefixPotential_pos}
The normalised Hedge distribution after a prefix of $t$ column actions is the
mixed row strategy with weights
\[
  p_t(i) \;=\; \frac{w_t(i)}{\Phi_t},
\]
where $w_t(i)$ is the prefix Hedge weight and $\Phi_t$ the prefix potential.
\end{definition}

n21026.content:
\begin{definition}[Online column best responses to Hedge]
\lean{hedgeResponseNat}
\label{hedgeResponseNat}
\leanok
\uses{ZeroSumGame, bestColumn, prefixHedgeMixedStrategy}
The sequence of column best responses generated online against Hedge: at time
$t$, given the history $a_0, \dots, a_{t-1}$ of prior column choices, the
column player responds with $a_t = \mathrm{bestColumn}(G, p_t)$, where $p_t$
is the prefix Hedge mixed strategy.  This is defined by well-founded recursion
on $t$.
\end{definition}

n21027.content:
\begin{lemma}[Prefix loss equals cumulative loss]
\lean{prefixGameLoss_eq_cumLoss}
\label{prefixGameLoss_eq_cumLoss}
\leanok
\uses{ZeroSumGame, ZeroSumGame.toLossSeq, cumLoss, prefixGameLoss}

For any fixed column-action sequence $a : \mathrm{Fin}\,T \to \mathrm{Fin}\,N$,
round $t < T$, and row $i$, the prefix cumulative loss of row $i$ along the
first $t$ actions equals the abstract cumulative loss of $i$ in the induced loss
sequence: $\mathrm{prefixGameLoss}(\dots) = \mathrm{cumLoss}(G.\mathrm{toLossSeq}(a), t, i)$.
\end{lemma}

n21028.content:
\begin{lemma}[Prefix weight equals Hedge weight]
\lean{prefixHedgeWeight_eq_hedgeWeight}
\label{prefixHedgeWeight_eq_hedgeWeight}
\leanok
\uses{ZeroSumGame, ZeroSumGame.toLossSeq, hedgeWeight, prefixGameLoss_eq_cumLoss, prefixHedgeWeight}

The prefix Hedge weight of row $i$ at round $t$ equals the abstract Hedge
weight $\mathrm{hedgeWeight}(\eta, G.\mathrm{toLossSeq}(a), t, i)$ for the
induced loss sequence.
\end{lemma}

n21029.content:
\begin{lemma}[Prefix potential equals Hedge potential]
\lean{prefixPotential_eq_potential}
\label{prefixPotential_eq_potential}
\leanok
\uses{ZeroSumGame, ZeroSumGame.toLossSeq, potential, prefixHedgeWeight_eq_hedgeWeight, prefixPotential}

The prefix potential at round $t$ equals the abstract Hedge potential
$\mathrm{potential}(\eta, G.\mathrm{toLossSeq}(a), t)$ for the induced loss
sequence.
\end{lemma}

n21030.content:
\begin{lemma}[Prefix strategy weight equals Hedge distribution]
\lean{prefixHedgeMixedStrategy_weight_eq_hedgeDist}
\label{prefixHedgeMixedStrategy_weight_eq_hedgeDist}
\leanok
\uses{ZeroSumGame, ZeroSumGame.toLossSeq, hedgeDist, prefixHedgeMixedStrategy, prefixHedgeWeight_eq_hedgeWeight, prefixPotential_eq_potential}

The weight of row $i$ in the prefix Hedge mixed strategy at round $t$ equals
the abstract Hedge distribution $\mathrm{hedgeDist}(\eta, G.\mathrm{toLossSeq}(a), t, i)$.
\end{lemma}

n21031.content:
\begin{lemma}[Regret-to-payoff bridge]
\lean{regret_to_payoff}
\label{regret_to_payoff}
\leanok
\uses{ZeroSumGame}

Suppose the row player uses per-round distributions $p_0, \dots, p_{T-1}$
(each summing to $1$) against column responses $j_0, \dots, j_{T-1}$, and
achieves cumulative loss regret at most $R$:
\[
  \sum_t \sum_i p_t(i)(1 - A_{i,j_t})
  - \min_i \sum_t (1 - A_{i,j_t}) \;\le\; R.
\]
Then the total payoff satisfies
\[
  \sum_t \sum_i p_t(i) A_{i,j_t}
  \;\ge\;
  \sup_i \sum_t A_{i,j_t} - R.
\]
\end{lemma}

n21032.content:
\begin{lemma}[Average of per-round minima is at most minimum of averages]
\lean{avg_min_le_min_avg}
\label{avg_min_le_min_avg}
\leanok

For any $f : \mathrm{Fin}\,T \to \mathrm{Fin}\,N \to \mathbb{R}$ and $T > 0$,
\[
  \frac{1}{T} \sum_{t=0}^{T-1} \min_{j} f(t, j)
  \;\le\;
  \min_{j} \frac{1}{T} \sum_{t=0}^{T-1} f(t, j).
\]
\end{lemma}

n21033.content:
\begin{lemma}[Hedge construction]
\lean{hedge_construction}
\label{hedge_construction}
\leanok
\uses{LossSeq, LossSeq.Valid, MixedStrategy, ZeroSumGame, ZeroSumGame.toLossSeq, ZeroSumGame.toLossSeq_valid, averageStrategy, bestColumn, bestColumn_spec, bestExpertLoss, cumLoss_horizon, empiricalStrategy, hedgeCumLoss, hedgeDist, hedgeDist_nonneg, hedgeDist_sum, hedgeLoss, hedgeResponseNat, hedge_regret_bound_tight, payoffVsPure, payoffVsPure_averageStrategy, prefixHedgeMixedStrategy, prefixHedgeMixedStrategy_weight_eq_hedgeDist, pureVsPayoff, pureVsPayoff_empiricalStrategy, regret, regret_to_payoff}

Given a game $G$ with $M \ge 2$ rows, a number of rounds $T > 0$, and a
learning rate $\eta > 0$, there exist mixed strategies $p$ (row) and $q$
(column) such that for all pure $i \in \mathrm{Fin}\,M$ and $j \in
\mathrm{Fin}\,N$,
\[
  \mathrm{payoffVsPure}(G, p, j)
  + \frac{\ln M / \eta + \eta T / 8}{T}
  \;\ge\;
  \mathrm{pureVsPayoff}(G, i, q).
\]
The strategies are constructed by running Hedge for $T$ rounds, with the
column player taking pure best responses, and then averaging.
\end{lemma}

n21034.content:
\begin{theorem}[Approximate minimax]
\lean{approx_minimax}
\label{approx_minimax}
\leanok
\uses{MixedStrategy, ZeroSumGame, hedge_construction, payoffVsPure, pureVsPayoff}

For any finite zero-sum game $G$ with $M \ge 2$ rows and any $\varepsilon > 0$,
there exist mixed strategies $p$ (row) and $q$ (column) forming an
$\varepsilon$-approximate saddle point: for all pure $i \in \mathrm{Fin}\,M$
and $j \in \mathrm{Fin}\,N$,
\[
  \mathrm{payoffVsPure}(G, p, j) + \varepsilon
  \;\ge\;
  \mathrm{pureVsPayoff}(G, i, q).
\]
\end{theorem}

n21035.content:
\begin{theorem}[Approximate minimax theorem]
\lean{minimax_approx_theorem}
\label{minimax_approx_theorem}
\leanok
\uses{MixedStrategy, ZeroSumGame, approx_minimax, payoffVsPure, pureVsPayoff}

For any finite zero-sum game $G$ with at least $2$ row actions and any
$\varepsilon > 0$, there exist mixed strategies $p, q$ such that for all pure
$i, j$,
\[
  \mathrm{payoffVsPure}(G, p, j) + \varepsilon
  \;\ge\;
  \mathrm{pureVsPayoff}(G, i, q).
\]
This is the same guarantee as \texttt{approx\_minimax}, stated in the
$\forall \varepsilon > 0, \exists p, q$ form.
\end{theorem}

n21037.content:
\begin{theorem}[Total weight upper bound]
\lean{wm_weight_upper_bound}
\label{wm_weight_upper_bound}
\leanok
\uses{wm_weight_shrinkage}

Under the same shrinkage hypothesis as \texttt{wm\_weight\_shrinkage}, if additionally
$n \ge 1$ and the initial total weight satisfies $W(0) = n$, then
\[
  W(M) \;\le\; n \cdot \left(\frac{1+\beta}{2}\right)^{\!M}.
\]
\end{theorem}

n21039.content:
\begin{theorem}[Logarithmic mistake bound]
\lean{wm_mistake_bound_log}
\label{wm_mistake_bound_log}
\leanok

Let $n \ge 2$, $\beta \in (0,1)$, and suppose
$\beta^{M^*} \le n \cdot \bigl(\tfrac{1+\beta}{2}\bigr)^{M_{\mathrm{WM}}}$.
Then
\[
  M_{\mathrm{WM}} \cdot \log\!\frac{2}{1+\beta}
  \;\le\;
  \log n \;+\; M^* \cdot \log\frac{1}{\beta}.
\]
Equivalently, $M_{\mathrm{WM}} \le \dfrac{\log n + M^* \cdot \log(1/\beta)}{\log(2/(1+\beta))}$,
giving the standard Weighted Majority mistake bound.
\end{theorem}

n21040.content:
\begin{theorem}[Factor-2 lower bound for deterministic algorithms]
\lean{deterministic_factor2_lower_bound}
\label{deterministic_factor2_lower_bound}
\leanok

For any $T \in \mathbb{N}$, there exist $M_{\mathrm{alg}}, M^* \in \mathbb{N}$ with
$M_{\mathrm{alg}} = T$ and $2 M^* \le T$.
This witnesses that a deterministic learner facing two constant experts can be forced
by an adversary to make $T$ mistakes while the best expert makes at most $T/2$,
showing the factor of $2$ in the Weighted Majority bound is unavoidable.
\end{theorem}

n21041.content:
\begin{definition}[Maximum size of a binary code with given distance]
\lean{codeA}
\label{codeA}
\leanok


For naturals $n$ and $d$, $A(n,d)$ is the supremum of the cardinalities $k$ for which
there is a finite set $C$ of binary codewords $\mathrm{Fin}\,n \to \mathrm{Bool}$ with
$|C| = k$ and such that any two distinct $x, y \in C$ differ in at least $d$
coordinates.
\end{definition}

n21043.content:
\begin{definition}[Asymptotic binary code rate]
\lean{rate}
\label{rate}
\leanok

\uses{codeA}
For $\delta \in [0,1]$, the asymptotic rate is
\[
  R(\delta) \;=\; \limsup_{n\to\infty} \frac{1}{n}\log_2 A(n, \lfloor \delta n \rfloor).
\]
\end{definition}

n21046.content:
\begin{theorem}[Value of the zeroth Krawtchouk polynomial]
\lean{krawtchouk_zero}

\label{krawtchouk_zero}
\leanok



\uses{krawtchouk}

For all $n$ and $x$, $K_0^{(n)}(x) = 1$.
\end{theorem}

n21049.content:
\begin{theorem}[Krawtchouk generating function]
\lean{krawtchouk_generating_function}
\label{krawtchouk_generating_function}
\leanok


\uses{krawtchouk}

For $x \le n$ and every real $z$,
\[
  \sum_{j=0}^{n} K_j^{(n)}(x)\, z^{j} \;=\; (1-z)^{x}(1+z)^{\,n-x}.
\]
\end{theorem}

n21050.content:
\begin{theorem}[Orthogonality of Krawtchouk polynomials]
\lean{krawtchouk_orthogonality}
\label{krawtchouk_orthogonality}
\leanok



\uses{krawtchouk, krawtchouk_generating_function}

For $r \le n$ and $s \le n$,
\[
  \sum_{x=0}^{n} \binom{n}{x} K_r^{(n)}(x)\,K_s^{(n)}(x)
  \;=\;
  \begin{cases}
    2^{n}\binom{n}{r}, & r = s,\\
    0, & r \ne s.
  \end{cases}
\]
\end{theorem}

n21051.content:
\begin{theorem}[Three-term recurrence for Krawtchouk polynomials]
\lean{krawtchouk_recurrence}
\label{krawtchouk_recurrence}
\leanok



\uses{krawtchouk, krawtchouk_generating_function}

For $1 \le j$, $j + 1 \le n$ and $x \le n$,
\[
  (j+1)\,K_{j+1}^{(n)}(x) \;=\; (n - 2x)\,K_j^{(n)}(x) - (n - j + 1)\,K_{j-1}^{(n)}(x).
\]
\end{theorem}

n21052.content:
\begin{theorem}[Agreement of the sum formula and the polynomial form]
\lean{krawtchoukPoly_eval_nat}
\label{krawtchoukPoly_eval_nat}
\leanok
\uses{krawtchouk, krawtchoukPoly, krawtchouk_zero, krawtchouk_one, krawtchouk_recurrence}

For $j \le n$ and $x \le n$, evaluating the polynomial $K_j^{(n)}$ at the real number
$x$ gives the value $K_j^{(n)}(x)$ of the alternating-sum definition.
\end{theorem}

n21053.content:
\begin{theorem}[Delsarte LP inequality]
\lean{delsarte_lp_bound}

\label{delsarte_lp_bound}





\uses{codeA, krawtchouk}
Let $F(x) = \sum_{j=0}^{n} F_j K_j^{(n)}(x)$ for real coefficients $F_j$. If
$F_0 > 0$, if $F_j \ge 0$ for all $1 \le j \le n$, and if $F(x) \le 0$ for every
integer $x$ with $d \le x \le n$, then
\[
  A(n,d) \;\le\; \frac{F(0)}{F_0}.
\]
\end{theorem}

n21054.content:
\begin{definition}[Truncated Christoffel--Darboux kernel]
\lean{cdKernel}
\label{cdKernel}
\leanok

\uses{krawtchoukPoly}
For $t \le n$ and real $a, x$, the truncated reproducing kernel is
\[
  \Phi_{n,t}(a,x) \;=\; \sum_{j=0}^{t} \frac{K_j^{(n)}(a)\,K_j^{(n)}(x)}{\binom{n}{j}}.
\]
\end{definition}

n21055.content:
\begin{theorem}[Christoffel--Darboux identity for Krawtchouk polynomials]
\lean{cd_identity}
\label{cd_identity}
\leanok

\uses{cdKernel, krawtchoukPoly}

For $t + 1 \le n$ and real $a \ne x$ there is a scalar $c > 0$ with
\[
  \Phi_{n,t}(a,x) \;=\; c\,\frac{K_t^{(n)}(a)K_{t+1}^{(n)}(x) - K_{t+1}^{(n)}(a)K_t^{(n)}(x)}{a - x}.
\]
\end{theorem}

n21056.content:
\begin{theorem}[Positivity of Krawtchouk values below all zeros]
\lean{krawtchouk_positive_below_smallest_zero}

\label{krawtchouk_positive_below_smallest_zero}




\uses{krawtchoukPoly}
Fix $t + 1 \le n$ and a real $a$ that is strictly smaller than every real zero
$\xi$ of $K_t^{(n)}$. Then $K_j^{(n)}(a) > 0$ for every $j \le t$.
\end{theorem}

n21057.content:
\begin{theorem}[Nonpositivity of the kernel beyond a threshold]
\lean{cdKernel_nonpos_beyond_threshold}
\label{cdKernel_nonpos_beyond_threshold}

\uses{cdKernel, krawtchoukPoly}
Under the same hypotheses ($t + 1 \le n$ and $a$ strictly below every real zero of
$K_t^{(n)}$), there exists a threshold $\eta$ such that $\Phi_{n,t}(a,x) \le 0$ for
every integer $x$ with $\eta \le x \le n$.
\end{theorem}

n21058.content:
\begin{theorem}[Finite-$n$ MRRW bound]
\lean{finite_n_mrrw_bound}
\label{finite_n_mrrw_bound}
\leanok

\uses{cdKernel, codeA, delsarte_lp_bound, krawtchoukPoly, krawtchoukPoly_eval_nat, krawtchouk_positive_below_smallest_zero}

Let $t + 1 \le n$, let $a$ be strictly below every real zero of $K_t^{(n)}$, and
suppose $\Phi_{n,t}(a,x) \le 0$ for every integer $x$ with $d \le x \le n$. Then
\[
  A(n,d) \;\le\; \Phi_{n,t}(a,0).
\]
\end{theorem}

n21059.content:
\begin{theorem}[Asymptotics of the smallest Krawtchouk zero]
\lean{smallest_zero_asymptotic}

\label{smallest_zero_asymptotic}





\uses{cdKernel, krawtchoukPoly}
Let $0 < \tau < 1/2$ and let $t_n$ satisfy $t_n / n \to \tau$. Then there is a
sequence $a_n$ such that, eventually in $n$, $a_n$ lies strictly below every real
zero of $K_{t_n}^{(n)}$, with $a_n/n \to \tfrac12 - \sqrt{\tau(1-\tau)}$, and such
that eventually $\Phi_{n,t_n}(a_n,x) \le 0$ for all integers $x$ with
$\lfloor (\tfrac12 - \sqrt{\tau(1-\tau)})n \rfloor \le x \le n$.
\end{theorem}

n21060.content:
\begin{theorem}[Entropy growth rate of the objective]
\lean{entropy_growth_of_objective}

\label{entropy_growth_of_objective}





\uses{binaryEntropy, cdKernel, krawtchoukPoly}
Let $0 < \tau < 1/2$, let $t_n/n \to \tau$, and let $a_n$ eventually lie strictly
below every real zero of $K_{t_n}^{(n)}$. Then
\[
  \limsup_{n\to\infty} \frac{1}{n}\log_2 \Phi_{n,t_n}(a_n,0) \;\le\; H(\tau).
\]
\end{theorem}

n21061.content:
\begin{theorem}[Entropy asymptotics for binomial tails]
\lean{binomial_tail_entropy_asymptotic}
\label{binomial_tail_entropy_asymptotic}
\uses{binaryEntropy}
For $0 \le \tau \le 1/2$,
\[
  \frac{1}{n}\log_2\!\left(\sum_{j=0}^{\lfloor \tau n\rfloor} \binom{n}{j}\right)
  \;\longrightarrow\; H(\tau)
  \qquad (n \to \infty).
\]
\end{theorem}

n21062.content:
\begin{theorem}[Involution between $\delta$ and $\tau$]
\lean{delta_tau_involution}
\label{delta_tau_involution}
\leanok

For $0 \le \delta \le 1/2$, setting $\tau = \tfrac12 - \sqrt{\delta(1-\delta)}$ gives
back $\delta = \tfrac12 - \sqrt{\tau(1-\tau)}$; that is, the map is an involution on
$[0,1/2]$.
\end{theorem}

n21065.content:
\begin{theorem}[Binary first MRRW bound]
\lean{mrrw_bound}

\label{mrrw_bound}





\uses{binaryEntropy, rate}
For every $\delta$ with $0 \le \delta \le 1/2$,
\[
  R(\delta) \;\le\; H\!\left(\tfrac12 - \sqrt{\delta(1-\delta)}\right).
\]
\end{theorem}

n21068.content:
\begin{definition}[Real-valued binomial coefficient]
\lean{chooseR}
\label{chooseR}
\leanok
For naturals $n$ and $k$, $\texttt{chooseR}\,n\,k$ is the binomial coefficient $\binom{n}{k}$
cast into $\mathbb{R}$.
\end{definition}

n21069.content:
\begin{theorem}[Binomial ratio bound, upper]
\lean{binomial_ratio_upper}

\label{binomial_ratio_upper}
\leanok



\uses{chooseR}

Fact 4.2 (upper half).  Let $n, \ell, q$ be naturals with $n > 0$, $q > 0$, $q \le \ell$,
$2\ell \le n$ and $2q \le n$.  Then
\[
  \frac{\binom{n-2q}{\ell-q}}{\binom{n}{\ell}} \ \le\ e^{3q}\left(\frac{\ell}{n}\right)^{q},
\]
where both binomial coefficients are taken in $\mathbb{R}$ via $\texttt{chooseR}$.
\end{theorem}

n21070.content:
\begin{theorem}[Binomial ratio bound, lower]
\lean{binomial_ratio_lower}

\label{binomial_ratio_lower}
\leanok



\uses{chooseR}

Fact 4.2 (lower half).  Under the same hypotheses $n > 0$, $q > 0$, $q \le \ell$,
$2\ell \le n$ and $2q \le n$,
\[
  e^{-3q}\left(\frac{\ell}{n}\right)^{q} \ \le\ \frac{\binom{n-2q}{\ell-q}}{\binom{n}{\ell}},
\]
with the binomial coefficients again read in $\mathbb{R}$ via $\texttt{chooseR}$.
\end{theorem}

n21071.content:
\begin{definition}[Heavy pairs of a hypergraph]
\lean{heavyPairs}
\label{heavyPairs}
\leanok

\uses{Hypergraph, Hypergraph.degree}
For a hypergraph $H$ on $\mathrm{Fin}\,n$ and a threshold $d$, the set of heavy pairs
\[
  P \;=\; \{\, Q \subseteq \mathrm{Fin}\,n \;:\; \left\lvert Q\right\rvert = 2, \ \deg_H(Q) > d \,\},
\]
realised as the collection of two-element sets $\{u,v\}$ whose degree in $H$ exceeds $d$.
\end{definition}

n21072.content:
\begin{theorem}[Counting heavy pairs]
\lean{heavy_pair_count_bound}
\label{heavy_pair_count_bound}
\leanok

\uses{Hypergraph, Hypergraph.IsUniform, Hypergraph.degree, heavyPairs}

Let $H$ be a $3$-uniform hypergraph on $\mathrm{Fin}\,n$ and let $d > 0$. Then the number
of heavy pairs satisfies
\[
  \left\lvert P\right\rvert \cdot d \;\le\; 3 \, \left\lvert H\right\rvert,
\]
where $P$ is the set of pairs of degree more than $d$; equivalently $\left\lvert P\right\rvert \le 3m/d$
for $m = \left\lvert H\right\rvert$ edges, since each $3$-edge contributes exactly three pairs.
\end{theorem}

n21074.content:
\begin{definition}[Hypergraph on $\mathrm{Fin}\,n$]
\lean{Hypergraph}
\label{Hypergraph}
\leanok

A hypergraph on the vertex set $\mathrm{Fin}\,n$ is a finite collection of subsets of
$\mathrm{Fin}\,n$, modelled as $\mathtt{Finset}\,(\mathtt{Finset}\,(\mathrm{Fin}\,n))$.
Its elements are called edges (or constraints).
\end{definition}

n21075.content:
\begin{definition}[$q$-uniform hypergraph]
\lean{Hypergraph.IsUniform}

\label{Hypergraph.IsUniform}
\leanok

\uses{Hypergraph}
A hypergraph $H$ on $\mathrm{Fin}\,n$ is $q$-uniform when every edge $C \in H$ has
exactly $q$ vertices, i.e.\ $\left\lvert C\right\rvert = q$.
\end{definition}

n21076.content:
\begin{definition}[Matching]
\lean{Hypergraph.IsMatching}
\label{Hypergraph.IsMatching}
\leanok

\uses{Hypergraph}
A hypergraph $H$ is a matching when its edges are pairwise disjoint: for all
$C, C' \in H$ with $C \neq C'$, the sets $C$ and $C'$ are disjoint.
\end{definition}

n21077.content:
\begin{definition}[Degree of a set in a hypergraph]
\lean{Hypergraph.degree}

\label{Hypergraph.degree}
\leanok

\uses{Hypergraph}
The degree of a vertex set $Q \subseteq \mathrm{Fin}\,n$ in a hypergraph $H$ is the
number of edges of $H$ containing $Q$:
\[
  \deg_H(Q) \;=\; \left\lvert \{\, C \in H \;:\; Q \subseteq C \,\}\right\rvert.
\]
\end{definition}

n21078.content:
\begin{definition}[Pair-degree bound]
\lean{Hypergraph.pairDegreeBound}
\label{Hypergraph.pairDegreeBound}
\leanok

\uses{Hypergraph, Hypergraph.degree}
A hypergraph $H$ satisfies the pair-degree bound $d$ when every pair of distinct
vertices $u \neq v$ lies in at most $d$ edges, i.e.\ $\deg_H(\{u,v\}) \le d$.
\end{definition}

n21079.content:
\begin{definition}[Sign values $\pm 1$]
\lean{IsPMOne}
\label{IsPMOne}
\leanok
The predicate on an integer $x$ stating that $x$ is a sign value, i.e.\ $x = 1$ or
$x = -1$. Assignments used below take values in this set.
\end{definition}

n21080.content:
\begin{definition}[Normal form locally decodable code]
\lean{NormalLDC}
\label{NormalLDC}
\leanok


\uses{Hypergraph, Hypergraph.IsMatching, Hypergraph.IsUniform}
The structural data of a $(3,\delta,\varepsilon)$-normally decodable code with message
length $k$ and block length $n$: for each message index $i : \mathrm{Fin}\,k$ a
hypergraph $H_i$ on $\mathrm{Fin}\,n$ which is $3$-uniform and a matching, together
with real parameters $\delta > 0$ and $\varepsilon > 0$ and the density requirement
$\delta n \le \left\lvert H_i\right\rvert$ for every $i$.
\end{definition}

n21081.content:
\begin{definition}[Combined hypergraph of an LDC]
\lean{NormalLDC.combined}
\label{NormalLDC.combined}
\leanok

\uses{Hypergraph, NormalLDC}
For a normal form code $L$, the hypergraph obtained as the union of all its matchings,
$\bigcup_{i : \mathrm{Fin}\,k} H_i$, viewed as a hypergraph on $\mathrm{Fin}\,n$.
\end{definition}

n21082.content:
\begin{definition}[Total number of constraints]
\lean{NormalLDC.totalConstraints}
\label{NormalLDC.totalConstraints}
\leanok

\uses{NormalLDC}
For a normal form code $L$, the total number of constraints
\[
  m \;=\; \sum_{i : \mathrm{Fin}\,k} \left\lvert H_i\right\rvert.
\]
\end{definition}

n21083.content:
\begin{definition}[Monomial of an assignment on a set]
\lean{assignment_prod}
\label{assignment_prod}
\leanok
For an assignment $x : \mathrm{Fin}\,n \to \mathbb{Z}$ and a set
$C \subseteq \mathrm{Fin}\,n$, the product
\[
  x_C \;=\; \prod_{v \in C} x_v .
\]
\end{definition}

n21084.content:
\begin{definition}[XOR polynomial of a message]
\lean{NormalLDC.xorPoly}
\label{NormalLDC.xorPoly}
\leanok


\uses{NormalLDC, NormalLDC.totalConstraints, assignment_prod}
For a normal form code $L$, a message $b : \mathrm{Fin}\,k \to \mathbb{Z}$ and an
assignment $x : \mathrm{Fin}\,n \to \mathbb{Z}$, the real-valued XOR instance
\[
  \psi_b(x) \;=\; \frac{1}{m} \sum_{i : \mathrm{Fin}\,k} b_i
    \sum_{C \in H_i} x_C ,
\]
where $m$ is the total number of constraints of $L$.
\end{definition}

