n21091.content:
\begin{theorem}[High-value observation for a normal form LDC]
\lean{high_value_observation}
\label{high_value_observation}
\leanok

\uses{IsPMOne, NormalLDC, NormalLDC.totalConstraints, NormalLDC.xorPoly, assignment_prod}

Let $L$ be a normal form $(3,\delta,\varepsilon)$-decodable code with message length
$k > 0$, block length $n > 0$ and at least one constraint, i.e.\ $m > 0$, and suppose the
advantage satisfies $\varepsilon \le 1/2$. Then there are a message
$b : \mathrm{Fin}\,k \to \mathbb{Z}$ and an assignment
$x : \mathrm{Fin}\,n \to \mathbb{Z}$, both taking values in $\{-1,1\}$, such that the XOR
polynomial of $L$ satisfies
\[
  \psi_b(x) \;\ge\; 2\varepsilon .
\]

\emph{Placeholder.}  The paper's Lemma 5.1 bounds the \emph{expectation}
$\mathbb{E}_b[\mathrm{val}(\psi_b)] \ge 2\varepsilon$; the Lean statement asserts only that \emph{some}
$b$ and $x$ achieve the bound, and is discharged by the constant all-ones witness.  The
expectation bound is \emph{not} formalised here.
\end{theorem}

n21096.content:
\begin{theorem}[Row sparsity of the Kikuchi matrices]
\lean{row_bound_le_two_d}

\label{row_bound_le_two_d}
\leanok


For naturals $d$ and $\mathrm{row\_nnz}$, if the number of nonzero entries in a row of
the matrix $B_i$ satisfies $\mathrm{row\_nnz} \le 2d$, then $\mathrm{row\_nnz} \le 2d$.
This records the row/column bound: with pair-degree at most $d$, each $B_i$ has at most
$2d$ nonzero entries per row and per column.
\end{theorem}

n21102.content:
\begin{definition}[Noise kernel of $\rho$-correlated pairs]
\lean{GeneralHypercontractivity.noiseKernel}
\label{GeneralHypercontractivity.noiseKernel}
\leanok

\uses{BooleanAnalysis.BoolCube, BooleanAnalysis.boolToSign}
For $\rho \in \mathbb{R}$ and $x, y$ in the cube $\mathrm{BoolCube}\,n$, the noise kernel is
\[
  K_\rho(x,y) \;=\; \prod_{i} \frac{1 + \rho\,\chi(x_i)\,\chi(y_i)}{2},
\]
where $\chi(\cdot)$ is the $\pm 1$ encoding of a bit. It is the transition probability from
$x$ to $y$ under $\rho$-correlated noise.
\end{definition}

n21103.content:
\begin{lemma}[Nonnegativity of the noise kernel]
\lean{GeneralHypercontractivity.noiseKernel_nonneg}
\label{GeneralHypercontractivity.noiseKernel_nonneg}
\leanok
\uses{BooleanAnalysis.BoolCube, BooleanAnalysis.boolToSign, GeneralHypercontractivity.noiseKernel}

If $0 \le \rho \le 1$ then $K_\rho(x,y) \ge 0$ for all $x, y \in \mathrm{BoolCube}\,n$.
\end{lemma}

n21104.content:
\begin{lemma}[Fourier form of the kernel product]
\lean{GeneralHypercontractivity.sum_fourier_kernel}
\label{GeneralHypercontractivity.sum_fourier_kernel}
\leanok
\uses{BooleanAnalysis.BoolCube, BooleanAnalysis.boolToSign, BooleanAnalysis.chiS}

For all $\rho \in \mathbb{R}$ and $x, y \in \mathrm{BoolCube}\,n$,
\[
  \sum_{S \subseteq [n]} \rho^{\left\lvert S\right\rvert}\,\chi_S(x)\,\chi_S(y)
  \;=\; \prod_{i} \bigl(1 + \rho\,\chi(x_i)\,\chi(y_i)\bigr).
\]
\end{lemma}

n21105.content:
\begin{lemma}[Noise operator as a kernel sum]
\lean{GeneralHypercontractivity.noiseOp_eq_kernel_sum}
\label{GeneralHypercontractivity.noiseOp_eq_kernel_sum}
\leanok
\uses{BooleanAnalysis.BoolCube, BooleanAnalysis.BooleanFunc, BooleanAnalysis.expect, BooleanAnalysis.fourierCoeff, BooleanAnalysis.innerProduct, BooleanAnalysis.noiseOp, BooleanAnalysis.uniformWeight, GeneralHypercontractivity.noiseKernel, GeneralHypercontractivity.sum_fourier_kernel}

For every $g : \mathrm{BoolCube}\,n \to \mathbb{R}$ and every $x$,
\[
  (T_\rho g)(x) \;=\; \sum_{y} K_\rho(x,y)\, g(y).
\]
\end{lemma}

n21106.content:
\begin{lemma}[Inner product as a kernel-weighted double sum]
\lean{GeneralHypercontractivity.innerProduct_noiseOp_eq_weighted_sum}
\label{GeneralHypercontractivity.innerProduct_noiseOp_eq_weighted_sum}
\leanok
\uses{BooleanAnalysis.BoolCube, BooleanAnalysis.BooleanFunc, BooleanAnalysis.expect, BooleanAnalysis.innerProduct, BooleanAnalysis.noiseOp, BooleanAnalysis.uniformWeight, GeneralHypercontractivity.noiseKernel, GeneralHypercontractivity.noiseOp_eq_kernel_sum}

For all $f, g : \mathrm{BoolCube}\,n \to \mathbb{R}$,
\[
  \left\langle f, T_\rho g \right\rangle \;=\; \frac{1}{2^n} \sum_{x} \sum_{y} K_\rho(x,y)\, f(x)\, g(y).
\]
\end{lemma}

n21107.content:
\begin{lemma}[Monotonicity of kernel-weighted expectations]
\lean{GeneralHypercontractivity.corrExpect_mono}
\label{GeneralHypercontractivity.corrExpect_mono}
\leanok
\uses{BooleanAnalysis.BoolCube, BooleanAnalysis.uniformWeight, GeneralHypercontractivity.noiseKernel, GeneralHypercontractivity.noiseKernel_nonneg}

Let $0 \le \rho \le 1$ and let $h, h' : \mathrm{BoolCube}\,n \times \mathrm{BoolCube}\,n \to \mathbb{R}$
satisfy $h(x,y) \le h'(x,y)$ for all $x, y$. Then the kernel-weighted average of $h$ is at
most that of $h'$:
\[
  \frac{1}{2^n}\sum_{x}\sum_{y} K_\rho(x,y)\, h(x,y)
  \;\le\;
  \frac{1}{2^n}\sum_{x}\sum_{y} K_\rho(x,y)\, h'(x,y).
\]
\end{lemma}

n21108.content:
\begin{lemma}[Factorization of the kernel along the last coordinate]
\lean{GeneralHypercontractivity.noiseKernel_snoc}
\label{GeneralHypercontractivity.noiseKernel_snoc}
\leanok
\uses{BooleanAnalysis.BoolCube, BooleanAnalysis.boolToSign, GeneralHypercontractivity.noiseKernel}

For $x', y' \in \mathrm{BoolCube}\,n$ and bits $b, b'$,
\[
  K_\rho\bigl(\mathrm{snoc}(x',b),\ \mathrm{snoc}(y',b')\bigr)
  \;=\; K_\rho(x',y') \cdot \frac{1 + \rho\,\chi(b)\,\chi(b')}{2}.
\]
\end{lemma}

n21109.content:
\begin{lemma}[Expectation on $n+1$ bits as an iterated expectation]
\lean{GeneralHypercontractivity.expect_succ_eq_iterated}
\label{GeneralHypercontractivity.expect_succ_eq_iterated}
\leanok
\uses{Bonami.sum_boolCube_succ, Bonami.uniformWeight_succ, BooleanAnalysis.BooleanFunc, BooleanAnalysis.expect}

For $h : \mathrm{BoolCube}\,(n+1) \to \mathbb{R}$,
\[
  \mathbb{E}[h] \;=\; \mathbb{E}_{x'}\Bigl[\tfrac12\bigl(h(\mathrm{snoc}(x',\mathit{false})) + h(\mathrm{snoc}(x',\mathit{true}))\bigr)\Bigr],
\]
the outer expectation being over $x' \in \mathrm{BoolCube}\,n$.
\end{lemma}

