\uses{BooleanAnalysis.BooleanFunc, BooleanAnalysis.fourierCoeff, KKL.noisyInfluence}

For every $\rho$,
\[
  \sum_{i=1}^{n} \mathrm{Inf}_i^{\rho}[f]
  \;=\; \sum_{S \subseteq [n]} \left\lvert S\right\rvert\,\rho^{\left\lvert S\right\rvert-1}\,\hat f(S)^2 .
\]
\end{lemma}

n21152.content:
\begin{lemma}[Total influence as a sum of influences]
