n21156.content:
\begin{lemma}[Fourier coefficients of the low-degree part]
\lean{KKL.fourierCoeff_lowDegreePart}
\label{KKL.fourierCoeff_lowDegreePart}
\leanok
\uses{BooleanAnalysis.BoolCube, BooleanAnalysis.BooleanFunc, BooleanAnalysis.chiS, BooleanAnalysis.expect, BooleanAnalysis.fourierCoeff, BooleanAnalysis.fourier_coeff_chi, BooleanAnalysis.innerProduct, BooleanAnalysis.uniformWeight, KKL.lowDegreePart}

The truncation acts as a projection on the Fourier side: for every $S$,
$\widehat{f_{\le k}}(S) = \hat f(S)$ when $\left\lvert S\right\rvert \le k$, and
$\widehat{f_{\le k}}(S) = 0$ otherwise.
\end{lemma}

n21157.content:
\begin{lemma}[$L^2$ error of low-degree truncation]
\lean{KKL.lowDegree_l2_error}
\label{KKL.lowDegree_l2_error}
\leanok
\uses{BooleanAnalysis.BooleanFunc, BooleanAnalysis.chiS, BooleanAnalysis.expect, BooleanAnalysis.fourierCoeff, BooleanAnalysis.innerProduct, BooleanAnalysis.parseval, BooleanAnalysis.uniformWeight, KKL.fourierCoeff_lowDegreePart, KKL.highDegreePart, KKL.l2DistSq, KKL.lowDegreePart, KKL.low_plus_high_eq}

The squared $L^2$ error of the degree-$k$ truncation is exactly the Fourier weight
above level $k$:
\[
  \mathbb{E}\big[(f - f_{\le k})^2\big] \;=\; \sum_{\left\lvert S\right\rvert > k} \hat f(S)^2 .
\]
\end{lemma}

n21158.content:
\begin{lemma}[Fourier tail weight bound]
\lean{KKL.tail_fourier_weight_bound}

\label{KKL.tail_fourier_weight_bound}
\leanok




























































\uses{BooleanAnalysis.BooleanFunc, BooleanAnalysis.fourierCoeff, BooleanAnalysis.totalInfluence, BooleanAnalysis.totalInfluence_eq_sum_sq_deg}

For $k > 0$ the Fourier weight of $f$ above level $k$ is controlled by the total
influence:
\[
  \sum_{\left\lvert S\right\rvert > k} \hat f(S)^2 \;\le\; \frac{I[f]}{k}.
\]
\end{lemma}

n21159.content:
\begin{lemma}[Low-degree approximation]
\lean{KKL.lowDegree_approx}

