\uses{DecisionTree, DecisionTree.card_symmDiff_singleton, DecisionTree.coeffs, DecisionTree.depth}

If $T.\mathrm{depth} < \left\lvert S\right\rvert$, then $\mathrm{coeffs}\,T\,S = 0$: frequencies of
cardinality exceeding the tree depth carry no weight.
\end{lemma}

n21181.content:
\begin{lemma}[Coefficient $1$-norm bounded by tree size]
\lean{DecisionTree.sum_abs_coeffs_le}

\label{DecisionTree.sum_abs_coeffs_le}
\leanok
\uses{BooleanAnalysis.boolToSign, DecisionTree, DecisionTree.coeffs, DecisionTree.size, DecisionTree.sum_symmDiff_reindex}

For every decision tree $T$,
\[
\sum_{S} \left\lvert \mathrm{coeffs}\,T\,S\right\rvert \le T.\mathrm{size},
\]
i.e.\ the spectral $1$-norm of the coefficients is at most the number of leaves.
\end{lemma}

n21182.content:
\begin{lemma}[Granularity, multiplicative form]
\lean{DecisionTree.coeffs_mul_two_pow_int}

