n21192.content:
\begin{lemma}[Specification of the minimum decision-tree depth]
\lean{DecisionTree.exists_dtree_of_dtDepth}
\label{DecisionTree.exists_dtree_of_dtDepth}
\leanok

\uses{DecisionTree, DecisionTree.depth, DecisionTree.eval, dtDepth}

For every Boolean function $f : \{0,1\}^n \to \{0,1\}$ there exists a decision tree $T$
with $T.\mathrm{depth} \le \mathrm{dtDepth}\,f$ that computes $f$, i.e.\
$T.\mathrm{eval}\,x = f(x)$ for all $x$.
\end{lemma}

n21193.content:
\begin{theorem}[Degree bounded by decision-tree depth (Proposition 3.16)]
\lean{DecisionTree.degree_le_dtDepth}
\label{DecisionTree.degree_le_dtDepth}
\leanok

\uses{BooleanAnalysis.boolToSign, BooleanAnalysis.has_degree_at_most, DecisionTree.degree_le_depth, DecisionTree.exists_dtree_of_dtDepth, DecisionTree.signEval, dtDepth}

For every Boolean function $f$, the $\pm 1$-encoding
$x \mapsto \mathrm{boolToSign}(f(x))$ has Fourier degree at most $\mathrm{dtDepth}\,f$,
the minimum depth of a decision tree computing $f$. This is the implication
$\mathrm{DT}(f) \le k \Rightarrow \deg(f) \le k$ used as input to O'Donnell's Lemma 4.21.
\end{theorem}

n21194.content:
\begin{lemma}[Subset-of-free-variables indicator factors per coordinate]
\lean{RestrictionFourier.indicator_subset_eq_prod}
\label{RestrictionFourier.indicator_subset_eq_prod}
\leanok
\uses{RestrictionFourier.mem_freeVars, SwitchingLemma2.Restriction, SwitchingLemma2.Restriction.freeVars}

For a set $T \subseteq \{0,\dots,n-1\}$ and a restriction $\rho$, the indicator of the event
$T \subseteq \mathrm{freeVars}(\rho)$ equals the product over all coordinates $i$ of the factor
that is the indicator of $\rho(i) = \star$ when $i \in T$, and $1$ otherwise.
\end{lemma}

n21195.content:
\begin{theorem}[{Free-set marginal $\Pr[T \subseteq J] = p^{\left\lvert T\right\rvert}$}]
\lean{RestrictionFourier.bernoulliRestrProb_subset_freeVars}
\label{RestrictionFourier.bernoulliRestrProb_subset_freeVars}
\leanok
\uses{LMN.varWeight, RestrictionFourier.indicator_subset_eq_prod, RestrictionFourier.sum_bernoulli_prod, SwitchingLemma2.Restriction.freeVars, SwitchingLemma2.bernoulliRestrProb}

Under a Bernoulli($p$)-random restriction with free-coordinate set $J$, the probability that a
fixed set $T$ is contained in $J$ is
\[
  \Pr[T \subseteq J] \;=\; p^{\left\lvert T\right\rvert} .
\]
This is the first-moment half of O'Donnell Proposition 4.17.
\end{theorem}

n21196.content:
\begin{lemma}[Free-coordinate count as a sum of indicators]
\lean{RestrictionFourier.card_inter_eq_sum}
\label{RestrictionFourier.card_inter_eq_sum}
\leanok
\uses{RestrictionFourier.mem_freeVars, SwitchingLemma2.Restriction, SwitchingLemma2.Restriction.freeVars}

For a set $U$ and a restriction $\rho$ with free-coordinate set $J$, the real number
$\left\lvert U \cap J\right\rvert$ equals $\sum_{i \in U} \mathbf{1}[\rho(i) = \star]$.
\end{lemma}

n21197.content:
\begin{lemma}[Expectation of one free-coordinate indicator]
\lean{RestrictionFourier.expectation_free_indicator}
\label{RestrictionFourier.expectation_free_indicator}
\leanok
\uses{RestrictionFourier.bernoulliRestrProb_subset_freeVars, RestrictionFourier.mem_freeVars, SwitchingLemma2.Restriction, SwitchingLemma2.Restriction.freeVars, SwitchingLemma2.bernoulliRestrProb, SwitchingLemma2.bernoulliRestrWeight}

For each coordinate $i$, the Bernoulli($p$)-weighted sum over all restrictions of the indicator
that $i$ is free equals $p$; that is, $\mathbb{E}[\mathbf{1}[i \in J]] = p$.
\end{lemma}

n21198.content:
\begin{lemma}[Expectation of a product of two free-coordinate indicators]
\lean{RestrictionFourier.expectation_free_indicator_pair}
\label{RestrictionFourier.expectation_free_indicator_pair}
\leanok
\uses{RestrictionFourier.bernoulliRestrProb_subset_freeVars, RestrictionFourier.mem_freeVars, SwitchingLemma2.Restriction, SwitchingLemma2.Restriction.freeVars, SwitchingLemma2.bernoulliRestrProb, SwitchingLemma2.bernoulliRestrWeight}

For distinct coordinates $i \ne j$, the Bernoulli($p$)-weighted sum over all restrictions of the
product of the two indicators that $i$ and $j$ are free equals $p^2$; that is,
$\mathbb{E}[\mathbf{1}[i \in J]\,\mathbf{1}[j \in J]] = p^2$.
\end{lemma}

n21199.content:
\begin{lemma}[First moment of the free-coordinate count]
\lean{RestrictionFourier.expectation_card_inter}
\label{RestrictionFourier.expectation_card_inter}
\leanok
\uses{RestrictionFourier.card_inter_eq_sum, RestrictionFourier.expectation_free_indicator, SwitchingLemma2.Restriction, SwitchingLemma2.Restriction.freeVars, SwitchingLemma2.bernoulliRestrWeight}

Under a Bernoulli($p$)-random restriction with free set $J$, for every set $U$,
\[
  \mathbb{E}\bigl[\left\lvert U \cap J\right\rvert\bigr] \;=\; p \cdot \left\lvert U\right\rvert .
\]
\end{lemma}

n21200.content:
\begin{lemma}[Second moment of the free-coordinate count]
\lean{RestrictionFourier.expectation_card_inter_sq}
\label{RestrictionFourier.expectation_card_inter_sq}
\leanok
\uses{RestrictionFourier.card_inter_eq_sum, RestrictionFourier.expectation_free_indicator, RestrictionFourier.expectation_free_indicator_pair, SwitchingLemma2.Restriction, SwitchingLemma2.Restriction.freeVars, SwitchingLemma2.bernoulliRestrWeight}

Under a Bernoulli($p$)-random restriction with free set $J$, for every set $U$,
\[
  \mathbb{E}\bigl[\left\lvert U \cap J\right\rvert^2\bigr] \;=\; p \cdot \left\lvert U\right\rvert \;+\; p^2\bigl(\left\lvert U\right\rvert^2 - \left\lvert U\right\rvert\bigr).
\]
\end{lemma}

n21201.content:
\begin{lemma}[Variance of the free-coordinate count]
\lean{RestrictionFourier.variance_card_inter}
\label{RestrictionFourier.variance_card_inter}
\leanok
\uses{RestrictionFourier.expectation_card_inter, RestrictionFourier.expectation_card_inter_sq, SwitchingLemma2.Restriction, SwitchingLemma2.Restriction.freeVars, SwitchingLemma2.bernoulliRestrWeight, SwitchingLemma2.bernoulliRestrWeight_sum_one}

For $0 \le p \le 1$ and every set $U$, the Bernoulli($p$)-weighted mean squared deviation of
$\left\lvert U \cap J\right\rvert$ from $p\left\lvert U\right\rvert$ is
\[
  \mathbb{E}\bigl[(p\left\lvert U\right\rvert - \left\lvert U \cap J\right\rvert)^2\bigr] \;=\; p \cdot \left\lvert U\right\rvert \cdot (1 - p).
\]
\end{lemma}

n21202.content:
\begin{theorem}[Chebyshev lower tail for the free-coordinate count]
\lean{RestrictionFourier.bernoulliRestrProb_card_inter_lt}
\label{RestrictionFourier.bernoulliRestrProb_card_inter_lt}
\leanok
\uses{RestrictionFourier.variance_card_inter, SwitchingLemma2.Restriction, SwitchingLemma2.Restriction.freeVars, SwitchingLemma2.bernoulliRestrProb, SwitchingLemma2.bernoulliRestrWeight, SwitchingLemma2.bernoulliRestrWeight_nonneg'}

Let $0 \le p \le 1$, let $U$ be a set of coordinates and let $k \ge 1$ satisfy
$3k \le p\left\lvert U\right\rvert$. Then, under a Bernoulli($p$)-random restriction with free set $J$,
\[
  \Pr\bigl[\left\lvert U \cap J\right\rvert < k\bigr] \;\le\; \frac{3}{4k}.
\]
This is the Bernoulli-restriction analogue of the binomial lower tail used in O'Donnell
Lemma 4.21, with the textbook bound $e^{-2k/3}$ replaced by the elementary $3/(4k) \le 3/4 < 1$.
\end{theorem}

n21203.content:
\begin{lemma}[Complement rule for Bernoulli-restriction probability]
\lean{RestrictionFourier.bernoulliRestrProb_not}
\label{RestrictionFourier.bernoulliRestrProb_not}
\leanok
\uses{SwitchingLemma2.Restriction, SwitchingLemma2.bernoulliRestrProb, SwitchingLemma2.bernoulliRestrWeight_sum_one}

For $0 \le p \le 1$ and any decidable event $E$ on restrictions,
$\Pr[\neg E] = 1 - \Pr[E]$ under the Bernoulli($p$)-restriction measure.
\end{lemma}

n21204.content:
\begin{theorem}[Lower bound on the probability of many free coordinates]
\lean{RestrictionFourier.bernoulliRestrProb_card_inter_ge}
\label{RestrictionFourier.bernoulliRestrProb_card_inter_ge}
\leanok
\uses{RestrictionFourier.bernoulliRestrProb_card_inter_lt, RestrictionFourier.bernoulliRestrProb_not, SwitchingLemma2.Restriction.freeVars, SwitchingLemma2.bernoulliRestrProb}

Let $0 \le p \le 1$, let $U$ be a set of coordinates and let $k \ge 1$ satisfy
$3k \le p\left\lvert U\right\rvert$. Then, under a Bernoulli($p$)-random restriction with free set $J$,
\[
  \Pr\bigl[k \le \left\lvert U \cap J\right\rvert\bigr] \;\ge\; \frac{1}{4},
\]
which is the form consumed by the concentration transfer of O'Donnell Lemma 4.21.
\end{theorem}

n21205.content:
\begin{definition}[Restriction commutes with the $\pm 1$-encoding]
\lean{RestrictionFourier.restrictBF_boolToSign}
\label{RestrictionFourier.restrictBF_boolToSign}
\leanok
\uses{BooleanAnalysis.boolToSign, SwitchingLemma2.Restriction, SwitchingLemma2.restrictFn}

The restriction $\mathrm{restrictBF}$ of a real-valued Boolean function reads free
coordinates from the input and fixed coordinates from the restriction $\rho$, i.e.
$(\mathrm{restrictBF}\,f\,\rho)(x) = f(\rho.\mathrm{extend}\,x)$. This statement says
that for a Boolean-valued $f : \{0,1\}^n \to \{0,1\}$, restricting its $\pm1$-encoding
agrees with encoding the restricted function: $\mathrm{restrictBF}\,(\mathrm{boolToSign}\circ f)\,\rho
= \mathrm{boolToSign}\circ(\mathrm{restrictFn}\,f\,\rho)$.
\end{definition}

n21206.content:
\begin{definition}[Membership in the free variables]
\lean{RestrictionFourier.mem_freeVars}
\label{RestrictionFourier.mem_freeVars}
\leanok
\uses{SwitchingLemma2.Restriction, SwitchingLemma2.Restriction.freeVars}

For a restriction $\rho$ and a coordinate $i$, we have $i \in \rho.\mathrm{freeVars}$ if
and only if $\rho\,i = \mathtt{none}$, i.e. exactly when $\rho$ leaves the coordinate $i$
unfixed. The companion definition $\mathrm{signProd}\,\rho\,T = \prod_{i \in T}
\mathrm{boolToSign}((\rho\,i).\mathrm{getD}\ \mathtt{false})$ collects the $\pm1$-encodings of
the bits $\rho$ fixes on a set $T$.
\end{definition}

n21207.content:
\begin{lemma}[Character through a restriction splits]
\lean{RestrictionFourier.chiS_extend}
\label{RestrictionFourier.chiS_extend}
\leanok
\uses{BooleanAnalysis.BoolCube, BooleanAnalysis.chiS, RestrictionFourier.mem_freeVars, SwitchingLemma2.Restriction, SwitchingLemma2.Restriction.extend, SwitchingLemma2.Restriction.freeVars}

For a set $U \subseteq [n]$, a restriction $\rho$ with free set $J = \rho.\mathrm{freeVars}$,
and an input $x$,
\[
  \chi_U(\rho.\mathrm{extend}\,x) \;=\; \chi_{U \cap J}(x)\cdot \mathrm{signProd}\,\rho\,(U \setminus J),
\]
so the character splits into a character in the free coordinates times a constant sign
coming from the fixed coordinates.
\end{lemma}

n21209.content:
\begin{lemma}[Sums over restrictions of per-coordinate products factor]
\lean{RestrictionFourier.sum_restriction_prod}
\label{RestrictionFourier.sum_restriction_prod}
\leanok
\uses{SwitchingLemma2.Restriction}

For any family $h : [n] \to \mathrm{Option}\ \mathrm{Bool} \to \mathbb{R}$,
\[
  \sum_{\rho} \prod_{i} h\,i\,(\rho\,i) \;=\; \prod_{i} \sum_{v} h\,i\,v,
\]
the sum ranging over all restrictions $\rho$ on $n$ variables and $v$ over the three
possible per-coordinate values.
\end{lemma}

n21210.content:
\begin{lemma}[Bernoulli-weighted products factor]
\lean{RestrictionFourier.sum_bernoulli_prod}
\label{RestrictionFourier.sum_bernoulli_prod}
\leanok
\uses{LMN.bernoulliRestrWeight_eq_prod, LMN.varWeight, RestrictionFourier.sum_restriction_prod, SwitchingLemma2.Restriction, SwitchingLemma2.bernoulliRestrWeight}

For $p \in \mathbb{R}$ and any family $h : [n] \to \mathrm{Option}\ \mathrm{Bool} \to \mathbb{R}$,
\[
  \sum_{\rho} \mathrm{bernoulliRestrWeight}\,p\,\rho \cdot \prod_{i} h\,i\,(\rho\,i)
  \;=\; \prod_{i} \sum_{v} \mathrm{varWeight}\,p\,v \cdot h\,i\,v,
\]
so the Bernoulli weight is absorbed coordinatewise into the per-variable weight
$\mathrm{varWeight}$.
\end{lemma}

n21211.content:
\begin{definition}[Per-coordinate local factor]
\lean{RestrictionFourier.localFactor}
\label{RestrictionFourier.localFactor}
\leanok
\uses{BooleanAnalysis.boolToSign}
Given sets $U, S \subseteq [n]$, a coordinate $i$ and a per-coordinate value $v$, the
local factor is $1$ if $i \in S$ and $v = \mathtt{none}$ (the coordinate must be free),
$0$ if $i \in S$ and $v$ is fixed; for $i \in U \setminus S$ it is $0$ when $v =
\mathtt{none}$ and $\mathrm{boolToSign}(b)$ when $v = \mathtt{some}\ b$; and $1$ for all
remaining coordinates. It encodes the event $U \cap \mathrm{freeVars} = S$ together with
the sign contributed on $U \setminus S$.
\end{definition}

n21212.content:
\begin{lemma}[Indicator times sign factors into local factors]
\lean{RestrictionFourier.indicator_signProd_eq_prod}
\label{RestrictionFourier.indicator_signProd_eq_prod}
\leanok
\uses{BooleanAnalysis.boolToSign, RestrictionFourier.localFactor, RestrictionFourier.mem_freeVars, SwitchingLemma2.Restriction, SwitchingLemma2.Restriction.freeVars}

If $S \subseteq U$ then for every restriction $\rho$ with free set $J$,
\[
  \mathbf{1}[U \cap J = S]\cdot \mathrm{signProd}\,\rho\,(U \setminus J)
  \;=\; \prod_{i} \mathrm{localFactor}\,U\,S\,i\,(\rho\,i),
\]
where the left-hand side is understood as $0$ when the indicator fails.
\end{lemma}

n21213.content:
\begin{lemma}[Average of one local factor]
\lean{RestrictionFourier.sum_varWeight_localFactor}
\label{RestrictionFourier.sum_varWeight_localFactor}
\leanok
\uses{BooleanAnalysis.boolToSign, LMN.varWeight, RestrictionFourier.localFactor}

For $p \in \mathbb{R}$, sets $U, S$ and a coordinate $i$,
\[
  \sum_{v} \mathrm{varWeight}\,p\,v \cdot \mathrm{localFactor}\,U\,S\,i\,v
  \;=\; \begin{cases} p & i \in S,\\ 0 & i \in U \setminus S,\\ 1 & \text{otherwise.}\end{cases}
\]
\end{lemma}

n21214.content:
\begin{lemma}[Average of a product of two local factors]
\lean{RestrictionFourier.sum_varWeight_localFactor_mul}
\label{RestrictionFourier.sum_varWeight_localFactor_mul}
\leanok
\uses{BooleanAnalysis.boolToSign, LMN.varWeight, RestrictionFourier.localFactor}

For $p \in \mathbb{R}$, sets $U, V, S$ and a coordinate $i$,
\[
  \sum_{v} \mathrm{varWeight}\,p\,v \cdot \bigl(\mathrm{localFactor}\,U\,S\,i\,v\cdot
  \mathrm{localFactor}\,V\,S\,i\,v\bigr)
  = \begin{cases} p & i \in S,\\ 1-p & i \notin S,\ i \in U \text{ and } i \in V,\\
  0 & i \notin S,\ i \in U \text{ or } i \in V,\\ 1 & \text{otherwise,}\end{cases}
\]
which is the per-coordinate average needed for the squared coefficient.
\end{lemma}

n21215.content:
\begin{lemma}[Product of a three-case indicator weight]
\lean{RestrictionFourier.prod_if_subset}
\label{RestrictionFourier.prod_if_subset}
\leanok

For $p \in \mathbb{R}$ and sets $S, U \subseteq [n]$,
\[
  \prod_{i} \bigl(p \text{ if } i \in S,\ (1-p) \text{ if } i \in U \setminus S,\ 1
  \text{ otherwise}\bigr) \;=\; p^{\left\lvert S\right\rvert}\,(1-p)^{\left\lvert U \setminus S\right\rvert}.
\]
\end{lemma}

n21216.content:
\begin{theorem}[Proposition 4.17, first identity]
\lean{RestrictionFourier.expectation_fourierCoeff_restrictBF}
\label{RestrictionFourier.expectation_fourierCoeff_restrictBF}
\leanok


\uses{BooleanAnalysis.BooleanFunc, BooleanAnalysis.fourierCoeff, RestrictionFourier.fourierCoeff_restrictBF, RestrictionFourier.indicator_signProd_eq_prod, RestrictionFourier.sum_bernoulli_prod, RestrictionFourier.sum_varWeight_localFactor, SwitchingLemma2.Restriction, SwitchingLemma2.Restriction.freeVars, SwitchingLemma2.bernoulliRestrWeight}

Under a Bernoulli($p$)-random restriction $\rho$, the expected Fourier coefficient of the
restricted function at $S$ is
\[
  \mathbb{E}_\rho\bigl[\widehat{f_\rho}(S)\bigr] \;=\; p^{\left\lvert S\right\rvert}\cdot \widehat{f}(S),
\]
the expectation being the $\mathrm{bernoulliRestrWeight}\,p$-weighted sum over all
restrictions.
\end{theorem}

n21217.content:
\begin{theorem}[Proposition 4.17, second identity]
\lean{RestrictionFourier.expectation_fourierCoeff_sq_restrictBF}
\label{RestrictionFourier.expectation_fourierCoeff_sq_restrictBF}
\leanok


\uses{BooleanAnalysis.BooleanFunc, BooleanAnalysis.fourierCoeff, RestrictionFourier.fourierCoeff_restrictBF, RestrictionFourier.indicator_signProd_eq_prod, RestrictionFourier.localFactor, RestrictionFourier.prod_if_subset, RestrictionFourier.sum_bernoulli_prod, RestrictionFourier.sum_varWeight_localFactor_mul, SwitchingLemma2.Restriction, SwitchingLemma2.Restriction.freeVars, SwitchingLemma2.bernoulliRestrWeight}

Under a Bernoulli($p$)-random restriction $\rho$, the expected squared Fourier
coefficient at $S$ is
\[
  \mathbb{E}_\rho\bigl[\widehat{f_\rho}(S)^2\bigr] \;=\; \sum_{U \supseteq S}
  p^{\left\lvert S\right\rvert}\,(1-p)^{\left\lvert U \setminus S\right\rvert}\cdot \widehat{f}(U)^2,
\]
where the sum runs over all $U \subseteq [n]$ and the terms with $S \not \subseteq U$
vanish.
\end{theorem}

n21218.content:
\begin{lemma}[The squared sign product is one]
\lean{RestrictionFourier.signProd_sq}
\label{RestrictionFourier.signProd_sq}
\leanok
\uses{BooleanAnalysis.boolToSign_sq, SwitchingLemma2.Restriction}

For every restriction $\rho$ and every set $T \subseteq [n]$, $(\mathrm{signProd}\,\rho\,T)^2 = 1$.
\end{lemma}

n21219.content:
\begin{theorem}[Proposition 4.17, probability form]
\lean{RestrictionFourier.bernoulliRestrProb_inter_freeVars}
\label{RestrictionFourier.bernoulliRestrProb_inter_freeVars}
\leanok
\uses{BooleanAnalysis.chiS, BooleanAnalysis.fourierCoeff, BooleanAnalysis.fourier_coeff_chi, RestrictionFourier.expectation_fourierCoeff_sq_restrictBF, RestrictionFourier.fourierCoeff_restrictBF, RestrictionFourier.signProd_sq, SwitchingLemma2.Restriction, SwitchingLemma2.Restriction.freeVars, SwitchingLemma2.bernoulliRestrProb}

For a Bernoulli($p$)-random restriction $\rho$ with free set $J = \rho.\mathrm{freeVars}$
and sets $U, S \subseteq [n]$,
\[
  \Pr_\rho\bigl[U \cap J = S\bigr] \;=\;
  \begin{cases} p^{\left\lvert S\right\rvert}\,(1-p)^{\left\lvert U \setminus S\right\rvert} & S \subseteq U,\\
  0 & \text{otherwise.}\end{cases}
\]
Combined with the second identity this yields O'Donnell's form
$\mathbb{E}_\rho[\widehat{f_\rho}(S)^2] = \sum_U \Pr[U \cap J = S]\cdot \widehat{f}(U)^2$.
\end{theorem}

n21220.content:
\begin{definition}[Restriction of a real-valued Boolean function]
\lean{RestrictionFourier.restrictBF}

\label{RestrictionFourier.restrictBF}
\leanok

\uses{BooleanAnalysis.BooleanFunc, SwitchingLemma2.Restriction, SwitchingLemma2.Restriction.extend}
Given $f : \{0,1\}^n \to \mathbb{R}$ and a restriction $\rho$, the restricted function
$f_\rho = \mathrm{restrictBF}\,f\,\rho$ is defined by
\[
  (\mathrm{restrictBF}\,f\,\rho)(x) \;=\; f(\rho.\mathrm{extend}\,x),
\]
so free coordinates are read from the input $x$ and fixed coordinates from $\rho$. It is
the real-valued analogue of $\mathrm{restrictFn}$.
\end{definition}

n21222.content:
\begin{definition}[The $\mathrm{AC}^0$ gate set]
\lean{ACP.AC_GateOps}
\label{ACP.AC_GateOps}
\leanok
\uses{ACP.FeedForward.GateOp.id}
The set of plain $\mathrm{AC}^0$ gate operations on the alphabet $\mathrm{Fin}\,2$: the
identity gate, the NOT gate $x \mapsto 1 - x_0$, and, for every arity $n$, the unbounded
fan-in AND gate $x \mapsto \prod_{i} x_i$.
\end{definition}

n21223.content:
\begin{lemma}[Counting tuples satisfying a pointwise predicate]
\lean{ACP.tuple_fail_count}
\label{ACP.tuple_fail_count}
\leanok

For a finite index type $\iota$, a finite type $\beta$ and a decidable predicate $P$ on
$\beta$, the number of functions $f : \iota \to \beta$ with $P(f(i))$ for all $i$ equals
$\left\lvert \{b : P(b)\}\right\rvert^{\left\lvert \iota\right\rvert}$.
\end{lemma}

n21225.content:
\begin{definition}[Booleanization of a field element]
\lean{ACP.bitify}
\label{ACP.bitify}
\leanok
The map $\mathbb{Z}/p \to \mathrm{Fin}\,2$ sending $a$ to $1$ if $a = 1$ and to $0$
otherwise. It is intended to be applied only to values lying in $\{0,1\}$.
\end{definition}

n21226.content:
\begin{lemma}[Booleanization is a section on $\{0,1\}$]
\lean{ACP.cast_bitify_eq}
\label{ACP.cast_bitify_eq}
\leanok
\uses{ACP.bitify}

If $a \in \{0,1\} \subseteq \mathbb{Z}/p$, then casting $\texttt{ACP.bitify}\,(a)$ back into
$\mathbb{Z}/p$ through $\mathbb{N}$ recovers $a$.
\end{lemma}

n21227.content:
\begin{lemma}[Fermat indicator of zero]
\lean{ACP.one_sub_pow_card_sub_one}
\label{ACP.one_sub_pow_card_sub_one}
\leanok

For every $a \in \mathbb{Z}/p$ with $p$ prime,
\[
1 - a^{p-1} = \begin{cases} 1 & \text{if } a = 0,\\ 0 & \text{otherwise.}\end{cases}
\]
\end{lemma}

n21228.content:
\begin{lemma}[Bit indicator agrees with booleanization]
\lean{ACP.bit_indicator_eq_bitify}
\label{ACP.bit_indicator_eq_bitify}
\leanok
\uses{ACP.bitify}

If $a \in \{0,1\} \subseteq \mathbb{Z}/p$, then $1 - (1-a)^{p-1}$ equals the cast of
$\texttt{ACP.bitify}\,(a)$ into $\mathbb{Z}/p$.
\end{lemma}

n21229.content:
\begin{definition}[Unbounded $\mathrm{MOD}_p$ gate]
\lean{ACP.modGateOp}
\label{ACP.modGateOp}
\leanok
The gate operation of arity \texttt{width} on Boolean inputs that outputs $1$ when the sum
of its inputs, cast into $\mathbb{Z}/p$, is $0$, and outputs $0$ otherwise.
\end{definition}

n21230.content:
\begin{definition}[{The $\mathrm{AC}^0[p]$ gate set}]
\lean{ACP.ACp_GateOps}
\label{ACP.ACp_GateOps}
\leanok
\uses{ACP.AC_GateOps, ACP.modGateOp}
The $\mathrm{AC}^0[p]$ gate set: the $\mathrm{AC}^0$ gates (identity, NOT, unbounded AND)
together with the unbounded $\mathrm{MOD}_p$ gate of every arity.
\end{definition}

n21231.content:
\begin{definition}[Randomized OR-approximating polynomial]
\lean{ACP.approxOr}
\label{ACP.approxOr}
\leanok
Given polynomials $P_1,\dots,P_{\mathrm{width}}$ over $\mathbb{Z}/p$ and a random seed
consisting of $\ell$ subsets $S_1,\dots,S_\ell$ of the input positions, the approximator is
\[
1 - \prod_{k=1}^{\ell}\Bigl(1 - \bigl(\textstyle\sum_{i \in S_k} P_i\bigr)^{p-1}\Bigr).
\]
\end{definition}

n21232.content:
\begin{definition}[Exact $\mathrm{MOD}_p$ polynomial]
\lean{ACP.exactMod}
\label{ACP.exactMod}
\leanok
The polynomial $1 - \bigl(\sum_i P_i\bigr)^{p-1}$ over $\mathbb{Z}/p$, which computes the
$\mathrm{MOD}_p$ predicate exactly on Boolean values.
\end{definition}

n21233.content:
\begin{definition}[Value-level OR approximator]
\lean{ACP.approxOr_val}
\label{ACP.approxOr_val}
\leanok
The value-level analogue of the randomized OR approximator: for $v : \mathrm{Fin}\,
\mathrm{width} \to \mathbb{Z}/p$ and subsets $S_1,\dots,S_\ell$,
\[
1 - \prod_{k}\Bigl(1 - \bigl(\textstyle\sum_{i \in S_k} v_i\bigr)^{p-1}\Bigr).
\]
\end{definition}

n21234.content:
\begin{definition}[Value-level OR detector]
\lean{ACP.OR_val}
\label{ACP.OR_val}
\leanok
For $v : \mathrm{Fin}\,\mathrm{width} \to \mathbb{Z}/p$, the quantity
$1 - \prod_{k}\bigl(1 - v_k^{\,p-1}\bigr)$, which detects whether some coordinate of $v$ is
nonzero.
\end{definition}

n21235.content:
\begin{theorem}[Degree bound for the OR approximator]
\lean{ACP.approxOr_totalDegree}
\label{ACP.approxOr_totalDegree}
\leanok
\uses{ACP.approxOr}

The total degree of $\texttt{ACP.approxOr}$ applied to $P_1,\dots,P_{\mathrm{width}}$ and a
seed $S$ is at most $(p-1)\,\ell \cdot \sup_i \deg(P_i)$.
\end{theorem}

n21236.content:
\begin{theorem}[Degree bound for the exact $\mathrm{MOD}_p$ polynomial]
\lean{ACP.exactMod_totalDegree}
\label{ACP.exactMod_totalDegree}
\leanok
\uses{ACP.exactMod}

The total degree of $\texttt{ACP.exactMod}$ applied to $P_1,\dots,P_{\mathrm{width}}$ is at
most $(p-1)\cdot \sup_i \deg(P_i)$.
\end{theorem}

n21237.content:
\begin{lemma}[Half the subsets miss a nonzero vector]
\lean{ACP.subset_sum_zero_bound}
\label{ACP.subset_sum_zero_bound}
\leanok

For a nonzero vector $v : \mathrm{Fin}\,n \to \mathbb{Z}/p$, the number of subsets
$s \subseteq \mathrm{Fin}\,n$ with $\sum_{i \in s} v_i = 0$ is at most half of all $2^n$
subsets; formally, twice that count is at most the total number of subsets.
\end{lemma}

n21238.content:
\begin{lemma}[Evaluation commutes with the OR approximator]
\lean{ACP.approxOr_eval_eq}
\label{ACP.approxOr_eval_eq}
\leanok
\uses{ACP.approxOr, ACP.approxOr_val}

Evaluating $\texttt{ACP.approxOr}\,(P, S)$ at a point $y$ gives the same result as applying
the value-level approximator $\texttt{ACP.approxOr\_val}$ to the evaluated inputs
$i \mapsto P_i(y)$ with the same seed $S$.
\end{lemma}

n21239.content:
\begin{lemma}[Characterization of approximator failure]
\lean{ACP.approxOr_failure_iff}
\label{ACP.approxOr_failure_iff}
\leanok
\uses{ACP.OR_val, ACP.approxOr_val, ACP.one_sub_pow_card_sub_one}

For $v : \mathrm{Fin}\,\mathrm{width} \to \mathbb{Z}/p$ and a seed $S$, the value-level
approximator differs from the OR detector if and only if $v \ne 0$ and every seed subset has
vanishing sum, i.e.\ $\sum_{i \in S_k} v_i = 0$ for all $k$.
\end{lemma}

n21240.content:
\begin{lemma}[Bad-seed count for a nonzero input]
\lean{ACP.count_bad_S}
\label{ACP.count_bad_S}
\leanok
\uses{ACP.OR_val, ACP.approxOr_failure_iff, ACP.approxOr_val}

For a nonzero $v$, the number of seeds $S : \mathrm{Fin}\,\ell \to \mathrm{Finset}
(\mathrm{Fin}\,\mathrm{width})$ on which the value-level approximator disagrees with the OR
detector, multiplied by $2^\ell$, is at most the total number of seeds.
\end{lemma}

n21241.content:
\begin{lemma}[Number of random seeds]
\lean{ACP.approxSeed_card}
\label{ACP.approxSeed_card}
\leanok

The type of seeds $\mathrm{Fin}\,\ell \to \mathrm{Finset}(\mathrm{Fin}\,\mathrm{width})$,
i.e.\ $\ell$ independent subset choices, has cardinality $2^{\mathrm{width}\cdot \ell}$.
\end{lemma}

n21242.content:
\begin{lemma}[Bad-seed bound for every input]
\lean{ACP.count_bad_S_or}
\label{ACP.count_bad_S_or}
\leanok
\uses{ACP.OR_val, ACP.approxOr_failure_iff, ACP.approxOr_val, ACP.count_bad_S}

Without any nonvanishing hypothesis on $v$: the number of seeds on which the value-level
approximator disagrees with the OR detector, multiplied by $2^\ell$, is at most the total
number of seeds.
\end{lemma}

n21243.content:
\begin{definition}[List of OR-approximating polynomials]
\lean{ACP.approxOrPolyList}
\label{ACP.approxOrPolyList}
\leanok
\uses{ACP.approxOr}
The list of all polynomials $\texttt{ACP.approxOr}\,(P,S)$, one entry per random seed $S$. It
is a list rather than a set, so a polynomial arising from several seeds appears with the
corresponding multiplicity.
\end{definition}

n21244.content:
\begin{lemma}[Length of the OR polynomial list]
\lean{ACP.approxOrPolyList_length}
\label{ACP.approxOrPolyList_length}
\leanok
\uses{ACP.approxOrPolyList, ACP.approxSeed_card}

The list $\texttt{ACP.approxOrPolyList}$ has length $2^{\mathrm{width}\cdot\ell}$.
\end{lemma}

n21245.content:
\begin{theorem}[Pointwise bad-seed count for OR]
\lean{ACP.approxOr_pointwise_bad_count}
\label{ACP.approxOr_pointwise_bad_count}
\leanok
\uses{ACP.OR_val, ACP.approxOr, ACP.approxOr_eval_eq, ACP.approxSeed_card, ACP.count_bad_S_or}

Fix an evaluation point $y$. The number of seeds $S$ for which
$\texttt{ACP.approxOr}\,(P,S)$ evaluated at $y$ differs from
$1 - \prod_k \bigl(1 - P_k(y)^{p-1}\bigr)$, multiplied by $2^\ell$, is at most
$2^{\mathrm{width}\cdot\ell}$; that is, at most a $2^{-\ell}$ fraction of seeds fail at $y$.
\end{theorem}

n21246.content:
\begin{theorem}[Good OR approximators exist as a distribution]
\lean{ACP.exists_good_approxOr}
\label{ACP.exists_good_approxOr}
\leanok
\uses{ACP.approxOr, ACP.approxOrPolyList, ACP.approxOrPolyList_length, ACP.approxOr_pointwise_bad_count, ACP.approxOr_totalDegree}

There is a list $Ps$ of polynomials, namely $\texttt{ACP.approxOrPolyList}\,(P)$, of length
$2^{\mathrm{width}\cdot\ell}$, every entry of which has total degree at most
$(p-1)\ell\cdot\sup_i \deg(P_i)$, and such that for every evaluation point $y$ the number of
seeds failing to compute the OR value at $y$, times $2^\ell$, is at most the length of $Ps$.
\end{theorem}

n21247.content:
\begin{definition}[Randomized AND-approximating polynomial]
\lean{ACP.approxAnd}
\label{ACP.approxAnd}
\leanok
\uses{ACP.approxOr}
The De Morgan dual of the OR approximator: $1 - \texttt{ACP.approxOr}\,(1 - P, S)$, where the
approximator is applied to the negated inputs $i \mapsto 1 - P_i$.
\end{definition}

n21248.content:
\begin{theorem}[Degree bound for the AND approximator]
\lean{ACP.approxAnd_totalDegree}
\label{ACP.approxAnd_totalDegree}
\leanok
\uses{ACP.approxAnd, ACP.approxOr_totalDegree}

The total degree of $\texttt{ACP.approxAnd}\,(P,S)$ is at most
$(p-1)\,\ell\cdot\sup_i \deg(P_i)$, the same bound as for the OR approximator.
\end{theorem}

n21249.content:
\begin{definition}[List of AND-approximating polynomials]
\lean{ACP.approxAndPolyList}
\label{ACP.approxAndPolyList}
\leanok
\uses{ACP.approxAnd}
The list of all polynomials $\texttt{ACP.approxAnd}\,(P,S)$, one entry per random seed $S$.
\end{definition}

n21250.content:
\begin{lemma}[Length of the AND polynomial list]
\lean{ACP.approxAndPolyList_length}
\label{ACP.approxAndPolyList_length}
\leanok
\uses{ACP.approxAndPolyList, ACP.approxSeed_card}

The list $\texttt{ACP.approxAndPolyList}$ has length $2^{\mathrm{width}\cdot\ell}$.
\end{lemma}

n21251.content:
\begin{theorem}[Pointwise bad-seed count for AND]
\lean{ACP.approxAnd_pointwise_bad_count}
\label{ACP.approxAnd_pointwise_bad_count}
\leanok
\uses{ACP.approxAnd, ACP.approxOr, ACP.approxOr_pointwise_bad_count}

Fix an evaluation point $y$. The number of seeds $S$ for which
$\texttt{ACP.approxAnd}\,(P,S)$ evaluated at $y$ differs from
$\prod_k \bigl(1 - (1 - P_k(y))^{p-1}\bigr)$, multiplied by $2^\ell$, is at most
$2^{\mathrm{width}\cdot\ell}$.
\end{theorem}

n21252.content:
\begin{theorem}[Good AND approximators exist as a distribution]
\lean{ACP.exists_good_approxAnd}
\label{ACP.exists_good_approxAnd}
\leanok
\uses{ACP.approxAnd, ACP.approxAndPolyList, ACP.approxAndPolyList_length, ACP.approxAnd_pointwise_bad_count, ACP.approxAnd_totalDegree}

There is a list $Ps$ of polynomials, namely $\texttt{ACP.approxAndPolyList}\,(P)$, of length
$2^{\mathrm{width}\cdot\ell}$, every entry of which has total degree at most
$(p-1)\ell\cdot\sup_i \deg(P_i)$, and such that for every evaluation point $y$ the number of
