\end{theorem}

n21253.content:
\begin{lemma}[{Case analysis on $\mathrm{AC}^0[p]$ gates}]
\lean{ACP.ACp_GateOps_cases}
\label{ACP.ACp_GateOps_cases}
\leanok
\uses{ACP.AC_GateOps, ACP.ACp_GateOps, ACP.FeedForward.GateOp.id, ACP.modGateOp}

Every gate operation in $\texttt{ACP.ACp\_GateOps}$ is one of the following: the identity gate
on a single input, the NOT gate $x \mapsto 1 - x_0$, an unbounded AND gate
$x \mapsto \prod_i x_i$ of some arity $n$, or a $\texttt{ACP.modGateOp}$ of some arity $n$.
\end{lemma}

n21254.content:
\begin{lemma}[Exact $\mathrm{MOD}_p$ on Boolean inputs]
\lean{ACP.exactMod_on_bits}
\label{ACP.exactMod_on_bits}
\leanok
\uses{ACP.bitify, ACP.cast_bitify_eq, ACP.modGateOp, ACP.one_sub_pow_card_sub_one}

If all values $\mathrm{inputs}_i$ lie in $\{0,1\} \subseteq \mathbb{Z}/p$, then
$1 - \bigl(\sum_i \mathrm{inputs}_i\bigr)^{p-1}$ equals the cast into $\mathbb{Z}/p$ of the
output of the $\mathrm{MOD}_p$ gate applied to the booleanized inputs
$i \mapsto \texttt{ACP.bitify}\,(\mathrm{inputs}_i)$.
\end{lemma}

n21255.content:
\begin{lemma}[Exact AND on Boolean inputs]
\lean{ACP.exactAnd_on_bits}
\label{ACP.exactAnd_on_bits}
\leanok
\uses{ACP.bitify}

If all values $\mathrm{inputs}_i$ lie in $\{0,1\} \subseteq \mathbb{Z}/p$, then
$\prod_i \bigl(1 - (1 - \mathrm{inputs}_i)^{p-1}\bigr)$ equals the cast into $\mathbb{Z}/p$
of $\prod_i \texttt{ACP.bitify}\,(\mathrm{inputs}_i)$, the Boolean AND of the booleanized
inputs.
\end{lemma}

n21257.content:
\begin{definition}[Boolean input cast to the prime field]
\lean{ACP.boolInput}
\label{ACP.boolInput}
\leanok
For a Boolean input $x : \mathrm{Fin}\,n \to \mathrm{Fin}\,2$, the map
$\mathrm{boolInput}_p(x)$ sends each coordinate $i$ to the image of the natural number $x_i$ in
$\mathbb{Z}/p$.
\end{definition}

n21258.content:
\begin{definition}[Field value of a bit]
\lean{ACP.boolVal}
\label{ACP.boolVal}
\leanok
The value in $\mathbb{Z}/p$ represented by a bit $b : \mathrm{Fin}\,2$, namely the image of the natural
number $b$ under the canonical map $\mathbb{N}\to \mathbb{Z}/p$.
\end{definition}

n21259.content:
\begin{lemma}[Bit values are $0$ or $1$]
\lean{ACP.boolVal_mem}
\label{ACP.boolVal_mem}
\leanok
\uses{ACP.boolVal}

For every bit $b : \mathrm{Fin}\,2$ the element $\mathrm{boolVal}_p(b)$ lies in the subset
$\{0,1\}$ of $\mathbb{Z}/p$.
\end{lemma}

n21260.content:
\begin{lemma}[Bitification inverts \texttt{boolVal}]
\lean{ACP.bitify_boolVal}
\label{ACP.bitify_boolVal}
\leanok
\uses{ACP.bitify, ACP.boolVal}

Applying $\mathrm{bitify}_p$ to $\mathrm{boolVal}_p(b)$ returns the original bit $b$, for every
$b : \mathrm{Fin}\,2$.
\end{lemma}

n21261.content:
\begin{lemma}[One-step unfolding of node evaluation]
\lean{ACP.evalNode_succ_eq}
\label{ACP.evalNode_succ_eq}
\leanok
\uses{ACP.FeedForward, ACP.FeedForward.evalNode}

For a feed-forward circuit $F$, a layer index $d$, a node $u$ at layer $d+1$ and an input $x$, the
value of $u$ is obtained by applying the gate operation attached to $u$ to the values of its input
nodes at layer $d$.
\end{lemma}

n21262.content:
\begin{definition}[Degree target after $d$ layers]
\lean{ACP.circuitDegreeBound}
\label{ACP.circuitDegreeBound}
\leanok
The degree budget for the approximating polynomials after $d$ layers, defined as
\[
\mathrm{circuitDegreeBound}(p,\ell,d) = \bigl((p-1)\ell\bigr)^{d}.
\]
\end{definition}

n21263.content:
\begin{definition}[Gate count in the first $d$ layers]
\lean{ACP.gateCountBefore}
\label{ACP.gateCountBefore}
\leanok
\uses{ACP.FeedForward}
For a circuit $F$ with finite node sets, $\mathrm{gateCountBefore}\,F\,d$ counts the non-input gates
in layers $1,\dots,d$: it is $0$ for $d = 0$ and, recursively, the count for $d$ plus the number of
nodes at layer $d+1$.
\end{definition}

n21264.content:
\begin{lemma}[Gate count at layer zero]
\lean{ACP.gateCountBefore_zero}
\label{ACP.gateCountBefore_zero}
\leanok
\uses{ACP.FeedForward, ACP.gateCountBefore}

$\mathrm{gateCountBefore}\,F\,0 = 0$: the input layer contributes no gates.
\end{lemma}

n21265.content:
\begin{lemma}[Gate count recursion]
\lean{ACP.gateCountBefore_succ}
\label{ACP.gateCountBefore_succ}
\leanok
\uses{ACP.FeedForward, ACP.gateCountBefore}

$\mathrm{gateCountBefore}\,F\,(d+1)$ equals $\mathrm{gateCountBefore}\,F\,d$ plus the cardinality of
the node set at layer $d+1$.
\end{lemma}

n21266.content:
\begin{lemma}[Cardinality of a product filtered on the left factor]
\lean{ACP.prod_left_filter_card}
\label{ACP.prod_left_filter_card}
\leanok

For finite types $\alpha,\beta$ and a decidable predicate $P$ on $\alpha$, the number of pairs
$z \in \alpha \times \beta$ with $P(z_1)$ equals $\left\lvert \{a : P(a)\}\right\rvert \cdot \left\lvert \beta\right\rvert$.
\end{lemma}

n21267.content:
\begin{lemma}[Fiberwise product counting]
\lean{ACP.prod_filter_fiber_mul_le}
\label{ACP.prod_filter_fiber_mul_le}
\leanok

Let $P$ be a predicate on $\alpha$, $Q$ a predicate on $\alpha \times \beta$, and $C, B$ natural
numbers such that for every $a$ with $P(a)$ the fiber count satisfies
$\left\lvert \{b : Q(a,b)\}\right\rvert \cdot C \le B$.  Then
\[
\left\lvert \{z \in \alpha\times\beta : P(z_1) \wedge Q(z_1,z_2)\}\right\rvert \cdot C \;\le\;
\left\lvert \{a : P(a)\}\right\rvert \cdot B .
\]
\end{lemma}

n21269.content:
\begin{lemma}[Counting functions bad at one coordinate]
\lean{ACP.pi_coordinate_bad_mul_le}
\label{ACP.pi_coordinate_bad_mul_le}
\leanok
\uses{ACP.piEquivAt}

Fix a coordinate $i$ and a decidable predicate $\mathrm{Bad}$ on $\beta_i$, and suppose
$\left\lvert \{b : \mathrm{Bad}(b)\}\right\rvert \cdot C \le \left\lvert \beta_i\right\rvert$.  Then the number of dependent functions
$f$ with $\mathrm{Bad}(f_i)$ satisfies
\[
\left\lvert \{f : \mathrm{Bad}(f_i)\}\right\rvert \cdot C \;\le\; \left\lvert (j : \iota) \to \beta_j\right\rvert.
\]
\end{lemma}

n21270.content:
\begin{lemma}[Union bound over coordinates of a dependent product]
\lean{ACP.pi_exists_bad_card_mul_le}
\label{ACP.pi_exists_bad_card_mul_le}
\leanok
\uses{ACP.pi_coordinate_bad_mul_le}

Given for each coordinate $i$ a decidable predicate $\mathrm{Bad}_i$ on $\beta_i$ with
$\left\lvert \{b : \mathrm{Bad}_i(b)\}\right\rvert \cdot C \le \left\lvert \beta_i\right\rvert$, the number of dependent functions bad
at some coordinate obeys
\[
\left\lvert \{f : \exists i,\ \mathrm{Bad}_i(f_i)\}\right\rvert \cdot C \;\le\; \left\lvert \iota\right\rvert \cdot \left\lvert (i : \iota) \to \beta_i\right\rvert.
\]
\end{lemma}

n21271.content:
\begin{lemma}[Filtering commutes with mapping, on lengths]
\lean{ACP.list_filter_map_length}
\label{ACP.list_filter_map_length}
\leanok

For a list $l$, a map $f$ and a decidable predicate $P$, the length of the filter of $l.\mathrm{map}\,f$
by $P$ equals the length of the filter of $l$ by the pulled-back predicate $a \mapsto P(f(a))$.
\end{lemma}

n21272.content:
\begin{lemma}[Finset list preserves filtered cardinality]
\lean{ACP.finset_toList_filter_length_eq_card}
\label{ACP.finset_toList_filter_length_eq_card}
\leanok

For a finset $s$ and a decidable predicate $q$, the length of the filtered list
$s.\mathrm{toList}$ by $q$ equals the cardinality of the filtered finset $s$ by $q$.
\end{lemma}

n21273.content:
\begin{definition}[Gate approximator family]
\lean{ACP.GatePolyFamily}
\label{ACP.GatePolyFamily}
\leanok
\uses{ACP.bitify, ACP.boolInput}
A \texttt{GatePolyFamily} for a gate operation $\mathrm{op}$ packages a nonempty finite seed type
together with, for each tuple of incoming polynomials and each seed, an approximating polynomial in
$n$ variables over $\mathbb{Z}/p$ subject to two guarantees: its total degree is at most
$(p-1)\ell \cdot \sup_i \deg(\text{polys}_i)$, and for every Boolean input $x$ at which all incoming
polynomials evaluate into $\{0,1\}$, the number of seeds on which the approximator disagrees with
the true gate value, multiplied by $2^{\ell}$, is at most the number of seeds.  Crucially the seed
type depends only on the gate, not on the incoming polynomials.
\end{definition}

n21274.content:
\begin{lemma}[Existence of a gate approximator family]
\lean{ACP.exists_gate_poly_family}
\label{ACP.exists_gate_poly_family}
\leanok
\uses{ACP.ACp_GateOps, ACP.ACp_GateOps_cases, ACP.GatePolyFamily, ACP.approxAnd, ACP.approxAnd_pointwise_bad_count, ACP.approxAnd_totalDegree, ACP.approxSeed_card, ACP.bitify, ACP.boolInput, ACP.cast_bitify_eq, ACP.exactAnd_on_bits, ACP.exactMod, ACP.exactMod_on_bits, ACP.exactMod_totalDegree, ACP.modGateOp}

For every $n$, every error parameter $\ell$, and every gate operation $\mathrm{op}$ belonging to the
$\mathrm{AC}^0[p]$ gate set, there exists a \texttt{GatePolyFamily} $p\,n\,\ell\,\mathrm{op}$.
\end{lemma}

n21275.content:
\begin{definition}[Chosen gate approximator family]
\lean{ACP.gatePolyFamily}
\label{ACP.gatePolyFamily}
\leanok
\uses{ACP.ACp_GateOps, ACP.GatePolyFamily, ACP.exists_gate_poly_family}
A choice of \texttt{GatePolyFamily} for each $\mathrm{AC}^0[p]$ gate operation, obtained from the
preceding existence statement.
\end{definition}

n21276.content:
\begin{definition}[Layer polynomial family]
\lean{ACP.LayerPolyFamily}
\label{ACP.LayerPolyFamily}
\leanok
\uses{ACP.FeedForward, ACP.FeedForward.evalNode, ACP.boolInput, ACP.circuitDegreeBound, ACP.gateCountBefore}
A \texttt{LayerPolyFamily} for a circuit $F$ at layer $d$ consists of a nonempty finite seed type and,
for each seed, a polynomial for every node of layer $d$, such that each polynomial has total degree at
most $\mathrm{circuitDegreeBound}(p,\ell,d)$ and, for every Boolean input $x$, the number of seeds
for which some layer-$d$ node is mispredicted, multiplied by $2^{\ell}$, is at most
$\mathrm{gateCountBefore}\,F\,d$ times the number of seeds.
\end{definition}

n21277.content:
\begin{definition}[Input layer family]
\lean{ACP.inputLayerFamily}
\label{ACP.inputLayerFamily}
\leanok
\uses{ACP.FeedForward, ACP.FeedForward.evalNode, ACP.LayerPolyFamily, ACP.boolInput, ACP.circuitDegreeBound, ACP.gateCountBefore}
The \texttt{LayerPolyFamily} at layer $0$: a single seed, with each input node represented exactly by
the corresponding variable $X_i$, so that no seed is ever bad.
\end{definition}

n21278.content:
\begin{definition}[Inductive layer step]
\lean{ACP.stepLayerFamily}
\label{ACP.stepLayerFamily}
\leanok
\uses{ACP.ACp_GateOps, ACP.FeedForward, ACP.FeedForward.evalNode, ACP.FeedForward.onlyUsesGates, ACP.GatePolyFamily, ACP.LayerPolyFamily, ACP.bitify, ACP.bitify_boolVal, ACP.boolInput, ACP.boolVal_mem, ACP.circuitDegreeBound, ACP.evalNode_succ_eq, ACP.gateCountBefore, ACP.gatePolyFamily, ACP.pi_exists_bad_card_mul_le, ACP.prod_filter_fiber_mul_le, ACP.prod_left_filter_card}
Given a circuit $F$ using only $\mathrm{AC}^0[p]$ gates and a \texttt{LayerPolyFamily} at layer $d$,
this produces a \texttt{LayerPolyFamily} at layer $d+1$.  Its seed type is the product of the previous
seed type with one gate seed per node of layer $d+1$, and each node polynomial is the gate
approximator applied to the layer-$d$ polynomials of its inputs.
\end{definition}

n21279.content:
\begin{definition}[Layer family built by recursion on depth]
\lean{ACP.buildLayerFamily}
\label{ACP.buildLayerFamily}
\leanok
\uses{ACP.ACp_GateOps, ACP.FeedForward, ACP.FeedForward.onlyUsesGates, ACP.LayerPolyFamily, ACP.inputLayerFamily, ACP.stepLayerFamily}
For a circuit using only $\mathrm{AC}^0[p]$ gates, the \texttt{LayerPolyFamily} at any layer
$d \le F.\mathrm{depth}$, obtained by starting from the input layer family and iterating the layer
step $d$ times.
\end{definition}

n21280.content:
\begin{theorem}[Polynomial distribution for all output nodes]
\lean{ACP.exists_poly_distribution_for_circuit_outputs}
\label{ACP.exists_poly_distribution_for_circuit_outputs}
\leanok
\uses{ACP.ACp_GateOps, ACP.FeedForward, ACP.FeedForward.eval, ACP.FeedForward.evalNode, ACP.FeedForward.onlyUsesGates, ACP.boolInput, ACP.buildLayerFamily, ACP.circuitDegreeBound, ACP.gateCountBefore}

Let $F$ be a feed-forward circuit over $\mathrm{Fin}\,2$ with finite node sets, finite output type
$\mathrm{out}$, using only $\mathrm{AC}^0[p]$ gates, and let $\ell$ be an error parameter.  Then there
is a nonempty finite seed type and a family $P$ of polynomials $P(s,o)$ over $\mathbb{Z}/p$ such that every
$P(s,o)$ has total degree at most $\mathrm{circuitDegreeBound}(p,\ell,F.\mathrm{depth})$ and, for each
Boolean input $x$,
\[
\left\lvert \{s : \exists o,\ P(s,o)(\mathrm{boolInput}_p\,x) \ne F.\mathrm{eval}\,x\,o\}\right\rvert \cdot 2^{\ell}
\;\le\; \mathrm{gateCountBefore}\,F\,F.\mathrm{depth} \cdot \left\lvert \mathrm{Seed}\right\rvert.
\]
\end{theorem}

n21281.content:
\begin{theorem}[Polynomial distribution for a single-output circuit]
\lean{ACP.exists_poly_distribution_for_circuit_one}
\label{ACP.exists_poly_distribution_for_circuit_one}
\leanok
\uses{ACP.ACp_GateOps, ACP.FeedForward, ACP.FeedForward.eval, ACP.FeedForward.evalNode, ACP.FeedForward.eval₁, ACP.FeedForward.onlyUsesGates, ACP.boolInput, ACP.buildLayerFamily, ACP.circuitDegreeBound, ACP.gateCountBefore}

The same statement for a circuit with a unique output node: there is a nonempty finite seed type and
polynomials $P(s)$ of total degree at most $\mathrm{circuitDegreeBound}(p,\ell,F.\mathrm{depth})$ such
that for every Boolean input $x$,
\[
\left\lvert \{s : P(s)(\mathrm{boolInput}_p\,x) \ne F.\mathrm{eval}_1\,x\}\right\rvert \cdot 2^{\ell}
\;\le\; \mathrm{gateCountBefore}\,F\,F.\mathrm{depth} \cdot \left\lvert \mathrm{Seed}\right\rvert.
\]
\end{theorem}

n21282.content:
\begin{theorem}[List form of the single-output distribution]
\lean{ACP.exists_poly_list_for_circuit_one}
\label{ACP.exists_poly_list_for_circuit_one}
\leanok
\uses{ACP.ACp_GateOps, ACP.FeedForward, ACP.FeedForward.eval₁, ACP.FeedForward.onlyUsesGates, ACP.boolInput, ACP.circuitDegreeBound, ACP.exists_poly_distribution_for_circuit_one, ACP.finset_toList_filter_length_eq_card, ACP.gateCountBefore, ACP.list_filter_map_length}

The single-output theorem restated with the seed distribution presented as a nonempty list $Ps$ of
polynomials with multiplicity, one entry per seed: every $P \in Ps$ has total degree at most
$\mathrm{circuitDegreeBound}(p,\ell,F.\mathrm{depth})$, and for every Boolean input $x$ the number of
entries of $Ps$ disagreeing with $F.\mathrm{eval}_1\,x$, multiplied by $2^{\ell}$, is at most
$\mathrm{gateCountBefore}\,F\,F.\mathrm{depth} \cdot \left\lvert Ps\right\rvert$.
\end{theorem}

n21283.content:
\begin{definition}[Index of a non-input layer]
\lean{ACP.gateLayerIdx}
\label{ACP.gateLayerIdx}
\leanok
\uses{ACP.FeedForward}
For a feed-forward circuit $F$, a bound $d \le F.\mathrm{depth}$ and an index
$j : \mathrm{Fin}\,d$, the layer index $\mathrm{gateLayerIdx}\,F\,h_d\,j \in
\mathrm{Fin}(F.\mathrm{depth}+1)$ is $j+1$, i.e.\ the $(j+1)$-st node layer of $F$.  It packages the
non-input layers $1, \dots, d$ as indices into $F.\mathrm{nodes}$ so that they can be summed over.
\end{definition}

n21285.content:
\begin{lemma}[Circuit size as a sum of layer cardinalities]
\lean{ACP.size_eq_sum_cards}
\label{ACP.size_eq_sum_cards}
\leanok
\uses{ACP.FeedForward, ACP.FeedForward.size}

For a feed-forward circuit $F$ with all node layers finite,
\[
F.\mathrm{size} \;=\; \sum_{d : \mathrm{Fin}\,F.\mathrm{depth}} \left\lvert F.\mathrm{nodes}(d+1)\right\rvert,
\]
so the total number of non-input gates equals the sum of the cardinalities of all non-input layers.
\end{lemma}

n21286.content:
\begin{lemma}[Full-depth gate count is the circuit size]
\lean{ACP.gateCountBefore_depth_eq_size}
\label{ACP.gateCountBefore_depth_eq_size}
\leanok
\uses{ACP.FeedForward, ACP.FeedForward.size, ACP.gateCountBefore, ACP.gateCountBefore_eq_sum_cards, ACP.gateLayerIdx, ACP.size_eq_sum_cards}

For a feed-forward circuit $F$ with all node layers finite, taking $d = F.\mathrm{depth}$ gives
\[
\mathrm{gateCountBefore}\,F\,F.\mathrm{depth} \;=\; F.\mathrm{size}.
\]
\end{lemma}

n21288.content:
\begin{theorem}[Polynomial distribution for a single output, size form]
\lean{ACP.exists_poly_distribution_for_circuit_one_size}
\label{ACP.exists_poly_distribution_for_circuit_one_size}
\leanok
\uses{ACP.ACp_GateOps, ACP.FeedForward, ACP.FeedForward.eval₁, ACP.FeedForward.onlyUsesGates, ACP.FeedForward.size, ACP.boolInput, ACP.circuitDegreeBound, ACP.exists_poly_distribution_for_circuit_one, ACP.gateCountBefore_depth_eq_size}

Same statement for a circuit with a unique output node: there exist a finite nonempty seed type
$\mathrm{Seed}$ and polynomials $P : \mathrm{Seed} \to \mathbb{Z}/p[X_1,\dots,X_n]$, each of total degree
at most $\mathrm{circuitDegreeBound}\,p\,\ell\,F.\mathrm{depth}$, such that for every Boolean input
$x$ the number of seeds $s$ with
$P_s(\mathrm{boolInput}_p(x)) \ne F.\mathrm{eval}_1(x)$ obeys
\[
\left\lvert \{s : \text{$s$ is bad for $x$}\}\right\rvert \cdot 2^{\ell}
  \;\le\; F.\mathrm{size} \cdot \left\lvert \mathrm{Seed}\right\rvert.
\]
\end{theorem}

n21289.content:
\begin{theorem}[Polynomial list for a single output, size form]
\lean{ACP.exists_poly_list_for_circuit_one_size}
\label{ACP.exists_poly_list_for_circuit_one_size}
\leanok
\uses{ACP.ACp_GateOps, ACP.FeedForward, ACP.FeedForward.eval₁, ACP.FeedForward.onlyUsesGates, ACP.FeedForward.size, ACP.boolInput, ACP.circuitDegreeBound, ACP.exists_poly_list_for_circuit_one, ACP.gateCountBefore_depth_eq_size}

The list formulation of the previous theorem: for a circuit $F$ with a unique output node whose
gates all lie in the $\mathrm{AC}^0[p]$ gate set, there is a nonempty list $Ps$ of polynomials in
$\mathbb{Z}/p[X_1,\dots,X_n]$, each of total degree at most
$\mathrm{circuitDegreeBound}\,p\,\ell\,F.\mathrm{depth}$, such that for every Boolean input $x$ the
sublist of $P \in Ps$ with $P(\mathrm{boolInput}_p(x)) \ne F.\mathrm{eval}_1(x)$ satisfies
\[
\left\lvert \{P \in Ps : \text{$P$ is wrong at $x$}\}\right\rvert \cdot 2^{\ell}
  \;\le\; F.\mathrm{size} \cdot \left\lvert Ps\right\rvert.
\]
\end{theorem}

n21290.content:
\begin{definition}[Gate with input wiring]
\lean{ACP.Gate}
\label{ACP.Gate}
\leanok
A gate over alphabet $\alpha$ with input domain \texttt{domain} consists of a gate
operation \texttt{op} (an arity type $\iota$ together with a function
$(\iota \to \alpha) \to \alpha$) and a wiring map $\iota \to \texttt{domain}$ that
assigns to each input slot the node it reads from.
\end{definition}

n21291.content:
\begin{definition}[Layered feedforward circuit]
\lean{ACP.FeedForward}
\label{ACP.FeedForward}
\leanok
\uses{ACP.Gate}
A feedforward circuit from \texttt{inp} to \texttt{out} over $\alpha$ consists of a
depth $d \in \mathbb{N}$, a family of node types indexed by the layers
$\mathrm{Fin}\,(d+1)$, and, for every layer $i < d$, a gate for each node of layer
$i+1$ whose inputs are wired to nodes of layer $i$. Layer $0$ is required to be the
input type \texttt{inp} and the last layer the output type \texttt{out}.
\end{definition}

n21292.content:
\begin{definition}[Identity gate operation]
\lean{ACP.FeedForward.GateOp.id}
\label{ACP.FeedForward.GateOp.id}
\leanok
The gate operation of arity $\mathrm{PUnit}$ that returns its single input
unchanged.
\end{definition}

n21293.content:
\begin{definition}[Evaluation of a single gate]
\lean{ACP.FeedForward.Gate.eval}
\label{ACP.FeedForward.Gate.eval}
\leanok
\uses{ACP.Gate}
Given a gate $g$ and an assignment $xs$ of values to the nodes of its input domain,
the value of $g$ is $g.\texttt{op}.\texttt{func}\,(xs \circ g.\texttt{inputs})$, i.e.\
the gate operation applied to the values read along the input wires.
\end{definition}

n21294.content:
\begin{definition}[Evaluation of a node]
\lean{ACP.FeedForward.evalNode}
\label{ACP.FeedForward.evalNode}
\leanok
\uses{ACP.FeedForward.Gate.eval}
For an input assignment $xs : \texttt{inp} \to \alpha$, the value of a node at layer
$d$ is defined by recursion on $d$: a layer-$0$ node is read off directly from $xs$,
and a node at layer $n+1$ evaluates its gate on the values of the layer-$n$ nodes.
\end{definition}

n21295.content:
\begin{definition}[Evaluation of a circuit]
\lean{ACP.FeedForward.eval}
\label{ACP.FeedForward.eval}
\leanok
\uses{ACP.FeedForward.evalNode}
The function $\texttt{out} \to \alpha$ sending each output node to its value in the
last layer under the input assignment $xs$.
\end{definition}

n21296.content:
\begin{definition}[Evaluation with a unique output]
\lean{ACP.FeedForward.eval₁}
\label{ACP.FeedForward.eval₁}
\leanok
\uses{ACP.FeedForward.eval}
When the output type is a \texttt{Unique} type, the single value
$F.\texttt{eval}\,xs\,\texttt{default} \in \alpha$ computed by the circuit.
\end{definition}

n21297.content:
\begin{definition}[Size of a feedforward circuit]
\lean{ACP.FeedForward.size}
\label{ACP.FeedForward.size}
\leanok
The size of $F$ is the cardinality $\mathrm{Nat.card}$ of the sigma type of all
non-input nodes, i.e.\ the total number of nodes lying in layers $1,\dots,\texttt{depth}$.
\end{definition}

n21298.content:
\begin{definition}[Finiteness of all layers]
\lean{ACP.FeedForward.Finite}
\label{ACP.FeedForward.Finite}
\leanok
The proposition that the node type of every layer $i$ is finite.
\end{definition}

n21299.content:
\begin{definition}[Restriction to a gate set]
\lean{ACP.FeedForward.onlyUsesGates}
\label{ACP.FeedForward.onlyUsesGates}
\leanok
For a set $S$ of gate operations, $\texttt{onlyUsesGates}\ S$ asserts that the
operation of every gate of the circuit belongs to $S$.
\end{definition}

n21300.content:
\begin{theorem}[Every circuit has at least one node]
\lean{BoolCircuit.Circuit.one_le_size}
\label{BoolCircuit.Circuit.one_le_size}
\leanok
\uses{BoolCircuit.Circuit, BoolCircuit.Circuit.size}

For every Boolean circuit $C$ on $n$ inputs, $1 \le C.\texttt{size}$.
\end{theorem}

n21301.content:
\begin{definition}[AND/OR gate restriction]
\lean{ACP.FeedForward.IsAndOrGate}
\label{ACP.FeedForward.IsAndOrGate}
\leanok
\uses{ACP.FeedForward}
Given a Boolean feedforward circuit $F$, a flag $\texttt{isAnd}$ on each non-input
node and a finiteness witness $\texttt{gfin}$ for each gate's arity,
$F.\texttt{IsAndOrGate}$ asserts that every gate operation is the conjunction of its
inputs when the flag is \texttt{true} and their disjunction when it is \texttt{false},
the inputs being enumerated by $\texttt{gfin}$. This is the gate restriction under
which $F$ can be converted into a \texttt{BoolCircuit.Circuit}.
\end{definition}

n21302.content:
\begin{definition}[Tree-unrolling of a node]
\lean{ACP.nodeToCircuit}
\label{ACP.nodeToCircuit}
\leanok
\uses{ACP.FeedForward, BoolCircuit.Circuit}
Recursively expands a node $v$ of layer $m$ of a Boolean feedforward circuit into a
tree-shaped $\texttt{Circuit}\ n$: a layer-$0$ node becomes the positive literal of the
corresponding input variable, and a node at a higher layer becomes an AND/OR node
whose children are the unrollings of the nodes on its input wires. Nodes feeding
several downstream gates are duplicated.
\end{definition}

n21303.content:
\begin{theorem}[Tree-unrolling preserves the value of a node]
\lean{ACP.nodeToCircuit_eval}
\label{ACP.nodeToCircuit_eval}
\leanok
\uses{ACP.FeedForward, ACP.FeedForward.Gate.eval, ACP.FeedForward.IsAndOrGate, ACP.FeedForward.evalNode, ACP.nodeToCircuit, BoolCircuit.Circuit.eval, BoolCircuit.Lit.eval}

If every gate of $F$ is an AND or OR gate as recorded by $\texttt{isAnd}$ and
$\texttt{gfin}$, then for every node $v$ at layer $m$ and every input
$x : \mathrm{Fin}\,n \to \{0,1\}$,
\[
(\texttt{nodeToCircuit}\ F\ \texttt{isAnd}\ \texttt{gfin}\ m\ h\ v).\texttt{eval}\ x
 = F.\texttt{evalNode}\ v\ x .
\]
\end{theorem}

n21304.content:
\begin{theorem}[Size bound for tree-unrolling]
\lean{ACP.nodeToCircuit_size_le}
\label{ACP.nodeToCircuit_size_le}
\leanok
\uses{ACP.FeedForward, ACP.nodeToCircuit, BoolCircuit.Circuit.size}

If every gate of $F$ has at most $k$ input wires, i.e.\
$\mathrm{card}\,(F.\texttt{gates}\ d\ v).\texttt{op}.\iota \le k$ for all $d$ and $v$,
then the unrolling of any node at layer $m$ has size at most $(k+1)^m$.
\end{theorem}

n21305.content:
\begin{definition}[Conversion to a Boolean circuit]
\lean{ACP.FeedForward.toCircuit}
\label{ACP.FeedForward.toCircuit}
\leanok
\uses{ACP.FeedForward, ACP.nodeToCircuit, BoolCircuit.Circuit}
For an AND/OR feedforward circuit $F$ and a chosen output node $o : \texttt{out}$,
the tree-shaped $\texttt{Circuit}\ n$ obtained by tree-unrolling $o$ from the last
layer down to the inputs.
\end{definition}

n21306.content:
\begin{theorem}[Conversion preserves evaluation]
\lean{ACP.FeedForward.toCircuit_eval}
\label{ACP.FeedForward.toCircuit_eval}
\leanok
\uses{ACP.FeedForward, ACP.FeedForward.IsAndOrGate, ACP.FeedForward.eval, ACP.FeedForward.toCircuit, ACP.nodeToCircuit_eval, BoolCircuit.Circuit.eval}

If every gate of $F$ is an AND or OR gate, then for every output node $o$ and every
input $x$,
\[
(F.\texttt{toCircuit}\ \texttt{isAnd}\ \texttt{gfin}\ o).\texttt{eval}\ x
 = F.\texttt{eval}\ x\ o .
\]
\end{theorem}

n21307.content:
\begin{theorem}[Size bound for the converted circuit]
\lean{ACP.FeedForward.toCircuit_size_le}
\label{ACP.FeedForward.toCircuit_size_le}
\leanok
\uses{ACP.FeedForward, ACP.FeedForward.toCircuit, ACP.nodeToCircuit_size_le, BoolCircuit.Circuit.size, BoolCircuit.Circuit.toFeedForward}

If every gate of $F$ has at most $k$ input wires, then for every output node $o$ the
tree-unrolled circuit satisfies
$(F.\texttt{toCircuit}\ \texttt{isAnd}\ \texttt{gfin}\ o).\texttt{size} \le (k+1)^{F.\texttt{depth}}$.
\end{theorem}

n21308.content:
\begin{definition}[Embedding a Boolean circuit as a feedforward circuit]
\lean{BoolCircuit.Circuit.toFeedForward}
\label{BoolCircuit.Circuit.toFeedForward}
\leanok
\uses{ACP.FeedForward, ACP.FeedForward.GateOp.id, BoolCircuit.Circuit, BoolCircuit.Circuit.depth, BoolCircuit.Circuit.eval}
Turns a circuit $C$ on $n$ inputs into a feedforward circuit
$\texttt{FeedForward}\ \texttt{Bool}\ (\mathrm{Fin}\,n)\ \mathrm{Unit}$ of depth
$C.\texttt{depth} + 1$: layer $0$ carries the $n$ input variables and every higher
layer carries a single wire. The gate from layer $0$ to layer $1$ computes
$C.\texttt{eval}$ from all inputs at once, and all later gates are identity wires
that pass the single Boolean value upward.
\end{definition}

n21309.content:
\begin{theorem}[Non-input nodes of the embedding are constant]
\lean{ACP.Circuit.toFeedForward_evalNode_const}
\label{ACP.Circuit.toFeedForward_evalNode_const}
\leanok
\uses{ACP.FeedForward.evalNode, BoolCircuit.Circuit, BoolCircuit.Circuit.depth, BoolCircuit.Circuit.eval, BoolCircuit.Circuit.toFeedForward}

For every input $x$, every layer index $m$ with $0 < m$ and every node $v$ of layer
$m$ of $C.\texttt{toFeedForward}$, the value of $v$ is
$C.\texttt{toFeedForward}.\texttt{evalNode}\ v\ x = C.\texttt{eval}\ x$.
\end{theorem}

n21310.content:
\begin{theorem}[The embedding computes the same function]
\lean{ACP.Circuit.toFeedForward_eval}
\label{ACP.Circuit.toFeedForward_eval}
\leanok
\uses{ACP.Circuit.toFeedForward_evalNode_const, ACP.FeedForward.eval₁, BoolCircuit.Circuit, BoolCircuit.Circuit.eval, BoolCircuit.Circuit.toFeedForward}

For every circuit $C$ on $n$ inputs and every input $x$,
$C.\texttt{toFeedForward}.\texttt{eval}_1\ x = C.\texttt{eval}\ x$.
\end{theorem}

n21311.content:
\begin{theorem}[Depth of the embedding]
\lean{ACP.Circuit.toFeedForward_depth}
\label{ACP.Circuit.toFeedForward_depth}
\leanok
\uses{BoolCircuit.Circuit, BoolCircuit.Circuit.depth, BoolCircuit.Circuit.toFeedForward}

The embedding uses one extra layer for the inputs:
$C.\texttt{toFeedForward}.\texttt{depth} = C.\texttt{depth} + 1$.
\end{theorem}

n21312.content:
\begin{theorem}[Size bound for the embedding]
\lean{ACP.Circuit.toFeedForward_size_le}
\label{ACP.Circuit.toFeedForward_size_le}
\leanok
\uses{ACP.FeedForward.size, BoolCircuit.Circuit, BoolCircuit.Circuit.depth, BoolCircuit.Circuit.one_le_size, BoolCircuit.Circuit.size, BoolCircuit.Circuit.toFeedForward}

For every circuit $C$ on $n$ inputs,
$C.\texttt{toFeedForward}.\texttt{size} \le C.\texttt{size} \cdot (C.\texttt{depth} + 1)$.
\end{theorem}

n21313.content:
\begin{definition}[Low-degree squarefree supports]
\lean{ACP.LowDegreeSupport}
\label{ACP.LowDegreeSupport}
\leanok
For $n, D \in \mathbb{N}$, the type of supports of squarefree monomials of degree at most
$D$: the subtype of finsets $s \subseteq \mathrm{Fin}\,n$ with $\left\lvert s\right\rvert \le D$.  In the
displays below this type is written $\mathcal{S}_{n,D}$.
\end{definition}

n21314.content:
\begin{definition}[Low-degree squarefree polynomial from coefficients]
\lean{ACP.lowDegreeSquarefreePolynomial}
\label{ACP.lowDegreeSquarefreePolynomial}
\leanok
\uses{ACP.LowDegreeSupport, ACP.squarefreeMonomial}
Given coefficients $c$ indexed by $\texttt{ACP.LowDegreeSupport}\ n\ D$, the multivariate
polynomial
\[
\sum_{\substack{s \subseteq \mathrm{Fin}\,n \\ \left\lvert s\right\rvert \le D}} c(s)\, \prod_{i \in s} X_i ,
\]
i.e. the sum of the squarefree monomials $\texttt{ACP.squarefreeMonomial}\ s$ weighted by
$c$, with the terms of support size $> D$ set to $0$.
\end{definition}

n21315.content:
\begin{theorem}[Squarefree representative on the root cube]
\lean{ACP.exists_squarefree_representative_on_rootCube}
\label{ACP.exists_squarefree_representative_on_rootCube}
\leanok
\uses{ACP.rootCube, ACP.squarefreeMonomial, ACP.squarefreePolynomial}

Every function $f : \{1,\omega\}^n \to K$ on the root cube is represented by a squarefree
(multilinear) polynomial: there are coefficients $c$ indexed by finsets of
$\mathrm{Fin}\,n$ such that $(\texttt{ACP.squarefreePolynomial}\ c)(x) = f(x)$ for all
$x$ in the root cube.
\end{theorem}

n21316.content:
\begin{theorem}[Monomial-level degree-preserving multilinearization]
\lean{ACP.monomial_lowDegree_squarefree_complete_on_rootCube}
\label{ACP.monomial_lowDegree_squarefree_complete_on_rootCube}
\leanok
\uses{ACP.LowDegreeSupport, ACP.lowDegreeSquarefreePolynomial, ACP.rootCube, ACP.squarefreeMonomial}

Assume $\omega \ne 1$.  If a monomial $a\,X^m$ has total exponent sum
$\sum_i m_i \le D$, then it agrees on the root cube $\{1,\omega\}^n$ with a squarefree
polynomial built only from supports of size at most $D$: there exist coefficients
$c$ on $\texttt{ACP.LowDegreeSupport}\ n\ D$ with
$(\texttt{ACP.lowDegreeSquarefreePolynomial}\ c)(x) = (a\,X^m)(x)$ for every $x$ in the cube.
\end{theorem}

n21317.content:
\begin{lemma}[Additivity in the coefficient function]
\lean{ACP.lowDegreeSquarefreePolynomial_add}
\label{ACP.lowDegreeSquarefreePolynomial_add}
\leanok
\uses{ACP.LowDegreeSupport, ACP.lowDegreeSquarefreePolynomial}

The constructor $\texttt{ACP.lowDegreeSquarefreePolynomial}$ is additive in its coefficient
argument: the polynomial attached to $c_1 + c_2$ is the sum of the polynomials attached
to $c_1$ and to $c_2$.
\end{lemma}

n21318.content:
\begin{lemma}[Zero coefficients give the zero polynomial]
\lean{ACP.lowDegreeSquarefreePolynomial_zero}
\label{ACP.lowDegreeSquarefreePolynomial_zero}
\leanok
\uses{ACP.LowDegreeSupport, ACP.lowDegreeSquarefreePolynomial}

The constructor $\texttt{ACP.lowDegreeSquarefreePolynomial}$ sends the identically zero
coefficient function to the zero polynomial.
\end{lemma}

n21319.content:
\begin{lemma}[Finite-sum linearity in the coefficients]
\lean{ACP.lowDegreeSquarefreePolynomial_sum}
\label{ACP.lowDegreeSquarefreePolynomial_sum}
\leanok
\uses{ACP.LowDegreeSupport, ACP.lowDegreeSquarefreePolynomial, ACP.lowDegreeSquarefreePolynomial_add, ACP.lowDegreeSquarefreePolynomial_zero}

For a finite index set $S$ and coefficient functions $c_i$, the polynomial attached to
the pointwise sum $\sum_{i \in S} c_i$ equals $\sum_{i \in S}$ of the polynomials attached
to the individual $c_i$.
\end{lemma}

n21320.content:
\begin{theorem}[Completeness of low-degree squarefree polynomials on the root cube]
\lean{ACP.lowDegree_squarefree_complete_on_rootCube}
\label{ACP.lowDegree_squarefree_complete_on_rootCube}
\leanok
\uses{ACP.LowDegreeSupport, ACP.lowDegreeSquarefreePolynomial, ACP.lowDegreeSquarefreePolynomial_sum, ACP.monomial_lowDegree_squarefree_complete_on_rootCube, ACP.rootCube}

Assume $\omega \ne 1$.  Every polynomial $Q$ with $\deg Q \le D$ agrees on the root cube
$\{1,\omega\}^n$ with a low-degree squarefree polynomial: there are coefficients $c$ on
$\texttt{ACP.LowDegreeSupport}\ n\ D$ such that
$(\texttt{ACP.lowDegreeSquarefreePolynomial}\ c)(x) = Q(x)$ for all $x$ in the cube.
\end{theorem}

n21321.content:
\begin{lemma}[Degree bound for the constructed polynomial]
\lean{ACP.lowDegreeSquarefreePolynomial_totalDegree_le}
\label{ACP.lowDegreeSquarefreePolynomial_totalDegree_le}
\leanok
\uses{ACP.LowDegreeSupport, ACP.lowDegreeSquarefreePolynomial, ACP.squarefreeMonomial, ACP.squarefreeMonomial_totalDegree_le_card}

For any coefficient function $c$ on $\texttt{ACP.LowDegreeSupport}\ n\ D$, the polynomial
$\texttt{ACP.lowDegreeSquarefreePolynomial}\ c$ has total degree at most $D$.
\end{lemma}

n21322.content:
\begin{definition}[Support-to-sigma injection]
\lean{ACP.lowDegreeSupportSigmaMap}
\label{ACP.lowDegreeSupportSigmaMap}
\leanok
\uses{ACP.LowDegreeSupport}
The map sending a low-degree support $s$ to the pair consisting of its exact cardinality
$\left\lvert s\right\rvert \in \mathrm{Fin}(D+1)$ together with $s$ itself, viewed as an element of
$\{t : \mathrm{Finset}(\mathrm{Fin}\,n) \mid \left\lvert t\right\rvert = \left\lvert s\right\rvert\}$.  It is used as an
injection for the binomial-sum bound rather than as a full equivalence.
\end{definition}

n21323.content:
\begin{theorem}[Binomial bound on the number of low-degree supports]
\lean{ACP.lowDegreeSupport_card_le_binomial_sum}
\label{ACP.lowDegreeSupport_card_le_binomial_sum}
\leanok
\uses{ACP.LowDegreeSupport, ACP.lowDegreeCoeff_card, ACP.lowDegreeSupportSigmaMap}

The number of low-degree squarefree supports satisfies
\[
\left\lvert \mathcal{S}_{n,D}\right\rvert \;\le\; \sum_{t=0}^{D} \binom{n}{t}.
\]
\end{theorem}

n21324.content:
\begin{lemma}[Size of the coefficient family]
\lean{ACP.lowDegreeCoeff_card}
\label{ACP.lowDegreeCoeff_card}
\leanok
\uses{ACP.LowDegreeSupport}

For a finite type $K_0$, the number of coefficient functions on low-degree supports is
\[
\left\lvert \mathcal{S}_{n,D} \to K_0\right\rvert
  \;=\; \left\lvert K_0\right\rvert^{\,\left\lvert \mathcal{S}_{n,D}\right\rvert} .
\]
\end{lemma}

n21325.content:
\begin{definition}[Root cube as Boolean strings]
\lean{ACP.rootCubeEquivFinTwo}
\label{ACP.rootCubeEquivFinTwo}
\leanok
\uses{ACP.rootCube}
If $\omega \ne 1$, the explicit equivalence $\{1,\omega\}^n \simeq (\mathrm{Fin}\,n \to
\mathrm{Fin}\,2)$ that records, for each coordinate, whether its value is $1$ or $\omega$.
\end{definition}

n21326.content:
\begin{lemma}[Cardinality of the root cube]
\lean{ACP.rootCube_card_of_ne_one}
\label{ACP.rootCube_card_of_ne_one}
\leanok
\uses{ACP.rootCube, ACP.rootCubeEquivFinTwo}

If $\omega \ne 1$ and $K$ is finite, then the root cube has exactly $2^n$ points:
$\left\lvert \{1,\omega\}^n\right\rvert = 2^n$.
\end{lemma}

n21327.content:
\begin{lemma}[Number of functions on the root cube]
\lean{ACP.rootCube_function_card_of_ne_one}
\label{ACP.rootCube_function_card_of_ne_one}
\leanok
\uses{ACP.rootCube, ACP.rootCube_card_of_ne_one}

If $\omega \ne 1$ and $K$ is finite, the number of functions $\{1,\omega\}^n \to K$ is
$\left\lvert K\right\rvert^{2^n}$.
\end{lemma}

n21329.content:
\begin{theorem}[Hamming-ball bound on the root cube]
\lean{ACP.rootCubeBall_card_le_binomial}
\label{ACP.rootCubeBall_card_le_binomial}
\leanok
\uses{ACP.function_hammingBall_card_le_binomial, ACP.rootCube, ACP.rootCubeBall, ACP.rootCubeFunctionBadCount}

For any center function on the root cube and any radius $e$, the Hamming ball
$\texttt{ACP.rootCubeBall}$ of radius $e$ around it satisfies
\[
\left\lvert B_e(\mathrm{center})\right\rvert
  \;\le\; \sum_{t=0}^{e} \binom{\left\lvert \{1,\omega\}^n\right\rvert}{t}\,\left\lvert K\right\rvert^{\,t}.
\]
\end{theorem}

n21330.content:
\begin{theorem}[Counting obstruction for low-degree squarefree candidates]
\lean{ACP.rootCube_counting_obstruction_lowDegreeSquarefree}
\label{ACP.rootCube_counting_obstruction_lowDegreeSquarefree}
\leanok
\uses{ACP.LowDegreeSupport, ACP.lowDegreeSquarefreePolynomial, ACP.lowDegree_squarefree_complete_on_rootCube, ACP.rootCube, ACP.rootCubeBadCount, ACP.rootCubeBall, ACP.rootCubeBall_card_le_binomial, ACP.rootCube_card_of_ne_one, ACP.rootCube_counting_obstruction, ACP.rootCube_function_card_of_ne_one}

Let $K$ be finite and $\omega \ne 1$.  Suppose the ball bound
$\sum_{t=0}^{e} \binom{2^n}{t}\,\left\lvert K\right\rvert^{\,t} \le B$ holds and the counting is strict,
\[
\left\lvert K\right\rvert^{2^n} \;>\; \left\lvert \mathcal{S}_{n,D} \to K\right\rvert\cdot B .
\]
Then it is \emph{not} the case that every function $f : \{1,\omega\}^n \to K$ admits a
polynomial $Q$ with $\deg Q \le D$ and $\texttt{ACP.rootCubeBadCount}\ f\ Q \le e$.
\end{theorem}

n21332.content:
\begin{definition}[MOD $q$ target inside $\mathbb{Z}/p$]
\lean{ACP.modQTarget}
\label{ACP.modQTarget}
\leanok
\uses{ACP.modGateOp}
For a prime $q$, the Boolean function $\mathrm{MOD}_q$ on $n$ inputs viewed as a function
$\{0,1\}^n \to \mathbb{Z}/p$: the output bit of the gate operation $\mathrm{modGateOp}\ q\ n$
is cast into $\mathbb{Z}/p$.
\end{definition}

n21333.content:
\begin{definition}[Bad input count on the Boolean cube]
\lean{ACP.badInputCount}
\label{ACP.badInputCount}
\leanok
\uses{ACP.boolInput}
For a target $f : \{0,1\}^n \to \mathbb{Z}/p$ and a polynomial
$P \in (\mathbb{Z}/p)[X_1,\dots,X_n]$, the number of Boolean inputs $x$ with
$P(\mathrm{boolInput}(x)) \neq f(x)$.
\end{definition}

n21334.content:
\begin{definition}[Low-degree bad-count lower bound]
\lean{ACP.LowDegreeBadCountLB}
\label{ACP.LowDegreeBadCountLB}
\leanok
\uses{ACP.badInputCount}
The predicate asserting that every polynomial $P$ of total degree at most $d$ has
$E \le \mathrm{badInputCount}(f, P)$, i.e.\ $f$ cannot be computed by a degree-$d$
polynomial on more than $2^n - E$ points of the Boolean cube.
\end{definition}

n21335.content:
\begin{lemma}[Averaging over parameters]
\lean{ACP.exists_good_parameter_of_pointwise_bound}
\label{ACP.exists_good_parameter_of_pointwise_bound}
\leanok

Let $\alpha,\beta$ be finite types with $\beta$ nonempty and let
$\mathrm{Fail} : \alpha \to \beta \to \mathrm{Prop}$ be decidable. If for every $a$ the
number of $b$ with $\mathrm{Fail}\,a\,b$ satisfies
$\left\lvert \{b : \mathrm{Fail}\,a\,b\}\right\rvert\cdot C \le B\cdot\left\lvert \beta\right\rvert$, then there is a single
$b$ with $\left\lvert \{a : \mathrm{Fail}\,a\,b\}\right\rvert\cdot C \le B\cdot\left\lvert \alpha\right\rvert$.
\end{lemma}

n21336.content:
\begin{theorem}[One polynomial from a pointwise distribution]
\lean{ACP.exists_single_polynomial_from_pointwise_distribution}
\label{ACP.exists_single_polynomial_from_pointwise_distribution}
\leanok
\uses{ACP.badInputCount, ACP.boolInput, ACP.exists_good_parameter_of_pointwise_bound}

Let $P$ be a family of polynomials over $\mathbb{Z}/p$ indexed by a nonempty finite seed
type. If for every Boolean input $x$ the number of seeds $s$ with
$(P_s)(\mathrm{boolInput}(x)) \neq f(x)$, times $2^{\ell}$, is at most
$B\cdot\left\lvert \mathrm{Seed}\right\rvert$, then some seed $s$ satisfies
$\mathrm{badInputCount}(f, P_s)\cdot 2^{\ell} \le B\cdot 2^{n}$.
\end{theorem}

n21337.content:
\begin{theorem}[{Single low-degree polynomial for an $\mathrm{AC}^0[p]$ circuit}]
\lean{ACP.exists_single_poly_for_circuit_one_size}
\label{ACP.exists_single_poly_for_circuit_one_size}
\leanok
\uses{ACP.ACp_GateOps, ACP.FeedForward, ACP.FeedForward.eval₁, ACP.FeedForward.onlyUsesGates, ACP.FeedForward.size, ACP.badInputCount, ACP.circuitDegreeBound, ACP.exists_poly_distribution_for_circuit_one_size, ACP.exists_single_polynomial_from_pointwise_distribution}

Let $F$ be a feed-forward circuit with a unique output that only uses $\mathrm{AC}^0[p]$
gate operations. Then there exists a polynomial $P$ over $\mathbb{Z}/p$ with
$\deg P \le \mathrm{circuitDegreeBound}\,p\,\ell\,(\mathrm{depth}\,F)$ whose bad-input
count against the function computed by $F$ satisfies
$\mathrm{badInputCount}\cdot 2^{\ell} \le \left\lvert F\right\rvert\cdot 2^{n}$, where $\left\lvert F\right\rvert$ is the
circuit size.
\end{theorem}

n21338.content:
\begin{theorem}[Size lower bound from a degree lower bound]
\lean{ACP.size_lower_bound_from_badCountLB}
\label{ACP.size_lower_bound_from_badCountLB}
\leanok
\uses{ACP.ACp_GateOps, ACP.FeedForward, ACP.FeedForward.eval₁, ACP.FeedForward.onlyUsesGates, ACP.FeedForward.size, ACP.LowDegreeBadCountLB, ACP.badInputCount, ACP.circuitDegreeBound, ACP.exists_single_poly_for_circuit_one_size, ACP.modGateOp, ACP.modQTarget}

If a feed-forward circuit $F$ over the $\mathrm{AC}^0[p]$ gate set computes
$\mathrm{MOD}_q$ on all Boolean inputs, and if $\mathrm{MOD}_q$ (viewed in $\mathbb{Z}/p$)
admits the lower bound $\mathrm{LowDegreeBadCountLB}$ with parameters
$(\mathrm{circuitDegreeBound}\,p\,\ell\,(\mathrm{depth}\,F), E)$, then
$E \cdot 2^{\ell} \le \left\lvert F\right\rvert\cdot 2^{n}$.
\end{theorem}

n21339.content:
\begin{theorem}[Relative-error size lower bound]
\lean{ACP.size_lower_bound_from_relative_badCountLB}
\label{ACP.size_lower_bound_from_relative_badCountLB}
\leanok
\uses{ACP.ACp_GateOps, ACP.FeedForward, ACP.FeedForward.eval₁, ACP.FeedForward.onlyUsesGates, ACP.FeedForward.size, ACP.LowDegreeBadCountLB, ACP.circuitDegreeBound, ACP.modGateOp, ACP.modQTarget, ACP.size_lower_bound_from_badCountLB}

Same hypotheses as the previous theorem, but with the bad-count bound taken in the
relative form $E = \delta \cdot 2^{n}$; the conclusion is then the clean size bound
$\delta \cdot 2^{\ell} \le \left\lvert F\right\rvert$.
\end{theorem}

n21340.content:
\begin{definition}[Standard field $\mathbb{F}_{p^{q-1}}$]
\lean{ACP.ModqField}
\label{ACP.ModqField}
\leanok
The Galois field $\mathbb{F}_{p^{q-1}}$, the standard field choice for the
$\mathrm{MOD}_q$ lower bound.
\end{definition}

n21341.content:
\begin{lemma}[Exponent $q-1$ is nonzero]
\lean{ACP.q_sub_one_ne_zero}
\label{ACP.q_sub_one_ne_zero}
\leanok

For a prime $q$ we have $q - 1 \neq 0$; this is the side condition needed to compute the
cardinality of $\mathbb{F}_{p^{q-1}}$.
\end{lemma}

n21342.content:
\begin{lemma}[Cardinality of $\mathbb{F}_{p^{q-1}}$]
\lean{ACP.natCard_modqField}
\label{ACP.natCard_modqField}
\leanok
\uses{ACP.ModqField, ACP.q_sub_one_ne_zero}

For primes $p$ and $q$, the field $\mathrm{ModqField}\,q$ has exactly $p^{q-1}$ elements.
\end{lemma}

n21343.content:
\begin{theorem}[A unit of order exactly $q$]
\lean{ACP.exists_unit_of_order_q_modqField}
\label{ACP.exists_unit_of_order_q_modqField}
\leanok
\uses{ACP.ModqField, ACP.natCard_modqField}

If $p \neq q$ are primes, then the unit group of $\mathbb{F}_{p^{q-1}}$ contains an
element $u$ with $\mathrm{ord}(u) = q$.
\end{theorem}

n21344.content:
\begin{theorem}[Nontrivial $q$-th root of unity]
\lean{ACP.exists_nontrivial_qth_root_modqField}
\label{ACP.exists_nontrivial_qth_root_modqField}
\leanok
\uses{ACP.ModqField, ACP.exists_unit_of_order_q_modqField}

If $p \neq q$ are primes, then there is $\omega \in \mathbb{F}_{p^{q-1}}$ with
$\omega^{q} = 1$ and $\omega \neq 1$.
\end{theorem}

n21345.content:
\begin{definition}[Root-of-unity cube $\{1,\omega\}^n$]
\lean{ACP.rootCube}
\label{ACP.rootCube}
\leanok
The subtype of vectors $x : \mathrm{Fin}\,n \to K$ such that each coordinate satisfies
$x_i = 1$ or $x_i = \omega$.
\end{definition}

n21346.content:
\begin{theorem}[Polynomial representation on the root cube]
\lean{ACP.exists_multilinear_representative_on_rootCube}
\label{ACP.exists_multilinear_representative_on_rootCube}
\leanok
\uses{ACP.rootCube}

Every function $f : \{1,\omega\}^n \to K$ agrees on the cube with the evaluation of some
polynomial $P \in K[X_1,\dots,X_n]$, i.e.\ $P(x) = f(x)$ for all $x$ in the cube.
\end{theorem}

n21347.content:
\begin{definition}[Squarefree monomial]
\lean{ACP.squarefreeMonomial}
\label{ACP.squarefreeMonomial}
\leanok
For $s \subseteq \mathrm{Fin}\,n$, the monomial $\prod_{i \in s} X_i$.
\end{definition}

n21348.content:
\begin{definition}[Squarefree (multilinear) polynomial from coefficients]
\lean{ACP.squarefreePolynomial}
\label{ACP.squarefreePolynomial}
\leanok
\uses{ACP.squarefreeMonomial}
Given coefficients $c_S$ indexed by subsets $S \subseteq \mathrm{Fin}\,n$, the polynomial
\[
  \sum_{S} c_S \prod_{i \in S} X_i .
\]
\end{definition}

n21349.content:
\begin{theorem}[Evaluation of a squarefree monomial]
\lean{ACP.squarefreeMonomial_eval}
\label{ACP.squarefreeMonomial_eval}
\leanok
\uses{ACP.squarefreeMonomial}

For any $x : \mathrm{Fin}\,n \to K$, the monomial indexed by $s$ evaluates to
$\prod_{i \in s} x_i$.
\end{theorem}

n21350.content:
\begin{theorem}[Affine expression is coordinatewise inversion]
\lean{ACP.rootCube_affine_inverse}
\label{ACP.rootCube_affine_inverse}
\leanok
\uses{ACP.rootCube}

If $\omega \neq 0$ and $x$ lies in $\{1,\omega\}^n$, then for every coordinate $i$,
\[
  1 + \omega^{-1} - \omega^{-1} x_i = x_i^{-1}.
\]
\end{theorem}

n21351.content:
\begin{theorem}[Degree of a squarefree monomial]
\lean{ACP.squarefreeMonomial_totalDegree_le_card}
\label{ACP.squarefreeMonomial_totalDegree_le_card}
\leanok
\uses{ACP.squarefreeMonomial}

The total degree of $\prod_{i \in s} X_i$ is at most $\left\lvert s\right\rvert$.
\end{theorem}

n21352.content:
\begin{theorem}[Coordinates on the root cube are nonzero]
\lean{ACP.rootCube_coord_ne_zero}
\label{ACP.rootCube_coord_ne_zero}
\leanok
\uses{ACP.rootCube}

If $\omega \neq 0$ and $x \in \{1,\omega\}^n$, then $x_i \neq 0$ for every $i$.
\end{theorem}

n21353.content:
\begin{theorem}[Top monomial times a complement inverse monomial]
\lean{ACP.rootCube_top_mul_compl_inverse}
\label{ACP.rootCube_top_mul_compl_inverse}
\leanok
\uses{ACP.rootCube, ACP.rootCube_coord_ne_zero}

For $\omega \neq 0$, $x \in \{1,\omega\}^n$ and $s \subseteq \mathrm{Fin}\,n$,
\[
  \Bigl(\prod_{i} x_i\Bigr)\cdot \prod_{i \in s^{c}} x_i^{-1} \;=\; \prod_{i \in s} x_i .
\]
\end{theorem}

n21354.content:
\begin{theorem}[Split at degree $n/2$]
\lean{ACP.split_multilinear_at_half_degree}
\label{ACP.split_multilinear_at_half_degree}
\leanok
\uses{ACP.rootCube, ACP.rootCube_affine_inverse, ACP.rootCube_top_mul_compl_inverse, ACP.squarefreeMonomial, ACP.squarefreeMonomial_totalDegree_le_card, ACP.squarefreePolynomial}

Let $\omega \neq 0$ and let $c$ be a coefficient family. Then there are polynomials
$P_1, P_2$ of total degree at most $n/2$ such that for every $x \in \{1,\omega\}^n$,
\[
  \Bigl(\textstyle\sum_S c_S \prod_{i \in S} X_i\Bigr)(x)
   = P_1(x) + \Bigl(\prod_i x_i\Bigr)\cdot P_2\bigl(1 + \omega^{-1} - \omega^{-1}x_1,\dots,
     1 + \omega^{-1} - \omega^{-1}x_n\bigr).
\]
\end{theorem}

n21355.content:
\begin{definition}[Affine inverse coordinate polynomial]
\lean{ACP.affineInvPoly}
\label{ACP.affineInvPoly}
\leanok
The degree-one polynomial $1 + \omega^{-1} - \omega^{-1} X_i$, which on $\{1,\omega\}$
with $\omega \neq 0$ computes $x \mapsto x^{-1}$.
\end{definition}

n21356.content:
\begin{theorem}[Evaluation of the affine inverse polynomial]
\lean{ACP.affineInvPoly_eval}
\label{ACP.affineInvPoly_eval}
\leanok
\uses{ACP.affineInvPoly}

For any $x : \mathrm{Fin}\,n \to K$, the polynomial $\mathrm{affineInvPoly}\,\omega\,i$
evaluates to $1 + \omega^{-1} - \omega^{-1} x_i$.
\end{theorem}

n21357.content:
\begin{theorem}[Affine inverse polynomial has degree at most one]
\lean{ACP.affineInvPoly_totalDegree_le_one}
\label{ACP.affineInvPoly_totalDegree_le_one}
\leanok
\uses{ACP.affineInvPoly}

The total degree of $\mathrm{affineInvPoly}\,\omega\,i$ is at most $1$.
\end{theorem}

n21358.content:
\begin{definition}[Affine-substituted squarefree monomial]
\lean{ACP.affineSquarefreeMonomial}
\label{ACP.affineSquarefreeMonomial}
\leanok
\uses{ACP.affineInvPoly}
For $s \subseteq \mathrm{Fin}\,n$, the product $\prod_{i \in s}(1 + \omega^{-1} -
\omega^{-1}X_i)$, i.e.\ the squarefree monomial after the affine inverse substitution.
\end{definition}

n21359.content:
\begin{theorem}[Evaluation of the affine squarefree monomial]
\lean{ACP.affineSquarefreeMonomial_eval}
\label{ACP.affineSquarefreeMonomial_eval}
\leanok
\uses{ACP.affineSquarefreeMonomial}

For any $x : \mathrm{Fin}\,n \to K$, the affine squarefree monomial indexed by $s$
evaluates to $\prod_{i \in s} (1 + \omega^{-1} - \omega^{-1} x_i)$.
\end{theorem}

n21360.content:
\begin{theorem}[Degree of the affine squarefree monomial]
\lean{ACP.affineSquarefreeMonomial_totalDegree_le_card}
\label{ACP.affineSquarefreeMonomial_totalDegree_le_card}
\leanok
\uses{ACP.affineInvPoly, ACP.affineInvPoly_totalDegree_le_one, ACP.affineSquarefreeMonomial}

The total degree of $\mathrm{affineSquarefreeMonomial}\,\omega\,s$ is at most $\left\lvert s\right\rvert$.
\end{theorem}

n21362.content:
\begin{definition}[Bad count of a polynomial on the root cube]
\lean{ACP.rootCubeBadCount}
\label{ACP.rootCubeBadCount}
\leanok
\uses{ACP.rootCube}
The number of points $x \in \{1,\omega\}^n$ on which $P(x) \neq f(x)$.
\end{definition}

n21363.content:
\begin{definition}[Hamming distance between functions on the root cube]
\lean{ACP.rootCubeFunctionBadCount}
\label{ACP.rootCubeFunctionBadCount}
\leanok
\uses{ACP.rootCube}
The number of points $x \in \{1,\omega\}^n$ on which two functions
$f, g : \{1,\omega\}^n \to K$ differ.
\end{definition}

n21364.content:
\begin{definition}[Hamming ball on the root cube]
\lean{ACP.rootCubeBall}
\label{ACP.rootCubeBall}
\leanok
\uses{ACP.rootCube, ACP.rootCubeFunctionBadCount}
The finite set of functions $f : \{1,\omega\}^n \to K$ that differ from a given center
function on at most $e$ points of the cube.
\end{definition}

n21365.content:
\begin{theorem}[Covering by Hamming balls: counting bound]
\lean{ACP.finite_cover_by_hamming_balls_card_bound}
\label{ACP.finite_cover_by_hamming_balls_card_bound}
\leanok

Let $\alpha, \beta, \mathrm{Cand}$ be finite and let $\mathrm{center} : \mathrm{Cand}
\to (\alpha \to \beta)$. If every ball $\{f : \left\lvert \{a : \mathrm{center}\,c\,a \neq f(a)\}\right\rvert
\le e\}$ has at most $B$ elements, and every $f : \alpha \to \beta$ lies in one of these
balls, then $\left\lvert \alpha \to \beta\right\rvert \le \left\lvert \mathrm{Cand}\right\rvert \cdot B$.
\end{theorem}

n21366.content:
\begin{theorem}[Finite counting obstruction on the root cube]
\lean{ACP.rootCube_counting_obstruction}
\label{ACP.rootCube_counting_obstruction}
\leanok
\uses{ACP.finite_cover_by_hamming_balls_card_bound, ACP.rootCube, ACP.rootCubeBadCount, ACP.rootCubeBall, ACP.rootCubeFunctionBadCount}

Suppose a finite family $(\mathrm{poly}\,c)_{c \in \mathrm{Cand}}$ represents, on the cube,
every polynomial of total degree at most $D$; suppose each Hamming ball of radius $e$
around such a candidate has at most $B$ elements; and suppose
$\left\lvert \{1,\omega\}^n \to K\right\rvert > \left\lvert \mathrm{Cand}\right\rvert \cdot B$. Then it is not the case that
every function on the cube has a degree-$\le D$ approximant with at most $e$ bad points.
\end{theorem}

n21367.content:
\begin{theorem}[Approximating the top monomial approximates everything]
\lean{ACP.rootProd_approx_implies_all_functions_approx}
\label{ACP.rootProd_approx_implies_all_functions_approx}
\leanok
\uses{ACP.rootCube, ACP.rootCubeBadCount, ACP.split_multilinear_at_half_degree_direct, ACP.squarefreePolynomial}

Assume $\omega \neq 0$ and that every function on $\{1,\omega\}^n$ is represented on the
cube by a squarefree polynomial. If $P$ has total degree at most $d$ and approximates the
top monomial $x \mapsto \prod_i x_i$ with at most $e$ bad points, then every function
$f$ on the cube has a polynomial $Q$ with $\deg Q \le n/2 + d$ and at most $e$ bad points.
\end{theorem}

n21368.content:
\begin{theorem}[No low-degree approximant to the top monomial]
\lean{ACP.no_low_degree_rootProd_approx}
\label{ACP.no_low_degree_rootProd_approx}
\leanok
\uses{ACP.rootCube, ACP.rootCubeBadCount, ACP.rootProd_approx_implies_all_functions_approx, ACP.squarefreePolynomial}

Assume $\omega \neq 0$, that every function on $\{1,\omega\}^n$ has a squarefree
representative, and the counting hypothesis that not every function on the cube admits a
degree-$\le n/2 + d$ approximant with at most $e$ bad points. Then no polynomial of total
degree at most $d$ approximates the top monomial $x \mapsto \prod_i x_i$ within $e$ bad
points.
\end{theorem}

n21369.content:
\begin{theorem}[Top-monomial inapproximability from finite counting]
\lean{ACP.no_low_degree_rootProd_approx_of_finite_counting}
\label{ACP.no_low_degree_rootProd_approx_of_finite_counting}
\leanok
\uses{ACP.no_low_degree_rootProd_approx, ACP.rootCube, ACP.rootCubeBadCount, ACP.rootCubeBall, ACP.rootCube_counting_obstruction, ACP.squarefreePolynomial}

The same conclusion as the previous theorem, with the abstract counting hypothesis replaced
by explicit data: a finite candidate family representing all degree-$\le n/2 + d$
polynomials on the cube, a bound $B$ on the size of each Hamming ball of radius $e$, and
the strict inequality $\left\lvert \{1,\omega\}^n \to K\right\rvert > \left\lvert \mathrm{Cand}\right\rvert \cdot B$.
\end{theorem}

n21370.content:
\begin{definition}[Subset Sum problem]
\lean{SubsetSumToPartition.SubsetSum}
\label{SubsetSumToPartition.SubsetSum}
\leanok
Given a weight function $w : U \to \mathbb{N}$ on a finite type $U$ and a target
$T \in \mathbb{N}$, the predicate asserts that some subset $S \subseteq U$ has total weight
exactly $T$, i.e.\ $\exists S,\ \sum_{a \in S} w(a) = T$.
\end{definition}

n21371.content:
\begin{definition}[Partition problem]
\lean{SubsetSumToPartition.Partition}
\label{SubsetSumToPartition.Partition}
\leanok
Given a weight function $v : U \to \mathbb{N}$ on a finite type $U$, the predicate asserts
that some subset $S \subseteq U$ has the same total weight as its complement, i.e.\
$\exists S,\ \sum_{b \in S} v(b) = \sum_{b \in S^{c}} v(b)$.
\end{definition}

n21372.content:
\begin{definition}[Reduction weight function]
\lean{SubsetSumToPartition.partitionWeight}
\label{SubsetSumToPartition.partitionWeight}
\leanok
The weight function on the augmented universe $U \oplus \mathrm{Bool}$ built from a Subset
Sum instance $(w, T)$. Writing $W = \sum_{a} w(a)$, it sends the original item
$\mathrm{inl}\,a$ to $w(a)$, the first dummy item $\mathrm{inr}\,\mathsf{true}$ to
$2W - T$, and the second dummy item $\mathrm{inr}\,\mathsf{false}$ to $W + T$.
\end{definition}

n21373.content:
\begin{theorem}[Completeness of the reduction]
\lean{SubsetSumToPartition.SubsetSumToPartitionCompleteness}
\label{SubsetSumToPartition.SubsetSumToPartitionCompleteness}
\leanok
\uses{SubsetSumToPartition.Partition, SubsetSumToPartition.SubsetSum, SubsetSumToPartition.partitionWeight}

Let $w : U \to \mathbb{N}$ and $T \in \mathbb{N}$ satisfy $T \le \sum_{a} w(a)$. If the
Subset Sum instance $(w, T)$ has a solution, then the Partition instance with weight
function $\texttt{SubsetSumToPartition.partitionWeight}\ w\ T$ on $U \oplus \mathrm{Bool}$
has a solution.
\end{theorem}

n21374.content:
\begin{theorem}[Soundness of the reduction]
\lean{SubsetSumToPartition.SubsetSumToPartitionSoundness}
\label{SubsetSumToPartition.SubsetSumToPartitionSoundness}
\leanok
\uses{SubsetSumToPartition.Partition, SubsetSumToPartition.SubsetSum, SubsetSumToPartition.partitionWeight}

Let $w : U \to \mathbb{N}$ and $T \in \mathbb{N}$ satisfy $T \le \sum_{a} w(a)$. If the
Partition instance with weight function
$\texttt{SubsetSumToPartition.partitionWeight}\ w\ T$ on $U \oplus \mathrm{Bool}$ has a
solution, then the original Subset Sum instance $(w, T)$ has a solution.
\end{theorem}

n21375.content:
\begin{theorem}[Subset Sum reduces to Partition]
\lean{SubsetSumToPartition.SubsetSumToPartitionReduction}
\label{SubsetSumToPartition.SubsetSumToPartitionReduction}
\leanok
\uses{SubsetSumToPartition.Partition, SubsetSumToPartition.SubsetSum, SubsetSumToPartition.SubsetSumToPartitionCompleteness, SubsetSumToPartition.SubsetSumToPartitionSoundness, SubsetSumToPartition.partitionWeight}

For $w : U \to \mathbb{N}$ and $T \in \mathbb{N}$ with $T \le \sum_{a} w(a)$, the Subset
Sum instance $(w, T)$ is solvable if and only if the Partition instance with weight
function $\texttt{SubsetSumToPartition.partitionWeight}\ w\ T$ on $U \oplus \mathrm{Bool}$
is solvable.
\end{theorem}

n21376.content:
\begin{definition}[Pure computation in the time monad]
\lean{TimeM.pure}
\label{TimeM.pure}
\leanok
Lifts a value $a : \alpha$ into the computation $\langle a, 0\rangle$ of type \texttt{TimeM T α},
i.e.\ the computation that returns $a$ at zero time cost.
\end{definition}

n21377.content:
\begin{definition}[Sequential composition in the time monad]
\lean{TimeM.bind}
\label{TimeM.bind}
\leanok
Given $m : \texttt{TimeM T α}$ and $f : \alpha \to \texttt{TimeM T β}$, the bind of $m$ and $f$
runs $f$ on the value returned by $m$ and returns $\langle (f\,m.\mathrm{ret}).\mathrm{ret},\;
m.\mathrm{time} + (f\,m.\mathrm{ret}).\mathrm{time}\rangle$: the two time costs are added.
\end{definition}

n21378.content:
\begin{theorem}[Return value of \texttt{pure}]
\lean{TimeM.ret_pure}
\label{TimeM.ret_pure}
\leanok

The value returned by $\mathrm{pure}\,a$ is $a$.
\end{theorem}

n21379.content:
\begin{theorem}[Return value of a bind]
\lean{TimeM.ret_bind}
\label{TimeM.ret_bind}
\leanok

The value returned by the bind of $m$ with $f$ is the value returned by $f\,m.\mathrm{ret}$.
\end{theorem}

n21380.content:
\begin{theorem}[Return value of a map]
\lean{TimeM.ret_map}
\label{TimeM.ret_map}
\leanok

For $f : \alpha \to \beta$ and $x : \texttt{TimeM T α}$, the value returned by the mapped
computation is $f(x.\mathrm{ret})$.
\end{theorem}

n21381.content:
\begin{theorem}[Return value of \texttt{seqRight}]
\lean{TimeM.ret_seqRight}
\label{TimeM.ret_seqRight}
\leanok

The right-sequencing of $x$ and $y$ returns the value returned by $y\,()$.
\end{theorem}

n21382.content:
\begin{theorem}[Return value of \texttt{seqLeft}]
\lean{TimeM.ret_seqLeft}
\label{TimeM.ret_seqLeft}
\leanok

The left-sequencing of $x$ and $y$ returns $x.\mathrm{ret}$.
\end{theorem}

n21383.content:
\begin{theorem}[Return value of \texttt{seq}]
\lean{TimeM.ret_seq}
\label{TimeM.ret_seq}
\leanok

For $f : \texttt{TimeM T (α → β)}$ and $x : \texttt{Unit → TimeM T α}$, the application
$\mathrm{seq}\,f\,x$ returns $f.\mathrm{ret}\bigl((x\,()).\mathrm{ret}\bigr)$.
\end{theorem}

n21384.content:
\begin{theorem}[Time cost of a bind]
\lean{TimeM.time_bind}
\label{TimeM.time_bind}
\leanok

The time cost of the bind of $m$ with $f$ is $m.\mathrm{time} + (f\,m.\mathrm{ret}).\mathrm{time}$.
\end{theorem}

n21385.content:
\begin{theorem}[Time cost of \texttt{pure}]
\lean{TimeM.time_pure}
\label{TimeM.time_pure}
\leanok

The time cost of $\mathrm{pure}\,a$ is $0$.
\end{theorem}

n21386.content:
\begin{theorem}[Time cost of a map]
\lean{TimeM.time_map}
\label{TimeM.time_map}
\leanok

Mapping a function over a computation does not change its time cost: it is $x.\mathrm{time}$.
\end{theorem}

n21387.content:
\begin{theorem}[Time cost of \texttt{seqRight}]
\lean{TimeM.time_seqRight}
\label{TimeM.time_seqRight}
\leanok

The time cost of the right-sequencing of $x$ and $y$ is $x.\mathrm{time} + (y\,()).\mathrm{time}$.
\end{theorem}

n21388.content:
\begin{theorem}[Time cost of \texttt{seqLeft}]
\lean{TimeM.time_seqLeft}
\label{TimeM.time_seqLeft}
\leanok

The time cost of the left-sequencing of $x$ and $y$ is $x.\mathrm{time} + (y\,()).\mathrm{time}$.
\end{theorem}

n21389.content:
\begin{theorem}[Time cost of \texttt{seq}]
\lean{TimeM.time_seq}
\label{TimeM.time_seq}
\leanok

The time cost of $\mathrm{seq}\,f\,x$ is $f.\mathrm{time} + (x\,()).\mathrm{time}$.
\end{theorem}

n21390.content:
\begin{definition}[Tick]
\lean{TimeM.tick}
\label{TimeM.tick}
\leanok
The computation $\mathrm{tick}\,c$ returns the trivial value and records time cost $c$; it is the
basic way of charging $c$ units of time.
\end{definition}

n21391.content:
\begin{theorem}[Return value of a tick]
\lean{TimeM.ret_tick}
\label{TimeM.ret_tick}
\leanok
\uses{TimeM.tick}

The value returned by $\mathrm{tick}\,c$ is the unit value.
\end{theorem}

n21392.content:
\begin{theorem}[Time cost of a tick]
\lean{TimeM.time_tick}
\label{TimeM.time_tick}
\leanok
\uses{TimeM.tick}

The time cost of $\mathrm{tick}\,c$ is $c$.
\end{theorem}

n21393.content:
\begin{definition}[Maximum of two naturals, timed]
\lean{max2}
\label{max2}
\leanok
The timed computation returning the larger of two natural numbers $x,y$, charging one unit of
time for the single comparison $x \le y$.
\end{definition}

n21394.content:
\begin{definition}[Median of three, timed]
\lean{median3}
\label{median3}
\leanok
For $a,b,c$ in a linear order, the timed computation returning a median of $a,b,c$ by a nested
sequence of comparisons, charging one unit of time per comparison performed.
\end{definition}

n21395.content:
\begin{theorem}[Correctness of the timed median]
\lean{median3_correct}
\label{median3_correct}
\leanok
\uses{median3}

The value returned by $\mathrm{median3}\,a\,b\,c$ is a median of $a$, $b$, $c$, in the sense that
it lies between at least one of the pairs drawn from $\{a,b,c\}$.
\end{theorem}

n21396.content:
\begin{theorem}[Comparison count of the timed median]
\lean{median3_time}
\label{median3_time}
\leanok
\uses{median3}

The computation $\mathrm{median3}\,a\,b\,c$ records a time cost of at most $3$, i.e.\ it performs
at most three comparisons.
\end{theorem}

n21397.content:
\begin{definition}[Timed ordered insertion]
\lean{insert}
\label{insert}
\leanok
Inserts $x$ into a list, walking the list until the first element $y$ with $x \le y$ and charging
one unit of time per comparison. On a sorted input it produces the sorted list containing $x$.
\end{definition}

n21398.content:
\begin{definition}[Timed insertion sort]
\lean{insertionSort}
\label{insertionSort}
\leanok
\uses{insert}
Insertion sort in the time monad: recursively sort the tail and then insert the head using the
timed insertion, accumulating the comparisons performed by every insertion step.
\end{definition}

n21399.content:
\begin{definition}[Sortedness by adjacent pairs]
\lean{IsSorted}
\label{IsSorted}
\leanok
The predicate on lists defined recursively: the empty list and singletons are sorted, and
$x :: y :: \mathit{rest}$ is sorted when $x \le y$ and $y :: \mathit{rest}$ is sorted.
\end{definition}

n21400.content:
\begin{theorem}[Adjacent sortedness is a chain]
\lean{isSorted_iff_isChain}
\label{isSorted_iff_isChain}
\leanok
\uses{IsSorted}

For any list $\mathit{xs}$, the predicate \texttt{IsSorted} holds of $\mathit{xs}$ if and only if
$\mathit{xs}$ is a chain for $\le$.
\end{theorem}

n21401.content:
\begin{theorem}[Adjacent sortedness equals pairwise sortedness]
\lean{isSorted_iff_sorted}
\label{isSorted_iff_sorted}
\leanok
\uses{IsSorted, isSorted_iff_isChain}

For any list $\mathit{xs}$, the predicate \texttt{IsSorted} holds of $\mathit{xs}$ if and only if
$\mathit{xs}$ is sorted in the usual pairwise sense with respect to $\le$.
\end{theorem}

n21402.content:
\begin{theorem}[Value returned by the timed insertion]
\lean{ret_insert}
\label{ret_insert}
\leanok
\uses{insert}

The value returned by the timed insertion of $x$ into $\mathit{xs}$ is the ordinary ordered
insertion of $x$ into $\mathit{xs}$ for the relation $\le$.
\end{theorem}

n21403.content:
\begin{theorem}[Value returned by the timed insertion sort]
\lean{ret_insertionSort}
\label{ret_insertionSort}
\leanok
\uses{insertionSort, ret_insert}

The value returned by the timed insertion sort of $\mathit{xs}$ is the ordinary insertion sort of
$\mathit{xs}$ for the relation $\le$.
\end{theorem}

n21404.content:
\begin{theorem}[Length after a timed insertion]
\lean{length_ret_insert}
\label{length_ret_insert}
\leanok
\uses{insert, ret_insert}

The list returned by inserting $x$ into $\mathit{xs}$ has length $\left\lvert \mathit{xs}\right\rvert + 1$.
\end{theorem}

n21405.content:
\begin{theorem}[Length after a timed insertion sort]
\lean{length_ret_insertionSort}
\label{length_ret_insertionSort}
\leanok
\uses{insertionSort, ret_insertionSort}

The list returned by the timed insertion sort of $\mathit{xs}$ has the same length as
$\mathit{xs}$.
\end{theorem}

n21406.content:
\begin{theorem}[Timed insertion is a permutation]
\lean{insert_perm}
\label{insert_perm}
\leanok
\uses{insert, ret_insert}

The list returned by inserting $x$ into $\mathit{xs}$ is a permutation of $x :: \mathit{xs}$.
\end{theorem}

n21407.content:
\begin{theorem}[Timed insertion preserves sortedness]
\lean{insert_sorted}
\label{insert_sorted}
\leanok
\uses{IsSorted, insert, isSorted_iff_sorted, ret_insert}

If $\mathit{xs}$ is sorted, then the list returned by inserting $x$ into $\mathit{xs}$ is sorted.
\end{theorem}

n21408.content:
\begin{theorem}[Timed insertion sort is a permutation]
\lean{insertionSort_perm}
\label{insertionSort_perm}
\leanok
\uses{insertionSort, ret_insertionSort}

The list returned by the timed insertion sort of $\mathit{xs}$ is a permutation of $\mathit{xs}$.
\end{theorem}

n21409.content:
\begin{theorem}[Timed insertion sort returns a sorted list]
\lean{insertionSort_sorted}
\label{insertionSort_sorted}
\leanok
\uses{IsSorted, insertionSort, isSorted_iff_sorted, ret_insertionSort}

For every list $\mathit{xs}$, the list returned by the timed insertion sort is sorted.
\end{theorem}

n21410.content:
\begin{theorem}[Functional correctness of insertion sort]
\lean{insertionSort_correct}
\label{insertionSort_correct}
\leanok
\uses{IsSorted, insertionSort, insertionSort_perm, insertionSort_sorted}

For every list $\mathit{xs}$, the output of the timed insertion sort is both sorted and a
permutation of $\mathit{xs}$.
\end{theorem}

n21411.content:
\begin{definition}[Insertion sort recurrence]
\lean{timeInsertionSortRec}
\label{timeInsertionSortRec}
\leanok
The worst-case comparison recurrence $T(0) = 0$ and $T(n+1) = T(n) + n$.
\end{definition}

n21412.content:
\begin{theorem}[Cost of one insertion]
\lean{time_insert_le}
\label{time_insert_le}
\leanok
\uses{insert}

Inserting $x$ into a list $\mathit{xs}$ costs at most $\left\lvert \mathit{xs}\right\rvert$ comparisons.
\end{theorem}

n21413.content:
\begin{theorem}[Insertion sort meets its recurrence]
\lean{time_insertionSort_le_rec}
\label{time_insertionSort_le_rec}
\leanok
\uses{insert, insertionSort, ret_insertionSort, timeInsertionSortRec, time_insert_le}

The time cost recorded by the timed insertion sort of $\mathit{xs}$ is at most
$T(\left\lvert \mathit{xs}\right\rvert)$, where $T$ is the insertion sort recurrence.
\end{theorem}

n21414.content:
\begin{theorem}[Quadratic bound for the recurrence]
\lean{timeInsertionSortRec_le_sq}
\label{timeInsertionSortRec_le_sq}
\leanok
\uses{timeInsertionSortRec}

For every $n$, the recurrence satisfies $T(n) \le n^2$.
\end{theorem}

n21415.content:
\begin{theorem}[Insertion sort performs at most $n^2$ comparisons]
\lean{time_insertionSort_le_sq}
\label{time_insertionSort_le_sq}
\leanok
\uses{insertionSort, timeInsertionSortRec_le_sq, time_insertionSort_le_rec}

The time cost recorded by the timed insertion sort of a list $\mathit{xs}$ of length $n$ is at
most $n^2$.
\end{theorem}

n21416.content:
\begin{lemma}[Core RSA exponent identity]
\lean{RSA.rsa_core}
\label{RSA.rsa_core}
\leanok

Let $p$ be prime. For every $c \in \mathbb{N}$ and every $x \in \mathbb{Z}/p\mathbb{Z}$,
\[
x^{\,1 + c(p-1)} = x .
\]
This is the form of Fermat's little theorem needed for RSA, valid also at $x = 0$.
\end{lemma}

n21417.content:
\begin{lemma}[RSA identity from an exponent factorization]
\lean{RSA.rsa_zmod_of_factor}
\label{RSA.rsa_zmod_of_factor}
\leanok
\uses{RSA.rsa_core}

Let $p$ be prime and $m, ed, c \in \mathbb{N}$ with $ed = 1 + c(p-1)$. Then $m^{ed} \equiv m$ in
$\mathbb{Z}/p\mathbb{Z}$, where both sides are the images of natural numbers.
\end{lemma}

n21418.content:
\begin{lemma}[RSA identity modulo $p$]
\lean{RSA.rsa_zmod_p}
\label{RSA.rsa_zmod_p}
\leanok
\uses{RSA.rsa_zmod_of_factor}

If $p$ is prime and $ed = 1 + k(p-1)(q-1)$, then $m^{ed} \equiv m$ in $\mathbb{Z}/p\mathbb{Z}$ for every
$m \in \mathbb{N}$.
\end{lemma}

n21419.content:
\begin{lemma}[RSA identity modulo $q$]
\lean{RSA.rsa_zmod_q}
\label{RSA.rsa_zmod_q}
\leanok
\uses{RSA.PublicKey, RSA.rsa_zmod_of_factor}

If $q$ is prime and $ed = 1 + k(p-1)(q-1)$, then $m^{ed} \equiv m$ in $\mathbb{Z}/q\mathbb{Z}$ for every
$m \in \mathbb{N}$.
\end{lemma}

n21420.content:
\begin{lemma}[Combining the two factors by CRT]
\lean{RSA.rsa_crt}
\label{RSA.rsa_crt}
\leanok
\uses{RSA.PublicKey}

Let $p$ and $q$ be coprime and suppose $m^{ed} \equiv m$ both in $\mathbb{Z}/p\mathbb{Z}$ and in
$\mathbb{Z}/q\mathbb{Z}$. Then $m^{ed} \equiv m$ in $\mathbb{Z}/pq\mathbb{Z}$.
\end{lemma}

n21421.content:
\begin{lemma}[CRT combination in power form]
\lean{RSA.rsa_crt_pow}
\label{RSA.rsa_crt_pow}
\leanok
\uses{RSA.PublicKey, RSA.rsa_crt}

The same statement written with the power taken inside the quotient ring: if $p$ and $q$ are
coprime and $\bar m^{\,ed} = \bar m$ in $\mathbb{Z}/p\mathbb{Z}$ and in $\mathbb{Z}/q\mathbb{Z}$, then
$\bar m^{\,ed} = \bar m$ in $\mathbb{Z}/pq\mathbb{Z}$.
\end{lemma}

n21422.content:
\begin{definition}[RSA public key]
\lean{RSA.PublicKey}
\label{RSA.PublicKey}
\leanok
A public key consists of a modulus $n \in \mathbb{N}$ and a public exponent $e \in \mathbb{N}$.
\end{definition}

n21423.content:
\begin{definition}[RSA secret key]
\lean{RSA.SecretKey}
\label{RSA.SecretKey}
\leanok
\uses{RSA.PublicKey}
A secret key consists of a public key together with naturals $p, q, d, k$ and proofs that $p$ and
$q$ are prime, that $p \ne q$, that the public modulus satisfies $n = pq$, and that the exponents
satisfy $e d = 1 + k(p-1)(q-1)$.
\end{definition}

n21424.content:
\begin{definition}[RSA encryption]
\lean{RSA.encrypt}
\label{RSA.encrypt}
\leanok
\uses{RSA.PublicKey}
Encryption of a message $m \in \mathbb{N}$ under a public key is $\bar m^{\,e} \in \mathbb{Z}/n\mathbb{Z}$, using
only the public data.
\end{definition}

n21425.content:
\begin{definition}[RSA decryption]
\lean{RSA.decrypt}
\label{RSA.decrypt}
\leanok
\uses{RSA.SecretKey}
Decryption of a ciphertext $c \in \mathbb{Z}/n\mathbb{Z}$ under a secret key is $c^{\,d}$, where $d$ is the
private exponent.
\end{definition}

n21426.content:
\begin{theorem}[Correctness of RSA]
\lean{RSA.rsa_correctness}
\label{RSA.rsa_correctness}
\leanok
\uses{RSA.SecretKey, RSA.decrypt, RSA.encrypt, RSA.rsa_crt_pow, RSA.rsa_zmod_p, RSA.rsa_zmod_q}

For any secret key and any message $m \in \mathbb{N}$, decrypting the encryption of $m$ recovers $m$:
\[
\bigl(\bar m^{\,e}\bigr)^{d} = \bar m \quad \text{in } \mathbb{Z}/n\mathbb{Z}.
\]
\end{theorem}

n21427.content:
\begin{definition}[Multigraph]
\lean{Multigraph}
\label{Multigraph}
\leanok
A multigraph on a vertex type $\alpha$ consists of a finite vertex set together with a
multiset of unordered pairs (elements of $\mathrm{Sym}_2\,\alpha$) as edges, subject to
two conditions: every endpoint of every edge is a live vertex, and no edge is a
self-loop (edges are loopless, since loops are deleted after each contraction).
\end{definition}

n21428.content:
\begin{definition}[Edge count of a multigraph]
\lean{Multigraph.edgeCount}
\label{Multigraph.edgeCount}
\leanok
\uses{Multigraph}
The number of edges of $G$ counted with multiplicity, i.e.\ the cardinality of the
edge multiset.
\end{definition}

n21429.content:
\begin{definition}[Vertex count of a multigraph]
\lean{Multigraph.vertexCount}
\label{Multigraph.vertexCount}
\leanok
\uses{Multigraph}
The number of vertices of $G$, i.e.\ the cardinality of its vertex \texttt{Finset}.
\end{definition}

n21430.content:
\begin{definition}[Contraction of an edge]
\lean{Multigraph.contract}
\label{Multigraph.contract}
\leanok
\uses{Multigraph}
Given an edge $e \in E(G)$ with endpoints $u$ and $v$, the contracted multigraph
$G/e$ is obtained by replacing every occurrence of $v$ by $u$ in all edges, deleting
the resulting self-loops (in particular all parallel copies of $e$), and removing $v$
from the vertex set. Parallel edges between the merged vertex and the rest of the graph
are retained with multiplicity.
\end{definition}

n21431.content:
\begin{lemma}[Contraction drops the vertex count by one]
\lean{contract_vertex_count}
\label{contract_vertex_count}
\leanok
\uses{Multigraph, Multigraph.contract, Multigraph.vertexCount}

If $e \in E(G)$ is not a diagonal (self-loop) pair, then
\[
  \left\lvert V(G/e)\right\rvert = \left\lvert V(G)\right\rvert - 1 .
\]
\end{lemma}

n21432.content:
\begin{lemma}[Contraction drops at least one edge]
\lean{contract_edge_count_le}
\label{contract_edge_count_le}
\leanok
\uses{Multigraph, Multigraph.contract, Multigraph.edgeCount}

For every edge $e \in E(G)$, the contracted multigraph satisfies
\[
  \left\lvert E(G/e)\right\rvert \le \left\lvert E(G)\right\rvert - 1 ,
\]
so contraction never increases the edge count and removes at least the contracted edge.
\end{lemma}

n21433.content:
\begin{definition}[Cut of a multigraph]
\lean{MulCut}
\label{MulCut}
\leanok
\uses{Multigraph}
A cut of $G$ is a subset $S \subseteq V(G)$ that is nonempty and whose complement
$V(G) \setminus S$ inside $V(G)$ is also nonempty; the two nonemptiness conditions rule
out the trivial partitions.
\end{definition}

n21434.content:
\begin{definition}[Crossing edges of a cut]
\lean{MulCut.crossingEdges}
\label{MulCut.crossingEdges}
\leanok
\uses{MulCut, Multigraph}
The multiset of edges of $G$ that cross the cut $C$, i.e.\ those edges having exactly
one endpoint in $S$, counted with multiplicity. It is obtained by filtering the edge
multiset by the condition that exactly one of the two representative endpoints lies
in $S$.
\end{definition}

n21435.content:
\begin{definition}[Crossing predicate for an unordered edge]
\lean{Crosses}
\label{Crosses}
\leanok
For a finite set $S$ and an unordered pair $e$, the predicate $\texttt{Crosses}\;S\;e$
holds when some element of $e$ lies in $S$ and some element of $e$ lies outside $S$.
This is a membership-based formulation independent of a choice of representative.
\end{definition}

n21436.content:
\begin{lemma}[Crossing in terms of chosen representatives]
\lean{crosses_iff_out}
\label{crosses_iff_out}
\leanok
\uses{Crosses}

For every finite set $S$ and unordered pair $e$, the predicate $\texttt{Crosses}\;S\;e$
holds if and only if, writing $(x, y)$ for the chosen representative of $e$, either
$x \in S$ and $y \notin S$, or $x \notin S$ and $y \in S$.
\end{lemma}

n21437.content:
\begin{lemma}[Crossing edges as a filter by the crossing predicate]
\lean{crossingEdges_eq_filter_crosses}
\label{crossingEdges_eq_filter_crosses}
\leanok
\uses{Crosses, MulCut, MulCut.crossingEdges, Multigraph, crosses_iff_out}

For every cut $C$ of $G$, the multiset of crossing edges equals the edge multiset of
$G$ filtered by the predicate $\texttt{Crosses}\;S$.
\end{lemma}

n21438.content:
\begin{definition}[Size of a cut]
\lean{MulCut.size}
\label{MulCut.size}
\leanok
\uses{MulCut, MulCut.crossingEdges, Multigraph}
The size of a cut $C$ is the number of crossing edges, counted with multiplicity.
\end{definition}

n21439.content:
\begin{definition}[Minimum cut]
\lean{IsMulMinCut}
\label{IsMulMinCut}
\leanok
\uses{MulCut, MulCut.size, Multigraph}
A cut $C$ of $G$ is a minimum cut when its size is at most the size of every cut $C'$
of $G$.
\end{definition}

n21440.content:
\begin{definition}[Cut induced on a contracted multigraph]
\lean{MulCut.contractedCut}
\label{MulCut.contractedCut}
\leanok
\uses{MulCut, MulCut.crossingEdges, Multigraph, Multigraph.contract}
If $e \in E(G)$ does not cross the cut $C$, then $C$ induces a cut of the contracted
multigraph $G/e$: the vertex side is the image of $S$ after merging the endpoints of
$e$, and both nonemptiness conditions continue to hold because $e$ has both endpoints
on the same side.
\end{definition}

n21441.content:
\begin{lemma}[Non-crossing contraction preserves cut size]
\lean{cut_size_preserved}
\label{cut_size_preserved}
\leanok
\uses{Crosses, MulCut, MulCut.contractedCut, MulCut.crossingEdges, MulCut.size, Multigraph, Multigraph.contract, crosses_iff_out, crossingEdges_eq_filter_crosses}

If $e \in E(G)$ does not cross the cut $C$, then the induced cut on $G/e$ has the same
size as $C$:
\[
  \left\lvert \text{cut } C \text{ in } G/e\right\rvert = \left\lvert C\right\rvert .
\]
\end{lemma}

n21442.content:
\begin{lemma}[Non-crossing contraction preserves minimality]
\lean{mincut_preserved_of_non_crossing}
\label{mincut_preserved_of_non_crossing}
\leanok
\uses{IsMulMinCut, MulCut, MulCut.contractedCut, MulCut.crossingEdges, MulCut.size, Multigraph, Multigraph.contract, count_bind_endpoints_eq_card_filter, crossingEdges_eq_filter_crosses, cut_size_preserved}

If $C$ is a minimum cut of $G$ and $e \in E(G)$ does not cross $C$, then the induced cut
on $G/e$ is again a minimum cut. Thus only crossing edges can destroy a fixed minimum
cut during contraction.
\end{lemma}

n21443.content:
\begin{definition}[One contraction step of Karger's algorithm]
\lean{kargerStep}
\label{kargerStep}
\leanok
\uses{Multigraph, Multigraph.contract, Multigraph.edgeCount}
Given a multigraph $G$ with at least one edge, a step of the algorithm is modelled as a
function from an index $i \in \mathrm{Fin}\,\left\lvert E(G)\right\rvert$ — thought of as a uniformly
random edge choice — to the multigraph obtained by contracting the $i$-th edge of $G$.
\end{definition}

n21444.content:
\begin{definition}[A full contraction run]
\lean{kargerRun}
\label{kargerRun}
\leanok
\uses{Multigraph, Multigraph.edgeCount, Multigraph.vertexCount}
A run of the algorithm on $G_0$ is indexed by a sequence of edge choices, one for each
of the $\left\lvert V(G_0)\right\rvert - 2$ contraction steps, and produces a multigraph. The current
Lean definition is a placeholder that returns $G_0$; the state-threading version is not
yet formalized.
\end{definition}

n21445.content:
\begin{definition}[Termination condition of the algorithm]
\lean{KargerOutput}
\label{KargerOutput}
\leanok
\uses{Multigraph, Multigraph.vertexCount}
The predicate stating that $G$ is a valid output of the algorithm, namely that it has
exactly two vertices; its remaining edges are then exactly the edges of the output cut.
\end{definition}

n21446.content:
\begin{definition}[Degree of a vertex]
\lean{Multigraph.degree}
\label{Multigraph.degree}
\leanok
\uses{Multigraph}
The degree of $v$ in a loopless multigraph $G$ is the number of edges incident to $v$,
counted with multiplicity.
\end{definition}

n21447.content:
\begin{lemma}[Membership in an unordered pair identifies a representative]
\lean{eq_out_or_eq_out_of_mem}
\label{eq_out_or_eq_out_of_mem}
\leanok

If $z$ belongs to the unordered pair $e$, then $z$ equals one of the two components of
the chosen representative of $e$.
\end{lemma}

n21448.content:
\begin{lemma}[Endpoint multiplicity equals incidence count]
\lean{count_bind_endpoints_eq_card_filter}
\label{count_bind_endpoints_eq_card_filter}
\leanok

For a multiset $m$ of unordered pairs and a vertex $v$, the multiplicity of $v$ in the
multiset obtained by binding each edge to its set of endpoints equals the number of
edges of $m$ containing $v$.
\end{lemma}

n21449.content:
\begin{lemma}[Singleton cut has size equal to the degree]
\lean{singleton_cut_size_eq_degree}
\label{singleton_cut_size_eq_degree}
\leanok
\uses{MulCut, MulCut.crossingEdges, MulCut.size, Multigraph, Multigraph.degree, crosses_iff_out, crossingEdges_eq_filter_crosses, eq_out_or_eq_out_of_mem}

Let $v \in V(G)$ be a vertex such that $V(G) \setminus \{v\}$ is nonempty. Then the cut
given by $S = \{v\}$ is a legitimate cut of $G$ and its size equals $\deg(v)$.
\end{lemma}

n21450.content:
\begin{lemma}[Removing a vertex leaves a nonempty vertex set]
\lean{erase_nonempty_of_cut}
\label{erase_nonempty_of_cut}
\leanok
\uses{MulCut, Multigraph}

If $G$ admits a cut $C$, then for every vertex $v$ the set $V(G) \setminus \{v\}$ is
nonempty, since both sides of $C$ are nonempty.
\end{lemma}

n21451.content:
\begin{lemma}[Min-cut size is at most every degree]
\lean{mincut_le_degree}
\label{mincut_le_degree}
\leanok
\uses{IsMulMinCut, MulCut, MulCut.size, Multigraph, Multigraph.degree, erase_nonempty_of_cut, singleton_cut_size_eq_degree}

If $C$ is a minimum cut of $G$ and $v \in V(G)$, then $\left\lvert C\right\rvert \le \deg(v)$: otherwise
the singleton cut at $v$ would be smaller.
\end{lemma}

n21452.content:
\begin{lemma}[Endpoints of edges are vertices]
\lean{endpoints_mem_vertices}
\label{endpoints_mem_vertices}
\leanok
\uses{Multigraph}

Any $x$ occurring in the multiset of all edge endpoints of $G$ belongs to $V(G)$.
\end{lemma}

n21453.content:
\begin{lemma}[Summing multiplicities over a covering set]
\lean{sum_counts_eq_card_of_subset}
\label{sum_counts_eq_card_of_subset}
\leanok

If every element of a multiset $m$ lies in the finite set $s$, then
\[
  \sum_{a \in s} \mathrm{count}_m(a) = \left\lvert m\right\rvert .
\]
\end{lemma}

n21454.content:
\begin{lemma}[Handshake lemma]
\lean{sum_degrees_eq_twice_edgeCount}
\label{sum_degrees_eq_twice_edgeCount}
\leanok
\uses{Multigraph, Multigraph.degree, Multigraph.edgeCount, count_bind_endpoints_eq_card_filter, endpoints_mem_vertices, sum_counts_eq_card_of_subset}

For every multigraph $G$,
\[
  \sum_{v \in V(G)} \deg(v) = 2\left\lvert E(G)\right\rvert .
\]
\end{lemma}

n21455.content:
\begin{lemma}[Edge count lower bound from a minimum degree]
\lean{edge_count_lower_bound}
\label{edge_count_lower_bound}
\leanok
\uses{Multigraph, Multigraph.degree, Multigraph.edgeCount, Multigraph.vertexCount, sum_degrees_eq_twice_edgeCount}

If every vertex of $G$ has degree at least $k$, then
\[
  k \cdot \left\lvert V(G)\right\rvert \le 2\left\lvert E(G)\right\rvert .
\]
\end{lemma}

n21456.content:
\begin{definition}[Survival probability of one step]
\lean{survivalProb}
\label{survivalProb}
\leanok
For a cut size $c$ and a current edge count $m$, the probability that a uniformly chosen
edge is not one of the $c$ cut edges, namely
\[
  1 - \frac{c}{m}.
\]
\end{definition}

n21457.content:
\begin{lemma}[Edge count invariant along the algorithm]
\lean{edge_count_invariant}
\label{edge_count_invariant}
\leanok
\uses{IsMulMinCut, MulCut, MulCut.size, Multigraph, Multigraph.edgeCount, Multigraph.vertexCount, edge_count_lower_bound, mincut_le_degree}

Let $C_0$ be a minimum cut of $G_0$ and let $i < \left\lvert V(G_0)\right\rvert - 1$. Then
\[
  \left\lvert C_0\right\rvert \cdot \bigl(\left\lvert V(G_0)\right\rvert - i\bigr) \le 2\left\lvert E(G_0)\right\rvert ,
\]
the invariant maintained after $i$ contraction steps.
\end{lemma}

n21459.content:
\begin{theorem}[Survival probability of a fixed min-cut]
\lean{karger_survival_prob_algorithmic}
\label{karger_survival_prob_algorithmic}
\leanok
\uses{IsMulMinCut, MulCut, Multigraph, Multigraph.vertexCount, telescope_prod}

Let $C$ be a minimum cut of a multigraph $G$ with $n = \left\lvert V(G)\right\rvert \ge 4$. Then the
telescoping product of per-step survival factors, which represents the probability that
none of the $n-2$ contractions picks a cut edge, is bounded below by
\[
  \frac{2}{n(n-1)} \;\le\; \prod_{i=0}^{n-3} \frac{n - i - 2}{n - i} .
\]
\end{theorem}

n21460.content:
\begin{theorem}[Repetition succeeds with high probability]
\lean{karger_whp}
\label{karger_whp}
\leanok
\uses{Multigraph, Multigraph.vertexCount}

Let $n = \left\lvert V(G)\right\rvert \ge 4$. Repeating the algorithm $n(n-1)/2$ independent times, the
success probability satisfies
\[
  1 - \left(1 - \frac{2}{n(n-1)}\right)^{n(n-1)/2} \;\ge\; 1 - e^{-1} .
\]
\end{theorem}

n21461.content:
\begin{lemma}[Counting disjoint events of large probability]
\lean{card_le_of_disjoint_prob_lb}
\label{card_le_of_disjoint_prob_lb}
\leanok

If $p > 0$ and $m \cdot p \le 1$ (as is the case for $m$ disjoint events each of
probability at least $p$), then $m \le p^{-1}$.
\end{lemma}

n21462.content:
\begin{lemma}[Closed form for $\binom{n}{2}$]
\lean{choose_two}
\label{choose_two}
\leanok

For $n \ge 2$,
\[
  \binom{n}{2} = \frac{n(n-1)}{2}
\]
as real numbers.
\end{lemma}

n21463.content:
\begin{lemma}[Polynomial bound on a binomial coefficient]
\lean{choose_le_pow}
\label{choose_le_pow}
\leanok

For all $n$ and $\alpha$, $\binom{n}{2\alpha} \le n^{2\alpha}$.
\end{lemma}

n21464.content:
\begin{theorem}[At most $\binom{n}{2}$ minimum cuts]
\lean{num_mincuts_le_choose}
\label{num_mincuts_le_choose}
\leanok
\uses{Multigraph, Multigraph.vertexCount, card_le_of_disjoint_prob_lb, choose_two}

Let $n = \left\lvert V(G)\right\rvert \ge 2$. If a family of $\mathrm{numCuts}$ cuts is disjoint in the
sense that $\mathrm{numCuts} \cdot \frac{2}{n(n-1)} \le 1$, then
\[
  \mathrm{numCuts} \le \binom{n}{2} .
\]
\end{theorem}

n21465.content:
\begin{theorem}[At most $n^{2\alpha}$ approximate minimum cuts]
\lean{num_alpha_mincuts_le}
\label{num_alpha_mincuts_le}
\leanok
\uses{Multigraph, Multigraph.vertexCount, card_le_of_disjoint_prob_lb, choose_le_pow}

Let $\alpha > 0$ with $2\alpha \le n = \left\lvert V(G)\right\rvert$. If a family of $\mathrm{numCuts}$
$\alpha$-minimum cuts satisfies
$\mathrm{numCuts} \cdot \binom{n}{2\alpha}^{-1} \le 1$, then
\[
  \mathrm{numCuts} \le n^{2\alpha} .
\]
\end{theorem}

n21466.content:
\begin{definition}[State of the contraction process]
\lean{KargerTrace.State}
\label{KargerTrace.State}
\leanok
\uses{MulCut, Multigraph}
A state consists of a multigraph $G$ over $\alpha$ together with a distinguished cut $C$
of $G$.  It records the current graph of the algorithm and the cut whose survival is
being tracked.
\end{definition}

n21467.content:
\begin{definition}[Contraction of a state along a non-crossing edge]
\lean{KargerTrace.contractState}
\label{KargerTrace.contractState}
\leanok
\uses{KargerTrace.State, MulCut.contractedCut, MulCut.crossingEdges, Multigraph.contract}
Given a state $s$, an edge $e$ of $s.G$ that does not cross the distinguished cut $s.C$,
the contracted state has graph $s.G$ contracted along $e$ and cut the corresponding
contracted cut.
\end{definition}

n21468.content:
\begin{definition}[Surviving step]
\lean{KargerTrace.SurvivingStep}
\label{KargerTrace.SurvivingStep}
\leanok
\uses{KargerTrace.State, KargerTrace.contractState, MulCut.crossingEdges}
The relation asserting that state $t$ arises from state $s$ by contracting some edge $e$
of $s.G$ that does not cross the distinguished cut of $s$.
\end{definition}

n21469.content:
\begin{definition}[Surviving run]
\lean{KargerTrace.SurvivingRun}
\label{KargerTrace.SurvivingRun}
\leanok
\uses{KargerTrace.State, KargerTrace.SurvivingStep}
The inductively defined relation of $n$ consecutive surviving steps leading from a state
$s$ to a state $t$: the empty run has $n = 0$ and $t = s$, and a run of length $n+1$ is a
run of length $n$ followed by one surviving step.
\end{definition}

n21470.content:
\begin{lemma}[Positive edge count from an edge]
\lean{KargerTrace.edgeCount_pos_of_mem}
\label{KargerTrace.edgeCount_pos_of_mem}
\leanok
\uses{Multigraph, Multigraph.edgeCount}

If $e$ is an edge of a multigraph $G$, then $G$ has positive edge count.
\end{lemma}

n21471.content:
\begin{lemma}[A surviving step preserves cut size]
\lean{KargerTrace.survivingStep_cut_size_eq}
\label{KargerTrace.survivingStep_cut_size_eq}
\leanok
\uses{KargerTrace.State, KargerTrace.SurvivingStep, MulCut.size, cut_size_preserved}

If $t$ is obtained from $s$ by a surviving step, then the distinguished cuts have the same
size: $t.C.\mathrm{size} = s.C.\mathrm{size}$.
\end{lemma}

n21472.content:
\begin{lemma}[A surviving step preserves minimality]
\lean{KargerTrace.survivingStep_mincut}
\label{KargerTrace.survivingStep_mincut}
\leanok
\uses{IsMulMinCut, KargerTrace.State, KargerTrace.SurvivingStep, mincut_preserved_of_non_crossing}

If $t$ is obtained from $s$ by a surviving step and $s.C$ is a min-cut of $s.G$, then
$t.C$ is a min-cut of $t.G$.
\end{lemma}

n21473.content:
\begin{lemma}[A surviving step removes one vertex]
\lean{KargerTrace.survivingStep_vertexCount_eq}
\label{KargerTrace.survivingStep_vertexCount_eq}
\leanok
\uses{KargerTrace.State, KargerTrace.SurvivingStep, KargerTrace.contractState, Multigraph.vertexCount, contract_vertex_count}

If $t$ is obtained from $s$ by a surviving step, then $t.G$ has exactly one vertex fewer
than $s.G$.
\end{lemma}

n21474.content:
\begin{lemma}[A surviving step requires an edge]
\lean{KargerTrace.survivingStep_edgeCount_pos}
\label{KargerTrace.survivingStep_edgeCount_pos}
\leanok
\uses{KargerTrace.State, KargerTrace.SurvivingStep, KargerTrace.edgeCount_pos_of_mem, Multigraph.edgeCount}

If some state $t$ is reachable from $s$ by a surviving step, then $s.G$ has positive edge
count.
\end{lemma}

n21475.content:
\begin{lemma}[A surviving run preserves cut size]
\lean{KargerTrace.survivingRun_cut_size_eq}
\label{KargerTrace.survivingRun_cut_size_eq}
\leanok
\uses{KargerTrace.State, KargerTrace.SurvivingRun, KargerTrace.survivingStep_cut_size_eq, MulCut.size}

If $t$ is reachable from $s$ by a surviving run of any length, then
$t.C.\mathrm{size} = s.C.\mathrm{size}$.
\end{lemma}

n21476.content:
\begin{lemma}[A surviving run preserves minimality]
\lean{KargerTrace.survivingRun_mincut}
\label{KargerTrace.survivingRun_mincut}
\leanok
\uses{IsMulMinCut, KargerTrace.State, KargerTrace.SurvivingRun, KargerTrace.survivingStep_mincut}

If $t$ is reachable from $s$ by a surviving run and $s.C$ is a min-cut, then $t.C$ is a
min-cut.
\end{lemma}

n21477.content:
\begin{lemma}[An $n$-step surviving run removes $n$ vertices]
\lean{KargerTrace.survivingRun_vertexCount_eq}
\label{KargerTrace.survivingRun_vertexCount_eq}
\leanok
\uses{KargerTrace.State, KargerTrace.SurvivingRun, KargerTrace.survivingStep_vertexCount_eq, Multigraph.vertexCount}

If $t$ is reachable from $s$ by a surviving run of $n$ steps, then
$t.G.\mathrm{vertexCount} = s.G.\mathrm{vertexCount} - n$ (truncated subtraction on
$\mathbb{N}$).
\end{lemma}

n21478.content:
\begin{lemma}[Trace-level edge-count invariant]
\lean{KargerTrace.survivingRun_edge_count_invariant}
\label{KargerTrace.survivingRun_edge_count_invariant}
\leanok
\uses{IsMulMinCut, KargerTrace.State, KargerTrace.SurvivingRun, KargerTrace.survivingRun_cut_size_eq, KargerTrace.survivingRun_mincut, MulCut.size, Multigraph.edgeCount, Multigraph.vertexCount, edge_count_lower_bound, mincut_le_degree}

If $t$ is reachable from $s$ by a surviving run and $s.C$ is a min-cut, then the graph
reached after the run still satisfies the handshaking lower bound
\[
  s.C.\mathrm{size}\cdot t.G.\mathrm{vertexCount} \;\le\; 2\, t.G.\mathrm{edgeCount}.
\]
\end{lemma}

n21479.content:
\begin{lemma}[Indexed trace edge-count invariant]
\lean{KargerTrace.survivingRun_edge_count_invariant_indexed}
\label{KargerTrace.survivingRun_edge_count_invariant_indexed}
\leanok
\uses{IsMulMinCut, KargerTrace.State, KargerTrace.SurvivingRun, KargerTrace.survivingRun_edge_count_invariant, KargerTrace.survivingRun_vertexCount_eq, MulCut.size, Multigraph.edgeCount, Multigraph.vertexCount}

The same invariant, with the vertex count after $n$ contractions written explicitly: for a
surviving run of $n$ steps from $s$ to $t$ with $s.C$ a min-cut,
\[
  s.C.\mathrm{size}\cdot(s.G.\mathrm{vertexCount} - n) \;\le\; 2\, t.G.\mathrm{edgeCount}.
\]
\end{lemma}

n21480.content:
\begin{lemma}[Algebraic one-step survival bound]
\lean{KargerTrace.survivalProb_ge_factor}
\label{KargerTrace.survivalProb_ge_factor}
\leanok
\uses{survivalProb}

For naturals $c, n, m$ with $2 \le n$, $0 < m$ and $c\,n \le 2m$, the survival probability
$1 - c/m$ satisfies
\[
  \frac{n-2}{n} \;\le\; 1 - \frac{c}{m}.
\]
\end{lemma}

n21481.content:
\begin{lemma}[One-step survival bound at a surviving state]
\lean{KargerTrace.survivingStep_survivalProb_ge_factor}
\label{KargerTrace.survivingStep_survivalProb_ge_factor}
\leanok
\uses{IsMulMinCut, KargerTrace.State, KargerTrace.SurvivingStep, KargerTrace.survivalProb_ge_factor, KargerTrace.survivingStep_edgeCount_pos, MulCut.size, Multigraph.edgeCount, Multigraph.vertexCount, edge_count_lower_bound, mincut_le_degree, survivalProb}

If a surviving step is possible from $s$, the distinguished cut $s.C$ is a min-cut, and
$s.G$ has at least two vertices, then writing $n = s.G.\mathrm{vertexCount}$,
\[
  \frac{n-2}{n} \;\le\; \mathrm{survivalProb}(s.C.\mathrm{size},\, s.G.\mathrm{edgeCount}).
\]
\end{lemma}

n21482.content:
\begin{lemma}[One-step survival bound after $i$ contractions]
\lean{KargerTrace.survivingRun_survivalProb_ge_factor}
\label{KargerTrace.survivingRun_survivalProb_ge_factor}
\leanok
\uses{IsMulMinCut, KargerTrace.State, KargerTrace.SurvivingRun, KargerTrace.SurvivingStep, KargerTrace.survivalProb_ge_factor, KargerTrace.survivingRun_cut_size_eq, KargerTrace.survivingRun_mincut, KargerTrace.survivingStep_edgeCount_pos, MulCut.size, Multigraph.edgeCount, Multigraph.vertexCount, edge_count_lower_bound, mincut_le_degree, survivalProb}

If $t$ is reached from $s$ by a surviving run of $i$ steps, a further surviving step is
possible from $t$, $s.C$ is a min-cut, and $t.G$ has at least two vertices, then with
$n_t = t.G.\mathrm{vertexCount}$,
\[
  \frac{n_t-2}{n_t} \;\le\; \mathrm{survivalProb}(s.C.\mathrm{size},\, t.G.\mathrm{edgeCount}).
\]
\end{lemma}

n21483.content:
\begin{definition}[Non-crossing edges of a state]
\lean{KargerTrace.nonCrossingEdges}
\label{KargerTrace.nonCrossingEdges}
\leanok
\uses{Crosses, KargerTrace.State}
The sub-multiset of edges of $s.G$ that do not cross the distinguished cut $s.C$; these
are exactly the edge choices that keep the cut alive.
\end{definition}

n21484.content:
\begin{definition}[Number of non-crossing choices]
\lean{KargerTrace.nonCrossingChoiceCount}
\label{KargerTrace.nonCrossingChoiceCount}
\leanok
\uses{KargerTrace.State, KargerTrace.nonCrossingEdges}
The cardinality (with multiplicity) of the multiset of non-crossing edges of a state.
\end{definition}

n21485.content:
\begin{definition}[Uniform one-step survival probability]
\lean{KargerTrace.uniformSurvivalProb}
\label{KargerTrace.uniformSurvivalProb}
\leanok
\uses{KargerTrace.State, KargerTrace.nonCrossingChoiceCount, Multigraph.edgeCount}
The real number obtained as the number of non-crossing edge choices divided by the total
edge count of $s.G$, i.e.\ the probability that a uniformly chosen edge occurrence does not
cross the cut.
\end{definition}

n21486.content:
\begin{lemma}[Non-crossing choices count edges minus cut size]
\lean{KargerTrace.nonCrossingChoiceCount_eq_edgeCount_sub_cutSize}
\label{KargerTrace.nonCrossingChoiceCount_eq_edgeCount_sub_cutSize}
\leanok
\uses{Crosses, KargerTrace.State, KargerTrace.nonCrossingChoiceCount, MulCut.size, Multigraph.edgeCount, crossingEdges_eq_filter_crosses}

For every state $s$, the number of non-crossing edge choices equals
$s.G.\mathrm{edgeCount} - s.C.\mathrm{size}$.
\end{lemma}

n21487.content:
\begin{lemma}[Cut size bounded by edge count]
\lean{KargerTrace.cut_size_le_edgeCount}
\label{KargerTrace.cut_size_le_edgeCount}
\leanok
\uses{KargerTrace.State, MulCut.crossingEdges, MulCut.size, Multigraph.edgeCount}

For every state $s$, $s.C.\mathrm{size} \le s.G.\mathrm{edgeCount}$.
\end{lemma}

n21488.content:
\begin{lemma}[Uniform choice realizes the survival probability]
\lean{KargerTrace.uniformSurvivalProb_eq_survivalProb}
\label{KargerTrace.uniformSurvivalProb_eq_survivalProb}
\leanok
\uses{KargerTrace.State, KargerTrace.cut_size_le_edgeCount, KargerTrace.nonCrossingChoiceCount_eq_edgeCount_sub_cutSize, KargerTrace.uniformSurvivalProb, MulCut.size, Multigraph.edgeCount, survivalProb}

If $s.G$ has at least one edge, the uniform survival probability of $s$ equals
$\mathrm{survivalProb}(s.C.\mathrm{size},\, s.G.\mathrm{edgeCount}) = 1 - c/m$ with
$c = s.C.\mathrm{size}$ and $m = s.G.\mathrm{edgeCount}$.
\end{lemma}

n21489.content:
\begin{definition}[Sample space of edge occurrences]
\lean{KargerTrace.edgeChoiceSpace}
\label{KargerTrace.edgeChoiceSpace}
\leanok
\uses{KargerTrace.State}
The finite set of pairs (edge, occurrence index) obtained from the edge multiset of $s.G$;
the second coordinate distinguishes parallel copies of the same edge, so that a uniform
choice on this set is a uniform choice of an edge occurrence.
\end{definition}

n21490.content:
\begin{definition}[Surviving edge occurrence]
\lean{KargerTrace.edgeChoiceSurvives}
\label{KargerTrace.edgeChoiceSurvives}
\leanok
\uses{Crosses, KargerTrace.State}
The predicate on an edge occurrence saying that its underlying edge does not cross the
distinguished cut of $s$.
\end{definition}

n21491.content:
\begin{lemma}[Size of the occurrence space]
\lean{KargerTrace.edgeChoiceSpace_card}
\label{KargerTrace.edgeChoiceSpace_card}
\leanok
\uses{KargerTrace.State, KargerTrace.edgeChoiceSpace, Multigraph.edgeCount}

The occurrence sample space of a state has cardinality $s.G.\mathrm{edgeCount}$.
\end{lemma}

n21492.content:
\begin{lemma}[Filtering occurrences by first coordinate]
\lean{KargerTrace.toEnumFinset_filter_fst_card_eq_filter_card}
\label{KargerTrace.toEnumFinset_filter_fst_card_eq_filter_card}
\leanok

For a multiset $m$ and a decidable predicate $p$, the number of enumerated occurrences of
$m$ whose first coordinate satisfies $p$ equals the cardinality of the sub-multiset of $m$
filtered by $p$.
\end{lemma}

n21493.content:
\begin{lemma}[Surviving occurrences count non-crossing choices]
\lean{KargerTrace.edgeChoiceSurvivalCount_eq_nonCrossingChoiceCount}
\label{KargerTrace.edgeChoiceSurvivalCount_eq_nonCrossingChoiceCount}
\leanok
\uses{Crosses, KargerTrace.State, KargerTrace.edgeChoiceSpace, KargerTrace.edgeChoiceSurvives, KargerTrace.nonCrossingChoiceCount, KargerTrace.nonCrossingEdges, KargerTrace.toEnumFinset_filter_fst_card_eq_filter_card}

The number of surviving edge occurrences of a state equals its number of non-crossing edge
choices.
\end{lemma}

n21494.content:
\begin{definition}[Survival ratio of the occurrence space]
\lean{KargerTrace.edgeChoiceSurvivalRatio}
\label{KargerTrace.edgeChoiceSurvivalRatio}
\leanok
\uses{KargerTrace.State, KargerTrace.edgeChoiceSpace, KargerTrace.edgeChoiceSurvives}
The ratio of the number of surviving edge occurrences to the total number of edge
occurrences, i.e.\ the concrete one-step survival probability of the finite sampling model.
\end{definition}

n21495.content:
\begin{lemma}[Survival ratio equals uniform survival probability]
\lean{KargerTrace.edgeChoiceSurvivalRatio_eq_uniformSurvivalProb}
\label{KargerTrace.edgeChoiceSurvivalRatio_eq_uniformSurvivalProb}
\leanok
\uses{KargerTrace.State, KargerTrace.edgeChoiceSpace_card, KargerTrace.edgeChoiceSurvivalCount_eq_nonCrossingChoiceCount, KargerTrace.edgeChoiceSurvivalRatio, KargerTrace.uniformSurvivalProb}

For every state, the occurrence-space survival ratio coincides with the uniform survival
probability.
\end{lemma}

n21496.content:
\begin{lemma}[An occurrence carries an actual edge]
\lean{KargerTrace.edgeChoice_mem_edges}
\label{KargerTrace.edgeChoice_mem_edges}
\leanok
\uses{KargerTrace.State, KargerTrace.edgeChoiceSpace}

The first projection of any element of the occurrence sample space of $s$ is an edge of
$s.G$.
\end{lemma}

n21497.content:
\begin{lemma}[Surviving occurrences are non-crossing]
\lean{KargerTrace.not_mem_crossingEdges_of_edgeChoiceSurvives}
\label{KargerTrace.not_mem_crossingEdges_of_edgeChoiceSurvives}
\leanok
\uses{Crosses, KargerTrace.State, KargerTrace.edgeChoiceSpace, KargerTrace.edgeChoiceSurvives, MulCut.crossingEdges, crossingEdges_eq_filter_crosses}

If an edge occurrence of $s$ survives, then its underlying edge is not a crossing edge of
the distinguished cut $s.C$.
\end{lemma}

n21498.content:
\begin{definition}[Successor state of a surviving occurrence]
\lean{KargerTrace.stateAfterSurvivingChoice}
\label{KargerTrace.stateAfterSurvivingChoice}
\leanok
\uses{KargerTrace.State, KargerTrace.contractState, KargerTrace.edgeChoiceSpace, KargerTrace.edgeChoiceSurvives, KargerTrace.edgeChoice_mem_edges, KargerTrace.not_mem_crossingEdges_of_edgeChoiceSurvives}
Given a state $s$ and a sampled edge occurrence that does not cross the distinguished cut,
this is the state obtained by contracting $s$ along the underlying edge.
\end{definition}

n21499.content:
\begin{lemma}[Sampling a surviving occurrence gives a surviving step]
\lean{KargerTrace.stateAfterSurvivingChoice_step}
\label{KargerTrace.stateAfterSurvivingChoice_step}
\leanok
\uses{KargerTrace.State, KargerTrace.SurvivingStep, KargerTrace.edgeChoiceSpace, KargerTrace.edgeChoiceSurvives, KargerTrace.edgeChoice_mem_edges, KargerTrace.not_mem_crossingEdges_of_edgeChoiceSurvives, KargerTrace.stateAfterSurvivingChoice}

For any surviving edge occurrence at $s$, the pair consisting of $s$ and the resulting
successor state is a surviving step.
\end{lemma}

n21500.content:
\begin{definition}[Recursive survival probability]
\lean{KargerTrace.survivalEventProb}
\label{KargerTrace.survivalEventProb}
\leanok
\uses{KargerTrace.State, KargerTrace.edgeChoiceSpace, KargerTrace.edgeChoiceSurvives, KargerTrace.stateAfterSurvivingChoice}
The finite probability that the distinguished cut survives the next given number of random
edge-occurrence choices, defined by recursion on the number of steps: zero steps have
probability $1$, and one further step averages over all edge occurrences, contributing $0$
for occurrences that cross the cut and the recursive value at the contracted state
otherwise.
\end{definition}

n21501.content:
\begin{lemma}[Base case of the recursive survival probability]
\lean{KargerTrace.survivalEventProb_zero}
\label{KargerTrace.survivalEventProb_zero}
\leanok
\uses{KargerTrace.State, KargerTrace.survivalEventProb}

With no remaining contractions the survival probability is $1$.
\end{lemma}

n21502.content:
\begin{lemma}[Recursion step of the survival probability]
\lean{KargerTrace.survivalEventProb_succ}
\label{KargerTrace.survivalEventProb_succ}
\leanok
\uses{KargerTrace.State, KargerTrace.edgeChoiceSpace, KargerTrace.edgeChoiceSurvives, KargerTrace.stateAfterSurvivingChoice, KargerTrace.survivalEventProb}

The unfolding equation: the survival probability for $\text{steps}+1$ contractions at $s$
is the average over all edge occurrences of $s$ of the survival probability for
$\text{steps}$ contractions at the contracted state, with crossing occurrences
contributing $0$.
\end{lemma}

n21503.content:
\begin{lemma}[Surviving occurrences in the attached sample space]
\lean{KargerTrace.edgeChoice_attach_filter_card}
\label{KargerTrace.edgeChoice_attach_filter_card}
\leanok
\uses{KargerTrace.State, KargerTrace.edgeChoiceSpace, KargerTrace.edgeChoiceSurvives}

Counting surviving occurrences in the attached (subtype) version of the sample space gives
the same number as counting them in the sample space itself.
\end{lemma}

n21505.content:
\begin{lemma}[One-step lower bound for the recursive probability]
\lean{KargerTrace.survivalEventProb_step_lower_bound}
\label{KargerTrace.survivalEventProb_step_lower_bound}
\leanok
\uses{KargerTrace.State, KargerTrace.card_mul_le_sum_ite_of_lower_bound, KargerTrace.edgeChoiceSpace, KargerTrace.edgeChoiceSurvivalRatio, KargerTrace.edgeChoiceSurvives, KargerTrace.edgeChoice_attach_filter_card, KargerTrace.stateAfterSurvivingChoice, KargerTrace.survivalEventProb, KargerTrace.survivalEventProb_succ}

If the occurrence sample space of $s$ is nonempty and every surviving branch has recursive
survival probability at least $B$, then the averaged survival probability for one more step
satisfies
\[
  \mathrm{edgeChoiceSurvivalRatio}(s)\cdot B \;\le\;
  \mathrm{survivalEventProb}(\text{steps}+1,\, s).
\]
\end{lemma}

n21506.content:
\begin{lemma}[Survival ratio bounded below by the Karger factor]
\lean{KargerTrace.edgeChoiceSurvivalRatio_ge_factor}
\label{KargerTrace.edgeChoiceSurvivalRatio_ge_factor}
\leanok
\uses{IsMulMinCut, KargerTrace.State, KargerTrace.cut_size_le_edgeCount, KargerTrace.edgeChoiceSurvivalRatio, KargerTrace.edgeChoiceSurvivalRatio_eq_uniformSurvivalProb, KargerTrace.survivalProb_ge_factor, KargerTrace.uniformSurvivalProb_eq_survivalProb, MulCut.size, Multigraph.edgeCount, Multigraph.vertexCount, edge_count_lower_bound, mincut_le_degree}

If $s.C$ is a min-cut of positive size and $s.G$ has at least two vertices, then with
$n = s.G.\mathrm{vertexCount}$,
\[
  \frac{n-2}{n} \;\le\; \mathrm{edgeChoiceSurvivalRatio}(s).
\]
\end{lemma}

n21507.content:
\begin{theorem}[Recursive survival lower bound]
\lean{KargerTrace.survivalEventProb_lower_bound}
\label{KargerTrace.survivalEventProb_lower_bound}
\leanok
\uses{IsMulMinCut, KargerTrace.State, KargerTrace.SurvivingStep, KargerTrace.cut_size_le_edgeCount, KargerTrace.edgeChoiceSpace, KargerTrace.edgeChoiceSpace_card, KargerTrace.edgeChoiceSurvivalRatio, KargerTrace.edgeChoiceSurvivalRatio_ge_factor, KargerTrace.stateAfterSurvivingChoice, KargerTrace.stateAfterSurvivingChoice_step, KargerTrace.survivalEventProb, KargerTrace.survivalEventProb_step_lower_bound, KargerTrace.survivingStep_cut_size_eq, KargerTrace.survivingStep_mincut, KargerTrace.survivingStep_vertexCount_eq, MulCut.size, Multigraph.edgeCount, Multigraph.vertexCount}

For every $n$ and every state $s$ whose distinguished cut is a min-cut of positive size,
if $2 \le n$ and $s.G$ has exactly $n$ vertices, then the recursive sampling model
survives $n-2$ contractions with probability at least
\[
  \frac{2}{n(n-1)}.
\]
\end{theorem}

n21508.content:
\begin{theorem}[Survival lower bound at the initial state]
\lean{KargerTrace.survivalEventProb_initial_lower_bound}
\label{KargerTrace.survivalEventProb_initial_lower_bound}
\leanok
\uses{IsMulMinCut, KargerTrace.State, KargerTrace.survivalEventProb, KargerTrace.survivalEventProb_lower_bound, MulCut.size, Multigraph.vertexCount}

For a state $s$ whose distinguished cut is a min-cut of positive size and whose graph has
at least two vertices, writing $n = s.G.\mathrm{vertexCount}$,
\[
  \frac{2}{n(n-1)} \;\le\; \mathrm{survivalEventProb}(n-2,\, s).
\]
\end{theorem}

n21509.content:
\begin{theorem}[Fixed min-cut survival probability]
\lean{KargerTrace.fixed_mincut_survival_probability_lower_bound}
\label{KargerTrace.fixed_mincut_survival_probability_lower_bound}
\leanok
\uses{IsMulMinCut, KargerTrace.State, KargerTrace.survivalEventProb, KargerTrace.survivalEventProb_initial_lower_bound, MulCut.size, Multigraph.vertexCount}

Human-facing form of the previous statement: a fixed min-cut of positive size in a graph
with $n \ge 2$ vertices survives the $n-2$ random contractions with probability at least
$2/(n(n-1))$.
\end{theorem}

n21510.content:
\begin{definition}[Graph-only occurrence space]
\lean{KargerTrace.graphChoiceSpace}
\label{KargerTrace.graphChoiceSpace}
\leanok
\uses{Multigraph}
The finite set of edge occurrences of a multigraph $G$, the same construction as the
state-level sample space but without reference to a distinguished cut.
\end{definition}

n21511.content:
\begin{lemma}[The two occurrence spaces agree]
\lean{KargerTrace.graphChoiceSpace_eq_edgeChoiceSpace}
\label{KargerTrace.graphChoiceSpace_eq_edgeChoiceSpace}
\leanok
\uses{KargerTrace.State, KargerTrace.edgeChoiceSpace, KargerTrace.graphChoiceSpace}

For every state $s$, the graph-only occurrence space of $s.G$ equals the occurrence space
of $s$.
\end{lemma}

n21512.content:
\begin{lemma}[A graph occurrence carries an actual edge]
\lean{KargerTrace.graphChoice_mem_edges}
\label{KargerTrace.graphChoice_mem_edges}
\leanok
\uses{KargerTrace.graphChoiceSpace, Multigraph}

The first projection of any element of the graph-only occurrence space of $G$ is an edge
of $G$.
\end{lemma}

n21513.content:
\begin{definition}[Graph after a sampled contraction]
\lean{KargerTrace.graphAfterChoice}
\label{KargerTrace.graphAfterChoice}
\leanok
\uses{KargerTrace.graphChoiceSpace, KargerTrace.graphChoice_mem_edges, Multigraph, Multigraph.contract}
The multigraph obtained by contracting $G$ along the edge underlying a sampled edge
occurrence.
\end{definition}

n21514.content:
\begin{lemma}[Sampled contraction removes one vertex]
\lean{KargerTrace.graphAfterChoice_vertexCount_eq}
\label{KargerTrace.graphAfterChoice_vertexCount_eq}
\leanok
\uses{KargerTrace.graphAfterChoice, KargerTrace.graphChoiceSpace, KargerTrace.graphChoice_mem_edges, Multigraph, Multigraph.vertexCount, contract_vertex_count}

Contracting along any sampled edge occurrence decreases the vertex count by exactly one.
\end{lemma}

n21515.content:
\begin{lemma}[State contraction agrees with graph contraction]
\lean{KargerTrace.stateAfterSurvivingChoice_graph_eq}
\label{KargerTrace.stateAfterSurvivingChoice_graph_eq}
\leanok
\uses{KargerTrace.State, KargerTrace.edgeChoiceSpace, KargerTrace.edgeChoiceSurvives, KargerTrace.graphAfterChoice, KargerTrace.graphChoiceSpace, KargerTrace.graphChoiceSpace_eq_edgeChoiceSpace, KargerTrace.stateAfterSurvivingChoice}

The graph of the successor state after a surviving occurrence equals the graph obtained by
contracting $s.G$ along the same occurrence viewed in the graph-only occurrence space.
\end{lemma}

n21516.content:
\begin{definition}[Graph-only Karger run]
\lean{KargerTrace.KargerGraphRun}
\label{KargerTrace.KargerGraphRun}
\leanok
\uses{KargerTrace.graphAfterChoice, KargerTrace.graphChoiceSpace, Multigraph}
The inductive relation asserting that $H$ is reachable from $G$ by a given number of
successive arbitrary edge-occurrence contractions.  It models the actual graph evolution
of the algorithm without tracking any distinguished cut.
\end{definition}

n21517.content:
\begin{lemma}[Vertex count along a graph run]
\lean{KargerTrace.kargerGraphRun_vertexCount_eq}
\label{KargerTrace.kargerGraphRun_vertexCount_eq}
\leanok
\uses{KargerTrace.KargerGraphRun, KargerTrace.graphAfterChoice_vertexCount_eq, Multigraph, Multigraph.vertexCount}

If $H$ is reachable from $G$ by a graph run of $\text{steps}$ contractions, then
$H.\mathrm{vertexCount} = G.\mathrm{vertexCount} - \text{steps}$.
\end{lemma}

n21518.content:
\begin{lemma}[A full graph run ends with two vertices]
\lean{KargerTrace.kargerGraphRun_full_vertexCount_eq_two}
\label{KargerTrace.kargerGraphRun_full_vertexCount_eq_two}
\leanok
\uses{KargerTrace.KargerGraphRun, KargerTrace.kargerGraphRun_vertexCount_eq, Multigraph, Multigraph.vertexCount}

If $G$ has at least two vertices and $H$ is reachable from $G$ by
$G.\mathrm{vertexCount} - 2$ contractions, then $H$ has exactly two vertices.
\end{lemma}

n21519.content:
\begin{lemma}[A full graph run yields a Karger output]
\lean{KargerTrace.kargerGraphRun_full_output}
\label{KargerTrace.kargerGraphRun_full_output}
\leanok
\uses{KargerOutput, KargerTrace.KargerGraphRun, KargerTrace.kargerGraphRun_full_vertexCount_eq_two, Multigraph, Multigraph.vertexCount}

Under the same hypotheses, the terminal graph $H$ is a valid Karger output, i.e.\ a
two-vertex multigraph.
\end{lemma}

n21520.content:
\begin{lemma}[Every edge yields an occurrence]
\lean{KargerTrace.choice_mem_graphChoiceSpace_of_edge_mem}
\label{KargerTrace.choice_mem_graphChoiceSpace_of_edge_mem}
\leanok
\uses{KargerTrace.graphChoiceSpace, Multigraph}

If $e$ is an edge of $G$, then the occurrence $(e, 0)$ belongs to the graph-only
occurrence space of $G$.
\end{lemma}

n21521.content:
\begin{lemma}[A surviving step is realized by a graph occurrence]
\lean{KargerTrace.survivingStep_graphChoice}
\label{KargerTrace.survivingStep_graphChoice}
\leanok
\uses{KargerTrace.State, KargerTrace.SurvivingStep, KargerTrace.choice_mem_graphChoiceSpace_of_edge_mem, KargerTrace.graphAfterChoice, KargerTrace.graphChoiceSpace}

If $t$ arises from $s$ by a surviving step, then there is an edge occurrence of $s.G$ whose
contraction produces exactly $t.G$.
\end{lemma}

n21522.content:
\begin{lemma}[Surviving runs project to graph runs]
\lean{KargerTrace.survivingRun_graphRun}
\label{KargerTrace.survivingRun_graphRun}
\leanok
\uses{KargerTrace.KargerGraphRun, KargerTrace.State, KargerTrace.SurvivingRun, KargerTrace.survivingStep_graphChoice}

A surviving run of $\text{steps}$ steps from $s$ to $t$ induces a graph-only Karger run of
the same length from $s.G$ to $t.G$.
\end{lemma}

n21523.content:
\begin{lemma}[A full surviving run ends with a Karger output]
\lean{KargerTrace.survivingRun_full_output}
\label{KargerTrace.survivingRun_full_output}
\leanok
\uses{KargerOutput, KargerTrace.State, KargerTrace.SurvivingRun, KargerTrace.kargerGraphRun_full_output, KargerTrace.survivingRun_graphRun, Multigraph.vertexCount}

If $s.G$ has at least two vertices and $t$ is reached from $s$ by a surviving run of
$s.G.\mathrm{vertexCount} - 2$ steps, then $t.G$ is a Karger output.
\end{lemma}

n21524.content:
\begin{definition}[Adaptive graph trace]
\lean{KargerTrace.KargerGraphTrace}
\label{KargerTrace.KargerGraphTrace}
\leanok
\uses{KargerTrace.graphAfterChoice, KargerTrace.graphChoiceSpace, Multigraph}
An explicit indexed execution of the contraction loop: a family of graphs indexed by
$\mathbb{N}$, an edge occurrence of the graph at each index below $\text{steps}$, and the
requirement that the next graph is the contraction of the current one along that
occurrence.  The choice type depends on the current graph, matching the adaptive nature of
the process.
\end{definition}

n21525.content:
\begin{lemma}[Prefixes of a graph trace are graph runs]
\lean{KargerTrace.kargerGraphTrace_prefix_run}
\label{KargerTrace.kargerGraphTrace_prefix_run}
\leanok
\uses{KargerTrace.KargerGraphRun, KargerTrace.KargerGraphTrace, KargerTrace.graphAfterChoice}

For $i \le \text{steps}$, the first $i$ stages of an adaptive graph trace form a graph run
from the initial graph to the graph at index $i$.
\end{lemma}

n21526.content:
\begin{lemma}[Vertex count along a graph trace]
\lean{KargerTrace.kargerGraphTrace_vertexCount_eq}
\label{KargerTrace.kargerGraphTrace_vertexCount_eq}
\leanok
\uses{KargerTrace.KargerGraphTrace, KargerTrace.kargerGraphRun_vertexCount_eq, KargerTrace.kargerGraphTrace_prefix_run, Multigraph.vertexCount}

For $i \le \text{steps}$, the graph at index $i$ of an adaptive trace has vertex count
equal to the initial vertex count minus $i$.
\end{lemma}

n21527.content:
\begin{lemma}[A full graph trace terminates with two vertices]
\lean{KargerTrace.kargerGraphTrace_full_output}
\label{KargerTrace.kargerGraphTrace_full_output}
\leanok
\uses{KargerOutput, KargerTrace.KargerGraphTrace, KargerTrace.kargerGraphTrace_vertexCount_eq, Multigraph.vertexCount}

If $2 \le n$ and an adaptive graph trace of $n-2$ steps starts from a graph with $n$
vertices, then its final graph is a Karger output.
\end{lemma}

n21528.content:
\begin{theorem}[Adaptive traces output two vertices]
\lean{KargerTrace.adaptive_karger_trace_outputs_two_vertices}
\label{KargerTrace.adaptive_karger_trace_outputs_two_vertices}
\leanok
\uses{KargerOutput, KargerTrace.KargerGraphTrace, KargerTrace.kargerGraphTrace_full_output, Multigraph.vertexCount}

Human-facing termination statement: every adaptive graph trace of $n-2$ contractions
starting from an $n$-vertex graph with $n \ge 2$ ends with a two-vertex graph.
\end{theorem}

n21529.content:
\begin{theorem}[Algorithmic trace summary]
\lean{KargerTrace.karger_algorithmic_trace_summary}
\label{KargerTrace.karger_algorithmic_trace_summary}
\leanok
\uses{IsMulMinCut, KargerOutput, KargerTrace.KargerGraphTrace, KargerTrace.State, KargerTrace.kargerGraphTrace_full_output, KargerTrace.survivalEventProb, KargerTrace.survivalEventProb_initial_lower_bound, MulCut.size, Multigraph.vertexCount}

For a state $s$ whose distinguished cut is a min-cut of positive size and whose graph has
$n = s.G.\mathrm{vertexCount} \ge 2$ vertices, both of the following hold: the recursive
sampling model survives $n-2$ contractions with probability at least $2/(n(n-1))$, and
every adaptive graph trace of $n-2$ contractions starting from $s.G$ ends with a Karger
output.
\end{theorem}

n21530.content:
\begin{theorem}[Main adaptive trace theorem]
\lean{KargerTrace.adaptive_karger_trace_main}
\label{KargerTrace.adaptive_karger_trace_main}
\leanok
\uses{IsMulMinCut, KargerOutput, KargerTrace.KargerGraphTrace, KargerTrace.State, KargerTrace.karger_algorithmic_trace_summary, KargerTrace.survivalEventProb, MulCut.size, Multigraph.vertexCount}

Human-facing name for the previous conjunction: the survival lower bound $2/(n(n-1))$
together with termination of every adaptive graph trace of $n-2$ contractions.
\end{theorem}

n21531.content:
\begin{definition}[Indexed surviving trace]
\lean{KargerTrace.SurvivingTrace}
\label{KargerTrace.SurvivingTrace}
\leanok
\uses{KargerTrace.State, KargerTrace.SurvivingStep}
A family of states indexed by $\mathbb{N}$ such that consecutive states at indices below
$\text{steps}$ are related by a surviving step.  This is the product-friendly counterpart
of a surviving run: it exposes the state present at each index.
\end{definition}

n21532.content:
\begin{definition}[Graph trace of a surviving trace]
\lean{KargerTrace.survivingTrace_toGraphTrace}
\label{KargerTrace.survivingTrace_toGraphTrace}
\leanok
\uses{KargerTrace.KargerGraphTrace, KargerTrace.SurvivingTrace, KargerTrace.survivingStep_graphChoice}
The adaptive graph trace obtained from an indexed surviving trace by forgetting the
distinguished cuts and choosing, at each step, an occurrence realizing the surviving step.
\end{definition}

n21533.content:
\begin{lemma}[Prefixes of a surviving trace are surviving runs]
\lean{KargerTrace.survivingTrace_prefix_run}
\label{KargerTrace.survivingTrace_prefix_run}
\leanok
\uses{KargerTrace.SurvivingRun, KargerTrace.SurvivingTrace}

For $i \le \text{steps}$, the first $i$ stages of an indexed surviving trace form a
surviving run from the initial state to the state at index $i$.
\end{lemma}

n21534.content:
\begin{lemma}[Vertex count along a surviving trace]
\lean{KargerTrace.survivingTrace_vertexCount_eq}
\label{KargerTrace.survivingTrace_vertexCount_eq}
\leanok
\uses{KargerTrace.SurvivingTrace, KargerTrace.survivingRun_vertexCount_eq, KargerTrace.survivingTrace_prefix_run, Multigraph.vertexCount}

For $i \le \text{steps}$, the graph at index $i$ of a surviving trace has vertex count
equal to the initial vertex count minus $i$.
\end{lemma}

n21535.content:
\begin{lemma}[Per-step survival bound along a surviving trace]
\lean{KargerTrace.survivingTrace_survivalProb_ge_factor}
\label{KargerTrace.survivingTrace_survivalProb_ge_factor}
\leanok
\uses{IsMulMinCut, KargerTrace.SurvivingTrace, KargerTrace.survivingRun_survivalProb_ge_factor, KargerTrace.survivingTrace_prefix_run, MulCut.size, Multigraph.edgeCount, Multigraph.vertexCount, survivalProb}

If the initial cut of an indexed surviving trace is a min-cut, $i < \text{steps}$, and the
graph at index $i$ has at least two vertices, then with $n_i$ its vertex count,
\[
  \frac{n_i-2}{n_i} \;\le\;
  \mathrm{survivalProb}\bigl(\,\text{initial cut size},\; \text{edge count at }i\,\bigr).
\]
\end{lemma}

n21536.content:
\begin{lemma}[Product of factors bounds the product of survival probabilities]
\lean{KargerTrace.survivingTrace_factor_product_le_survival_product}
\label{KargerTrace.survivingTrace_factor_product_le_survival_product}
\leanok
\uses{IsMulMinCut, KargerTrace.SurvivingTrace, KargerTrace.survivingTrace_survivalProb_ge_factor, MulCut.size, Multigraph.edgeCount, Multigraph.vertexCount, survivalProb}

If the initial cut is a min-cut and every graph along the first $\text{steps}$ indices has
at least two vertices, then
\[
  \prod_{i<\text{steps}} \frac{n_i-2}{n_i} \;\le\;
  \prod_{i<\text{steps}} \mathrm{survivalProb}\bigl(\,\text{initial cut size},\;
  \text{edge count at }i\,\bigr),
\]
where $n_i$ is the vertex count at index $i$.
\end{lemma}

n21537.content:
\begin{lemma}[Factor product in telescoping form]
\lean{KargerTrace.survivingTrace_factor_product_eq_telescope}
\label{KargerTrace.survivingTrace_factor_product_eq_telescope}
\leanok
\uses{KargerTrace.SurvivingTrace, KargerTrace.survivingTrace_vertexCount_eq, Multigraph.vertexCount}

If a surviving trace has $\text{steps} = n-2$ and starts from a graph with $n$ vertices,
then
\[
  \prod_{i<\text{steps}} \frac{n_i-2}{n_i}
  \;=\; \prod_{i<n-2} \frac{n-i-2}{n-i}.
\]
\end{lemma}

n21538.content:
\begin{theorem}[Product-level trace survival bound]
\lean{KargerTrace.survivingTrace_product_survival_lower_bound}
\label{KargerTrace.survivingTrace_product_survival_lower_bound}
\leanok
\uses{IsMulMinCut, KargerTrace.SurvivingTrace, KargerTrace.survivingTrace_factor_product_eq_telescope, KargerTrace.survivingTrace_factor_product_le_survival_product, MulCut.size, Multigraph.edgeCount, Multigraph.vertexCount, survivalProb, telescope_prod}

For an indexed surviving trace of $n-2$ steps starting from an $n$-vertex graph with
$n \ge 2$, initial min-cut, and at least two vertices at every step,
\[
  \frac{2}{n(n-1)} \;\le\;
  \prod_{i<n-2} \mathrm{survivalProb}\bigl(\,\text{initial cut size},\;
  \text{edge count at }i\,\bigr).
\]
\end{theorem}

n21539.content:
\begin{definition}[Product of uniform survival probabilities]
\lean{KargerTrace.survivingTraceUniformSurvivalProduct}
\label{KargerTrace.survivingTraceUniformSurvivalProduct}
\leanok
\uses{KargerTrace.SurvivingTrace, KargerTrace.uniformSurvivalProb}
The product over $i < \text{steps}$ of the uniform one-step survival probabilities of the
states of an indexed surviving trace.
\end{definition}

n21540.content:
\begin{lemma}[Uniform product as a product of survival probabilities]
\lean{KargerTrace.survivingTrace_uniform_product_eq_survival_product}
\label{KargerTrace.survivingTrace_uniform_product_eq_survival_product}
\leanok
\uses{KargerTrace.SurvivingTrace, KargerTrace.survivingStep_edgeCount_pos, KargerTrace.survivingTraceUniformSurvivalProduct, KargerTrace.uniformSurvivalProb_eq_survivalProb, MulCut.size, Multigraph.edgeCount, survivalProb}

The uniform survival product of a trace equals the product over $i < \text{steps}$ of
$\mathrm{survivalProb}$ applied to the cut size and edge count at index $i$.
\end{lemma}

n21541.content:
\begin{lemma}[Uniform product with the initial cut size]
\lean{KargerTrace.survivingTrace_uniform_product_eq_initial_cut_survival_product}
\label{KargerTrace.survivingTrace_uniform_product_eq_initial_cut_survival_product}
\leanok
\uses{KargerTrace.SurvivingRun, KargerTrace.SurvivingTrace, KargerTrace.survivingRun_cut_size_eq, KargerTrace.survivingTraceUniformSurvivalProduct, KargerTrace.survivingTrace_prefix_run, KargerTrace.survivingTrace_uniform_product_eq_survival_product, MulCut.size, Multigraph.edgeCount, survivalProb}

The same product may be written using the initial cut size at every index, since cut size
is invariant along a surviving trace.
\end{lemma}

n21542.content:
\begin{theorem}[Lower bound for the uniform survival product]
\lean{KargerTrace.survivingTrace_uniform_survival_product_lower_bound}
\label{KargerTrace.survivingTrace_uniform_survival_product_lower_bound}
\leanok
\uses{IsMulMinCut, KargerTrace.SurvivingTrace, KargerTrace.survivingTraceUniformSurvivalProduct, KargerTrace.survivingTrace_product_survival_lower_bound, KargerTrace.survivingTrace_uniform_product_eq_initial_cut_survival_product, Multigraph.vertexCount}

Under the same hypotheses as the product-level bound, the product of the concrete uniform
one-step survival probabilities along the trace is at least $2/(n(n-1))$.
\end{theorem}

n21543.content:
\begin{definition}[Product of occurrence-space survival ratios]
\lean{KargerTrace.survivingTraceEdgeChoiceSurvivalProduct}
\label{KargerTrace.survivingTraceEdgeChoiceSurvivalProduct}
\leanok
\uses{KargerTrace.SurvivingTrace, KargerTrace.edgeChoiceSurvivalRatio}
The product over $i < \text{steps}$ of the finite sample-space survival ratios of the
states of an indexed surviving trace.
\end{definition}

n21544.content:
\begin{lemma}[The two concrete products agree]
\lean{KargerTrace.survivingTrace_edgeChoice_product_eq_uniform_product}
\label{KargerTrace.survivingTrace_edgeChoice_product_eq_uniform_product}
\leanok
\uses{KargerTrace.SurvivingTrace, KargerTrace.edgeChoiceSurvivalRatio_eq_uniformSurvivalProb, KargerTrace.survivingTraceEdgeChoiceSurvivalProduct, KargerTrace.survivingTraceUniformSurvivalProduct}

For every indexed surviving trace, the product of occurrence-space survival ratios equals
the product of uniform survival probabilities.
\end{lemma}

n21545.content:
\begin{theorem}[Lower bound for the occurrence-space survival product]
\lean{KargerTrace.survivingTrace_edgeChoice_survival_product_lower_bound}
\label{KargerTrace.survivingTrace_edgeChoice_survival_product_lower_bound}
\leanok
\uses{IsMulMinCut, KargerTrace.SurvivingTrace, KargerTrace.survivingTraceEdgeChoiceSurvivalProduct, KargerTrace.survivingTrace_edgeChoice_product_eq_uniform_product, KargerTrace.survivingTrace_uniform_survival_product_lower_bound, Multigraph.vertexCount}

For an indexed surviving trace of $n-2$ steps starting from an $n$-vertex graph with
$n \ge 2$, initial min-cut, and at least two vertices at every step, the product of the
finite uniform edge-choice survival ratios is at least $2/(n(n-1))$.
\end{theorem}

n21546.content:
\begin{lemma}[Exchanging the head edge for a new edge]
\lean{Kruskal.exchange_take_head}
\label{Kruskal.exchange_take_head}
\leanok
\uses{Kruskal.Reach, Kruskal.WEdge, Kruskal.reach_lift, Kruskal.reach_mono, Kruskal.reach_of_mem, Kruskal.reach_symm}

Let $\mathit{base}, \mathit{rest}$ be edge lists on $n$ vertices and let $g, e$ be edges.
Suppose that in $\mathit{base} \mathbin{+\!\!+} \mathit{rest}$ the vertex $e.u$ reaches
$g.u$ and $g.v$ reaches $e.v$. Then every pair $a, b$ that is reachable in
$\mathit{base} \mathbin{+\!\!+} (g :: \mathit{rest})$ is also reachable in
$\mathit{base} \mathbin{+\!\!+} \mathit{rest} \mathbin{+\!\!+} [e]$; that is, $g$ may be
replaced by $e$ without losing connectivity.
\end{lemma}

n21547.content:
\begin{lemma}[Exchanging the head edge, reversed orientation]
\lean{Kruskal.exchange_take_head'}
\label{Kruskal.exchange_take_head'}
\leanok
\uses{Kruskal.Reach, Kruskal.SymAdj, Kruskal.WEdge, Kruskal.exchange_take_head, Kruskal.reach_lift}

The same exchange statement with the endpoints of $g$ taken in the opposite order:
if in $\mathit{base} \mathbin{+\!\!+} \mathit{rest}$ the vertex $e.u$ reaches $g.v$ and
$g.u$ reaches $e.v$, then every pair reachable in
$\mathit{base} \mathbin{+\!\!+} (g :: \mathit{rest})$ is reachable in
$\mathit{base} \mathbin{+\!\!+} \mathit{rest} \mathbin{+\!\!+} [e]$.
\end{lemma}

n21548.content:
\begin{lemma}[Exchange argument over a base edge list]
\lean{Kruskal.exchange_with_base}
\label{Kruskal.exchange_with_base}
\leanok
\uses{Kruskal.Reach, Kruskal.WEdge, Kruskal.exchange_take_head, Kruskal.exchange_take_head', Kruskal.reach_cons_iff, Kruskal.reach_lift, Kruskal.reach_mem_iff, Kruskal.reach_mono, Kruskal.reach_of_mem, Kruskal.reach_symm}

Let $\mathit{base}, S$ be edge lists and let $e$ be an edge with $e.u \neq e.v$ whose
endpoints are connected in $\mathit{base} \mathbin{+\!\!+} S$ but not in $\mathit{base}$
alone. Then there exists an edge $f \in S$ such that every pair $a, b$ reachable in
$\mathit{base} \mathbin{+\!\!+} S$ remains reachable in
$\mathit{base} \mathbin{+\!\!+} (S \setminus \{f\}) \mathbin{+\!\!+} [e]$, where
$S \setminus \{f\}$ denotes $\mathtt{S.erase}\,f$.
\end{lemma}

n21549.content:
\begin{lemma}[Union--find form of the exchange argument]
\lean{Kruskal.uf_exchange}
\label{Kruskal.uf_exchange}
\leanok
\uses{Kruskal.Reach, Kruskal.UF, Kruskal.UF.SamePartition, Kruskal.UF.merge, Kruskal.UF.mergeAll, Kruskal.WEdge, Kruskal.exchange_with_base, Kruskal.mergeAll_iff_reach, Kruskal.reach_lift, Kruskal.reach_mem_iff, Kruskal.reach_mono, Kruskal.reach_symm}

Let $\mathit{uf}$ be a union--find state whose classes are exactly the reachability
classes of an edge list $\mathit{base}$, i.e.\ $\mathit{uf}\,a = \mathit{uf}\,b$ iff
$a$ and $b$ are reachable in $\mathit{base}$. If merging all edges of $S$ into
$\mathit{uf}$ identifies $e.u$ and $e.v$ while $\mathit{uf}$ itself keeps them apart,
then there is an edge $f \in S$ such that
$(\mathit{uf}.\mathtt{merge}\,e.u\,e.v).\mathtt{mergeAll}\,(S \setminus \{f\})$
induces the same partition as $\mathit{uf}.\mathtt{mergeAll}\,S$.
\end{lemma}

n21551.content:
\begin{definition}[Union--find state after the greedy loop]
\lean{Kruskal.ufAfterProcessEdges}
\label{Kruskal.ufAfterProcessEdges}
\leanok
\uses{Kruskal.UF, Kruskal.UF.find, Kruskal.UF.merge, Kruskal.WEdge}
The union--find structure obtained by running the greedy loop over a list of weighted
edges: starting from a state $uf$, each edge $e$ is merged into the state when its
endpoints $e.u$ and $e.v$ currently lie in different components, and is ignored
otherwise. Unlike $\texttt{Kruskal.processEdges}$ it returns only the final state, not the
list of accepted edges.
\end{definition}

n21552.content:
\begin{lemma}[Greedy loop induces the full merge partition]
\lean{Kruskal.ufAfterProcessEdges_partition}
\label{Kruskal.ufAfterProcessEdges_partition}
\leanok
\uses{Kruskal.UF, Kruskal.UF.SamePartition, Kruskal.UF.merge, Kruskal.UF.mergeAll, Kruskal.WEdge, Kruskal.merge_noop, Kruskal.ufAfterProcessEdges}

For every edge list and every initial state $uf$, the state
$\texttt{Kruskal.ufAfterProcessEdges}$ produces induces the same partition of the vertices
as merging all the edges unconditionally, i.e.\ it has the same partition as
$uf.\mathrm{mergeAll}$ applied to the whole list.
\end{lemma}

n21553.content:
\begin{lemma}[Accumulator factors out of the greedy loop]
\lean{Kruskal.processEdges_acc}
\label{Kruskal.processEdges_acc}
\leanok
\uses{Kruskal.UF, Kruskal.UF.merge, Kruskal.WEdge, Kruskal.processEdges}

Running $\texttt{Kruskal.processEdges}$ with an accumulator $acc$ yields
$acc^{\mathrm{rev}}$ followed by the output of the same run started from the empty
accumulator; the accumulator only contributes a reversed prefix.
\end{lemma}

n21554.content:
\begin{lemma}[Selected edges span the same partition]
\lean{Kruskal.processEdges_same_partition}
\label{Kruskal.processEdges_same_partition}
\leanok
\uses{Kruskal.UF, Kruskal.UF.SamePartition, Kruskal.UF.find, Kruskal.UF.mergeAll, Kruskal.WEdge, Kruskal.processEdges, Kruskal.processEdges_acc, Kruskal.ufAfterProcessEdges, Kruskal.ufAfterProcessEdges_partition}

Merging the edges selected by the greedy loop into $uf$ gives the same partition as
merging all the input edges into $uf$: the discarded edges never change connectivity.
\end{lemma}

n21555.content:
\begin{lemma}[Skipping an edge inside a component]
\lean{Kruskal.processEdges_skip}
\label{Kruskal.processEdges_skip}
\leanok
\uses{Kruskal.UF, Kruskal.UF.find, Kruskal.WEdge, Kruskal.processEdges}

If the endpoints of $e$ already have the same union--find representative, then the
greedy loop on $e :: rest$ from state $uf$ returns exactly the output of the loop on
$rest$ from the same state.
\end{lemma}

n21556.content:
\begin{lemma}[Weight contributed by an accepted edge]
\lean{Kruskal.processEdges_take_weight}
\label{Kruskal.processEdges_take_weight}
\leanok
\uses{Kruskal.UF, Kruskal.UF.find, Kruskal.UF.merge, Kruskal.WEdge, Kruskal.processEdges, Kruskal.processEdges_acc, Kruskal.totalWeight}

If the endpoints of $e$ lie in different components of $uf$, then the total weight of the
greedy output on $e :: rest$ equals $e.\mathrm{weight}$ plus the total weight of the
greedy output on $rest$ started from the merged state $uf.\mathrm{merge}\,e.u\,e.v$.
\end{lemma}

n21558.content:
\begin{theorem}[Kruskal's output spans the input]
\lean{Kruskal.kruskal_spans}
\label{Kruskal.kruskal_spans}
\leanok
\uses{Kruskal.Reach, Kruskal.SpansLike, Kruskal.UF.init, Kruskal.WEdge, Kruskal.kruskal, Kruskal.mergeAll_init_iff, Kruskal.processEdges_same_partition, Kruskal.reach_mono}

For every weighted edge list $E$ over $\mathrm{Fin}\,n$, the output $\mathrm{kruskal}\,n\,E$
spans like $E$: any two vertices reachable in $E$ are reachable using only the selected
edges.
\end{theorem}

n21559.content:
\begin{theorem}[Optimality of Kruskal's algorithm]
\lean{Kruskal.kruskal_optimal}
\label{Kruskal.kruskal_optimal}
\leanok
\uses{Kruskal.SpansLike, Kruskal.WEdge, Kruskal.kruskal, Kruskal.mergeAll_init_iff, Kruskal.processEdges_optimal, Kruskal.reach_mono, Kruskal.totalWeight}

If $S$ is a sublist of $E$ that spans like $E$, then
\[
  \mathrm{totalWeight}\bigl(\mathrm{kruskal}\;n\;E\bigr) \;\le\; \mathrm{totalWeight}(S),
\]
so Kruskal's output has minimum total weight among all spanning subsets of $E$.
\end{theorem}

n21560.content:
\begin{lemma}[Reflexivity of SamePartition]
\lean{Kruskal.UF.SamePartition.rfl}
\label{Kruskal.UF.SamePartition.rfl}
\leanok
\uses{Kruskal.UF, Kruskal.UF.SamePartition}

Every union--find state $\mathit{uf} : \mathtt{UF}\,n$ induces the same partition as
itself: $\mathtt{SamePartition}\,\mathit{uf}\,\mathit{uf}$.
\end{lemma}

n21562.content:
\begin{lemma}[Transitivity of SamePartition]
\lean{Kruskal.UF.SamePartition.trans}
\label{Kruskal.UF.SamePartition.trans}
\leanok
\uses{Kruskal.UF, Kruskal.UF.SamePartition}

If $\mathtt{SamePartition}\,\mathit{uf}_1\,\mathit{uf}_2$ and
$\mathtt{SamePartition}\,\mathit{uf}_2\,\mathit{uf}_3$, then
$\mathtt{SamePartition}\,\mathit{uf}_1\,\mathit{uf}_3$. Together with reflexivity and
symmetry, $\mathtt{SamePartition}$ is an equivalence relation on union--find states.
\end{lemma}

n21563.content:
\begin{lemma}[Merging within a component is a no-op]
\lean{Kruskal.merge_noop}
\label{Kruskal.merge_noop}
\leanok
\uses{Kruskal.UF, Kruskal.UF.merge}

If two vertices $i, j$ already carry the same representative,
$\mathit{uf}\,i = \mathit{uf}\,j$, then merging them leaves the state unchanged:
$\mathit{uf}.\mathtt{merge}\,i\,j = \mathit{uf}$.
\end{lemma}

n21564.content:
\begin{lemma}[Merging preserves existing components]
\lean{Kruskal.mergeAll_preserves}
\label{Kruskal.mergeAll_preserves}
\leanok
\uses{Kruskal.UF, Kruskal.UF.merge, Kruskal.UF.mergeAll, Kruskal.WEdge}

If $\mathit{uf}\,a = \mathit{uf}\,b$, then for any list of weighted edges
$\mathit{edges}$ we still have
$(\mathit{uf}.\mathtt{mergeAll}\,\mathit{edges})\,a = (\mathit{uf}.\mathtt{mergeAll}\,\mathit{edges})\,b$;
that is, merging never splits vertices that are already in the same component.
\end{lemma}

n21565.content:
\begin{lemma}[Merging characterizes reachability]
\lean{Kruskal.mergeAll_iff_reach}
\label{Kruskal.mergeAll_iff_reach}
\leanok
\uses{Kruskal.Reach, Kruskal.UF, Kruskal.UF.merge, Kruskal.UF.mergeAll, Kruskal.WEdge, Kruskal.reach_cons_iff, Kruskal.reach_mono, Kruskal.reach_symm}

Suppose the union--find state $\mathit{uf}$ represents reachability in a base edge list,
i.e.\ $\mathit{uf}\,a = \mathit{uf}\,b \leftrightarrow \mathtt{Reach}\,\mathit{base}\,a\,b$
for all $a, b$. Then after merging along $\mathit{edges}$,
\[
  (\mathit{uf}.\mathtt{mergeAll}\,\mathit{edges})\,a
    = (\mathit{uf}.\mathtt{mergeAll}\,\mathit{edges})\,b
  \quad\longleftrightarrow\quad
  \mathtt{Reach}\,(\mathit{base} \mathbin{+\!\!+} \mathit{edges})\,a\,b .
\]
\end{lemma}

n21566.content:
\begin{lemma}[Correctness of merging from the initial state]
\lean{Kruskal.mergeAll_init_iff}
\label{Kruskal.mergeAll_init_iff}
\leanok
\uses{Kruskal.Reach, Kruskal.SymAdj, Kruskal.UF.init, Kruskal.UF.mergeAll, Kruskal.WEdge, Kruskal.mergeAll_iff_reach}

Starting from the initial union--find state $\mathtt{UF.init}\,n$, in which every vertex
is its own component, two vertices $a, b$ end up with the same representative after
merging along $\mathit{edges}$ if and only if $\mathtt{Reach}\,\mathit{edges}\,a\,b$.
\end{lemma}

n21567.content:
\begin{lemma}[Merging respects SamePartition]
\lean{Kruskal.mergeAll_congr}
\label{Kruskal.mergeAll_congr}
\leanok
\uses{Kruskal.UF, Kruskal.UF.SamePartition, Kruskal.UF.merge, Kruskal.UF.mergeAll, Kruskal.WEdge}

If $\mathtt{SamePartition}\,\mathit{uf}_1\,\mathit{uf}_2$, then merging both states along
the same edge list preserves this:
$\mathtt{SamePartition}\,(\mathit{uf}_1.\mathtt{mergeAll}\,\mathit{edges})\,(\mathit{uf}_2.\mathtt{mergeAll}\,\mathit{edges})$.
\end{lemma}

n21568.content:
\begin{lemma}[Two merges commute up to partition]
\lean{Kruskal.merge_swap_partition}
\label{Kruskal.merge_swap_partition}
\leanok
\uses{Kruskal.UF, Kruskal.UF.SamePartition, Kruskal.UF.merge, Kruskal.WEdge}

For any state $\mathit{uf}$ and edges $a, b$, merging the endpoints of $a$ and then those
of $b$ yields the same partition as merging them in the opposite order:
$\mathtt{SamePartition}\,((\mathit{uf}.\mathtt{merge}\,a.u\,a.v).\mathtt{merge}\,b.u\,b.v)\,((\mathit{uf}.\mathtt{merge}\,b.u\,b.v).\mathtt{merge}\,a.u\,a.v)$.
\end{lemma}

n21569.content:
\begin{lemma}[Merging is permutation invariant]
\lean{Kruskal.mergeAll_perm}
\label{Kruskal.mergeAll_perm}
\leanok
\uses{Kruskal.UF, Kruskal.UF.SamePartition, Kruskal.UF.SamePartition.trans, Kruskal.UF.mergeAll, Kruskal.WEdge, Kruskal.erase_append_perm, Kruskal.mergeAll_congr, Kruskal.merge_swap_partition}

If the edge lists $l_1$ and $l_2$ are permutations of each other, then merging along them
gives the same partition:
$\mathtt{SamePartition}\,(\mathit{uf}.\mathtt{mergeAll}\,l_1)\,(\mathit{uf}.\mathtt{mergeAll}\,l_2)$.
\end{lemma}

n21570.content:
\begin{lemma}[Merging along a list with one appended edge]
\lean{Kruskal.mergeAll_append_single}
\label{Kruskal.mergeAll_append_single}
\leanok
\uses{Kruskal.UF, Kruskal.UF.merge, Kruskal.UF.mergeAll, Kruskal.WEdge}

Merging along $l \mathbin{+\!\!+} [e]$ equals first merging along $l$ and then merging the
endpoints of $e$:
$\mathit{uf}.\mathtt{mergeAll}\,(l \mathbin{+\!\!+} [e]) = (\mathit{uf}.\mathtt{mergeAll}\,l).\mathtt{merge}\,e.u\,e.v$.
\end{lemma}

n21571.content:
\begin{lemma}[Merging along a cons list]
\lean{Kruskal.mergeAll_cons_eq}
\label{Kruskal.mergeAll_cons_eq}
\leanok
\uses{Kruskal.UF, Kruskal.UF.SamePartition, Kruskal.UF.SamePartition.rfl, Kruskal.UF.merge, Kruskal.UF.mergeAll, Kruskal.WEdge}

Merging along $e :: S$ gives the same partition as first merging the endpoints of $e$ and
then merging along $S$:
$\mathtt{SamePartition}\,(\mathit{uf}.\mathtt{mergeAll}\,(e :: S))\,((\mathit{uf}.\mathtt{merge}\,e.u\,e.v).\mathtt{mergeAll}\,S)$.
\end{lemma}

n21572.content:
\begin{lemma}[Moving a member edge to the end is a permutation]
\lean{Kruskal.erase_append_perm}
\label{Kruskal.erase_append_perm}
\leanok
\uses{Kruskal.WEdge}

If $e \in l$ for an edge list $l$, then $l$ is a permutation of
$l.\mathtt{erase}\,e \mathbin{+\!\!+} [e]$.
\end{lemma}

n21574.content:
\begin{definition}[Finite upper image of the payoff]
\lean{OnlineLearning.finiteUpperImage}
\label{OnlineLearning.finiteUpperImage}
\leanok
For sets $X, Y \subseteq \mathbb{R}$, a payoff $f : \mathbb{R}\to \mathbb{R}\to \mathbb{R}$, and a finite
sample $u$ of columns from $Y$, the finite upper image is the set
\[
  U(X,f,u) \;=\; \{\, z : u \to \mathbb{R}\;\mid\; \exists\, x \in X,\ \forall y \in u,\ f(x,y) < z_y \,\}
\]
of vectors that strictly dominate the payoff vector of some row on the sample $u$.
This set is written $\texttt{OnlineLearning.finiteUpperImage}$ in Lean.
\end{definition}

n21575.content:
\begin{lemma}[Upper image is nonempty]
\lean{OnlineLearning.finiteUpperImage_nonempty}
\label{OnlineLearning.finiteUpperImage_nonempty}
\leanok
\uses{OnlineLearning.finiteUpperImage}

If $X$ is nonempty, then for every finite column sample $u$ the upper image
$U(X,f,u)$ is nonempty.
\end{lemma}

n21576.content:
\begin{lemma}[Upper image is convex]
\lean{OnlineLearning.finiteUpperImage_convex}
\label{OnlineLearning.finiteUpperImage_convex}
\leanok
\uses{OnlineLearning.finiteUpperImage}

If $X$ is convex and $x \mapsto f(x,y)$ is convex on $X$ for every $y \in Y$, then
$U(X,f,u)$ is a convex subset of $u \to \mathbb{R}$ for every finite column sample $u$.
\end{lemma}

n21577.content:
\begin{lemma}[Upper image is upward closed]
\lean{OnlineLearning.finiteUpperImage_upper}
\label{OnlineLearning.finiteUpperImage_upper}
\leanok
\uses{OnlineLearning.finiteUpperImage}

