n21585.content:
\begin{theorem}[Convex-compact minimax theorem by separation]
\lean{OnlineLearning.convex_compact_minimax_by_separation}
\label{OnlineLearning.convex_compact_minimax_by_separation}
\leanok
\uses{OnlineLearning.ConvexCompactMinimaxHypotheses, OnlineLearning.ConvexCompactMinimaxStatement, OnlineLearning.convex_compact_minimax_of_finite_sublevel_intersections, OnlineLearning.finite_sublevel_intersections_by_separation}

Under the convex-compact minimax hypotheses
$\texttt{OnlineLearning.ConvexCompactMinimaxHypotheses}$ for $X$, $Y$, $f$, the minimax
identity $\texttt{OnlineLearning.ConvexCompactMinimaxStatement}$ holds:
\[
  \inf_{x \in X} \sup_{y \in Y} f(x,y) \;=\; \sup_{y \in Y} \inf_{x \in X} f(x,y).
\]
This is the final form of the theorem obtained via the finite-column separation route.
\end{theorem}

n21588.content:
\begin{definition}[Vertex connectivity $\kappa(G)$]
\lean{SimpleGraph.vertexConnectivity}
\label{SimpleGraph.vertexConnectivity}
\leanok
\uses{SimpleGraph.IsVertexCut}
The book's case split is on "$G$ has a pair of distinct nonadjacent vertices";
the Lean split is on the equivalent "$G$ has a vertex cut at all", which is the
condition the two branches actually need.  So
\item some cut exists $\Rightarrow$ \texttt{$\kappa$ = sInf \{S.card | G.IsVertexCut S\}};
\item no cut exists (the complete graphs) $\Rightarrow$ $\kappa = \nu - 1$.

\texttt{sInf} on $\mathbb{N}$ is Mathlib's \texttt{Nat.sInf}, with \texttt{sInf $\emptyset$ = 0}; the $if$ guard means
that fallback is never reached here.  Natural subtraction makes $\nu - 1 = 0$
when $V$ is empty, matching "trivial $\Rightarrow$ $\kappa = 0$".
\end{definition}

